// Medidor de mesa: escala vermelha e agulha fixa em 4% da escala.
import React from 'react';
import { Caixa, Escrita, mat, Retangulo, Traco } from './base';

const C = { corpo: '#d83d45', escuro: '#a82737', face: '#fff2df', agulha: '#342e3a' };
const Y = 0.12;
const ANGULO = Math.PI * 0.96;

export const PonteiroChance: React.FC = () => (
  <group>
    <Retangulo w={0.5} h={0.12} d={0.07} raio={0.018} p={[0, 0.06, 0]} cor={C.corpo} />
    <mesh position={[0, Y, 0]} rotation={[-Math.PI / 2, 0, 0]} material={mat(C.corpo)} castShadow receiveShadow>
      <cylinderGeometry args={[0.25, 0.25, 0.07, 40, 1, false, -Math.PI / 2, Math.PI]} />
    </mesh>
    {/* Corpo termina em z=0,035; face começa em 0,057. */}
    <mesh position={[0, Y, 0.06]} rotation={[-Math.PI / 2, 0, 0]} material={mat(C.face, { brilho: 0.12 })} castShadow receiveShadow>
      <cylinderGeometry args={[0.211, 0.211, 0.006, 40, 1, false, -Math.PI / 2, Math.PI]} />
    </mesh>
    {/* Marcas radiais separadas 2 cm da face. Zero à esquerda. */}
    {Array.from({ length: 11 }, (_, i) => {
      const angulo = Math.PI * (1 - i / 10);
      const maior = i % 5 === 0;
      return <Caixa key={i} p={[0.184 * Math.cos(angulo), Y + 0.184 * Math.sin(angulo), 0.085]}
        t={[maior ? 0.024 : 0.015, maior ? 0.008 : 0.006, 0.004]}
        giro={angulo} cor={i < 3 ? C.escuro : C.corpo} sombra={false} />;
    })}
    <Escrita texto="0" altura={0.023} p={[-0.171, 0.169, 0.085]} cor={C.escuro} />
    <Escrita texto="100" altura={0.02} p={[0.163, 0.169, 0.085]} cor={C.escuro} />
    <Escrita texto="CHANCE REAL" altura={0.032} p={[0, 0.054, 0.057]} cor={C.face} />
    {/* Agulha parada: 7,2° acima do zero, sem animação. */}
    <Traco a={[0, Y]} b={[0.165 * Math.cos(ANGULO), Y + 0.165 * Math.sin(ANGULO)]}
      largura={0.012} d={0.006} z={0.11} cor={C.agulha} />
    <mesh position={[0, Y, 0.14]} rotation={[-Math.PI / 2, 0, 0]} material={mat(C.escuro)} castShadow receiveShadow>
      <cylinderGeometry args={[0.023, 0.023, 0.014, 24]} />
    </mesh>
  </group>
);
