// Câmera controlada pelo quadro: posição/alvo interpolados entre chaves (sem física, 100% determinística).
import React, { useLayoutEffect } from 'react';
import { useThree } from '@react-three/fiber';
import * as THREE from 'three';

type V3 = [number, number, number];
export type ChaveCam = { q: number; pos: V3; alvo: V3; fov?: number };
const suave = (t: number) => t * t * (3 - 2 * t);

export function camNoQuadro(chaves: ChaveCam[], quadro: number) {
  if (quadro <= chaves[0].q) return chaves[0];
  for (let i = 1; i < chaves.length; i++) {
    const a = chaves[i - 1], b = chaves[i];
    if (quadro <= b.q) {
      const t = suave((quadro - a.q) / (b.q - a.q));
      const mix = (x: V3, y: V3) => x.map((v, k) => v + (y[k] - v) * t) as V3;
      return { q: quadro, pos: mix(a.pos, b.pos), alvo: mix(a.alvo, b.alvo), fov: (a.fov ?? 40) + ((b.fov ?? 40) - (a.fov ?? 40)) * t };
    }
  }
  return chaves[chaves.length - 1];
}

export const Camera: React.FC<{ chaves: ChaveCam[]; quadro: number }> = ({ chaves, quadro }) => {
  const cam = useThree((s) => s.camera) as THREE.PerspectiveCamera;
  const c = camNoQuadro(chaves, quadro);
  useLayoutEffect(() => {
    cam.position.set(...c.pos); cam.fov = c.fov ?? 40; cam.near = 0.3; cam.far = 200;
    cam.lookAt(...c.alvo); cam.updateProjectionMatrix();
  });
  return null;
};
