// Ações de corpo do lote r06 (vídeo "E se a sua sorte DOBRASSE todo dia?"): quicarBola, sortear, abrirPacote.
// Só juntas do boneco padrão (graus; altura em metros), animação só em função do quadro (30 fps), sem acaso.
// Cada mão é escrita como "onde fica", em metros, no espaço do boneco (chão em y = 0, olhando +Z);
// a IK analítica do r05 (`ikBraco`) converte em juntas. +X = direita de quem olha = braço D.
import { BASE, type Juntas } from '../../../kit/poses';
import { ikBraco, paraTronco, ciclo } from '../r05-acao/acoes';

export type V3 = [number, number, number];
export { ciclo };
export const suave = (t: number) => { const k = Math.min(1, Math.max(0, t)); return k * k * (3 - 2 * k); };
const GRAU = Math.PI / 180;

type Corpo = Pick<Juntas, 'altura' | 'troncoX' | 'troncoY'>;
/** Braço que leva a mão ao ponto `p` (espaço do boneco), já descontando a inclinação do tronco. */
const braco = (lado: 1 | -1, c: Corpo, p: V3): Partial<Juntas> => {
  const b = ikBraco(lado, paraTronco(c, p));
  return lado === 1 ? { ombroDX: b.x, ombroDZ: b.z, cotoveloD: b.cot } : { ombroEX: b.x, ombroEZ: b.z, cotoveloE: b.cot };
};
/** Quanto o corpo desce com as pernas dobradas (quadril q, joelho j), para os pés ficarem no chão. */
const descida = (q: number, j: number) => -(0.55 - 0.25 * Math.cos(q * GRAU) - 0.3 * Math.cos((q - j) * GRAU));

// ── quicarBola ───────────────────────────────────────────────────────────
// Meio agachado (joelhos dobrados, tronco 13° à frente), braço D estendido para baixo e para fora,
// com a mão sobre a bola, ao lado da perna. A cabeça olha a bola. Braço E aberto, de equilíbrio.
// Ciclo de 20 q (1,5 quique por segundo): a bola sai da mão no alto, bate no chão na metade e volta.
// A mão sobe e desce (cos) sempre por cima da bola, sem atravessá-la. No quadro 90 a bola está perto do chão.
export const BOLA_R = 0.12; // bola de basquete: 24 cm
export const BOLA_XZ: [number, number] = [0.4, 0.3];
const QUIQUE = 20, FASE = 4;
const MAO_ALTA = 0.82, MAO_BAIXA = 0.66;
const PERNAS_QUICAR = { quadrilE: 20, joelhoE: 34, quadrilD: 20, joelhoD: 34 };
const CORPO_QUICAR: Corpo = { altura: descida(20, 34), troncoX: 13, troncoY: -10 };
/** 0..1 dentro do quique (0 = bola na mão, 0,5 = bola no chão). */
export const tempoQuique = (q: number) => ciclo(q - FASE, QUIQUE) / QUIQUE;
/** Altura do centro da bola: |cos| dá a batida seca no chão. */
export const alturaBola = (q: number) => BOLA_R + (MAO_ALTA - 0.072 - 2 * BOLA_R) * Math.abs(Math.cos(Math.PI * tempoQuique(q)));
/** Altura do centro da mão: encosta na bola no alto e "empurra" até MAO_BAIXA. */
export const alturaMaoQuique = (q: number) => MAO_BAIXA + (MAO_ALTA - MAO_BAIXA) * Math.cos(Math.PI * tempoQuique(q)) ** 2;
const maoQuique = (q: number): V3 => [BOLA_XZ[0], alturaMaoQuique(q), BOLA_XZ[1]];
const MAO_EQUILIBRIO: V3 = [-0.42, 0.84, 0.18];
export const QUICAR: Partial<Juntas> = {
  ...PERNAS_QUICAR, ...CORPO_QUICAR, cabecaX: 6, cabecaY: 20, cabecaZ: -4,
  ...braco(1, CORPO_QUICAR, maoQuique(FASE + 8)), ...braco(-1, CORPO_QUICAR, MAO_EQUILIBRIO),
};
export function quicarBola(q: number): Partial<Juntas> {
  const empurra = Math.sin(Math.PI * tempoQuique(q)); // 1 com a bola no chão
  const c: Corpo = { ...CORPO_QUICAR, altura: CORPO_QUICAR.altura - 0.012 * empurra, troncoX: CORPO_QUICAR.troncoX + 2 * empurra };
  return { ...c, ...braco(1, c, maoQuique(q)), ...braco(-1, c, MAO_EQUILIBRIO), cabecaX: 4 + 5 * empurra };
}

// ── sortear ──────────────────────────────────────────────────────────────
// Mão E dentro da urna (caixa na altura da cintura, à frente e um pouco à esquerda de quem olha),
// remexendo em círculos curtos. Mão D erguida ao lado da cabeça, braço quase estendido (não é "muque"),
// segurando o papel virado para a câmera; ela balança de leve, mostrando. A cabeça olha o papel.
export const URNA = { centro: [-0.13, 0, 0.44] as V3, mesa: 0.62, lado: 0.32 }; // mesa de 62 cm + urna de 32 cm
const NA_URNA: V3 = [-0.13, 0.92, 0.42];
const PAPEL_MAO: V3 = [0.45, 1.42, 0.2];
const CORPO_SORTEAR: Corpo = { altura: 0, troncoX: 7, troncoY: -6 };
export const maoNaUrna = (q: number): V3 => {
  const a = (2 * Math.PI * q) / 24;
  return [NA_URNA[0] + 0.03 * Math.sin(a), NA_URNA[1] + 0.012 * Math.sin(2 * a), NA_URNA[2] + 0.025 * Math.cos(a)];
};
export const maoPapel = (q: number): V3 => {
  const a = (2 * Math.PI * q) / 16;
  return [PAPEL_MAO[0] + 0.012 * Math.sin(a), PAPEL_MAO[1] + 0.025 * Math.sin(a + 0.6), PAPEL_MAO[2]];
};
export const SORTEAR: Partial<Juntas> = {
  ...CORPO_SORTEAR, quadrilE: 4, joelhoE: 8, cabecaX: -6, cabecaY: 22, cabecaZ: -8,
  ...braco(-1, CORPO_SORTEAR, NA_URNA), ...braco(1, CORPO_SORTEAR, PAPEL_MAO),
};
export function sortear(q: number): Partial<Juntas> {
  const p = maoPapel(q);
  return { ...braco(-1, CORPO_SORTEAR, maoNaUrna(q)), ...braco(1, CORPO_SORTEAR, p), cabecaY: 22 + 30 * (p[0] - PAPEL_MAO[0]) };
}

// ── abrirPacote ──────────────────────────────────────────────────────────
// As duas mãos à frente do peito seguram as pontas de cima do pacote; o rasgo abre do meio da borda de cima
// para baixo: cada metade gira em torno do fundo (pivô embaixo, no meio) e a mão de cada lado vai junto,
// uma para cada lado (a D também vem para a frente, a E vai para trás). Cabeça baixa olhando o pacote.
// Ciclo de 48 q: segura (0–6), puxa (6–36), segura aberto (36–48). No quadro 90 o rasgo está quase todo aberto.
export const PACOTE = { pivo: [0, 0.76, 0.3] as V3, larg: 0.24, alt: 0.3, prof: 0.05, giro: 11 };
const PUXA = 48;
/** 0..1: quanto o pacote já rasgou no quadro. */
export const rasgo = (q: number) => suave((ciclo(q - 60, PUXA) - 6) / 30);
/** Ponta de cima do pacote do lado `lado` (onde a mão segura), no espaço do boneco. */
export function pontaPacote(lado: 1 | -1, r: number): V3 {
  const a = -lado * PACOTE.giro * GRAU * r; // a metade D gira para +X (ângulo negativo em Z)
  const lx = lado * (PACOTE.larg / 2 - 0.02), ly = PACOTE.alt - 0.035;
  const [px, py, pz] = PACOTE.pivo;
  return [px + lx * Math.cos(a) - ly * Math.sin(a), py + lx * Math.sin(a) + ly * Math.cos(a), pz + 0.02 * lado * r];
}
const maoPacote = (lado: 1 | -1, r: number): V3 => {
  const p = pontaPacote(lado, r);
  return [p[0] + 0.015 * lado, p[1], p[2] + PACOTE.prof / 2 + 0.035];
};
const CORPO_PACOTE: Corpo = { altura: 0, troncoX: 5, troncoY: 0 };
export const ABRIR_PACOTE: Partial<Juntas> = {
  ...CORPO_PACOTE, quadrilD: 4, joelhoD: 8, cabecaX: 18, cabecaY: 0, cabecaZ: 4,
  ...braco(-1, CORPO_PACOTE, maoPacote(-1, 0.9)), ...braco(1, CORPO_PACOTE, maoPacote(1, 0.9)),
};
export function abrirPacote(q: number): Partial<Juntas> {
  const r = rasgo(q);
  const forca = Math.sin(Math.PI * Math.min(1, Math.max(0, (ciclo(q - 60, PUXA) - 6) / 30))); // esforço no meio do puxão
  return {
    ...braco(-1, CORPO_PACOTE, maoPacote(-1, r)), ...braco(1, CORPO_PACOTE, maoPacote(1, r)),
    troncoX: CORPO_PACOTE.troncoX - 3 * forca, cabecaZ: 4 - 6 * forca,
  };
}

// ── juntas completas ─────────────────────────────────────────────────────
export const ACOES: Record<string, { pose: Partial<Juntas>; animar: (q: number) => Partial<Juntas> }> = {
  quicarBola: { pose: QUICAR, animar: quicarBola },
  sortear: { pose: SORTEAR, animar: sortear },
  abrirPacote: { pose: ABRIR_PACOTE, animar: abrirPacote },
};
export const juntasNoQuadro = (nome: string, q: number): Juntas => {
  const a = ACOES[nome];
  return { ...BASE, ...(a?.pose ?? {}), ...(a ? a.animar(q) : {}) };
};
