// Cinemática direta do boneco padrão (mesmas medidas e ordem de giros do kit/Boneco.tsx).
// Serve para pôr pacote, escova e alça da mochila exatamente na mão, em qualquer quadro.
import * as THREE from 'three';
import type { Juntas } from '../../../kit/poses';

const R = THREE.MathUtils.degToRad;
const m4 = (x: number, y: number, z: number, rx = 0, ry = 0, rz = 0) =>
  new THREE.Matrix4().compose(new THREE.Vector3(x, y, z), new THREE.Quaternion().setFromEuler(new THREE.Euler(rx, ry, rz)), new THREE.Vector3(1, 1, 1));

/** Matriz do tronco (espaço do boneco, já com a `altura`). */
const tronco = (j: Juntas) => m4(0, j.altura, 0).multiply(m4(0, 0.66, 0, R(j.troncoX), R(j.troncoY), 0)).multiply(m4(0, -0.66, 0));

/** Matriz da mão (centro da esfera). lado 1 = braço D (+X), -1 = braço E. */
export function matrizMao(j: Juntas, lado: 1 | -1): THREE.Matrix4 {
  const [x, z, cot] = lado === 1 ? [j.ombroDX, j.ombroDZ, j.cotoveloD] : [j.ombroEX, j.ombroEZ, j.cotoveloE];
  return tronco(j)
    .multiply(m4(0.25 * lado, 1.06, 0, R(-x), 0, R(z) * lado))
    .multiply(m4(0, -0.22, 0, R(-cot), 0, 0))
    .multiply(m4(0, -0.25, 0));
}
/** Matriz do centro da cabeça (frente = +Z local). */
export function matrizCabeca(j: Juntas): THREE.Matrix4 {
  return tronco(j).multiply(m4(0, 1.18, 0, R(j.cabecaX), R(j.cabecaY), R(j.cabecaZ))).multiply(m4(0, 0.32, 0));
}
/** Matriz do pé (centro do tênis). lado 1 = perna D. */
export function matrizPe(j: Juntas, lado: 1 | -1): THREE.Matrix4 {
  const [q, jo] = lado === 1 ? [j.quadrilD, j.joelhoD] : [j.quadrilE, j.joelhoE];
  return m4(0, j.altura, 0).multiply(m4(0.1 * lado, 0.64, 0, R(-q))).multiply(m4(0, -0.25, 0, R(jo))).multiply(m4(0, -0.3, 0.05));
}
export const posicao = (m: THREE.Matrix4) => new THREE.Vector3().setFromMatrixPosition(m);
/** Ponto de um tronco em coordenadas do boneco (ex.: costas, para a mochila). */
export const pontoTronco = (j: Juntas, p: [number, number, number]) => new THREE.Vector3(...p).applyMatrix4(tronco(j));
export const matrizTronco = tronco;
