import React from 'react';
import * as THREE from 'three';

export type V3 = [number, number, number];
export type Mancha = { x: number; y: number; largura: number; altura: number; cor: string };

const cache = new Map<string, THREE.MeshStandardMaterial>();
export const mat = (cor: string, brilho = 0, metal = 0) => {
  const chave = `${cor}|${brilho}|${metal}`;
  let material = cache.get(chave);
  if (!material) {
    material = new THREE.MeshStandardMaterial({
      color: cor, roughness: 0.85, metalness: metal,
      emissive: cor, emissiveIntensity: brilho,
    });
    cache.set(chave, material);
  }
  return material;
};

export const Caixa: React.FC<{
  p: V3; t: V3; cor: string; r?: V3; sombra?: boolean; brilho?: number; metal?: number;
}> = ({ p, t, cor, r, sombra = true, brilho = 0, metal = 0 }) => (
  <mesh position={p} rotation={r} material={mat(cor, brilho, metal)} castShadow={sombra} receiveShadow>
    <boxGeometry args={t} />
  </mesh>
);

// Números de sete segmentos, desenhados com caixas. Coordenadas no plano XY.
export const numero = (
  texto: string, x: number, y: number, largura: number, altura: number,
  traco: number, cor: string, intervalo = largura * 0.22,
): Mancha[] => {
  const segmentos: Record<string, string> = {
    '0': 'abcdef', '1': 'bc', '2': 'abged', '3': 'abgcd',
    '4': 'fgbc', '5': 'afgcd', '6': 'afgecd', '7': 'abc', '8': 'abcdefg', '9': 'abfgcd',
  };
  const lateral = (largura - traco) / 2;
  const vertical = altura / 4;
  const pecas: Record<string, [number, number, number, number]> = {
    a: [0, (altura - traco) / 2, largura, traco],
    b: [lateral, vertical, traco, altura / 2],
    c: [lateral, -vertical, traco, altura / 2],
    d: [0, -(altura - traco) / 2, largura, traco],
    e: [-lateral, -vertical, traco, altura / 2],
    f: [-lateral, vertical, traco, altura / 2],
    g: [0, 0, largura, traco],
  };
  let cursor = x;
  return [...texto].flatMap((letra) => {
    const centro = cursor + largura / 2;
    cursor += largura + intervalo;
    if (letra === '+' || letra === '=') {
      const barras: Mancha[] = [
        { x: centro, y: y + (letra === '=' ? altura * 0.16 : 0), largura, altura: traco, cor },
      ];
      barras.push(letra === '+'
        ? { x: centro, y, largura: traco, altura: altura * 0.65, cor }
        : { x: centro, y: y - altura * 0.16, largura, altura: traco, cor });
      return barras;
    }
    return [...(segmentos[letra] ?? '')].map((segmento) => {
      const [dx, dy, w, h] = pecas[segmento];
      return { x: centro + dx, y: y + dy, largura: w, altura: h, cor };
    });
  });
};

// Mosaico sólido de caixas adjacentes, com as cores encaixadas no mesmo plano.
export const Mosaico: React.FC<{
  largura: number; altura: number; espessura: number; cor: string; manchas: Mancha[];
  brilho?: number; sombra?: boolean;
}> = ({ largura, altura, espessura, cor, manchas, brilho = 0, sombra = true }) => {
  const medida = (valor: number) => Math.round(valor * 1_000_000) / 1_000_000;
  const marcas = manchas.map((m) => ({
    x0: medida(Math.max(-largura / 2, m.x - m.largura / 2)),
    x1: medida(Math.min(largura / 2, m.x + m.largura / 2)),
    y0: medida(Math.max(-altura / 2, m.y - m.altura / 2)),
    y1: medida(Math.min(altura / 2, m.y + m.altura / 2)), cor: m.cor,
  })).filter((m) => m.x1 > m.x0 && m.y1 > m.y0);
  const niveis = [...new Set([-altura / 2, altura / 2, ...marcas.flatMap((m) => [m.y0, m.y1])])].sort((a, b) => a - b);
  const blocos: typeof marcas = [];
  let anteriores = new Map<string, number>();
  for (let linha = 0; linha < niveis.length - 1; linha++) {
    const y0 = niveis[linha], y1 = niveis[linha + 1], meio = (y0 + y1) / 2;
    const ativas = marcas.filter((m) => meio > m.y0 && meio < m.y1).reverse();
    const cortes = [...new Set([-largura / 2, largura / 2, ...ativas.flatMap((m) => [m.x0, m.x1])])].sort((a, b) => a - b);
    const faixas: typeof marcas = [];
    for (let coluna = 0; coluna < cortes.length - 1; coluna++) {
      const x0 = cortes[coluna], x1 = cortes[coluna + 1];
      const centro = (x0 + x1) / 2;
      const tinta = ativas.find((m) => centro > m.x0 && centro < m.x1)?.cor ?? cor;
      const ultima = faixas[faixas.length - 1];
      if (ultima?.cor === tinta) ultima.x1 = x1;
      else faixas.push({ x0, x1, y0, y1, cor: tinta });
    }
    const atuais = new Map<string, number>();
    for (const faixa of faixas) {
      const chave = `${faixa.x0}|${faixa.x1}|${faixa.cor}`;
      const anterior = anteriores.get(chave);
      if (anterior === undefined) {
        atuais.set(chave, blocos.length);
        blocos.push(faixa);
      } else {
        blocos[anterior].y1 = y1;
        atuais.set(chave, anterior);
      }
    }
    anteriores = atuais;
  }
  return (
    <group>
      {/* Verso uniforme e superfície encaixada em contato direto. */}
      <Caixa p={[0, 0, -espessura * 0.1]} t={[largura, altura, espessura * 0.8]} cor={cor} sombra={sombra} />
      {blocos.map((b, i) => (
        <Caixa key={i} p={[(b.x0 + b.x1) / 2, (b.y0 + b.y1) / 2, espessura * 0.4]}
          t={[b.x1 - b.x0, b.y1 - b.y0, espessura * 0.2]} cor={b.cor} brilho={brilho} sombra={sombra} />
      ))}
    </group>
  );
};
