// Trinta faces para +Y: seis colunas de cinco moedas, sem faces escondidas.
import React from 'react';
import { mat } from './base';

const RAIO = 0.09;
const PASSO = 0.205;
const borda = mat('#cb921d', { brilho: 0.12 });
const face = mat('#ffc535', { brilho: 0.2 });
const relevo = mat('#ffe28a', { brilho: 0.2 });
const materiais = [borda, face, borda];

const Moeda: React.FC = () => (
  <group>
    <mesh position={[0, 0.012, 0]} material={materiais} castShadow receiveShadow>
      <cylinderGeometry args={[RAIO, RAIO, 0.024, 32]} />
    </mesh>
    <mesh position={[0, 0.029, 0]} rotation={[-Math.PI / 2, 0, 0]} material={relevo}>
      <torusGeometry args={[0.077, 0.005, 8, 32]} />
    </mesh>
    {/* Cabeça e busto em relevo, sem serrilhas ou textura. */}
    <mesh position={[0, 0.03, -0.024]} scale={[1, 0.25, 1]} material={relevo}>
      <sphereGeometry args={[0.024, 16, 8]} />
    </mesh>
    <mesh position={[0, 0.03, 0.027]} scale={[1, 0.16, 0.55]} material={relevo}>
      <sphereGeometry args={[0.04, 16, 8]} />
    </mesh>
  </group>
);

export const PilhaMoedas: React.FC = () => (
  <group>
    {Array.from({ length: 6 }, (_, coluna) => (
      <group key={coluna} position={[(coluna - 2.5) * PASSO, 0, 0]}>
        {Array.from({ length: 5 }, (_, linha) => (
          <group key={linha} position={[0, 0, (linha - 2) * PASSO]}><Moeda /></group>
        ))}
      </group>
    ))}
  </group>
);
