// Uma película vertical de 2 x 3 m. Travessia em -Z → +Z pelo quadro.
import React from 'react';
import { useCurrentFrame } from 'remotion';
import { mat, type V3 } from './base';

const FRISOS: { p: V3; t: V3 }[] = [
  { p: [-0.96, 1.5, 0.04], t: [0.08, 3, 0.08] },
  { p: [0.96, 1.5, 0.04], t: [0.08, 3, 0.08] },
  { p: [0, 0.04, 0.04], t: [1.84, 0.08, 0.08] },
  { p: [0, 2.96, 0.04], t: [1.84, 0.08, 0.08] },
];
const CICLO = 120;

export const BarreiraNoQuadro: React.FC<{ quadro: number }> = ({ quadro }) => (
  <group>
    <mesh position={[0, 1.5, 0]} material={mat('#00a9d4', { opacidade: 0.32, brilho: 0.35, duplo: true })} renderOrder={2}>
      <planeGeometry args={[2, 3]} />
    </mesh>
    {FRISOS.map(({ p, t }, i) => (
      <mesh key={i} position={p} material={mat('#a2faff', { brilho: 0.65 })}>
        <boxGeometry args={t} />
      </mesh>
    ))}
    {/* Reflexo largo, separado da película por 3 cm. */}
    <mesh position={[-0.5, 1.5, 0.03]} rotation={[0, 0, -0.12]}
      material={mat('#d6ffff', { opacidade: 0.2, brilho: 0.5, duplo: true })} renderOrder={3}>
      <planeGeometry args={[0.16, 2.64]} />
    </mesh>
    {Array.from({ length: 6 }, (_, i) => {
      const faixa = i % 3;
      const fase = ((quadro / CICLO + 0.03 + faixa * 0.14 + Math.floor(i / 3) * 0.5) % 1 + 1) % 1;
      const escala = Math.min(1, fase / 0.08, (1 - fase) / 0.08);
      const x = (fase - 0.5) * 1.5;
      const y = 0.65 + faixa * 0.85;
      const z = (fase - 0.5) * 2.4;
      const contato = Math.max(0, 1 - Math.abs(z) / 0.4);
      return (
        <group key={i}>
          {/* Sem sombra no piso: são partículas luminosas. */}
          <mesh position={[x, y, z]} scale={escala} material={mat('#ffce00', { brilho: 0.7 })}>
            <sphereGeometry args={[0.15, 24, 16]} />
          </mesh>
          <mesh position={[x, y, 0.08]} scale={contato}
            material={mat('#d6ffff', { brilho: 0.65, opacidade: 0.5 })} renderOrder={4}>
            <torusGeometry args={[0.21, 0.04, 8, 24]} />
          </mesh>
        </group>
      );
    })}
  </group>
);

export const BarreiraBrilhante: React.FC = () => <BarreiraNoQuadro quadro={useCurrentFrame()} />;
