// Base do lote r13-objeto: cache de material por cor (com variantes de brilho e vidro) e o pão francês reutilizável.
import * as THREE from 'three';
import React from 'react';

const cache = new Map<string, THREE.MeshStandardMaterial>();
/** Material chapado (roughness 0.85). `brilho` > 0 acende a cor; `opac` < 1 deixa translúcido (vidro, halo). */
export const mat = (cor: string, o: { brilho?: number; opac?: number; rug?: number } = {}) => {
  const { brilho = 0, opac = 1, rug = 0.85 } = o;
  const k = [cor, brilho, opac, rug].join('|');
  let m = cache.get(k);
  if (!m) {
    m = new THREE.MeshStandardMaterial({ color: cor, roughness: rug });
    if (brilho > 0) { m.emissive = new THREE.Color(cor); m.emissiveIntensity = brilho; }
    if (opac < 1) { m.transparent = true; m.opacity = opac; m.depthWrite = false; }
    cache.set(k, m);
  }
  return m;
};

type V3 = [number, number, number];
export const Caixa: React.FC<{ p: V3; t: V3; m: THREE.Material; sombra?: boolean }> = ({ p, t, m, sombra = true }) => (
  <mesh position={p} material={m} castShadow={sombra} receiveShadow><boxGeometry args={t} /></mesh>
);

/** Placa de cantos arredondados deitada (plano XZ), espessura h em Y: 2 caixas em cruz + 4 cilindros. */
export const Placa: React.FC<{ w: number; d: number; h: number; r: number; p: V3; m: THREE.Material; sombra?: boolean }> = ({ w, d, h, r, p, m, sombra = true }) => (
  <group position={p}>
    <mesh material={m} castShadow={sombra} receiveShadow><boxGeometry args={[w - 2 * r, h, d]} /></mesh>
    <mesh material={m} castShadow={sombra} receiveShadow><boxGeometry args={[w, h, d - 2 * r]} /></mesh>
    {([[-1, -1], [1, -1], [-1, 1], [1, 1]] as const).map(([sx, sz]) => (
      <mesh key={`${sx}${sz}`} position={[sx * (w / 2 - r), 0, sz * (d / 2 - r)]} material={m} castShadow={sombra} receiveShadow>
        <cylinderGeometry args={[r, r, h, 16]} />
      </mesh>
    ))}
  </group>
);

export const COR_PAO = { casca: '#dc8f2e', ponta: '#c9761f', pestana: '#f0b24e', corte: '#5e300c' };

const Elipsoide: React.FC<{ p: [number, number, number]; s: [number, number, number]; cor: string; giro?: number }> = ({ p, s, cor, giro = 0 }) => (
  <mesh position={p} rotation={[0, 0, giro]} scale={s} material={mat(cor)} castShadow receiveShadow><sphereGeometry args={[1, 32, 16]} /></mesh>
);

/** Pão francês de 20 cm (comprimento em X), origem no centro da base: corpo fino, pontas afuniladas e um corte fundo. */
export const PaoFrances: React.FC<{ escala?: number }> = ({ escala = 1 }) => (
  <group scale={escala}>
    {/* corpo (a base entra um pouco no apoio = fundo achatado) */}
    <Elipsoide p={[0, 0.025, 0]} s={[0.07, 0.036, 0.037]} cor={COR_PAO.casca} />
    {/* pontas: cone truncado (cilindro de raios diferentes) saindo do corpo, mais uma bolinha na ponta = afunila liso */}
    {[-1, 1].map((s) => (
      <group key={s} position={[s * 0.035, 0.025, 0]} rotation={[0, 0, s * (Math.PI / 2 - 0.06)]}>
        <mesh position={[0, -0.03, 0]} material={mat(COR_PAO.casca)} castShadow receiveShadow><cylinderGeometry args={[0.031, 0.011, 0.06, 28]} /></mesh>
        <mesh position={[0, -0.06, 0]} material={mat(COR_PAO.ponta)} castShadow receiveShadow><sphereGeometry args={[0.0115, 16, 10]} /></mesh>
      </group>
    ))}
    {/* corte ao longo do comprimento, levemente em diagonal: sulco escuro e uma pestana clara levantada de um lado só */}
    <group position={[0, 0.0565, 0]} rotation={[0, 0.1, 0]}>
      <Elipsoide p={[0, 0, 0.001]} s={[0.052, 0.006, 0.0085]} cor={COR_PAO.corte} />
      <mesh position={[0, 0.002, -0.009]} rotation={[0.5, 0, 0]} scale={[0.05, 0.007, 0.0055]} material={mat(COR_PAO.pestana)} castShadow receiveShadow>
        <sphereGeometry args={[1, 24, 10]} />
      </mesh>
    </group>
  </group>
);
