// Efeito: fileira de prédios de Nova York no fundo, numa só profundidade e com o meio livre para o personagem.
// Torres cinza e azuis com janelas amarelas acesas e caixas-d'água, mais uma torre em degraus estilo Empire State.
// Com o tempo elas encolhem e afundam no chão, todas juntas e devagar, até sumirem.
// Anti-cintilação: nenhuma face coplanar (janelas e degraus se cruzam com a caixa de trás), sem tremor e janelas ≥ 30 cm.
import React from 'react';
import { Caixa, mat, suave } from './base';

const C = {
  cinza: ['#9aa1aa', '#7f8792'], azul: ['#6b9ad0', '#5786bf'],
  topo: '#4c525b', calcada: '#7a7f86', janela: '#ffd54a',
  empire: '#d2cbb8', empireDegrau: '#bab29c', antena: '#e4e0d4', caixaDagua: '#8a5a3c', tampa: '#6e4630',
};

type Predio = { x0: number; x1: number; h: number; cor: string; extra?: 'caixaDagua' | 'antena' };
// fileira contínua dos dois lados; o vão |x| < 1,8 fica livre (atrás do personagem)
const FILEIRA: Predio[] = [
  { x0: -6.9, x1: -5.3, h: 3.4, cor: C.azul[0], extra: 'caixaDagua' },
  { x0: -5.3, x1: -3.75, h: 5.6, cor: C.cinza[1] },
  // Empire State de -3,75 a -1,8
  { x0: 1.8, x1: 3.3, h: 3.8, cor: C.cinza[0], extra: 'caixaDagua' },
  { x0: 3.3, x1: 4.9, h: 5.8, cor: C.azul[1], extra: 'antena' },
  { x0: 4.9, x1: 6.9, h: 3.5, cor: C.cinza[1], extra: 'caixaDagua' },
];
const PROF = 1.4;
const EMPIRE = { x: -2.78, h: 3.75 };

/** Grade de janelas na frente de uma caixa (largura w), da altura y0 até y1. Metade da janela entra na parede. */
const Janelas: React.FC<{ w: number; y0: number; y1: number; z: number }> = ({ w, y0, y1, z }) => {
  const nc = Math.max(2, Math.floor(w / 0.55));
  const passo = w / nc, linhas = Math.floor((y1 - y0) / 0.75);
  return (
    <>
      {Array.from({ length: linhas * nc }, (_, i) => {
        const l = Math.floor(i / nc), c = i % nc;
        return <Caixa key={i} p={[-w / 2 + passo * (c + 0.5), y0 + l * 0.75 + 0.25, z]} t={[Math.max(0.3, passo * 0.5), 0.42, 0.1]} cor={C.janela} brilho={0.6} sombra={false} />;
      })}
    </>
  );
};

const CaixaDagua: React.FC<{ x: number; y: number }> = ({ x, y }) => (
  <group position={[x, y, 0]}>
    {[-0.2, 0.2].map((px) => <Caixa key={px} p={[px, 0.22, 0]} t={[0.1, 0.5, 0.1]} cor={C.topo} />)}
    <mesh position={[0, 0.75, 0]} material={mat(C.caixaDagua)} castShadow receiveShadow><cylinderGeometry args={[0.34, 0.34, 0.62, 14]} /></mesh>
    <mesh position={[0, 1.17, 0]} material={mat(C.tampa)} castShadow><cylinderGeometry args={[0, 0.38, 0.26, 14]} /></mesh>
  </group>
);

const Torre: React.FC<{ p: Predio }> = ({ p }) => {
  const w = p.x1 - p.x0;
  return (
    <group>
      <Caixa p={[0, p.h / 2, 0]} t={[w, p.h, PROF]} cor={p.cor} />
      {/* beiral do topo (encaixado 4 cm na caixa) */}
      <Caixa p={[0, p.h + 0.05, 0]} t={[w + 0.14, 0.18, PROF + 0.14]} cor={C.topo} />
      <Janelas w={w - 0.2} y0={0.45} y1={p.h - 0.3} z={PROF / 2} />
      {p.extra === 'caixaDagua' && <CaixaDagua x={w * 0.2} y={p.h + 0.1} />}
      {p.extra === 'antena' && (
        <mesh position={[0, p.h + 0.6, 0]} material={mat(C.antena)} castShadow><cylinderGeometry args={[0.06, 0.06, 1.0, 8]} /></mesh>
      )}
    </group>
  );
};

/** Torre em degraus: base larga, três recuos, coroa e agulha. Faixas verticais acesas em cada degrau. */
const Empire: React.FC = () => {
  // largura, base, altura (cada degrau entra 5 cm no de baixo)
  const niveis: [number, number, number][] = [[1.9, 0, 1.55], [1.45, 1.5, 0.7], [1.05, 2.15, 0.5], [0.7, 2.6, 0.38]];
  return (
    <group>
      {niveis.map(([w, y, h], i) => {
        const nf = Math.max(2, Math.floor(w / 0.34));
        return (
          <group key={i}>
            <Caixa p={[0, y + h / 2, 0]} t={[w, h, w * 0.75]} cor={i % 2 ? C.empireDegrau : C.empire} />
            {/* faixas acesas: 12 cm de largura, metade entra na parede */}
            {i < 3 && Array.from({ length: nf }, (_, k) => (
              <Caixa key={k} p={[(k - (nf - 1) / 2) * (w / nf), y + h / 2 + 0.03, w * 0.375]} t={[0.12, h - 0.3, 0.1]} cor={C.janela} brilho={0.6} sombra={false} />
            ))}
          </group>
        );
      })}
      {/* coroa e agulha */}
      <mesh position={[0, 3.08, 0]} material={mat(C.empire)} castShadow receiveShadow><cylinderGeometry args={[0.2, 0.28, 0.2, 10]} /></mesh>
      <mesh position={[0, 3.25, 0]} material={mat(C.empireDegrau)} castShadow receiveShadow><cylinderGeometry args={[0.12, 0.17, 0.18, 10]} /></mesh>
      <mesh position={[0, 3.52, 0]} material={mat(C.antena)} castShadow><cylinderGeometry args={[0.045, 0.08, 0.48, 8]} /></mesh>
    </group>
  );
};

/** `inicio`/`duracao` em quadros: quando começa a afundar e quanto leva; `z`: linha dos prédios. */
export const PredioNovaYork: React.FC<{ quadro: number; inicio?: number; duracao?: number; z?: number }> = ({ quadro, inicio = 50, duracao = 100, z = -6.8 }) => {
  const itens = [
    ...FILEIRA.map((p) => ({ x: (p.x0 + p.x1) / 2, h: p.h, atraso: 8 - Math.abs((p.x0 + p.x1) / 2), el: <Torre p={p} /> })),
    { x: EMPIRE.x, h: EMPIRE.h, atraso: 12, el: <Empire /> }, // o Empire afunda por último
  ];
  const prog = (atraso: number) => suave((quadro - inicio - atraso) / (duracao - 12));
  // calçada (uma por lado): fica no chão enquanto os prédios afundam por ela e baixa no fim
  const calc = 1 - suave((prog(12) - 0.85) / 0.15);
  return (
    <group position={[0, 0, z]}>
      {calc > 0.01 && [-1, 1].map((lado) => (
        <mesh key={lado} position={[lado * 4.35, 0.06 * calc - 0.03, 0]} scale={[1, calc, 1]} material={mat(C.calcada)} receiveShadow>
          <boxGeometry args={[5.4, 0.18, PROF + 0.5]} />
        </mesh>
      ))}
      {itens.map((it, i) => {
        const t = prog(it.atraso);
        const enc = 1 - 0.25 * t; // encolhe até 75% enquanto afunda
        if (t > 0.999) return null;
        return <group key={i} position={[it.x, -t * it.h * enc, 0]} scale={enc}>{it.el}</group>;
      })}
    </group>
  );
};
