// Pão francês quente (20 cm) sozinho numa bandeja de metal, com fumacinha subindo em bolas encadeadas.
// Origem no centro da base da bandeja; o pão fica no comprido (X), de frente para +Z.
// O pão é UMA malha: uma cápsula do Three.js com os vértices afinados nas pontas (sem emendas entre peças).
import React from 'react';
import * as THREE from 'three';
import { mergeVertices } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import { useCurrentFrame } from 'remotion';
import { mat, Caixa } from './base';

const COR = {
  casca: '#d98a2b', labio: '#eba847', corte: '#4f2507',
  fundo: '#9da7b2', parede: '#5f6b78', aro: '#c9d2dc', sombra: '#2a2016', fumaca: '#ffffff',
};

// --- forma do pão: 20 cm de comprimento, 7,2 cm de largura, ~5,2 cm de altura ---
const MEIO = 0.1, R = 0.036; // meio comprimento e raio do corpo
const BASE = 0.004; // pão apoiado no fundo da bandeja
/** perfil ao longo do comprimento (t de -1 a 1): corpo quase constante, pontas afuniladas e arredondadas */
const perfil = (t: number) => Math.pow(Math.max(0, 1 - Math.abs(t) ** 2.6), 0.55);
/** barriga levemente curva: as pontas descem 4 mm */
const curva = (x: number) => -0.004 * (x / MEIO) ** 2;
const CENTRO = BASE + 0.018; // eixo do pão; em cima 0,95 R, embaixo 0,5 R (fundo achatado)
/** altura do topo do pão em x (o corte e a fumaça seguem esta linha) */
const topo = (x: number) => CENTRO + curva(x) + 0.95 * R * perfil(x / MEIO);

/** Malha de primitiva deitada em X: cada vértice (x ao longo, v vertical, p profundidade) passa por `mover`;
 *  depois as emendas são soldadas e as normais refeitas (superfície lisa, sem linhas). */
const deformar = (g: THREE.BufferGeometry, mover: (x: number, v: number, p: number) => [number, number, number]) => {
  const pos = g.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    // giro de 90° (Y → X, X → -Y): só trocar os eixos espelharia a malha e inverteria as faces
    const [x, y, z] = mover(pos.getY(i), -pos.getX(i), pos.getZ(i));
    pos.setXYZ(i, x, y, z);
  }
  g.deleteAttribute('normal');
  g.deleteAttribute('uv');
  const s = mergeVertices(g, 1e-6);
  s.computeVertexNormals();
  return s;
};

/** Tira deitada sobre o topo do pão: meio comprimento `meio`, raio `r` (achatado em `alto`), pontas arredondadas. */
const tira = (meio: number, r: number, alto: number, desce: number) =>
  deformar(new THREE.SphereGeometry(1, 12, 48), (t, v, p) => {
    const k = (r * Math.pow(Math.max(0, 1 - Math.abs(t) ** 6), 0.5)) / Math.sqrt(Math.max(1e-9, 1 - t * t));
    const x = t * meio;
    return [x, topo(x) + desce + v * k * alto, p * k];
  });

// geometrias fixas, criadas uma vez (determinístico)
const GEO = {
  // esfera unitária esticada em fuso: o raio de cada anel vira R * perfil(t)
  corpo: deformar(new THREE.SphereGeometry(1, 48, 64), (t, v, p) => {
    const anel = Math.sqrt(Math.max(1e-9, 1 - t * t));
    const k = (R * perfil(t)) / anel;
    const x = t * MEIO, vv = v * k;
    return [x, CENTRO + curva(x) + vv * (vv > 0 ? 0.95 : 0.5), p * k];
  }),
  // sulco escuro contínuo ao longo do topo (15 cm) e lábios levantados dos lados; esfera com muitos anéis no comprimento
  // (a cápsula do Three não tem vértices no meio e não acompanharia a curva do topo)
  corte: tira(0.075, 0.005, 0.5, -0.0012),
  labio: tira(0.072, 0.003, 1, -0.0004),
};

const Pao: React.FC = () => (
  <group>
    <mesh geometry={GEO.corpo} material={mat(COR.casca)} castShadow receiveShadow />
    <mesh geometry={GEO.corte} material={mat(COR.corte)} receiveShadow />
    {[-1, 1].map((s) => <mesh key={s} position={[0, 0, s * 0.0062]} geometry={GEO.labio} material={mat(COR.labio)} castShadow receiveShadow />)}
  </group>
);

// --- bandeja: 28 x 13 cm, borda de 1,6 cm ---
const L = 0.28, P = 0.13, ALT = 0.016, E = 0.006;
/** Bandeja de metal: fundo prateado, paredes de aço escuro e um aro redondo contínuo (tubos + esferas nos cantos). */
const Bandeja: React.FC = () => {
  const cx = L / 2 - E / 2, cz = P / 2 - E / 2, ra = 0.004;
  return (
    <group>
      <Caixa p={[0, 0.002, 0]} t={[L - E, 0.004, P - E]} m={mat(COR.fundo)} />
      <Caixa p={[0, ALT / 2, cz]} t={[L, ALT, E]} m={mat(COR.parede)} />
      <Caixa p={[0, ALT / 2, -cz]} t={[L, ALT, E]} m={mat(COR.parede)} />
      <Caixa p={[cx, ALT / 2, 0]} t={[E, ALT, P - 2 * E]} m={mat(COR.parede)} />
      <Caixa p={[-cx, ALT / 2, 0]} t={[E, ALT, P - 2 * E]} m={mat(COR.parede)} />
      {/* aro enrolado por cima: liso nos cantos */}
      {[-1, 1].map((s) => (
        <React.Fragment key={s}>
          <mesh position={[0, ALT, s * cz]} rotation={[0, 0, Math.PI / 2]} material={mat(COR.aro, { brilho: 0.05 })} castShadow><cylinderGeometry args={[ra, ra, 2 * cx, 12]} /></mesh>
          <mesh position={[s * cx, ALT, 0]} rotation={[Math.PI / 2, 0, 0]} material={mat(COR.aro, { brilho: 0.05 })} castShadow><cylinderGeometry args={[ra, ra, 2 * cz, 12]} /></mesh>
          {[-1, 1].map((t) => <mesh key={t} position={[s * cx, ALT, t * cz]} material={mat(COR.aro, { brilho: 0.05 })} castShadow><sphereGeometry args={[ra, 12, 8]} /></mesh>)}
        </React.Fragment>
      ))}
    </group>
  );
};

/** Fumaça: bolinhas brancas translúcidas que nascem no topo do pão e crescem na subida (balanço < 0,3 mm por quadro). */
const Fumaca: React.FC<{ x: number; fase: number; n: number }> = ({ x, fase, n }) => {
  const q = useCurrentFrame();
  let y = topo(x) + 0.003;
  return (
    <group position={[x, 0, -0.004]}>
      {Array.from({ length: n }, (_, i) => {
        const t = i / (n - 1);
        const r = 0.0045 + 0.0085 * t;
        y += i === 0 ? r : r * 1.5; // cada bola encosta na anterior
        const dx = Math.sin(i * 0.9 + fase) * 0.007 * t + Math.sin((q / 75) * Math.PI * 2 + i * 0.6 + fase) * 0.0025 * t;
        return (
          <mesh key={i} position={[dx, y, 0]} material={mat(COR.fumaca, { brilho: 0.45, opac: 0.55 - 0.2 * t })}>
            <sphereGeometry args={[r, 16, 12]} />
          </mesh>
        );
      })}
    </group>
  );
};

export const PaoQuente: React.FC = () => (
  <group>
    <Bandeja />
    {/* sombra de contato do pão no fundo da bandeja */}
    <mesh position={[0, 0.0042, 0.006]} scale={[1, 1, 0.36]} material={mat(COR.sombra, { opac: 0.4 })}><cylinderGeometry args={[0.102, 0.102, 0.0004, 40]} /></mesh>
    <Pao />
    <Fumaca x={-0.035} fase={0} n={6} />
    <Fumaca x={0.04} fase={2.1} n={5} />
  </group>
);
