// Lote r08-acao, 3ª versão das ações: pensada para a câmera de frente (a da vitrine e a mais comum nas cenas).
// O kit só inclina o tronco para a frente/trás e as pernas só andam em Z; então a ação vai para o LADO da tela
// (+X, à direita de quem olha): o tronco gira 3/4 para lá e os braços esticam nessa direção, sem encurtar na
// perspectiva. O `acoes.ts` (2ª versão, de perfil) continua servindo as demos.
import * as THREE from 'three';
import { BASE, type Juntas } from '../../../kit/poses';
import { ALCANCE, alturaNoChao, bracoNo, posOmbro } from './cinematica';

const v3 = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);
const suave = (t: number) => { const k = Math.min(1, Math.max(0, t)); return k * k * (3 - 2 * k); };
const trecho = (q: number, a: number, b: number) => suave((q - a) / (b - a));
const R = THREE.MathUtils.degToRad;
/** Direção pelo azimute (de +Z para +X) e elevação, em graus. */
const direcao = (az: number, el: number) => v3(Math.sin(R(az)) * Math.cos(R(el)), Math.sin(R(el)), Math.cos(R(az)) * Math.cos(R(el)));

/** BASE + corpo, braços pela IK e o pé mais baixo apoiado no chão. */
function fechar(corpo: Partial<Juntas>, maoD?: THREE.Vector3, maoE?: THREE.Vector3): Juntas {
  let j: Juntas = { ...BASE, ...corpo };
  if (maoD) j = { ...j, ...bracoNo(j, 1, maoD) };
  if (maoE) j = { ...j, ...bracoNo(j, -1, maoE) };
  return { ...j, altura: alturaNoChao(j) };
}
/** Braço solto, colado ao corpo. */
const BRACO_E_SOLTO: Partial<Juntas> = { ombroEX: 6, ombroEZ: 2, cotoveloE: 16 };

// ── puxar ─────────────────────────────────────────────────────────────────
// Quem foge está à direita de quem olha (az 62°). O tronco gira 48° para ele e deita para trás (−18°, −25° no
// tranco). Os dois braços esticam retos, na altura do peito, e se juntam numa alça só (as mãos quase se tocam).
// Perna D à frente, reta, de calcanhar fincado e ponta para cima; perna E atrás, dobrada: o peso fica atrás.
// A cabeça baixa o queixo e pende para longe da puxada. Tranco a cada 30 quadros (pico no 90).
const DIR_PUXA = direcao(62, -6);
export const tranco = (q: number) => Math.pow(0.5 + 0.5 * Math.cos((2 * Math.PI * q) / 30), 2);
export function puxar(q: number): Partial<Juntas> {
  const f = tranco(q);
  const corpo: Partial<Juntas> = {
    troncoX: -18 - 7 * f, troncoY: 48,
    quadrilD: 30 + 3 * f, joelhoD: 2, quadrilE: -8, joelhoE: 26,
    cabecaX: 10 + 4 * f, cabecaY: -12, cabecaZ: 14 + 4 * f,
  };
  const j = { ...BASE, ...corpo };
  const meio = posOmbro(j, 1).add(posOmbro(j, -1)).multiplyScalar(0.5);
  const alca = meio.addScaledVector(DIR_PUXA, 0.56); // além do alcance: os dois braços ficam retos, mirando a alça
  return fechar(corpo, alca, alca);
}
export const PUXAR: Partial<Juntas> = puxar(90);

// ── riscar ────────────────────────────────────────────────────────────────
// O alvo está à direita, na altura do ombro (az 74°). O tronco gira 40° para ele; o braço D estica reto, com o
// punho firme, e a mão desenha um X de 11 cm num plano de frente para o braço. O braço E fica solto, junto ao
// corpo. Peso na perna E (reta); a D vai um pouco à frente, relaxada. O tronco empurra +3° em cada traço.
const CORPO_RISCAR: Partial<Juntas> = {
  troncoX: 4, troncoY: 40,
  quadrilD: 14, joelhoD: 14, quadrilE: -5, joelhoE: 0,
  ...BRACO_E_SOLTO,
  cabecaX: 2, cabecaY: -4, cabecaZ: 0, // rosto a 36° da câmera: além de ~38° o sorriso do kit deforma
};
const DIR_RISCA = direcao(74, 6);
const OMBRO_R = posOmbro({ ...BASE, ...CORPO_RISCAR }, 1);
const CENTRO_X = OMBRO_R.clone().addScaledVector(DIR_RISCA, ALCANCE - 0.016);
const U = new THREE.Vector3().crossVectors(v3(0, 1, 0), DIR_RISCA).normalize(); // lado do X
const V = new THREE.Vector3().crossVectors(DIR_RISCA, U).normalize(); // cima do X
const MEIO = 0.055, AR = 0.05;
const canto = (sx: number, sy: number, fora = 0) =>
  CENTRO_X.clone().addScaledVector(U, sx * MEIO).addScaledVector(V, sy * MEIO).addScaledVector(DIR_RISCA, -fora);
/** Mão no quadro: sobe 6–30, encosta 34–40, 1º traço 40–54, troca de canto 54–80, 2º traço 80–98, recua. */
function maoRiscar(q: number): { mao: THREE.Vector3; forca: number } {
  const t1 = trecho(q, 40, 54), t2 = trecho(q, 80, 98);
  let mao: THREE.Vector3;
  if (q < 40) mao = OMBRO_R.clone().add(v3(0.03, -0.44, 0.1)).lerp(canto(-1, 1, AR), trecho(q, 6, 30)).lerp(canto(-1, 1), trecho(q, 34, 40));
  else if (q < 54) mao = canto(-1, 1).lerp(canto(1, -1), t1);
  else if (q < 80) mao = canto(1, -1 + 2 * trecho(q, 58, 74), AR * (trecho(q, 54, 60) - trecho(q, 74, 80)));
  else if (q < 98) mao = canto(1, 1).lerp(canto(-1, -1), t2);
  else mao = canto(-1, -1, 0.08 * trecho(q, 98, 112));
  return { mao, forca: Math.sin(Math.PI * t1) + Math.sin(Math.PI * t2) };
}
export function riscar(q: number): Partial<Juntas> {
  const { mao, forca } = maoRiscar(q);
  return fechar({ ...CORPO_RISCAR, troncoX: 4 + 3 * forca }, mao);
}
export const RISCAR: Partial<Juntas> = riscar(90);

// ── entregar ──────────────────────────────────────────────────────────────
// Quem recebe está à direita (az 68°), a ~1 m. O tronco gira 34° para ele e inclina 8° para a frente; a perna D
// dá o passo. O braço D vai à frente, um pouco abaixo do ombro, com o cotovelo levemente dobrado (~30°).
// A cabeça fica com o tronco (mais giro deforma o sorriso do kit) e baixa o queixo: olha a mão e quem recebe.
// Entre 10 e 34 o braço sai do peito; depois, a cada 40 quadros, um "toma!" (estica de vez e volta).
const CORPO_ENTREGAR: Partial<Juntas> = {
  troncoX: 8, troncoY: 34,
  quadrilD: 24, joelhoD: 12, quadrilE: -10, joelhoE: 10,
  ...BRACO_E_SOLTO,
  cabecaX: 10, cabecaY: -2, cabecaZ: 0, // rosto a 32° da câmera
};
const DIR_ENTREGA = direcao(68, -14);
const OMBRO_ENT = posOmbro({ ...BASE, ...CORPO_ENTREGAR }, 1);
const MAO_PEITO = OMBRO_ENT.clone().add(v3(-0.08, -0.22, 0.2));
function maoEntregar(q: number): THREE.Vector3 {
  const f = ((((q - 34) % 40) + 40) % 40) / 40;
  const toma = q >= 34 && f < 0.5 ? Math.sin(2 * Math.PI * f) : 0;
  const estendida = OMBRO_ENT.clone().addScaledVector(DIR_ENTREGA, ALCANCE - 0.024 + 0.018 * toma);
  return MAO_PEITO.clone().lerp(estendida, trecho(q, 10, 34));
}
export function entregar(q: number): Partial<Juntas> {
  return fechar(CORPO_ENTREGAR, maoEntregar(q));
}
export const ENTREGAR: Partial<Juntas> = entregar(90);
