// Objetos das ações do lote (tamanho real, só primitivas, cores chapadas, cache de material por cor).
import * as THREE from 'three';
import React from 'react';

const cache = new Map<string, THREE.MeshStandardMaterial>();
export const mat = (cor: string, rug = 0.85) => {
  const k = `${cor}|${rug}`;
  let m = cache.get(k);
  if (!m) { m = new THREE.MeshStandardMaterial({ color: cor, roughness: rug }); cache.set(k, m); }
  return m;
};
type V3 = [number, number, number];
const Caixa: React.FC<{ p: V3; t: V3; cor: string; r?: V3 }> = ({ p, t, cor, r = [0, 0, 0] }) => (
  <mesh position={p} rotation={r} material={mat(cor)} castShadow receiveShadow><boxGeometry args={t} /></mesh>
);
/** Cilindro deitado ao longo de Z, de z0 a z1 (raio r0 em z0 e r1 em z1). */
const TuboZ: React.FC<{ z0: number; z1: number; r0: number; r1?: number; cor: string; y?: number; seg?: number }> = ({ z0, z1, r0, r1 = r0, cor, y = 0, seg = 16 }) => (
  <mesh position={[0, y, (z0 + z1) / 2]} rotation={[Math.PI / 2, 0, 0]} material={mat(cor)} castShadow>
    {/* deitado com giro X de +90°: o topo do cilindro (r1) vai para +Z */}
    <cylinderGeometry args={[r1, r0, Math.abs(z1 - z0), seg]} />
  </mesh>
);

// ── Marcador permanente vermelho (15 cm). Origem no centro da mão que o segura; a ponta aponta para +Z ──
const MK = { corpo: '#d7263d', escuro: '#9e1729', rotulo: '#f4f1ea', ponta: '#b3122b' };
export const PONTA_MARCADOR = 0.13;
export const Marcador: React.FC = () => (
  <group>
    {/* tampa encaixada atrás, com o clipe */}
    <TuboZ z0={-0.105} z1={-0.05} r0={0.0145} cor={MK.corpo} />
    <TuboZ z0={-0.112} z1={-0.105} r0={0.011} r1={0.0145} cor={MK.escuro} />
    <Caixa p={[0, 0.017, -0.075]} t={[0.006, 0.006, 0.045]} cor={MK.escuro} />
    {/* corpo com faixa clara do rótulo e anel escuro */}
    <TuboZ z0={-0.05} z1={0.085} r0={0.013} cor={MK.corpo} />
    <TuboZ z0={0.075} z1={0.095} r0={0.0135} cor={MK.rotulo} />
    <TuboZ z0={0.095} z1={0.105} r0={0.013} r1={0.009} cor={MK.escuro} />
    {/* ponta chanfrada */}
    <TuboZ z0={0.105} z1={PONTA_MARCADOR} r0={0.0055} r1={0.002} cor={MK.ponta} />
  </group>
);

// ── Caneta esferográfica (15 cm). Origem no centro da mão; a ponta (oferecida) aponta para +Z ──
const CN = { corpo: '#2f6fd6', tampa: '#1d3f86', ponta: '#c9ced6', clipe: '#e8edf3' };
export const PONTA_CANETA = 0.155;
export const Caneta: React.FC = () => (
  <group>
    {/* botão atrás, corpo azul, cone de metal e ponta */}
    <TuboZ z0={-0.04} z1={-0.025} r0={0.005} cor={CN.tampa} />
    <TuboZ z0={-0.025} z1={0.12} r0={0.0085} cor={CN.corpo} seg={6} />
    <TuboZ z0={0.06} z1={0.1} r0={0.009} cor={CN.tampa} seg={6} />
    <TuboZ z0={0.12} z1={0.145} r0={0.0085} r1={0.003} cor={CN.ponta} />
    <TuboZ z0={0.145} z1={PONTA_CANETA} r0={0.002} r1={0.001} cor={CN.tampa} />
    {/* clipe de metal em cima, perto do botão */}
    <Caixa p={[0, 0.011, -0.005]} t={[0.005, 0.004, 0.045]} cor={CN.clipe} />
  </group>
);

// ── Quadro de calendário num cavalete (alvo do X). Origem no chão, sob o centro do quadro; face de riscar em -Z ──
// O quadro tem 72 × 56 cm e o centro a `alturaCentro`; a face de riscar fica em z = 0 (o corpo vai para +Z).
const QD = { moldura: '#8a5a2b', folha: '#fbf7ee', topo: '#3a7bd5', grade: '#b9c2cf', dia: '#3a3f4b', pe: '#6e4522' };
const CEL = 0.2; // lado de cada dia do calendário
/** Centro do dia (coluna 0..2, linha 0..1) relativo ao centro do quadro. */
export const centroDia = (col: number, lin: number): [number, number] => [(col - 1) * CEL, 0.05 - lin * CEL];
export const Cavalete: React.FC<{ alturaCentro: number }> = ({ alturaCentro: yc }) => {
  const w = 0.72, h = 0.56;
  // 3 colunas × 2 linhas de dias, centradas no quadro
  const x0 = -CEL;
  return (
    <group>
      <group position={[0, yc, 0]}>
        <Caixa p={[0, 0, 0.02]} t={[w + 0.06, h + 0.06, 0.03]} cor={QD.moldura} />
        <Caixa p={[0, 0, 0.002]} t={[w, h, 0.01]} cor={QD.folha} />
        {/* faixa do mês com "rabiscos" claros */}
        <Caixa p={[0, h / 2 - 0.05, -0.006]} t={[w, 0.1, 0.006]} cor={QD.topo} />
        {[[-0.12, 0.12], [0.06, 0.16]].map(([x, l], i) => (
          <Caixa key={i} p={[x, h / 2 - 0.05, -0.0105]} t={[l, 0.03, 0.004]} cor={QD.folha} />
        ))}
        {/* grade dos dias (as linhas ficam -1 cm à frente da folha) */}
        {[0, 1, 2, 3].map((c) => <Caixa key={`v${c}`} p={[x0 - CEL / 2 + c * CEL, -0.05, -0.005]} t={[0.008, 2 * CEL, 0.004]} cor={QD.grade} />)}
        {[0, 1, 2].map((l) => <Caixa key={`h${l}`} p={[x0 + CEL, 0.15 - l * CEL, -0.005]} t={[3 * CEL, 0.008, 0.004]} cor={QD.grade} />)}
        {/* número de cada dia: um tracinho no canto (simples, sem fonte) */}
        {[0, 1, 2, 3, 4, 5].map((i) => (
          <Caixa key={i} p={[x0 - CEL / 2 + 0.04 + (i % 3) * CEL, 0.12 - Math.floor(i / 3) * CEL, -0.006]} t={[0.016, 0.035, 0.004]} cor={QD.dia} />
        ))}
      </group>
      {/* cavalete: duas pernas da frente, uma atrás e a canaleta que apoia o quadro */}
      {[-1, 1].map((l) => (
        <mesh key={l} position={[0.28 * l, (yc + h / 2) / 2, 0.07]} rotation={[-0.1, 0, -0.08 * l]} material={mat(QD.pe)} castShadow receiveShadow>
          <boxGeometry args={[0.04, yc + h / 2 + 0.05, 0.035]} />
        </mesh>
      ))}
      <mesh position={[0, yc / 2 + 0.1, 0.32]} rotation={[-0.35, 0, 0]} material={mat(QD.pe)} castShadow receiveShadow>
        <boxGeometry args={[0.04, yc + 0.25, 0.035]} />
      </mesh>
      <Caixa p={[0, yc - h / 2 - 0.045, 0.0]} t={[w + 0.12, 0.03, 0.08]} cor={QD.pe} />
    </group>
  );
};

/** Traço de marcador entre dois pontos (no plano XY do quadro), com espessura de 2,2 cm. */
export const Traco: React.FC<{ a: THREE.Vector3; b: THREE.Vector3; cor?: string }> = ({ a, b, cor = MK.corpo }) => {
  const d = new THREE.Vector3().subVectors(b, a);
  const L = d.length();
  if (L < 0.002) return null;
  const c = new THREE.Vector3().addVectors(a, b).multiplyScalar(0.5);
  return (
    <group position={c} rotation={[0, 0, Math.atan2(d.y, d.x)]}>
      <mesh material={mat(cor)} receiveShadow><boxGeometry args={[L, 0.022, 0.003]} /></mesh>
      {/* pontas arredondadas */}
      {[-1, 1].map((l) => (
        <mesh key={l} position={[(l * L) / 2, 0, 0]} rotation={[Math.PI / 2, 0, 0]} material={mat(cor)}>
          <cylinderGeometry args={[0.011, 0.011, 0.003, 14]} />
        </mesh>
      ))}
    </group>
  );
};
