import React from 'react';
import { useCurrentFrame } from 'remotion';
import { Caixa, Placa } from './base';

const C = { ouro: '#edb940', ouroEscuro: '#ad7528', preto: '#080a0e', branco: '#ffffff', rastro: '#667078' };
const VALOR = '1.073.741.824x';
const ALTURA = 0.4;
const LARGURA = 0.17;
const TRACO = 0.038;
const PASSO = 0.48;
const JANELA = 0.46;

// a: topo; b/c: direita; d: base; e/f: esquerda; g: meio.
const DIGITOS = ['abcdef', 'bc', 'abdeg', 'abcdg', 'bcfg', 'acdfg', 'acdefg', 'abc', 'abcdefg', 'abcdfg'];
type Traco = { nome: string; x: number; y: number; largura: number; altura: number };
const SEGMENTOS: Traco[] = [
  { nome: 'a', x: 0, y: (ALTURA - TRACO) / 2, largura: LARGURA - TRACO, altura: TRACO },
  { nome: 'b', x: (LARGURA - TRACO) / 2, y: (ALTURA - TRACO) / 4, largura: TRACO, altura: (ALTURA - 3 * TRACO) / 2 },
  { nome: 'c', x: (LARGURA - TRACO) / 2, y: -(ALTURA - TRACO) / 4, largura: TRACO, altura: (ALTURA - 3 * TRACO) / 2 },
  { nome: 'd', x: 0, y: -(ALTURA - TRACO) / 2, largura: LARGURA - TRACO, altura: TRACO },
  { nome: 'e', x: -(LARGURA - TRACO) / 2, y: -(ALTURA - TRACO) / 4, largura: TRACO, altura: (ALTURA - 3 * TRACO) / 2 },
  { nome: 'f', x: -(LARGURA - TRACO) / 2, y: (ALTURA - TRACO) / 4, largura: TRACO, altura: (ALTURA - 3 * TRACO) / 2 },
  { nome: 'g', x: 0, y: 0, largura: LARGURA - TRACO, altura: TRACO },
];

// Recorte geométrico: nenhuma parte do rolete ultrapassa a sua janela.
const Digito: React.FC<{
  numero: number; deslocamento?: number; janela?: number; cor?: string;
}> = ({ numero, deslocamento = 0, janela = JANELA, cor = C.branco }) => (
  <group>
    {SEGMENTOS.filter((s) => DIGITOS[numero].includes(s.nome)).map((s) => {
      const baixo = Math.max(-janela / 2, s.y + deslocamento - s.altura / 2);
      const alto = Math.min(janela / 2, s.y + deslocamento + s.altura / 2);
      if (alto - baixo < 0.002) return null;
      return <Caixa key={s.nome} p={[s.x, (alto + baixo) / 2, 0]} t={[s.largura, alto - baixo, 0.008]}
        cor={cor} sombra={false} chapado />;
    })}
  </group>
);

const Rolete: React.FC<{ alvo: number; indice: number; quadro: number }> = ({ alvo, indice, quadro }) => {
  const passos = 18 + indice;
  const tempo = Math.min(1, Math.max(0, quadro / (56 + indice * 3)));
  const progresso = passos * (1 - (1 - tempo) ** 2);
  const inteiro = Math.floor(progresso);
  const fracao = progresso - inteiro;
  const atual = (alvo - passos + inteiro + 100) % 10;
  // No quadro 90, o valor já é legível e os roletes ainda deixam rastros.
  const giro = Math.max(0, quadro) / 2.3 + indice * 0.37;
  const parte = giro - Math.floor(giro);
  const anterior = Math.floor(giro) % 10;
  return (
    <group>
      <Digito numero={atual} deslocamento={-fracao * PASSO} />
      {tempo < 1 && <Digito numero={(atual + 1) % 10} deslocamento={(1 - fracao) * PASSO} />}
      {quadro < 132 && ([-1, 1] as const).map((lado) => (
        <group key={lado} position={[0, lado * 0.3, 0]}>
          <Digito numero={anterior} deslocamento={-parte * PASSO} janela={0.09} cor={C.rastro} />
          <Digito numero={(anterior + 1) % 10} deslocamento={(1 - parte) * PASSO} janela={0.09} cor={C.rastro} />
        </group>
      ))}
    </group>
  );
};

const larguraCaractere = (caractere: string) => caractere === '.' ? 0.055 : LARGURA;
const ESPACO = 0.04;
const LARGURA_TEXTO = [...VALOR].reduce((soma, c) => soma + larguraCaractere(c), 0) + (VALOR.length - 1) * ESPACO;

// Frente +Z: painel de 3 m, borda uniforme de 10 cm e pés no chão.
export const ContadorGigante: React.FC<{ quadro?: number }> = ({ quadro }) => {
  const quadroAtual = useCurrentFrame();
  const q = quadro ?? quadroAtual;
  let cursor = -LARGURA_TEXTO / 2;
  let indice = 0;
  return (
    <group>
      {([-1, 1] as const).map((lado) => (
        <group key={lado}>
          <Caixa p={[lado * 1.1, 0.07, -0.04]} t={[0.52, 0.14, 0.56]} cor={C.ouroEscuro} />
          <Caixa p={[lado * 1.1, 0.4, -0.04]} t={[0.12, 0.58, 0.16]} cor={C.ouroEscuro} />
        </group>
      ))}
      <Placa p={[0, 1.16, -0.04]} largura={3} altura={1.04} espessura={0.24} raio={0.1} cor={C.ouroEscuro} />
      <Placa p={[0, 1.16, 0.13]} largura={3} altura={1.04} espessura={0.06} raio={0.1} cor={C.ouro} />
      <Placa p={[0, 1.16, 0.21]} largura={2.8} altura={0.84} espessura={0.04} raio={0.045} cor={C.preto} chapado />
      {/* Tela até z=0,23; caixas de 8 mm a 2 cm da superfície. */}
      <group position={[0, 1.16, 0.254]}>
        {[...VALOR].map((caractere, i) => {
          const largura = larguraCaractere(caractere);
          const x = cursor + largura / 2;
          cursor += largura + ESPACO;
          if (caractere === '.') return <Caixa key={i} p={[x, -0.1725, 0]} t={[0.055, 0.055, 0.008]}
            cor={C.branco} sombra={false} chapado />;
          if (caractere === 'x') return (
            <group key={i} position={[x, -0.08, 0]}>
              <Caixa p={[0, 0, 0]} t={[0.17, TRACO, 0.008]} cor={C.branco} giro={Math.PI / 4} sombra={false} chapado />
              <Caixa p={[0, 0, 0.028]} t={[0.17, TRACO, 0.008]} cor={C.branco} giro={-Math.PI / 4} sombra={false} chapado />
            </group>
          );
          return <group key={i} position={[x, 0, 0]}><Rolete alvo={Number(caractere)} indice={indice++} quadro={q} /></group>;
        })}
      </group>
    </group>
  );
};
