// Objeto: caderno roxo da Bia, aberto (35,5 x 25,5 cm aberto; cada página 15,5 x 21,5 cm), espiral no meio,
// as duas páginas niveladas e cheias de contas a lápis grafite, em traço grosso. As contas dobram linha a linha.
// `inclinacao` (graus): 0 = em pé, 15 = encostado (vitrine), 90 = deitado aberto sobre a mesa.
import React from 'react';
import { random } from 'remotion';
import { mat, Tracos, Inclinado, textoTracos, type Traco } from './base';

const C = { capa: '#8e5bd6', capaEscura: '#6a3fb0', pagina: '#fbfaf5', lapis: '#3c3e44', espiral: '#9aa1ab' };
const CW = 0.37, CH = 0.255, CD = 0.008; // capa aberta (8 mm: dá borda e sombra)
const PW = 0.16, PH = 0.215, PD = 0.006; // cada bloco de páginas (sobra ~2 cm de capa roxa em volta)
const VAO = 0.008; // meio-vão da espiral (cada página começa a 8 mm do meio)
const zP = CD + PD; // frente das páginas

// 5 + 4 linhas, no máximo 9 caracteres para caber com margem de 10%; a última conta fica sublinhada
const CONTAS = [
  ['1x2=2', '2x2=4', '4x2=8', '8x2=16', '16x2=32'],
  ['32x2=64', '64x2=128', '128x2=256', '256x2=512'],
];
const LETRA = { w: 0.0078, h: 0.019, passo: 0.0136, incl: 0.16, traco: 0.0038 };
const MARGEM = 0.1 * PW; // 1,6 cm
const TOPO = CH / 2 + PH / 2 - 0.1 * PH - LETRA.h, PASSO_LINHA = 0.037; // base da 1ª linha e espaço entre linhas

/** Contas de uma página (lado -1 = esquerda, 1 = direita), com pequeno tremor de mão determinístico. */
const contasPagina = (lado: -1 | 1): Traco[] => {
  const x0 = lado * (VAO + PW / 2) - PW / 2 + MARGEM;
  return CONTAS[lado < 0 ? 0 : 1].flatMap((txt, i) => {
    const dx = random(`caderno-x-${lado}-${i}`) * 0.003, dy = (random(`caderno-y-${lado}-${i}`) - 0.5) * 0.003;
    const y = TOPO - i * PASSO_LINHA + dy, giro = (random(`caderno-g-${lado}-${i}`) - 0.5) * 0.03;
    const t = textoTracos(txt, x0 + dx, y, LETRA.w, LETRA.h, LETRA.passo, LETRA.incl);
    // última conta da direita: resultado sublinhado duas vezes
    if (lado > 0 && i === CONTAS[1].length - 1) {
      const xa = x0 + dx + 6 * LETRA.passo - 0.002, xb = x0 + dx + 8 * LETRA.passo + LETRA.w + 0.003;
      t.push([xa, y - 0.0065, xb, y - 0.0075], [xa + 0.002, y - 0.0125, xb - 0.002, y - 0.0135]);
    }
    // gira a linha inteira um pouquinho em volta do começo (ninguém escreve reto)
    return t.map(([a, b, c, d]): Traco => {
      const r = (px: number, py: number) => [x0 + dx + (px - x0 - dx) * Math.cos(giro) - (py - y) * Math.sin(giro), y + (px - x0 - dx) * Math.sin(giro) + (py - y) * Math.cos(giro)];
      const [p1, p2] = [r(a, b), r(c, d)];
      return [p1[0], p1[1], p2[0], p2[1]];
    });
  });
};

const Caderno: React.FC = () => {
  const lapis = mat(C.lapis, { rug: 0.9 });
  const tracos = React.useMemo(() => [...contasPagina(-1), ...contasPagina(1)], []);
  return (
    <group>
      {/* capa roxa aberta (8 mm), com a lombada mais escura atrás da espiral */}
      <mesh position={[0, CH / 2, CD / 2]} material={mat(C.capa)} castShadow receiveShadow><boxGeometry args={[CW, CH, CD]} /></mesh>
      <mesh position={[0, CH / 2, CD + 0.0004]} material={mat(C.capaEscura)} receiveShadow><boxGeometry args={[2 * VAO + 0.004, CH - 0.006, 0.0008]} /></mesh>
      {/* blocos de páginas, um de cada lado, no mesmo plano e do mesmo tamanho */}
      {[-1, 1].map((lado) => (
        <mesh key={lado} position={[lado * (VAO + PW / 2), CH / 2, CD + PD / 2]} material={mat(C.pagina, { brilho: 0.15 })} castShadow receiveShadow><boxGeometry args={[PW, PH, PD]} /></mesh>
      ))}
      <Tracos tracos={tracos} l={LETRA.traco} z={zP + 0.0006} m={lapis} />
      {/* espiral: 6 argolas grossas atravessando o vão do meio */}
      {Array.from({ length: 6 }, (_, i) => (
        <mesh key={i} position={[0, CH / 2 - PH / 2 + 0.022 + i * ((PH - 0.044) / 5), zP - 0.003]} rotation={[Math.PI / 2, 0, 0]} material={mat(C.espiral, { rug: 0.5 })} castShadow>
          <torusGeometry args={[0.012, 0.0032, 8, 20]} />
        </mesh>
      ))}
    </group>
  );
};

export const CadernoBia: React.FC<{ inclinacao?: number }> = ({ inclinacao = 15 }) => (
  <group position={[0, 0, inclinacao >= 80 ? CH / 2 : 0]}>
    <Inclinado graus={inclinacao}><Caderno /></Inclinado>
  </group>
);
