// Gráfico em metros, atrás do elenco. Crescimento e aperto dependem só do quadro.
import React from 'react';
import { useCurrentFrame } from 'remotion';
import { Caixa, mat, type V3 } from './base';

export const CEU_GRAFICO = '#123778';
const C = { eixo: '#3465b1', verde: '#2edb78', vermelho: '#f43c45' };
const BASE = 0.12;
const TETO = 2.72;
const Z = -3.1;

const suave = (quadro: number, de: number, ate: number) => {
  const t = Math.max(0, Math.min(1, (quadro - de) / (ate - de)));
  return t * t * (3 - 2 * t);
};

// Traços contínuos: o 1 tem haste inteira, bandeira e pé; os zeros são fechados.
const Traco: React.FC<{ p: V3; t: V3; giro?: number }> = ({ p, t, giro = 0 }) => (
  <Caixa p={p} t={t} r={[0, 0, giro]} cor={C.vermelho} brilho={0.18} sombra={false} />
);

const Zero: React.FC<{ x: number }> = ({ x }) => (
  <group position={[x, 0, 0]}>
    {[-1, 1].map((lado) => (
      <React.Fragment key={lado}>
        <Traco p={[0, lado * 0.22, 0]} t={[0.4, 0.1, 0.12]} />
        <Traco p={[lado * 0.15, 0, 0]} t={[0.1, 0.34, 0.12]} />
      </React.Fragment>
    ))}
  </group>
);

const Rotulo: React.FC = () => (
  // O pé das letras encosta na linha; toda a inscrição usa o mesmo vermelho.
  <group position={[-2.92, TETO + 0.39, Z + 0.42]}>
    <Traco p={[-0.85, 0, 0]} t={[0.11, 0.54, 0.12]} />
    <Traco p={[-0.91, 0.19, 0]} t={[0.25, 0.1, 0.12]} giro={0.55} />
    <Traco p={[-0.85, -0.22, 0]} t={[0.34, 0.1, 0.12]} />
    <Zero x={-0.3} />
    <Zero x={0.26} />
    {/* Dois anéis quadrados e uma diagonal grossa formam o percentual. */}
    <group position={[0.96, 0, 0]}>
      {[-1, 1].map((lado) => (
        <group key={lado} position={[-lado * 0.19, lado * 0.15, 0]}>
          {[-1, 1].map((s) => (
            <React.Fragment key={s}>
              <Traco p={[0, s * 0.1, 0]} t={[0.28, 0.08, 0.12]} />
              <Traco p={[s * 0.1, 0, 0]} t={[0.08, 0.12, 0.12]} />
            </React.Fragment>
          ))}
        </group>
      ))}
      <Traco p={[0, 0, 0]} t={[0.1, 0.66, 0.12]} giro={-0.55} />
    </group>
  </group>
);

export const GraficoBarras: React.FC = () => {
  const quadro = useCurrentFrame();
  const aperto = suave(quadro, 68, 88);
  const altura = 0.45 + (TETO - BASE - 0.45) * suave(quadro, 20, 68);
  const alturaTopo = Math.min(altura * 0.5, 1.04 - 0.38 * aperto);
  const alturaCorpo = altura - alturaTopo;
  const larguraCorpo = 0.82 + 0.32 * aperto;
  const larguraTopo = larguraCorpo + 0.56 * aperto;

  return (
    <group>
      {/* Sem parede: o céu liso não recebe o polígono de sombra do teto. */}
      <hemisphereLight args={['#b0d6ff', '#365ba7', 0.95]} />
      <directionalLight position={[-6, 6, 3]} color="#bad8ff" intensity={0.85} />
      <Caixa p={[0, -0.16, 0]} t={[70, 0.32, 70]} cor={CEU_GRAFICO} brilho={0.1} sombra={false} />
      <Caixa p={[0, BASE / 2, Z]} t={[8.5, BASE, 0.8]} cor={C.eixo} sombra={false} />
      {/* Duas barras à esquerda, uma no intervalo do elenco e duas à direita. */}
      {[
        { x: -3.45, h: 0.65, l: 0.72 },
        { x: -2.18, h: 1.15, l: 0.78 },
        { x: 0, h: 1.82, l: 0.82 },
        { x: 1.95, h: 2.2, l: 0.82 },
      ].map(({ x, h, l }, i) => {
        const a = 0.18 + (h - 0.18) * suave(quadro, 4 + i * 7, 34 + i * 7);
        return <Caixa key={i} p={[x, BASE + a / 2, Z]} t={[l, a, 0.62]} cor={C.verde} />;
      })}
      {/* Mesmo verde e bordas contínuas: o terço superior inteiro se deforma. */}
      <Caixa p={[3.25, BASE + alturaCorpo / 2, Z]} t={[larguraCorpo, alturaCorpo, larguraCorpo * 0.46]} cor={C.verde} />
      <group position={[3.25, BASE + alturaCorpo + alturaTopo / 2, Z]} scale={[1, 1, 0.46]}>
        <mesh rotation={[0, Math.PI / 4, 0]} material={mat(C.verde, 0, true, true)} castShadow receiveShadow>
          <cylinderGeometry args={[larguraTopo / Math.SQRT2, larguraCorpo / Math.SQRT2, alturaTopo, 4]} />
        </mesh>
      </group>
      {/* Guia horizontal sem postes. O topo verde encosta na face inferior. */}
      <Caixa p={[0, TETO + 0.06, Z]} t={[8.5, 0.12, 0.8]} cor={C.vermelho} brilho={0.18} sombra={false} />
      <Rotulo />
    </group>
  );
};
