// Efeito `noite`: a cena vira um quarto à noite, azul-escuro, e a luz quente vem só do abajur (à direita) e do celular (na mão).
// Como funciona: as luzes da cena (céu e sol do kit/Luz) são escurecidas e puxadas para o azul; o sol fica quase apagado,
// então a única sombra marcada é a do abajur. O quarto (piso, parede com janela, cama, quadro) cobre o cenário do dia.
// Tudo volta ao original quando o efeito sai de cena.
import * as THREE from 'three';
import React, { useLayoutEffect } from 'react';
import { useThree } from '@react-three/fiber';
import { Halo, mat, suave, TAU, type V3 } from './base';

const C = {
  fundo: '#141a33', ceuLuz: '#7486c8', chaoLuz: '#2a3150', lua: '#9db3ee', preenche: '#6f8de0',
  quente: '#ffb45c', cupula: '#ffd9a0', lampada: '#fff1cf', tela: '#f4f6ff', telaLuz: '#ffd7a8', telaHalo: '#e2ebff', luar: '#6f86d6',
  parede: '#7d88a8', rodape: '#d8d2c6', piso1: '#8a6446', piso2: '#7d5a3e',
  janela: '#e4ddd0', vidro: '#1c2758', luaDisco: '#fff1c4', astro: '#e8ecff', cortina: '#55668a',
  cama: '#6e4a32', colchao: '#e8e4dc', coberta: '#4f7fb8', travesseiro: '#f4f1ea',
  moldura: '#3a3a48', quadro: '#e9b55a', morro: '#3f8f6a',
  madeira: '#8a5a3a', madeiraEsc: '#6e452c', metal: '#3a3a44', capa: '#2d3a5c', tapete: '#4b546b', tapeteBorda: '#959cad',
};
const NOITE = '__noite';
const PISO = 0.025; // topo do piso do quarto (o tênis do boneco começa em 3,5 cm)

type Original = { intensidade: number; cor: THREE.Color; chao?: THREE.Color };

/** Escurece e azula as luzes que não são do efeito; `k` 0..1 é o quanto já anoiteceu. */
function useAnoitecer(k: number) {
  const scene = useThree((s) => s.scene);
  useLayoutEffect(() => {
    scene.traverse((o) => {
      const l = o as THREE.Light;
      if (!l.isLight || l.userData[NOITE]) return;
      const ud = l.userData as { noiteOrig?: Original };
      const h = l as THREE.HemisphereLight;
      if (!ud.noiteOrig) ud.noiteOrig = { intensidade: l.intensity, cor: l.color.clone(), chao: h.isHemisphereLight ? h.groundColor.clone() : undefined };
      const orig = ud.noiteOrig;
      // céu: ar azul que ainda deixa ler as cores; sol: apagado (a sombra do dia some de vez)
      const fator = h.isHemisphereLight ? 0.7 : (l as THREE.DirectionalLight).isDirectionalLight ? 0 : 0.3;
      l.intensity = orig.intensidade * (1 + (fator - 1) * k);
      l.color.copy(orig.cor).lerp(new THREE.Color(h.isHemisphereLight ? C.ceuLuz : C.lua), k);
      if (h.isHemisphereLight && orig.chao) h.groundColor.copy(orig.chao).lerp(new THREE.Color(C.chaoLuz), k);
    });
    const ud = scene.userData as { noiteFundo?: THREE.Color };
    const fundo = scene.background as THREE.Color | null;
    if (fundo && fundo.isColor) {
      if (!ud.noiteFundo) ud.noiteFundo = fundo.clone();
      fundo.copy(ud.noiteFundo).lerp(new THREE.Color(C.fundo), k);
    }
  });
  // ao sair de cena, devolve tudo como estava
  useLayoutEffect(() => () => {
    scene.traverse((o) => {
      const l = o as THREE.Light;
      const orig = (l.userData as { noiteOrig?: Original }).noiteOrig;
      if (!l.isLight || !orig) return;
      l.intensity = orig.intensidade; l.color.copy(orig.cor);
      if (orig.chao) (l as THREE.HemisphereLight).groundColor.copy(orig.chao);
      delete l.userData.noiteOrig;
    });
    const ud = scene.userData as { noiteFundo?: THREE.Color };
    if (ud.noiteFundo && scene.background && (scene.background as THREE.Color).isColor) (scene.background as THREE.Color).copy(ud.noiteFundo);
    delete ud.noiteFundo;
  }, [scene]);
}

const Caixa: React.FC<{ p: V3; t: V3; cor: string; brilho?: number; sombra?: boolean; r?: V3 }> = ({ p, t, cor, brilho = 0, sombra = true, r }) => (
  <mesh position={p} rotation={r} material={mat(cor, brilho)} castShadow={sombra} receiveShadow><boxGeometry args={t} /></mesh>
);

/** Quarto: piso de tábuas largas, parede do fundo com rodapé, janela com lua e cortinas, cama à esquerda, quadro e prateleira à direita.
 *  Deixa livre a frente (|x| < 1,5 e z > -1). Parede em z = -2,4. */
const Quarto: React.FC<{ quadro: number }> = ({ quadro }) => {
  const tabuas = 25, larg = 0.4;
  // astros na janela: piscam devagar (só emissivo)
  const astro = (i: number) => 0.6 + 0.3 * Math.sin((quadro / 75) * TAU + i * 2.1);
  return (
    <group>
      {/* piso: tábuas de 40 cm em dois tons, de frente para trás */}
      {Array.from({ length: tabuas }, (_, i) => (
        <Caixa key={i} p={[(i - (tabuas - 1) / 2) * larg, PISO - 0.03, 0.1]} t={[larg, 0.06, 9]} cor={i % 2 ? C.piso1 : C.piso2} sombra={false} />
      ))}
      {/* parede do fundo e rodapé */}
      <Caixa p={[0, 1.6, -2.5]} t={[10, 3.4, 0.2]} cor={C.parede} />
      <Caixa p={[0, PISO + 0.06, -2.38]} t={[10, 0.12, 0.04]} cor={C.rodape} sombra={false} />

      {/* janela: céu, lua, astros, moldura em cruz, peitoril e cortinas */}
      <group position={[-1.7, 1.65, -2.4]}>
        <Caixa p={[0, 0, 0.01]} t={[1.1, 1.1, 0.02]} cor={C.vidro} brilho={0.35} sombra={false} />
        <mesh position={[-0.27, 0.27, 0.03]} rotation={[Math.PI / 2, 0, 0]} material={mat(C.luaDisco, 0.9)}><cylinderGeometry args={[0.13, 0.13, 0.02, 28]} /></mesh>
        {([[0.25, 0.32], [0.3, -0.22], [-0.25, -0.3]] as [number, number][]).map(([x, y], i) => (
          <mesh key={i} position={[x, y, 0.03]} rotation={[0, 0, Math.PI / 4]} material={mat(C.astro, astro(i))}><boxGeometry args={[0.08, 0.08, 0.02]} /></mesh>
        ))}
        <Caixa p={[0, 0.6, 0.05]} t={[1.3, 0.1, 0.1]} cor={C.janela} />
        <Caixa p={[0, -0.6, 0.05]} t={[1.3, 0.1, 0.1]} cor={C.janela} />
        <Caixa p={[-0.6, 0, 0.05]} t={[0.1, 1.1, 0.1]} cor={C.janela} />
        <Caixa p={[0.6, 0, 0.05]} t={[0.1, 1.1, 0.1]} cor={C.janela} />
        <Caixa p={[0, 0, 0.06]} t={[0.08, 1.1, 0.08]} cor={C.janela} />
        <Caixa p={[0, -0.69, 0.1]} t={[1.5, 0.08, 0.2]} cor={C.janela} />
        <Caixa p={[-0.86, 0.05, 0.14]} t={[0.34, 1.6, 0.08]} cor={C.cortina} />
        <Caixa p={[0.86, 0.05, 0.14]} t={[0.34, 1.6, 0.08]} cor={C.cortina} />
        <Caixa p={[0, 0.88, 0.2]} t={[2.2, 0.08, 0.08]} cor={C.metal} />
      </group>

      {/* cama de solteiro à esquerda, cabeceira na parede */}
      <group position={[-2.6, PISO, -1.4]}>
        <Caixa p={[0, 0.17, 0]} t={[1.1, 0.3, 1.9]} cor={C.cama} />
        <Caixa p={[0, 0.41, 0]} t={[1.02, 0.18, 1.84]} cor={C.colchao} />
        <Caixa p={[0, 0.44, 0.33]} t={[1.08, 0.2, 1.2]} cor={C.coberta} />
        <mesh position={[0, 0.56, -0.66]} scale={[0.36, 0.09, 0.2]} material={mat(C.travesseiro)} castShadow receiveShadow><sphereGeometry args={[1, 20, 12]} /></mesh>
        <Caixa p={[0, 0.5, -0.92]} t={[1.2, 1.0, 0.1]} cor={C.cama} />
      </group>

      {/* quadro na parede: sol e morro */}
      <group position={[1.7, 1.75, -2.4]}>
        <Caixa p={[0, 0, 0.02]} t={[0.8, 0.62, 0.04]} cor={C.moldura} />
        <Caixa p={[0, 0, 0.05]} t={[0.66, 0.48, 0.02]} cor={C.quadro} sombra={false} />
        <mesh position={[0.05, -0.24, 0.08]} rotation={[Math.PI / 2, 0, 0]} scale={[1, 1, 0.55]} material={mat(C.morro)}>
          <cylinderGeometry args={[0.26, 0.26, 0.02, 24, 1, false, Math.PI / 2, Math.PI]} />
        </mesh>
        <mesh position={[-0.18, 0.1, 0.08]} rotation={[Math.PI / 2, 0, 0]} material={mat('#fff3d0')}><cylinderGeometry args={[0.08, 0.08, 0.02, 20]} /></mesh>
      </group>
      {/* prateleira com livros */}
      <group position={[2.9, 1.25, -2.4]}>
        <Caixa p={[0, 0, 0.13]} t={[0.9, 0.06, 0.26]} cor={C.madeira} />
        {(['#c8504a', '#e2b04a', '#4f9a7a', '#5a6fb8'] as const).map((c, i) => (
          <Caixa key={c} p={[-0.3 + i * 0.12, 0.15 + (i % 2) * 0.02, 0.13]} t={[0.09, 0.24 + (i % 2) * 0.04, 0.2]} cor={c} />
        ))}
      </group>
    </group>
  );
};

/** Criado-mudo com abajur de mesa (cúpula acesa). Origem no chão, frente para +Z. Lâmpada a 0,98 m (luz de lado no rosto, não de baixo). */
const Abajur: React.FC<{ aceso: number }> = ({ aceso }) => (
  <group>
    {/* criado-mudo: corpo, tampo, gaveta e puxador */}
    <mesh position={[0, 0.25, 0]} material={mat(C.madeira)} castShadow receiveShadow><boxGeometry args={[0.46, 0.5, 0.4]} /></mesh>
    <mesh position={[0, 0.52, 0]} material={mat(C.madeiraEsc)} castShadow receiveShadow><boxGeometry args={[0.5, 0.04, 0.44]} /></mesh>
    <mesh position={[0, 0.33, 0.21]} material={mat(C.madeiraEsc)} receiveShadow><boxGeometry args={[0.38, 0.16, 0.02]} /></mesh>
    <mesh position={[0, 0.33, 0.235]} material={mat(C.metal)}><sphereGeometry args={[0.022, 10, 8]} /></mesh>
    {/* abajur: base, haste, lâmpada e cúpula (não projetam sombra, senão tapam a própria luz) */}
    <mesh position={[0, 0.565, 0]} material={mat(C.metal)} receiveShadow><cylinderGeometry args={[0.08, 0.1, 0.05, 20]} /></mesh>
    <mesh position={[0, 0.78, 0]} material={mat(C.metal)}><cylinderGeometry args={[0.014, 0.014, 0.4, 10]} /></mesh>
    <mesh position={[0, 0.98, 0]} material={mat(C.lampada, 1.5 * aceso)}><sphereGeometry args={[0.05, 14, 10]} /></mesh>
    <mesh position={[0, 1.04, 0]} material={mat(C.cupula, 0.25 + 0.7 * aceso)}>
      <cylinderGeometry args={[0.11, 0.19, 0.24, 24, 1, true]} />
    </mesh>
    {/* boca da cúpula mais acesa: a luz escapa por baixo */}
    <mesh position={[0, 0.925, 0]} rotation={[Math.PI / 2, 0, 0]} material={mat(C.lampada, 1.4 * aceso)}><torusGeometry args={[0.185, 0.012, 8, 28]} /></mesh>
    {/* brilho em volta da cúpula e poça de luz no tampo */}
    <group position={[0, 1.0, 0.05]}><Halo cor={C.quente} raio={0.2} forca={0.5 * aceso} z={0} /></group>
    <group position={[0, 0.545, 0]} rotation={[-Math.PI / 2, 0, 0]}><Halo cor={C.quente} raio={0.24} forca={0.5 * aceso} z={0} /></group>
  </group>
);

/** Celular de 0,24 m (maior que o real, para ler na escala do boneco): capa, tela acesa com "rabiscos" e um halo claro. */
const Celular: React.FC<{ aceso: number }> = ({ aceso }) => (
  <group>
    <mesh material={mat(C.capa)} castShadow><boxGeometry args={[0.13, 0.24, 0.018]} /></mesh>
    <mesh position={[0, 0.006, 0.0105]} material={mat(C.tela, 0.9 * aceso)}><boxGeometry args={[0.112, 0.2, 0.003]} /></mesh>
    {/* rabiscos de texto e bloco amarelo na tela */}
    {[0.065, 0.035, 0.005].map((y, i) => (
      <mesh key={y} position={[-0.01 + (i === 1 ? -0.01 : 0), y, 0.0125]} material={mat('#8a9ab8')}><boxGeometry args={[i === 1 ? 0.06 : 0.08, 0.014, 0.002]} /></mesh>
    ))}
    <mesh position={[0, -0.055, 0.0125]} material={mat('#f2c94c', 0.6 * aceso)}><boxGeometry args={[0.07, 0.04, 0.002]} /></mesh>
    {/* halo azul-branco pequeno (≤ 0,8× o aparelho) */}
    <Halo cor={C.telaHalo} raio={0.1} forca={0.55 * aceso} z={0.02} />
  </group>
);

export type PropsNoite = {
  quadro: number;
  /** Desenha o quarto (false quando o cenário do plano já é um quarto ou uma sala). */
  quarto?: boolean;
  /** Onde fica o criado-mudo com abajur (no chão); `null` = cena já tem o abajur, só a luz em `luzAbajur`. */
  abajur?: V3 | null;
  /** Luz do abajur quando `abajur` é null (posição da lâmpada). */
  luzAbajur?: V3;
  /** Centro do celular; padrão: na mão direita do boneco parado na origem. `null` = sem celular. */
  celular?: V3 | null;
  /** Desenha o aparelho (false quando o personagem já segura um). */
  mostrarCelular?: boolean;
  /** Tapete sob o personagem (`null` = sem). */
  tapete?: V3 | null;
  /** Quadros para anoitecer (0 = já começa de noite). */
  transicao?: number;
};

export const Noite: React.FC<PropsNoite> = ({
  quadro, quarto = true, abajur = [1.12, PISO, 0.15], luzAbajur, celular = [0.32, 0.64, 0.17], mostrarCelular = true,
  tapete = [-0.15, 0, 0.3], transicao = 20,
}) => {
  const k = transicao > 0 ? suave(quadro / transicao) : 1;
  useAnoitecer(k);
  // as luzes quentes acendem logo depois de escurecer; o abajur tem um vaivém leve (±3%, 3 s)
  const aceso = suave((quadro - transicao * 0.4) / Math.max(1, transicao * 0.6));
  const vaivem = 1 + 0.03 * Math.sin((quadro / 90) * TAU);

  const lampada: V3 | null = abajur ? [abajur[0], abajur[1] + 0.98, abajur[2]] : luzAbajur ?? null;
  // tela virada para cima e para a frente; a luz sai 7 cm à frente da tela
  const giroCel: V3 = [-0.5, -0.15, 0];
  const normal = new THREE.Vector3(0, 0, 1).applyEuler(new THREE.Euler(...giroCel));
  const luzCel: V3 | null = celular ? [celular[0] + normal.x * 0.07, celular[1] + normal.y * 0.07, celular[2] + normal.z * 0.07] : null;

  return (
    <group>
      {quarto && <Quarto quadro={quadro} />}
      {tapete && (
        <group position={tapete}>
          {/* miolo + 4 faixas de borda clara lado a lado, todos na mesma altura (sem camadas sobrepostas) */}
          <Caixa p={[0, PISO + 0.01, 0]} t={[2.2, 0.02, 1.6]} cor={C.tapete} sombra={false} />
          <Caixa p={[0, PISO + 0.01, 0.89]} t={[2.56, 0.02, 0.18]} cor={C.tapeteBorda} sombra={false} />
          <Caixa p={[0, PISO + 0.01, -0.89]} t={[2.56, 0.02, 0.18]} cor={C.tapeteBorda} sombra={false} />
          {/* laterais só ao lado do miolo (não sobrepõem as faixas da frente e de trás) */}
          <Caixa p={[1.19, PISO + 0.01, 0]} t={[0.18, 0.02, 1.6]} cor={C.tapeteBorda} sombra={false} />
          <Caixa p={[-1.19, PISO + 0.01, 0]} t={[0.18, 0.02, 1.6]} cor={C.tapeteBorda} sombra={false} />
        </group>
      )}
      {lampada && (
        <pointLight userData={{ [NOITE]: true }} position={lampada} color={C.quente} intensity={3.4 * aceso * vaivem} distance={7} decay={2}
          castShadow shadow-mapSize={[1024, 1024]} shadow-bias={-0.002} shadow-radius={5} shadow-camera-near={0.12} />
      )}
      {abajur && <group position={abajur}><Abajur aceso={aceso} /></group>}
      {celular && luzCel && (
        <group>
          <pointLight userData={{ [NOITE]: true }} position={luzCel} color={C.telaLuz} intensity={1.1 * aceso} distance={1.6} decay={2} />
          {mostrarCelular && <group position={celular} rotation={giroCel}><Celular aceso={aceso} /></group>}
        </group>
      )}
      {/* poça de luz quente no chão em volta do criado-mudo */}
      {abajur && (
        <group position={[abajur[0], PISO + 0.03, abajur[2] + 0.1]} rotation={[-Math.PI / 2, 0, 0]}><Halo cor={C.quente} raio={0.7} forca={0.3 * aceso} z={0} /></group>
      )}
      {/* luar entrando pela janela: azul, sem sombra, para a cama e o canto esquerdo não sumirem */}
      {quarto && <pointLight userData={{ [NOITE]: true }} position={[-1.9, 1.5, -1.3]} color={C.luar} intensity={1.6 * k} distance={4} decay={2} />}
      {/* preenchimento azul baixo e frontal: tênis e pernas não somem no escuro */}
      <pointLight userData={{ [NOITE]: true }} position={[0, 0.5, 2.6]} color={C.preenche} intensity={1.4 * k} distance={5} decay={2} />
    </group>
  );
};
