// Objetos das demos do lote (tamanho real, só primitivas, cores chapadas, cache de material por cor).
import * as THREE from 'three';
import React from 'react';

const cache = new Map<string, THREE.MeshStandardMaterial>();
export const mat = (cor: string) => {
  let m = cache.get(cor);
  if (!m) { m = new THREE.MeshStandardMaterial({ color: cor, roughness: 0.85 }); cache.set(cor, m); }
  return m;
};
type V3 = [number, number, number];
const Caixa: React.FC<{ p: V3; t: V3; cor: string; r?: V3 }> = ({ p, t, cor, r = [0, 0, 0] }) => (
  <mesh position={p} rotation={r} material={mat(cor)} castShadow receiveShadow><boxGeometry args={t} /></mesh>
);
/** Cilindro ao longo de Z, de z0 a z1 (raio r0 em z0 e r1 em z1). */
const TuboZ: React.FC<{ z0: number; z1: number; r0: number; r1?: number; cor: string; seg?: number }> = ({ z0, z1, r0, r1 = r0, cor, seg = 16 }) => (
  <mesh position={[0, 0, (z0 + z1) / 2]} rotation={[Math.PI / 2, 0, 0]} material={mat(cor)} castShadow>
    <cylinderGeometry args={[r1, r0, Math.abs(z1 - z0), seg]} />
  </mesh>
);

/** Põe os filhos com a origem em `p` e o eixo +Z apontando para `dir`. */
export const Apontado: React.FC<{ p: THREE.Vector3; dir: THREE.Vector3; children: React.ReactNode }> = ({ p, dir, children }) => {
  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 0, 1), dir.clone().normalize());
  return <group position={p} quaternion={q}>{children}</group>;
};
/** Põe os filhos numa matriz pronta (ex.: o tronco de um boneco). */
export const NaMatriz: React.FC<{ m: THREE.Matrix4; children: React.ReactNode }> = ({ m, children }) => {
  const p = new THREE.Vector3(), q = new THREE.Quaternion(), s = new THREE.Vector3();
  m.decompose(p, q, s);
  return <group position={p} quaternion={q}>{children}</group>;
};
/** Cilindro de a até b (alça esticada). */
export const Barra: React.FC<{ a: THREE.Vector3; b: THREE.Vector3; r: number; cor: string }> = ({ a, b, r, cor }) => {
  const d = new THREE.Vector3().subVectors(b, a);
  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), d.clone().normalize());
  return (
    <mesh position={a.clone().add(b).multiplyScalar(0.5)} quaternion={q} material={mat(cor)} castShadow>
      <cylinderGeometry args={[r, r, d.length(), 10]} />
    </mesh>
  );
};

// ── Mochila escolar (30 × 38 × 16 cm). Origem no meio das costas de quem usa; o corpo vai para −Z ──
const MO = { corpo: '#2f9fd0', escuro: '#1f6f96', ziper: '#f2c94c', alca: '#24354f' };
/** Alça de mão no topo da mochila, no sistema da mochila (é por ela que se puxa). */
export const ALCA_MOCHILA = new THREE.Vector3(0, 0.235, -0.08);
export const Mochila: React.FC = () => (
  <group>
    {/* corpo com topo redondo */}
    <Caixa p={[0, -0.02, -0.08]} t={[0.3, 0.3, 0.16]} cor={MO.corpo} />
    <mesh position={[0, 0.13, -0.08]} rotation={[0, 0, Math.PI / 2]} scale={[1, 1, 1.14]} material={mat(MO.corpo)} castShadow receiveShadow>
      <cylinderGeometry args={[0.07, 0.07, 0.3, 20]} />
    </mesh>
    {/* bolso de fora com zíper e puxador */}
    <Caixa p={[0, -0.08, -0.18]} t={[0.22, 0.15, 0.05]} cor={MO.escuro} />
    <Caixa p={[0, -0.003, -0.205]} t={[0.2, 0.014, 0.006]} cor={MO.ziper} />
    <Caixa p={[0.07, -0.02, -0.21]} t={[0.016, 0.034, 0.008]} cor={MO.ziper} />
    {/* alça de mão no topo */}
    <mesh position={[0, 0.2, -0.08]} material={mat(MO.alca)} castShadow>
      <torusGeometry args={[0.04, 0.012, 8, 16, Math.PI]} />
    </mesh>
    {/* alças dos ombros: passam por cima e descem pela frente do peito */}
    {[-1, 1].map((l) => (
      <group key={l}>
        <Caixa p={[0.11 * l, 0.2, 0.09]} t={[0.05, 0.02, 0.2]} cor={MO.alca} />
        <Caixa p={[0.11 * l, 0.06, 0.205]} t={[0.05, 0.27, 0.02]} r={[-0.12, 0, 0]} cor={MO.alca} />
      </group>
    ))}
  </group>
);

// ── Marcador vermelho (15 cm). Origem no centro da mão; a ponta aponta para +Z, a `PONTA` (13 cm) ──
const MK = { corpo: '#d7263d', escuro: '#8f1424', rotulo: '#f4f1ea' };
export const Marcador: React.FC = () => (
  <group>
    <TuboZ z0={-0.06} z1={-0.02} r0={0.016} cor={MK.escuro} />
    <TuboZ z0={-0.02} z1={0.09} r0={0.015} cor={MK.corpo} />
    <TuboZ z0={0.03} z1={0.06} r0={0.0155} cor={MK.rotulo} />
    <TuboZ z0={0.09} z1={0.11} r0={0.015} r1={0.008} cor={MK.escuro} />
    <TuboZ z0={0.11} z1={0.13} r0={0.006} r1={0.003} cor={MK.corpo} />
  </group>
);

// ── Caneta grossa (17 cm, 2,4 cm de diâmetro), azul-escura com tampa branca: contrasta com as camisas.
// Origem no meio dela; a ponta (oferecida) aponta para +Z, a `PONTA_CANETA` ──
const CN = { corpo: '#1d3f86', tampa: '#f4f1ea', metal: '#c9ced6', ponta: '#111827' };
export const PONTA_CANETA = 0.085;
export const Caneta: React.FC = () => (
  <group>
    <TuboZ z0={-0.085} z1={-0.03} r0={0.013} cor={CN.tampa} seg={12} />
    <Caixa p={[0, 0.016, -0.06]} t={[0.007, 0.006, 0.045]} cor={CN.tampa} />
    <TuboZ z0={-0.03} z1={0.05} r0={0.012} cor={CN.corpo} seg={6} />
    <TuboZ z0={0.05} z1={0.072} r0={0.012} r1={0.005} cor={CN.metal} />
    <TuboZ z0={0.072} z1={PONTA_CANETA} r0={0.004} r1={0.0015} cor={CN.ponta} />
  </group>
);

// ── Placa de metas num pé (o alvo do X). Origem no centro da face (z = 0), face para +Z ──
// 3 colunas × 2 linhas de quadradinhos (os dias); os dois primeiros já têm X. O X novo vai no 3º, (col 2, linha 0).
const PL = { moldura: '#e9e4d8', face: '#ffffff', faixa: '#3a7bd5', borda: '#8d96a8', pe: '#5b6375', x: '#d7263d' };
const CEL = 0.17;
/** Centro do quadradinho (coluna 0..2, linha 0..1) em relação ao centro da face. */
export const centroCelula = (col: number, lin: number): [number, number] => [(col - 1) * CEL, 0.03 - lin * CEL];
const XFeito: React.FC<{ p: [number, number] }> = ({ p }) => (
  <group position={[p[0], p[1], 0.006]}>
    {[1, -1].map((s) => <Caixa key={s} p={[0, 0, 0]} t={[0.13, 0.02, 0.003]} r={[0, 0, (s * Math.PI) / 4]} cor={PL.x} />)}
  </group>
);
export const Placa: React.FC<{ alturaCentro: number }> = ({ alturaCentro }) => (
  <group>
    <group position={[0, alturaCentro, 0]}>
      <Caixa p={[0, 0, -0.025]} t={[0.62, 0.5, 0.04]} cor={PL.moldura} />
      <Caixa p={[0, 0, -0.002]} t={[0.56, 0.44, 0.006]} cor={PL.face} />
      {/* faixa do título com dois rabiscos */}
      <Caixa p={[0, 0.18, 0.002]} t={[0.56, 0.08, 0.004]} cor={PL.faixa} />
      {[[-0.1, 0.16], [0.1, 0.1]].map(([x, l]) => <Caixa key={x} p={[x, 0.18, 0.005]} t={[l, 0.022, 0.003]} cor={PL.face} />)}
      {/* quadradinhos dos dias (contorno de 1,2 cm) */}
      {[0, 1, 2].flatMap((c) => [0, 1].map((l) => {
        const [x, y] = centroCelula(c, l);
        return (
          <group key={`${c}${l}`} position={[x, y, 0.003]}>
            {[-1, 1].map((s) => <Caixa key={`h${s}`} p={[0, s * 0.065, 0]} t={[0.142, 0.012, 0.003]} cor={PL.borda} />)}
            {[-1, 1].map((s) => <Caixa key={`v${s}`} p={[s * 0.065, 0, 0]} t={[0.012, 0.142, 0.003]} cor={PL.borda} />)}
          </group>
        );
      }))}
      <XFeito p={centroCelula(0, 0)} />
      <XFeito p={centroCelula(1, 0)} />
    </group>
    {/* pé: haste, base em cruz */}
    <mesh position={[0, (alturaCentro - 0.25) / 2, -0.05]} material={mat(PL.pe)} castShadow receiveShadow>
      <cylinderGeometry args={[0.022, 0.022, alturaCentro - 0.25, 12]} />
    </mesh>
    <Caixa p={[0, 0.02, -0.05]} t={[0.5, 0.04, 0.06]} cor={PL.pe} />
    <Caixa p={[0, 0.02, -0.05]} t={[0.06, 0.04, 0.4]} cor={PL.pe} />
  </group>
);

/** Traço de marcador entre dois pontos do plano XY da placa (2,2 cm de largura). */
export const Traco: React.FC<{ a: THREE.Vector3; b: THREE.Vector3 }> = ({ a, b }) => {
  const d = new THREE.Vector3().subVectors(b, a);
  const L = d.length();
  if (L < 0.003) return null;
  return (
    <group position={a.clone().add(b).multiplyScalar(0.5)} rotation={[0, 0, Math.atan2(d.y, d.x)]}>
      <mesh material={mat(MK.corpo)}><boxGeometry args={[L, 0.022, 0.003]} /></mesh>
    </group>
  );
};
