// Primitivas em metros. Frente em +Z; materiais compartilhados por cor.
import React, { useLayoutEffect, useMemo, useRef } from 'react';
import * as THREE from 'three';

export type V3 = [number, number, number];
export type Retangulo = { x: number; y: number; l: number; a: number; cor: string };
const cache = new Map<string, THREE.MeshStandardMaterial>();
export const mat = (cor: string) => {
  let material = cache.get(cor);
  if (!material) {
    material = new THREE.MeshStandardMaterial({ color: cor, roughness: 0.85 });
    cache.set(cor, material);
  }
  return material;
};

export const Caixa: React.FC<{ p: V3; t: V3; cor: string; r?: V3; sombra?: boolean }> = ({ p, t, cor, r, sombra = true }) => (
  <mesh position={p} rotation={r} material={mat(cor)} castShadow={sombra} receiveShadow={sombra}>
    <boxGeometry args={t} />
  </mesh>
);

export const RetanguloArredondado: React.FC<{
  l: number; a: number; e: number; raio: number; p: V3; cor: string;
}> = ({ l, a, e, raio, p, cor }) => (
  <group position={p}>
    <Caixa p={[0, 0, 0]} t={[l - 2 * raio, a, e]} cor={cor} />
    <Caixa p={[0, 0, 0]} t={[l, a - 2 * raio, e]} cor={cor} />
    {([-1, 1] as const).flatMap((x) => ([-1, 1] as const).map((y) => (
      <mesh key={`${x}/${y}`} position={[x * (l / 2 - raio), y * (a / 2 - raio), 0]}
        rotation={[Math.PI / 2, 0, 0]} material={mat(cor)} castShadow receiveShadow>
        <cylinderGeometry args={[raio, raio, e, 12]} />
      </mesh>
    )))}
  </group>
);

// a: topo, b/c: direita, d: base, e/f: esquerda, g: meio.
export const SEGMENTOS: Record<string, string> = {
  '0': 'abcdef', '1': 'bc', '2': 'abdeg', '3': 'abcdg', '4': 'bcfg',
  '5': 'acdfg', '6': 'acdefg', '7': 'abc', '8': 'abcdefg', '9': 'abcdfg',
};

/** Dígitos vistos de +Z; o 1 é uma haste contínua na direita. */
export function numero(valor: string, x: number, y: number, altura: number, traco: number, cor: string): Retangulo[] {
  const largura = altura * 0.56, passo = largura + traco * 1.25;
  const larguras = [...valor].map((c) => c === '.' ? traco : largura);
  const total = larguras.reduce((s, l) => s + l, 0) + (valor.length - 1) * (passo - largura);
  let cursor = x - total / 2;
  return [...valor].flatMap((c, i) => {
    const cx = cursor + larguras[i] / 2;
    cursor += larguras[i] + passo - largura;
    if (c === '.') return [{ x: cx, y: y - altura / 2 + traco / 2, l: traco, a: traco, cor }];
    const vx = (largura - traco) / 2, vy = (altura - traco) / 4;
    // Traços se encontram sem vãos. Laterais contínuas evitam um "1" pontilhado.
    const horizontal = largura;
    const vertical = (altura + traco) / 2;
    const segmentos: Record<string, [number, number, number, number]> = {
      a: [0, 2 * vy, horizontal, traco], b: [vx, vy, traco, vertical],
      c: [vx, -vy, traco, vertical], d: [0, -2 * vy, horizontal, traco],
      e: [-vx, -vy, traco, vertical], f: [-vx, vy, traco, vertical],
      g: [0, 0, horizontal, traco],
    };
    let ativos = SEGMENTOS[c];
    const unidos: Retangulo[] = [];
    for (const [cima, baixo, dx] of [['b', 'c', vx], ['f', 'e', -vx]] as const) {
      if (ativos.includes(cima) && ativos.includes(baixo)) {
        unidos.push({ x: cx + dx, y, l: traco, a: altura, cor });
        ativos = ativos.replace(cima, '').replace(baixo, '');
      }
    }
    return [...unidos, ...[...ativos].map((s) => {
      const [dx, dy, l, a] = segmentos[s];
      return { x: cx + dx, y: y + dy, l, a, cor };
    })];
  });
}

/** Caixas instanciadas por cor; os papéis também têm tinta nas próprias caixas. */
export const Tracos: React.FC<{ retangulos: Retangulo[]; z: number; espessura: number; borda?: string; sombra?: boolean }> = ({ retangulos, z, espessura, borda, sombra = false }) => {
  const ref = useRef<THREE.InstancedMesh>(null);
  useLayoutEffect(() => {
    const malha = ref.current;
    if (!malha) return;
    const matriz = new THREE.Matrix4(), giro = new THREE.Quaternion();
    retangulos.forEach((r, i) => {
      matriz.compose(new THREE.Vector3(r.x, r.y, z), giro, new THREE.Vector3(r.l, r.a, espessura));
      malha.setMatrixAt(i, matriz);
    });
    malha.instanceMatrix.needsUpdate = true;
    malha.computeBoundingSphere();
    malha.computeBoundingBox();
  }, [retangulos, z, espessura]);
  const frente = mat(retangulos[0].cor);
  const lateral = borda ? mat(borda) : frente;
  return (
    <instancedMesh ref={ref} args={[undefined, undefined, retangulos.length]}
      material={borda ? [lateral, lateral, lateral, lateral, frente, lateral] : frente} castShadow={sombra} receiveShadow={sombra}>
      <boxGeometry args={[1, 1, 1]} />
    </instancedMesh>
  );
};

/** Recorta a tinta no papel: caixas vizinhas, nunca camadas sobrepostas. */
export function recortarPapel(l: number, a: number, cor: string, tintas: Retangulo[]): Retangulo[] {
  let partes: Retangulo[] = [{ x: 0, y: a / 2, l, a, cor }];
  const tolerancia = 1e-10;
  for (const tinta of tintas) {
    const x0 = Math.max(-l / 2, tinta.x - tinta.l / 2), x1 = Math.min(l / 2, tinta.x + tinta.l / 2);
    const y0 = Math.max(0, tinta.y - tinta.a / 2), y1 = Math.min(a, tinta.y + tinta.a / 2);
    if (x1 - x0 <= tolerancia || y1 - y0 <= tolerancia) continue;
    const novas: Retangulo[] = [];
    const adicionar = (esq: number, dir: number, baixo: number, cima: number, c: string) => {
      if (dir - esq > tolerancia && cima - baixo > tolerancia)
        novas.push({ x: (esq + dir) / 2, y: (baixo + cima) / 2, l: dir - esq, a: cima - baixo, cor: c });
    };
    for (const p of partes) {
      const esq = p.x - p.l / 2, dir = p.x + p.l / 2, baixo = p.y - p.a / 2, cima = p.y + p.a / 2;
      const ix0 = Math.max(esq, x0), ix1 = Math.min(dir, x1), iy0 = Math.max(baixo, y0), iy1 = Math.min(cima, y1);
      if (ix1 - ix0 <= tolerancia || iy1 - iy0 <= tolerancia) { novas.push(p); continue; }
      adicionar(esq, ix0, baixo, cima, p.cor);
      adicionar(ix1, dir, baixo, cima, p.cor);
      adicionar(ix0, ix1, baixo, iy0, p.cor);
      adicionar(ix0, ix1, iy1, cima, p.cor);
    }
    adicionar(x0, x1, y0, y1, tinta.cor);
    partes = novas;
  }
  return partes;
}

export const Papel: React.FC<{ l: number; a: number; e: number; cor: string; borda: string; tintas: Retangulo[] }> = ({ l, a, e, cor, borda, tintas }) => {
  const grupos = useMemo(() => {
    const cores = new Map<string, Retangulo[]>();
    for (const r of recortarPapel(l, a, cor, tintas)) {
      if (!cores.has(r.cor)) cores.set(r.cor, []);
      cores.get(r.cor)!.push(r);
    }
    return [...cores.entries()];
  }, [l, a, cor, tintas]);
  return (
    <group>
      {/* Verso contínuo projeta a sombra; a impressão não recebe sombras internas. */}
      <mesh position={[0, a / 2, -e / 4]} material={mat(borda)} castShadow receiveShadow>
        <boxGeometry args={[l, a, e / 2]} />
      </mesh>
      {grupos.map(([c, retangulos]) => <Tracos key={c} retangulos={retangulos} z={e / 4} espessura={e / 2} borda={borda} />)}
    </group>
  );
};
