// Adereços das ações do lote r06: bola de basquete, urna de sorteio com mesinha, papelzinho, pacote de figurinhas.
// <ObjetosDaAcao> vai DENTRO do mesmo grupo do <Boneco> (mesma posição e giro): tudo no espaço do boneco,
// nos mesmos pontos que a pose usa para as mãos. Só primitivas, cores chapadas, cache de material por cor.
import * as THREE from 'three';
import React from 'react';
import {
  BOLA_R, BOLA_XZ, alturaBola, tempoQuique, URNA, maoPapel, PACOTE, rasgo, ciclo, type V3,
} from './acoes';

const cache = new Map<string, THREE.MeshStandardMaterial>();
const mat = (cor: string, opaco = 1) => {
  const k = cor + opaco;
  let m = cache.get(k);
  if (!m) {
    m = new THREE.MeshStandardMaterial({ color: cor, roughness: 0.85, transparent: opaco < 1, opacity: opaco, depthWrite: opaco === 1 });
    cache.set(k, m);
  }
  return m;
};
const R = THREE.MathUtils.degToRad;
const Caixa: React.FC<{ p: V3; t: V3; cor: string; r?: V3; sombra?: boolean }> = ({ p, t, cor, r = [0, 0, 0], sombra = true }) => (
  <mesh position={p} rotation={r} material={mat(cor)} castShadow={sombra} receiveShadow><boxGeometry args={t} /></mesh>
);

// ── bola ─────────────────────────────────────────────────────────────────
/** Bola de basquete (24 cm), origem no centro: laranja com quatro gomos escuros. */
export const Bola: React.FC = () => (
  <group>
    <mesh material={mat('#f07a26')} castShadow receiveShadow><sphereGeometry args={[BOLA_R, 32, 16]} /></mesh>
    {[[0, 0, 0], [0, Math.PI / 2, 0], [Math.PI / 2, 0, 0]].map((r, i) => (
      <mesh key={i} rotation={r as V3} material={mat('#3a1d0e')}><torusGeometry args={[BOLA_R + 0.001, 0.0045, 6, 40]} /></mesh>
    ))}
  </group>
);

/** Sombra de contato: disco escuro no chão, maior e mais forte quanto mais perto a bola está. */
const SombraContato: React.FC<{ p: V3; altura: number }> = ({ p, altura }) => {
  const perto = 1 - Math.min(1, altura / 0.6);
  const s = 0.7 + 0.5 * perto;
  return (
    <mesh position={[p[0], 0.028, p[2]]} rotation={[-Math.PI / 2, 0, 0]} scale={[s, s, 1]} material={mat('#163a63', 0.35 + 0.35 * perto)}>
      <circleGeometry args={[BOLA_R, 24]} />
    </mesh>
  );
};

/** Linhas de movimento: dois traços brancos dos lados da bola enquanto ela desce rápido; um "estalo" no chão na batida. */
const MarcasQuique: React.FC<{ q: number; p: V3 }> = ({ q, p }) => {
  const t = tempoQuique(q);
  const desce = t > 0.15 && t < 0.5 ? Math.sin(Math.PI * (t - 0.15) / 0.35) : 0;
  const batida = t > 0.45 && t < 0.62 ? Math.sin(Math.PI * (t - 0.45) / 0.17) : 0;
  return (
    <group>
      {desce > 0.05 && [-1, 1].map((l) => (
        <mesh key={l} position={[p[0] + (BOLA_R + 0.04) * l, p[1] + 0.06, p[2] + 0.03]} material={mat('#ffffff')}>
          <capsuleGeometry args={[0.011, 0.12 * desce, 4, 8]} />
        </mesh>
      ))}
      {batida > 0.05 && [-1, -0.35, 0.35, 1].map((k) => (
        <mesh key={k} position={[p[0] + 0.2 * k, 0.05 + 0.04 * (1 - Math.abs(k)), p[2] + 0.05]} rotation={[0, 0, R(-35 * k)]} scale={[1, batida, 1]} material={mat('#ffffff')}>
          <capsuleGeometry args={[0.01, 0.07, 4, 8]} />
        </mesh>
      ))}
    </group>
  );
};

// ── urna e papel ─────────────────────────────────────────────────────────
/** Mesinha de 62 cm (tampo 42 × 42 cm), origem no centro do chão. */
const Mesinha: React.FC<{ altura: number }> = ({ altura }) => (
  <group>
    <Caixa p={[0, altura - 0.02, 0]} t={[0.42, 0.04, 0.42]} cor="#c98f55" />
    {[[-1, -1], [-1, 1], [1, -1], [1, 1]].map(([a, b], i) => (
      <Caixa key={i} p={[0.17 * a, (altura - 0.04) / 2, 0.17 * b]} t={[0.04, altura - 0.04, 0.04]} cor="#a8703d" />
    ))}
  </group>
);
/** "?" de traços grossos (frente para +Z), com ~16 cm de altura. */
const Interrogacao: React.FC<{ cor: string }> = ({ cor }) => (
  <group>
    <Caixa p={[0, 0.07, 0]} t={[0.08, 0.025, 0.008]} cor={cor} sombra={false} />
    <Caixa p={[0.04, 0.045, 0]} t={[0.025, 0.07, 0.008]} cor={cor} sombra={false} />
    <Caixa p={[0.015, 0.012, 0]} t={[0.06, 0.025, 0.008]} cor={cor} sombra={false} />
    <Caixa p={[-0.004, -0.02, 0]} t={[0.025, 0.05, 0.008]} cor={cor} sombra={false} />
    <Caixa p={[-0.004, -0.072, 0]} t={[0.028, 0.028, 0.008]} cor={cor} sombra={false} />
  </group>
);
/** Urna de sorteio de 32 cm: caixa roxa de bordas claras, boca redonda no tampo e "?" amarelo na frente.
 *  Origem no centro da base. */
export const Urna: React.FC<{ lado: number }> = ({ lado }) => {
  const m = lado / 2;
  return (
    <group>
      <Caixa p={[0, m, 0]} t={[lado, lado, lado]} cor="#7b4fc9" />
      {/* frisos nas arestas de cima */}
      {[[0, m - 0.002], [0, -m + 0.002]].map(([x, z], i) => <Caixa key={i} p={[x, lado - 0.01, z]} t={[lado + 0.016, 0.024, 0.024]} cor="#f2e6ff" />)}
      {[-1, 1].map((l) => <Caixa key={l} p={[l * (m - 0.002), lado - 0.01, 0]} t={[0.024, 0.024, lado + 0.016]} cor="#f2e6ff" />)}
      {/* boca: aro amarelo e fundo escuro */}
      <mesh position={[0, lado + 0.002, 0]} material={mat('#24133f')}><cylinderGeometry args={[0.095, 0.095, 0.006, 28]} /></mesh>
      <mesh position={[0, lado + 0.006, 0]} rotation={[Math.PI / 2, 0, 0]} material={mat('#f2c94c')} castShadow><torusGeometry args={[0.1, 0.014, 8, 32]} /></mesh>
      <group position={[0, m, m + 0.005]}><Interrogacao cor="#f2c94c" /></group>
      {/* papeizinhos caídos no tampo */}
      <Caixa p={[0.11, lado + 0.003, 0.1]} t={[0.05, 0.004, 0.035]} cor="#ffffff" r={[0, R(25), 0]} />
      <Caixa p={[-0.12, lado + 0.003, -0.09]} t={[0.045, 0.004, 0.03]} cor="#fff3b0" r={[0, R(-40), 0]} />
    </group>
  );
};
/** Algarismo "7" de traços grossos (frente para +Z), ~5 cm. */
const Sete: React.FC = () => (
  <group>
    <Caixa p={[0, 0.022, 0]} t={[0.034, 0.009, 0.003]} cor="#d93a3a" sombra={false} />
    <Caixa p={[0.006, -0.004, 0]} t={[0.009, 0.05, 0.003]} cor="#d93a3a" r={[0, 0, R(-20)]} sombra={false} />
  </group>
);
/** Papelzinho sorteado, aberto e um pouco dobrado no meio (14 × 10 cm na escala do boneco), com um "7" e rabiscos.
 *  Origem na borda de baixo (onde os dedos seguram), frente para +Z. */
export const Papel: React.FC = () => (
  <group>
    {[-1, 1].map((l) => (
      <group key={l} rotation={[0, R(-12 * l), 0]}>
        <Caixa p={[0.035 * l, 0.05, 0]} t={[0.07, 0.1, 0.004]} cor="#ffffff" />
      </group>
    ))}
    <group position={[-0.03, 0.055, 0.008]}><Sete /></group>
    {[0, 1, 2].map((i) => <Caixa key={i} p={[0.035, 0.07 - i * 0.02, 0.012]} t={[0.04 - i * 0.008, 0.006, 0.002]} cor="#5a6b85" sombra={false} />)}
  </group>
);

// ── pacote ───────────────────────────────────────────────────────────────
/** Estrela de 6 pontas: dois prismas triangulares (frente para +Z). */
const Estrela: React.FC<{ r: number; cor: string }> = ({ r, cor }) => (
  <group rotation={[Math.PI / 2, 0, 0]}>
    {[0, Math.PI].map((a) => (
      <mesh key={a} rotation={[0, a + Math.PI / 2, 0]} material={mat(cor)}><cylinderGeometry args={[r, r, 0.006, 3]} /></mesh>
    ))}
  </group>
);
/** Serrilha da solda (dentinhos em losango), largura `w`, centrada na origem. */
const Serrilha: React.FC<{ w: number; cor: string }> = ({ w, cor }) => {
  const n = Math.round(w / 0.02);
  return <>{Array.from({ length: n }, (_, i) => (
    <Caixa key={i} p={[-w / 2 + 0.01 + i * 0.02, 0, 0]} t={[0.014, 0.014, 0.012]} r={[0, 0, Math.PI / 4]} cor={cor} sombra={false} />
  ))}</>;
};
/** Metade do pacote de figurinhas (lado 1 = D). Origem no pivô (meio da borda de baixo). */
const MeioPacote: React.FC<{ lado: 1 | -1; aberto: number }> = ({ lado, aberto }) => {
  const { larg, alt, prof } = PACOTE, w = larg / 2, cx = (lado * w) / 2;
  return (
    <group>
      <Caixa p={[cx, alt / 2, 0]} t={[w, alt - 0.03, prof]} cor="#2fa3d9" />
      {/* faixa amarela e estrela partida ao meio (cada metade leva a sua) */}
      <Caixa p={[cx, alt * 0.3, prof / 2 + 0.004]} t={[w, 0.05, 0.004]} cor="#f2c94c" sombra={false} />
      <group position={[lado * 0.035, alt * 0.62, prof / 2 + 0.006]}><Estrela r={0.04} cor="#ffffff" /></group>
      {/* soldas de cima e de baixo, mais finas que o corpo */}
      <Caixa p={[cx, alt - 0.012, 0]} t={[w, 0.03, 0.014]} cor="#1f7fb0" />
      <Caixa p={[cx, 0.012, 0]} t={[w, 0.03, 0.014]} cor="#1f7fb0" />
      <group position={[cx, -0.002, 0]}><Serrilha w={w} cor="#1f7fb0" /></group>
      <group position={[cx, alt + 0.002, 0]}><Serrilha w={w} cor="#1f7fb0" /></group>
      {/* borda rasgada: branca, em zigue-zague, na beirada de dentro, de cima até onde o rasgo chegou */}
      {aberto > 0.05 && Array.from({ length: 5 }, (_, i) => (
        <Caixa key={i} p={[0.004 * lado + (i % 2) * 0.008 * lado, alt - 0.02 - i * 0.028 * aberto, 0]} t={[0.014, 0.03 * aberto, prof + 0.006]} cor="#f4f4f4" sombra={false} />
      ))}
    </group>
  );
};
/** Pacote de figurinhas (24 × 30 cm) que rasga de cima para baixo: `r` 0 fechado, 1 aberto. Origem no pivô. */
export const Pacote: React.FC<{ r: number }> = ({ r }) => (
  <group>
    {([-1, 1] as const).map((l) => (
      <group key={l} position={[0, 0, 0.02 * l * r]} rotation={[0, 0, -l * R(PACOTE.giro) * r]}><MeioPacote lado={l} aberto={r} /></group>
    ))}
    {/* figurinhas aparecendo pela fenda */}
    {r > 0.2 && ['#f26b3a', '#ffffff', '#8e5bd6'].map((c, i) => (
      <Caixa key={c} p={[(i - 1) * 0.012, PACOTE.alt - 0.07 + 0.03 * r - i * 0.012, (i - 1) * 0.01]} t={[0.05, 0.07, 0.006]} r={[0, 0, R((i - 1) * 8)]} cor={c} />
    ))}
  </group>
);
/** Traços de força: saem da ponta do rasgo durante o puxão. */
const MarcasRasgo: React.FC<{ q: number }> = ({ q }) => {
  const f = ciclo(q - 60, 48);
  const k = f > 6 && f < 40 ? Math.sin(Math.PI * (f - 6) / 34) : 0;
  if (k < 0.05) return null;
  const [px, py, pz] = PACOTE.pivo;
  return (
    <group position={[px, py + PACOTE.alt + 0.05, pz + PACOTE.prof]}>
      {[-1, 0, 1].map((i) => (
        <mesh key={i} position={[0.045 * i, 0.03 + 0.03 * k - 0.012 * Math.abs(i), 0]} rotation={[0, 0, R(-28 * i)]} scale={[1, k, 1]} material={mat('#ffffff')}>
          <capsuleGeometry args={[0.009, 0.06, 4, 8]} />
        </mesh>
      ))}
    </group>
  );
};

// ── montagem por ação ─────────────────────────────────────────────────────
/** Objetos da ação `nome` no quadro `quadro`, no espaço do boneco (ponha junto do <Boneco>).
 *  `pele` desenha o polegar que prende o papel. */
export const ObjetosDaAcao: React.FC<{ nome: string; quadro: number; pele?: string }> = ({ nome, quadro, pele = '#e9b48a' }) => {
  if (nome === 'quicarBola') {
    const p: V3 = [BOLA_XZ[0], alturaBola(quadro), BOLA_XZ[1]];
    return (
      <group>
        <group position={p} rotation={[quadro * 0.35, 0, R(20)]}><Bola /></group>
        <SombraContato p={p} altura={p[1] - BOLA_R} />
        <MarcasQuique q={quadro} p={p} />
      </group>
    );
  }
  if (nome === 'sortear') {
    const [x, , z] = URNA.centro;
    const m = maoPapel(quadro);
    return (
      <group>
        <group position={[x, 0, z]}><Mesinha altura={URNA.mesa} /></group>
        <group position={[x, URNA.mesa, z]}><Urna lado={URNA.lado} /></group>
        {/* papel saindo de cima da mão, virado para a câmera, com o polegar na frente */}
        <group position={[m[0] - 0.01, m[1] + 0.04, m[2] + 0.03]} rotation={[R(-8), R(-14), R(-6)]} scale={1.4}>
          <Papel />
          <mesh position={[-0.01, 0.012, 0.022]} rotation={[0, 0, R(-20)]} material={mat(pele)} castShadow>
            <capsuleGeometry args={[0.02, 0.035, 4, 10]} />
          </mesh>
        </group>
      </group>
    );
  }
  if (nome === 'abrirPacote') {
    return (
      <group>
        <group position={PACOTE.pivo}><Pacote r={rasgo(quadro)} /></group>
        <MarcasRasgo q={quadro} />
      </group>
    );
  }
  return null;
};
