// Objeto: smartphone em tamanho real (7,5 x 15,5 x 0,8 cm) dentro de uma capinha. Origem no centro, tela para +Z.
// Cantos arredondados = 2 caixas em cruz + 4 cilindros nos cantos (só primitivas).
import * as THREE from 'three';
import React from 'react';
import { mat } from './base';

const C = {
  capa: '#22b29a', capaEscura: '#1a8f7c', vidro: '#0b0d12', tela: '#eef3fb', barra: '#d5e0f2',
  widget: '#7fb0ff', sol: '#ffd23f', marca: '#2a3242', lente: '#05070a', anel: '#9aa3ad', flash: '#fff3c4',
};
const ICONES = ['#ff5a5f', '#ffb400', '#2ecc71', '#4f7cff'];

const telaMat = (cor: string) => mat(cor, { brilho: 0.55, rug: 0.5 });
const vidroPreto = mat(C.vidro, { rug: 0.18 });

/** Retângulo de cantos arredondados, espessura d em Z, centrado em (x, y, z). */
const Ret: React.FC<{ w: number; h: number; d: number; r: number; x?: number; y?: number; z: number; m: THREE.Material; sombra?: boolean }> = ({ w, h, d, r, x = 0, y = 0, z, m, sombra = false }) => (
  <group position={[x, y, z]}>
    <mesh material={m} castShadow={sombra} receiveShadow><boxGeometry args={[w - 2 * r, h, d]} /></mesh>
    <mesh material={m} castShadow={sombra} receiveShadow><boxGeometry args={[w, h - 2 * r, d]} /></mesh>
    {([[-1, -1], [1, -1], [-1, 1], [1, 1]] as const).map(([sx, sy]) => (
      <mesh key={`${sx}${sy}`} position={[sx * (w / 2 - r), sy * (h / 2 - r), 0]} rotation={[Math.PI / 2, 0, 0]} material={m} castShadow={sombra} receiveShadow>
        <cylinderGeometry args={[r, r, d, 16]} />
      </mesh>
    ))}
  </group>
);

const Disco: React.FC<{ r: number; d: number; x: number; y: number; z: number; m: THREE.Material }> = ({ r, d, x, y, z, m }) => (
  <mesh position={[x, y, z]} rotation={[Math.PI / 2, 0, 0]} material={m}><cylinderGeometry args={[r, r, d, 24]} /></mesh>
);

export const Celular: React.FC<{ telaAcesa?: boolean }> = ({ telaAcesa = true }) => {
  // camadas em Z (frente): capinha até +4,5 mm, vidro até +5,5 mm, tela até +6,3 mm, ícones até +7,3 mm
  const zTela = 0.0059, zIcone = 0.0068;
  const capa = mat(C.capa, { rug: 0.75 });
  return (
    <group>
      {/* capinha (corpo) */}
      <Ret w={0.079} h={0.159} d={0.011} r={0.013} z={-0.001} m={capa} sombra />
      {/* frente de vidro preto (bordas finas) */}
      <Ret w={0.0735} h={0.1535} d={0.003} r={0.0105} z={0.004} m={vidroPreto} />
      {telaAcesa ? (
        <group>
          <Ret w={0.068} h={0.148} d={0.0008} r={0.008} z={zTela} m={telaMat(C.tela)} />
          {/* barra de cima: faixa clara, hora à esquerda, bateria à direita, câmera frontal no meio */}
          <Ret w={0.062} h={0.009} d={0.0008} r={0.003} y={0.0655} z={zIcone - 0.0004} m={telaMat(C.barra)} />
          <mesh position={[-0.022, 0.0655, zIcone + 0.0003]} material={mat(C.marca)}><boxGeometry args={[0.011, 0.0032, 0.0006]} /></mesh>
          <mesh position={[0.024, 0.0655, zIcone + 0.0003]} material={mat(C.marca)}><boxGeometry args={[0.0075, 0.0034, 0.0006]} /></mesh>
          {[0, 1, 2].map((i) => <mesh key={i} position={[0.0135 + i * 0.0022, 0.0645 + i * 0.0006, zIcone + 0.0003]} material={mat(C.marca)}><boxGeometry args={[0.0013, 0.0014 + i * 0.0012, 0.0006]} /></mesh>)}
          <Disco r={0.0026} d={0.0012} x={0} y={0.0655} z={zIcone + 0.0002} m={vidroPreto} />
          {/* widget com sol */}
          <Ret w={0.06} h={0.032} d={0.001} r={0.005} y={0.039} z={zIcone - 0.0003} m={telaMat(C.widget)} />
          <Disco r={0.0075} d={0.0008} x={-0.017} y={0.039} z={zIcone + 0.0005} m={telaMat(C.sol)} />
          <mesh position={[0.011, 0.044, zIcone + 0.0005]} material={telaMat('#ffffff')}><boxGeometry args={[0.026, 0.0045, 0.0006]} /></mesh>
          <mesh position={[0.007, 0.034, zIcone + 0.0005]} material={telaMat('#e3eeff')}><boxGeometry args={[0.018, 0.0035, 0.0006]} /></mesh>
          {/* 4 ícones de app */}
          {ICONES.map((cor, i) => (
            <Ret key={cor} w={0.0125} h={0.0125} d={0.001} r={0.0032} x={-0.0237 + i * 0.0158} y={0.006} z={zIcone - 0.0003} m={telaMat(cor)} />
          ))}
          {/* cartão com gráfico de barras dobrando */}
          <Ret w={0.06} h={0.05} d={0.001} r={0.005} y={-0.032} z={zIcone - 0.0003} m={telaMat('#dfe8f7')} />
          <mesh position={[-0.012, -0.0135, zIcone + 0.0005]} material={telaMat('#9fb0c8')}><boxGeometry args={[0.03, 0.0035, 0.0006]} /></mesh>
          {[0.004, 0.008, 0.016, 0.03].map((h, i) => (
            <mesh key={i} position={[-0.018 + i * 0.012, -0.053 + h / 2, zIcone + 0.0005]} material={telaMat(i === 3 ? '#2ecc71' : '#8fd9b0')}>
              <boxGeometry args={[0.008, h, 0.0006]} />
            </mesh>
          ))}
          {/* indicador de início */}
          <Ret w={0.024} h={0.0018} d={0.0008} r={0.0008} y={-0.0675} z={zIcone - 0.0004} m={mat(C.marca)} />
        </group>
      ) : (
        // apagada: tela preta brilhante com um reflexo diagonal discreto
        <mesh position={[0.012, 0.025, 0.0058]} rotation={[0, 0, 0.6]} material={mat('#3a4150', { rug: 0.3 })}>
          <boxGeometry args={[0.012, 0.11, 0.0004]} />
        </mesh>
      )}
      {/* botões laterais (+X): volume e liga */}
      <mesh position={[0.0398, 0.035, -0.001]} material={mat(C.capaEscura)} castShadow><boxGeometry args={[0.0022, 0.022, 0.005]} /></mesh>
      <mesh position={[0.0398, 0.006, -0.001]} material={mat(C.capaEscura)} castShadow><boxGeometry args={[0.0022, 0.012, 0.005]} /></mesh>
      {/* câmera traseira: módulo no canto de cima (esquerdo, olhando por trás) com 2 lentes e flash */}
      <group position={[0.0195, 0.0595, -0.0065]}>
        <Ret w={0.028} h={0.03} d={0.002} r={0.007} z={-0.001} m={mat(C.capaEscura)} sombra />
        {[0.0072, -0.0072].map((y) => (
          <group key={y}>
            <Disco r={0.0055} d={0.0016} x={0.004} y={y} z={-0.0025} m={mat(C.anel, { rug: 0.4, metal: 0.6 })} />
            <Disco r={0.0042} d={0.0012} x={0.004} y={y} z={-0.0033} m={vidroPreto} />
          </group>
        ))}
        <Disco r={0.002} d={0.0012} x={-0.0075} y={0.0072} z={-0.0024} m={mat(C.flash, { brilho: 0.2 })} />
      </group>
    </group>
  );
};
