// Objeto: prova (folha A4, 21 x 29,7 cm) com um 10 vermelho enorme circulado no topo e linhas de texto cinza-claro.
// O 10 tem 1/3 da altura da folha (10 cm) e se lê de frente (+Z): o "1" à esquerda, o "0" (oval) à direita.
// `inclinacao` (graus): 0 = em pé, 15 = encostada (vitrine), 90 = deitada sobre a carteira, com a frente para cima.
import React from 'react';
import { mat, Tracos, Inclinado, type Traco } from './base';

const C = { papel: '#f8f7f1', borda: '#dedad0', linha: '#c2c2c2', vermelho: '#e0262b' };
const W = 0.21, H = 0.297, D = 0.004;
const zF = D + 0.0004; // frente do papel

// poucas linhas de texto, grossas (9 mm) e cinza-claro, abaixo do círculo
const COMPR = [0.165, 0.14, 0.165, 0.11, 0.15];
const LINHAS: Traco[] = COMPR.map((c, i) => [-0.0825, 0.092 - i * 0.0175, -0.0825 + c, 0.092 - i * 0.0175]);

// o 10: 10 cm de altura, centro em (0, CY); "1" de traços grossos (1,4 cm) e "0" oval (toro achatado)
const CY = 0.193, AL = 0.1, ESP = 0.014, X1 = -0.03;
// a bandeirinha começa um pouco abaixo e à esquerda do topo: a ponta da caixa fica dentro da haste (sem "espinho")
const UM: Traco[] = [[X1, CY - AL / 2, X1, CY + AL / 2], [X1 - 0.003, CY + AL / 2 - 0.003, X1 - 0.02, CY + AL / 2 - 0.023]];

const Folha: React.FC = () => {
  const verm = mat(C.vermelho, { rug: 0.7 });
  return (
    <group>
      {/* folha com espessura mínima de cartolina (4 mm) para ter borda e sombra */}
      <mesh position={[0, H / 2, D / 2]} material={mat(C.papel, { brilho: 0.15 })} castShadow receiveShadow><boxGeometry args={[W, H, D]} /></mesh>
      <mesh position={[0, H / 2, D / 2 - 0.0003]} material={mat(C.borda)} castShadow><boxGeometry args={[W + 0.0016, H + 0.0016, D - 0.0014]} /></mesh>
      <Tracos tracos={LINHAS} l={0.009} z={zF} m={mat(C.linha)} />
      {/* 10 vermelho enorme e o círculo grosso em volta, com folga */}
      <Tracos tracos={UM} l={ESP} z={zF + 0.0004} m={verm} />
      <mesh position={[0.024, CY, zF + 0.0004]} scale={[0.72, 1.4, 0.12]} material={verm} receiveShadow>
        <torusGeometry args={[0.033, 0.0095, 10, 48]} />
      </mesh>
      <mesh position={[0, CY, zF + 0.0004]} scale={[1.1, 0.95, 0.12]} material={verm} receiveShadow>
        <torusGeometry args={[0.08, 0.006, 8, 72]} />
      </mesh>
    </group>
  );
};

export const ProvaDez: React.FC<{ inclinacao?: number }> = ({ inclinacao = 15 }) => (
  <group position={[0, 0, inclinacao >= 80 ? H / 2 : 0]}>
    <Inclinado graus={inclinacao}><Folha /></Inclinado>
  </group>
);
