// Objeto: relógio de rua de 3 m. Base em degraus, poste cinza, braços de apoio e caixa redonda com mostrador
// branco dos dois lados (frente +Z), ponteiros pretos marcando 7h00. Origem no centro da base.
import React from 'react';
import { Caixa, Cil, Haste, mat } from './base';

const C = { poste: '#8b9199', escuro: '#5b626b', caixa: '#4c535b', mostrador: '#faf8f2', marca: '#2b2f35', ponteiro: '#141518', dourado: '#d9a93a' };

const Y_CENTRO = 2.62, R_CAIXA = 0.3, FUNDO = 0.16, R_MOSTRADOR = 0.255;
const ang = (h: number) => (h / 12) * Math.PI * 2; // horas → ângulo horário a partir do 12

/** Mostrador visto de frente (+Z do grupo): marcas das horas, ponteiros das 7h00 e eixo central. */
const Mostrador: React.FC = () => (
  <group>
    <Cil p={[0, 0, 0.004]} topo={R_MOSTRADOR} h={0.008} cor={C.mostrador} lados={48} r={[Math.PI / 2, 0, 0]} />
    {/* moldura grossa em volta do vidro */}
    <mesh position={[0, 0, 0.01]} material={mat(C.escuro)} castShadow receiveShadow><torusGeometry args={[R_MOSTRADOR + 0.012, 0.022, 10, 48]} /></mesh>
    {/* 12 marcas: as de 12, 3, 6 e 9 maiores */}
    {Array.from({ length: 12 }, (_, i) => {
      const a = ang(i), grande = i % 3 === 0, rr = grande ? 0.2 : 0.212;
      return <Caixa key={i} p={[Math.sin(a) * rr, Math.cos(a) * rr, 0.0105]} r={[0, 0, -a]} t={grande ? [0.026, 0.06, 0.005] : [0.014, 0.034, 0.005]} cor={C.marca} sombra={false} />;
    })}
    {/* ponteiro das horas no 7 (curto e largo) */}
    <group position={[0, 0, 0.016]} rotation={[0, 0, -ang(7)]}>
      <Caixa p={[0, 0.05, 0]} t={[0.03, 0.13, 0.005]} cor={C.ponteiro} />
      <mesh position={[0, 0.115, 0]} rotation={[Math.PI / 2, 0, Math.PI / 4]} material={mat(C.ponteiro)} castShadow><cylinderGeometry args={[0.026, 0.026, 0.005, 4]} /></mesh>
    </group>
    {/* ponteiro dos minutos no 12 (longo e fino) */}
    <group position={[0, 0, 0.022]}>
      <Caixa p={[0, 0.08, 0]} t={[0.018, 0.2, 0.005]} cor={C.ponteiro} />
    </group>
    <Cil p={[0, 0, 0.026]} topo={0.018} h={0.012} cor={C.dourado} lados={20} r={[Math.PI / 2, 0, 0]} />
  </group>
);

export const RelogioDeRua: React.FC = () => (
  <group>
    {/* base em dois degraus, octogonal */}
    <Cil p={[0, 0.06, 0]} topo={0.25} base={0.28} h={0.12} cor={C.escuro} lados={8} />
    <Cil p={[0, 0.19, 0]} topo={0.17} base={0.21} h={0.14} cor={C.poste} lados={8} />
    {/* fuste inferior mais grosso com anel, depois o poste */}
    <Cil p={[0, 0.52, 0]} topo={0.1} base={0.13} h={0.52} cor={C.poste} lados={16} />
    <Cil p={[0, 0.8, 0]} topo={0.12} h={0.06} cor={C.escuro} lados={16} />
    <Cil p={[0, 1.5, 0]} topo={0.07} base={0.08} h={1.4} cor={C.poste} lados={20} />
    <Cil p={[0, 2.06, 0]} topo={0.1} base={0.1} h={0.06} cor={C.escuro} lados={16} />
    <Cil p={[0, 2.2, 0]} topo={0.09} base={0.06} h={0.22} cor={C.poste} lados={16} />
    {/* braços de apoio do poste até a caixa do relógio, com bolinhas nas pontas */}
    {[-1, 1].map((s) => (
      <group key={s}>
        <Haste a={[s * 0.07, 2.08, 0]} b={[s * 0.215, 2.43, 0]} r={0.02} cor={C.escuro} />
        <mesh position={[s * 0.07, 2.08, 0]} material={mat(C.escuro)} castShadow><sphereGeometry args={[0.032, 14, 10]} /></mesh>
      </group>
    ))}
    {/* caixa redonda do relógio (tambor) e os dois mostradores */}
    <Cil p={[0, Y_CENTRO, 0]} topo={R_CAIXA} h={FUNDO} cor={C.caixa} lados={40} r={[Math.PI / 2, 0, 0]} />
    {/* cinta em volta do tambor */}
    <mesh position={[0, Y_CENTRO, 0]} scale={[1, 1, 2]} material={mat(C.escuro)} castShadow receiveShadow>
      <torusGeometry args={[R_CAIXA, 0.03, 10, 48]} />
    </mesh>
    <group position={[0, Y_CENTRO, FUNDO / 2]}><Mostrador /></group>
    <group position={[0, Y_CENTRO, -FUNDO / 2]} rotation={[0, Math.PI, 0]}><Mostrador /></group>
    {/* remate no topo: pescoço e bola dourada (chega a 3 m) */}
    <Cil p={[0, Y_CENTRO + R_CAIXA + 0.03, 0]} topo={0.025} base={0.05} h={0.05} cor={C.escuro} lados={12} />
    <mesh position={[0, 2.99, 0]} material={mat(C.dourado)} castShadow><sphereGeometry args={[0.035, 16, 12]} /></mesh>
  </group>
);
