// Objeto: caixa de sapato de papelão (30 x 11 x 18 cm), tampa aberta para trás (~110°), cheia de papeizinhos dobrados.
// Origem no centro da base, frente para +Z.
import React from 'react';
import { random } from 'remotion';
import { Caixa, mat, type V3 } from './base';

const C = { papelao: '#d9a76a', dentro: '#9a6a3a', tampa: '#e8c08a', aba: '#c9945a', etiqueta: '#f4ead2', rabisco: '#6b4a2c', papel: '#ffffff', dobra: '#ece5d4' };
const L = 0.3, A = 0.11, P = 0.18, E = 0.006; // largura, altura, profundidade, espessura da parede

/** Bilhete dobrado ao meio: duas abas brancas em "V" aberto (a dobra fica para cima). */
const Bilhete: React.FC<{ p: V3; giro: number; incl: number; abre: number }> = ({ p, giro, incl, abre }) => (
  <group position={p} rotation={[incl, giro, 0]}>
    {[-1, 1].map((s) => (
      <group key={s} rotation={[0, 0, s * abre]}>
        <mesh position={[s * 0.021, -0.001, 0]} material={mat(s < 0 ? C.papel : C.dobra)} receiveShadow={false}>
          <boxGeometry args={[0.042, 0.0025, 0.034]} />
        </mesh>
      </group>
    ))}
  </group>
);

// 13 bilhetes sobre o monte de papel, espalhados pela boca da caixa (posição e giro fixos por semente)
const BILHETES = Array.from({ length: 13 }, (_, i) => {
  const col = i % 5, lin = Math.floor(i / 5);
  return {
    // dentro da boca (x ±0,1, z ±0,045): com o giro, a aba alcança 2,7 cm e não fura a parede
    p: [-0.1 + col * 0.05 + (random(`bx${i}`) - 0.5) * 0.012, 0.1 + random(`by${i}`) * 0.012, -0.042 + lin * 0.042 + (random(`bz${i}`) - 0.5) * 0.008] as V3,
    giro: random(`bg${i}`) * Math.PI,
    incl: (random(`bi${i}`) - 0.5) * 0.4,
    abre: -0.4 - random(`ba${i}`) * 0.25,
  };
});

export const CaixaDeSapato: React.FC = () => (
  <group>
    {/* corpo: fundo e 4 paredes (por dentro, marrom escuro) */}
    <Caixa p={[0, E / 2, 0]} t={[L, E, P]} cor={C.papelao} />
    <Caixa p={[0, A / 2, P / 2 - E / 2]} t={[L, A, E]} cor={C.papelao} />
    <Caixa p={[0, A / 2, -P / 2 + E / 2]} t={[L, A, E]} cor={C.papelao} />
    <Caixa p={[L / 2 - E / 2, A / 2, 0]} t={[E, A, P - 2 * E]} cor={C.papelao} />
    <Caixa p={[-L / 2 + E / 2, A / 2, 0]} t={[E, A, P - 2 * E]} cor={C.papelao} />
    {/* forro interno escuro, 2 mm para dentro das paredes */}
    <Caixa p={[0, A / 2 + 0.003, P / 2 - E - 0.002]} t={[L - 2 * E - 0.004, A - 0.006, 0.002]} cor={C.dentro} />
    <Caixa p={[0, A / 2 + 0.003, -P / 2 + E + 0.002]} t={[L - 2 * E - 0.004, A - 0.006, 0.002]} cor={C.dentro} />
    <Caixa p={[L / 2 - E - 0.002, A / 2 + 0.003, 0]} t={[0.002, A - 0.006, P - 2 * E - 0.004]} cor={C.dentro} />
    <Caixa p={[-L / 2 + E + 0.002, A / 2 + 0.003, 0]} t={[0.002, A - 0.006, P - 2 * E - 0.004]} cor={C.dentro} />
    {/* monte de papel que enche a caixa até perto da borda */}
    <Caixa p={[0, 0.05, 0]} t={[L - 2 * E - 0.008, 0.088, P - 2 * E - 0.008]} cor={C.dobra} sombra={false} />
    {BILHETES.map((b, i) => <Bilhete key={i} {...b} />)}

    {/* etiqueta grande na frente com 2 rabiscos */}
    <Caixa p={[0.06, 0.058, P / 2 + 0.001]} t={[0.11, 0.055, 0.002]} cor={C.etiqueta} />
    <Caixa p={[0.052, 0.066, P / 2 + 0.0025]} t={[0.075, 0.008, 0.0015]} cor={C.rabisco} sombra={false} />
    <Caixa p={[0.043, 0.049, P / 2 + 0.0025]} t={[0.057, 0.008, 0.0015]} cor={C.rabisco} sombra={false} />

    {/* tampa: articulada na borda de trás, aberta ~110° (passou da vertical) */}
    <group position={[0, A + 0.002, -P / 2 - 0.004]} rotation={[-(110 * Math.PI) / 180, 0, 0]}>
      <Caixa p={[0, 0.003, P / 2 + 0.004]} t={[L + 0.012, E, P + 0.012]} cor={C.tampa} />
      {/* abas da tampa (em volta, viradas para "baixo" da tampa fechada) */}
      <Caixa p={[0, -0.012, P + 0.007]} t={[L + 0.012, 0.03, E]} cor={C.aba} />
      <Caixa p={[0, -0.012, 0.001]} t={[L + 0.012, 0.03, E]} cor={C.aba} />
      <Caixa p={[L / 2 + 0.003, -0.012, P / 2 + 0.004]} t={[E, 0.03, P]} cor={C.aba} />
      <Caixa p={[-L / 2 - 0.003, -0.012, P / 2 + 0.004]} t={[E, 0.03, P]} cor={C.aba} />
    </group>
  </group>
);
