import React from 'react';
import { matChapado, type V3 } from './base';

const PRETO = '#000000';

const Membro: React.FC<{ p: V3; raio: number; comprimento: number; giro?: number }> = (
  { p, raio, comprimento, giro = 0 },
) => (
  <mesh position={p} rotation={[0, 0, giro]} scale={[1, 1, 0.05 / raio]}
    material={matChapado(PRETO)} castShadow>
    <capsuleGeometry args={[raio, comprimento, 6, 16]} />
  </mesh>
);

// Recorte de 1,70 m, com pescoço, ombros e vão entre pernas finas.
export const SilhuetaHumana: React.FC = () => (
  <group>
    <mesh position={[0, 1.555, 0]} scale={[1, 1, 0.35]} material={matChapado(PRETO)} castShadow>
      <sphereGeometry args={[0.145, 24, 16]} />
    </mesh>
    <Membro p={[0, 1.36, 0]} raio={0.048} comprimento={0.1} />
    <Membro p={[0, 1.225, 0]} raio={0.065} comprimento={0.26} giro={Math.PI / 2} />
    <mesh position={[0, 1.02, 0]} scale={[1, 1, 0.35]} material={matChapado(PRETO)} castShadow>
      <cylinderGeometry args={[0.18, 0.13, 0.46, 20]} />
    </mesh>
    <mesh position={[0, 0.78, 0]} scale={[1, 0.6, 0.35]} material={matChapado(PRETO)} castShadow>
      <sphereGeometry args={[0.16, 20, 12]} />
    </mesh>
    {([-1, 1] as const).map((lado) => (
      <group key={lado}>
        <Membro p={[lado * 0.25, 1.015, 0]} raio={0.045} comprimento={0.42} giro={lado * 0.1} />
        <mesh position={[lado * 0.277, 0.755, 0]} material={matChapado(PRETO)} castShadow>
          <sphereGeometry args={[0.05, 16, 12]} />
        </mesh>
        <Membro p={[lado * 0.1, 0.39, 0]} raio={0.055} comprimento={0.56} />
        {/* O raio do pé determina o contato exato com y=0. */}
        <Membro p={[lado * 0.115, 0.045, 0]} raio={0.045} comprimento={0.07} giro={Math.PI / 2} />
      </group>
    ))}
  </group>
);
