// Ilha de embarque com calçada. Frente do abrigo para +Z, medidas em metros.
import React from 'react';
import { Caixa, Haste, mat, vidro } from './base';

const C = {
  calcada: '#b8b4a8', junta: '#97988e', meioFio: '#e0d9c7', asfalto: '#202632',
  faixa: '#f4d47c', metal: '#465965', teto: '#9da9ab', banco: '#dce0da',
  placa: '#15538c', branco: '#faf4e6', janela: '#45677b', porta: '#526875',
  vidro: '#b7d5d5', terra: '#9fa88d',
};

const Predio: React.FC<{ x: number; largura: number; altura: number; cor: string }> = ({
  x, largura, altura, cor,
}) => (
  <group position={[x, 0, -10.4]}>
    <Caixa p={[0, altura / 2, 0]} t={[largura, altura, 2.2]} cor={cor} />
    <Caixa p={[0, altura + 0.1, 0]} t={[largura + 0.2, 0.2, 2.4]} cor={C.branco} />
    <Caixa p={[0, 0.18, 1.2]} t={[largura, 0.36, 0.16]} cor={C.meioFio} />
    {/* Porta de 2,1 m e degrau dão escala às fachadas. */}
    <Caixa p={[0, 1.2, 1.24]} t={[0.96, 2.1, 0.16]} cor={C.branco} />
    <Caixa p={[0, 1.2, 1.44]} t={[0.72, 1.86, 0.16]} cor={C.porta} />
    <Caixa p={[0, 0.08, 1.6]} t={[1.2, 0.16, 0.6]} cor={C.meioFio} />
    {[-1, 1].map((lado) => [1.65, 3.75].map((y, i) => (
      <group key={`${lado}-${i}`} position={[lado * largura * 0.31, y, 1.24]}>
        <Caixa p={[0, 0, 0]} t={[0.98, 1.28, 0.16]} cor={C.branco} />
        <Caixa p={[0, 0, 0.2]} t={[0.72, 1.02, 0.16]} cor={C.janela} sombra={false} />
        <Caixa p={[0, -0.7, 0.12]} t={[1.1, 0.12, 0.32]} cor={C.branco} />
      </group>
    )))}
  </group>
);

const Calcada: React.FC = () => (
  <group>
    {/* Asfalto só na rua; terreno claro atrás das casas elimina o falso muro. */}
    <Caixa p={[0, -0.36, -8]} t={[60, 0.16, 40]} cor={C.terra} sombra={false} />
    <Caixa p={[0, -0.3, 0.1]} t={[40, 0.16, 15.8]} cor={C.asfalto} sombra={false} />
    {/* Ilha de três metros; a rua passa também entre a câmera e a calçada. */}
    <Caixa p={[0, -0.2, -0.2]} t={[3, 0.2, 2]} cor={C.junta} sombra={false} />
    <Caixa p={[-0.55, -0.16, -2.2]} t={[5.9, 0.32, 2]} cor={C.calcada} sombra={false} />
    <Caixa p={[-0.55, -0.11, -3.3]} t={[6.1, 0.22, 0.2]} cor={C.meioFio} />
    {[-1, 1].map((lado) => <Caixa key={lado} p={[lado * 1.6, -0.11, -0.2]} t={[0.2, 0.22, 2]} cor={C.meioFio} />)}
    <Caixa p={[0, -0.11, 0.9]} t={[3.4, 0.22, 0.2]} cor={C.meioFio} />
    <Caixa p={[-3.5, -0.11, -2.2]} t={[0.2, 0.22, 2]} cor={C.meioFio} />
    <Caixa p={[2.4, -0.11, -2.2]} t={[0.2, 0.22, 2]} cor={C.meioFio} />
    <Caixa p={[-2.55, -0.11, -1.2]} t={[1.9, 0.22, 0.2]} cor={C.meioFio} />
    <Caixa p={[2, -0.11, -1.2]} t={[0.8, 0.22, 0.2]} cor={C.meioFio} />
    {/* Placas separadas por juntas de 8 cm, sem faces coplanares sobrepostas. */}
    {Array.from({ length: 2 }, (_, coluna) => Array.from({ length: 2 }, (_, linha) => (
      <Caixa key={`${coluna}-${linha}`}
        p={[-1.5 + (coluna + 0.5) * 1.5, -0.04, -1.2 + (linha + 0.5)]}
        t={[1.42, 0.08, 0.92]} cor={C.calcada} sombra={false} />
    )))}
    {Array.from({ length: 10 }, (_, i) => (
      <Caixa key={i} p={[-3.7 + i * 0.48, -0.02, -1.45]} t={[0.32, 0.08, 0.32]} cor={C.faixa} sombra={false} />
    ))}
    <Caixa p={[0, -0.14, -8.55]} t={[40, 0.28, 1.3]} cor={C.calcada} sombra={false} />
    <Caixa p={[0, -0.11, -7.8]} t={[40, 0.22, 0.2]} cor={C.meioFio} />
    {[-12, -8, -4, 0, 4, 8, 12].map((x) => (
      <Caixa key={x} p={[x, -0.24, -5.5]} t={[1.8, 0.08, 0.16]} cor={C.faixa} sombra={false} />
    ))}
    {[-0.2, 3, 6.2].map((z) => (
      <Caixa key={z} p={[3.2, -0.24, z]} t={[0.16, 0.08, 1.5]} cor={C.faixa} sombra={false} />
    ))}
  </group>
);

const Abrigo: React.FC = () => (
  <group position={[-0.95, 0, -2.25]}>
    {/* Moldura contínua une o painel traseiro à cobertura de 2,9 m. */}
    {[-2.15, 2.15].map((x) => (
      <group key={x}>
        <Caixa p={[x, 0.08, -0.55]} t={[0.36, 0.16, 0.36]} cor={C.metal} />
        <Caixa p={[x, 1.42, -0.55]} t={[0.16, 2.84, 0.16]} cor={C.metal} />
        <Haste a={[x, 2.3, -0.55]} b={[x, 2.8, 0.62]} raio={0.06} cor={C.metal} />
      </group>
    ))}
    {[0.3, 2.65].map((y) => <Caixa key={y} p={[0, y, -0.55]} t={[4.3, 0.14, 0.16]} cor={C.metal} />)}
    <Caixa p={[0, 1.48, -0.55]} t={[0.12, 2.2, 0.16]} cor={C.metal} />
    {[-1.08, 1.08].map((x) => (
      <mesh key={x} position={[x, 1.48, -0.55]} material={vidro(C.vidro)} receiveShadow>
        <boxGeometry args={[1.98, 2.2, 0.08]} />
      </mesh>
    ))}
    <Caixa p={[-2.15, 1.46, 0]} t={[0.16, 2.36, 1.02]} cor="#a9bdbc" />
    <Caixa p={[-2.15, 1.42, 0.59]} t={[0.16, 2.84, 0.16]} cor={C.metal} />
    <Caixa p={[0, 2.91, 0]} t={[4.7, 0.22, 1.9]} cor={C.teto} />
    <Caixa p={[0, 2.75, 0.87]} t={[4.7, 0.1, 0.16]} cor={C.metal} />
    {/* Banco de 3,8 m: trecho esquerdo livre da silhueta do Téo. */}
    <Caixa p={[-0.1, 0.45, -0.04]} t={[3.8, 0.14, 0.62]} cor={C.banco} />
    <Caixa p={[-0.1, 0.95, -0.35]} t={[3.8, 0.56, 0.14]} cor={C.banco} />
    {[-1.65, 1.45].map((x) => (
      <group key={x}>
        <Caixa p={[x, 0.19, -0.04]} t={[0.16, 0.38, 0.5]} cor={C.metal} />
        <Caixa p={[x, 0.69, -0.46]} t={[0.12, 1.06, 0.12]} cor={C.metal} />
        <Caixa p={[x, 0.7, 0]} t={[0.12, 0.12, 0.6]} cor={C.metal} />
      </group>
    ))}
  </group>
);

const PlacaDoPonto: React.FC = () => (
  <group position={[2.02, 0, -1.85]}>
    <Caixa p={[0, 0.08, 0]} t={[0.34, 0.16, 0.34]} cor={C.meioFio} />
    <Haste a={[0, 0.16, 0]} b={[0, 3.02, 0]} raio={0.08} cor={C.metal} />
    <Caixa p={[0, 2.57, 0.18]} t={[1.08, 1.14, 0.12]} cor={C.placa} />
    {/* Carroceria, janela e duas rodas, sem molduras extras. */}
    <Caixa p={[0, 2.61, 0.32]} t={[0.68, 0.68, 0.12]} cor={C.branco} sombra={false} />
    <Caixa p={[0, 2.75, 0.46]} t={[0.48, 0.2, 0.12]} cor={C.placa} sombra={false} />
    {[-1, 1].map((lado) => (
      <group key={lado}>
        <Caixa p={[lado * 0.23, 2.19, 0.32]} t={[0.14, 0.16, 0.12]} cor={C.branco} sombra={false} />
        <Caixa p={[lado * 0.22, 2.45, 0.46]} t={[0.1, 0.1, 0.12]} cor={C.placa} sombra={false} />
      </group>
    ))}
  </group>
);

export const PontoDeOnibus: React.FC = () => (
  <group>
    <Calcada />
    <Predio x={-7.5} largura={3.8} altura={5.2} cor="#e4ad76" />
    <Predio x={-3.4} largura={3.8} altura={5.5} cor="#83b9ac" />
    <Predio x={0.7} largura={3.8} altura={5.1} cor="#df9686" />
    {/* Vão atrás da placa; fachada amarela fora da sua silhueta. */}
    <Predio x={8} largura={3.8} altura={5.4} cor="#e4ca7e" />
    <Abrigo />
    <PlacaDoPonto />
    <mesh position={[-3, 0.36, -1.5]} material={mat('#547c74')} castShadow receiveShadow>
      <cylinderGeometry args={[0.25, 0.22, 0.72, 12]} />
    </mesh>
    <Caixa p={[-3, 0.73, -1.5]} t={[0.54, 0.1, 0.54]} cor={C.metal} />
    <Caixa p={[-3, 0.74, -1.42]} t={[0.28, 0.08, 0.18]} cor="#263d44" sombra={false} />
  </group>
);
