// Cenário: sala de aula de escola pública brasileira, de dia. Medidas em metros, Y para cima, chão em y = 0.
// A frente da sala (lousa) fica em -Z; os personagens ficam perto de (0,0,0) virados para +Z (câmera e carteiras).
// Janelas na parede +X, do lado de onde vem o sol da Luz padrão: a luz entra e desenha os caixilhos no chão.
import * as THREE from 'three';
import React from 'react';
import { random } from 'remotion';
import type { LimitesCenario } from '../contrato';
import { Caixa, Haste, mat, vidro, type V3 } from './base';

const C = {
  piso: '#e9e2d2', piso2: '#dcd2bf', grama: '#9cc078', muro: '#e3c58c',
  parede: '#f3e8cf', barrado: '#79b3a3', faixa: '#4f8b7b', teto: '#f7f3ec',
  madeira: '#9a6236', madeiraClara: '#d9ad74', lousa: '#2f5b46', giz: '#f3f1e8', gizAmarelo: '#f2d36b',
  metal: '#4b525c', cinza: '#9aa3ad', assento: '#2f6fd0', porta: '#8c5a35', branco: '#f8f5ef',
  vidro: '#d8eef9', cortica: '#c99a5e', folha: '#4f9a52', tronco: '#6b4a2f',
};

// medidas da sala
const X = 4; // meia largura (paredes laterais em x = ±4)
const ZF = -3.8; // face da parede do fundo (lousa)
const ZT = 8; // as paredes vão até atrás da câmera
const H = 3.5; // pé-direito
const B = 1.2; // altura do barrado
const L = ZT - ZF + 0.2, ZC = (ZF - 0.2 + ZT) / 2; // comprimento e centro das paredes laterais

export const LIMITES_SALA: LimitesCenario = { limiteX: 1.4, limiteZ: [-3.0, 3.0], ceu: '#cde8f6' };

/** Piso: base clara + ladrilhos de 1 m alternados (2 cm acima da base). */
const Piso: React.FC = () => {
  const lad: V3[] = [];
  for (let i = 0; i < 2 * X; i++) for (let j = 0; j < 11; j++) if ((i + j) % 2 === 0) lad.push([-X + 0.5 + i, -0.015, ZF + 0.5 + j]);
  return (
    <group>
      <Caixa p={[0, -0.1, 0]} t={[80, 0.1, 80]} cor={C.grama} sombra={false} />
      <Caixa p={[0, -0.045, ZC]} t={[2 * X + 0.4, 0.05, L]} cor={C.piso} sombra={false} />
      {lad.map((p, i) => <Caixa key={i} p={p} t={[1, 0.03, 1]} cor={C.piso2} sombra={false} />)}
    </group>
  );
};

/** Trecho de parede com barrado embaixo, faixa e parede clara em cima. Eixo: 'x' corre em X, 'z' corre em Z. */
const Parede: React.FC<{ c: V3; comp: number; eixo: 'x' | 'z'; y0?: number; y1?: number; dentro: number }> = ({ c, comp, eixo, y0 = 0, y1 = H + 0.1, dentro }) => {
  const t = (h: number, e = 0.2): V3 => (eixo === 'x' ? [comp, h, e] : [e, h, comp]);
  const em = (y: number, off = 0): V3 => (eixo === 'x' ? [c[0], y, c[2] + off * dentro] : [c[0] + off * dentro, y, c[2]]);
  const pecas: React.ReactNode[] = [];
  if (y0 < B) pecas.push(<Caixa key="b" p={em((y0 + Math.min(B, y1)) / 2)} t={t(Math.min(B, y1) - y0)} cor={C.barrado} />);
  if (y1 > B) pecas.push(<Caixa key="p" p={em((Math.max(B, y0) + y1) / 2)} t={t(y1 - Math.max(B, y0))} cor={C.parede} />);
  // faixa do barrado: 3 cm mais saliente que a parede
  if (y0 <= B && y1 >= B) pecas.push(<Caixa key="f" p={em(B)} t={t(0.1, 0.26)} cor={C.faixa} />);
  return <group>{pecas}</group>;
};

/** Traço de giz entre dois pontos da lousa (x, y), 8 cm de largura, 2 cm à frente do quadro. */
const Giz: React.FC<{ a: [number, number]; b: [number, number]; cor?: string }> = ({ a, b, cor = C.giz }) => {
  const dx = b[0] - a[0], dy = b[1] - a[1];
  return <Caixa p={[(a[0] + b[0]) / 2, (a[1] + b[1]) / 2, ZF + 0.045]} t={[Math.hypot(dx, dy) + 0.08, 0.08, 0.03]} r={[0, 0, Math.atan2(dy, dx)]} cor={cor} sombra={false} />;
};

const Lousa: React.FC = () => {
  const y = 1.6, w = 3.6, h = 1.25;
  // "palavras" de giz: [x inicial, comprimento] por linha; inclinação mínima para parecer feito à mão
  const linhas: [number, number][][] = [
    [[-1.5, 0.55], [-0.82, 0.3]],
    [[-1.5, 0.3], [-1.08, 0.5], [-0.46, 0.18]],
    [[-1.5, 0.62], [-0.76, 0.26]],
    [[-1.5, 0.22], [-1.16, 0.42]],
  ];
  return (
    <group>
      <Caixa p={[0, y, ZF + 0.02]} t={[w, h, 0.04]} cor={C.lousa} />
      {/* moldura de madeira, 4 cm à frente do quadro */}
      <Caixa p={[0, y + h / 2 + 0.05, ZF + 0.04]} t={[w + 0.2, 0.1, 0.08]} cor={C.madeira} />
      <Caixa p={[0, y - h / 2 - 0.05, ZF + 0.04]} t={[w + 0.2, 0.1, 0.08]} cor={C.madeira} />
      <Caixa p={[-w / 2 - 0.05, y, ZF + 0.04]} t={[0.1, h, 0.08]} cor={C.madeira} />
      <Caixa p={[w / 2 + 0.05, y, ZF + 0.04]} t={[0.1, h, 0.08]} cor={C.madeira} />
      <Caixa p={[0, y - h / 2 - 0.125, ZF + 0.08]} t={[w, 0.05, 0.16]} cor={C.madeira} />
      <Caixa p={[1.1, y - h / 2 - 0.07, ZF + 0.1]} t={[0.2, 0.06, 0.09]} cor={C.madeiraClara} />
      {/* rabiscos: linhas de "conta" à esquerda, gráfico subindo à direita (nada de texto) */}
      {linhas.map((ln, i) => ln.map(([x0, c], k) => {
        const yy = y + 0.42 - i * 0.26, inc = (random(`giz-${i}-${k}`) - 0.5) * 0.04;
        return <Giz key={`${i}-${k}`} a={[x0, yy - inc]} b={[x0 + c, yy + inc]} />;
      }))}
      <Giz a={[-1.5, y + 0.3]} b={[-0.55, y + 0.3]} cor={C.gizAmarelo} />
      <Giz a={[0.35, y + 0.45]} b={[0.35, y - 0.42]} />
      <Giz a={[0.35, y - 0.42]} b={[1.55, y - 0.42]} />
      <Giz a={[0.5, y - 0.3]} b={[0.85, y - 0.12]} cor={C.gizAmarelo} />
      <Giz a={[0.85, y - 0.12]} b={[1.1, y - 0.2]} cor={C.gizAmarelo} />
      <Giz a={[1.1, y - 0.2]} b={[1.45, y + 0.32]} cor={C.gizAmarelo} />
      <Giz a={[1.45, y + 0.32]} b={[1.27, y + 0.3]} cor={C.gizAmarelo} />
      <Giz a={[1.45, y + 0.32]} b={[1.5, y + 0.14]} cor={C.gizAmarelo} />
    </group>
  );
};

/** Relógio redondo de parede marcando 10h10. */
const Relogio: React.FC<{ p: V3 }> = ({ p }) => {
  const ponteiro = (ang: number, comp: number, larg: number, z: number) => (
    <group position={[0, 0, z]} rotation={[0, 0, -ang]}>
      <Caixa p={[0, comp / 2 - 0.03, 0]} t={[larg, comp, 0.02]} cor="#222428" sombra={false} />
    </group>
  );
  return (
    <group position={p}>
      <mesh position={[0, 0, 0.04]} rotation={[Math.PI / 2, 0, 0]} material={mat(C.branco)} castShadow receiveShadow><cylinderGeometry args={[0.3, 0.3, 0.08, 40]} /></mesh>
      <mesh position={[0, 0, 0.06]} material={mat('#d6453d')} castShadow><torusGeometry args={[0.3, 0.05, 12, 40]} /></mesh>
      {[0, 1, 2, 3].map((i) => <Caixa key={i} p={[0.21 * Math.sin((i * Math.PI) / 2), 0.21 * Math.cos((i * Math.PI) / 2), 0.09]} t={[0.08, 0.08, 0.02]} cor="#3a3d44" sombra={false} />)}
      {ponteiro((-50 * Math.PI) / 180, 0.17, 0.08, 0.11)}
      {ponteiro((60 * Math.PI) / 180, 0.24, 0.08, 0.13)}
      <mesh position={[0, 0, 0.15]} rotation={[Math.PI / 2, 0, 0]} material={mat('#d6453d')}><cylinderGeometry args={[0.045, 0.045, 0.02, 16]} /></mesh>
    </group>
  );
};

const CORES_LIVRO = ['#d64545', '#f2b134', '#3a86c8', '#2fa36b', '#8e5bd6', '#f07f3c', '#e9e1cc', '#1f4f8a'];

/** Estante de madeira encostada no fundo, com livros coloridos e um globo em cima. */
const Estante: React.FC<{ x: number }> = ({ x }) => {
  const w = 1.4, h = 1.9, d = 0.4, zc = ZF + d / 2;
  const livros: { p: V3; t: V3; cor: string; inc: number }[] = [];
  [0.08, 0.63, 1.18].forEach((base, s) => {
    let cx = x - w / 2 + 0.1;
    for (let k = 0; cx < x + w / 2 - 0.22; k++) {
      const r = (n: string) => random(`livro-${s}-${k}-${n}`);
      const lw = 0.08 + r('w') * 0.05, lh = 0.26 + r('h') * 0.16;
      if (s === 2 && k === 4) { cx += 0.3; continue; } // vão na prateleira de cima
      const inc = r('i') > 0.85 ? 0.2 : 0;
      livros.push({ p: [cx + lw / 2, base + lh / 2, ZF + 0.2], t: [lw, lh, 0.26], cor: CORES_LIVRO[Math.floor(r('c') * CORES_LIVRO.length)], inc });
      cx += lw + 0.006 + inc * 0.15;
    }
  });
  return (
    <group>
      <Caixa p={[x, h / 2, ZF + 0.02]} t={[w, h, 0.04]} cor={C.madeira} />
      <Caixa p={[x - w / 2 + 0.04, h / 2, zc]} t={[0.08, h, d]} cor={C.madeiraClara} />
      <Caixa p={[x + w / 2 - 0.04, h / 2, zc]} t={[0.08, h, d]} cor={C.madeiraClara} />
      {[0.04, 0.59, 1.14, h - 0.04].map((y, i) => <Caixa key={i} p={[x, y, zc]} t={[w, 0.08, d]} cor={C.madeiraClara} />)}
      {livros.map((l, i) => <Caixa key={i} p={l.p} t={l.t} cor={l.cor} r={[0, 0, -l.inc]} />)}
      {/* globo terrestre */}
      <Haste a={[x + 0.35, h, zc]} b={[x + 0.35, h + 0.12, zc]} r={0.05} cor={C.madeira} />
      <mesh position={[x + 0.35, h + 0.3, zc]} material={mat('#3f8fd2')} castShadow receiveShadow><sphereGeometry args={[0.18, 24, 16]} /></mesh>
      <mesh position={[x + 0.27, h + 0.36, zc + 0.07]} scale={[1, 0.8, 0.6]} material={mat('#5fae5a')} castShadow><sphereGeometry args={[0.1, 14, 10]} /></mesh>
      <mesh position={[x + 0.35, h + 0.3, zc]} rotation={[0, Math.PI / 2, 0.4]} material={mat('#c9a14a')} castShadow><torusGeometry args={[0.22, 0.02, 8, 32]} /></mesh>
    </group>
  );
};

/** Mural de cortiça com papéis (sem texto). */
