// Cenário: pátio aberto da escola, de dia. Medidas em metros, Y para cima, chão em y = 0.
// Pátio de cimento em placas de 2 m (dois tons, sem linhas finas), amarelinha pintada atrás dos personagens,
// calçada bege e canteiro na frente do prédio amarelo. A entrada fica num patamar com degraus, no vão entre
// os personagens, então a porta aparece acima das cabeças. Banco à esquerda e árvore num canteiro à direita.
import React from 'react';
import type { LimitesCenario } from '../tipos';
import { Caixa, Cilindro, Copa, Haste, Letreiro, PlanoFoco, mat, type V3 } from './base';

const C = {
  grama: '#9cc078', cimento: '#b4b7b6', cimento2: '#a3a7a7', calcada: '#e6d6b2', calcadaBorda: '#cdbb93',
  predio: '#f2c14e', barrado: '#c8693f', branco: '#f8f5ef', vidro: '#3f6f9e', porta: '#2f78b8', portaEscura: '#245f94',
  marquise: '#c8693f', canteiro: '#7fae5e', terra: '#8a6a4a', folha: '#4f9a52', folha2: '#5fae5a', folha3: '#468a4a',
  tronco: '#6b4a2f', ripa: '#a8683a', ferro: '#2f5d4a', placa: '#f8f5ef', letra: '#2f6fb0', caixaDagua: '#5aa0d6',
  tijolo: '#b85a3a',
};

const ZP = -8.6; // fachada do prédio
const ZC0 = -6.7; // começo da calçada bege (fim do cimento)
const HP = 3.9; // altura da parede do prédio
const HF = 4.6; // altura do frontão da entrada
const XPORTA = -0.3; // centro da porta (no vão entre os personagens)
const YP = 0.45; // altura do patamar da entrada

export const LIMITES_PATIO: LimitesCenario = { limiteX: 1.5, limiteZ: [-1.0, 3.0], ceu: '#a9d8f0' };

/** Chão: grama de base, pátio de cimento em placas de 2 m de dois tons e calçada bege mais alta na frente do prédio. */
const Chao: React.FC = () => {
  const placas: V3[] = [];
  for (let i = 0; i < 13; i++) for (let j = 0; j < 8; j++) if ((i + j) % 2 === 0) placas.push([-13 + 1 + i * 2, -0.01, ZC0 + 1 + j * 2]);
  return (
    <group>
      <Caixa p={[0, -0.12, -10]} t={[90, 0.1, 70]} cor={C.grama} sombra={false} />
      <Caixa p={[0, -0.045, (ZC0 + 10) / 2]} t={[26, 0.05, 10 - ZC0]} cor={C.cimento} sombra={false} />
      {/* placas escuras 2 cm acima da base */}
      {placas.map((p, i) => <Caixa key={i} p={p} t={[2, 0.02, 2]} cor={C.cimento2} sombra={false} />)}
      {/* calçada bege: 8 cm acima do pátio, com borda mais escura e larga */}
      <Caixa p={[0, 0.04, (ZC0 + ZP) / 2 - 0.1]} t={[26, 0.08, ZC0 - ZP + 0.2]} cor={C.calcada} sombra={false} />
      <Caixa p={[0, 0.045, ZC0 - 0.1]} t={[26, 0.09, 0.2]} cor={C.calcadaBorda} />
    </group>
  );
};

/** Amarelinha pintada no cimento: casas de 50 cm coloridas e o "céu" em meia-lua (pintura 2 cm acima do chão). */
const Amarelinha: React.FC<{ x: number; z: number }> = ({ x, z }) => {
  const cores = ['#f2c94c', '#4fa3d9', '#e8664a', '#7cc06a'];
  const casas: [number, number][] = [[0, 0], [-0.25, 1], [0.25, 1], [0, 2], [-0.25, 3], [0.25, 3], [0, 4]];
  return (
    <group>
      {casas.map(([dx, k], i) => <Caixa key={i} p={[x + dx, 0.01, z - k * 0.5]} t={[0.5, 0.02, 0.5]} cor={cores[i % 4]} sombra={false} />)}
      <mesh position={[x, 0.01, z - 4 * 0.5 - 0.25]} rotation={[0, Math.PI / 2, 0]} material={mat(cores[1])} receiveShadow>
        <cylinderGeometry args={[0.5, 0.5, 0.02, 24, 1, false, 0, Math.PI]} />
      </mesh>
    </group>
  );
};

/** Janela da fachada: moldura branca, vidro 3 cm à frente, travessa grossa e peitoril. */
const Janela: React.FC<{ x: number }> = ({ x }) => {
  const y = 2.0, w = 1.4, h = 1.6;
  return (
    <group>
      <Caixa p={[x, y, ZP + 0.02]} t={[w + 0.24, h + 0.24, 0.04]} cor={C.branco} sombra={false} />
      <Caixa p={[x, y, ZP + 0.05]} t={[w, h, 0.04]} cor={C.vidro} sombra={false} />
      <Caixa p={[x, y, ZP + 0.08]} t={[0.1, h, 0.04]} cor={C.branco} sombra={false} />
      <Caixa p={[x, y + 0.25, ZP + 0.08]} t={[w, 0.1, 0.04]} cor={C.branco} sombra={false} />
      <Caixa p={[x, y - h / 2 - 0.12, ZP + 0.1]} t={[w + 0.4, 0.1, 0.2]} cor={C.branco} />
    </group>
  );
};

/** Prédio da escola: parede amarela, barrado terracota, cornija branca, janelas, entrada com patamar e letreiro. */
const Predio: React.FC = () => {
  const janelas = [-9.6, -7.2, -4.8, -2.55, 2.3, 8.5, 10.9];
  return (
    <group>
      <Caixa p={[0, HP / 2, ZP - 3]} t={[24, HP, 6]} cor={C.predio} />
      {/* barrado (3 cm à frente da parede) e cornija */}
      <Caixa p={[0, 0.35, ZP + 0.015]} t={[24, 0.7, 0.03]} cor={C.barrado} sombra={false} />
      {/* cornija dos dois lados do frontão */}
      {[[-12.2, XPORTA - 1.8], [XPORTA + 1.8, 12.2]].map(([x0, x1]) => (
        <Caixa key={x0} p={[(x0 + x1) / 2, HP + 0.12, ZP - 2.85]} t={[x1 - x0, 0.24, 6.6]} cor={C.branco} />
      ))}
      <Caixa p={[0, HP + 0.3, ZP - 3.2]} t={[24, 0.12, 5.6]} cor="#d9cfbd" />
      {/* frontão da entrada (sobe acima da cornija), com cornija própria */}
      <Caixa p={[XPORTA, (HP + HF) / 2, ZP - 0.4]} t={[3.6, HF - HP, 0.8]} cor={C.predio} />
      <Caixa p={[XPORTA, HF + 0.1, ZP - 0.35]} t={[3.9, 0.2, 1.0]} cor={C.branco} />
      {/* caixa d'água no telhado */}
      <Cilindro p={[-6.5, HP + 0.36, ZP - 3.5]} r={0.9} h={1.0} cor={C.caixaDagua} />
      <Cilindro p={[-6.5, HP + 1.36, ZP - 3.5]} r={0.95} r2={0.95} h={0.12} cor="#4a8fc4" />
      {janelas.map((x) => <Janela key={x} x={x} />)}
      {/* entrada: patamar com 3 degraus, porta dupla azul com visores, marquise e letreiro */}
      <Caixa p={[XPORTA, YP / 2, ZP + 0.6]} t={[3.2, YP, 1.2]} cor="#d9d2c3" />
      {[0, 1, 2].map((k) => (
        <Caixa key={k} p={[XPORTA, (YP * (3 - k)) / 3 / 2, ZP + 1.2 + 0.17 + k * 0.34]} t={[2.6, (YP * (3 - k)) / 3, 0.34]} cor={k % 2 ? '#d9d2c3' : '#cbc3b2'} />
      ))}
      <Caixa p={[XPORTA, YP + 1.3, ZP + 0.02]} t={[2.0, 2.6, 0.04]} cor={C.branco} sombra={false} />
      {[-1, 1].map((s) => (
        <group key={s}>
          <Caixa p={[XPORTA + s * 0.43, YP + 1.2, ZP + 0.05]} t={[0.8, 2.3, 0.04]} cor={C.porta} sombra={false} />
          <Caixa p={[XPORTA + s * 0.43, YP + 1.65, ZP + 0.08]} t={[0.44, 0.7, 0.03]} cor="#a9d3ee" sombra={false} />
          <Caixa p={[XPORTA + s * 0.12, YP + 1.05, ZP + 0.1]} t={[0.08, 0.36, 0.06]} cor="#d9dde0" />
        </group>
      ))}
      <Caixa p={[XPORTA, YP + 1.2, ZP + 0.075]} t={[0.08, 2.3, 0.03]} cor={C.portaEscura} sombra={false} />
      <Caixa p={[XPORTA, 3.15, ZP + 0.7]} t={[3.0, 0.16, 1.4]} cor={C.marquise} />
      {/* letreiro "ESCOLA" em letras de traço grosso */}
      <Caixa p={[XPORTA, 3.95, ZP + 0.03]} t={[3.0, 0.72, 0.06]} cor={C.placa} />
      <Letreiro texto="ESCOLA" p={[XPORTA, 3.95, ZP + 0.07]} alt={0.46} larg={0.3} passo={0.44} traco={0.08} cor={C.letra} />
      {/* canteiros com arbustos ao longo da fachada, com vão na entrada */}
      {[[-12, XPORTA - 1.75], [XPORTA + 1.75, 12]].map(([x0, x1]) => (
        <group key={x0}>
          {/* mureta de tijolo (frente e pontas) e terra 6 cm abaixo da borda */}
          <Caixa p={[(x0 + x1) / 2, 0.16, ZP + 0.74]} t={[x1 - x0, 0.32, 0.12]} cor={C.tijolo} />
          <Caixa p={[x0 + 0.06, 0.16, ZP + 0.4]} t={[0.12, 0.32, 0.8]} cor={C.tijolo} />
          <Caixa p={[x1 - 0.06, 0.16, ZP + 0.4]} t={[0.12, 0.32, 0.8]} cor={C.tijolo} />
          <Caixa p={[(x0 + x1) / 2, 0.13, ZP + 0.35]} t={[x1 - x0 - 0.12, 0.26, 0.7]} cor={C.terra} sombra={false} />
        </group>
      ))}
      {[-10.8, -8.4, -6.0, -3.7, 1.9, 3.4, 7.3, 9.7].map((x, i) => (
        <Copa key={x} p={[x, 0.55, ZP + 0.42]} r={0.38} s={[1.3, 0.9, 0.9]} cor={i % 2 ? C.folha : C.folha2} />
      ))}
      {/* copas atrás do prédio */}
      {[-11, -3.5, 4.5, 11.5].map((x, i) => (
        <mesh key={x} position={[x, HP + 0.2 + (i % 2) * 0.4, ZP - 8]} material={mat(i % 2 ? C.folha : C.folha3, { flat: true })} castShadow receiveShadow><icosahedronGeometry args={[1.7, 0]} /></mesh>
      ))}
    </group>
  );
};

/** Banco de praça: duas ripas no assento e duas no encosto (madeira escura), laterais de ferro verde. Olha para +Z. */
const Banco: React.FC<{ p: V3 }> = ({ p }) => {
  const c = 1.8;
  return (
    <group position={p}>
      <Caixa p={[0, 0.45, 0.08]} t={[c, 0.06, 0.16]} cor={C.ripa} />
      <Caixa p={[0, 0.45, -0.16]} t={[c, 0.06, 0.16]} cor={C.ripa} />
      <Caixa p={[0, 0.66, -0.3]} t={[c, 0.14, 0.06]} cor={C.ripa} r={[-0.12, 0, 0]} />
      <Caixa p={[0, 0.88, -0.33]} t={[c, 0.14, 0.06]} cor={C.ripa} r={[-0.12, 0, 0]} />
      {[-1, 1].map((s) => (
        <group key={s} position={[s * (c / 2 - 0.15), 0, 0]}>
          <Caixa p={[0, 0.21, 0.14]} t={[0.08, 0.42, 0.08]} cor={C.ferro} />
          <Caixa p={[0, 0.21, -0.22]} t={[0.08, 0.42, 0.08]} cor={C.ferro} />
          <Caixa p={[0, 0.41, -0.04]} t={[0.08, 0.06, 0.48]} cor={C.ferro} />
          <Caixa p={[0, 0.7, -0.3]} t={[0.08, 0.6, 0.08]} cor={C.ferro} r={[-0.12, 0, 0]} />
          <Caixa p={[0, 0.03, -0.04]} t={[0.14, 0.06, 0.56]} cor={C.ferro} />
        </group>
      ))}
    </group>
  );
};

/** Árvore num canteiro redondo de tijolo: tronco que entra na copa, copa grande e uma copa menor de lado. */
const Arvore: React.FC<{ p: V3 }> = ({ p }) => (
  <group position={p}>
    <Cilindro p={[0, 0, 0]} r={0.8} h={0.32} cor={C.tijolo} seg={24} />
    <Cilindro p={[0, 0, 0]} r={0.66} h={0.28} cor={C.terra} seg={24} sombra={false} />
    <Haste a={[0, 0.28, 0]} b={[0, 2.5, 0]} r={0.17} cor={C.tronco} />
    <Haste a={[0, 1.6, 0]} b={[0.5, 2.15, 0.15]} r={0.1} cor={C.tronco} />
    <mesh position={[0, 2.8, 0]} material={mat(C.folha, { flat: true })} castShadow receiveShadow><icosahedronGeometry args={[1.0, 0]} /></mesh>
    <mesh position={[0.7, 2.3, 0.25]} material={mat(C.folha2, { flat: true })} castShadow receiveShadow><icosahedronGeometry args={[0.6, 0]} /></mesh>
  </group>
);

export const PatioEscola: React.FC = () => (
  <group>
    <PlanoFoco z={-1.0} />
    <Chao />
    <Amarelinha x={0} z={-1.6} />
    <Predio />
    <Banco p={[-3.0, 0, -2.6]} />
    <Arvore p={[3.8, 0, -4.2]} />
    {/* lixeira ao lado do banco, afastada dele */}
    <Cilindro p={[-4.35, 0, -2.9]} r={0.2} r2={0.17} h={0.6} cor="#e8664a" />
    <Cilindro p={[-4.35, 0.6, -2.9]} r={0.22} h={0.06} cor="#c8503a" />
  </group>
);
