// Efeito `noite`: a cena vira noite azul e a luz quente vem só do celular (na mão) e de um abajur (à direita).
// Como funciona: as luzes que já estão na cena (céu e sol do kit/Luz) são escurecidas e puxadas para o azul, sem apagar
// o cenário; o fundo vira azul-noite; entram a luz do celular (spot de baixo para cima no rosto), a do abajur (pontual,
// curta, com sombra) e um preenchimento azul baixo para os pés. Tudo volta ao original quando o efeito sai da cena.
import * as THREE from 'three';
import React, { useLayoutEffect, useMemo } from 'react';
import { useThree } from '@react-three/fiber';
import { mat, suave, type V3 } from './base';

const C = {
  ceu: '#24305a', ceuLuz: '#5d77c0', chaoLuz: '#2a3456', lua: '#9db3ee', preenche: '#7d9cf0',
  quente: '#ffb45c', cupula: '#ffd9a0', lampada: '#fff1cf', tela: '#ffe2b0',
  madeira: '#8a5a3a', madeiraEsc: '#6e452c', metal: '#3a3a44', capa: '#2d6cdf', tapete: '#8a5aa8', tapeteBorda: '#6b4386',
};
const NOITE = '__noite';

type Original = { intensidade: number; cor: THREE.Color; chao?: THREE.Color };

/** Escurece e azula as luzes que não são do efeito; `k` 0..1 é o quanto já anoiteceu. */
function useAnoitecer(k: number) {
  const scene = useThree((s) => s.scene);
  useLayoutEffect(() => {
    const luzes: [THREE.Light, Original][] = [];
    scene.traverse((o) => {
      const l = o as THREE.Light;
      if (!l.isLight || l.userData[NOITE]) return;
      const ud = l.userData as { noiteOrig?: Original };
      if (!ud.noiteOrig) {
        const h = l as THREE.HemisphereLight;
        ud.noiteOrig = { intensidade: l.intensity, cor: l.color.clone(), chao: h.isHemisphereLight ? h.groundColor.clone() : undefined };
      }
      luzes.push([l, ud.noiteOrig]);
    });
    for (const [l, o] of luzes) {
      const h = l as THREE.HemisphereLight;
      // céu: ar azul que ainda deixa ler o cenário; sol: vira lua (azul, mais fraca, mantém a sombra suave)
      const fator = h.isHemisphereLight ? 0.85 : (l as THREE.DirectionalLight).isDirectionalLight ? 0.3 : 0.35;
      l.intensity = o.intensidade * (1 + (fator - 1) * k);
      l.color.copy(o.cor).lerp(new THREE.Color(h.isHemisphereLight ? C.ceuLuz : C.lua), k);
      if (h.isHemisphereLight && o.chao) h.groundColor.copy(o.chao).lerp(new THREE.Color(C.chaoLuz), k);
    }
    // fundo (céu da cena)
    const ud = scene.userData as { noiteFundo?: THREE.Color };
    const fundo = scene.background as THREE.Color | null;
    if (fundo && (fundo as THREE.Color).isColor) {
      if (!ud.noiteFundo) ud.noiteFundo = fundo.clone();
      fundo.copy(ud.noiteFundo).lerp(new THREE.Color(C.ceu), k);
    }
  });
  // ao sair de cena, devolve tudo como estava
  useLayoutEffect(() => () => {
    scene.traverse((o) => {
      const l = o as THREE.Light;
      const orig = (l.userData as { noiteOrig?: Original }).noiteOrig;
      if (!l.isLight || !orig) return;
      l.intensity = orig.intensidade; l.color.copy(orig.cor);
      if (orig.chao) (l as THREE.HemisphereLight).groundColor.copy(orig.chao);
      delete l.userData.noiteOrig;
    });
    const ud = scene.userData as { noiteFundo?: THREE.Color };
    if (ud.noiteFundo && scene.background && (scene.background as THREE.Color).isColor) (scene.background as THREE.Color).copy(ud.noiteFundo);
    delete ud.noiteFundo;
  }, [scene]);
}

/** Criado-mudo com abajur de mesa (cúpula acesa). Origem no chão, frente para +Z. Lâmpada a 0,83 m. */
const Abajur: React.FC<{ aceso: number }> = ({ aceso }) => (
  <group>
    {/* criado-mudo: corpo, tampo, gaveta e puxador */}
    <mesh position={[0, 0.25, 0]} material={mat(C.madeira)} castShadow receiveShadow><boxGeometry args={[0.46, 0.5, 0.4]} /></mesh>
    <mesh position={[0, 0.52, 0]} material={mat(C.madeiraEsc)} castShadow receiveShadow><boxGeometry args={[0.5, 0.04, 0.44]} /></mesh>
    <mesh position={[0, 0.33, 0.21]} material={mat(C.madeiraEsc)} receiveShadow><boxGeometry args={[0.38, 0.16, 0.02]} /></mesh>
    <mesh position={[0, 0.33, 0.23]} material={mat(C.metal)}><sphereGeometry args={[0.022, 10, 8]} /></mesh>
    {/* abajur: base, haste, lâmpada e cúpula (sem halo: a cúpula acesa basta) */}
    <mesh position={[0, 0.565, 0]} material={mat(C.metal)} castShadow receiveShadow><cylinderGeometry args={[0.08, 0.1, 0.05, 20]} /></mesh>
    <mesh position={[0, 0.7, 0]} material={mat(C.metal)} castShadow><cylinderGeometry args={[0.014, 0.014, 0.24, 10]} /></mesh>
    <mesh position={[0, 0.83, 0]} material={mat(C.lampada, 1.5 * aceso)}><sphereGeometry args={[0.045, 14, 10]} /></mesh>
    <mesh position={[0, 0.88, 0]} material={mat(C.cupula, 0.2 + 0.6 * aceso)}>
      <cylinderGeometry args={[0.1, 0.17, 0.2, 24, 1, true]} />
    </mesh>
  </group>
);

/** Celular de 0,15 m: capa e tela acesa na face +Z. Origem no centro do aparelho. */
const Celular: React.FC<{ aceso: number }> = ({ aceso }) => (
  <group>
    <mesh material={mat(C.capa)} castShadow><boxGeometry args={[0.075, 0.15, 0.014]} /></mesh>
    <mesh position={[0, 0.004, 0.0085]} material={mat(C.tela, 1.2 * aceso)}><boxGeometry args={[0.064, 0.13, 0.003]} /></mesh>
  </group>
);

/** Tapete redondo que marca o "cantinho" (3,5 cm de altura, acima das linhas da quadra). */
const Tapete: React.FC = () => (
  <group>
    <mesh position={[0, 0.02, 0]} material={mat(C.tapeteBorda)} receiveShadow><cylinderGeometry args={[1.15, 1.15, 0.03, 40]} /></mesh>
    <mesh position={[0, 0.025, 0]} material={mat(C.tapete)} receiveShadow><cylinderGeometry args={[1.0, 1.0, 0.03, 40]} /></mesh>
  </group>
);

export type PropsNoite = {
  quadro: number;
  /** Onde fica o criado-mudo com abajur (no chão); `null` = cena já tem o abajur, só a luz em `luzAbajur`. */
  abajur?: V3 | null;
  /** Luz do abajur quando `abajur` é null (posição da lâmpada). */
  luzAbajur?: V3;
  /** Centro do celular; padrão: na mão direita do boneco parado na origem. `null` = sem celular. */
  celular?: V3 | null;
  /** Desenha o aparelho (false quando o personagem já segura um). */
  mostrarCelular?: boolean;
  /** Para onde a luz da tela aponta (o rosto). */
  rosto?: V3;
  /** Tapete redondo sob o personagem e o criado-mudo (false quando o cenário já é um quarto). */
  tapete?: V3 | null;
  /** Quadros para anoitecer (0 = já começa de noite). */
  transicao?: number;
};

export const Noite: React.FC<PropsNoite> = ({
  quadro, abajur = [1.0, 0.04, -0.2], luzAbajur, celular = [0.34, 0.68, 0.13], mostrarCelular = true,
  rosto = [0.05, 1.42, 0.3], tapete = [0.4, 0, -0.05], transicao = 20,
}) => {
  const k = transicao > 0 ? suave(quadro / transicao) : 1;
  useAnoitecer(k);
  // as luzes quentes acendem logo depois de escurecer; a tela "respira" de leve
  const aceso = suave((quadro - transicao * 0.4) / Math.max(1, transicao * 0.6));
  const tela = aceso * (0.92 + 0.08 * Math.sin(quadro * 0.21) * Math.sin(quadro * 0.07));

  const lampada: V3 | null = abajur ? [abajur[0], abajur[1] + 0.83, abajur[2]] : luzAbajur ?? null;
  // alvo do spot do celular (o rosto); precisa estar na cena para o three atualizar a matriz
  const alvo = useMemo(() => new THREE.Object3D(), []);
  alvo.position.set(...rosto);
  // luz do celular: logo acima da tela, mirando o rosto de baixo para cima
  const luzCel: V3 | null = celular ? [celular[0] - 0.02, celular[1] + 0.06, celular[2] + 0.05] : null;

  return (
    <group>
      {tapete && <group position={tapete}><Tapete /></group>}
      {lampada && (
        <pointLight userData={{ [NOITE]: true }} position={lampada} color={C.quente} intensity={2.2 * aceso} distance={2.6} decay={2}
          castShadow shadow-mapSize={[1024, 1024]} shadow-bias={-0.002} shadow-radius={6} />
      )}
      {abajur && <group position={abajur}><Abajur aceso={aceso} /></group>}
      {celular && luzCel && (
        <group>
          <primitive object={alvo} />
          <spotLight userData={{ [NOITE]: true }} position={luzCel} target={alvo} color={C.quente} intensity={3.5 * tela}
            distance={2} decay={2} angle={0.42} penumbra={0.8} />
          {mostrarCelular && (
            // tela virada para cima e para a frente (o rosto e a câmera veem a luz)
            <group position={celular} rotation={[-0.85, -0.2, 0]}><Celular aceso={tela} /></group>
          )}
        </group>
      )}
      {/* preenchimento azul baixo e frontal: tênis e pernas não somem no escuro */}
      <pointLight userData={{ [NOITE]: true }} position={[0, 0.4, 2.4]} color={C.preenche} intensity={2.2 * k} distance={5} decay={2} />
    </group>
  );
};
