// Fundo distante, sem chão. A faixa de estrelas deixa uma clareira central.
import React from 'react';
import * as THREE from 'three';
import { random } from 'remotion';
import type { LimitesCenario } from '../tipos';
import { mat, type V3 } from './base';

export const LIMITES_ESPACO: LimitesCenario = {
  limiteX: 8, limiteZ: [-5, 4], ceu: '#0b1534',
};

// Plano primitivo com cores nos vértices, sem textura nem shader próprio.
const fundo = new THREE.PlaneGeometry(84, 54, 56, 36);
const posicoes = fundo.getAttribute('position');
const cores = new Float32Array(posicoes.count * 3);
const marinho = new THREE.Color('#0b1534');
const violeta = new THREE.Color('#242344');
const halo = new THREE.Color('#222e50');
for (let i = 0; i < posicoes.count; i++) {
  const x = posicoes.getX(i), y = posicoes.getY(i);
  const luz = Math.exp(-1.6 * ((x / 15) ** 2 + (y / 11) ** 2));
  const roxo = Math.exp(-2 * (((x + 8) / 17) ** 2 + ((y - 4) / 12) ** 2));
  const cor = marinho.clone().lerp(violeta, roxo * 0.6).lerp(halo, luz * 0.85);
  cor.toArray(cores, i * 3);
}
fundo.setAttribute('color', new THREE.BufferAttribute(cores, 3));

const tons = [
  { cor: '#586582', brilho: 0.25 },
  { cor: '#8d9bb8', brilho: 0.4 },
  { cor: '#c9d1df', brilho: 0.55 },
  { cor: '#f4f3ed', brilho: 0.7 },
];

const estrelas = Array.from({ length: 220 }, (_, i) => {
  const acaso = (parte: string) => random(`l02-espaco-v2-${i}-${parte}`);
  const x = (acaso('x') - 0.5) * 48;
  const y = i < 95
    ? (acaso('y') - 0.5) * 28
    : 0.42 * x + 5 + (acaso('y') + acaso('largura') - 1) * 5;
  const z = -14 - acaso('z') * 8;
  // A clareira cresce com a distância, protegendo as silhuetas na vitrine.
  const distancia = (5.7 - z) / 23.7;
  const central = (x / (6.8 * distancia)) ** 2
    + ((y + 1.8 * distancia) / (5.8 * distancia)) ** 2;
  return {
    p: [x, y, z] as V3,
    raio: 0.04 + acaso('raio') ** 2 * 0.065,
    tom: tons[Math.floor(acaso('tom') ** 1.8 * tons.length)],
    central,
  };
}).filter((estrela) => estrela.central > 1);

export const Espaco: React.FC = () => (
  <group>
    <mesh position={[-1, -2.5, -28]} geometry={fundo} material={mat('#ffffff', 0, true)} />
    {estrelas.map(({ p, raio, tom }, i) => (
      <mesh key={i} position={p} material={mat(tom.cor, tom.brilho)}>
        <sphereGeometry args={[raio, 12, 8]} />
      </mesh>
    ))}
  </group>
);
