// Ficha de cena: o ÚNICO formato que o Claude preenche. Schema fechado (sem campos extras) + regras de coerência.
// Qualquer coisa fora do catálogo ou incoerente é RECUSADA com mensagem clara; nada é "adivinhado".
import { z } from 'zod';
import { foraDoQuadro } from './enquadramento';
import { ACOES, ANGULOS, BOCAS, CENARIOS, DURACAO, EFEITOS, MOVIMENTOS, NOMES_CENARIOS, OBJETOS, OLHARES, PERSONAGENS, PLANOS } from './catalogo';

const XZ = z.tuple([z.number(), z.number()]);
const Quadro = z.number().int().min(0);

const Acao = z.strictObject({
  q: Quadro, acao: z.enum(ACOES),
  ate: XZ.optional(), // obrigatório quando acao = "andar"
});
const Expr = z.strictObject({
  q: Quadro, boca: z.enum(BOCAS).default('neutra'),
  sobrancelha: z.enum(['brava', 'normal', 'surpresa']).default('normal'),
  olhar: z.enum(OLHARES).default('frente'),
});
const Personagem = z.strictObject({
  id: z.enum(PERSONAGENS),
  pos: XZ, giro: z.number().min(-180).max(180).default(0),
  acoes: z.array(Acao).min(1),
  expressoes: z.array(Expr).min(1),
  // quadros [início, fim] de cada palavra que ESTE personagem fala (vem da voz): a boca mexe só aí
  falando: z.array(z.tuple([Quadro, Quadro])).optional(),
});
const Camera = z.strictObject({
  plano: z.enum(PLANOS), angulo: z.enum(ANGULOS).default('frente'),
  movimento: z.enum(MOVIMENTOS).default('parado'),
  alvo: z.union([z.string(), z.array(z.string()).min(1).max(4)]), // 1 personagem ou um grupo; a câmera enquadra todos
  de: z.string().optional(), // plano "ombro": por cima do ombro de quem
});

export const FichaSchema = z.strictObject({
  versao: z.literal(1),
  id: z.string().regex(/^[a-z0-9-]{3,40}$/, 'id só com letras minúsculas, números e hífen'),
  duracao: z.number().int().min(DURACAO.min).max(DURACAO.max),
  cenario: z.enum(NOMES_CENARIOS),
  personagens: z.array(Personagem).min(1).max(6),
  camera: Camera,
  bola: z.strictObject({ pos: XZ }).optional(),
  // objetos da oficina: no chão/mesa numa posição, ou na mão de um personagem
  objetos: z.array(z.strictObject({ nome: z.enum(OBJETOS), pos: XZ.optional(), de: z.enum(PERSONAGENS).optional() })).max(6).optional(),
  // efeitos da oficina, em volta de um personagem (padrão: o primeiro alvo da câmera)
  efeitos: z.array(z.strictObject({ nome: EFEITOS.length ? z.enum(EFEITOS as [string, ...string[]]) : z.never(), em: z.enum(PERSONAGENS).optional() })).max(3).optional(),
  // contador do canto (HUD): o mesmo do ato
  hud: z.strictObject({ rotulo: z.string().max(24), valor: z.string().max(40), grande: z.boolean().optional() }).optional(), // grande = virada do dia: aparece grande e encolhe para o canto
  luz: z.enum(['dia', 'noite', 'abajur']).optional(),
  // tela 2D nítida por cima (plano detalhe de celular/papel): texto LEGÍVEL, nunca texto 3D falso
  tela: z.strictObject({ tipo: z.enum(['celular', 'papel']), titulo: z.string().max(40).optional(), linhas: z.array(z.strictObject({ de: z.enum(['eu', 'outro', 'sistema']), texto: z.string().max(120) })).max(6) }).optional(),
}).superRefine((f, ctx) => {
  const erro = (path: (string | number)[], message: string) => ctx.addIssue({ code: 'custom', path, message });
  const lim = CENARIOS[f.cenario];
  const dentro = ([x, zz]: [number, number]) => Math.abs(x) <= lim.limiteX && zz >= lim.limiteZ[0] && zz <= lim.limiteZ[1];
  const ids = new Set<string>();
  f.personagens.forEach((p, i) => {
    if (ids.has(p.id)) erro(['personagens', i, 'id'], `personagem "${p.id}" repetido`);
    ids.add(p.id);
    if (!dentro(p.pos)) erro(['personagens', i, 'pos'], `posição fora do cenário "${f.cenario}"`);
    for (const [nome, lista] of [['acoes', p.acoes], ['expressoes', p.expressoes]] as const) {
      if (lista[0].q !== 0) erro(['personagens', i, nome, 0, 'q'], 'a primeira entrada tem de começar no quadro 0');
      lista.forEach((e, k) => {
        if (e.q >= f.duracao) erro(['personagens', i, nome, k, 'q'], `quadro ${e.q} passa da duração (${f.duracao})`);
        if (k > 0 && e.q <= lista[k - 1].q) erro(['personagens', i, nome, k, 'q'], 'quadros têm de ser crescentes');
      });
    }
    p.acoes.forEach((a, k) => {
      if (a.acao === 'andar' && !a.ate) erro(['personagens', i, 'acoes', k, 'ate'], '"andar" precisa de destino "ate"');
      if (a.acao !== 'andar' && a.ate) erro(['personagens', i, 'acoes', k, 'ate'], '"ate" só vale para "andar"');
      if (a.ate && !dentro(a.ate)) erro(['personagens', i, 'acoes', k, 'ate'], 'destino fora do cenário');
      if (a.acao === 'andar') {
        const fim = k + 1 < p.acoes.length ? p.acoes[k + 1].q : f.duracao;
        if (fim - a.q < 20) erro(['personagens', i, 'acoes', k], '"andar" precisa de pelo menos 20 quadros');
      }
    });
  });
  // personagens não podem se atravessar na posição inicial nem no destino
  const pontos = f.personagens.flatMap((p) => [{ id: p.id, xz: p.pos }, ...p.acoes.filter((a) => a.ate).map((a) => ({ id: p.id, xz: a.ate! }))]);
  for (let a = 0; a < pontos.length; a++) for (let b = a + 1; b < pontos.length; b++) {
    if (pontos[a].id === pontos[b].id) continue;
    const d = Math.hypot(pontos[a].xz[0] - pontos[b].xz[0], pontos[a].xz[1] - pontos[b].xz[1]);
    if (d < 0.8) erro(['personagens'], `"${pontos[a].id}" e "${pontos[b].id}" ficam a ${d.toFixed(2)} m (mínimo 0,8 m)`);
  }
  // quem anda não pode atravessar outro personagem parado no caminho
  const distSeg = (p: [number, number], a: [number, number], b: [number, number]) => {
    const vx = b[0] - a[0], vz = b[1] - a[1], L = vx * vx + vz * vz || 1;
    const t = Math.max(0, Math.min(1, ((p[0] - a[0]) * vx + (p[1] - a[1]) * vz) / L));
    return Math.hypot(p[0] - a[0] - vx * t, p[1] - a[1] - vz * t);
  };
  f.personagens.forEach((p, i) => {
    let de = p.pos as [number, number];
    p.acoes.forEach((a, k) => {
      if (!a.ate) return;
      for (const o of f.personagens) if (o.id !== p.id && !o.acoes.some((x) => x.ate) && distSeg(o.pos as [number, number], de, a.ate as [number, number]) < 0.6)
        erro(['personagens', i, 'acoes', k], `"${p.id}" atravessa "${o.id}" no caminho`);
      de = a.ate as [number, number];
    });
  });
  for (const a of [f.camera.alvo].flat()) if (!ids.has(a)) erro(['camera', 'alvo'], `alvo "${a}" não está na cena`);
  if (f.camera.plano === 'ombro' && (!f.camera.de || !ids.has(f.camera.de) || [f.camera.alvo].flat().includes(f.camera.de))) erro(['camera', 'de'], 'plano "ombro" precisa de "de" (outro personagem da cena)');
  if (f.bola && !dentro(f.bola.pos)) erro(['bola', 'pos'], 'bola fora do cenário');
  (f.objetos ?? []).forEach((o, i) => {
    if (!o.pos && !o.de) erro(['objetos', i], 'objeto precisa de pos ou de "de" (personagem que segura)');
    if (o.de && !ids.has(o.de)) erro(['objetos', i, 'de'], 'personagem "' + o.de + '" não está na cena');
    if (o.pos && !dentro(o.pos)) erro(['objetos', i, 'pos'], 'objeto fora do cenário');
  });
  (f.efeitos ?? []).forEach((e, i) => { if (e.em && !ids.has(e.em)) erro(['efeitos', i, 'em'], 'personagem "' + e.em + '" não está na cena'); });
});

export type Ficha = z.output<typeof FichaSchema>;
export type FichaEntrada = z.input<typeof FichaSchema>;

/** Valida e devolve a ficha normalizada, ou lança erro com TODOS os problemas listados. */
export function validarFicha(dado: unknown): Ficha {
  const r = FichaSchema.safeParse(dado);
  if (!r.success) {
    const linhas = r.error.issues.map((i) => `- ${i.path.join('.') || '(raiz)'}: ${i.message}`);
    throw new Error(`Ficha recusada:\n${linhas.join('\n')}`);
  }
  const fora = foraDoQuadro(r.data);
  if (fora.length) throw new Error(`Ficha recusada:\n${fora.map((m) => `- camera: ${m}`).join('\n')}`);
  return r.data;
}
