import React from 'react';
import * as THREE from 'three';

export type V3 = [number, number, number];
export type V2 = [number, number];

const cache = new Map<string, THREE.MeshStandardMaterial>();
export const mat = (cor: string, brilho = 0) => {
  const chave = `${cor}|${brilho}`;
  let material = cache.get(chave);
  if (!material) {
    material = new THREE.MeshStandardMaterial({ color: cor, roughness: 0.85 });
    // Emissão só na tela, sem luz extra no palco.
    if (brilho > 0) {
      material.emissive.set(cor);
      material.emissiveIntensity = brilho;
    }
    cache.set(chave, material);
  }
  return material;
};

export const Caixa: React.FC<{ p: V3; t: V3; cor: string; r?: V3; sombra?: boolean; brilho?: number }> = ({ p, t, cor, r, sombra = true, brilho = 0 }) => (
  <mesh position={p} rotation={r} material={mat(cor, brilho)} castShadow={sombra} receiveShadow>
    <boxGeometry args={t} />
  </mesh>
);

// Traços no plano XY, voltados para +Z.
export const Traco: React.FC<{ a: V2; b: V2; z: number; cor: string; largura?: number; espessura?: number }> = ({ a, b, z, cor, largura = 0.003, espessura = 0.0008 }) => (
  <Caixa p={[(a[0] + b[0]) / 2, (a[1] + b[1]) / 2, z]}
    t={[Math.hypot(b[0] - a[0], b[1] - a[1]) + largura, largura, espessura]}
    r={[0, 0, Math.atan2(b[1] - a[1], b[0] - a[0])]} cor={cor} sombra={false} />
);

// Duas caixas e quatro cilindros: cantos arredondados sem malha externa.
export const Retangulo: React.FC<{ p: V3; w: number; h: number; d: number; raio: number; cor: string; sombra?: boolean; brilho?: number }> = ({ p, w, h, d, raio, cor, sombra = true, brilho = 0 }) => (
  <group position={p}>
    <Caixa p={[0, 0, 0]} t={[w - 2 * raio, h, d]} cor={cor} sombra={sombra} brilho={brilho} />
    <Caixa p={[0, 0, 0]} t={[w, h - 2 * raio, d]} cor={cor} sombra={sombra} brilho={brilho} />
    {([-1, 1] as const).flatMap((x) => ([-1, 1] as const).map((y) => (
      <mesh key={`${x}-${y}`} position={[x * (w / 2 - raio), y * (h / 2 - raio), 0]}
        rotation={[Math.PI / 2, 0, 0]} material={mat(cor, brilho)} castShadow={sombra} receiveShadow>
        <cylinderGeometry args={[raio, raio, d, 12]} />
      </mesh>
    )))}
  </group>
);

// Coordenadas normalizadas: segmentos a, b, c, d, e, f, g.
const SEGMENTOS: [V2, V2][] = [
  [[0, 1], [0.5, 1]], [[0.5, 1], [0.5, 0.5]],
  [[0.5, 0.5], [0.5, 0]], [[0, 0], [0.5, 0]],
  [[0, 0.5], [0, 0]], [[0, 1], [0, 0.5]], [[0, 0.5], [0.5, 0.5]],
];
const DIGITOS: Record<string, number[]> = {
  '0': [0, 1, 2, 3, 4, 5], '2': [0, 1, 6, 4, 3],
  '3': [0, 1, 6, 2, 3], '4': [5, 6, 1, 2], '5': [0, 5, 6, 2, 3],
  '6': [0, 5, 6, 4, 2, 3], '7': [0, 1, 2], '8': [0, 1, 2, 3, 4, 5, 6],
  '9': [0, 1, 2, 3, 5, 6],
};
export const Glifo: React.FC<{ valor: string; x: number; y: number; z: number; altura: number; cor: string; largura?: number }> = ({ valor, x, y, z, altura, cor, largura = altura * 0.12 }) => {
  let linhas: [V2, V2][];
  if (valor === '1') {
    // Gancho e pé distinguem o algarismo de uma letra I.
    linhas = [[[0.05, 0.8], [0.25, 1]], [[0.25, 1], [0.25, 0]], [[0.02, 0], [0.48, 0]]];
  } else if (valor === '+' || valor === '=') {
    linhas = valor === '+'
      ? [[[0, 0.5], [0.5, 0.5]], [[0.25, 0.25], [0.25, 0.75]]]
      : [[[0, 0.65], [0.5, 0.65]], [[0, 0.35], [0.5, 0.35]]];
  } else {
    linhas = (DIGITOS[valor] ?? []).map((i) => SEGMENTOS[i]);
  }
  return <group>{linhas.map(([a, b], i) => (
    <Traco key={i} a={[x + a[0] * altura, y + a[1] * altura]}
      b={[x + b[0] * altura, y + b[1] * altura]} z={z} cor={cor} largura={largura} />
  ))}</group>;
};
