// Objeto: ônibus urbano grande (12 x 2,5 x 3,4 m) de caixas, branco com faixa vermelha, janelas azuis lotadas de passageiros.
// Comprimento em X com a FRENTE para +X (anda para +X); lado direito (+Z) com as duas portas. Origem no centro da base, chão em y = 0.
import * as THREE from 'three';
import React from 'react';
import { random } from 'remotion';
import { mat, Caixa, Cilindro, Esfera } from './base';

export const L = 12, W = 2.5;
const RC = 0.22;               // raio dos cantos verticais
const Z = W / 2;               // face lateral
export const RODA = 0.52;      // raio da roda (≈ 1 m de diâmetro)
export const EIXOS = [3.5, -3.0];    // x dos eixos (frente, trás)
const PORTAS: [number, number][] = [[4.62, 5.72], [-0.9, 0.3]]; // lado direito (+Z): dianteira e do meio
const Y_JAN = [1.62, 2.62];    // faixa das janelas laterais

const C = {
  branco: '#f6f5f0', vermelho: '#d8312f', borracha: '#2a2d33', interior: '#1d3554', vidro: '#7fc0ff',
  pneu: '#1b1b1d', aro: '#c7ccd2', miolo: '#5d636b', arco: '#26282c', farol: '#fff4c8', lanterna: '#ff3b30', seta: '#ffab2e',
  cinza: '#d9dde2', placa: '#121418', led: '#ffb020', porta: '#2e5f8e',
};
const PELE = ['#f2c7a5', '#d9a27a', '#a86e4a', '#7a4a2e', '#f5d6bd', '#c58c63'];
const CABELO = ['#2b1d14', '#4a2f1d', '#111111', '#7a4b24', '#c9a15a', '#5b5b5b', '#2b1d14'];
const ROUPA = ['#e74c3c', '#3498db', '#2ecc71', '#f1c40f', '#9b59b6', '#ffffff', '#ff8a1f', '#34495e', '#e84393', '#16a085'];
const pega = <T,>(lista: T[], s: string) => lista[Math.floor(random(s) * lista.length) % lista.length];

/** Bloco com a planta de cantos arredondados (no plano XZ), de y0 a y1. `folga` engorda a planta (faixa por cima do corpo). */
const Bloco: React.FC<{ y0: number; y1: number; m: THREE.Material; x0?: number; x1?: number; folga?: number; sombra?: boolean }> = ({ y0, y1, m, x0 = -L / 2, x1 = L / 2, folga = 0, sombra = true }) => {
  const h = y1 - y0, y = (y0 + y1) / 2, cx = (x0 + x1) / 2, cl = x1 - x0 + 2 * folga, w = W + 2 * folga, r = RC + folga;
  return (
    <group position={[cx, y, 0]}>
      <Caixa p={[0, 0, 0]} t={[cl, h, w - 2 * r]} m={m} sombra={sombra} />
      <Caixa p={[0, 0, 0]} t={[cl - 2 * r, h, w]} m={m} sombra={sombra} />
      {([[-1, -1], [1, -1], [-1, 1], [1, 1]] as const).map(([sx, sz]) => (
        <Cilindro key={`${sx}${sz}`} p={[sx * (cl / 2 - r), 0, sz * (w / 2 - r)]} r={r} h={h} m={m} seg={20} sombra={sombra} />
      ))}
    </group>
  );
};

/** Passageiro (cabeça, cabelo, ombros e às vezes o braço na barra), entre o fundo escuro e o vidro. */
const Passageiro: React.FC<{ x: number; lado: 1 | -1; s: string; fundo?: boolean }> = ({ x, lado, s, fundo = false }) => {
  const emPe = fundo || random(`${s}-pe`) > 0.35;
  // alturas bem variadas (sentados, em pé, altos, baixos); a fileira de trás aparece entre as cabeças da frente
  const yc = (emPe ? 2.3 : 2.0) + (random(`${s}-y`) - 0.5) * 0.22 + (fundo ? 0.06 : 0);
  const z = lado * (Z - (fundo ? 0.45 : 0.17)), zo = lado * (Z - (fundo ? 0.48 : 0.2));
  const k = 0.9 + random(`${s}-k`) * 0.25; // tamanho da pessoa
  const cabelo = random(`${s}-cab`);
  const roupa = mat(pega(ROUPA, `${s}-r`));
  return (
    <group position={[x, 0, 0]}>
      {/* ombros: cápsula deitada ao longo do ônibus */}
      <mesh position={[0, yc - 0.28 * k, zo]} rotation={[0, 0, Math.PI / 2]} scale={[k, k, k]} material={roupa}><capsuleGeometry args={[0.15, 0.2, 4, 10]} /></mesh>
      <Esfera p={[0, yc, z]} r={0.13 * k} m={mat(pega(PELE, `${s}-p`))} sombra={false} />
      {cabelo < 0.8 && <Esfera p={[0, yc + 0.045 * k, z - lado * 0.014]} r={0.134 * k} esc={[1, cabelo < 0.3 ? 0.75 : 0.62, 1]} m={mat(pega(CABELO, `${s}-c`))} sombra={false} />}
      {/* em pé, metade segura a barra do teto */}
      {!fundo && emPe && random(`${s}-b`) > 0.5 && (
        <mesh position={[0.14, yc + 0.1, zo]} rotation={[0, 0, -0.25]} material={roupa}><capsuleGeometry args={[0.05, 0.4, 4, 8]} /></mesh>
      )}
    </group>
  );
};

/** Lista de x de janelas (vãos) num lado: corta as portas no lado direito. */
const vaos = (lado: 1 | -1): [number, number][] => {
  const ini = -L / 2 + 0.45, fim = lado === 1 ? PORTAS[0][0] - 0.06 : L / 2 - 0.35;
  const trechos: [number, number][] = lado === 1 ? [[ini, PORTAS[1][0] - 0.06], [PORTAS[1][1] + 0.06, fim]] : [[ini, fim]];
  const out: [number, number][] = [];
  for (const [a, b] of trechos) {
    const n = Math.max(1, Math.round((b - a) / 1.3)), p = (b - a) / n;
    for (let i = 0; i < n; i++) out.push([a + i * p, a + (i + 1) * p]);
  }
  return out;
};

const Lateral: React.FC<{ lado: 1 | -1 }> = ({ lado }) => {
  const v = vaos(lado), yj = (Y_JAN[0] + Y_JAN[1]) / 2, hj = Y_JAN[1] - Y_JAN[0];
  const vidro = mat(C.vidro, { opac: 0.16, rug: 0.25 }); // vidro limpo, sem reflexo: o povo aparece
  const branco = mat(C.branco), borracha = mat(C.borracha);
  // passageiros apertados: um a cada ~30 cm (ombro com ombro), mais uma fileira de trás
  const pass: number[] = [];
  for (const [a, b] of v) for (let x = a + 0.18; x < b - 0.1; x += 0.3) pass.push(x + (random(`px-${lado}-${x.toFixed(2)}`) - 0.5) * 0.05);
  return (
    <group>
      {/* peitoril branco sob as janelas e colunas entre os vidros */}
      <Caixa p={[0, 1.46, lado * (Z - 0.04)]} t={[L - 2 * RC, 0.32, 0.08]} m={branco} />
      {v.flatMap(([a, b], i) => [a, ...(i === v.length - 1 ? [b] : [])]).map((x, i) => (
        <Caixa key={i} p={[x, yj, lado * (Z - 0.04)]} t={[0.13, hj, 0.08]} m={branco} />
      ))}
      {/* borrachas pretas em cima e embaixo da faixa de vidro */}
      <Caixa p={[0, Y_JAN[0], lado * (Z - 0.035)]} t={[L - 2 * RC, 0.045, 0.09]} m={borracha} sombra={false} />
      <Caixa p={[0, Y_JAN[1], lado * (Z - 0.035)]} t={[L - 2 * RC, 0.04, 0.09]} m={borracha} sombra={false} />
      {v.map(([a, b], i) => (
        <Caixa key={i} p={[(a + b) / 2, yj, lado * (Z - 0.022)]} t={[b - a - 0.1, hj - 0.04, 0.01]} m={vidro} sombra={false} recebe={false} />
      ))}
      {/* barra do teto e o povo */}
      <Cilindro p={[0, 2.56, lado * (Z - 0.2)]} r={0.025} h={L - 1.4} eixo="x" m={mat(C.cinza)} sombra={false} />
      {pass.map((x, i) => <Passageiro key={i} x={x} lado={lado} s={`pas-${lado}-${i}`} />)}
      {pass.filter((_, i) => i % 2 === 0).map((x, i) => <Passageiro key={`f${i}`} x={x + 0.15} lado={lado} s={`pf-${lado}-${i}`} fundo />)}
    </group>
  );
};

/** Porta de vidro de folha dupla (lado direito), por cima da carroceria. */
const Porta: React.FC<{ x0: number; x1: number }> = ({ x0, x1 }) => {
  const cx = (x0 + x1) / 2, w = x1 - x0;
  return (
    <group position={[cx, 0, Z]}>
      <Caixa p={[0, 1.5, 0.006]} t={[w, 2.2, 0.02]} m={mat(C.borracha)} sombra={false} />
      {[-1, 1].map((s) => (
        <group key={s}>
          <Caixa p={[s * w / 4, 1.52, 0.016]} t={[w / 2 - 0.09, 2.08, 0.01]} m={mat(C.porta, { rug: 0.3 })} sombra={false} />
          <Caixa p={[s * 0.07, 1.3, 0.026]} t={[0.04, 0.5, 0.02]} m={mat(C.cinza)} sombra={false} />
        </group>
      ))}
    </group>
  );
};

/** Roda: pneu, aro claro com 5 parafusos (mostram o giro) e miolo. `giro` em radianos. */
const Roda: React.FC<{ x: number; lado: 1 | -1; giro: number }> = ({ x, lado, giro }) => (
  <group position={[x, RODA, lado * (Z - 0.13)]} rotation={[0, 0, giro]}>
    <Cilindro p={[0, 0, 0]} r={RODA} h={0.3} eixo="z" m={mat(C.pneu)} seg={28} />
    <Cilindro p={[0, 0, lado * 0.15]} r={0.3} h={0.03} eixo="z" m={mat(C.aro)} />
    <Cilindro p={[0, 0, lado * 0.17]} r={0.11} h={0.03} eixo="z" m={mat(C.miolo)} sombra={false} />
    {[0, 1, 2, 3, 4].map((i) => {
      const a = (i / 5) * Math.PI * 2;
      return <Cilindro key={i} p={[Math.cos(a) * 0.2, Math.sin(a) * 0.2, lado * 0.17]} r={0.03} h={0.03} eixo="z" m={mat(C.miolo)} seg={10} sombra={false} />;
    })}
  </group>
);

// dígitos de 7 segmentos para o letreiro (a b c d e f g)
const SEG: Record<string, string> = { '1': 'bc', '2': 'abged', '5': 'afgcd' };
const Digito: React.FC<{ c: string; z: number; y: number }> = ({ c, z, y }) => {
  const w = 0.11, h = 0.17, s = 0.03, hx = w / 2 - s / 2, hy = h / 2 - s / 2;
  const seg: Record<string, [number, number, number, number]> = {
    a: [0, hy, w, s], d: [0, -hy, w, s], g: [0, 0, w, s],
    b: [hx, h / 4, s, h / 2], c: [hx, -h / 4, s, h / 2], e: [-hx, -h / 4, s, h / 2], f: [-hx, h / 4, s, h / 2],
  };
  // vista de frente (+X): o eixo "direita" do letreiro é -Z
  return <>{[...SEG[c]].map((k) => <Caixa key={k} p={[0, y + seg[k][1], z - seg[k][0]]} t={[0.01, seg[k][3], seg[k][2]]} m={mat(C.led, { brilho: 1.2 })} sombra={false} />)}</>;
};

const Frente: React.FC = () => {
  const xf = L / 2;
  return (
    <group>
      {/* para-brisa (vidro translúcido) com o fundo da cabine e o motorista atrás */}
      {/* piso escuro da cabine e painel */}
      <Caixa p={[xf - 0.75, 1.31, 0]} t={[1.4, 0.04, W - 0.3]} m={mat('#3a3f47')} sombra={false} />
      <Caixa p={[xf - 0.2, 1.42, 0]} t={[0.3, 0.2, W - 0.5]} m={mat(C.borracha)} sombra={false} />
      {/* vidro na frente das colunas dos cantos, com borracha em volta */}
      <Caixa p={[xf + 0.006, 1.97, 0]} t={[0.01, 1.28, W - 0.2]} m={mat(C.vidro, { opac: 0.3, rug: 0.25 })} sombra={false} recebe={false} />
      {/* borracha de cantos redondos: 4 cápsulas que se encontram em curvas */}
      {[1.35, 2.6].map((y) => (
        <mesh key={y} position={[xf + 0.012, y, 0]} rotation={[Math.PI / 2, 0, 0]} scale={[0.5, 1, 1]} material={mat(C.borracha)}>
          <capsuleGeometry args={[0.035, W - 0.3, 4, 10]} />
        </mesh>
      ))}
      {[-1, 1].map((s) => (
        <mesh key={s} position={[xf + 0.012, 1.975, s * (Z - 0.115)]} scale={[0.5, 1, 1]} material={mat(C.borracha)}>
          <capsuleGeometry args={[0.035, 1.25, 4, 10]} />
        </mesh>
      ))}
      {/* limpadores */}
      {[-1, 1].map((s) => <Caixa key={s} p={[xf + 0.02, 1.52, s * 0.42]} t={[0.015, 0.4, 0.025]} r={[s * 0.9, 0, 0]} m={mat(C.borracha)} sombra={false} />)}
      {/* motorista à esquerda (-Z) e volante */}
      <group position={[xf - 0.75, 0, -0.55]}>
        <mesh position={[0, 1.78, 0]} material={mat('#3d6fb0')}><capsuleGeometry args={[0.15, 0.2, 4, 10]} /></mesh>
        <Esfera p={[0, 2.08, 0]} r={0.11} m={mat(PELE[2])} sombra={false} />
        <Esfera p={[-0.02, 2.13, 0]} r={0.115} esc={[1, 0.6, 1]} m={mat(CABELO[2])} sombra={false} />
        <mesh position={[0.38, 1.72, 0]} rotation={[0, Math.PI / 2, 0.5]} material={mat(C.borracha)}><torusGeometry args={[0.2, 0.025, 8, 24]} /></mesh>
      </group>
      {/* passageiros em pé perto da porta */}
      <Passageiro x={xf - 0.75} lado={1} s="cab-1" />
      <Passageiro x={xf - 1.0} lado={1} s="cab-2" />
      {/* faróis: moldura escura de pontas redondas (cápsula deitada), dois faróis com aro e a seta na ponta */}
      {[-1, 1].map((s) => (
        <group key={s}>
          <mesh position={[xf + 0.012, 0.68, s * 0.66]} rotation={[Math.PI / 2, 0, 0]} scale={[0.4, 1, 1]} material={mat(C.borracha)}>
            <capsuleGeometry args={[0.13, 0.4, 4, 14]} />
          </mesh>
          {[0.47, 0.73].map((zf) => (
            <group key={zf} position={[xf + 0.07, 0.68, s * zf]} rotation={[0, Math.PI / 2, 0]}>
              <mesh material={mat(C.aro)}><torusGeometry args={[0.095, 0.018, 8, 24]} /></mesh>
              <mesh rotation={[Math.PI / 2, 0, 0]} material={mat(C.farol, { brilho: 0.9 })}><cylinderGeometry args={[0.088, 0.088, 0.02, 24]} /></mesh>
            </group>
          ))}
          <Esfera p={[xf + 0.05, 0.68, s * 0.94]} r={0.055} esc={[0.5, 1, 1]} m={mat(C.seta, { brilho: 0.6 })} sombra={false} />
          {/* retrovisores: braço e espelho preto */}
          <Caixa p={[xf + 0.14, 2.6, s * (Z + 0.06)]} t={[0.3, 0.05, 0.05]} r={[0, 0, -0.3]} m={mat(C.borracha)} />
          <Caixa p={[xf + 0.28, 2.3, s * (Z + 0.12)]} t={[0.06, 0.42, 0.2]} m={mat(C.placa)} />
        </group>
      ))}
      {/* para-choque */}
      <Caixa p={[xf + 0.05, 0.45, 0]} t={[0.12, 0.2, W - 0.12]} m={mat('#4a4f57')} />
      {/* letreiro de destino: número da linha em LED âmbar + "texto" em traços */}
      <Caixa p={[xf + 0.015, 2.86, 0]} t={[0.03, 0.3, 1.9]} m={mat(C.placa)} sombra={false} />
      <group position={[xf + 0.035, 0, 0]}>
        {['2', '1', '5'].map((c, i) => <Digito key={i} c={c} z={0.78 - i * 0.16} y={2.86} />)}
        {/* destino em duas linhas de "palavras" (vista de frente, a direita do letreiro é -Z) */}
        {([[2.91, 0.18, 0.3], [2.91, -0.2, 0.36], [2.91, -0.62, 0.26], [2.8, 0.13, 0.2], [2.8, -0.22, 0.44]] as const).map(([y, z, w], i) => (
          <Caixa key={i} p={[0, y, z]} t={[0.01, 0.06, w]} m={mat(C.led, { brilho: 1.2 })} sombra={false} />
        ))}
      </group>
    </group>
  );
};

const Traseira: React.FC = () => {
  const xt = -L / 2;
  return (
    <group>
      <Caixa p={[xt - 0.01, 2.15, 0]} t={[0.03, 0.85, W - 2 * RC - 0.1]} m={mat('#2c4a6a', { rug: 0.3 })} sombra={false} />
      {[-1, 1].map((s) => <Caixa key={s} p={[xt - 0.015, 0.85, s * (Z - 0.2)]} t={[0.03, 0.42, 0.14]} m={mat(C.lanterna, { brilho: 0.6 })} sombra={false} />)}
      {[0, 1, 2].map((i) => <Caixa key={i} p={[xt - 0.012, 1.52 - i * 0.1, 0]} t={[0.025, 0.05, 1.2]} m={mat(C.borracha)} sombra={false} />)}
      <Caixa p={[xt - 0.05, 0.45, 0]} t={[0.12, 0.2, W - 0.12]} m={mat('#4a4f57')} />
    </group>
  );
};

/** Ônibus parado no lugar. `andado` (m) gira as rodas como se tivesse rodado essa distância para +X. */
export const Onibus: React.FC<{ andado?: number; rastro?: boolean; quadro?: number }> = ({ andado = 0, rastro = false, quadro = 0 }) => {
  const branco = mat(C.branco), giro = -andado / RODA;
  return (
    <group>
      {/* carroceria: saia, faixa vermelha (1 cm para fora), faixa das janelas e teto */}
      <Bloco y0={0.4} y1={1.3} m={branco} />
      <Bloco y0={0.86} y1={1.16} m={mat(C.vermelho)} folga={0.008} sombra={false} />
      <Bloco y0={2.65} y1={3.12} m={branco} />
      {[[-1, -1], [1, -1], [-1, 1], [1, 1]].map(([sx, sz], i) => (
        // colunas da frente pretas (moldura do vidro que dobra a quina); as de trás, brancas
        <Cilindro key={i} p={[sx * (L / 2 - RC), 1.97, sz * (Z - RC)]} r={RC} h={1.36} m={sx === 1 ? mat(C.borracha) : branco} seg={20} />
      ))}
      {/* faixa vermelha fina no alto, só nas laterais */}
      {[-1, 1].map((s) => <Caixa key={s} p={[0, 2.86, s * (Z + 0.006)]} t={[L - 2 * RC, 0.1, 0.012]} m={mat(C.vermelho)} sombra={false} />)}
      {/* fundo escuro do salão (o "azul" das janelas) e parede da cabine */}
      <Caixa p={[-0.5, 1.97, 0]} t={[L - 1.9, 1.34, W - 0.6]} m={mat(C.interior)} sombra={false} />
      <Lateral lado={1} />
      <Lateral lado={-1} />
      {PORTAS.map(([a, b], i) => <Porta key={i} x0={a} x1={b} />)}
      <Frente />
      <Traseira />
      {/* ar-condicionado no teto */}
      <Caixa p={[-0.8, 3.24, 0]} t={[3.2, 0.24, 1.6]} m={mat(C.cinza)} />
      <Caixa p={[-0.8, 3.37, 0]} t={[2.6, 0.04, 1.2]} m={mat('#b9bfc7')} />
      {/* caixas de roda escuras (meio disco) e rodas */}
      {EIXOS.flatMap((x) => ([1, -1] as const).map((lado) => (
        <group key={`${x}${lado}`}>
          <mesh position={[x, RODA, lado * (Z + 0.008)]} rotation={[Math.PI / 2, 0, 0]} material={mat(C.arco)}>
            <cylinderGeometry args={[RODA + 0.1, RODA + 0.1, 0.012, 24, 1, false, Math.PI / 2, Math.PI]} />
          </mesh>
          <Roda x={x} lado={lado} giro={giro} />
        </group>
      )))}
      {rastro && <Rastro quadro={quadro} />}
    </group>
  );
};

/** Sinais de velocidade (opcional): 4 riscos grossos e longos saindo da traseira, e poeira atrás das rodas. */
const Rastro: React.FC<{ quadro: number }> = ({ quadro }) => {
  const risco = mat('#ffffff', { opac: 0.85, brilho: 0.5 }), poeira = mat('#e4ddd0', { opac: 0.6 });
  // [y, z, folga atrás da traseira, comprimento]: cápsulas de 18 cm de espessura, do lado de fora da carroceria
  const riscos: [number, number, number, number][] = [
    [0.9, Z + 0.35, 0.5, 6.5], [1.75, Z + 0.25, 1.4, 8.0], [2.55, Z + 0.3, 0.8, 7.0], [3.25, Z - 0.6, 1.8, 5.5],
  ];
  return (
    <group>
      {riscos.map(([y, z, f, c], i) => {
        const vai = ((quadro * 0.9 + i * 7) % 20) / 20; // escorregam para trás e voltam
        return (
          <mesh key={i} position={[-L / 2 - f - c / 2 - vai * 0.8, y, z]} rotation={[0, 0, Math.PI / 2]} material={risco}>
            <capsuleGeometry args={[0.09, c, 4, 10]} />
          </mesh>
        );
      })}
      {/* poeira: nuvens achatadas no chão, atrás das duas rodas, crescendo e ficando para trás */}
      {EIXOS.flatMap((xe, e) => [0, 1, 2, 3].map((i) => {
        const t = ((quadro + i * 6 + e * 3) % 24) / 24;
        return <Esfera key={`${e}${i}`} p={[xe - 0.75 - t * (e ? 3.2 : 1.6), 0.12 + t * 0.18, Z - 0.1 + t * 0.3]} r={(e ? 0.22 : 0.16) + t * 0.25} esc={[1.6, 0.7, 1]} m={poeira} sombra={false} />;
      }))}
    </group>
  );
};
