import React from 'react';
import { mat, Mosaico, numero, type Mancha } from './base';

const vermelho = '#e12636';
const prova: Mancha[] = [
  // O 1 tem haste, entrada e base largas. O zero é uma elipse contínua.
  { x: -0.036, y: 0.077, largura: 0.012, altura: 0.082, cor: vermelho },
  { x: -0.038, y: 0.112, largura: 0.024, altura: 0.012, cor: vermelho },
  { x: -0.036, y: 0.041, largura: 0.034, altura: 0.012, cor: vermelho },
  { x: 0, y: -0.015, largura: 0.151, altura: 0.012, cor: '#89939d' },
  { x: -0.014, y: -0.059, largura: 0.123, altura: 0.012, cor: '#89939d' },
  { x: -0.003, y: -0.103, largura: 0.145, altura: 0.012, cor: '#89939d' },
];

// Folha de 21 × 30 cm. Tinta encaixada na superfície, sem placas sobrepostas.
export const ProvaDez: React.FC = () => (
  <group position={[0, 0.0015, 0]} rotation={[-Math.PI / 2, 0, 0]}>
    <Mosaico largura={0.21} altura={0.3} espessura={0.003} cor="#ffffff" manchas={prova} />
    <mesh position={[0.026, 0.077, 0.0015]} scale={[0.76, 1.1, 0.08]} material={mat(vermelho)} receiveShadow>
      <torusGeometry args={[0.033, 0.0065, 8, 48]} />
    </mesh>
    <mesh position={[0, 0.077, 0.0015]} scale={[1.43, 1, 0.1]} material={mat(vermelho)} receiveShadow>
      <torusGeometry args={[0.06, 0.0045, 8, 64]} />
    </mesh>
  </group>
);

const caderno: Mancha[] = [
  { x: -0.087, y: 0, largura: 0.143, altura: 0.206, cor: '#fffdf8' },
  { x: 0.087, y: 0, largura: 0.143, altura: 0.206, cor: '#ffffff' },
  { x: 0, y: 0, largura: 0.014, altura: 0.25, cor: '#512391' },
];
for (const x of [-0.152, 0.022]) {
  for (const [linha, conta] of ['2+2=4', '4+4=8'].entries()) {
    caderno.push(...numero(conta, x, 0.05 - linha * 0.096,
      0.022, 0.036, 0.0055, '#26232d', 0.005));
  }
}

// Capa roxa larga, páginas claras e lombada central destacada.
export const CadernoBia: React.FC = () => (
  <group position={[0, 0.009, 0]} rotation={[-Math.PI / 2, 0, 0]}>
    <Mosaico largura={0.35} altura={0.25} espessura={0.018} cor="#8d43d3" manchas={caderno} />
    <mesh position={[0, 0, 0.008]} scale={[0.006, 0.119, 0.003]} material={mat('#b984eb')} receiveShadow>
      <sphereGeometry args={[1, 12, 12]} />
    </mesh>
  </group>
);
