import React, { useLayoutEffect, useRef } from 'react';
import * as THREE from 'three';
import { useThree } from '@react-three/fiber';
import { useVideoConfig } from 'remotion';
import { Caixa, type V3 } from './base';

type Enquadramento = {
  alvo: V3;
  direcao: V3;
  fov: number;
  deslocamento?: V3;
  carteira?: boolean;
  posicao?: V3;
  rotacao?: V3;
};

const enquadramentos: Record<string, Enquadramento> = {
  celular: {
    alvo: [0, 0.666, 0], direcao: [0, 0.87, 0.493], fov: 5.3,
    carteira: true, posicao: [0, 0.666, 0.075], rotacao: [-Math.PI / 2, 0, 0],
  },
  provaDez: {
    alvo: [0, 0.662, 0], direcao: [0, 0.87, 0.493], fov: 10,
    carteira: true, posicao: [0, 0.66, 0],
  },
  cadernoBia: {
    alvo: [0, 0.67, 0], direcao: [0, 0.87, 0.493], fov: 10.2,
    carteira: true, posicao: [0, 0.66, 0],
  },
  moeda: {
    alvo: [0, 0.017, 0], direcao: [0, 0.87, 0.493], fov: 4,
    posicao: [0, 0.01, 0],
  },
  paoQuente: {
    alvo: [0, 0.74, 0], direcao: [0, 0.65, 0.76], fov: 10.5,
    carteira: true, posicao: [0, 0.66, 0],
  },
  lousa: {
    alvo: [0, 0.62, 0], direcao: [0, 0.06, 1], fov: 39,
    deslocamento: [1.25, 0, 0],
  },
};

const Carteira: React.FC = () => (
  <group>
    <Caixa p={[0, 0.62, 0]} t={[0.8, 0.08, 0.65]} cor="#8caeae" />
    {[-1, 1].flatMap((x) => [-1, 1].map((z) => (
      <Caixa key={`${x}/${z}`} p={[x * 0.32, 0.29, z * 0.245]}
        t={[0.08, 0.58, 0.08]} cor="#4c626d" />
    )))}
  </group>
);

const Apresentacao: React.FC<{ Componente: React.FC; plano: Enquadramento }> = ({ Componente, plano }) => {
  const camera = useThree((s) => s.camera) as THREE.PerspectiveCamera;
  const grupo = useRef<THREE.Group>(null);

  // A câmera comum é configurada antes deste grupo, na mesma atualização React.
  useLayoutEffect(() => {
    if (!grupo.current) return;
    const anterior = {
      posicao: camera.position.clone(), rotacao: camera.quaternion.clone(),
      fov: camera.fov, near: camera.near, far: camera.far,
    };
    grupo.current.updateWorldMatrix(true, false);
    const alvo = grupo.current.localToWorld(new THREE.Vector3(...plano.alvo));
    // Distância de 2,1 m coincide com o foco óptico da VitrineLote.
    const distancia = new THREE.Vector3(...plano.direcao).normalize().multiplyScalar(2.1);
    camera.position.copy(alvo).add(distancia);
    camera.lookAt(alvo);
    camera.fov = plano.fov;
    camera.near = 0.1;
    camera.far = 200;
    camera.updateProjectionMatrix();
    camera.updateMatrixWorld();
    return () => {
      camera.position.copy(anterior.posicao);
      camera.quaternion.copy(anterior.rotacao);
      camera.fov = anterior.fov;
      camera.near = anterior.near;
      camera.far = anterior.far;
      camera.updateProjectionMatrix();
      camera.updateMatrixWorld();
    };
  });

  return (
    <group ref={grupo} position={plano.deslocamento}>
      {plano.carteira && <Carteira />}
      <group position={plano.posicao} rotation={plano.rotacao}>
        <Componente />
      </group>
    </group>
  );
};

// Apresentação exclusiva da vitrine. Em outras composições, entrega a peça na origem.
export function apresentar(Componente: React.FC, nome: string): React.FC {
  return function PecaApresentada() {
    const { id } = useVideoConfig();
    if (id !== 'VitrineLote') return <Componente />;
    return <Apresentacao Componente={Componente} plano={enquadramentos[nome]} />;
  };
}
