import React from 'react';
import { Caixa, Glifo, mat } from './base';

const CONTAS = [['7+5', '=12', '3+4=7'], ['12+7', '=19', '2+5=7']];
const ROXO = '#8340cc';
const INCLINACAO = -Math.PI / 3;
const ALTURA = 0.14 * Math.cos(INCLINACAO) + 0.016 * Math.abs(Math.sin(INCLINACAO));
const DOBRA = 0.45;
const TOPO_Y = ALTURA + 0.14 * Math.cos(INCLINACAO) + 0.012 * Math.sin(INCLINACAO);
const TOPO_Z = 0.14 * Math.sin(INCLINACAO) - 0.012 * Math.cos(INCLINACAO);
const BASE_Y = 0.004 * Math.sin(DOBRA);
const COMPRIMENTO_ABA = (TOPO_Y - BASE_Y) / Math.cos(DOBRA);

const Pagina: React.FC<{ lado: -1 | 1 }> = ({ lado }) => (
  <group rotation={[0, -lado * 0.10, 0]}>
    {/* Capa deixa uma margem roxa larga ao redor do bloco de folhas. */}
    <Caixa p={[lado * 0.100, 0, -0.012]} t={[0.196, 0.28, 0.008]} cor={ROXO} />
    <Caixa p={[lado * 0.100, 0, -0.001]} t={[0.164, 0.244, 0.014]} cor="#cecad7" />
    <Caixa p={[lado * 0.100, 0, 0.0065]} t={[0.164, 0.244, 0.003]} cor="#fffefa" sombra={false} />
    {/* Pequena curva de papel junto ao vinco, sem lombada sobre a escrita. */}
    <mesh position={[lado * 0.019, 0, 0.002]} material={mat('#eeeaf2')} castShadow receiveShadow>
      <cylinderGeometry args={[0.007, 0.007, 0.24, 12]} />
    </mesh>
    {CONTAS[lado === -1 ? 0 : 1].map((conta, linha) => (
      <group key={linha}>
        {conta.split('').map((valor, i) => (
          <Glifo key={i} valor={valor} x={(lado === -1 ? -0.170 : 0.033) + i * 0.027}
            y={0.065 - linha * 0.068} z={0.0095} altura={0.036}
            largura={0.0045} cor="#494650" />
        ))}
      </group>
    ))}
  </group>
);

// Aberto: cerca de 40 × 28 cm. Capa traseira dobrada sustenta a inclinação.
export const CadernoBia: React.FC = () => (
  <group>
    <group position={[0, ALTURA, 0]} rotation={[INCLINACAO, 0, 0]}>
      <Caixa p={[0, 0, -0.006]} t={[0.012, 0.28, 0.02]} cor="#58268d" />
      <Pagina lado={-1} />
      <Pagina lado={1} />
    </group>
    {/* Aba da própria capa: une a borda superior ao apoio, atrás do caderno. */}
    <Caixa p={[0, (TOPO_Y + BASE_Y) / 2, TOPO_Z - COMPRIMENTO_ABA * Math.sin(DOBRA) / 2]}
      t={[0.376, COMPRIMENTO_ABA, 0.008]} r={[DOBRA, 0, 0]} cor="#6830a4" />
  </group>
);
