// Objetos das ações do lote l15: caderno + lápis, moeda, bola, caixa de sorteio + papel, banco.
// <ObjetosDaAcao> vai DENTRO do mesmo grupo do boneco (mesma posição e giro) e usa a cinemática do kit
// para pôr cada objeto na mão no quadro pedido. Tamanho real, cores chapadas, cache de material por cor.
import * as THREE from 'three';
import React from 'react';
import { ciclo, juntasNoQuadro, MOEDA_VOO, alturaMoeda, QUIQUE, faseQuique } from './acoes';
import { matrizMao, posicao } from './cinematica';

const matCache = new Map<string, THREE.MeshStandardMaterial>();
const mat = (cor: string) => {
  let m = matCache.get(cor);
  if (!m) { m = new THREE.MeshStandardMaterial({ color: cor, roughness: 0.85 }); matCache.set(cor, m); }
  return m;
};
type V3 = [number, number, number];
const Caixa: React.FC<{ p: V3; t: V3; cor: string; r?: V3 }> = ({ p, t, cor, r = [0, 0, 0] }) => (
  <mesh position={p} rotation={r} material={mat(cor)} castShadow receiveShadow><boxGeometry args={t} /></mesh>
);
const R = THREE.MathUtils.degToRad;
const vec = (v: THREE.Vector3): V3 => [v.x, v.y, v.z];

// ── peças soltas ─────────────────────────────────────────────────────────
/** Caderno universitário aberto, 40 × 27 cm (deitado; origem no centro, página para +Y). */
export const Caderno: React.FC = () => (
  <group>
    <Caixa p={[0, -0.006, 0]} t={[0.41, 0.012, 0.28]} cor="#2f6fb5" />
    {([-1, 1] as const).map((l) => <Caixa key={l} p={[0.1 * l, 0.002, 0]} t={[0.193, 0.006, 0.265]} cor="#f6f3ea" />)}
    <Caixa p={[0, 0.004, 0]} t={[0.01, 0.006, 0.265]} cor="#c9c2b0" />
    {/* página da esquerda cheia; na da direita, a linha que está sendo escrita */}
    {[0, 1, 2, 3, 4, 5].map((i) => (
      <Caixa key={i} p={[-0.1 + (i % 2) * 0.008, 0.0058, -0.09 + i * 0.034]} t={[0.15 - (i % 3) * 0.025, 0.0015, 0.01]} cor="#4a5568" />
    ))}
    {[0, 1].map((i) => <Caixa key={i} p={[0.07 + i * 0.01, 0.0058, -0.09 + i * 0.034]} t={[0.11 - i * 0.03, 0.0015, 0.01]} cor="#4a5568" />)}
  </group>
);
/** Lápis "jumbo" de 17 cm (1,5 cm de grossura, o de criança) ao longo de +Y, ponta (grafite) na origem. */
export const Lapis: React.FC = () => (
  <group>
    <mesh position={[0, 0.011, 0]} material={mat('#e8c49a')} castShadow><coneGeometry args={[0.0075, 0.022, 6]} /></mesh>
    <mesh position={[0, 0.004, 0]} material={mat('#2a2a2a')}><coneGeometry args={[0.0028, 0.008, 6]} /></mesh>
    <mesh position={[0, 0.09, 0]} material={mat('#f2c230')} castShadow><cylinderGeometry args={[0.0075, 0.0075, 0.136, 6]} /></mesh>
    <mesh position={[0, 0.163, 0]} material={mat('#b8b8b8')} castShadow><cylinderGeometry args={[0.0079, 0.0079, 0.012, 8]} /></mesh>
    <mesh position={[0, 0.174, 0]} material={mat('#e98aa0')} castShadow><cylinderGeometry args={[0.0075, 0.0075, 0.011, 8]} /></mesh>
  </group>
);
/** Moeda de 2,7 cm (face para +Z): borda dourada, face mais clara e um "1" em relevo. */
export const Moeda: React.FC = () => (
  <group rotation={[Math.PI / 2, 0, 0]}>
    <mesh material={mat('#d9a521')} castShadow><cylinderGeometry args={[0.0135, 0.0135, 0.0022, 24]} /></mesh>
    <mesh position={[0, 0.0007, 0]} material={mat('#f2c94c')}><cylinderGeometry args={[0.011, 0.011, 0.0012, 24]} /></mesh>
    <Caixa p={[0.001, 0.0014, 0]} t={[0.003, 0.0008, 0.012]} cor="#c08f16" />
  </group>
);
/** Bola de basquete (24 cm), laranja com gomos escuros. Origem no centro. */
export const Bola: React.FC<{ giro?: number }> = ({ giro = 0 }) => (
  <group rotation={[giro, 0, 0.3]}>
    <mesh material={mat('#e8742a')} castShadow receiveShadow><sphereGeometry args={[0.12, 28, 16]} /></mesh>
    <mesh material={mat('#3a2418')}><torusGeometry args={[0.1205, 0.004, 6, 40]} /></mesh>
    <mesh rotation={[0, Math.PI / 2, 0]} material={mat('#3a2418')}><torusGeometry args={[0.1205, 0.004, 6, 40]} /></mesh>
    <mesh rotation={[Math.PI / 2, 0, 0]} material={mat('#3a2418')}><torusGeometry args={[0.1205, 0.004, 6, 40]} /></mesh>
  </group>
);
/** Caixa de sorteio 34 × 30 × 30 cm, aberta em cima (boca com borda). Origem no centro da base. */
export const CaixaSorteio: React.FC = () => {
  const L = 0.34, A = 0.3, P = 0.3, e = 0.015;
  return (
    <group>
      <Caixa p={[0, e / 2, 0]} t={[L, e, P]} cor="#c0392b" />
      <Caixa p={[0, A / 2, P / 2 - e / 2]} t={[L, A, e]} cor="#d9483a" />
      <Caixa p={[0, A / 2, -P / 2 + e / 2]} t={[L, A, e]} cor="#d9483a" />
      {([-1, 1] as const).map((l) => <Caixa key={l} p={[l * (L / 2 - e / 2), A / 2, 0]} t={[e, A, P - 2 * e]} cor="#c0392b" />)}
      {/* fundo escuro por dentro, para a boca ler como abertura */}
      <Caixa p={[0, A * 0.55, 0]} t={[L - 2 * e - 0.004, 0.01, P - 2 * e - 0.004]} cor="#3b1712" />
      {/* faixa e "?" na frente (traços grossos) */}
      <Caixa p={[0, A - 0.03, P / 2 + 0.003]} t={[L, 0.03, 0.006]} cor="#f2c94c" />
      <Caixa p={[0, 0.17, P / 2 + 0.004]} t={[0.07, 0.018, 0.006]} cor="#ffffff" />
      <Caixa p={[0.027, 0.145, P / 2 + 0.004]} t={[0.018, 0.05, 0.006]} cor="#ffffff" />
      <Caixa p={[0.008, 0.115, P / 2 + 0.004]} t={[0.04, 0.018, 0.006]} cor="#ffffff" />
      <Caixa p={[-0.004, 0.095, P / 2 + 0.004]} t={[0.018, 0.03, 0.006]} cor="#ffffff" />
      <Caixa p={[-0.004, 0.05, P / 2 + 0.004]} t={[0.02, 0.02, 0.006]} cor="#ffffff" />
    </group>
  );
};
/** Suporte de madeira para a caixa de sorteio (tampo 40 × 36 cm), altura `h` até o tampo. Origem no chão. */
export const Suporte: React.FC<{ h: number }> = ({ h }) => (
  <group>
    <Caixa p={[0, h - 0.015, 0]} t={[0.4, 0.03, 0.36]} cor="#a0724a" />
    <Caixa p={[0, (h - 0.03) / 2, 0]} t={[0.3, h - 0.03, 0.26]} cor="#8a5f3b" />
  </group>
);
/** Papelzinho do sorteio, 8 × 10 cm, de pé, frente para +Z, com um rabisco. Origem no centro. */
export const Papel: React.FC = () => (
  <group>
    <Caixa p={[0, 0, 0]} t={[0.08, 0.1, 0.003]} cor="#fbfaf5" />
    <Caixa p={[0, 0.003, 0.0022]} t={[0.08, 0.003, 0.0015]} cor="#d8d4c8" />
    <Caixa p={[0, 0.025, 0.0025]} t={[0.05, 0.01, 0.0015]} cor="#2e5e9e" />
    <Caixa p={[0, -0.025, 0.0025]} t={[0.035, 0.01, 0.0015]} cor="#2e5e9e" />
  </group>
);
/** Banco baixo de madeira, tampo 44 × 40 cm a 0,30 m do chão. Origem no centro da base. */
export const Banco: React.FC = () => (
  <group>
    <Caixa p={[0, 0.285, 0]} t={[0.44, 0.03, 0.4]} cor="#c98b4e" />
    {([[-1, -1], [-1, 1], [1, -1], [1, 1]] as const).map(([a, b]) => (
      <Caixa key={`${a}${b}`} p={[0.18 * a, 0.135, 0.16 * b]} t={[0.045, 0.27, 0.045]} cor="#9a6534" />
    ))}
    <Caixa p={[0, 0.08, 0]} t={[0.36, 0.03, 0.03]} cor="#9a6534" />
  </group>
);

// ── montagem por ação ─────────────────────────────────────────────────────
/** Objetos da ação `nome` no quadro `quadro`, no espaço do boneco (ponha junto do <Boneco>).
 *  `pele` (opcional) desenha o polegar erguido no `jogarMoeda`. */
export const ObjetosDaAcao: React.FC<{ nome: string; quadro: number; pele?: string }> = ({ nome, quadro, pele }) => {
  const j = juntasNoQuadro(nome, quadro);
  const maoD = posicao(matrizMao(j, 1));
  const maoE = posicao(matrizMao(j, -1));

  if (nome === 'escrever') {
    // caderno preso pela borda esquerda na mão E, inclinado 15° para a frente; a ponta do lápis encosta
    // na página logo à frente da mão D e o lápis sobe passando pela mão
    const inc = R(15);
    const c = new THREE.Vector3(maoE.x + 0.19, maoE.y + 0.01, maoE.z);
    const alturaPagina = (z: number) => c.y + 0.006 * Math.cos(inc) - ((z - c.z) / Math.cos(inc)) * Math.sin(inc);
    const pz = maoD.z + 0.05;
    const ponta = new THREE.Vector3(maoD.x - 0.02, alturaPagina(pz), pz);
    const dir = new THREE.Vector3(0.3, 1, -0.6).normalize();
    const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
    return (
      <group>
        <group position={vec(c)} rotation={[inc, 0, 0]}><Caderno /></group>
        <group position={vec(ponta)} quaternion={q}><Lapis /></group>
      </group>
    );
  }
  if (nome === 'jogarMoeda') {
    // a moeda sai de cima da mão no início do voo, sobe ~45 cm girando (até a altura do rosto) e volta.
    // Escala 2,2 (6 cm): com 2,7 cm ela some ao lado da mão do boneco, que tem 14 cm. Gira em volta de X
    // e fica de frente para a câmera no topo do voo (quadro 30 do ciclo).
    const f = ciclo(quadro, 60);
    const base = posicao(matrizMao(juntasNoQuadro(nome, quadro - f + MOEDA_VOO[0]), 1));
    const noAr = f >= MOEDA_VOO[0] && f < MOEDA_VOO[1];
    const p = noAr ? base.clone().add(new THREE.Vector3(0, 0.09 + 0.45 * alturaMoeda(f), 0)) : maoD.clone().add(new THREE.Vector3(0, 0.09, 0.01));
    return (
      <group>
        <group position={vec(p)} rotation={[noAr ? (f - 30) * 0.5 : R(-60), 0, 0]} scale={2.2}><Moeda /></group>
        {pele && (
          <mesh position={[maoD.x - 0.01, maoD.y + 0.07, maoD.z + 0.01]} rotation={[0, 0, R(10)]} material={mat(pele)} castShadow>
            <capsuleGeometry args={[0.022, 0.035, 4, 10]} />
          </mesh>
        )}
      </group>
    );
  }
  if (nome === 'quicarBola') {
    // mão empurra a bola até o fim da descida (fase 0,5), a bola vai ao chão e volta a encontrar a mão em ~0,35
    const r = 0.12, t = faseQuique(quadro), raioMao = 0.072;
    const topoBola = (qq: number) => posicao(matrizMao(juntasNoQuadro(nome, qq), 1)).y - raioMao - r;
    let y: number;
    if (t >= 0.35 && t < 0.5) y = maoD.y - raioMao - r;
    else {
      const u = ciclo(t - 0.5, 1) / 0.85; // 0 solta, 0,5 no chão, 1 volta à mão
      const q0 = quadro - ciclo(t - 0.5, 1) * QUIQUE;
      const ini = topoBola(q0), fim = topoBola(q0 + 0.85 * QUIQUE);
      y = r + (ini + (fim - ini) * u - r) * Math.abs(Math.cos(Math.PI * u));
    }
    return <group position={[maoD.x, y, maoD.z]}><Bola giro={quadro * 0.15} /></group>;
  }
  if (nome === 'sortear') {
    // caixa parada (num suporte) na pose fixa, com a boca 5 cm acima da mão E; o papel sai por cima da mão D
    const fixa = posicao(matrizMao(juntasNoQuadro(nome, 0), -1));
    const base = fixa.y + 0.05 - 0.3;
    return (
      <group>
        <group position={[fixa.x, 0, fixa.z + 0.03]}>
          <Suporte h={base} />
          <group position={[0, base, 0]}><CaixaSorteio /></group>
        </group>
        <group position={[maoD.x - 0.01, maoD.y + 0.11, maoD.z + 0.02]} rotation={[0, R(-20), R(-6)]}><Papel /></group>
      </group>
    );
  }
  if (nome === 'virarCabeca') return <Banco />;
  return null;
};
