// Objeto: celular preto (7,2 x 15 x 0,85 cm), tela acesa com uma conversa e os dois risquinhos azuis de "lida".
// Na vitrine fica em pé, apoiado no pezinho da capinha e inclinado 14° para trás (a tela olha para a câmera).
// `naMao`: sem pezinho e sem inclinação, origem no centro do aparelho (para pôr na mão do boneco).
import React from 'react';
import { mat, Ret, Tracos, type Traco } from './base';

const C = {
  corpo: '#16181d', vidro: '#07080b', borda: '#2a2d35', fundo: '#eef3f9', recebido: '#9eaabb', enviado: '#2f7bff', risco: '#1a5fe8',
};
const W = 0.072, H = 0.15, D = 0.0085; // aparelho
const TW = 0.064, TH = 0.136; // tela
const tela = (cor: string) => mat(cor, { brilho: 0.85, rug: 0.5 });

// dois "✓" grossos, um ao lado do outro (s = largura de cada um)
const risquinhos = (x: number, y: number, s: number): Traco[] => {
  const v = (dx: number): Traco[] => [
    [x + dx - 0.5 * s, y + 0.05 * s, x + dx - 0.12 * s, y - 0.35 * s],
    [x + dx - 0.12 * s, y - 0.35 * s, x + dx + 0.5 * s, y + 0.42 * s],
  ];
  return [...v(0), ...v(0.5 * s)];
};

// Tela acesa com poucas formas grandes: balão cinza recebido, dois balões azuis enviados e os dois risquinhos azuis.
const Tela: React.FC = () => {
  const zT = 0.0006, zB = 0.0012, zX = 0.0018; // camadas: fundo, balões, risquinhos
  return (
    <group>
      <Ret w={TW} h={TH} d={0.0006} r={0.006} z={zT} m={tela(C.fundo)} />
      <Ret w={0.04} h={0.022} d={0.0006} r={0.006} x={-0.0085} y={0.042} z={zB} m={tela(C.recebido)} />
      <Ret w={0.05} h={0.024} d={0.0006} r={0.006} x={0.0035} y={0.008} z={zB} m={tela(C.enviado)} />
      <Ret w={0.038} h={0.02} d={0.0006} r={0.006} x={0.0095} y={-0.022} z={zB} m={tela(C.enviado)} />
      <Tracos tracos={risquinhos(0.012, -0.045, 0.016)} l={0.0042} z={zX} m={tela(C.risco)} />
    </group>
  );
};

const Aparelho: React.FC = () => (
  <group>
    {/* corpo preto e vidro da frente (bordas finas) */}
    <Ret w={W} h={H} d={D} r={0.01} z={D / 2} m={mat(C.corpo, { rug: 0.6 })} sombra />
    <Ret w={W - 0.003} h={H - 0.003} d={0.0008} r={0.0088} z={D + 0.0004} m={mat(C.vidro, { rug: 0.25 })} />
    <group position={[0, -0.0005, D + 0.0008]}><Tela /></group>
    {/* botões laterais (+X) */}
    <mesh position={[W / 2 + 0.0008, 0.035, D / 2]} material={mat(C.borda)} castShadow><boxGeometry args={[0.002, 0.024, 0.004]} /></mesh>
    <mesh position={[W / 2 + 0.0008, 0.008, D / 2]} material={mat(C.borda)} castShadow><boxGeometry args={[0.002, 0.012, 0.004]} /></mesh>
    {/* câmera de trás: módulo quadrado com duas lentes */}
    <group position={[-0.019, 0.054, -0.001]}>
      <Ret w={0.024} h={0.026} d={0.002} r={0.006} z={0} m={mat(C.borda)} sombra />
      {[0.006, -0.006].map((y) => (
        <mesh key={y} position={[0, y, -0.0012]} rotation={[Math.PI / 2, 0, 0]} material={mat('#05060a', { rug: 0.3 })}><cylinderGeometry args={[0.0042, 0.0042, 0.001, 16]} /></mesh>
      ))}
    </group>
  </group>
);

// pezinho dobrável da capinha: preso a 9 cm da base, abre 40° e encosta na mesa com o aparelho inclinado 14°
const INCL = 14, ABRE = 40, PRESO = 0.09;
const rad = (g: number) => (g * Math.PI) / 180;
const PE = (PRESO * Math.cos(rad(INCL))) / Math.cos(rad(ABRE - INCL));

export const Celular: React.FC<{ naMao?: boolean }> = ({ naMao = false }) => {
  if (naMao) return <group position={[0, 0, -D / 2]}><Aparelho /></group>;
  return (
    <group rotation={[-rad(INCL), 0, 0]}>
      <group position={[0, H / 2, 0]}><Aparelho /></group>
      <mesh position={[0, PRESO - (PE / 2) * Math.cos(rad(ABRE)), -(PE / 2) * Math.sin(rad(ABRE)) - 0.001]} rotation={[rad(ABRE), 0, 0]} material={mat(C.borda)} castShadow receiveShadow>
        <boxGeometry args={[0.034, PE, 0.002]} />
      </mesh>
      <mesh position={[0, PRESO, -0.001]} rotation={[0, 0, Math.PI / 2]} material={mat(C.borda)} castShadow><cylinderGeometry args={[0.002, 0.002, 0.036, 10]} /></mesh>
    </group>
  );
};
