import React from 'react';
import * as THREE from 'three';
import { Caixa, mat } from './formas';

// Camadas leves atrás do boneco suavizam a borda sem tingir o rosto.
const halos = Array.from({ length: 6 }, (_, i) => new THREE.MeshBasicMaterial({
  color: '#ffd677', transparent: true, opacity: 0.004 + (5 - i) * 0.002,
  blending: THREE.AdditiveBlending, depthWrite: false,
}));
const ouro = mat('#f5bd43');
const claro = mat('#ffdf83');

const Particula: React.FC<{ indice: number; tempo: number; intensidade: number }> = ({ indice, tempo, intensidade }) => {
  const ciclo = ((tempo / 6 + indice / 16) % 1 + 1) % 1;
  const angulo = indice * 2.39996 + tempo * 0.52;
  const raio = 0.66 + 0.08 * Math.sin(indice * 1.7 + tempo * 0.4);
  const tamanho = Math.sin(Math.PI * ciclo) ** 2 * intensidade;
  return (
    <group position={[Math.cos(angulo) * raio, 0.12 + ciclo * 1.95, Math.sin(angulo) * raio]} scale={tamanho}>
      {indice % 3 === 0 ? (
        <group rotation={[0, 0, Math.PI / 4 + Math.sin(tempo + indice) * 0.15]}>
          <mesh material={claro}><boxGeometry args={[0.035, 0.13, 0.028]} /></mesh>
          <mesh material={claro}><boxGeometry args={[0.13, 0.035, 0.028]} /></mesh>
        </group>
      ) : (
        <group rotation={[0.15, angulo + tempo * 0.4, 0.15]}>
          <mesh rotation={[Math.PI / 2, 0, 0]} material={ouro}><cylinderGeometry args={[0.052, 0.052, 0.024, 16]} /></mesh>
          <mesh position={[0, 0, 0.016]} rotation={[Math.PI / 2, 0, 0]} material={claro}><cylinderGeometry args={[0.034, 0.034, 0.008, 12]} /></mesh>
        </group>
      )}
    </group>
  );
};
export const BrilhoSorte: React.FC<{ quadro: number; intensidade?: number }> = ({ quadro, intensidade = 1 }) => {
  const tempo = quadro / 30;
  const forca = Math.max(0, Math.min(2, intensidade));
  const pulso = 1 + 0.055 * Math.sin(tempo * 2.2);
  return (
    <group visible={forca > 0}>
      {halos.map((material, i) => (
        <mesh key={i} position={[0, 1.08, -0.72]} scale={[(0.62 + i * 0.048) * pulso, 0.86 + i * 0.036, 0.12 + i * 0.025]} material={material}>
          <sphereGeometry args={[1, 32, 20]} />
        </mesh>
      ))}
      <mesh position={[0, 0.045, 0]} rotation={[-Math.PI / 2, 0, 0]} material={ouro}><torusGeometry args={[0.53, 0.018, 8, 64]} /></mesh>
      {Array.from({ length: 16 }, (_, i) => <Particula key={i} indice={i} tempo={tempo} intensidade={Math.min(1.2, forca)} />)}
      {/* ×2 só com caixas, sem fonte 3D. */}
      <group position={[0, 2.05 + 0.015 * Math.sin(tempo * 1.4), -0.35]} scale={pulso}>
        <Caixa p={[-0.14, 0, 0]} t={[0.035, 0.16, 0.035]} giro={[0, 0, Math.PI / 4]} cor="#ffdc78" sombra={false} />
        <Caixa p={[-0.14, 0, 0]} t={[0.035, 0.16, 0.035]} giro={[0, 0, -Math.PI / 4]} cor="#ffdc78" sombra={false} />
        {[-0.09, 0, 0.09].map((y) => <Caixa key={y} p={[0.08, y, 0]} t={[0.15, 0.035, 0.035]} cor="#ffdc78" sombra={false} />)}
        <Caixa p={[0.1375, 0.045, 0]} t={[0.035, 0.09, 0.035]} cor="#ffdc78" sombra={false} />
        <Caixa p={[0.0225, -0.045, 0]} t={[0.035, 0.09, 0.035]} cor="#ffdc78" sombra={false} />
      </group>
    </group>
  );
};
