// Objeto: papelzinho de rifa (5 x 6 cm aberto), branco liso, dobrado ao meio e meio aberto (~145° entre as metades):
// a metade da frente deitada, a de trás levantada ~35° com o 437 em traços pretos grossos no lado de dentro.
// Origem no centro da base, frente para +Z.
import React from 'react';
import { Caixa, mat, type V3 } from './base';

const C = { papel: '#fbfaf3', dobra: '#dedbd0', tinta: '#15161a' };

const L = 0.05;      // largura (X)
const M = 0.03;      // profundidade de cada metade
const E = 0.0005;    // espessura do papel
const ERGUIDA = 35;  // graus da metade de trás em relação ao chão (ângulo entre as metades: 145°)
const Z_DOBRA = -0.002; // assim a pegada do papel (5,5 cm de fundo) fica centrada na origem

// dígitos: todos com a mesma caixa (w x h) e o mesmo traço t
const W = 0.0105, H = 0.018, T = 0.0026, P = 0.0003; // P: espessura da tinta

/** Traços de cada dígito no plano XY (y para cima): [centro, tamanho, giro em Z]. */
const tracos = (d: string): [V3, V3, number][] => {
  const topo = H / 2 - T / 2, dir = W / 2 - T / 2, esq = -W / 2 + T / 2;
  const barra = (y: number, w = W, x = 0): [V3, V3, number] => [[x, y, 0], [w, T, P], 0];
  const vert = (x: number, y0: number, y1: number): [V3, V3, number] => [[x, (y0 + y1) / 2, 0], [T, y1 - y0, P], 0];
  if (d === '4') return [vert(esq, -T / 2, H / 2), barra(0), vert(dir, -H / 2, H / 2)];
  if (d === '3') return [barra(topo), barra(0, W - T * 0.6, T * 0.3), barra(-topo), vert(dir, -H / 2, H / 2)];
  // '7': barra no alto e diagonal da ponta direita até a base, um pouco à esquerda do meio
  const x1 = dir, y1 = topo, x2 = -W * 0.12, y2 = -H / 2 + T / 2;
  const comp = Math.hypot(x1 - x2, y1 - y2);
  return [barra(topo), [[(x1 + x2) / 2, (y1 + y2) / 2, 0], [T, comp, P], Math.atan2(x1 - x2, y1 - y2) * -1]];
};

const Digito: React.FC<{ d: string; x: number }> = ({ d, x }) => (
  <group position={[x, 0, 0]}>
    {tracos(d).map(([p, t, g], i) => <Caixa key={i} p={p} t={t} r={[0, 0, g]} cor={C.tinta} sombra={false} />)}
  </group>
);

export const PapelRifa: React.FC = () => {
  const ang = ((180 - ERGUIDA) * Math.PI) / 180; // quanto a metade de trás girou desde fechada
  return (
    <group>
      {/* metade da frente, deitada */}
      <Caixa p={[0, E / 2, Z_DOBRA + M / 2]} t={[L, E, M]} cor={C.papel} />

      {/* vinco arredondado na dobra, um tom abaixo do papel */}
      <mesh position={[0, E, Z_DOBRA]} rotation={[0, 0, Math.PI / 2]} material={mat(C.dobra)} castShadow receiveShadow>
        <cylinderGeometry args={[E * 1.2, E * 1.2, L, 10]} />
      </mesh>

      {/* metade de trás: gira na dobra (eixo X), de fechada (por cima da da frente) até erguida para trás */}
      <group position={[0, E, Z_DOBRA]} rotation={[-ang, 0, 0]}>
        <group position={[0, 0, M / 2]}>
          <Caixa p={[0, 0, 0]} t={[L, E, M]} cor={C.papel} />
          {/* 437 no lado de dentro (-Y local), com o alto dos dígitos longe da dobra; lê-se de frente */}
          <group position={[0, -E / 2 - P / 2 - 0.00005, 0.0005]} rotation={[Math.PI / 2, 0, 0]}>
            {['4', '3', '7'].map((d, i) => <Digito key={i} d={d} x={(i - 1) * 0.0148} />)}
          </group>
        </group>
      </group>
    </group>
  );
};
