// Efeito: horizonte de Nova York bem no fundo, logo atrás da mureta da quadra, com um céu liso que cobre a parede do ginásio
// (o efeito substitui o fundo, sem cenário duplo). Torres cinza e azuis de alturas e andares variados, janelas amarelas e
// um Empire State cinza-azulado em degraus. Com o tempo todos encolhem e afundam devagar, até sumirem atrás da mureta.
// Anti-tremido: nada mais fino que 9 cm, janelas atravessam a fachada (sem face coplanar), movimento lento e sem tremor.
import * as THREE from 'three';
import React, { useMemo } from 'react';
import { random } from 'remotion';
import { Caixa, mat, suave } from './base';

const C = {
  cinza: ['#a7adb6', '#8c939e', '#767e8a'], azul: ['#7aa6d8', '#5d8cc4', '#4a77b0'],
  topo: '#4c525b', janela: '#ffd54a', apagada: '#3d4a5c', antena: '#dfe3ea',
  empire: '#8e9fb8', empireDegrau: '#7a8ca6', caixaDagua: '#8a6a52', tampa: '#5e4a3c',
};
const PROF = 0.36; // profundidade das torres (cabem entre a mureta e o céu)

type Torre = { x: number; w: number; h: number; cor: string; andar: number; extra?: 'caixa' | 'antena' | 'beiral' };
// fileira inteira de x = -5,7 a 5,7 (dentro do quadro, com sobra), incluindo atrás do personagem
const TORRES: Torre[] = [
  { x: -5.2, w: 1.0, h: 1.9, cor: C.cinza[0], andar: 0.42, extra: 'caixa' },
  { x: -4.22, w: 0.9, h: 2.5, cor: C.azul[1], andar: 0.36, extra: 'antena' },
  { x: -3.18, w: 1.12, h: 2.05, cor: C.cinza[2], andar: 0.48 },
  { x: -2.17, w: 0.84, h: 2.65, cor: C.azul[0], andar: 0.4, extra: 'beiral' },
  { x: -1.25, w: 0.98, h: 1.7, cor: C.cinza[1], andar: 0.45, extra: 'caixa' },
  { x: -0.2, w: 1.1, h: 2.3, cor: C.azul[2], andar: 0.38 },
  { x: 0.78, w: 0.8, h: 1.95, cor: C.cinza[0], andar: 0.5, extra: 'beiral' },
  // Empire State em x = 1,85
  { x: 2.88, w: 0.92, h: 2.2, cor: C.azul[1], andar: 0.44, extra: 'caixa' },
  { x: 3.88, w: 1.06, h: 2.6, cor: C.cinza[2], andar: 0.37, extra: 'antena' },
  { x: 4.98, w: 1.0, h: 1.85, cor: C.azul[0], andar: 0.46, extra: 'beiral' },
];
const EMPIRE_X = 1.85, EMPIRE_H = 2.85;

/** Grade de janelas na fachada (w de largura), andares de altura `andar`; algumas apagadas. Metade da janela entra na parede. */
const Janelas: React.FC<{ w: number; h: number; andar: number; semente: string }> = ({ w, h, andar, semente }) => {
  const nc = Math.max(2, Math.round(w / 0.3));
  const passo = w / nc, linhas = Math.floor((h - 0.45) / andar);
  return (
    <>
      {Array.from({ length: linhas * nc }, (_, i) => {
        const l = Math.floor(i / nc), c = i % nc;
        const acesa = random(`${semente}-${i}`) > 0.18;
        return (
          <Caixa key={i} p={[-w / 2 + passo * (c + 0.5), 0.35 + l * andar + andar * 0.3, PROF / 2]} t={[Math.max(0.12, passo * 0.5), Math.max(0.15, andar * 0.52), 0.06]}
            m={acesa ? mat(C.janela, 0.55) : mat(C.apagada)} sombra={false} />
        );
      })}
    </>
  );
};

const CaixaDagua: React.FC<{ x: number; y: number }> = ({ x, y }) => (
  <group position={[x, y, 0]}>
    {[-0.12, 0.12].map((px) => <Caixa key={px} p={[px, 0.12, 0]} t={[0.09, 0.26, 0.09]} m={mat(C.topo)} />)}
    <mesh position={[0, 0.4, 0]} material={mat(C.caixaDagua)} castShadow receiveShadow><cylinderGeometry args={[0.2, 0.2, 0.34, 14]} /></mesh>
    <mesh position={[0, 0.64, 0]} material={mat(C.tampa)} castShadow><cylinderGeometry args={[0.04, 0.23, 0.16, 14]} /></mesh>
  </group>
);

// vão de 10 cm entre torres vizinhas: o céu entre elas nunca vira uma fresta fina (que cintila)
const Predio: React.FC<{ t: Torre; i: number }> = ({ t: t0, i }) => {
  const t = { ...t0, w: t0.w - 0.1 };
  return (
  <group>
    <Caixa p={[0, t.h / 2, 0]} t={[t.w, t.h, PROF]} m={mat(t.cor)} />
    {/* coroamento do topo, encaixado 3 cm na caixa */}
    <Caixa p={[0, t.h + 0.02, 0]} t={[t.w + 0.08, 0.1, PROF + 0.08]} m={mat(C.topo)} />
    {t.extra === 'beiral' && <Caixa p={[0, t.h + 0.12, 0]} t={[t.w * 0.6, 0.16, PROF * 0.7]} m={mat(t.cor)} />}
    <Janelas w={t.w - 0.16} h={t.h} andar={t.andar} semente={`ny-r10-${i}`} />
    {t.extra === 'caixa' && <CaixaDagua x={t.w * 0.18} y={t.h + 0.06} />}
    {t.extra === 'antena' && (
      <mesh position={[0, t.h + 0.25, 0]} material={mat(C.antena)} castShadow><cylinderGeometry args={[0.045, 0.06, 0.45, 8]} /></mesh>
    )}
  </group>
  );
};

/** Empire State em degraus: base larga, três recuos, coroa e agulha (2,85 m). Faixas verticais acesas nos degraus. */
const Empire: React.FC = () => {
  // largura, base, altura (cada degrau entra 4 cm no de baixo)
  const niveis: [number, number, number][] = [[1.0, 0, 1.35], [0.8, 1.31, 0.5], [0.64, 1.77, 0.38], [0.44, 2.11, 0.28]];
  return (
    <group>
      {niveis.map(([w, y, h], i) => {
        const nf = Math.max(2, Math.round(w / 0.24));
        return (
          <group key={i}>
            <Caixa p={[0, y + h / 2, 0]} t={[w, h, Math.min(PROF, w * 0.8)]} m={mat(i % 2 ? C.empireDegrau : C.empire)} />
            {/* faixas acesas: 10 cm de largura, metade entra na parede */}
            {i < 3 && Array.from({ length: nf }, (_, k) => (
              <Caixa key={k} p={[(k - (nf - 1) / 2) * (w / nf), y + h / 2 + 0.02, Math.min(PROF, w * 0.8) / 2]} t={[0.1, h - 0.22, 0.06]} m={mat(C.janela, 0.55)} sombra={false} />
            ))}
          </group>
        );
      })}
      {/* coroa e agulha */}
      <mesh position={[0, 2.45, 0]} material={mat(C.empire)} castShadow receiveShadow><cylinderGeometry args={[0.12, 0.18, 0.12, 12]} /></mesh>
      <mesh position={[0, 2.54, 0]} material={mat(C.empireDegrau)} castShadow receiveShadow><cylinderGeometry args={[0.08, 0.11, 0.1, 12]} /></mesh>
      <mesh position={[0, 2.7, 0]} material={mat(C.antena)} castShadow><cylinderGeometry args={[0.045, 0.065, 0.3, 8]} /></mesh>
    </group>
  );
};

/** `inicio`/`duracao` em quadros (quando começa a afundar e quanto leva); `z`: linha dos prédios; `ceu`: cor do céu liso atrás. */
export const PredioNovaYork: React.FC<{ quadro: number; inicio?: number; duracao?: number; z?: number; ceu?: string | null }> = ({
  quadro, inicio = 50, duracao = 90, z = -8.02, ceu = '#9fd3ee',
}) => {
  const mCeu = useMemo(() => (ceu ? new THREE.MeshBasicMaterial({ color: ceu }) : null), [ceu]);
  const itens = [
    ...TORRES.map((t, i) => ({ x: t.x, h: t.h + 0.7, atraso: Math.round(random(`ny-r10-atraso-${i}`) * 14), el: <Predio t={t} i={i} /> })),
    { x: EMPIRE_X, h: EMPIRE_H, atraso: 18, el: <Empire /> }, // o Empire afunda por último
  ];
  return (
    <group>
      {/* céu liso: cobre a parede do fundo (o efeito vira o horizonte); não recebe luz nem sombra */}
      {mCeu && <mesh position={[0, 6, z - 0.28]} material={mCeu}><planeGeometry args={[60, 14]} /></mesh>}
      <group position={[0, 0, z]}>
        {itens.map((it, i) => {
          const t = suave((quadro - inicio - it.atraso) / (duracao - 18));
          if (t > 0.999) return null;
          const enc = 1 - 0.3 * t; // encolhe até 70% enquanto afunda
          return <group key={i} position={[it.x, -t * it.h * enc, 0]} scale={enc}>{it.el}</group>;
        })}
      </group>
    </group>
  );
};
