// Primitivas do lote. Medidas em metros, Y para cima.
import React from 'react';
import * as THREE from 'three';

export type V3 = [number, number, number];

const cache = new Map<string, THREE.MeshStandardMaterial>();
export const mat = (cor: string, opacidade = 1, brilho = 0) => {
  const chave = `${cor}|${opacidade}|${brilho}`;
  let material = cache.get(chave);
  if (!material) {
    material = new THREE.MeshStandardMaterial({
      color: cor,
      roughness: 0.85,
      emissive: cor,
      emissiveIntensity: brilho,
      transparent: opacidade < 1,
      opacity: opacidade,
      depthWrite: opacidade === 1,
      side: opacidade < 1 ? THREE.DoubleSide : THREE.FrontSide,
    });
    cache.set(chave, material);
  }
  return material;
};

export const Caixa: React.FC<{
  p: V3; t: V3; cor: string; r?: V3; sombra?: boolean; opacidade?: number; brilho?: number;
}> = ({ p, t, cor, r, sombra = true, opacidade = 1, brilho = 0 }) => (
  <mesh position={p} rotation={r} material={mat(cor, opacidade, brilho)}
    castShadow={sombra && opacidade === 1} receiveShadow={opacidade === 1}>
    <boxGeometry args={t} />
  </mesh>
);

export const Esfera: React.FC<{ p: V3; r: number; cor: string; escala?: V3; brilho?: number }> = ({ p, r, cor, escala, brilho = 0 }) => (
  <mesh position={p} scale={escala} material={mat(cor, 1, brilho)} castShadow receiveShadow>
    <sphereGeometry args={[r, 16, 10]} />
  </mesh>
);

// Cantos com quartos de cilindro; faces superiores sem sobreposição.
export const Tampo: React.FC<{ p: V3; t: V3; raio: number; cor: string }> = ({ p, t: [w, h, d], raio, cor }) => (
  <group position={p}>
    <Caixa p={[0, 0, 0]} t={[w - 2 * raio, h, d]} cor={cor} />
    {([-1, 1] as const).map((lado) => (
      <Caixa key={lado} p={[lado * (w / 2 - raio / 2), 0, 0]} t={[raio, h, d - 2 * raio]} cor={cor} />
    ))}
    {([-1, 1] as const).flatMap((x) => ([-1, 1] as const).map((z) => (
      <mesh key={`${x}:${z}`} position={[x * (w / 2 - raio), 0, z * (d / 2 - raio)]}
        material={mat(cor)} castShadow receiveShadow>
        <cylinderGeometry args={[raio, raio, h, 8, 1, false,
          x === 1 ? (z === 1 ? 0 : Math.PI / 2) : (z === -1 ? Math.PI : 3 * Math.PI / 2), Math.PI / 2]} />
      </mesh>
    )))}
  </group>
);
