// Ajuste só da vitrine (composição VitrineLote), no padrão do r12/r13: tira a peça do pedestal, deita num piso liso
// longe do Téo e das linhas da quadra, e fecha a câmera nela. Fora da vitrine, os componentes ficam puros (origem, sem câmera).
import React, { useLayoutEffect } from 'react';
import { useThree } from '@react-three/fiber';
import { useVideoConfig } from 'remotion';
import * as THREE from 'three';

type V3 = [number, number, number];
/** desloc: soma à posição que a vitrine dá (0,75; 0,75; 0) no pedestal; alvo: centro do quadro; altura: altura do quadro no alvo (m);
 *  dist: distância da câmera (2,1 = foco do DOF da vitrine); elev/azim em graus; pe: [largura, fundo, recuo] da sombra de contato (recuo = quanto sai para trás-esquerda). */
type Plano = { desloc: V3; alvo: V3; altura: number; dist: number; elev: number; azim: number; pe: [number, number, number]; suave?: boolean };

// trecho azul liso da quadra (topo em y = 0,01), longe das linhas: a folha branca salta do azul.
// Câmera mais baixa (42°) e girada (20°) para a borda de 5 mm aparecer na frente e na direita.
const FOLHA = { desloc: [4.75, -0.74, -2.5], alvo: [5.5, 0.012, -2.5], altura: 0.56, dist: 2.1, elev: 42, azim: 20, pe: [0.3, 0.4, 0.004], suave: true } satisfies Plano;

export const PLANOS = {
  provaQuimica: FOLHA,
  provaOito: FOLHA,
  // dentro da quadra (topo em y = 0,01), num trecho azul liso longe das linhas: o dourado e os brilhos saltam do azul
  figurinhaDourada: { desloc: [3.75, -0.74, -1], alvo: [4.5, 0.012, -1], altura: 0.17, dist: 2.1, elev: 58, azim: 6, pe: [0.06, 0.09, 0.0012] },
} satisfies Record<string, Plano>;

const AjustarCamera: React.FC<{ p: Plano }> = ({ p }) => {
  const camera = useThree((s) => s.camera) as THREE.PerspectiveCamera;
  // roda depois da <Camera> do palco (vem antes na árvore), a cada quadro, sem loop próprio
  useLayoutEffect(() => {
    const e = (p.elev * Math.PI) / 180, a = (p.azim * Math.PI) / 180, h = p.dist * Math.cos(e);
    camera.position.set(p.alvo[0] + h * Math.sin(a), p.alvo[1] + p.dist * Math.sin(e), p.alvo[2] + h * Math.cos(a));
    camera.lookAt(...p.alvo);
    camera.fov = (2 * Math.atan(p.altura / 2 / p.dist) * 180) / Math.PI;
    camera.updateProjectionMatrix();
    camera.updateMatrixWorld();
  });
  return null;
};

// sombra de contato: retângulo escuro translúcido rente ao piso, um pouco maior e puxado para trás-esquerda (lado oposto ao sol)
const matSombra = new THREE.MeshStandardMaterial({ color: '#000000', transparent: true, opacity: 0.18, depthWrite: false, roughness: 0.9 });
const SombraContato: React.FC<{ pe: [number, number, number] }> = ({ pe: [w, f, r] }) => (
  <mesh position={[-r, 0.0006, -1.2 * r]} material={matSombra}><boxGeometry args={[w + r, 0.0002, f + r]} /></mesh>
);

// sombra suave (folhas): 7 retângulos translúcidos crescentes, 0,3 mm um acima do outro, puxados para trás-esquerda
const matSuave = new THREE.MeshStandardMaterial({ color: '#0b1f3a', transparent: true, opacity: 0.06, depthWrite: false, roughness: 0.9 });
const MARGENS = [0.002, 0.006, 0.011, 0.017, 0.024, 0.032, 0.041];
const SombraSuave: React.FC<{ pe: [number, number, number] }> = ({ pe: [w, f] }) => (
  <>
    {MARGENS.map((m, i) => (
      <mesh key={i} position={[-0.01, 0.0004 + (MARGENS.length - i) * 0.0003, -0.012]} material={matSuave}>
        <boxGeometry args={[w + 2 * m, 0.0002, f + 2 * m]} />
      </mesh>
    ))}
  </>
);

export function apresentar(Componente: React.FC<{ deitada?: boolean }>, nome: keyof typeof PLANOS): React.FC {
  return function PecaNaVitrine() {
    const { id } = useVideoConfig();
    if (id !== 'VitrineLote') return <Componente />;
    const p: Plano = PLANOS[nome];
    return (
      <>
        <AjustarCamera p={p} />
        <group position={p.desloc}>{p.suave ? <SombraSuave pe={p.pe} /> : <SombraContato pe={p.pe} />}<group position={[0, 0.001, 0]}><Componente deitada /></group></group>
      </>
    );
  };
}
