// O boneco do canal: formas simples (cápsula, esfera), cabeça grande com contorno, olhos com pupila.
// Tudo paramétrico: visual (cores, cabelo, acessório), pose (juntas) e expressão. Nenhum desenho novo por cena.
import * as THREE from 'three';
import React, { useLayoutEffect, useMemo, useRef } from 'react';
import { useThree } from '@react-three/fiber';
import { BASE, type Juntas } from './poses';

export type Visual = {
  pele: string; camisa: string; calca: string; tenis: string;
  cabelo: 'cachos' | 'coques' | 'liso' | 'raspado'; cabeloCor: string; bone?: string;
};
export type Expressao = {
  piscar?: number; // 0 aberto, 1 fechado
  olharX?: number; olharY?: number; // -1..1
  boca?: 'neutra' | 'sorriso' | 'aberta' | 'o' | 'triste';
  sobrancelha?: number; // -1 brava, 0 normal, 1 surpresa
};

const R = THREE.MathUtils.degToRad;
const matCache = new Map<string, THREE.MeshStandardMaterial>();
const mat = (cor: string) => {
  let m = matCache.get(cor);
  if (!m) { m = new THREE.MeshStandardMaterial({ color: cor, roughness: 0.82 }); matCache.set(cor, m); }
  return m;
};
const contorno = new THREE.MeshBasicMaterial({ color: '#0a0a0a', side: THREE.BackSide });

const Capsula: React.FC<{ comp: number; raio: number; cor: string }> = ({ comp, raio, cor }) => (
  // cápsula pendurada para baixo a partir da junta (origem no topo)
  <mesh position={[0, -comp / 2, 0]} material={mat(cor)} castShadow receiveShadow>
    <capsuleGeometry args={[raio, comp, 8, 20]} />
  </mesh>
);
const Esfera: React.FC<{ p?: [number, number, number]; r: number; cor: string; esc?: [number, number, number]; seg?: number }> = ({ p = [0, 0, 0], r, cor, esc = [1, 1, 1], seg = 32 }) => (
  <mesh position={p} scale={esc} material={mat(cor)} castShadow receiveShadow>
    <sphereGeometry args={[r, seg, seg / 2]} />
  </mesh>
);

/** Braço: ombro → cotovelo → mão. lado -1 = esquerdo do boneco (à direita de quem olha). */
const Braco: React.FC<{ lado: 1 | -1; x: number; z: number; cot: number; v: Visual }> = ({ lado, x, z, cot, v }) => (
  <group position={[0.25 * lado, 1.06, 0]} rotation={[R(-x), 0, R(z) * lado]}>
    <Capsula comp={0.2} raio={0.062} cor={v.camisa} />
    <group position={[0, -0.22, 0]} rotation={[R(-cot), 0, 0]}>
      <Capsula comp={0.18} raio={0.056} cor={v.camisa} />
      <Esfera p={[0, -0.25, 0]} r={0.072} cor={v.pele} />
    </group>
  </group>
);
const Perna: React.FC<{ lado: 1 | -1; q: number; j: number; v: Visual }> = ({ lado, q, j, v }) => (
  <group position={[0.1 * lado, 0.64, 0]} rotation={[R(-q), 0, 0]}>
    <Capsula comp={0.22} raio={0.074} cor={v.calca} />
    <group position={[0, -0.25, 0]} rotation={[R(j), 0, 0]}>
      <Capsula comp={0.2} raio={0.07} cor={v.calca} />
      <mesh position={[0, -0.3, 0.05]} material={mat(v.tenis)} castShadow receiveShadow>
        <boxGeometry args={[0.15, 0.11, 0.27]} />
      </mesh>
    </group>
  </group>
);

const Cabeca: React.FC<{ v: Visual; e: Expressao }> = ({ v, e }) => {
  const pisc = e.piscar ?? 0, ox = (e.olharX ?? 0) * 0.025, oy = (e.olharY ?? 0) * 0.02, sb = e.sobrancelha ?? 0;
  const boca = e.boca ?? 'neutra';
  return (
    <group>
      <Esfera r={0.34} cor={v.pele} seg={48} />
      <mesh material={contorno}><sphereGeometry args={[0.358, 48, 24]} /></mesh>
      {([-1, 1] as const).map((l) => (
        <group key={l}>
          {/* olho: branco + pupila; piscar achata o olho */}
          <group position={[0.11 * l, 0.04, 0.3]} scale={[1, Math.max(0.08, 1 - pisc), 1]}>
            <Esfera r={0.075} cor="#ffffff" esc={[1, 1.15, 0.45]} />
            <Esfera p={[ox, oy - 0.01, 0.035]} r={0.038} cor="#161616" esc={[1, 1.1, 0.5]} />
            <Esfera p={[ox + 0.012, oy + 0.012, 0.05]} r={0.011} cor="#ffffff" />
          </group>
          {/* sobrancelha */}
          <mesh position={[0.11 * l, 0.16 + sb * 0.03, 0.31]} rotation={[0, 0, R(-sb * 12 * l + (sb < 0 ? 18 * l : 0))]} material={mat(v.cabeloCor)}>
            <capsuleGeometry args={[0.012, 0.07, 4, 8]} />
          </mesh>
          <Esfera p={[0.18 * l, -0.08, 0.27]} r={0.045} cor="#f08a8a" esc={[1, 0.6, 0.3]} />
        </group>
      ))}
      {boca === 'sorriso' && (
        <mesh position={[0, -0.12, 0.315]} rotation={[0, 0, Math.PI]} material={mat('#5a1f1f')}>
          <torusGeometry args={[0.06, 0.013, 8, 24, Math.PI]} />
        </mesh>
      )}
      {boca === 'triste' && (
        <mesh position={[0, -0.17, 0.31]} material={mat('#5a1f1f')}>
          <torusGeometry args={[0.05, 0.012, 8, 24, Math.PI]} />
        </mesh>
      )}
      {boca === 'aberta' && <Esfera p={[0, -0.13, 0.31]} r={0.06} cor="#5a1f1f" esc={[1.2, 0.8, 0.4]} />}
      {boca === 'o' && <Esfera p={[0, -0.13, 0.32]} r={0.035} cor="#5a1f1f" esc={[1, 1.2, 0.4]} />}
      {boca === 'neutra' && (
        <mesh position={[0, -0.13, 0.325]} rotation={[0, 0, Math.PI / 2]} material={mat('#5a1f1f')}>
          <capsuleGeometry args={[0.01, 0.05, 4, 8]} />
        </mesh>
      )}
      <Cabelo v={v} />
    </group>
  );
};

const Cabelo: React.FC<{ v: Visual }> = ({ v }) => {
  const cachos = useMemo(() => Array.from({ length: 16 }, (_, i) => {
    const a = (i / 16) * Math.PI * 2;
    return [0.29 * Math.cos(a), 0.12 + 0.05 * Math.sin(3 * a), -0.06 - 0.22 * Math.sin(a)] as [number, number, number];
  }), []);
  const c = v.cabeloCor;
  return (
    <group>
      {v.cabelo === 'cachos' && cachos.map((p, i) => <Esfera key={i} p={p} r={0.095} cor={c} seg={14} />)}
      {v.cabelo === 'coques' && (<><Esfera p={[0, 0.07, -0.03]} r={0.355} cor={c} esc={[1, 0.9, 1]} /><Esfera p={[-0.22, 0.33, -0.05]} r={0.12} cor={c} /><Esfera p={[0.22, 0.33, -0.05]} r={0.12} cor={c} /></>)}
      {v.cabelo === 'liso' && <Esfera p={[0, 0.08, -0.04]} r={0.355} cor={c} esc={[1.02, 0.88, 1]} />}
      {v.cabelo === 'raspado' && <Esfera p={[0, 0.06, -0.02]} r={0.346} cor={c} esc={[1, 0.9, 1]} />}
      {v.bone && (
        <group>
          <Esfera p={[0, 0.235, -0.05]} r={0.335} cor={v.bone} esc={[1.02, 0.58, 1.0]} />
          <mesh position={[0, 0.2, -0.4]} rotation={[R(-10), 0, 0]} material={mat(v.bone)} castShadow>
            <boxGeometry args={[0.34, 0.035, 0.24]} />
          </mesh>
        </group>
      )}
    </group>
  );
};

/** Regra fixa: personagem fora do enquadramento não projeta sombra (evita "sombra fantasma" entrando antes do corpo). */
function useSombraSoNoQuadro(ref: React.RefObject<THREE.Group | null>) {
  const cam = useThree((s) => s.camera);
  useLayoutEffect(() => {
    const g = ref.current; if (!g) return;
    cam.updateMatrixWorld(); g.updateMatrixWorld();
    const fr = new THREE.Frustum().setFromProjectionMatrix(new THREE.Matrix4().multiplyMatrices(cam.projectionMatrix, cam.matrixWorldInverse));
    const centro = new THREE.Vector3(0, 0.9, 0).applyMatrix4(g.matrixWorld);
    const visivel = fr.intersectsSphere(new THREE.Sphere(centro, 0.95));
    g.traverse((o) => { if ((o as THREE.Mesh).isMesh && (o as THREE.Mesh).material !== contorno) o.castShadow = visivel; });
  });
}

export const Boneco: React.FC<{ v: Visual; j?: Juntas; e?: Expressao; pos?: [number, number, number]; giro?: number }> = ({ v, j = BASE, e = {}, pos = [0, 0, 0], giro = 0 }) => {
  const ref = useRef<THREE.Group>(null);
  useSombraSoNoQuadro(ref);
  return (
  <group ref={ref} position={[pos[0], pos[1] + j.altura, pos[2]]} rotation={[0, R(giro), 0]}>
    <Perna lado={-1} q={j.quadrilE} j={j.joelhoE} v={v} />
    <Perna lado={1} q={j.quadrilD} j={j.joelhoD} v={v} />
    <group position={[0, 0.66, 0]} rotation={[R(j.troncoX), R(j.troncoY), 0]}>
      <group position={[0, -0.66, 0]}>
        <mesh position={[0, 0.86, 0]} material={mat(v.camisa)} castShadow receiveShadow>
          <capsuleGeometry args={[0.19, 0.28, 8, 24]} />
        </mesh>
        <Braco lado={-1} x={j.ombroEX} z={j.ombroEZ} cot={j.cotoveloE} v={v} />
        <Braco lado={1} x={j.ombroDX} z={j.ombroDZ} cot={j.cotoveloD} v={v} />
        <group position={[0, 1.18, 0]} rotation={[R(j.cabecaX), R(j.cabecaY), R(j.cabecaZ)]}>
          <group position={[0, 0.32, 0]}><Cabeca v={v} e={e} /></group>
        </group>
      </group>
    </group>
  </group>
);
};
