// Folha grande, inclinada para trás e apoiada pela borda inferior.
import React from 'react';
import { Caixa, mat, Retangulo, Traco, type V2 } from './base';

const C = { papel: '#fffdf5', texto: '#626971', nota: '#e62036' };
const Z = 0.027;
const INCLINACAO = -Math.PI / 7;
const TITULO: [V2, V2][][] = [
  [[[0, 0], [0, 1]], [[0, 1], [1, 1]], [[1, 1], [1, 0.5]], [[1, 0.5], [0, 0.5]]], // P
  [[[0, 0], [0, 1]], [[0, 1], [1, 1]], [[1, 1], [1, 0.5]], [[1, 0.5], [0, 0.5]], [[0.4, 0.5], [1, 0]]], // R
  [[[0, 0], [0, 1]], [[0, 1], [1, 1]], [[1, 1], [1, 0]], [[1, 0], [0, 0]]], // O
  [[[0, 1], [0.5, 0]], [[0.5, 0], [1, 1]]], // V
  [[[0, 0], [0.5, 1]], [[0.5, 1], [1, 0]], [[0.2, 0.4], [0.8, 0.4]]], // A
];

export const ProvaSete: React.FC = () => (
  <group position={[0, 0.003 * Math.sin(-INCLINACAO), 0.16]} rotation={[INCLINACAO, 0, 0]}>
    {/* 36 × 46 cm; a espessura de 6 mm fica visível na borda. */}
    <Retangulo w={0.36} h={0.46} d={0.006} raio={0.005} p={[0, 0.23, 0]} cor={C.papel} />
    <group position={[-0.151, 0.405, Z]}>
      {TITULO.map((letra, i) => letra.map(([a, b], j) => (
        <Traco key={`${i}-${j}`} a={[i * 0.023 + a[0] * 0.014, a[1] * 0.024]}
          b={[i * 0.023 + b[0] * 0.014, b[1] * 0.024]} largura={0.0035} z={0} cor={C.texto} />
      )))}
    </group>
    {/* Cabeçalho e respostas simples, com bastante branco em volta da nota. */}
    <Caixa p={[-0.1, 0.38, Z]} t={[0.105, 0.009, 0.004]} cor={C.texto} sombra={false} />
    {[0, 1, 2].map((i) => (
      <group key={i}>
        <Caixa p={[-0.005, 0.223 - i * 0.073, Z]} t={[0.294, 0.012, 0.004]} cor={C.texto} sombra={false} />
        <Caixa p={[-0.038, 0.197 - i * 0.073, Z]} t={[0.228, 0.008, 0.004]} cor={C.texto} sombra={false} />
      </group>
    ))}
    {/* Traços de 2 cm e círculo de 1,6 cm: a nota domina o canto direito. */}
    <Traco a={[0.033, 0.385]} b={[0.11, 0.385]} largura={0.021} z={Z} cor={C.nota} />
    <Traco a={[0.109, 0.376]} b={[0.058, 0.282]} largura={0.021} z={Z} cor={C.nota} />
    <mesh position={[0.072, 0.337, Z]} scale={[1, 1.12, 0.25]} material={mat(C.nota)} receiveShadow>
      <torusGeometry args={[0.077, 0.008, 10, 64]} />
    </mesh>
  </group>
);
