// Demonstrações das ações COM objetos e com o "outro" personagem. O contrato `acao` só leva juntas, então a
// vitrine mostra o Téo de mãos vazias; estas peças (tipo 'efeito') põem ao lado dele quem faz a ação de verdade:
// pacote rasgando, escova na boca, alguém sentado com a raspadinha, a mochila puxada pela alça.
import * as THREE from 'three';
import React from 'react';
import { Boneco } from '../../../kit/Boneco';
import { ELENCO } from '../../../kit/elenco';
import { BASE, pose, type Juntas } from '../../../kit/poses';
import type { PecaOficina } from '../tipos';
import { aberturaPacote, forcaPuxao, juntasNoQuadro } from './acoes';
import { matrizCabeca, matrizMao, matrizTronco, posicao } from './cinematica';
import { ALCA_MOCHILA, Banquinho, Barra, Espuma, Escova, Mochila, PACOTE, Pacote, Raspadinha, TiraPacote } from './objetos';

const v3 = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);
/** Põe filhos numa matriz (posição + giro) calculada pela cinemática. */
const NaMatriz: React.FC<{ m: THREE.Matrix4; children: React.ReactNode }> = ({ m, children }) => {
  const p = new THREE.Vector3(), q = new THREE.Quaternion(), s = new THREE.Vector3();
  m.decompose(p, q, s);
  return <group position={p} quaternion={q}>{children}</group>;
};

// ---------- abrirPacote: c1 segura o pacote pela boca; a mão D leva a tira rasgada ----------
const DemoAbrirPacote: React.FC<{ quadro: number }> = ({ quadro }) => {
  const j = juntasNoQuadro('abrirPacote', quadro), a = aberturaPacote(quadro);
  const maoE = posicao(matrizMao(j, -1)), maoD = posicao(matrizMao(j, 1));
  const w = PACOTE.larg;
  return (
    <group position={[1.0, 0, 0.1]} rotation={[0, -0.25, 0]}>
      <Boneco v={ELENCO.c1} j={j} e={{ boca: a > 0.5 ? 'aberta' : 'neutra', olharY: -0.7, sobrancelha: a > 0.5 ? 1 : -0.3 }} />
      {/* a mão E (de baixo) segura o pacote pela lateral; a tira da ponta sai na mão D (de cima) */}
      <group position={[maoE.x + w / 2 - 0.03, maoE.y + 0.13, maoE.z + 0.02]}><Pacote rasgado={a > 0.02} /></group>
      <group position={[maoD.x - w / 4, maoD.y + 0.015, maoD.z + 0.02]} rotation={[0, 0, -0.6 * a]}><TiraPacote /></group>
    </group>
  );
};

// ---------- escovarDentes: Bia com a escova entrando pelo canto da boca e espuma ----------
const DemoEscovar: React.FC<{ quadro: number }> = ({ quadro }) => {
  const j = juntasNoQuadro('escovarDentes', quadro);
  const mao = posicao(matrizMao(j, 1));
  const boca = v3(0.035, -0.13, 0.33).applyMatrix4(matrizCabeca(j));
  const dir = new THREE.Vector3().subVectors(mao, boca).normalize();
  const giro = new THREE.Quaternion().setFromUnitVectors(v3(0, 1, 0), dir);
  return (
    <group position={[1.0, 0, 0.1]} rotation={[0, -0.25, 0]}>
      <Boneco v={ELENCO.bia} j={j} e={{ boca: 'aberta', olharX: -0.3, piscar: 0.35 }} />
      <group position={boca} quaternion={giro}><Escova /></group>
      <NaMatriz m={matrizCabeca(j)}><group position={[0, -0.15, 0.335]}><Espuma fase={quadro * 0.8} /></group></NaMatriz>
    </group>
  );
};

// ---------- inclinar: Bia sentada com uma raspadinha; c1 se inclina por cima do ombro dela ----------
const SENTADA: Juntas = { ...pose('sentar'), ombroEX: 49, ombroEZ: -26, cotoveloE: 55, ombroDX: 49, ombroDZ: -26, cotoveloD: 55, cabecaX: 18 };
const DemoInclinar: React.FC<{ quadro: number }> = ({ quadro }) => {
  // com as cabeças grandes, a mão no ombro dela faria as cabeças se encontrarem: aqui as duas mãos vão às coxas
  const j: Juntas = { ...juntasNoQuadro('inclinar', quadro), ombroDX: 12, ombroDZ: -17, cotoveloD: 20, cabecaY: -12 };
  const meio = new THREE.Vector3().addVectors(posicao(matrizMao(SENTADA, 1)), posicao(matrizMao(SENTADA, -1))).multiplyScalar(0.5);
  return (
    <group position={[1.05, 0, -0.4]}>
      <Banquinho />
      <Boneco v={ELENCO.bia} j={SENTADA} e={{ boca: 'sorriso', olharY: -1 }} />
      <group position={[meio.x, meio.y + 0.02, meio.z + 0.01]} rotation={[-0.75, 0, 0]}><Raspadinha /></group>
      <Boneco v={ELENCO.c1} j={j} e={{ boca: 'o', olharY: -1, olharX: -0.6, sobrancelha: 1 }} pos={[0.78, 0, -0.42]} giro={-28} />
    </group>
  );
};

// ---------- puxar: c2 puxa a mochila de c1, que tenta ir embora (cena de lado: os dois olham para +X) ----------
const ANDANDO: Juntas = {
  ...BASE, troncoX: 14, cabecaY: -55, cabecaX: -4,
  ombroEX: 45, ombroEZ: 20, cotoveloE: 35, ombroDX: -25, ombroDZ: 20, cotoveloD: 30,
  quadrilE: 28, joelhoE: 12, quadrilD: -18, joelhoD: 30,
};
const DemoPuxar: React.FC<{ quadro: number }> = ({ quadro }) => {
  // cena de lado: o giro diagonal do tronco (feito para a câmera de frente) não é preciso aqui
  const j: Juntas = { ...juntasNoQuadro('puxar', quadro), troncoY: 0, cabecaY: 0 };
  const f = forcaPuxao(quadro);
  const maoE = posicao(matrizMao(j, -1)), maoD = posicao(matrizMao(j, 1));
  const mMochila = matrizTronco(ANDANDO).multiply(new THREE.Matrix4().makeTranslation(0, 0.95, -0.19));
  const alca = v3(...ALCA_MOCHILA).applyMatrix4(mMochila);
  const meio = new THREE.Vector3().addVectors(maoE, maoD).multiplyScalar(0.5);
  const d = meio.z + 0.2 - alca.z - 0.05 * f; // quem é puxado recua um pouco a cada tranco
  const alcaCena = alca.clone().add(v3(0, 0, d));
  return (
    <group position={[1.15, 0, -0.75]} rotation={[0, Math.PI / 2, 0]}>
      <Boneco v={ELENCO.c2} j={j} e={{ boca: 'aberta', sobrancelha: -1 }} />
      <group position={[0, 0, d]}>
        <Boneco v={ELENCO.c1} j={ANDANDO} e={{ boca: 'o', olharX: -0.8, sobrancelha: 1 }} />
        <NaMatriz m={mMochila}><Mochila /></NaMatriz>
      </group>
      {/* alça de mão esticada até as duas mãos */}
      <Barra a={maoE} b={alcaCena} r={0.012} cor="#22324f" />
      <Barra a={maoD} b={alcaCena} r={0.012} cor="#22324f" />
    </group>
  );
};

export const DEMOS: PecaOficina[] = [
  { tipo: 'efeito', nome: 'abrirPacote+objetos', Componente: DemoAbrirPacote },
  { tipo: 'efeito', nome: 'escovarDentes+objetos', Componente: DemoEscovar },
  { tipo: 'efeito', nome: 'inclinar+outro', Componente: DemoInclinar },
  { tipo: 'efeito', nome: 'puxar+outro', Componente: DemoPuxar },
];
