// Pátio diurno: prédio recuado, banco e árvore nas laterais livres.
import React from 'react';
import { Caixa, Haste, mat } from './base';

const C = {
  cimento: '#cac5ba', calcada: '#e1dbcf', meioFio: '#f5eddd', linha: '#fff5de',
  parede: '#f3ce60', rodape: '#dfa64f', branco: '#fff8e7', telhado: '#cf7750',
  vidro: '#629daf', vidroClaro: '#93c9d8', porta: '#3d7b8c', metal: '#4b6262',
  madeira: '#b87940', madeiraClara: '#dba66b', tronco: '#996339',
  folha: '#54a454', folhaClara: '#79b95e', folhaEscura: '#429356',
  grama: '#91ba6d', terra: '#9b7650',
};

const JanelaEscola: React.FC<{ x: number }> = ({ x }) => (
  <group position={[x, 1.76, -7.6]}>
    {[-1, 1].map((lado) => <Caixa key={lado} p={[lado * 0.31, 0, 0.1]} t={[0.5, 1, 0.08]}
      cor={lado < 0 ? C.vidro : C.vidroClaro} sombra={false} recebeSombra={false} />)}
    {[-0.64, 0, 0.64].map((xMoldura) => <Caixa key={xMoldura} p={[xMoldura, 0, 0.22]} t={[0.12, 1.24, 0.12]} cor={C.branco} sombra={false} />)}
    {[-0.56, 0.56].map((y) => <Caixa key={y} p={[0, y, 0.22]} t={[1.16, 0.12, 0.12]} cor={C.branco} sombra={false} />)}
    <Caixa p={[0, -0.7, 0.28]} t={[1.52, 0.12, 0.36]} cor={C.branco} />
  </group>
);

const Predio: React.FC = () => (
  <group>
    {/* Fachada inteira cabe sob o céu da vitrine, incluindo a cobertura. */}
    <Caixa p={[0, 1.55, -8.4]} t={[11.4, 3.1, 1.6]} cor={C.parede} />
    <Caixa p={[0, 0.28, -7.48]} t={[11.4, 0.4, 0.12]} cor={C.rodape} sombra={false} />
    <Caixa p={[0, 3.13, -8.4]} t={[11.8, 0.18, 2]} cor={C.branco} sombra={false} />
    <Caixa p={[0, 3.3, -8.4]} t={[12, 0.12, 2.12]} cor={C.telhado} />
    {[-4.55, -2.65, 2.65, 4.55].map((x) => <JanelaEscola key={x} x={x} />)}
    <Caixa p={[0, 1.16, -7.48]} t={[1.56, 2.12, 0.12]} cor={C.porta} />
    {[-0.84, 0, 0.84].map((x) => <Caixa key={x} p={[x, 1.19, -7.34]} t={[0.12, 2.18, 0.12]} cor={C.branco} sombra={false} />)}
    <Caixa p={[0, 2.34, -7.34]} t={[1.8, 0.12, 0.12]} cor={C.branco} sombra={false} />
    {[-1, 1].map((lado) => (
      <group key={lado}>
        <Caixa p={[lado * 0.42, 1.68, -7.34]} t={[0.52, 0.7, 0.08]} cor={C.vidroClaro} sombra={false} recebeSombra={false} />
        <Caixa p={[lado * 0.2, 1.04, -7.24]} t={[0.08, 0.3, 0.08]} cor={C.branco} />
      </group>
    ))}
    <Caixa p={[0, 2.65, -7.13]} t={[2.16, 0.16, 1.3]} cor={C.branco} />
    <Caixa p={[0, 2.81, -7.13]} t={[2.28, 0.12, 1.42]} cor={C.telhado} />
  </group>
);

const Banco: React.FC = () => (
  <group position={[-2.8, 0, -1.65]} rotation={[0, 0.32, 0]}>
    {/* Banco em três quartos; topo do assento a 45 cm. */}
    {[-0.18, 0, 0.18].map((z) => <Caixa key={z} p={[0, 0.4, z]} t={[1.75, 0.1, 0.16]} cor={C.madeiraClara} />)}
    {[-1, 1].map((lado) => (
      <group key={lado}>
        <Caixa p={[lado * 0.59, 0.175, 0.18]} t={[0.12, 0.35, 0.12]} cor={C.metal} />
        <Caixa p={[lado * 0.59, 0.48, -0.18]} t={[0.12, 0.96, 0.12]} cor={C.metal} />
        <Caixa p={[lado * 0.59, 0.29, 0]} t={[0.12, 0.12, 0.54]} cor={C.metal} />
      </group>
    ))}
    {[0.68, 0.88].map((y) => <Caixa key={y} p={[0, y, -0.28]} t={[1.75, 0.16, 0.1]} cor={C.madeira} />)}
  </group>
);

const Arvore: React.FC = () => (
  <group position={[2.7, 0, -3.1]}>
    {/* Terra e grama rebaixadas em relação à borda do canteiro. */}
    <Caixa p={[0, 0.06, 0]} t={[1.8, 0.12, 1.62]} cor={C.terra} sombra={false} />
    <Caixa p={[0, 0.16, 0]} t={[1.8, 0.08, 1.62]} cor={C.grama} sombra={false} />
    {[-0.97, 0.97].map((x) => <Caixa key={x} p={[x, 0.12, 0]} t={[0.14, 0.24, 1.9]} cor={C.meioFio} />)}
    {[-0.88, 0.88].map((z) => <Caixa key={z} p={[0, 0.12, z]} t={[1.8, 0.24, 0.14]} cor={C.meioFio} />)}
    <mesh position={[0, 0.45, 0]} material={mat(C.tronco)} castShadow receiveShadow>
      <cylinderGeometry args={[0.17, 0.28, 0.62, 20]} />
    </mesh>
    <Haste a={[0, 0.5, 0]} b={[0, 2.08, 0]} r={0.16} cor={C.tronco} />
    {[-1, 1].map((lado) => <Haste key={lado} a={[0, 0.38, 0]} b={[lado * 0.42, 0.22, 0.24]} r={0.09} cor={C.tronco} />)}
    <Haste a={[0, 1.38, 0]} b={[-0.4, 2.06, 0]} r={0.09} cor={C.tronco} />
    <Haste a={[0, 1.52, 0]} b={[0.39, 2.13, 0.12]} r={0.1} cor={C.tronco} />
    {/* Esferas lisas; copa inteira abaixo de 3,1 m. */}
    <mesh position={[-0.42, 2.14, 0]} material={mat(C.folha)} castShadow receiveShadow>
      <sphereGeometry args={[0.66, 28, 20]} />
    </mesh>
    <mesh position={[0.42, 2.23, 0.06]} material={mat(C.folhaClara)} castShadow receiveShadow>
      <sphereGeometry args={[0.72, 28, 20]} />
    </mesh>
    <mesh position={[0, 2.42, -0.18]} material={mat(C.folhaEscura)} castShadow receiveShadow>
      <sphereGeometry args={[0.65, 28, 20]} />
    </mesh>
  </group>
);

const Faixas: React.FC = () => (
  <group>
    {/* Pintura 2,5 cm acima do piso, com traços de 12 cm. */}
    {[-3.35, 3.35].map((x) => <mesh key={x} position={[x, 0.025, -1.25]} rotation={[-Math.PI / 2, 0, 0]} material={mat(C.linha)} receiveShadow>
      <planeGeometry args={[0.12, 4.7]} />
    </mesh>)}
    {[-3.66, 1.16].map((z) => <mesh key={z} position={[0, 0.025, z]} rotation={[-Math.PI / 2, 0, 0]} material={mat(C.linha)} receiveShadow>
      <planeGeometry args={[6.82, 0.12]} />
    </mesh>)}
  </group>
);

export const PatioEscola: React.FC = () => (
  <group>
    <Caixa p={[0, -0.1, 0]} t={[40, 0.2, 40]} cor={C.cimento} sombra={false} />
    <Caixa p={[0, 0.05, -6.7]} t={[13, 0.1, 1.36]} cor={C.calcada} sombra={false} />
    <Caixa p={[0, 0.08, -5.87]} t={[13, 0.16, 0.22]} cor={C.meioFio} />
    <Predio />
    <Banco />
    <Arvore />
    <Faixas />
  </group>
);
