// Demonstrações das ações COM os objetos e o "outro" personagem. O contrato `acao` só leva juntas, então a
// vitrine mostra o Téo de mãos vazias; estas peças (tipo 'efeito') mostram a ação de verdade ao lado dele.
import * as THREE from 'three';
import React from 'react';
import { Boneco } from '../../../kit/Boneco';
import { ELENCO } from '../../../kit/elenco';
import { BASE, type Juntas } from '../../../kit/poses';
import type { PecaOficina } from '../tipos';
import { caminhoRiscar, FACE_ALVO, juntasNoQuadro, maoEntregar, RISCO } from './acoes';
import { bracoNo, posMao } from './cinematica';
import { Caneta, Cavalete, centroDia, Marcador, PONTA_CANETA, Traco } from './objetos';

const v3 = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);
const suave = (t: number) => { const k = Math.min(1, Math.max(0, t)); return k * k * (3 - 2 * k); };
const R = THREE.MathUtils.degToRad;

// ── riscar: c2 marca um X vermelho no dia do calendário. Visto por cima do ombro (o quadro fica entre ele e a câmera
// na vista de frente, então o grupo gira para mostrar a face riscada) ──
const DemoRiscar: React.FC<{ quadro: number }> = ({ quadro }) => {
  const j = juntasNoQuadro('riscar', quadro);
  const { traco1, traco2 } = caminhoRiscar(quadro);
  const c = RISCO.centro, m = RISCO.meio, z = FACE_ALVO - 0.011;
  const canto = (sx: number, sy: number) => v3(c.x + sx * m, c.y + sy * m, z);
  const mao = posMao(j, 1);
  const terminado = quadro >= 96;
  return (
    <group position={[1.95, 0, -0.35]} rotation={[0, R(-150), 0]}>
      <Boneco v={ELENCO.c2} j={j} e={{ boca: terminado ? 'sorriso' : 'neutra', olharX: 0.5, olharY: -0.2, sobrancelha: terminado ? 0.4 : -0.3 }} />
      <group position={mao}><Marcador /></group>
      {/* o X cai no 1º dia da linha de cima: o quadro fica para fora, longe da cabeça */}
      <group position={[c.x - centroDia(0, 0)[0], 0, FACE_ALVO + 0.007]}><Cavalete alturaCentro={c.y - centroDia(0, 0)[1]} /></group>
      {traco1 > 0 && <Traco a={canto(-1, 1)} b={canto(-1, 1).lerp(canto(1, -1), traco1)} />}
      {traco2 > 0 && <Traco a={canto(1, 1)} b={canto(1, 1).lerp(canto(-1, -1), traco2)} />}
    </group>
  );
};

// ── entregar: c1 oferece a caneta; Bia, virada para ele, estica a mão E até a ponta ──
// Os dois ficam a 3/4 da câmera (giros ±50°), lado a lado, para a caneta aparecer entre as mãos.
const DemoEntregar: React.FC<{ quadro: number }> = ({ quadro }) => {
  const j = juntasNoQuadro('entregar', quadro);
  const giroD = R(50), giroR = R(-50);
  const posD = v3(0.75, 0, 0.1), posR = v3(1.85, 0, 0.1);
  // a mão de Bia para logo depois da ponta da caneta (as mãos do boneco são grandes: 14 cm)
  const mao = maoEntregar(quadro);
  const pega = v3(mao.x, mao.y, mao.z + PONTA_CANETA + 0.06).applyAxisAngle(v3(0, 1, 0), giroD).add(posD);
  // Bia: mão E vai da cintura até a ponta da caneta entre os quadros 48 e 62
  const alvoLocal = pega.clone().sub(posR).applyAxisAngle(v3(0, 1, 0), -giroR);
  const repouso = v3(-0.3, 0.62, 0.12);
  const k = suave((quadro - 48) / 14);
  const jr0: Juntas = { ...BASE, troncoX: 3 * k, altura: -0.03, quadrilE: -3, quadrilD: 8, joelhoD: 5 };
  const jr: Juntas = {
    ...jr0, ...bracoNo(jr0, -1, repouso.clone().lerp(alvoLocal, k)),
    ombroDX: -4, ombroDZ: 10, cotoveloD: 12, cabecaX: 4 + 6 * k, cabecaY: -18, cabecaZ: -4 * k,
  };
  const recebeu = quadro >= 62;
  return (
    <group>
      <group position={posD} rotation={[0, giroD, 0]}>
        <Boneco v={ELENCO.c1} j={j} e={{ boca: 'sorriso', olharY: -0.3, sobrancelha: 0.3 }} />
        <group position={posMao(j, 1)}><Caneta /></group>
      </group>
      <group position={posR} rotation={[0, giroR, 0]}>
        <Boneco v={ELENCO.bia} j={jr} e={{ boca: recebeu ? 'sorriso' : 'o', olharY: -0.4, sobrancelha: 0.6 }} />
      </group>
    </group>
  );
};

export const DEMOS: PecaOficina[] = [
  { tipo: 'efeito', nome: 'riscar+objetos', Componente: DemoRiscar },
  { tipo: 'efeito', nome: 'entregar+outro', Componente: DemoEntregar },
];
