// Objeto: figurinha dourada (cartão de 6 x 9 cm, 2 mm) com moldura dourada escura, painel dourado claro com faixas de brilho,
// estrela branca grande (60% da largura) com contorno e três brilhos brancos de quatro pontas que pulsam com o quadro.
// Em pé: frente para +Z, base em y = 0. `deitada`: frente para cima, centrada na origem.
import React from 'react';
import { useCurrentFrame } from 'remotion';
import { mat, Ret, Tracos, Deitavel, type Traco } from './base';

const C = { moldura: '#c8860f', painel: '#ffd84a', faixa: '#fff3b8', contornoEstrela: '#c97a0a', estrela: '#ffffff', brilho: '#ffffff' };
const W = 0.06, H = 0.09, D = 0.002;
const zc = (k: number) => D + 0.0003 + k * 0.0006; // camadas da frente, 0,6 mm entre elas

// dourado claro: pouco metal (sem mapa de ambiente o metal escurece), rugosidade baixa para o reflexo do sol e um leve acendimento
const dourado = (cor: string) => mat(cor, { rug: 0.35, metal: 0.15, brilho: 0.22 });

// painel: 5 x 8 cm; faixas de brilho a 45°, recortadas dentro do painel (a moldura cobre as pontas)
const PW = 0.05, PH = 0.08;
const faixa = (c: number, l: number): Traco => {
  const a = PW / 2 - l / 2, b = PH / 2 - l / 2; // reta y = x + c dentro do retângulo |x| ≤ a, |y| ≤ b
  const x1 = Math.max(-a, -b - c), x2 = Math.min(a, b - c);
  return [x1, x1 + c, x2, x2 + c];
};

/** Estrela de 5 pontas: pentágono no meio + 5 triângulos (prismas de 3 lados escalados). R = raio das pontas. */
const Estrela: React.FC<{ R: number; z: number; cor: string; brilho?: number }> = ({ R, z, cor, brilho = 0 }) => {
  const m = mat(cor, { brilho });
  const ri = 0.382 * R, d = 0.0004;
  return (
    <group position={[0, 0, z]}>
      <group rotation={[0, 0, Math.PI / 5]}>
        <mesh rotation={[-Math.PI / 2, 0, 0]} material={m} receiveShadow><cylinderGeometry args={[ri, ri, d, 5]} /></mesh>
      </group>
      {[0, 1, 2, 3, 4].map((k) => (
        <group key={k} rotation={[0, 0, (k * 2 * Math.PI) / 5]}>
          {/* triângulo equilátero de raio 1 escalado: base 0,449R, altura 0,691R, base encostada no pentágono */}
          <mesh position={[0, 0.535 * R, 0]} rotation={[-Math.PI / 2, 0, 0]} scale={[0.2593 * R, 1, 0.4607 * R]} material={m} receiveShadow>
            <cylinderGeometry args={[1, 1, d, 3]} />
          </mesh>
        </group>
      ))}
    </group>
  );
};

/** Brilho de quatro pontas: dois losangos cruzados, branco aceso, sem sombra. */
const Brilho: React.FC<{ x: number; y: number; z: number; tam: number; fase: number; q: number }> = ({ x, y, z, tam, fase, q }) => {
  const s = tam * (0.72 + 0.28 * Math.sin(q * 0.16 + fase));
  const m = mat(C.brilho, { brilho: 1 });
  const losango = (giro: number) => (
    <group rotation={[0, 0, giro]}>
      <group scale={[s * 0.24, s, 1]}>
        <mesh rotation={[0, 0, Math.PI / 4]} material={m}><boxGeometry args={[Math.SQRT1_2, Math.SQRT1_2, 0.0006]} /></mesh>
      </group>
    </group>
  );
  return (
    <group position={[x, y, z]} rotation={[0, 0, 0.05 * Math.sin(q * 0.05 + fase)]}>
      {losango(0)}
      {losango(Math.PI / 2)}
    </group>
  );
};

export const FigurinhaDourada: React.FC<{ deitada?: boolean; brilhos?: boolean }> = ({ deitada = false, brilhos = true }) => {
  const q = useCurrentFrame();
  return (
    <Deitavel deitada={deitada} alto={H}>
      <group position={[0, H / 2, 0]}>
        {/* corpo = moldura dourada escura; painel dourado claro por cima */}
        {/* sem sombra projetada: com 2 mm, o desvio da sombra do sol (~3 cm) a soltaria do cartão; a cena põe sombra de contato */}
        <Ret w={W} h={H} d={D} r={0.005} z={D / 2} m={dourado(C.moldura)} />
        <Ret w={PW} h={PH} d={0.0004} r={0.003} z={zc(0)} m={dourado(C.painel)} />
        <Tracos tracos={[faixa(0.018, 0.009)]} l={0.009} z={zc(1)} m={dourado(C.faixa)} />
        <Tracos tracos={[faixa(-0.006, 0.004)]} l={0.004} z={zc(1)} m={dourado(C.faixa)} />
        {/* estrela branca grande (3,6 cm) com contorno dourado escuro */}
        <Estrela R={0.0235} z={zc(2)} cor={C.contornoEstrela} />
        <Estrela R={0.019} z={zc(3)} cor={C.estrela} brilho={0.35} />
        {brilhos && (<>
          <Brilho x={0.031} y={0.043} z={0.008} tam={0.034} fase={0} q={q} />
          <Brilho x={-0.032} y={-0.036} z={0.008} tam={0.026} fase={2.1} q={q} />
          <Brilho x={0.033} y={-0.012} z={0.008} tam={0.016} fase={4.2} q={q} />
        </>)}
      </group>
    </Deitavel>
  );
};
