// Nota de 12 × 6 cm; espessura toy de 1,2 mm e frente para +Z.
import React from 'react';
import { Caixa } from './base';

const C = { papel: '#b9f582', faixa: '#62bd61', tinta: '#123f24' };
type Retangulo = { x: number; y: number; largura: number; altura: number; cor: string };

const marcas: Retangulo[] = [];
const marcar = (x: number, y: number, largura: number, altura: number, cor = C.tinta) => {
  marcas.push({ x, y, largura, altura, cor });
};

// Duas faixas largas substituem a moldura fina.
marcar(-0.054, 0.03, 0.006, 0.048, C.faixa);
marcar(0.054, 0.03, 0.006, 0.048, C.faixa);

// Algarismos de 44 mm com traços de 6 mm. O 1 tem bandeira e pé.
marcar(-0.036, 0.03, 0.006, 0.044);
marcar(-0.040, 0.049, 0.014, 0.006);
marcar(-0.036, 0.011, 0.018, 0.006);
for (const x of [-0.007, 0.027]) {
  for (const y of [0.011, 0.049]) marcar(x, y, 0.026, 0.006);
  for (const lado of [-1, 1]) {
    marcar(x + lado * 0.010, 0.03, 0.006, 0.038);
  }
}

// Cada cor ocupa uma região da folha. Não há placas sobrepostas ao papel.
const limites = (eixo: 'x' | 'y') => {
  const tamanho = eixo === 'x' ? 'largura' : 'altura';
  const bordas = eixo === 'x' ? [-0.06, 0.06] : [0, 0.06];
  for (const marca of marcas) {
    bordas.push(marca[eixo] - marca[tamanho] / 2, marca[eixo] + marca[tamanho] / 2);
  }
  return [...new Set(bordas.map((borda) => Math.round(borda * 1e6) / 1e6))].sort((a, b) => a - b);
};

const xs = limites('x'), ys = limites('y');
const corEm = (x: number, y: number) => {
  let cor = C.papel;
  for (const marca of marcas) {
    if (Math.abs(x - marca.x) < marca.largura / 2 && Math.abs(y - marca.y) < marca.altura / 2) cor = marca.cor;
  }
  return cor;
};

// Une células vizinhas da mesma cor para reduzir a quantidade de caixas.
const trechos: Retangulo[] = [];
for (let j = 0; j < ys.length - 1; j++) {
  const y = (ys[j] + ys[j + 1]) / 2, altura = ys[j + 1] - ys[j];
  let inicio = xs[0], cor = corEm((xs[0] + xs[1]) / 2, y);
  for (let i = 1; i < xs.length; i++) {
    const proxima = i < xs.length - 1 ? corEm((xs[i] + xs[i + 1]) / 2, y) : undefined;
    if (proxima !== cor) {
      trechos.push({ x: (inicio + xs[i]) / 2, y, largura: xs[i] - inicio, altura, cor });
      inicio = xs[i];
      if (proxima !== undefined) cor = proxima;
    }
  }
}

export const NotaCem: React.FC = () => (
  <group>
    {trechos.map(({ x, y, largura, altura, cor }, i) => (
      <Caixa key={i} p={[x, y, 0]} t={[largura, altura, 0.0012]} cor={cor} />
    ))}
  </group>
);
