const LuzDaJanela: React.FC = () => {
  const cena = useThree((estado) => estado.scene);
  const luz = useRef<THREE.DirectionalLight>(null);
  const alvo = useMemo(() => {
    const objeto = new THREE.Object3D();
    objeto.position.set(0, 0, 0.5);
    return objeto;
  }, []);

  useLayoutEffect(() => {
    const anteriores: { luz: THREE.DirectionalLight; intensidade: number; sombra: boolean }[] = [];
    // Uma direção de sombra para o quarto, restaurada ao trocar de peça.
    cena.traverse((objeto) => {
      if (objeto instanceof THREE.DirectionalLight && objeto !== luz.current) {
        anteriores.push({ luz: objeto, intensidade: objeto.intensity, sombra: objeto.castShadow });
        objeto.intensity = 0;
        objeto.castShadow = false;
      }
    });
    return () => {
      anteriores.forEach(({ luz: anterior, intensidade, sombra }) => {
        anterior.intensity = intensidade;
        anterior.castShadow = sombra;
      });
    };
  }, [cena]);

  return (
    <group>
      <primitive object={alvo} />
      <directionalLight ref={luz} target={alvo} position={[1.9, 5, -3]} color="#fff0d2" intensity={2.4}
        castShadow shadow-mapSize={[4096, 4096]} shadow-radius={3} shadow-bias={-0.00015} shadow-normalBias={0.01}
        shadow-camera-left={-6} shadow-camera-right={6} shadow-camera-top={6} shadow-camera-bottom={-6}
        shadow-camera-near={0.1} shadow-camera-far={20} />
    </group>
  );
};

