import React from 'react';
import { Caixa, Esfera, mat } from './base';

const C = { preto: '#171e27', branco: '#fff7e8', laranja: '#f5a128', olho: '#090d13' };

// 60 cm de altura. Base no chão; corpo e rosto virados juntos para o lado.
export const Pinguim: React.FC = () => (
  <group rotation={[0, -0.62, 0]}>
    <mesh position={[0, 0.33, 0]} material={mat(C.preto)} castShadow receiveShadow>
      <capsuleGeometry args={[0.16, 0.22, 8, 24]} />
    </mesh>
    <Esfera p={[0, 0.28, 0.112]} t={[0.125, 0.19, 0.066]} cor={C.branco} />
    {/* Bochechas claras deixam os olhos de ponto legíveis. */}
    {([-1, 1] as const).map((lado) => (
      <group key={lado}>
        <Esfera p={[lado * 0.058, 0.466, 0.122]} t={[0.057, 0.071, 0.043]} cor={C.branco} />
        <Esfera p={[lado * 0.059, 0.482, 0.162]} t={[0.012, 0.015, 0.009]} cor={C.olho} />
        <Caixa p={[lado * 0.175, 0.29, -0.006]} t={[0.045, 0.245, 0.095]} r={[0.1, 0, lado * 0.24]} cor={C.preto} />
        <Caixa p={[lado * 0.085, 0.025, 0.065]} t={[0.115, 0.05, 0.195]} r={[0, lado * -0.12, 0]} cor={C.laranja} />
      </group>
    ))}
    {/* Cone obtido do cilindro com raio superior zero; aponta para +Z. */}
    <mesh position={[0, 0.435, 0.183]} rotation={[Math.PI / 2, 0, 0]} material={mat(C.laranja)} castShadow receiveShadow>
      <cylinderGeometry args={[0, 0.035, 0.082, 12]} />
    </mesh>
  </group>
);
