// Efeito: a pergunta "E se...?" em letras 3D grossas e arredondadas, amarelas com contorno preto, flutuando no ar.
// Cada letra é feita de traços redondos: cápsulas (retas), arcos de toro (curvas) e esferas (pontos e pontas).
// O contorno é o mesmo traço, mais grosso, em preto e recuado. O título não faz sombra (não suja o chão nem o boné).
import React from 'react';
import { mat, suave, TAU, type V3 } from './base';

// grade: maiúscula com 10 de altura (linha central do traço), minúscula com 7; ângulos em graus
type Peca =
  | { k: 'reta'; a: [number, number]; b: [number, number] }
  | { k: 'arco'; c: [number, number]; r: number; de: number; ate: number } // de -> ate no sentido anti-horário
  | { k: 'bola'; c: [number, number]; r?: number };
type Glifo = { w: number; p: Peca[] };

const E: Glifo = { w: 5.5, p: [
  { k: 'reta', a: [0, 0], b: [0, 10] }, { k: 'reta', a: [0, 10], b: [5.5, 10] },
  { k: 'reta', a: [0, 5], b: [4.5, 5] }, { k: 'reta', a: [0, 0], b: [5.5, 0] },
] };
// "s": arco de cima abre para a direita-baixo, arco de baixo abre para a esquerda-cima
const s: Glifo = { w: 3.6, p: [
  { k: 'arco', c: [1.8, 5.2], r: 1.8, de: 20, ate: 270 },
  { k: 'arco', c: [1.8, 1.8], r: 1.8, de: -160, ate: 90 },
  { k: 'bola', c: [1.8 + 1.8 * Math.cos(20 * Math.PI / 180), 5.2 + 1.8 * Math.sin(20 * Math.PI / 180)] },
  { k: 'bola', c: [1.8 + 1.8 * Math.cos(-160 * Math.PI / 180), 1.8 + 1.8 * Math.sin(-160 * Math.PI / 180)] },
] };
// "e": barra no meio e volta quase completa, aberta embaixo à direita
const e: Glifo = { w: 6.4, p: [
  { k: 'reta', a: [0, 3.5], b: [6.4, 3.5] },
  { k: 'arco', c: [3.2, 3.5], r: 3.2, de: 0, ate: 315 },
  { k: 'bola', c: [3.2 + 3.2 * Math.cos(-45 * Math.PI / 180), 3.5 + 3.2 * Math.sin(-45 * Math.PI / 180)] },
] };
const ponto: Glifo = { w: 0, p: [{ k: 'bola', c: [0, 0.4], r: 1.45 }] };
// "?": gancho, haste curta e ponto
const interrog: Glifo = { w: 5.2, p: [
  { k: 'arco', c: [2.6, 7.4], r: 2.6, de: -90, ate: 160 },
  { k: 'bola', c: [2.6 + 2.6 * Math.cos(160 * Math.PI / 180), 7.4 + 2.6 * Math.sin(160 * Math.PI / 180)] },
  { k: 'reta', a: [2.6, 4.8], b: [2.6, 3.2] },
  { k: 'bola', c: [2.6, 0.4], r: 1.45 },
] };

// texto: glifo + avanço até o próximo (o espaço entre "E" e "se" é maior)
const TEXTO: [Glifo, number][] = [[E, 9.5], [s, 3.6], [e, 3.9], [ponto, 4.1], [ponto, 4.1], [ponto, 3.8], [interrog, 0]];
const LARGURA = TEXTO.reduce((a, [g, esp]) => a + g.w + esp, 0);

const R = 1.05; // raio do traço amarelo
const BORDA = 0.75; // quanto o contorno preto passa do amarelo
const RECUO = 1.4; // contorno atrás do amarelo (a frente amarela fica sempre por cima)
const C = { letra: '#ffd23f', contorno: '#1b1b1f' };

/** Um traço (amarelo ou contorno): `extra` engrossa o raio, `z` recua. */
const Traco: React.FC<{ p: Peca; extra: number; z: number; cor: string; brilho: number }> = ({ p, extra, z, cor, brilho }) => {
  const m = mat(cor, brilho);
  if (p.k === 'reta') {
    const [ax, ay] = p.a, [bx, by] = p.b;
    const comp = Math.hypot(bx - ax, by - ay);
    const ang = Math.atan2(by - ay, bx - ax) - Math.PI / 2;
    return (
      <mesh position={[(ax + bx) / 2, (ay + by) / 2, z]} rotation={[0, 0, ang]} material={m}>
        <capsuleGeometry args={[R + extra, comp, 6, 16]} />
      </mesh>
    );
  }
  if (p.k === 'arco') {
    const de = (p.de * Math.PI) / 180, arco = ((p.ate - p.de) * Math.PI) / 180;
    return (
      <mesh position={[p.c[0], p.c[1], z]} rotation={[0, 0, de]} material={m}>
        <torusGeometry args={[p.r, R + extra, 12, 36, arco]} />
      </mesh>
    );
  }
  return (
    <mesh position={[p.c[0], p.c[1], z]} material={m}>
      <sphereGeometry args={[(p.r ?? R) + extra, 16, 12]} />
    </mesh>
  );
};

const Letra: React.FC<{ g: Glifo }> = ({ g }) => (
  <group>
    {g.p.map((p, i) => (
      <group key={i}>
        <Traco p={p} extra={0} z={0} cor={C.letra} brilho={0.12} />
        <Traco p={p} extra={BORDA} z={-RECUO} cor={C.contorno} brilho={0} />
      </group>
    ))}
  </group>
);

/** `pos`: centro do título (m); `altura`: altura da maiúscula (m, linha central do traço).
 *  Padrão: no ar, em cima e à esquerda do personagem na origem (na câmera do canal, acima do boné
 *  não cabe um título legível sem cortar). Num plano mais aberto, passe `pos` acima da cena. */
export const TituloFlutuante: React.FC<{ quadro: number; pos?: V3; altura?: number }> = ({ quadro, pos = [-1.18, 1.78, 0.2], altura = 0.24 }) => {
  const u = altura / 10;
  let x = -LARGURA / 2;
  // flutua: sobe e desce devagar e balança um pouco
  const boia = 0.025 * Math.sin((TAU * quadro) / 90);
  return (
    <group position={[pos[0], pos[1] + boia, pos[2]]}
      rotation={[0.05 * Math.sin((TAU * quadro) / 150), 0.12 + 0.05 * Math.sin((TAU * quadro) / 110), 0.04 + 0.02 * Math.sin((TAU * quadro) / 130)]}>
      <group scale={u} position={[0, -5 * u, 0]}>
        {TEXTO.map(([g, esp], i) => {
          const x0 = x; x += g.w + esp;
          // entrada em sequência: cada letra cresce com um pequeno exagero (passa de 1 e volta)
          const t = suave((quadro - 4 * i) / 14);
          const pulo = t * (1 + 0.18 * Math.sin(Math.PI * t));
          // balanço em onda, letra a letra
          const fase = (TAU * quadro) / 60 - i * 0.7;
          return (
            <group key={i} position={[x0 + g.w / 2, 0.5 * Math.sin(fase), 0]} rotation={[0, 0, 0.04 * Math.sin(fase + 1.2)]} scale={pulo}>
              <group position={[-g.w / 2, 0, 0]}><Letra g={g} /></group>
            </group>
          );
        })}
      </group>
    </group>
  );
};
