// Lógica pura do montador: dado a ficha e o quadro, calcula pose, posição, expressão e câmera.
// Sem React aqui, para poder testar sem renderizar.
import { BASE, misturar, pose, type Juntas } from '../kit/poses';
import type { Expressao } from '../kit/Boneco';
import type { Ficha } from './schema';
import { ACOES_OFICINA, CENARIOS_3D } from './pecas';

type P = Ficha['personagens'][number];
type V3 = [number, number, number];
const TRANS = 8; // quadros de transição entre ações
const suave = (t: number) => { const k = Math.min(1, Math.max(0, t)); return k * k * (3 - 2 * k); };
const fimDoBloco = (p: P, k: number, dur: number) => (k + 1 < p.acoes.length ? p.acoes[k + 1].q : dur);

/** Posição (x,z) e giro do personagem no quadro, seguindo os blocos "andar". */
export function caminho(p: P, q: number, dur: number): { xz: [number, number]; giro: number; andando: boolean } {
  let xz: [number, number] = [...p.pos];
  for (let k = 0; k < p.acoes.length; k++) {
    const a = p.acoes[k];
    if (q < a.q) break;
    if (a.acao !== 'andar' || !a.ate) continue;
    const fim = fimDoBloco(p, k, dur), t = suave((q - a.q) / (fim - a.q));
    const de = xz, ate = a.ate as [number, number];
    const atual: [number, number] = [de[0] + (ate[0] - de[0]) * t, de[1] + (ate[1] - de[1]) * t];
    if (q < fim) return { xz: atual, giro: (Math.atan2(ate[0] - de[0], ate[1] - de[1]) * 180) / Math.PI, andando: true };
    xz = [...ate];
  }
  return { xz, giro: p.giro, andando: false };
}

function poseDaAcao(a: P['acoes'][number], q: number): Juntas {
  const d = q - a.q;
  switch (a.acao) {
    case 'acenar': return misturar(pose('acenar'), pose('acenar2'), 0.5 + 0.5 * Math.sin(d / 4));
    case 'andar': return misturar(pose('andar1'), pose('andar2'), 0.5 + 0.5 * Math.sin(d / 3.2));
    case 'pular': return { ...pose('comemorar'), altura: Math.abs(Math.sin(d / 5)) * 0.14 };
    default: {
      const o = ACOES_OFICINA[a.acao]; // ação da oficina: pose parcial + animação opcional
      if (o) return { ...pose('parado'), ...o.pose, ...(o.animar ? o.animar(d) : {}) };
      return pose(a.acao);
    }
  }
}

export function juntasNoQuadro(p: P, q: number): Juntas {
  let k = 0; while (k + 1 < p.acoes.length && p.acoes[k + 1].q <= q) k++;
  const atual = poseDaAcao(p.acoes[k], q);
  const base = k === 0 || q - p.acoes[k].q >= TRANS ? atual : misturar(poseDaAcao(p.acoes[k - 1], q), atual, (q - p.acoes[k].q) / TRANS);
  return vida(p, q, base);
}

/** Vida (14/11, prévia 1 estava parada demais): respiração e balanço leve sempre; quem está FALANDO gesticula
 *  (antebraço e cabeça acompanham as palavras) e se inclina um pouco. Tudo pelo quadro, determinístico. */
function vida(p: P, q: number, j: Juntas): Juntas {
  const s = semente(p.id), r = { ...j };
  r.troncoX += Math.sin((q + s) / 38) * 1.2; r.troncoY += Math.sin((q + s) / 61) * 2; r.cabecaY += Math.sin((q + s * 2) / 47) * 3;
  const w = p.falando ?? [];
  // falando = dentro de uma palavra ou num respiro curto (<= 10 quadros) entre palavras
  const fala = w.some(([a, b]) => q >= a - 4 && q <= b + 10);
  if (fala && p.acoes.every((a) => a.acao !== 'andar')) {
    const g = Math.sin((q + s) / 5.5);
    r.cotoveloD += 18 + 14 * g; r.ombroDX += 14 + 8 * g; r.cabecaX += 3 * Math.sin((q + s) / 4);
    r.cotoveloE += 6 + 6 * Math.sin((q + s) / 7); r.troncoX += 2;
  }
  return r;
}

const OLHAR: Record<string, [number, number]> = { frente: [0, 0], esquerda: [1, 0], direita: [-1, 0], cima: [0, 1], baixo: [0, -1] };
const SOBR: Record<string, number> = { brava: -1, normal: 0, surpresa: 1 };
function semente(s: string) { let h = 7; for (const c of s) h = (h * 31 + c.charCodeAt(0)) % 997; return h; }

export function expressaoNoQuadro(p: P, q: number): Expressao {
  let k = 0; while (k + 1 < p.expressoes.length && p.expressoes[k + 1].q <= q) k++;
  const e = p.expressoes[k];
  // piscada automática a cada ~3,3 s, deslocada por personagem (determinística)
  const ciclo = 100, fase = (q + semente(p.id)) % ciclo;
  const piscar = fase < 6 ? Math.sin((fase / 6) * Math.PI) : 0;
  const [ox, oy] = OLHAR[e.olhar];
  // fala: durante cada palavra a boca abre e fecha (abre no meio da palavra); fora das palavras, a boca da expressão
  const w = (p.falando ?? []).find(([a, b]) => q >= a && q <= b);
  const boca = w ? (Math.floor((q - w[0]) / 3) % 2 === 0 ? 'aberta' : (e.boca === 'aberta' ? 'o' : e.boca)) : e.boca;
  return { boca, sobrancelha: SOBR[e.sobrancelha], olharX: ox, olharY: oy, piscar };
}

const PLANO = { geral: { d: 7.5, h: 2.6, fov: 38 }, medio: { d: 4.0, h: 1.75, fov: 36 }, close: { d: 2.3, h: 1.6, fov: 32 } /* 14/11: era 1,9 e cortava a cabeça */ };
const ANG = { frente: 0, tresQuartosEsq: -35, tresQuartosDir: 35, baixo: 0, alto: 0 };
// "mão no ombro": tremor bem leve e lento em TODO plano (a referência nunca fica 100% parada). Determinístico.
const tremor = (q: number, s: number) => [Math.sin((q + s) / 23) * 0.012 + Math.sin((q + s) / 9.7) * 0.004, Math.sin((q + s * 3) / 29) * 0.01] as const;

/** Câmera nunca sai do espaço do cenário (14/11, prévia 3: plano aberto em sala pequena atravessava a parede e mostrava só parede).
 *  Se a posição passa da área livre (+40 cm), aproxima a câmera do alvo e abre a lente na mesma proporção. */
function dentroDoCenario(f: Ficha, c: { pos: V3; alvo: V3; fov: number; foco: number }) {
  const lim = CENARIOS_3D[f.cenario]?.limites; if (!lim) return c;
  const [x0, x1, z0, z1] = [-lim.limiteX - 0.4, lim.limiteX + 0.4, lim.limiteZ[0] - 0.4, lim.limiteZ[1] + 0.4];
  const [px, py, pz] = c.pos, [ax, ay, az] = c.alvo;
  let k = 1; // fração do caminho alvo→câmera que cabe dentro da caixa
  if (px > x1) k = Math.min(k, (x1 - ax) / (px - ax)); if (px < x0) k = Math.min(k, (x0 - ax) / (px - ax));
  if (pz > z1) k = Math.min(k, (z1 - az) / (pz - az)); if (pz < z0) k = Math.min(k, (z0 - az) / (pz - az));
  if (!(k < 1) || k <= 0.05) return c;
  const pos: V3 = [ax + (px - ax) * k, ay + (py - ay) * k, az + (pz - az) * k];
  const fov = Math.min(75, (2 * Math.atan(Math.tan((c.fov * Math.PI) / 360) / k) * 180) / Math.PI);
  return { pos, alvo: c.alvo, fov, foco: c.foco * k };
}

export function cameraNoQuadro(f: Ficha, q: number): { pos: V3; alvo: V3; fov: number; foco: number } { return dentroDoCenario(f, cameraBruta(f, q)); }

function cameraBruta(f: Ficha, q: number): { pos: V3; alvo: V3; fov: number; foco: number } {
  const t = suave(q / Math.max(1, f.duracao - 1));
  const ondeEsta = (id: string) => { const p = f.personagens.find((x) => x.id === id)!; const c = caminho(p, q, f.duracao); return { xz: c.xz, giro: c.giro, alt: juntasNoQuadro(p, q).altura }; };
  const [tx, ty] = tremor(q, f.duracao);
  const mov = (d: number) => (f.camera.movimento === 'aproximar' ? d * (1 - 0.22 * t) : f.camera.movimento === 'afastar' ? d * (1 + 0.22 * t) : d);
  const lado = f.camera.movimento === 'lateral' ? 0.35 * (t - 0.5) : 0;

  // OMBRO (over the shoulder): câmera atrás e ao lado do ombro de "de", olhando para o rosto do alvo (o contraplano da conversa)
  if (f.camera.plano === 'ombro' && f.camera.de) {
    const a = ondeEsta([f.camera.alvo].flat()[0]), b = ondeEsta(f.camera.de);
    const vx = a.xz[0] - b.xz[0], vz = a.xz[1] - b.xz[1], L = Math.hypot(vx, vz) || 1, ux = vx / L, uz = vz / L;
    const dist = mov(1.7); // 14/11: 0,95 deixava a cabeça de quem escuta ocupando metade do quadro
    const pos: V3 = [b.xz[0] - ux * dist + uz * (0.85 + lado) + tx, 1.72 + b.alt + ty, b.xz[1] - uz * dist - ux * (0.85 + lado)];
    const alvo: V3 = [a.xz[0], 1.42 + a.alt, a.xz[1]];
    return { pos, alvo, fov: 38, foco: Math.hypot(alvo[0] - pos[0], alvo[1] - pos[1], alvo[2] - pos[2]) };
  }
  // DETALHE: perto das mãos/objeto do alvo (a tela 2D entra por cima quando houver)
  if (f.camera.plano === 'detalhe') {
    const a = ondeEsta([f.camera.alvo].flat()[0]), r = (a.giro * Math.PI) / 180;
    const hx = a.xz[0] + Math.cos(r) * -0.32 + Math.sin(r) * 0.28, hz = a.xz[1] - Math.sin(r) * -0.32 + Math.cos(r) * 0.28;
    const d = mov(0.9);
    const pos: V3 = [hx + Math.sin(r) * d + lado + tx, 1.25 + ty, hz + Math.cos(r) * d];
    return { pos, alvo: [hx, 0.92 + a.alt, hz], fov: 30, foco: d };
  }
  const ids = [f.camera.alvo].flat();
  const pts = ids.map((id) => ondeEsta(id).xz);
  const alt = Math.min(...ids.map((id) => ondeEsta(id).alt));
  const cx = pts.reduce((a, p) => a + p[0], 0) / pts.length, cz = pts.reduce((a, p) => a + p[1], 0) / pts.length;
  const espalho = Math.max(0, ...pts.map((p) => Math.hypot(p[0] - cx, p[1] - cz)));
  const pl = PLANO[f.camera.plano as keyof typeof PLANO];
  // grupo: afasta o suficiente para caber todo mundo (meia largura visível >= espalho + margem)
  const meiaLarg = espalho + 0.9, tanH = Math.tan(((pl.fov / 2) * Math.PI) / 180) * (16 / 9);
  let d = Math.max(pl.d, meiaLarg / tanH), yaw = ANG[f.camera.angulo];
  const h = f.camera.angulo === 'baixo' ? 0.45 : f.camera.angulo === 'alto' ? pl.h + 1.6 : pl.h + (d - pl.d) * 0.15;
  d = mov(d);
  if (f.camera.movimento === 'lateral') yaw += 15 * t;
  const rr = (yaw * Math.PI) / 180;
  const alvo: V3 = [cx, (f.camera.plano === 'close' ? 1.5 : 1.25) + alt, cz];
  const pos: V3 = [cx + Math.sin(rr) * d + tx, h + alt + ty, cz + Math.cos(rr) * d];
  const foco = Math.hypot(pos[0] - cx, pos[1] - 1.5, pos[2] - cz);
  return { pos, alvo, fov: pl.fov, foco };
}
export { BASE };
