// Base do lote r15-objeto: cache de material por cor (com brilho e translucidez) e formas do kit, no padrão do Quadra.tsx.
import * as THREE from 'three';
import React from 'react';

export type V3 = [number, number, number];

const cache = new Map<string, THREE.MeshStandardMaterial>();
/** Material chapado (roughness 0.85). `brilho` > 0 acende a cor; `opac` < 1 deixa translúcido (vidro, rastro). */
export const mat = (cor: string, o: { brilho?: number; opac?: number; rug?: number } = {}) => {
  const { brilho = 0, opac = 1, rug = 0.85 } = o;
  const k = [cor, brilho, opac, rug].join('|');
  let m = cache.get(k);
  if (!m) {
    m = new THREE.MeshStandardMaterial({ color: cor, roughness: rug });
    if (brilho > 0) { m.emissive = new THREE.Color(cor); m.emissiveIntensity = brilho; }
    if (opac < 1) { m.transparent = true; m.opacity = opac; m.depthWrite = false; }
    cache.set(k, m);
  }
  return m;
};

export const Caixa: React.FC<{ p: V3; t: V3; m: THREE.Material; r?: V3; sombra?: boolean; recebe?: boolean }> = ({ p, t, m, r, sombra = true, recebe = true }) => (
  <mesh position={p} rotation={r} material={m} castShadow={sombra} receiveShadow={recebe}><boxGeometry args={t} /></mesh>
);

export const Esfera: React.FC<{ p: V3; r: number; m: THREE.Material; esc?: V3; sombra?: boolean }> = ({ p, r, m, esc, sombra = true }) => (
  <mesh position={p} scale={esc} material={m} castShadow={sombra} receiveShadow><sphereGeometry args={[r, 20, 14]} /></mesh>
);

/** Cilindro com o eixo em X, Y ou Z. */
export const Cilindro: React.FC<{ p: V3; r: number; h: number; m: THREE.Material; eixo?: 'x' | 'y' | 'z'; seg?: number; sombra?: boolean }> = ({ p, r, h, m, eixo = 'y', seg = 24, sombra = true }) => (
  <mesh position={p} rotation={eixo === 'x' ? [0, 0, Math.PI / 2] : eixo === 'z' ? [Math.PI / 2, 0, 0] : undefined} material={m} castShadow={sombra} receiveShadow>
    <cylinderGeometry args={[r, r, h, seg]} />
  </mesh>
);

// início do quarto de cilindro de cada canto (cilindro deitado em Z: x = r·sen θ, y = -r·cos θ)
const QUARTO: Record<string, number> = { '1,1': Math.PI / 2, '1,-1': 0, '-1,1': Math.PI, '-1,-1': 1.5 * Math.PI };

/** Retângulo de cantos arredondados no plano XY, espessura d em Z: 3 caixas lado a lado + 4 quartos de cilindro.
 *  Nenhuma peça se sobrepõe a outra (sem z-fighting nem tampa recuada, que deixava "recortes" nos cantos). */
export const Ret: React.FC<{ w: number; h: number; d: number; r: number; p: V3; m: THREE.Material; sombra?: boolean }> = ({ w, h, d, r, p, m, sombra = false }) => (
  <group position={p}>
    <mesh material={m} castShadow={sombra} receiveShadow><boxGeometry args={[w, h - 2 * r, d]} /></mesh>
    {[-1, 1].map((s) => (
      <mesh key={s} position={[0, s * (h / 2 - r / 2), 0]} material={m} castShadow={sombra} receiveShadow><boxGeometry args={[w - 2 * r, r, d]} /></mesh>
    ))}
    {([[-1, -1], [1, -1], [-1, 1], [1, 1]] as const).map(([sx, sy]) => (
      <mesh key={`${sx}${sy}`} position={[sx * (w / 2 - r), sy * (h / 2 - r), 0]} rotation={[Math.PI / 2, 0, 0]} material={m} castShadow={sombra} receiveShadow>
        <cylinderGeometry args={[r, r, d, 8, 1, false, QUARTO[`${sx},${sy}`], Math.PI / 2]} />
      </mesh>
    ))}
  </group>
);

/** Brilho de 4 pontas (dois losangos cruzados, acesos, sem sombra) no plano XY. */
export const Brilho: React.FC<{ p: V3; t: number; cor?: string; giro?: number }> = ({ p, t, cor = '#fff6c2', giro = 0 }) => {
  const m = mat(cor, { brilho: 1.1 });
  return (
    <group position={p} rotation={[0, 0, giro]} scale={[t, t, t]}>
      {/* quadrado girado 45° e depois achatado = losango */}
      <group scale={[0.22, 1, 0.1]}><mesh material={m} rotation={[0, 0, Math.PI / 4]}><boxGeometry args={[0.7, 0.7, 0.7]} /></mesh></group>
      <group scale={[1, 0.22, 0.1]}><mesh material={m} rotation={[0, 0, Math.PI / 4]}><boxGeometry args={[0.7, 0.7, 0.7]} /></mesh></group>
    </group>
  );
};
