// Dois semicírculos no mesmo plano e com o mesmo centro.
import React from 'react';
import { mat } from './base';

const CORES = ['#ef5350', '#ff9346', '#ffd34c', '#62ba6a', '#4d9de0', '#6264c9', '#9d66cc'];
const RAIOS = [1.42, 0.74];

export const ArcoIrisDuplo: React.FC = () => (
  <group>
    {/* Faixas de 8 cm; vão de 12 cm entre conjuntos e abertura central de 44 cm. */}
    {RAIOS.map((raio) => CORES.map((cor, i) => (
      <group key={`${raio}-${cor}`} scale={[1, 1, 0.55]}>
        <mesh material={mat(cor)} castShadow receiveShadow>
          <torusGeometry args={[raio - i * 0.08, 0.04, 16, 96, Math.PI]} />
        </mesh>
        {/* Tampas planas na mesma linha de base. */}
        {[-1, 1].map((lado) => (
          <mesh key={lado} position={[lado * (raio - i * 0.08), 0.001, 0]} material={mat(cor)} castShadow receiveShadow>
            <cylinderGeometry args={[0.04, 0.04, 0.002, 24]} />
          </mesh>
        ))}
      </group>
    )))}
  </group>
);
