// Cenário: ponto de ônibus numa esquina, de dia. Medidas em metros, Y para cima, chão (calçada) em y = 0.
// Os personagens ficam numa calçada larga, de frente para a câmera. Atrás, à esquerda, fica o abrigo (teto e
// banco cinza-claros), deslocado para o banco não sumir atrás deles. À direita fica o poste com a placa, recuado
// do meio-fio. A calçada termina num meio-fio contínuo, e a rua transversal de asfalto escuro segue para o fundo
// (com o ônibus chegando). Ao fundo há uma fileira de prédios baixos coloridos, com lojas no térreo.
import React from 'react';
import type { LimitesCenario } from '../tipos';
import { Caixa, Cilindro, Copa, Digito, Haste, PlanoFoco, mat, vidro, type V3 } from './base';

const C = {
  calcada: '#d6d3cb', calcada2: '#c8c5bc', meioFio: '#f1eee6', tatil: '#f2c94c', asfalto: '#3f444c', faixa: '#f2c94c',
  teto: '#dfe2e5', tetoBorda: '#8d949c', pilar: '#5b636d', banco: '#e6e8ea', bancoPe: '#8d949c', vidro: '#cfe8f5',
  placa: '#2f6fb0', branco: '#f8f5ef', amarelo: '#f2c94c', escuro: '#2b2f36', vidroLoja: '#3f6f9e',
  tronco: '#6b4a2f', folha: '#4f9a52', folha2: '#5fae5a', terra: '#8a6a4a',
};

const XM = 3.3; // borda da calçada (meio-fio) do lado da rua transversal
const ZM = 3.2; // borda da calçada do lado da frente
const Y_RUA = -0.15; // a rua fica 15 cm abaixo da calçada
const XR1 = 10.6; // fim da rua transversal (começo da calçada de lá)

export const LIMITES_PONTO: LimitesCenario = { limiteX: 1.5, limiteZ: [-1.0, 3.0], ceu: '#a9d8f0' };

/** Chão: calçada em placas de 1,5 m, piso tátil amarelo contínuo, meio-fio claro e ruas de asfalto escuro. */
const Chao: React.FC = () => {
  const placas: V3[] = [];
  for (let i = 0; i < 13; i++) for (let j = 0; j < 6; j++) if ((i + j) % 2 === 0) placas.push([XM - 0.25 - 0.75 - i * 1.5, -0.01, ZM - 0.25 - 0.75 - j * 1.5]);
  const zFaixa: number[] = [];
  for (let z = 2; z > -60; z -= 4) zFaixa.push(z);
  return (
    <group>
      {/* asfalto (rua da frente e transversal) */}
      <Caixa p={[0, Y_RUA - 0.06, 0]} t={[120, 0.12, 140]} cor={C.asfalto} sombra={false} />
      {/* faixa central tracejada da transversal: 20 cm × 2 m, 2 cm acima do asfalto */}
      {zFaixa.map((z) => <Caixa key={z} p={[(XM + 0.25 + XR1) / 2, Y_RUA + 0.01, z]} t={[0.2, 0.02, 2]} cor={C.faixa} sombra={false} />)}
      {/* calçada de cá: um L grande (frente larga + faixa ao longo da transversal) */}
      <Caixa p={[(XM - 0.25 - 30) / 2, -0.08, (ZM - 0.25 - 5.0) / 2]} t={[XM - 0.25 + 30, 0.16, ZM - 0.25 + 5.0]} cor={C.calcada} sombra={false} />
      <Caixa p={[(XM - 0.25 + 1.0) / 2, -0.08, (-5.0 - 60) / 2]} t={[XM - 0.25 - 1.0, 0.16, 60 - 5.0]} cor={C.calcada} sombra={false} />
      {placas.map((p, i) => <Caixa key={i} p={p} t={[1.5, 0.02, 1.5]} cor={C.calcada2} sombra={false} />)}
      {/* piso tátil: faixa amarela contínua de 40 cm, 2 cm acima, a 25 cm do meio-fio */}
      <Caixa p={[XM - 0.25 - 0.45, 0.01, (ZM - 0.7 - 60) / 2]} t={[0.4, 0.02, ZM - 0.7 + 60]} cor={C.tatil} sombra={false} />
      {/* meio-fio contínuo: 25 cm de largura, 3 cm acima da calçada, face à mostra até o asfalto */}
      <Caixa p={[XM - 0.125, -0.06, (ZM - 60) / 2]} t={[0.25, 0.24, ZM + 60]} cor={C.meioFio} />
      <Caixa p={[(XM - 30) / 2, -0.06, ZM - 0.125]} t={[XM + 30, 0.24, 0.25]} cor={C.meioFio} />
      {/* calçada de lá */}
      <Caixa p={[XR1 + 0.125, -0.06, -20]} t={[0.25, 0.24, 100]} cor={C.meioFio} />
      <Caixa p={[XR1 + 3, -0.08, -20]} t={[4.8, 0.16, 100]} cor={C.calcada} sombra={false} />
    </group>
  );
};

type Predio = { x0: number; x1: number; zf: number; alt: number; cor: string; detalhe: string; toldo: string };
// fileira do fundo (fachadas para +Z): térreo de loja; os mais altos ganham um andar de janelas
const FILEIRA: Predio[] = [
  { x0: -15.5, x1: -10.2, zf: -4.4, alt: 5.8, cor: '#e9a3c4', detalhe: '#a85a7c', toldo: '#2fa36b' },
  { x0: -10.2, x1: -5.8, zf: -4.7, alt: 3.7, cor: '#7cc5d9', detalhe: '#f8f5ef', toldo: '#e8664a' },
  { x0: -5.8, x1: -1.6, zf: -4.4, alt: 3.5, cor: '#e07a5f', detalhe: '#f8f5ef', toldo: '#f2c94c' },
  { x0: -1.6, x1: 1.0, zf: -4.4, alt: 6.0, cor: '#f2c14e', detalhe: '#c0603e', toldo: '#3a86c8' },
];

/** Prédio baixo com loja no térreo: porta, vitrine, toldo inclinado, platibanda e (se alto) janelas em cima. */
const PredioLoja: React.FC<{ p: Predio }> = ({ p }) => {
  const { x0, x1, zf, alt, cor, detalhe, toldo } = p;
  const xc = (x0 + x1) / 2, w = x1 - x0, prof = 8;
  const xPorta = x0 + 0.9, xVit = (x0 + 1.6 + x1 - 0.3) / 2, wVit = x1 - 0.3 - (x0 + 1.6);
  return (
    <group>
      <Caixa p={[xc, alt / 2, zf - prof / 2]} t={[w, alt, prof]} cor={cor} />
      {/* platibanda com faixa de cor */}
      <Caixa p={[xc, alt + 0.06, zf - 0.1]} t={[w, 0.12, 0.3]} cor={detalhe} />
      {/* porta e vitrine (molduras brancas, vidro 3 cm à frente) */}
      <Caixa p={[xPorta, 1.1, zf + 0.02]} t={[1.0, 2.2, 0.04]} cor={C.branco} sombra={false} />
      <Caixa p={[xPorta, 1.05, zf + 0.05]} t={[0.8, 2.1, 0.04]} cor={C.escuro} sombra={false} />
      <Caixa p={[xVit, 1.35, zf + 0.02]} t={[wVit, 1.7, 0.04]} cor={C.branco} sombra={false} />
      <Caixa p={[xVit, 1.4, zf + 0.05]} t={[wVit - 0.2, 1.4, 0.04]} cor={C.vidroLoja} sombra={false} />
      <Caixa p={[xVit, 0.3, zf + 0.06]} t={[wVit, 0.6, 0.12]} cor={detalhe} />
      {/* toldo inclinado com barra branca na ponta */}
      <Caixa p={[xc, 2.6, zf + 0.45]} t={[w - 0.2, 0.1, 1.0]} cor={toldo} r={[0.35, 0, 0]} />
      <Caixa p={[xc, 2.38, zf + 0.93]} t={[w - 0.2, 0.18, 0.08]} cor={C.branco} />
      {/* letreiro da loja: faixa de cor acima do toldo */}
      <Caixa p={[xc, 3.05, zf + 0.04]} t={[w - 0.8, 0.4, 0.08]} cor={detalhe} />
      {alt > 4.5 && [x0 + w * 0.27, x0 + w * 0.73].map((x) => (
        <group key={x}>
          <Caixa p={[x, 4.5, zf + 0.02]} t={[1.1, 1.2, 0.04]} cor={C.branco} sombra={false} />
          <Caixa p={[x, 4.5, zf + 0.05]} t={[0.9, 1.0, 0.04]} cor={C.vidroLoja} sombra={false} />
          <Caixa p={[x, 3.9, zf + 0.06]} t={[1.2, 0.1, 0.12]} cor={C.branco} />
        </group>
      ))}
    </group>
  );
};

/** Bloco simples (prédios ao longo da transversal): caixa colorida, cornija e janelas na face virada para a rua
 *  (face ±1 em X); `frente` também põe janelas na face +Z (o bloco que fecha o fim da rua). */
const Bloco: React.FC<{ x: number; z0: number; z1: number; larg: number; alt: number; cor: string; face: 1 | -1 | 0; frente?: boolean }> = ({ x, z0, z1, larg, alt, cor, face, frente = false }) => {
  const zc = (z0 + z1) / 2, xf = x + (face * larg) / 2;
  const jan: [number, number][] = [];
  if (face) for (let y = 1.6; y < alt - 0.8; y += 1.8) for (let z = z0 + 1.2; z < z1 - 0.8; z += 2.0) jan.push([y, z]);
  const janF: [number, number][] = [];
  if (frente) for (let y = 1.6; y < alt - 0.8; y += 2.0) for (let xx = x - larg / 2 + 1.5; xx < x + larg / 2 - 0.8; xx += 2.6) janF.push([y, xx]);
  return (
    <group>
      <Caixa p={[x, alt / 2, zc]} t={[larg, alt, z1 - z0]} cor={cor} />
      <Caixa p={[x, alt + 0.08, zc]} t={[larg + 0.2, 0.16, z1 - z0 + 0.2]} cor={C.branco} />
      {jan.map(([y, z]) => (
        <group key={`${y}${z}`}>
          <Caixa p={[xf + face * 0.02, y, z]} t={[0.04, 1.1, 1.0]} cor={C.branco} sombra={false} />
          <Caixa p={[xf + face * 0.05, y, z]} t={[0.04, 0.9, 0.8]} cor={C.vidroLoja} sombra={false} />
        </group>
      ))}
      {janF.map(([y, xx]) => (
        <group key={`f${y}${xx}`}>
          <Caixa p={[xx, y, z1 + 0.02]} t={[1.0, 1.1, 0.04]} cor={C.branco} sombra={false} />
          <Caixa p={[xx, y, z1 + 0.05]} t={[0.8, 0.9, 0.04]} cor={C.vidroLoja} sombra={false} />
        </group>
      ))}
    </group>
  );
};

/** Abrigo do ponto: teto cinza-claro com testeira, dois pilares atrás, painel de vidro, banco e painel de anúncio. */
const Abrigo: React.FC<{ x: number; z: number }> = ({ x, z }) => {
  const w = 3.3, hT = 2.55, zt = z - 0.05; // z = linha dos pilares (fundo)
  return (
    <group position={[x, 0, 0]}>
      {/* teto: placa grossa, levemente inclinada para trás, com testeira escura na frente */}
      <Caixa p={[0, hT, zt + 0.7]} t={[w + 0.3, 0.14, 1.7]} cor={C.teto} r={[-0.04, 0, 0]} />
      <Caixa p={[0, hT - 0.01, zt + 1.56]} t={[w + 0.3, 0.24, 0.1]} cor={C.tetoBorda} />
      {/* pilares (12 cm) e travessa */}
      {[-1, 1].map((s) => <Caixa key={s} p={[s * (w / 2 - 0.1), hT / 2, z]} t={[0.12, hT, 0.12]} cor={C.pilar} />)}
      <Caixa p={[0, 2.3, z]} t={[w - 0.2, 0.12, 0.12]} cor={C.pilar} />
      {/* painel de vidro no fundo (2 cm atrás dos pilares) e faixa de quadro embaixo */}
      <mesh position={[0, 1.35, z - 0.09]} material={vidro(C.vidro, 0.35)}><boxGeometry args={[w - 0.3, 1.7, 0.03]} /></mesh>
      <Caixa p={[0, 0.42, z - 0.09]} t={[w - 0.3, 0.16, 0.06]} cor={C.pilar} />
      {/* banco cinza-claro: assento grosso, encosto e dois pés */}
      <Caixa p={[0, 0.46, z + 0.3]} t={[2.4, 0.1, 0.44]} cor={C.banco} />
      <Caixa p={[0, 0.82, z + 0.1]} t={[2.4, 0.26, 0.08]} cor={C.banco} r={[-0.1, 0, 0]} />
      {[-0.95, 0.95].map((dx) => <Caixa key={dx} p={[dx, 0.21, z + 0.3]} t={[0.12, 0.42, 0.34]} cor={C.bancoPe} />)}
      {/* painel de anúncio iluminado na lateral esquerda */}
      <Caixa p={[-w / 2 + 0.02, 1.3, zt + 0.7]} t={[0.14, 2.0, 1.26]} cor={C.pilar} />
      <Caixa p={[-w / 2 + 0.11, 1.3, zt + 0.7]} t={[0.04, 1.8, 1.08]} cor="#fff6dc" m={mat('#fff6dc', { brilho: 0.35 })} />
      <Caixa p={[-w / 2 + 0.15, 1.6, zt + 0.7]} t={[0.04, 0.5, 0.8]} cor="#e8664a" sombra={false} />
      <Caixa p={[-w / 2 + 0.15, 0.95, zt + 0.55]} t={[0.04, 0.12, 0.6]} cor="#3a86c8" sombra={false} />
      <Caixa p={[-w / 2 + 0.15, 0.75, zt + 0.6]} t={[0.04, 0.12, 0.7]} cor="#3a86c8" sombra={false} />
      {/* faixa no topo da testeira com o ícone do ônibus */}
      <Caixa p={[0, hT + 0.24, zt + 1.5]} t={[0.9, 0.34, 0.1]} cor={C.placa} />
      <IconeOnibus p={[0, hT + 0.24, zt + 1.56]} e={0.5} />
    </group>
  );
};

/** Ícone de ônibus visto de frente (caixas), no plano XY. `e` = escala (1 → 40 cm de altura). */
const IconeOnibus: React.FC<{ p: V3; e: number }> = ({ p, e }) => (
  <group position={p} scale={[e, e, 1]}>
    <Caixa p={[0, 0.02, 0]} t={[0.32, 0.32, 0.01]} cor={C.branco} sombra={false} />
    <Caixa p={[0, 0.07, 0.008]} t={[0.24, 0.12, 0.01]} cor={C.placa} sombra={false} />
    <Caixa p={[-0.09, -0.07, 0.008]} t={[0.06, 0.05, 0.01]} cor={C.placa} sombra={false} />
    <Caixa p={[0.09, -0.07, 0.008]} t={[0.06, 0.05, 0.01]} cor={C.placa} sombra={false} />
    <Caixa p={[-0.1, -0.18, 0]} t={[0.07, 0.08, 0.01]} cor={C.branco} sombra={false} />
    <Caixa p={[0.1, -0.18, 0]} t={[0.07, 0.08, 0.01]} cor={C.branco} sombra={false} />
  </group>
);

/** Poste da parada: tubo de 10 cm, placa azul com o ônibus e, embaixo, a placa amarela com a linha "207". */
const PostePlaca: React.FC<{ x: number; z: number }> = ({ x, z }) => (
  <group position={[x, 0, z]}>
    <Cilindro p={[0, 0, 0]} r={0.05} h={2.75} cor={C.pilar} seg={12} />
    <Cilindro p={[0, 0, 0]} r={0.1} h={0.08} cor={C.pilar} seg={12} />
    <Caixa p={[0, 2.42, 0.07]} t={[0.5, 0.5, 0.04]} cor={C.placa} />
    <Caixa p={[0, 2.42, 0.095]} t={[0.44, 0.44, 0.01]} cor={C.branco} sombra={false} />
    <Caixa p={[0, 2.42, 0.105]} t={[0.4, 0.4, 0.01]} cor={C.placa} sombra={false} />
    <IconeOnibus p={[0, 2.43, 0.115]} e={0.95} />
    <Caixa p={[0, 1.98, 0.07]} t={[0.5, 0.26, 0.04]} cor={C.amarelo} />
    {['2', '0', '7'].map((d, i) => <Digito key={i} d={d} p={[(i - 1) * 0.13, 1.98, 0.095]} alt={0.17} larg={0.09} traco={0.03} cor={C.escuro} />)}
  </group>
);

/** Ônibus de brinquedo vindo pela transversal, de frente para a câmera (+Z). Frente em z. */
const Onibus: React.FC<{ x: number; z: number }> = ({ x, z }) => {
  const c = 10, w = 2.5;
  return (
    <group position={[x, Y_RUA, z - c / 2]}>
      <Caixa p={[0, 1.15, 0]} t={[w, 1.6, c]} cor="#2f78b8" />
      <Caixa p={[0, 2.35, 0]} t={[w, 0.8, c]} cor={C.branco} />
      <Caixa p={[0, 2.85, 0]} t={[w - 0.1, 0.2, c - 0.2]} cor="#dfe2e5" />
      {/* frente: para-brisa, letreiro com a linha, faróis e para-choque */}
      <Caixa p={[0, 2.0, c / 2 + 0.02]} t={[w - 0.3, 1.2, 0.04]} cor="#1f3f5f" sombra={false} />
      <Caixa p={[0, 2.75, c / 2 + 0.02]} t={[w - 0.6, 0.3, 0.04]} cor={C.escuro} sombra={false} />
      {['2', '0', '7'].map((d, i) => <Digito key={i} d={d} p={[(i - 1) * 0.24, 2.75, c / 2 + 0.05]} alt={0.22} larg={0.14} traco={0.05} cor="#f2a23a" />)}
      {[-1, 1].map((s) => <Caixa key={s} p={[s * 0.9, 0.85, c / 2 + 0.03]} t={[0.3, 0.16, 0.06]} cor="#fff6d8" sombra={false} />)}
      <Caixa p={[0, 0.45, c / 2 + 0.06]} t={[w, 0.24, 0.12]} cor="#5b636d" />
      {/* janelas laterais (lado -X, visível da calçada) */}
      {[-3.6, -1.6, 0.4, 2.4].map((dz) => <Caixa key={dz} p={[-w / 2 - 0.02, 2.0, dz]} t={[0.04, 0.8, 1.6]} cor="#1f3f5f" sombra={false} />)}
      {[[-1, 3.2], [1, 3.2], [-1, -3.0], [1, -3.0]].map(([s, dz]) => (
        <mesh key={`${s}${dz}`} position={[s * (w / 2 - 0.15), 0.45, dz]} rotation={[0, 0, Math.PI / 2]} material={mat('#2b2d33')} castShadow receiveShadow>
          <cylinderGeometry args={[0.45, 0.45, 0.32, 18]} />
        </mesh>
      ))}
    </group>
  );
};

/** Árvore de calçada num quadrado de terra. */
const Arvore: React.FC<{ p: V3; e?: number }> = ({ p, e = 1 }) => (
  <group position={p} scale={e}>
    <Caixa p={[0, 0.0, 0]} t={[1.0, 0.04, 1.0]} cor={C.terra} sombra={false} />
    <Haste a={[0, 0, 0]} b={[0, 1.9, 0]} r={0.12} cor={C.tronco} />
    <mesh position={[0, 2.5, 0]} material={mat(C.folha, { flat: true })} castShadow receiveShadow><icosahedronGeometry args={[0.85, 0]} /></mesh>
    <mesh position={[0.4, 2.1, 0.3]} material={mat(C.folha2, { flat: true })} castShadow receiveShadow><icosahedronGeometry args={[0.5, 0]} /></mesh>
  </group>
);

export const PontoDeOnibus: React.FC = () => (
  <group>
    <PlanoFoco z={-1.0} />
    <Chao />
    {FILEIRA.map((p, i) => <PredioLoja key={i} p={p} />)}
    {/* ao longo da transversal: deste lado e do outro; no fim, um bloco fecha o horizonte */}
    <Bloco x={-1.3} z0={-20} z1={-12.4} larg={4.6} alt={4.6} cor="#c4b0e8" face={1} />
    <Bloco x={-1.3} z0={-30} z1={-20} larg={4.6} alt={6.8} cor="#f28c6b" face={1} />
    <Bloco x={16} z0={-16} z1={-6} larg={4.6} alt={5.2} cor="#7cc5d9" face={-1} />
    <Bloco x={16} z0={-27} z1={-16} larg={4.6} alt={7.4} cor="#f5d06a" face={-1} />
    <Bloco x={7} z0={-44} z1={-36} larg={22} alt={8} cor="#e9b98f" face={0} frente />
    <Abrigo x={-2.55} z={-3.0} />
    <PostePlaca x={2.0} z={-1.3} />
    {/* lixeira afastada do abrigo, inteira na calçada */}
    <Cilindro p={[1.95, 0, -3.1]} r={0.2} r2={0.17} h={0.62} cor="#3f9a5c" />
    <Cilindro p={[1.95, 0.62, -3.1]} r={0.22} h={0.06} cor="#2f7a48" />
    <Arvore p={[1.65, 0, -8]} />
    <Arvore p={[XR1 + 1.5, 0, -4]} e={1.1} />
    <Onibus x={5.4} z={-24} />
    {/* arbustos no pé dos prédios de lá */}
    {[-3, -9.5, -20].map((z, i) => <Copa key={z} p={[XR1 + 3.2, 0.4, z]} r={0.55} s={[1, 0.8, 1.4]} cor={i % 2 ? C.folha : C.folha2} />)}
  </group>
);
