// Folha de parede de 40 x 50 cm. A argola superior serve para pendurar.
import React from 'react';
import { mat, numero, Papel, type Retangulo } from './base';

const C = { papel: '#fffdf5', borda: '#ded9cc', tinta: '#20313c', celula: '#e8ede8', vermelho: '#d43b36' };
const dias = Array.from({ length: 31 }, (_, i) => ({
  valor: i + 1, x: -0.156 + (i % 7) * 0.052, y: 0.325 - Math.floor(i / 7) * 0.062,
}));
const tintas: Retangulo[] = [
  { x: 0, y: 0.422, l: 0.364, a: 0.086, cor: C.vermelho },
  // Mês 07 de 2026: 31 dias, sem letras simuladas por rabiscos.
  ...numero('07', -0.105, 0.422, 0.046, 0.0055, C.papel),
  ...numero('2026', 0.064, 0.422, 0.034, 0.004, C.papel),
  // Quadros chapados separados pelo próprio papel, sem linhas finas.
  ...Array.from({ length: 35 }, (_, i) => ({
    x: -0.156 + (i % 7) * 0.052, y: 0.325 - Math.floor(i / 7) * 0.062,
    l: 0.047, a: 0.056, cor: C.celula,
  })),
  ...dias.flatMap(({ valor, x, y }) => numero(String(valor), x, y,
    valor === 25 ? 0.028 : 0.034, valor === 25 ? 0.0034 : 0.0038, valor === 25 ? C.vermelho : C.tinta)),
];
const dia25 = dias[24];

export const Calendario: React.FC = () => (
  <group>
    <Papel l={0.40} a={0.50} e={0.009} cor={C.papel} borda={C.borda} tintas={tintas} />
    <mesh position={[0, 0.478, 0]} rotation={[0, Math.PI / 2, 0]} material={mat(C.tinta)} castShadow>
      <torusGeometry args={[0.013, 0.004, 8, 24]} />
    </mesh>
    {/* Marca apartada da face, sem projetar sombra na grade. */}
    <mesh position={[dia25.x, dia25.y, 0.029]} scale={[1.12, 1.08, 1]}
      material={mat(C.vermelho)} castShadow={false} receiveShadow={false}>
      <torusGeometry args={[0.024, 0.003, 8, 40]} />
    </mesh>
  </group>
);
