// Objeto: pacote de figurinhas (8 x 12 cm, envelope fino), azul chapado com estrelas amarelas em grade regular,
// rasgado no topo em zigue-zague, com duas figurinhas aparecendo pela boca. Deitado (frente para cima, topo para -Z),
// levemente girado. Origem no centro da base. Modelado no plano XY (frente +Z) e depois deitado.
import React from 'react';
import { Caixa, mat, type V3 } from './base';

const C = { azul: '#2a5cf0', estrela: '#ffd23f', dentro: '#d3dae6', carta: '#fbfaf5', carta1: '#3fbf6b', carta2: '#ff5a5f' };

const W = 0.08;
const BASE = -0.06;          // pé do envelope (12 cm até o alto do verso)
const ESP = 0.0018;          // espessura do envelope (frente + verso + figurinhas)
const TOPO_FRENTE = 0.05;    // onde o rasgo da frente começa
const TOPO_FUNDO = 0.058;    // o verso sobe mais (dá para ver o lado de dentro)
const DENTE = 0.008;         // passo do zigue-zague

/** Estrela de 5 pontas chapada, de frente para +Z: 5 losangos planos (sem laterais, nada de emenda) num só plano,
 *  com um pentágono fino logo abaixo tapando o miolo; sem sombra. */
const Estrela: React.FC<{ p: V3; R: number; giro?: number }> = ({ p, R, giro = 0 }) => {
  const ri = R * 0.42, yc = ri * 0.81, hh = R - yc, hw = ri * 0.588, m = mat(C.estrela);
  return (
    <group position={p} rotation={[0, 0, giro]}>
      <mesh position={[0, 0, -0.00025]} rotation={[Math.PI / 2, 0, 0]} material={m}><cylinderGeometry args={[ri * 1.03, ri * 1.03, 0.0003, 5]} /></mesh>
      {[0, 1, 2, 3, 4].map((k) => (
        <group key={k} rotation={[0, 0, (k * 2 * Math.PI) / 5]}>
          <group position={[0, yc, 0]} scale={[hw / 0.7071, hh / 0.7071, 1]}>
            <mesh rotation={[0, 0, Math.PI / 4]} material={m}><planeGeometry args={[1, 1]} /></mesh>
          </group>
        </group>
      ))}
    </group>
  );
};

/** Zigue-zague regular ao longo de X: quadrados a 45° com meia diagonal = meio passo (não passam das laterais). */
const Dentes: React.FC<{ y: number; z: number; d: number; cor: string }> = ({ y, z, d, cor }) => {
  const n = Math.round(W / DENTE), s = DENTE / Math.SQRT2;
  return (
    <>
      {Array.from({ length: n }, (_, i) => (
        <mesh key={i} position={[-W / 2 + DENTE * (i + 0.5), y, z]} rotation={[0, 0, Math.PI / 4]} material={mat(cor)} castShadow receiveShadow>
          <boxGeometry args={[s, s, d]} />
        </mesh>
      ))}
    </>
  );
};

// estampa: 5 fileiras alternando 3 e 2 estrelas, passo regular
const ESTRELAS: [number, number][] = [];
[0.032, 0.013, -0.006, -0.025, -0.044].forEach((y, linha) => {
  (linha % 2 === 0 ? [-0.024, 0, 0.024] : [-0.012, 0.012]).forEach((x) => ESTRELAS.push([x, y]));
});

export const PacoteFigurinhas: React.FC = () => {
  const frente = ESP * 0.6, verso = ESP * 0.3; // espessuras das duas camadas
  const hCorpo = TOPO_FRENTE - BASE;
  return (
    <group rotation={[0, 0.28, 0]}>
      <group rotation={[-Math.PI / 2, 0, 0]}>
        {/* verso: sobe acima da frente e mostra o lado de dentro (prateado) com o seu zigue-zague */}
        <Caixa p={[0, (BASE + TOPO_FUNDO) / 2, verso / 2]} t={[W, TOPO_FUNDO - BASE, verso]} cor={C.dentro} />
        <Dentes y={TOPO_FUNDO} z={verso / 2} d={verso} cor={C.dentro} />

        {/* figurinhas saindo pela boca (entre o verso e a frente) */}
        <group position={[-0.009, TOPO_FRENTE + 0.004, verso + 0.0002]} rotation={[0, 0, 0.12]}>
          <Caixa p={[0, 0, 0]} t={[0.05, 0.03, 0.0003]} cor={C.carta} sombra={false} />
          <Caixa p={[0, 0.002, 0.0002]} t={[0.042, 0.022, 0.0003]} cor={C.carta1} sombra={false} />
        </group>
        <group position={[0.01, TOPO_FRENTE + 0.001, verso + 0.0007]} rotation={[0, 0, -0.08]}>
          <Caixa p={[0, 0, 0]} t={[0.05, 0.03, 0.0003]} cor={C.carta} sombra={false} />
          <Caixa p={[0, 0.002, 0.0002]} t={[0.042, 0.022, 0.0003]} cor={C.carta2} sombra={false} />
        </group>

        {/* frente azul chapada com o rasgo em zigue-zague */}
        <Caixa p={[0, (BASE + TOPO_FRENTE) / 2, ESP - frente / 2]} t={[W, hCorpo, frente]} cor={C.azul} />
        <Dentes y={TOPO_FRENTE} z={ESP - frente / 2} d={frente} cor={C.azul} />

        {/* estrelas amarelas planas, 0,3 mm acima da frente */}
        {ESTRELAS.map(([x, y], i) => <Estrela key={i} p={[x, y, ESP + 0.0003]} R={0.0068} giro={(i % 2) * 0.32} />)}
      </group>
    </group>
  );
};
