// Demonstrações das ações COM os adereços. O contrato `acao` só leva juntas, então a vitrine mostra o Téo
// de mãos vazias e sorrindo; estas peças (tipo 'efeito') põem ao lado dele um coadjuvante (c1, sem boné)
// fazendo a mesma ação, com as mesmas juntas, os objetos na mão e o rosto da ação.
import React from 'react';
import { Boneco, type Expressao } from '../../../kit/Boneco';
import { ELENCO } from '../../../kit/elenco';
import { juntasNoQuadro } from './acoes';
import { ObjetosDaAcao } from './objetos';
import type { PecaOficina } from '../tipos';

type V3 = [number, number, number];
const V = ELENCO.c1;
// rosto e lugar de cada demo; o abrirPacote fica mais perto da câmera para as mãos aparecerem grandes
const DEMO: Record<string, { e: Expressao; pos: V3; giro: number }> = {
  quicarBola: { e: { boca: 'sorriso', olharY: -1, olharX: 0.6 }, pos: [0.95, 0, 0], giro: -14 },
  sortear: { e: { boca: 'aberta', olharY: 0.6, olharX: 0.8, sobrancelha: 0.7 }, pos: [1.0, 0, 0.35], giro: -12 },
  abrirPacote: { e: { boca: 'aberta', olharY: -1, sobrancelha: -1, piscar: 0.35 }, pos: [0.85, 0, 0.95], giro: -16 },
};

const Demo = (nome: string): React.FC<{ quadro: number }> => ({ quadro }) => {
  const d = DEMO[nome];
  return (
    <group position={d.pos} rotation={[0, (d.giro * Math.PI) / 180, 0]}>
      <Boneco v={V} j={juntasNoQuadro(nome, quadro)} e={d.e} />
      <ObjetosDaAcao nome={nome} quadro={quadro} pele={V.pele} />
    </group>
  );
};

export const DEMOS: PecaOficina[] = Object.keys(DEMO).map((nome) => ({
  tipo: 'efeito' as const, nome: `${nome}+objetos`, Componente: Demo(nome),
}));
