import React from 'react';
import { useCurrentFrame } from 'remotion';
import { Caixa, Esfera, mat } from './base';

const C = {
  branco: '#f4f0e6', teto: '#e1e4de', vermelho: '#d53f3e',
  borracha: '#202832', vidro: '#72b7d7', vidroEscuro: '#36799e',
  passageiro: '#213e56', passageiroClaro: '#325971', pneu: '#1b2028',
  cubo: '#8f9aa4', farol: '#fff1bc', pisca: '#ef9d35',
};

// Silhuetas em relevo no vidro opaco: leitura estável, sem transparência.
const Janela: React.FC<{ lado: number; z: number; indice: number }> = ({ lado, z, indice }) => (
  <group position={[0, 0, z]}>
    <Caixa p={[lado * 1.28, 2.15, 0]} t={[0.12, 1.26, 1.4]} cor={C.borracha} />
    <Caixa p={[lado * 1.4, 2.15, 0]} t={[0.08, 1.06, 1.2]} cor={C.vidro} />
    {[-1, 0, 1].map((i) => {
      const y = 2.35 + ((indice + i + 3) % 3) * 0.055;
      const cor = (indice + i) % 2 === 0 ? C.passageiro : C.passageiroClaro;
      return (
        <group key={i}>
          <Caixa p={[lado * 1.5, y - 0.3, i * 0.37]} t={[0.08, 0.4, 0.35]} cor={cor} sombra={false} />
          <Esfera p={[lado * 1.51, y, i * 0.37]} t={[0.045, 0.13, 0.125]} cor={cor} />
        </group>
      );
    })}
  </group>
);

const Roda: React.FC<{ lado: number; z: number; angulo: number }> = ({ lado, z, angulo }) => (
  <group position={[lado * 1.22, 0.55, z]} rotation={[angulo, 0, 0]}>
    <mesh rotation={[0, 0, Math.PI / 2]} material={mat(C.pneu)} castShadow receiveShadow>
      <cylinderGeometry args={[0.55, 0.55, 0.34, 24]} />
    </mesh>
    <mesh position={[lado * 0.23, 0, 0]} rotation={[0, 0, Math.PI / 2]} material={mat(C.cubo)} castShadow receiveShadow>
      <cylinderGeometry args={[0.27, 0.27, 0.08, 16]} />
    </mesh>
    {[0, Math.PI / 2].map((r) => (
      <Caixa key={r} p={[lado * 0.32, 0, 0]} t={[0.08, 0.36, 0.08]} r={[r, 0, 0]} cor={C.borracha} sombra={false} />
    ))}
  </group>
);

const Portas: React.FC = () => (
  <group>
    <Caixa p={[1.3, 1.68, 4.65]} t={[0.12, 2.18, 1.6]} cor={C.borracha} />
    {[4.25, 5.05].map((z) => (
      <group key={z}>
        <Caixa p={[1.42, 1.68, z]} t={[0.08, 1.96, 0.66]} cor={C.branco} />
        <Caixa p={[1.52, 2.05, z]} t={[0.08, 1.02, 0.46]} cor={C.vidroEscuro} />
        <Caixa p={[1.52, 1.09, z]} t={[0.08, 0.42, 0.46]} cor={C.vidroEscuro} />
        <Caixa p={[1.62, 1.45, z - 0.18]} t={[0.08, 0.23, 0.08]} cor={C.borracha} />
      </group>
    ))}
    <Caixa p={[1.42, 0.58, 4.65]} t={[0.36, 0.12, 1.65]} cor={C.cubo} />
  </group>
);

// Veículo em escala real: 11,6 m de carroceria, 2,5 m de largura, 3,1 m de altura.
// Origem no centro da base; frente para +Z. Retrovisores e pneus alargam a silhueta.
export const OnibusModelo: React.FC<{ giroRodas?: number }> = ({ giroRodas = 0 }) => (
  <group>
    <Caixa p={[0, 0.69, 0]} t={[2.1, 0.22, 10.9]} cor={C.borracha} />
    <Caixa p={[0, 1.36, 0]} t={[2.5, 0.68, 11.6]} cor={C.branco} />
    {/* Saia em trechos: vãos reais sobre os dois eixos. */}
    {([[-5.1, 1.4], [-0.2, 6.2], [4.9, 1.8]] as const).map(([z, comprimento]) => (
      <Caixa key={z} p={[0, 0.83, z]} t={[2.5, 0.38, comprimento]} cor={C.branco} />
    ))}
    <Caixa p={[0, 2.18, 0]} t={[2.46, 1.28, 11.52]} cor={C.branco} />
    <Caixa p={[0, 2.95, 0]} t={[2.54, 0.3, 11.64]} cor={C.teto} />
    {([-1, 1] as const).map((lado) => (
      <group key={lado}>
        <Caixa p={[lado * 1.31, 1.36, 0]} t={[0.08, 0.26, 11.6]} cor={C.vermelho} />
        <Caixa p={[lado * 1.31, 0.63, 0]} t={[0.08, 0.12, 5.6]} cor={C.borracha} />
        {[-4.75, -3.25, -1.75, -0.25, 1.25, 2.75].map((z, indice) => <Janela key={z} lado={lado} z={z} indice={indice} />)}
        {lado === -1 && <Janela lado={lado} z={4.25} indice={6} />}
        {[-3.85, 3.45].map((z) => <Roda key={z} lado={lado} z={z} angulo={giroRodas} />)}
        {/* Retrovisor robusto, sem hastes finas no plano aberto. */}
        <Caixa p={[lado * 1.48, 2.54, 5.25]} t={[0.4, 0.1, 0.12]} cor={C.borracha} />
        <Caixa p={[lado * 1.68, 2.38, 5.25]} t={[0.16, 0.38, 0.23]} cor={C.borracha} />
        <Caixa p={[lado * 1.68, 2.38, 5.445]} t={[0.12, 0.28, 0.08]} cor={C.cubo} />
      </group>
    ))}
    <Portas />
    {/* Frente e traseira: cores chapadas, molduras e camadas com folga de 2 cm. */}
    {([-1, 1] as const).map((extremo) => (
      <group key={extremo}>
        <Caixa p={[0, 1.36, extremo * 5.86]} t={[2.5, 0.26, 0.08]} cor={C.vermelho} />
        <Caixa p={[0, 2.12, extremo * 5.88]} t={[2.36, 1.26, 0.12]} cor={C.borracha} />
        <Caixa p={[0, 2.12, extremo * 6]} t={[2.16, 1.06, 0.08]} cor={C.vidro} />
        <Caixa p={[0, 0.67, extremo * 5.92]} t={[2.62, 0.2, 0.16]} cor={C.borracha} />
        {[-1, 1].map((lado) => (
          <group key={lado}>
            <Caixa p={[lado * 0.86, 0.98, extremo * 5.91]} t={[0.36, 0.2, 0.1]} cor={extremo === 1 ? C.farol : C.vermelho} />
            <Caixa p={[lado * 1.1, 0.98, extremo * 5.91]} t={[0.12, 0.2, 0.1]} cor={C.pisca} />
          </group>
        ))}
      </group>
    ))}
    {/* Lotação também visível pelo para-brisa. */}
    {[-0.68, 0, 0.68].map((x) => (
      <group key={x}>
        <Caixa p={[x, 1.94, 6.1]} t={[0.45, 0.42, 0.08]} cor={C.passageiro} sombra={false} />
        <Esfera p={[x, 2.31, 6.11]} t={[0.14, 0.15, 0.045]} cor={C.passageiro} />
      </group>
    ))}
    <Caixa p={[0, 2.12, 6.23]} t={[0.08, 1.1, 0.08]} cor={C.borracha} />
    {[-1, 1].map((lado) => (
      <Caixa key={lado} p={[lado * 0.54, 1.77, 6.23]} t={[0.62, 0.08, 0.08]} r={[0, 0, lado * 0.2]} cor={C.borracha} sombra={false} />
    ))}
    {/* Letreiro com rabiscos largos, sem fonte ou números ambíguos. */}
    <Caixa p={[0, 2.86, 5.91]} t={[2.2, 0.3, 0.1]} cor={C.borracha} />
    {([-0.66, 0, 0.66] as const).map((x) => <Caixa key={x} p={[x, 2.86, 6.03]} t={[0.46, 0.1, 0.1]} cor={C.farol} sombra={false} />)}
    {[-0.18, 0.04, 0.26].map((y) => <Caixa key={y} p={[0, 0.99 + y, -5.91]} t={[1.1, 0.08, 0.1]} cor={C.borracha} sombra={false} />)}
  </group>
);

// Passagem lateral a 2,4 m/s (30 fps); sem reinício ou salto na trajetória.
export const OnibusNoQuadro: React.FC<{ quadro: number }> = ({ quadro }) => {
  const percurso = (quadro - 90) * 0.08;
  return (
    <group position={[percurso, 0, -3.3]} rotation={[0, Math.PI / 2, 0]}>
      <OnibusModelo giroRodas={percurso / 0.55} />
    </group>
  );
};

export const Onibus: React.FC = () => <OnibusNoQuadro quadro={useCurrentFrame()} />;
