// Avenida com dois planos de torres e circulação fora da frente dos protagonistas.
import React from 'react';
import { useCurrentFrame } from 'remotion';
import type { LimitesCenario } from '../tipos';
import { Ambiente, Caixa, mat, type V3 } from './base';

const C = {
  piso: '#d8cdb9', faixaPiso: '#b7aa92', meioFio: '#f4e7d0', asfalto: '#788792',
  faixa: '#fff1bf', janela: '#365e79', vidro: '#96ced9', pneu: '#38424c',
};

export const LIMITES_CIDADE: LimitesCenario = { limiteX: 1.4, limiteZ: [-1, 3], ceu: '#b8e2fa' };

type PredioDados = { x: number; z: number; h: number; cor: string };
const PREDIOS: PredioDados[] = [
  { x: -18.5, z: -27, h: 12, cor: '#dba071' },
  { x: -11.1, z: -25, h: 18, cor: '#80b6af' },
  { x: -3.7, z: -26, h: 13, cor: '#a1a9d2' },
  { x: 3.7, z: -28, h: 20, cor: '#e6bb63' },
  { x: 11.1, z: -25, h: 15, cor: '#d99888' },
  { x: 18.5, z: -27, h: 17, cor: '#78b5c8' },
];
const TORRES: PredioDados[] = [
  { x: -22, z: -40, h: 23, cor: '#9fbfcb' },
  { x: -14, z: -39, h: 26, cor: '#b8c8d7' },
  { x: -6, z: -40, h: 22, cor: '#93b7c0' },
  { x: 7, z: -41, h: 27, cor: '#abc5d6' },
  { x: 17, z: -40, h: 25, cor: '#a4c6c5' },
];

const Predio: React.FC<PredioDados> = ({ x, z, h, cor }) => (
  <group position={[x, 0, z]}>
    <Caixa p={[0, h / 2, 0]} t={[6, h, 5]} cor={cor} />
    <Caixa p={[0, h + 0.14, 0]} t={[6.3, 0.28, 5.3]} cor={C.meioFio} />
    <Caixa p={[0, 2.1, 2.85]} t={[6.2, 0.3, 1]} cor={C.meioFio} />
    {[-1.5, 1.5].map((xJanela) => (
      <Caixa key={xJanela} p={[xJanela, 0.95, 2.66]} t={[2.2, 1.9, 0.2]} cor={C.vidro} sombra={false} />
    ))}
    {[0, 1, 2, 3].map((andar) => [-1.5, 1.5].map((xJanela, coluna) => (
      <Caixa key={`${andar}-${coluna}`} p={[xJanela, 3.6 + andar * (h - 5) / 3, 2.66]}
        t={[1.7, 1.7, 0.2]} cor={(andar + coluna) % 3 === 0 ? C.vidro : C.janela} sombra={false} />
    )))}
  </group>
);

type Roupa = { pele: string; cabelo: string; camisa: string; calca: string };
const ROUPAS: Roupa[] = [
  { pele: '#b97b55', cabelo: '#332721', camisa: '#df675d', calca: '#384b6a' },
  { pele: '#efc6a2', cabelo: '#674936', camisa: '#49a89c', calca: '#414a58' },
  { pele: '#85563e', cabelo: '#251f24', camisa: '#edbf56', calca: '#48596b' },
  { pele: '#d8a478', cabelo: '#51382c', camisa: '#8291ca', calca: '#4d485b' },
  { pele: '#a66d4c', cabelo: '#34272b', camisa: '#e59fba', calca: '#384c57' },
  { pele: '#f0cfaa', cabelo: '#503327', camisa: '#e4934f', calca: '#425970' },
];

const POSICOES: [number, number][] = [
  [-5.9, -1.65], [-3.1, -1.65], [3.1, -1.65], [5.9, -1.65],
  [-5.45, -3.15], [-2.15, -3.15], [2.15, -3.15], [5.45, -3.15],
  ...[-13.5, -10.5, -7.5, -4.5, -1.5, 1.5, 4.5, 7.5, 10.5, 13.5].map((x): [number, number] => [x, -11.9]),
];

const Capsula: React.FC<{ p: V3; raio: number; comp: number; cor: string }> = ({ p, raio, comp, cor }) => (
  <mesh position={p} material={mat(cor)} castShadow receiveShadow>
    <capsuleGeometry args={[raio, comp, 8, 20]} />
  </mesh>
);
const Esfera: React.FC<{ p: V3; r: number; cor: string; escala?: V3 }> = ({ p, r, cor, escala }) => (
  <mesh position={p} scale={escala} material={mat(cor)} castShadow receiveShadow>
    <sphereGeometry args={[r, 32, 20]} />
  </mesh>
);

// Cabeça, torso e espessura dos membros seguem o Boneco. Rosto simplificado ao longe.
const Pedestre: React.FC<{ indice: number; quadro: number }> = ({ indice, quadro }) => {
  const roupa = ROUPAS[indice % ROUPAS.length];
  const sentido = indice % 2 === 0 ? 1 : -1;
  const [origemX, z] = POSICOES[indice];
  // Deslocamento curto e cíclico preserva as distâncias durante a animação.
  const x = origemX + Math.sin(quadro / 90) * 0.18;
  const passo = Math.sin(quadro / 30 * 5 + indice * 1.4) * 0.3;
  return (
    <group position={[x, 0, z]} rotation={[0, sentido * 0.6, 0]}>
      <Capsula p={[0, 0.86, 0]} raio={0.19} comp={0.28} cor={roupa.camisa} />
      <Esfera p={[0, 1.5, 0]} r={0.34} cor={roupa.pele} />
      {/* Calota restrita ao alto da cabeça, com o rosto inteiro descoberto. */}
      <mesh position={[0, 1.5, 0]} material={mat(roupa.cabelo)} castShadow receiveShadow>
        <sphereGeometry args={[0.355, 32, 16, 0, Math.PI * 2, 0, 1.18]} />
      </mesh>
      {indice % 5 === 0 && <>
        <Esfera p={[-0.22, 1.83, -0.05]} r={0.12} cor={roupa.cabelo} />
        <Esfera p={[0.22, 1.83, -0.05]} r={0.12} cor={roupa.cabelo} />
      </>}
      {[-1, 1].map((lado) => (
        <group key={lado}>
          <Esfera p={[lado * 0.11, 1.54, 0.3]} r={0.075} escala={[1, 1.15, 0.6]} cor="#fffaf0" />
          <Esfera p={[lado * 0.11, 1.53, 0.35]} r={0.042} cor="#24282d" />
          <group position={[lado * 0.25, 1.06, 0]} rotation={[lado * passo, 0, lado * 0.12]}>
            <Capsula p={[0, -0.22, 0]} raio={0.062} comp={0.36} cor={roupa.camisa} />
            <Esfera p={[0, -0.47, 0]} r={0.072} cor={roupa.pele} />
          </group>
          <group position={[lado * 0.1, 0.64, 0]} rotation={[-lado * passo, 0, 0]}>
            <Capsula p={[0, -0.26, 0]} raio={0.074} comp={0.45} cor={roupa.calca} />
            <Caixa p={[0, -0.585, 0.05]} t={[0.15, 0.11, 0.27]} cor={C.meioFio} />
          </group>
        </group>
      ))}
    </group>
  );
};

const Veiculo: React.FC<{ x: number; z: number; onibus?: boolean; cor: string }> = ({ x, z, onibus = false, cor }) => {
  const comp = onibus ? 4.6 : 2.7;
  return (
    <group position={[x, -0.14, z]}>
      <Caixa p={[0, onibus ? 0.95 : 0.55, 0]} t={[comp, onibus ? 1.5 : 0.7, 1.25]} cor={cor} />
      {onibus ? [-1.55, -0.52, 0.52, 1.55].map((xx) => (
        <Caixa key={xx} p={[xx, 1.28, 0.73]} t={[0.8, 0.62, 0.16]} cor={C.janela} sombra={false} />
      )) : <>
        <Caixa p={[-0.12, 1.05, 0]} t={[1.55, 0.6, 1.12]} cor={cor} />
        <Caixa p={[-0.12, 1.12, 0.66]} t={[1.22, 0.34, 0.16]} cor={C.janela} sombra={false} />
      </>}
      {[-1, 1].map((lado) => [-1, 1].map((eixo) => (
        <mesh key={`${lado}-${eixo}`} position={[eixo * comp * 0.32, 0.28, lado * 0.64]}
          rotation={[Math.PI / 2, 0, 0]} material={mat(C.pneu)} castShadow receiveShadow>
          <cylinderGeometry args={[0.28, 0.28, 0.18, 20]} />
        </mesh>
      )))}
    </group>
  );
};

export const CidadeToy: React.FC = () => {
  const quadro = useCurrentFrame();
  return (
    <group>
      <Ambiente />
      {/* Faixas de piso se encontram pela borda, com topo em y=0. */}
      <Caixa p={[0, -0.24, -15]} t={[100, 0.2, 90]} cor={C.asfalto} sombra={false} />
      <Caixa p={[0, -0.1, 2.75]} t={[60, 0.2, 4.5]} cor={C.faixaPiso} sombra={false} />
      <Caixa p={[0, -0.1, -2.05]} t={[60, 0.2, 4.7]} cor={C.piso} sombra={false} />
      <Caixa p={[0, -0.1, 0.35]} t={[60, 0.2, 0.1]} cor={C.meioFio} sombra={false} />
      <Caixa p={[0, -0.1, 0.45]} t={[60, 0.2, 0.1]} cor={C.faixaPiso} sombra={false} />
      <Caixa p={[0, -0.1, -4.5]} t={[60, 0.2, 0.2]} cor={C.meioFio} sombra={false} />
      <Caixa p={[0, -0.1, -30.4]} t={[60, 0.2, 39.2]} cor={C.piso} sombra={false} />
      <Caixa p={[0, -0.1, -10.7]} t={[60, 0.2, 0.2]} cor={C.meioFio} sombra={false} />
      {[-12, -6, 0, 6, 12].map((x) => <Caixa key={x} p={[x, -0.16, -7.6]} t={[2.7, 0.08, 0.18]} cor={C.faixa} sombra={false} />)}
      {/* Travessia lateral em caixas espessas sobre o asfalto rebaixado. */}
      {[0, 1, 2, 3, 4, 5].map((i) => <Caixa key={i} p={[-10.5, -0.16, -5 - i * 0.95]}
        t={[2.3, 0.08, 0.42]} cor={C.meioFio} sombra={false} />)}
      {TORRES.map(({ x, z, h, cor }) => <group key={x}>
        <Caixa p={[x, h / 2, z]} t={[5.2, h, 5]} cor={cor} />
      </group>)}
      {PREDIOS.map((predio) => <Predio key={predio.x} {...predio} />)}
      <Veiculo x={-4.6} z={-6.1} cor="#dc7962" />
      <Veiculo x={5.8} z={-8.9} cor="#e7b84c" onibus />
      {POSICOES.map((_, indice) => <Pedestre key={indice} indice={indice} quadro={quadro} />)}
    </group>
  );
};
