// Montador genérico: recebe uma ficha VALIDADA e monta a cena só com peças do catálogo (kit + oficina). Nenhum código por cena.
import React, { useLayoutEffect, useRef } from 'react';
import * as THREE from 'three';
import { AbsoluteFill, useCurrentFrame, useVideoConfig } from 'remotion';
import { ThreeCanvas } from '@remotion/three';
import { Boneco } from '../kit/Boneco';
import { Luz } from '../kit/Luz';
import { Camera } from '../kit/Camera';
import { Foco, Acabamento } from '../kit/Pos';
import { ELENCO } from '../kit/elenco';
import { CENARIOS_3D, EFEITOS_3D, HudContador, OBJETOS_3D } from './pecas';
import { HudGrande, Tela2D } from '../kit/Tela2D';
import { validarFicha, type FichaEntrada } from './schema';
import { caminho, cameraNoQuadro, expressaoNoQuadro, juntasNoQuadro } from './montador';

/** Objeto na mão: se a peça veio grande (ex.: celular de 50 cm), reduz para caber na mão (maior lado até 35 cm). */
const NaMao: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const g = useRef<THREE.Group>(null);
  useLayoutEffect(() => {
    const o = g.current; if (!o) return; o.scale.setScalar(1); o.updateMatrixWorld(true);
    const t = new THREE.Box3().setFromObject(o).getSize(new THREE.Vector3()); const m = Math.max(t.x, t.y, t.z);
    if (m > 0.35) o.scale.setScalar(0.35 / m);
  }, []);
  return <group ref={g}>{children}</group>;
};

export const Cena: React.FC<{ ficha: FichaEntrada; soCenario?: boolean }> = ({ ficha, soCenario = false }) => {
  const f = validarFicha(ficha); // ficha inválida = erro no render, nunca uma cena "chutada"
  const q = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const cam = cameraNoQuadro(f, q);
  const { Componente: Fundo, limites } = CENARIOS_3D[f.cenario];
  const ceu = limites.ceu;
  const ondeEsta = (id: string) => { const p = f.personagens.find((x) => x.id === id)!; return caminho(p, q, f.duracao); };
  return (
    <AbsoluteFill style={{ backgroundColor: ceu }}>
      <ThreeCanvas width={width} height={height} shadows flat gl={{ antialias: true, preserveDrawingBuffer: true }} camera={{ fov: cam.fov, position: cam.pos }}>
        <color attach="background" args={[ceu]} />
        <Camera chaves={[{ q: 0, pos: cam.pos, alvo: cam.alvo, fov: cam.fov }]} quadro={0} />
        {/* luz por cena (14/11): dia = sol; noite = céu azul fraco + luz de lua; abajur = noite + luz quente perto do protagonista */}
        {(f.luz ?? 'dia') === 'dia' ? <Luz ceu={ceu} /> : <Luz ceu="#2a3a66" forca={0.55} dir={[0.4, -1, -0.5]} />}
        {f.luz && f.luz !== 'dia' && <pointLight position={[ondeEsta(f.personagens[0].id).xz[0] + 0.9, 1.5, ondeEsta(f.personagens[0].id).xz[1] + 0.6]} color={f.luz === 'abajur' ? '#ffb45c' : '#b9cfff'} intensity={f.luz === 'abajur' ? 6 : 2.5} distance={6} decay={1.6} />}
        <Fundo />
        {!soCenario && f.personagens.map((p) => {
          const c = caminho(p, q, f.duracao);
          return <Boneco key={p.id} v={ELENCO[p.id]} j={juntasNoQuadro(p, q)} e={expressaoNoQuadro(p, q)} pos={[c.xz[0], 0, c.xz[1]]} giro={c.giro} />;
        })}
        {!soCenario && f.bola && (
          <mesh position={[f.bola.pos[0], 0.13, f.bola.pos[1]]} castShadow receiveShadow>
            <sphereGeometry args={[0.13, 32, 16]} /><meshStandardMaterial color="#e8582c" roughness={0.7} />
          </mesh>
        )}
        {!soCenario && (f.objetos ?? []).map((o, i) => {
          const peca = OBJETOS_3D[o.nome]; if (!peca) return null;
          if (o.de) { // na mão: à frente e à direita do personagem, na altura da mão, girando junto com ele
            const c = ondeEsta(o.de), r = (c.giro * Math.PI) / 180;
            const x = c.xz[0] + Math.cos(r) * -0.32 + Math.sin(r) * 0.28, z = c.xz[1] - Math.sin(r) * -0.32 + Math.cos(r) * 0.28;
            return <group key={i} position={[x, 0.85, z]} rotation={[0, r, 0]}><NaMao><peca.Componente /></NaMao></group>;
          }
          return (
            <group key={i} position={[o.pos![0], 0, o.pos![1]]}>
              {peca.apoio === 'mesa' && <mesh position={[0, 0.375, 0]} castShadow receiveShadow><boxGeometry args={[0.5, 0.75, 0.5]} /><meshStandardMaterial color="#d9d2c3" roughness={0.85} /></mesh>}
              <group position={[0, peca.apoio === 'mesa' ? 0.75 : 0, 0]}><peca.Componente /></group>
            </group>
          );
        })}
        {!soCenario && (f.efeitos ?? []).map((e, i) => {
          const Ef = EFEITOS_3D[e.nome]; if (!Ef) return null;
          const c = ondeEsta(e.em ?? [f.camera.alvo].flat()[0]);
          return <group key={i} position={[c.xz[0], 0, c.xz[1]]}><Ef quadro={q} /></group>;
        })}
        <Foco foco={cam.foco} />
      </ThreeCanvas>
      <Acabamento quadro={q} />
      {f.tela && <Tela2D quadro={q} tipo={f.tela.tipo} titulo={f.tela.titulo} linhas={f.tela.linhas} />}
      {f.hud && f.hud.grande && <HudGrande quadro={q} rotulo={f.hud.rotulo} valor={f.hud.valor} />}
      {f.hud && (!f.hud.grande || q > 60) && <HudContador quadro={f.hud.grande ? q - 60 : q + 30} rotulo={f.hud.rotulo} valor={f.hud.valor} />}
    </AbsoluteFill>
  );
};
