// Cenário: gráfico 3D de barras verdes num fundo azul-escuro liso. As barras sobem em degraus iguais;
// a última sobe, bate na linha-teto vermelha "100%" e se espreme contra ela (o topo fica largo e baixo).
// Metros, Y para cima. O chão é invisível (só recebe sombra), então não há horizonte nem emenda.
// O gráfico fica num pedestal em z = -14, com a base acima da altura das cabeças: visto da câmera da vitrine,
// as cinco barras, a linha e a etiqueta ficam por cima dos personagens, com margem dos dois lados.
import * as THREE from 'three';
import React, { useMemo } from 'react';
import { useCurrentFrame } from 'remotion';
import type { LimitesCenario } from '../tipos';
import { Caixa, Caixas, Ceu, PlanoFoco, Sol, type V3 } from './base';
import { Palavra } from './letras';

const C = {
  barra: '#2fbf6a', tampa: '#7be3a3', base: '#c9d6ea', baseFrente: '#9fb3d3', pedestal: '#1d3570', pedestal2: '#25407f',
  painel: '#3c62b0', grade: '#5077c4', linha: '#e8443a', amarelo: '#ffd23f', branco: '#ffffff',
};

export const LIMITES_GRAFICO: LimitesCenario = { limiteX: 1.5, limiteZ: [-1, 3], ceu: '#152a5c' };

const ZG = -14; // linha das barras
const X0 = -2.3; // centro das barras (a etiqueta fica à direita delas)
const PASSO = 3.3; // distância entre barras
const XS = [-2, -1, 0, 1, 2].map((i) => X0 + i * PASSO);
const L = 1.6; // lado da barra
const YB = 2.3; // topo da base (na altura das cabeças, vistas da câmera)
const ALT = [0.6, 1.2, 1.8, 2.4]; // degraus iguais
const HMAX = 2.75; // altura da linha-teto acima da base (a 5ª barra iria a 3 m e bate aqui)
const ET = 0.16; // espessura da linha
const YT = YB + HMAX + ET / 2; // centro da linha-teto
const XA = -10.2, XB = 8.6; // pontas da base e da linha-teto (a etiqueta fica dentro, à direita)
const LARG = XB - XA, XM = (XA + XB) / 2;

const clamp = (t: number) => Math.min(1, Math.max(0, t));
const saida = (t: number) => 1 - Math.pow(1 - clamp(t), 3);
// quadros-chave: barras 1-4 crescem em sequência; a 5ª sobe reto, bate em Q_BATE e se espreme até Q_BATE + 12
const Q_BARRA = (i: number) => 4 + i * 9;
const Q5 = 40, Q_BATE = 58;

/** Setinha amarela "subindo" na face da frente. */
const Seta: React.FC<{ p: V3 }> = ({ p }) => (
  <group position={p}>
    <Caixa p={[-0.16, 0, 0]} t={[0.42, 0.12, 0.03]} r={[0, 0, Math.PI / 4]} cor={C.amarelo} sombra={false} />
    <Caixa p={[0.16, 0, 0]} t={[0.42, 0.12, 0.03]} r={[0, 0, -Math.PI / 4]} cor={C.amarelo} sombra={false} />
  </group>
);

/** Barra comum: corpo verde + tampa clara, com seta na frente. */
const Barra: React.FC<{ x: number; h: number }> = ({ x, h }) => {
  if (h < 0.01) return null;
  const tampa = Math.min(0.1, h * 0.3);
  return (
    <group position={[x, YB, ZG]}>
      <Caixa p={[0, (h - tampa) / 2, 0]} t={[L, h - tampa, L]} cor={C.barra} />
      <Caixa p={[0, h - tampa / 2, 0]} t={[L, tampa, L]} cor={C.tampa} />
      {h > 0.5 && <Seta p={[0, h - 0.32, L / 2 + 0.02]} />}
    </group>
  );
};

/** Última barra: sobe reta até a linha; depois do choque o corpo alarga um pouco e o topo vira uma "almofada"
 *  larga e baixa, espremida contra a linha (caixas retas, sem trapézio). `k` = 0 antes do choque, 1 espremida. */
const BarraEspremida: React.FC<{ x: number; h: number; k: number }> = ({ x, h, k }) => {
  if (h < 0.01) return null;
  const hTopo = 0.1 + 0.16 * k; // a tampa vira a almofada
  const hMeio = 0.3 * k; // faixa de transição: o corpo "esparrama" em dois degraus
  const wCorpo = L * (1 + 0.1 * k), wMeio = L * (1 + 0.38 * k), wTopo = L * (1 + 0.75 * k);
  const hCorpo = h - hTopo - hMeio;
  return (
    <group position={[x, YB, ZG]}>
      <Caixa p={[0, hCorpo / 2, 0]} t={[wCorpo, hCorpo, wCorpo]} cor={C.barra} />
      {k > 0 && <Caixa p={[0, hCorpo + hMeio / 2, 0]} t={[wMeio, hMeio, wCorpo + 0.05]} cor={C.barra} />}
      <Caixa p={[0, h - hTopo / 2, 0]} t={[wTopo, hTopo, wCorpo + 0.1 * k]} cor={C.tampa} />
      {k === 0 && h > 0.5 && <Seta p={[0, h - 0.32, L / 2 + 0.02]} />}
    </group>
  );
};

/** Marca de impacto (estilo gibi): três raios curtos saindo do canto. `lado` = -1 esquerda, 1 direita. */
const Impacto: React.FC<{ p: V3; lado: 1 | -1; k: number }> = ({ p, lado, k }) => (
  <group position={p} scale={k}>
    {[-30, 5, 40].map((a) => {
      const r = THREE.MathUtils.degToRad(a), dx = Math.cos(r) * lado, dy = Math.sin(r);
      return <Caixa key={a} p={[dx * 0.4, dy * 0.4, 0]} t={[0.36, 0.11, 0.05]} r={[0, 0, Math.atan2(dy, dx)]} cor={C.amarelo} sombra={false} />;
    })}
  </group>
);

export const GraficoBarras: React.FC = () => {
  const q = useCurrentFrame();
  // 5ª barra: sobe em linha reta até a linha; depois do choque se espreme com um pequeno quique
  const h5 = Math.min(HMAX, ((q - Q5) / (Q_BATE - Q5)) * HMAX);
  const tb = q - Q_BATE;
  const k5 = tb <= 0 ? 0 : clamp(saida(tb / 10) + 0.12 * Math.sin(tb * 0.8) * Math.exp(-tb / 7));
  const kImp = tb <= 0 ? 0 : saida(tb / 6);
  const faiscas = useMemo(() => [-1, 1].flatMap((s) => [0.2, 0.55, 0.9].map((y) => ({ s, y }))), []);
  const tf = clamp(tb / 16);
  const x5 = XS[4], wTopo5 = L * (1 + 0.75 * k5);
  // linhas de grade do painel de trás, uma a cada degrau (0,6 m)
  const grade = useMemo(() => [1, 2, 3, 4].map((i) => ({ p: [XM, YB + i * 0.6, ZG - 1.43] as V3, t: [LARG - 0.6, 0.08, 0.04] as V3 })), []);
  return (
    <group>
      <Ceu baixo="#1f3a78" alto="#0d1838" />
      {/* sol vindo da frente e um pouco da direita: as sombras das barras caem no painel de trás */}
      <Sol dir={[-1.0, -0.8, -0.6]} cor="#fff1dc" forca={2.4} area={24} />
      <hemisphereLight args={['#c4d2ff', '#1d3470', 0.6]} />
      <PlanoFoco z={-1} />
      {/* chão invisível: só a sombra aparece, sobre o mesmo azul do fundo */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} receiveShadow>
        <planeGeometry args={[80, 80]} />
        <shadowMaterial opacity={0.45} color="#050b1c" />
      </mesh>
      {/* pedestal azul (um tom acima do fundo) com a base clara do gráfico em cima */}
      <Caixa p={[XM, (YB - 0.16) / 2, ZG - 0.2]} t={[LARG, YB - 0.16, 2.6]} cor={C.pedestal} />
      <Caixa p={[XM, 0.25, ZG + 1.15]} t={[LARG + 0.2, 0.5, 0.4]} cor={C.pedestal2} />
      <Caixa p={[XM, YB - 0.08, ZG - 0.2]} t={[LARG + 0.1, 0.16, 2.7]} cor={C.base} />
      <Caixa p={[XM, YB - 0.2, ZG + 1.17]} t={[LARG + 0.1, 0.08, 0.08]} cor={C.baseFrente} sombra={false} />
      {/* painel de trás com grade: recebe a sombra das barras e marca os degraus */}
      <Caixa p={[XM, YB + HMAX / 2 + 0.2, ZG - 1.5]} t={[LARG, HMAX + 0.4, 0.1]} cor={C.painel} />
      <Caixas itens={grade} cor={C.grade} sombra={false} />
      {ALT.map((h, i) => <Barra key={i} x={XS[i]} h={h * saida((q - Q_BARRA(i)) / 12)} />)}
      <BarraEspremida x={x5} h={Math.max(0, h5)} k={k5} />
      {/* linha-teto vermelha com tampas nas pontas */}
      <Caixa p={[XM, YT, ZG]} t={[LARG - 0.4, ET, ET * 1.4]} cor={C.linha} />
      {[-1, 1].map((s) => <Caixa key={s} p={[XM + s * (LARG / 2 - 0.2), YT, ZG]} t={[0.24, 0.34, 0.26]} cor={C.linha} />)}
      {/* etiqueta "100%" pendurada logo abaixo da linha, colada no ponto de choque */}
      <group position={[x5 + 3.05, YT - ET / 2 - 0.08, ZG + 0.1]}>
        <Caixa p={[0, -0.3, 0]} t={[2.0, 0.6, 0.1]} cor={C.linha} />
        <Palavra txt="100%" p={[0, -0.5, 0.07]} l={0.3} a={0.4} e={0.085} esp={0.13} cor={C.branco} />
      </group>
      {/* choque: marcas de impacto nos cantos de cima e faíscas */}
      {kImp > 0 && (<>
        <Impacto p={[x5 - wTopo5 / 2 - 0.08, YT - 0.32, ZG + 0.95]} lado={-1} k={kImp * 0.85} />
        <Impacto p={[x5 + wTopo5 / 2 + 0.08, YT - 0.32, ZG + 0.95]} lado={1} k={kImp * 0.85} />
      </>)}
      {tb > 0 && tf < 1 && faiscas.map(({ s, y }, i) => (
        <Caixa key={i} p={[x5 + s * (0.9 + tf * 1.4 * y), YT - 0.1 - y * tf * 0.6, ZG + 1.0]} t={[0.14 * (1 - tf), 0.14 * (1 - tf), 0.14 * (1 - tf)]} cor={C.amarelo} sombra={false} />
      ))}
    </group>
  );
};
