import React from 'react';
import * as THREE from 'three';

export type V3 = [number, number, number];

const cache = new Map<string, THREE.MeshStandardMaterial>();
const cacheChapado = new Map<string, THREE.MeshBasicMaterial>();

// Recortes e LEDs mantêm a cor mesmo sob a luz quente do palco.
export const matChapado = (cor: string) => {
  let material = cacheChapado.get(cor);
  if (!material) {
    material = new THREE.MeshBasicMaterial({ color: cor, toneMapped: false });
    cacheChapado.set(cor, material);
  }
  return material;
};
export const mat = (cor: string) => {
  let material = cache.get(cor);
  if (!material) {
    material = new THREE.MeshStandardMaterial({ color: cor, roughness: 0.85 });
    cache.set(cor, material);
  }
  return material;
};

export const Caixa: React.FC<{
  p: V3; t: V3; cor: string; giro?: number; sombra?: boolean; chapado?: boolean;
}> = ({ p, t, cor, giro = 0, sombra = true, chapado = false }) => (
  <mesh position={p} rotation={[0, 0, giro]} material={chapado ? matChapado(cor) : mat(cor)}
    castShadow={sombra} receiveShadow={!chapado}>
    <boxGeometry args={t} />
  </mesh>
);

// Caixa arredondada: duas caixas e quatro cilindros, como no celular aprovado.
export const Placa: React.FC<{
  p: V3; largura: number; altura: number; espessura: number; raio: number; cor: string; chapado?: boolean;
}> = ({ p, largura, altura, espessura, raio, cor, chapado = false }) => (
  <group position={p}>
    <Caixa p={[0, 0, 0]} t={[largura - 2 * raio, altura, espessura]} cor={cor} chapado={chapado} />
    <Caixa p={[0, 0, 0]} t={[largura, altura - 2 * raio, espessura]} cor={cor} chapado={chapado} />
    {([-1, 1] as const).flatMap((sx) => ([-1, 1] as const).map((sy) => (
      <mesh key={`${sx}:${sy}`} position={[sx * (largura / 2 - raio), sy * (altura / 2 - raio), 0]}
        rotation={[Math.PI / 2, 0, 0]} material={chapado ? matChapado(cor) : mat(cor)} castShadow receiveShadow={!chapado}>
        <cylinderGeometry args={[raio, raio, espessura, 16]} />
      </mesh>
    )))}
  </group>
);
