// Base do lote r10-efeito: cache de material por cor (padrão do Quadra.tsx), formas comuns e a luz fria da neve.
import * as THREE from 'three';
import React, { useEffect, useLayoutEffect, useRef } from 'react';
import { useThree } from '@react-three/fiber';

export type V3 = [number, number, number];
export const TAU = Math.PI * 2;

const cache = new Map<string, THREE.MeshStandardMaterial>();
/** Material chapado (roughness 0,85). `brilho` > 0 acende a cor com emissivo (janela acesa, tela). `luz` troca a cor do emissivo. */
export const mat = (cor: string, brilho = 0, luz?: string) => {
  const b = Math.round(brilho * 20) / 20;
  const k = `${cor}|${b}|${luz ?? ''}`;
  let m = cache.get(k);
  if (!m) {
    m = new THREE.MeshStandardMaterial({ color: cor, roughness: 0.85 });
    if (b > 0) { m.emissive = new THREE.Color(luz ?? cor); m.emissiveIntensity = b; }
    cache.set(k, m);
  }
  return m;
};

/** Suaviza 0..1 (smoothstep). */
export const suave = (t: number) => { const x = Math.min(1, Math.max(0, t)); return x * x * (3 - 2 * x); };
/** Resto sempre positivo (loop sem número negativo). */
export const modulo = (a: number, n: number) => ((a % n) + n) % n;

export const Caixa: React.FC<{ p: V3; t: V3; m: THREE.Material; sombra?: boolean; recebe?: boolean }> = ({ p, t, m, sombra = true, recebe = true }) => (
  <mesh position={p} material={m} castShadow={sombra} receiveShadow={recebe}><boxGeometry args={t} /></mesh>
);

/** Retângulo de cantos arredondados (2 caixas em cruz + 4 cilindros), espessura d em Z. */
export const Ret: React.FC<{ w: number; h: number; d: number; r: number; x?: number; y?: number; z?: number; m: THREE.Material; sombra?: boolean }> = ({ w, h, d, r, x = 0, y = 0, z = 0, m, sombra = false }) => (
  <group position={[x, y, z]}>
    <mesh material={m} castShadow={sombra} receiveShadow><boxGeometry args={[w - 2 * r, h, d]} /></mesh>
    <mesh material={m} castShadow={sombra} receiveShadow><boxGeometry args={[w, h - 2 * r, d]} /></mesh>
    {([[-1, -1], [1, -1], [-1, 1], [1, 1]] as const).map(([sx, sy]) => (
      <mesh key={`${sx}${sy}`} position={[sx * (w / 2 - r), sy * (h / 2 - r), 0]} rotation={[Math.PI / 2, 0, 0]} material={m} castShadow={sombra} receiveShadow>
        <cylinderGeometry args={[r, r, d, 16]} />
      </mesh>
    ))}
  </group>
);

/** Disco virado para +Z. */
export const Disco: React.FC<{ r: number; d: number; x?: number; y?: number; z?: number; m: THREE.Material }> = ({ r, d, x = 0, y = 0, z = 0, m }) => (
  <mesh position={[x, y, z]} rotation={[Math.PI / 2, 0, 0]} material={m}><cylinderGeometry args={[r, r, d, 24]} /></mesh>
);

/** Traço reto de ponta redonda no plano XY (cápsula), de a até b, espessura e. */
export const Traco: React.FC<{ a: [number, number]; b: [number, number]; e: number; z?: number; m: THREE.Material }> = ({ a, b, e, z = 0, m }) => {
  const dx = b[0] - a[0], dy = b[1] - a[1], comp = Math.hypot(dx, dy);
  return (
    <mesh position={[(a[0] + b[0]) / 2, (a[1] + b[1]) / 2, z]} rotation={[0, 0, Math.atan2(dy, dx) - Math.PI / 2]} scale={[1, 1, 0.35]} material={m}>
      <capsuleGeometry args={[e / 2, comp, 4, 10]} />
    </mesh>
  );
};

type Guardado = { s?: THREE.DirectionalLight; sc?: THREE.Color; sf?: number; h?: THREE.HemisphereLight; hc?: THREE.Color; hg?: THREE.Color };
/** Luz fria enquanto o efeito está montado: esfria o hemisfério e o sol do kit (<Luz>) e devolve tudo ao desmontar. */
export const LuzFria: React.FC<{ ceu?: string; chao?: string; sol?: string; forcaSol?: number }> = ({ ceu = '#cfe0ff', chao = '#7f8aa0', sol = '#e4ecff', forcaSol = 2.0 }) => {
  const { scene } = useThree();
  const kit = useRef<Guardado | null>(null);
  const aplicar = () => {
    if (!kit.current) {
      const k: Guardado = {};
      scene.traverse((o) => {
        if (!k.s && (o as THREE.DirectionalLight).isDirectionalLight && o.castShadow) { k.s = o as THREE.DirectionalLight; k.sc = k.s.color.clone(); k.sf = k.s.intensity; }
        if (!k.h && (o as THREE.HemisphereLight).isHemisphereLight) { k.h = o as THREE.HemisphereLight; k.hc = k.h.color.clone(); k.hg = k.h.groundColor.clone(); }
      });
      kit.current = k;
    }
    const k = kit.current;
    if (k.s) { k.s.color.set(sol); k.s.intensity = forcaSol; }
    if (k.h) { k.h.color.set(ceu); k.h.groundColor.set(chao); }
  };
  useLayoutEffect(aplicar);
  useEffect(aplicar);
  useEffect(() => () => {
    const k = kit.current; if (!k) return;
    if (k.s && k.sc) { k.s.color.copy(k.sc); k.s.intensity = k.sf ?? k.s.intensity; }
    if (k.h && k.hc && k.hg) { k.h.color.copy(k.hc); k.h.groundColor.copy(k.hg); }
  }, []);
  return null;
};
