// Base do lote r18-objeto: cache de material por cor, primitivas posicionadas e dígitos de 7 segmentos.
import * as THREE from 'three';
import React from 'react';

const cache = new Map<string, THREE.MeshStandardMaterial>();
/** Material chapado (roughness 0.85 por padrão), um por cor+rugosidade+brilho próprio (emissivo, 0 a 1). */
export const mat = (cor: string, rug = 0.85, brilho = 0) => {
  const k = `${cor}|${rug}|${brilho}`;
  let m = cache.get(k);
  if (!m) {
    m = new THREE.MeshStandardMaterial({ color: cor, roughness: rug });
    if (brilho > 0) { m.emissive = new THREE.Color(cor); m.emissiveIntensity = brilho; }
    cache.set(k, m);
  }
  return m;
};

export type V3 = [number, number, number];
type Sombra = { sombra?: boolean; recebe?: boolean };

export const Caixa: React.FC<{ p: V3; t: V3; cor: string; r?: V3; m?: THREE.Material } & Sombra> = ({ p, t, cor, r, m, sombra = true, recebe = true }) => (
  <mesh position={p} rotation={r} material={m ?? mat(cor)} castShadow={sombra} receiveShadow={recebe}><boxGeometry args={t} /></mesh>
);

/** Cilindro em pé (eixo Y); `r` gira (ex.: [PI/2,0,0] deita o disco de frente para +Z). */
export const Cil: React.FC<{ p: V3; raio: number; h: number; cor: string; raio2?: number; lados?: number; r?: V3; m?: THREE.Material } & Sombra> = (
  { p, raio, h, cor, raio2, lados = 32, r, m, sombra = true, recebe = true },
) => (
  <mesh position={p} rotation={r} material={m ?? mat(cor)} castShadow={sombra} receiveShadow={recebe}><cylinderGeometry args={[raio, raio2 ?? raio, h, lados]} /></mesh>
);

// ── dígitos de 7 segmentos ────────────────────────────────────────────────
//   a
//  f b
//   g
//  e c
//   d
const SEGS: Record<string, string> = {
  '0': 'abcdef', '1': 'bc', '2': 'abged', '3': 'abgcd', '4': 'fgbc',
  '5': 'afgcd', '6': 'afgedc', '7': 'abc', '8': 'abcdefg', '9': 'abcdfg',
};
/** Retângulos [x, y, largura, altura] de um dígito centrado na origem (w x h, traço s).
 *  Os traços se sobrepõem nos cantos (mesma cor, mesmo plano): o dígito fica inteiriço. */
export function segmentos(d: string, w: number, h: number, s: number): [number, number, number, number][] {
  const out: [number, number, number, number][] = [];
  const meio = (h - s) / 2 + s; // altura de cada traço vertical (meia altura + sobreposição)
  for (const c of SEGS[d] ?? '') {
    if (c === 'a') out.push([0, h / 2 - s / 2, w, s]);
    if (c === 'g') out.push([0, 0, w, s]);
    if (c === 'd') out.push([0, -h / 2 + s / 2, w, s]);
    if (c === 'f') out.push([-w / 2 + s / 2, h / 4, s, meio]);
    if (c === 'b') out.push([w / 2 - s / 2, h / 4, s, meio]);
    if (c === 'e') out.push([-w / 2 + s / 2, -h / 4, s, meio]);
    if (c === 'c') out.push([w / 2 - s / 2, -h / 4, s, meio]);
  }
  // o "1" fica no meio da casa (não encostado à direita, senão lê como "I" deslocado)
  if (d === '1') return out.map(([x, y, a, b]) => [x - (w / 2 - s / 2) * 0.65, y, a, b]);
  return out;
}
