// Ajuste só da vitrine (composição VitrineLote), no padrão do r12–r14: posiciona a peça e fecha a câmera do palco nela.
// Fora da vitrine os componentes ficam puros (na origem, sem câmera, sem chão).
import React, { useLayoutEffect } from 'react';
import { useThree } from '@react-three/fiber';
import { useCurrentFrame, useVideoConfig } from 'remotion';
import * as THREE from 'three';
import { mat, Caixa, type V3 } from './base';
import { Trevo } from './Trevo';
import { Onibus, L as L_ONIBUS, W as W_ONIBUS, RODA, EIXOS } from './Onibus';
import { GraficoBarras } from './GraficoBarras';

const BASE_VITRINE: V3 = [0.75, 0, 0]; // onde a vitrine põe um objeto com apoio 'chao'

/** Câmera esférica em volta do alvo: dist (m), elev/azim (graus, azim 0 = de frente, +Z), altura do quadro no alvo (m). */
type Cam = { alvo: V3; dist: number; elev: number; azim: number; altura?: number; fov?: number; pos?: V3 };

const AjustarCamera: React.FC<{ c: Cam }> = ({ c }) => {
  const camera = useThree((s) => s.camera) as THREE.PerspectiveCamera;
  // roda depois da <Camera> do palco (vem antes na árvore), a cada quadro, sem loop próprio
  useLayoutEffect(() => {
    const e = (c.elev * Math.PI) / 180, a = (c.azim * Math.PI) / 180, h = c.dist * Math.cos(e);
    if (c.pos) camera.position.set(...c.pos);
    else camera.position.set(c.alvo[0] + h * Math.sin(a), c.alvo[1] + c.dist * Math.sin(e), c.alvo[2] + h * Math.cos(a));
    camera.lookAt(...c.alvo);
    camera.fov = c.fov ?? (2 * Math.atan((c.altura ?? 1) / 2 / c.dist) * 180) / Math.PI;
    camera.updateProjectionMatrix();
    camera.updateMatrixWorld();
  });
  return null;
};

/** Põe a peça em `pos` (mundo) e ajusta a câmera — só na VitrineLote. `extra` (mundo) também só aparece na vitrine. */
const naVitrine = (pos: V3, cam: Cam, filhos: React.ReactNode, puro: React.ReactNode, extra?: React.ReactNode) => {
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const { id } = useVideoConfig();
  if (id !== 'VitrineLote') return <>{puro}</>;
  return (
    <>
      <AjustarCamera c={cam} />
      <group position={[pos[0] - BASE_VITRINE[0], pos[1] - BASE_VITRINE[1], pos[2] - BASE_VITRINE[2]]}>{filhos}</group>
      {extra && <group position={[-BASE_VITRINE[0], -BASE_VITRINE[1], -BASE_VITRINE[2]]}>{extra}</group>}
    </>
  );
};

// Closes do trevo e do gráfico: num canto vazio do terreno (x = -6, z = 24), longe do Téo e da quadra.
// A câmera olha um pouco de cima para pegar a peça E a sua sombra no chão; o fundo é só chão liso, desfocado por igual.
const CANTO: V3 = [-6, 0, 24];

// ── trevo: pé do caule 30 cm acima do chão; close com o trevo no centro
const TREVO_ALTURA = 0.22;
export const TrevoNaVitrine: React.FC = () => {
  const q = useCurrentFrame();
  const abre = Math.min(1, Math.max(0, (q - 96) / 44)); // abre um pouco o quadro quando vira 2 e 4 trevos
  return naVitrine(
    [CANTO[0], TREVO_ALTURA, CANTO[2]],
    { alvo: [CANTO[0], 0.2 + 0.08 * abre, CANTO[2] - 0.02], dist: 1.2, elev: 28, azim: -8, altura: 0.54 + 0.45 * abre },
    <Trevo alturaChao={TREVO_ALTURA} />, <Trevo />,
  );
};

// ── gráfico: borda de baixo 25 cm acima do chão; close de frente (um pouco de cima), gráfico centralizado
const GRAFICO_ALTURA = 0.25;
export const GraficoNaVitrine: React.FC = () =>
  naVitrine(
    [CANTO[0], GRAFICO_ALTURA, CANTO[2]],
    { alvo: [CANTO[0] + 0.01, 0.33, CANTO[2] - 0.02], dist: 1.35, elev: 22, azim: 4, altura: 0.68 },
    <GraficoBarras alturaChao={GRAFICO_ALTURA} />, <GraficoBarras />,
  );

// ── ônibus: passa numa rua montada só para a vitrine (asfalto, faixas, calçadas e prédios), em z = 20 e x < 0,
// com a câmera de pedestre na calçada, à frente-direita, olhando para longe da quadra e da escola.
const VEL = 0.2;   // m por quadro
const Z_RUA = 20;
const Y_ASF = 0.01;                       // topo do asfalto
const RUA = { ini: -95, fim: 15 };        // trecho de rua em X
const Z_MEIO = Z_RUA - 2.4;               // linha tracejada entre as pistas
const Z_PERTO = Z_RUA + 2.9, Z_LONGE = Z_RUA - 6.1; // meios-fios

const Rua: React.FC = () => {
  const cx = (RUA.ini + RUA.fim) / 2, cl = RUA.fim - RUA.ini;
  const branco = mat('#f4f4f0'), calcada = mat('#cdcac2'), guia = mat('#a9a69e');
  const tracos: number[] = [];
  for (let x = RUA.ini + 2; x < RUA.fim; x += 6) tracos.push(x);
  // prédios do outro lado da rua: [x0, largura, altura, cor]
  const predios: [number, number, number, string][] = [
    [-92, 10, 13, '#e3b778'], [-81, 8, 9, '#9fc0d8'], [-72, 11, 15, '#e8d6b0'], [-60, 9, 10, '#d98c6a'],
    [-50, 12, 13, '#b8c9a0'], [-37, 8, 8, '#e3b778'], [-28, 10, 12, '#a7b4d6'], [-17, 9, 9, '#e8d6b0'],
    [-7, 11, 14, '#d98c6a'], [5, 10, 10, '#9fc0d8'],
  ];
  return (
    <group>
      {/* asfalto cinza (o chão da quadra fica 3 cm por baixo) */}
      <Caixa p={[cx, Y_ASF - 0.02, (Z_PERTO + Z_LONGE) / 2]} t={[cl, 0.04, Z_PERTO - Z_LONGE]} m={mat('#5f636b')} sombra={false} />
      {/* faixa tracejada do meio e linhas de bordo (2 cm acima do asfalto) */}
      {tracos.map((x) => <Caixa key={x} p={[x, Y_ASF, Z_MEIO]} t={[3, 0.04, 0.16]} m={branco} sombra={false} />)}
      {[Z_PERTO - 0.35, Z_LONGE + 0.35].map((z) => <Caixa key={z} p={[cx, Y_ASF, z]} t={[cl, 0.04, 0.14]} m={branco} sombra={false} />)}
      {/* calçadas com meio-fio */}
      <Caixa p={[cx, 0.07, Z_PERTO + 4.6]} t={[cl, 0.18, 9]} m={calcada} sombra={false} />
      <Caixa p={[cx, 0.07, Z_LONGE - 2.6]} t={[cl, 0.18, 5]} m={calcada} sombra={false} />
      {[Z_PERTO + 0.12, Z_LONGE - 0.12].map((z) => <Caixa key={z} p={[cx, 0.1, z]} t={[cl, 0.22, 0.24]} m={guia} sombra={false} />)}
      {/* prédios: bloco, platibanda e uma faixa de janelas por andar */}
      {predios.map(([x0, w, h, cor]) => (
        <group key={x0} position={[x0 + w / 2, 0, Z_LONGE - 9]}>
          <Caixa p={[0, h / 2, 0]} t={[w, h, 8]} m={mat(cor)} sombra={false} />
          <Caixa p={[0, h + 0.15, 0]} t={[w + 0.3, 0.3, 8.3]} m={mat('#efe9dc')} sombra={false} />
          {Array.from({ length: Math.floor((h - 1.5) / 3) }, (_, i) => (
            <Caixa key={i} p={[0, 2.4 + i * 3, 4.06]} t={[w - 1.4, 1.3, 0.12]} m={mat('#2e4c78')} sombra={false} />
          ))}
        </group>
      ))}
    </group>
  );
};

const matSombra = mat('#1c1e22', { opac: 0.1, rug: 0.9 });
const MARGENS = [0.0, 0.1, 0.22, 0.36, 0.52];
/** Sombra suave sob o ônibus (retângulos translúcidos crescentes) e sombra de contato escura sob cada roda. */
const SombraOnibus: React.FC = () => (
  <>
    {MARGENS.map((m, i) => (
      <mesh key={i} position={[0, 0.002 + (MARGENS.length - i) * 0.0006, 0]} material={matSombra}>
        <boxGeometry args={[L_ONIBUS + 0.1 + 2 * m, 0.0002, W_ONIBUS + 2 * m]} />
      </mesh>
    ))}
    {EIXOS.flatMap((x) => [1, -1].map((s) => (
      <mesh key={`${x}${s}`} position={[x, 0.006, s * (W_ONIBUS / 2 - 0.12)]} scale={[RODA * 1.1, 1, 0.3]} material={mat('#141518', { opac: 0.55 })}>
        <cylinderGeometry args={[1, 1, 0.001, 24]} />
      </mesh>
    )))}
  </>
);

export const OnibusNaVitrine: React.FC = () => {
  const q = useCurrentFrame();
  const xFrente = -14 + VEL * (q - 90);
  const andado = VEL * q;
  return naVitrine(
    [xFrente - L_ONIBUS / 2, Y_ASF, Z_RUA],
    // câmera na calçada, à frente-direita; ônibus inteiro no quadro com folga à direita (para onde ele vai)
    // (a ~3,8 m do canto da frente: perto do foco de 2,1 m da vitrine, a frente fica nítida e a traseira desfoca)
    { pos: [xFrente + 3.0, 1.4, Z_RUA + 3.6], alvo: [xFrente - 0.94, 1.93, Z_RUA + 0.52], dist: 0, elev: 0, azim: 0, fov: 47 },
    <><SombraOnibus /><Onibus andado={andado} rastro quadro={q} /></>,
    <Onibus />,
    <Rua />,
  );
};
