// Objeto: prova de química (folha de 30 x 40 cm, 5 mm para a borda aparecer) com um tubo de ensaio azul desenhado no topo
// e linhas de texto cinza em espaçamento regular. `ProvaOito` é a mesma folha com um 8 vermelho grande circulado no canto.
// Em pé: frente para +Z, base em y = 0. `deitada`: frente para cima, centrada na origem. `pilha`: n folhas (a de cima desenhada).
import React from 'react';
import { random } from 'remotion';
import { mat, Ret, Disco, Tracos, Deitavel, type Traco } from './base';

const C = {
  papel: '#fff7ec', borda: '#b3a68f', linha: '#8d929e', titulo: '#5c6272',
  contorno: '#1c4a96', vidro: '#a9d2f5', liquido: '#2a7fe0', menisco: '#1a5fb8', reflexo: '#ffffff',
  vermelho: '#d9202a',
};
const W = 0.3, H = 0.4, D = 0.005, TAMPA = 0.0004; // corpo da folha (cor da borda) + tampa branca rente ao topo
// branco quente: o céu e o azul da quadra puxam para o verde-água, então a base é um pouco creme e acesa
const PAPEL = mat(C.papel, { brilho: 0.12 });
// camadas de tinta acima da tampa: 0,6 mm entre uma e outra (nunca coplanares)
const zc = (k: number) => D + TAMPA + 0.0003 + k * 0.0006;

// corpo: 7 linhas de 8 mm, passo regular de 2,7 cm, margem de 2,5 cm à esquerda
const COMPR = [0.25, 0.21, 0.25, 0.16, 0.25, 0.22, 0.12];
const LINHAS: Traco[] = COMPR.map((c, i) => [-0.125, -0.005 - i * 0.027, -0.125 + c, -0.005 - i * 0.027]);
// cabeçalho da provaQuimica, à direita do tubo: título grosso + duas linhas (nome e turma)
const TITULO: Traco[] = [[-0.05, 0.142, 0.115, 0.142]];
const CABECALHO: Traco[] = [[-0.05, 0.105, 0.09, 0.105], [-0.05, 0.078, 0.125, 0.078]];

/** Tubo de ensaio desenhado: contorno azul-escuro, vidro azul-claro, fundo redondo, líquido pela metade, boca com aba. */
const Tubo: React.FC = () => {
  const X = -0.105, rr = 0.017, c = 0.0035, yb = 0.045, yt = 0.163, yl = 0.095; // raio, contorno, fundo, boca, líquido
  const caixa = (y0: number, y1: number, w: number, k: number, cor: string, x = X) => (
    <mesh position={[x, (y0 + y1) / 2, zc(k)]} material={mat(cor)} receiveShadow><boxGeometry args={[w, y1 - y0, 0.0004]} /></mesh>
  );
  return (
    <group>
      {caixa(yb, yt, 2 * (rr + c), 1, C.contorno)}
      <Disco r={rr + c} d={0.0004} x={X} y={yb} z={zc(1)} m={mat(C.contorno)} />
      {caixa(yb, yt, 2 * rr, 2, C.vidro)}
      <Disco r={rr} d={0.0004} x={X} y={yb} z={zc(2)} m={mat(C.vidro)} />
      {caixa(yb, yl, 2 * rr, 3, C.liquido)}
      <Disco r={rr} d={0.0004} x={X} y={yb} z={zc(3)} m={mat(C.liquido)} />
      {/* nível do líquido, boca com aba, reflexo no vidro e duas bolhas */}
      {caixa(yl - 0.002, yl + 0.002, 2 * rr, 4, C.menisco)}
      {caixa(yt - 0.004, yt + 0.004, 2 * (rr + c) + 0.01, 4, C.contorno)}
      {caixa(yl + 0.012, yt - 0.014, 0.004, 4, C.reflexo, X - rr + 0.007)}
      <Disco r={0.0045} d={0.0004} x={X + 0.005} y={0.072} z={zc(4)} m={mat(C.reflexo)} />
      <Disco r={0.003} d={0.0004} x={X - 0.006} y={0.054} z={zc(4)} m={mat(C.reflexo)} />
    </group>
  );
};

/** Anel chapado: disco vermelho + miolo cor de papel por cima (sem o sombreado de um toro). sx alarga em X (elipse); traço t igual em volta. */
const Anel: React.FC<{ y: number; r: number; t: number; sx?: number; k: number }> = ({ y, r, t, sx = 1, k }) => (
  <>
    <mesh position={[0, y, zc(k)]} rotation={[Math.PI / 2, 0, 0]} scale={[sx, 1, 1]} material={mat(C.vermelho)} receiveShadow>
      <cylinderGeometry args={[r, r, 0.0004, 64]} />
    </mesh>
    <mesh position={[0, y, zc(k + 1)]} rotation={[Math.PI / 2, 0, 0]} scale={[(sx * r - t) / (r - t), 1, 1]} material={PAPEL} receiveShadow>
      <cylinderGeometry args={[r - t, r - t, 0.0004, 64]} />
    </mesh>
  </>
);

/** O 8 vermelho (10 x 6,7 cm, traço de 1,4–1,5 cm: dois anéis empilhados) dentro de uma elipse de 18 x 13 cm (1,4:1), traço de 1 cm. */
const OitoCirculado: React.FC = () => (
  <group position={[0.0375, 0.115, 0]}>
    <Anel y={0} r={0.065} t={0.01} sx={0.09 / 0.065} k={1} />
    {/* anéis do 8: os traços se juntam na cintura, e os miolos não cortam o outro anel */}
    <Anel y={-0.022} r={0.028} t={0.015} sx={1.2} k={3} />
    <Anel y={0.027} r={0.024} t={0.014} sx={1.15} k={5} />
  </group>
);

const Folha: React.FC<{ oito: boolean }> = ({ oito }) => (
  <group position={[0, H / 2, 0]}>
    <Tracos tracos={LINHAS} l={0.008} z={zc(1)} m={mat(C.linha)} />
    <Tubo />
    {oito ? <OitoCirculado /> : (
      <>
        <Tracos tracos={TITULO} l={0.018} z={zc(1)} m={mat(C.titulo)} />
        <Tracos tracos={CABECALHO} l={0.008} z={zc(1)} m={mat(C.linha)} />
      </>
    )}
  </group>
);

/** Papel: corpo de 5 mm na cor da borda (a espessura aparece de lado) e a tampa branca, 1,5 mm para dentro. */
const Papel: React.FC<{ z: number }> = ({ z }) => (
  <group position={[0, H / 2, 0]}>
    <Ret w={W} h={H} d={D} r={0.004} z={z + D / 2} m={mat(C.borda)} sombra recebe={false} />
    <Ret w={W - 0.003} h={H - 0.003} d={TAMPA * 2} r={0.003} z={z + D} m={PAPEL} />
  </group>
);

const Prova: React.FC<{ oito: boolean; deitada?: boolean; pilha?: number }> = ({ oito, deitada = false, pilha = 1 }) => {
  const n = Math.max(1, Math.round(pilha));
  const passo = D + TAMPA;
  return (
    <Deitavel deitada={deitada} alto={H}>
      {/* folhas de baixo: lisas, um pouco tortas (acaso fixo) */}
      {Array.from({ length: n - 1 }, (_, i) => (
        <group key={i} position={[(random(`prova-x-${i}`) - 0.5) * 0.012, (random(`prova-y-${i}`) - 0.5) * 0.01, 0]}
          rotation={[0, 0, (random(`prova-r-${i}`) - 0.5) * 0.06]}>
          <Papel z={i * passo} />
        </group>
      ))}
      <group position={[0, 0, (n - 1) * passo]}>
        <Papel z={0} />
        <Folha oito={oito} />
      </group>
    </Deitavel>
  );
};

export const ProvaQuimica: React.FC<{ deitada?: boolean; pilha?: number }> = (p) => <Prova oito={false} {...p} />;
export const ProvaOito: React.FC<{ deitada?: boolean; pilha?: number }> = (p) => <Prova oito {...p} />;
