// Cenário: corredor comprido de escola. Piso claro em xadrez, paredes amarelas, armários azuis à esquerda (-X),
// portas das salas à direita (+X), luminárias no teto e porta dupla com janela no fim (-Z). Perspectiva em fuga.
import React from 'react';
import type { LimitesCenario } from '../tipos';
import { Caixa, PlanoFoco, mat, type V3 } from './base';

const C = {
  piso: '#ece6d8', piso2: '#ddd3bf', parede: '#f4d36e', rodape: '#c99a3c', faixa: '#e7bf52', teto: '#f4f2ec',
  armario: '#3f73c4', armario2: '#5a8fdc', escuro: '#25467a', puxador: '#d9dde3',
  batente: '#f8f5ef', folha: '#9a6236', visor: '#bfe0f2', placa: '#2f6fb0', branco: '#f8f5ef',
  luz: '#fffdf4', cortica: '#c99a5e', ceuJanela: '#a9d8f0',
};

const X = 2.4; // paredes em x = ±2,4 (corredor de 4,8 m)
const H = 3.0; // pé-direito
const ZF = -16; // parede do fundo
const ZT = 8; // as paredes vão até atrás da câmera
const ZC = (ZF + ZT) / 2, L = ZT - ZF;

export const LIMITES_CORREDOR: LimitesCenario = { limiteX: 1.5, limiteZ: [-1.0, 3.0], ceu: '#f6efdc' };

/** Piso: base clara + ladrilhos de 1,2 m no outro tom, 2 cm acima. */
const Piso: React.FC = () => {
  const lad: V3[] = [];
  for (let i = 0; i < 4; i++) for (let j = 0; j < 20; j++) if ((i + j) % 2 === 0) lad.push([-X + 0.6 + i * 1.2, -0.01, ZF + 0.6 + j * 1.2]);
  return (
    <group>
      <Caixa p={[0, -0.06, ZC]} t={[2 * X + 0.4, 0.08, L]} cor={C.piso} sombra={false} />
      {lad.map((p, i) => <Caixa key={i} p={p} t={[1.2, 0.02, 1.2]} cor={C.piso2} sombra={false} />)}
    </group>
  );
};

/** Parede lateral contínua (sem sombra projetada), rodapé fino e faixa na altura de 1,1 m. `lado` -1 = esquerda. */
const Parede: React.FC<{ lado: 1 | -1 }> = ({ lado }) => {
  const xd = lado * X; // face interna
  return (
    <group>
      <Caixa p={[xd + lado * 0.1, H / 2, ZC]} t={[0.2, H + 0.2, L]} cor={C.parede} sombra={false} />
      {/* rodapé e faixa saem só 2 cm da parede: batentes e placas ficam 2 cm à frente deles */}
      <Caixa p={[xd - lado * 0.01, 0.06, ZC]} t={[0.02, 0.12, L]} cor={C.rodape} sombra={false} />
      <Caixa p={[xd - lado * 0.01, 2.3, ZC]} t={[0.02, 0.1, L]} cor={C.faixa} sombra={false} />
    </group>
  );
};

/** Bloco de armários na parede esquerda: `n` portas de 45 cm a partir de z0 (indo para -Z). Altura 1,85 m. */
const Armarios: React.FC<{ z0: number; n: number }> = ({ z0, n }) => {
  const prof = 0.4, alt = 1.85, w = 0.45, xf = -X + prof; // xf = frente do armário
  const zc = z0 - (n * w) / 2;
  return (
    <group>
      <Caixa p={[-X + prof / 2, alt / 2 + 0.05, zc]} t={[prof, alt - 0.1, n * w]} cor={C.armario} />
      <Caixa p={[-X + prof / 2, 0.05, zc]} t={[prof - 0.06, 0.1, n * w]} cor={C.escuro} sombra={false} />
      {Array.from({ length: n }, (_, i) => {
        const z = z0 - w / 2 - i * w;
        return (
          <group key={i}>
            {/* porta 2 cm à frente da carcaça; fresta de 8 cm entre portas */}
            <Caixa p={[xf + 0.02, alt / 2 + 0.05, z]} t={[0.04, alt - 0.22, w - 0.08]} cor={C.armario2} sombra={false} />
            {/* ventilação e puxador, todos na mesma altura, 2 cm à frente da porta */}
            <Caixa p={[xf + 0.05, 1.6, z]} t={[0.03, 0.1, 0.24]} cor={C.escuro} sombra={false} />
            <Caixa p={[xf + 0.06, 1.0, z - 0.1]} t={[0.04, 0.2, 0.08]} cor={C.puxador} sombra={false} />
          </group>
        );
      })}
    </group>
  );
};

/** Porta de sala na parede direita, centrada em z: batente, folha 2 cm à frente, visor 2 cm à frente, maçaneta e placa. */
const PortaSala: React.FC<{ z: number; cor: string }> = ({ z, cor }) => {
  const xf = X; // face da parede
  return (
    <group>
      <Caixa p={[xf - 0.02, 1.1, z]} t={[0.04, 2.2, 1.2]} cor={C.batente} sombra={false} />
      <Caixa p={[xf - 0.04, 1.04, z]} t={[0.04, 2.08, 1.0]} cor={C.folha} sombra={false} />
      <Caixa p={[xf - 0.06, 1.5, z + 0.2]} t={[0.04, 0.5, 0.26]} cor={C.visor} sombra={false} />
      <mesh position={[xf - 0.1, 1.0, z - 0.36]} material={mat(C.puxador)} castShadow><sphereGeometry args={[0.05, 12, 8]} /></mesh>
      {/* placa da sala: retângulo colado na parede acima do batente, com um traço branco grosso de "nome" */}
      <Caixa p={[xf - 0.02, 2.48, z]} t={[0.04, 0.26, 0.7]} cor={cor} sombra={false} />
      <Caixa p={[xf - 0.04, 2.48, z]} t={[0.03, 0.08, 0.44]} cor={C.branco} sombra={false} />
    </group>
  );
};

/** Mural de cortiça na parede direita, com papéis coloridos (sem texto). */
const Mural: React.FC<{ z: number }> = ({ z }) => (
  <group>
    {/* moldura de madeira, cortiça 2 cm à frente, papéis 2 cm à frente da cortiça */}
    <Caixa p={[X - 0.02, 1.55, z]} t={[0.04, 1.0, 1.5]} cor={C.folha} sombra={false} />
    <Caixa p={[X - 0.04, 1.55, z]} t={[0.04, 0.84, 1.34]} cor={C.cortica} sombra={false} />
    {([[1.7, -0.35, '#fdfbf3'], [1.65, 0.1, '#f6d95c'], [1.4, 0.42, '#8fc6f0'], [1.35, -0.12, '#f5a6b8']] as const).map(([y, dz, cor], i) => (
      <Caixa key={i} p={[X - 0.07, y, z + dz]} t={[0.02, 0.3, 0.26]} cor={cor} sombra={false} />
    ))}
  </group>
);

/** Fundo do corredor: parede, porta dupla com visores e janela alta com céu. */
const Fundo: React.FC = () => (
  <group>
    <Caixa p={[0, H / 2, ZF - 0.1]} t={[2 * X + 0.4, H + 0.2, 0.2]} cor={C.parede} sombra={false} />
    <Caixa p={[0, 0.06, ZF + 0.01]} t={[2 * X, 0.12, 0.02]} cor={C.rodape} sombra={false} />
    <Caixa p={[0, 1.15, ZF + 0.02]} t={[2.0, 2.3, 0.04]} cor={C.batente} sombra={false} />
    {[-0.46, 0.46].map((x) => (
      <group key={x}>
        <Caixa p={[x, 1.08, ZF + 0.04]} t={[0.84, 2.16, 0.04]} cor={C.armario} sombra={false} />
        <Caixa p={[x, 1.45, ZF + 0.06]} t={[0.4, 0.7, 0.04]} cor={C.visor} sombra={false} />
        <Caixa p={[x - Math.sign(x) * 0.28, 1.0, ZF + 0.08]} t={[0.1, 0.1, 0.04]} cor={C.puxador} sombra={false} />
      </group>
    ))}
    {/* janela alta acima da porta */}
    <Caixa p={[0, 2.68, ZF + 0.02]} t={[2.0, 0.5, 0.04]} cor={C.batente} sombra={false} />
    <Caixa p={[0, 2.68, ZF + 0.04]} t={[1.8, 0.34, 0.04]} cor={C.ceuJanela} sombra={false} m={mat(C.ceuJanela, { brilho: 0.5 })} />
  </group>
);

export const CorredorEscola: React.FC = () => {
  // armários: blocos de 7 portas (3,15 m) com vãos de parede entre eles
  const blocos = [1.2, -2.6, -6.4, -10.2];
  const portas = [-0.6, -5.2, -9.8, -14.0];
  const placas = ['#2f6fb0', '#d6453d', '#2fa36b', '#8e5bd6'];
  const luzes = Array.from({ length: 8 }, (_, i) => 4 - i * 2.6);
  return (
    <group>
      {/* foco: o fundo do corredor é desfocado como se estivesse a 1 m atrás dos bonecos */}
      <PlanoFoco z={-1.0} />
      <Piso />
      <Parede lado={-1} />
      <Parede lado={1} />
      <Fundo />
      {/* teto claro, levemente aceso (sem sombra: a luz é a das luminárias) */}
      <Caixa p={[0, H + 0.05, ZC]} t={[2 * X + 0.4, 0.1, L]} cor={C.teto} sombra={false} m={mat(C.teto, { brilho: 0.5 })} />
      {luzes.map((z) => (
        <group key={z}>
          <Caixa p={[0, H - 0.03, z]} t={[0.6, 0.06, 1.4]} cor="#d9dde3" sombra={false} />
          <mesh position={[0, H - 0.08, z]} material={mat(C.luz, { brilho: 1.4 })}><boxGeometry args={[0.44, 0.04, 1.24]} /></mesh>
        </group>
      ))}
      {/* luz difusa das luminárias, sem sombra */}
      {[2.5, -3.5, -9.5].map((z) => <pointLight key={z} position={[0, H - 0.4, z]} color="#fff4dc" intensity={6} distance={9} decay={1.2} />)}
      {blocos.map((z) => <Armarios key={z} z0={z} n={7} />)}
      {portas.map((z, i) => <PortaSala key={z} z={z} cor={placas[i]} />)}
      <Mural z={-2.9} />
      <Mural z={-11.9} />
    </group>
  );
};
