// Objetos das demonstrações do lote (tamanho real, só primitivas, cores chapadas, cache de material por cor).
import * as THREE from 'three';
import React from 'react';

const cache = new Map<string, THREE.MeshStandardMaterial>();
export const mat = (cor: string, rug = 0.85) => {
  const k = `${cor}|${rug}`;
  let m = cache.get(k);
  if (!m) { m = new THREE.MeshStandardMaterial({ color: cor, roughness: rug }); cache.set(k, m); }
  return m;
};
type V3 = [number, number, number];
const Caixa: React.FC<{ p: V3; t: V3; cor: string; r?: V3 }> = ({ p, t, cor, r = [0, 0, 0] }) => (
  <mesh position={p} rotation={r} material={mat(cor)} castShadow receiveShadow><boxGeometry args={t} /></mesh>
);
const Bola: React.FC<{ p: V3; r: number; cor: string; esc?: V3 }> = ({ p, r, cor, esc = [1, 1, 1] }) => (
  <mesh position={p} scale={esc} material={mat(cor)} castShadow receiveShadow><sphereGeometry args={[r, 20, 12]} /></mesh>
);
/** Trevo de 4 folhas chapado (frente +Z), centro em p. */
const Trevo: React.FC<{ p: V3; t: number }> = ({ p, t }) => (
  <group position={p}>
    {[0, 1, 2, 3].map((i) => {
      const a = (i * Math.PI) / 2 + Math.PI / 4;
      return <Bola key={i} p={[Math.cos(a) * t * 0.55, Math.sin(a) * t * 0.55, 0]} r={t * 0.5} cor="#2f9e44" esc={[1, 1, 0.25]} />;
    })}
    <Caixa p={[t * 0.25, -t * 0.9, 0]} t={[t * 0.18, t * 0.9, t * 0.1]} r={[0, 0, 0.5]} cor="#237a34" />
  </group>
);

// ---------------- Pacote de salgadinho (18 × 25 × 5 cm). Origem no meio da boca (borda de cima), frente +Z ----------------
export const PACOTE = { larg: 0.18, alt: 0.25 };
const P = { saco: '#f5c542', faixa: '#e2862b', rotulo: '#d63a2f', selo: '#c9a12f', dentro: '#5a3a1a', salg: '#f0a535' };
export const Pacote: React.FC<{ rasgado: boolean }> = ({ rasgado }) => {
  const { larg: w, alt: h } = PACOTE;
  return (
    <group>
      {/* corpo "estufado": núcleo achatado + elipsoide de ar */}
      <Caixa p={[0, -h / 2, 0]} t={[w, h - 0.04, 0.02]} cor={P.saco} />
      <Bola p={[0, -h / 2, 0]} r={1} cor={P.saco} esc={[w * 0.49, (h - 0.05) * 0.5, 0.03]} />
      {/* faixa laranja embaixo e rótulo vermelho com trevo */}
      <Caixa p={[0, -h + 0.055, 0.016]} t={[w * 0.9, 0.04, 0.012]} cor={P.faixa} />
      <mesh position={[0, -h / 2 + 0.01, 0.029]} rotation={[Math.PI / 2, 0, 0]} material={mat(P.rotulo)} castShadow>
        <cylinderGeometry args={[0.05, 0.05, 0.006, 28]} />
      </mesh>
      <Trevo p={[0, -h / 2 + 0.016, 0.034]} t={0.026} />
      {/* selos serrilhados: embaixo inteiro; em cima só a metade E se rasgado */}
      <Caixa p={[0, -h + 0.0125, 0]} t={[w, 0.025, 0.012]} cor={P.selo} />
      <Caixa p={rasgado ? [-w / 4, -0.0125, 0] : [0, -0.0125, 0]} t={[rasgado ? w / 2 : w, 0.025, 0.012]} cor={P.selo} />
      {rasgado && (
        <group>
          {/* boca aberta escura e salgadinhos aparecendo */}
          <Caixa p={[w / 4, -0.028, 0]} t={[w / 2 - 0.01, 0.012, 0.03]} cor={P.dentro} />
          {[[0.03, -0.018], [0.058, -0.012], [0.075, -0.02]].map(([x, y], i) => (
            <mesh key={i} position={[x, y, 0.004 * i]} rotation={[i, i * 0.7, 0]} material={mat(P.salg)} castShadow>
              <icosahedronGeometry args={[0.013, 0]} />
            </mesh>
          ))}
        </group>
      )}
    </group>
  );
};
/** A tira rasgada da ponta de cima (metade D do selo). Origem no centro da tira. */
export const TiraPacote: React.FC = () => (
  <group>
    <Caixa p={[0, 0, 0]} t={[PACOTE.larg / 2, 0.03, 0.013]} cor={P.selo} />
    <Caixa p={[0, -0.018, 0]} t={[PACOTE.larg / 2 - 0.006, 0.01, 0.016]} cor={P.saco} />
  </group>
);

