// ---------------- Mochila (30 × 40 × 15 cm). Origem no meio das costas de quem usa; o corpo vai para -Z ----------------
const M = { corpo: '#3b6fd6', bolso: '#2a55ad', ziper: '#f2c94c', alca: '#22324f' };
export const Mochila: React.FC = () => (
  <group>
    <Caixa p={[0, -0.03, -0.075]} t={[0.3, 0.3, 0.15]} cor={M.corpo} />
    {/* topo arredondado */}
    <mesh position={[0, 0.12, -0.075]} rotation={[0, 0, Math.PI / 2]} scale={[1, 1, 1.07]} material={mat(M.corpo)} castShadow receiveShadow>
      <cylinderGeometry args={[0.07, 0.07, 0.3, 20]} />
    </mesh>
    {/* bolso da frente com zíper amarelo e puxador */}
    <Caixa p={[0, -0.07, -0.17]} t={[0.22, 0.15, 0.05]} cor={M.bolso} />
    <Caixa p={[0, 0.005, -0.196]} t={[0.2, 0.012, 0.004]} cor={M.ziper} />
    <Caixa p={[0.07, -0.01, -0.199]} t={[0.014, 0.03, 0.006]} cor={M.ziper} />
    {/* alças nos ombros: passam por cima e descem pela frente do peito */}
    {[-1, 1].map((l) => (
      <group key={l}>
        <Caixa p={[0.11 * l, 0.2, 0.09]} t={[0.05, 0.02, 0.2]} cor={M.alca} />
        <Caixa p={[0.11 * l, 0.06, 0.205]} t={[0.05, 0.27, 0.02]} r={[-0.12, 0, 0]} cor={M.alca} />
      </group>
    ))}
  </group>
);
/** Ponto da alça de mão (no topo), no sistema da mochila. */
export const ALCA_MOCHILA: V3 = [0, 0.2, -0.075];

/** Cilindro de a até b (alça esticada, cabo...). */
export const Barra: React.FC<{ a: THREE.Vector3; b: THREE.Vector3; r: number; cor: string }> = ({ a, b, r, cor }) => {
  const d = new THREE.Vector3().subVectors(b, a); const c = new THREE.Vector3().addVectors(a, b).multiplyScalar(0.5);
  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), d.clone().normalize());
  return (
    <mesh position={c} quaternion={q} material={mat(cor)} castShadow>
      <capsuleGeometry args={[r, Math.max(0.001, d.length()), 4, 10]} />
    </mesh>
  );
};

// ---------------- Raspadinha (10 × 15 cm). Origem no centro, frente +Z ----------------
export const Raspadinha: React.FC = () => (
  <group>
    <Caixa p={[0, 0, 0]} t={[0.1, 0.15, 0.003]} cor="#f2b632" />
    <Caixa p={[0, 0.052, 0.002]} t={[0.08, 0.03, 0.002]} cor="#d63a2f" />
    {/* "x2" em traços grossos */}
    <Caixa p={[-0.012, 0.052, 0.0035]} t={[0.004, 0.022, 0.0015]} r={[0, 0, 0.6]} cor="#ffffff" />
    <Caixa p={[-0.012, 0.052, 0.0035]} t={[0.004, 0.022, 0.0015]} r={[0, 0, -0.6]} cor="#ffffff" />
    {[[0.012, 0.06, 0.012, 0.003], [0.018, 0.056, 0.003, 0.008], [0.012, 0.052, 0.012, 0.003], [0.006, 0.048, 0.003, 0.008], [0.012, 0.044, 0.012, 0.003]].map(([x, y, w, hh], i) => (
      <Caixa key={i} p={[x, y, 0.0035]} t={[w, hh, 0.0015]} cor="#ffffff" />
    ))}
    {/* área de raspar: 3 × 2 círculos, 2 já raspados mostrando trevos */}
    {[0, 1, 2, 3, 4, 5].map((i) => {
      const x = -0.03 + (i % 3) * 0.03, y = 0.005 - Math.floor(i / 3) * 0.035;
      const raspado = i === 1 || i === 4;
      return (
        <group key={i} position={[x, y, 0.002]}>
          <mesh rotation={[Math.PI / 2, 0, 0]} material={mat(raspado ? '#fff7dc' : '#b8bec7', raspado ? 0.85 : 0.5)}>
            <cylinderGeometry args={[0.012, 0.012, 0.002, 18]} />
          </mesh>
          {raspado && <Trevo p={[0, 0.002, 0.0015]} t={0.008} />}
        </group>
      );
    })}
  </group>
);

