// Cenário: espaço sideral, sem chão. Fundo azul-marinho chapado (o céu da peça), estrelinhas brancas
// pequenas e nítidas espalhadas por igual, um planeta com anel e uma lua bem longe dos bonecos.
import * as THREE from 'three';
import React, { useLayoutEffect, useMemo, useRef } from 'react';
import { random } from 'remotion';
import type { LimitesCenario } from '../tipos';
import { PlanoFoco, mat } from './base';

export const LIMITES_ESPACO: LimitesCenario = { limiteX: 1.5, limiteZ: [-1.0, 3.0], ceu: '#172a5c' };

// estrelas numa casca de raio R em volta da origem; 1 px da vitrine (fov 40, 1080 p) a 40 m ≈ 2,7 cm
const R = 40, N = 2600;
const geoEstrela = new THREE.IcosahedronGeometry(1, 1);
const matEstrela = mat('#ffffff', { brilho: 1.2 });

/** Céu de estrelas: distribuição de Fibonacci na esfera (uniforme, sem aglomerados) com um leve sorteio.
 *  Raio de 3,2 a 4,8 cm: 2 a 3,5 px de diâmetro. Uma malha instanciada só (leve). */
const Estrelas: React.FC = () => {
  const ref = useRef<THREE.InstancedMesh>(null);
  const matrizes = useMemo(() => {
    const m = new THREE.Matrix4(), out: THREE.Matrix4[] = [];
    const ouro = Math.PI * (3 - Math.sqrt(5));
    for (let i = 0; i < N; i++) {
      const a = (k: string) => random(`r01-estrela-${i}-${k}`);
      const y = 1 - ((i + 0.5 + (a('y') - 0.5) * 0.8) / N) * 2;
      const raio = Math.sqrt(Math.max(0, 1 - y * y)), th = i * ouro + (a('t') - 0.5) * 0.04;
      const r = 0.032 + a('r') * 0.016;
      m.compose(new THREE.Vector3(Math.cos(th) * raio * R, y * R, Math.sin(th) * raio * R), new THREE.Quaternion(), new THREE.Vector3(r, r, r));
      out.push(m.clone());
    }
    return out;
  }, []);
  useLayoutEffect(() => {
    const im = ref.current; if (!im) return;
    matrizes.forEach((mm, i) => im.setMatrixAt(i, mm));
    im.instanceMatrix.needsUpdate = true;
    im.computeBoundingSphere();
  }, [matrizes]);
  return <instancedMesh ref={ref} args={[geoEstrela, matEstrela, N]} frustumCulled={false} />;
};

/** Planeta chapado com anel, bem ao fundo (alto e à esquerda). */
const Planeta: React.FC = () => (
  <group position={[-9.5, 6.2, -24]} rotation={[0.35, 0, 0.3]}>
    <mesh material={mat('#e98b5a')} receiveShadow><sphereGeometry args={[2.4, 40, 24]} /></mesh>
    {/* faixa mais escura: esfera achatada 2 cm maior que o planeta */}
    <mesh scale={[1, 0.3, 1]} material={mat('#c9653e')}><sphereGeometry args={[2.42, 40, 16]} /></mesh>
    <mesh rotation={[Math.PI / 2, 0, 0]} scale={[1, 1, 0.12]} material={mat('#f2d6a2')}><torusGeometry args={[3.6, 0.42, 4, 64]} /></mesh>
  </group>
);

export const Espaco: React.FC = () => (
  <group>
    {/* foco: tudo atrás de z = 0 é desfocado como se estivesse no plano dos bonecos (estrelas nítidas) */}
    <PlanoFoco z={0} />
    <Estrelas />
    <Planeta />
    {/* lua pequena, à direita e longe */}
    <mesh position={[11, 4.2, -30]} material={mat('#d9dde6', { flat: true })}><icosahedronGeometry args={[1.0, 1]} /></mesh>
    {/* luz de recorte azulada por trás e preenchimento frio: separam os bonecos (roupas escuras) do fundo */}
    <directionalLight color="#a9c8ff" intensity={2.6} position={[2, 4, -6]} />
    <directionalLight color="#8fa6e8" intensity={0.5} position={[-3, 1, 5]} />
  </group>
);
