// Base do lote r09-efeito: cache de material por cor (padrão do Quadra.tsx), halo suave e utilitários comuns.
import * as THREE from 'three';
import React, { useMemo } from 'react';

export type V3 = [number, number, number];
export const TAU = Math.PI * 2;

const cache = new Map<string, THREE.MeshStandardMaterial>();
/** Material chapado (roughness 0,85). `brilho` > 0 acende a cor (emissivo). Valores arredondados para o cache não crescer. */
export const mat = (cor: string, brilho = 0, rug = 0.85) => {
  const b = Math.round(brilho * 20) / 20;
  const k = `${cor}|${b}|${rug}`;
  let m = cache.get(k);
  if (!m) {
    m = new THREE.MeshStandardMaterial({ color: cor, roughness: rug });
    if (b > 0) { m.emissive = new THREE.Color(cor); m.emissiveIntensity = b; }
    cache.set(k, m);
  }
  return m;
};

/** Suaviza 0..1 (smoothstep). */
export const suave = (t: number) => { const x = Math.min(1, Math.max(0, t)); return x * x * (3 - 2 * x); };

/** Disco de halo: degradê radial por cor de vértice (centro aceso, borda preta = invisível no aditivo). Raio 1. */
const geoHalo = (() => {
  const g = new THREE.CircleGeometry(1, 32, 0, TAU);
  const pos = g.attributes.position, cor = new Float32Array(pos.count * 3);
  for (let i = 0; i < pos.count; i++) {
    const r = Math.hypot(pos.getX(i), pos.getY(i));
    const k = Math.pow(Math.max(0, 1 - r), 2.2);
    cor[i * 3] = cor[i * 3 + 1] = cor[i * 3 + 2] = k;
  }
  g.setAttribute('color', new THREE.BufferAttribute(cor, 3));
  return g;
})();

/** Halo aditivo de cor `cor`, raio `raio`, força `forca` 0..1 (vira a opacidade). Não projeta nem recebe sombra. */
export const Halo: React.FC<{ cor: string; raio: number; forca: number; z?: number }> = ({ cor, raio, forca, z = -0.005 }) => {
  const m = useMemo(() => new THREE.MeshBasicMaterial({
    color: cor, vertexColors: true, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
  }), [cor]);
  m.opacity = Math.max(0, Math.min(1, forca));
  return <mesh position={[0, 0, z]} scale={raio} geometry={geoHalo} material={m} />;
};
