// Cozinha aberta para +Z. Mobiliário em metros, piso em y=0.
import React from 'react';
import * as THREE from 'three';
import { Caixa, Haste, mat, type V3 } from './base';

const C = {
  piso: '#eee3cd', parede: '#fff8e8', rejunte: '#fffdf5', azulejo: '#F2C94C',
  branco: '#ffffff', corpo: '#e5e8e3', puxador: '#386d70', bancada: '#e6e0ce',
  cuba: '#416779', inox: '#b5cbd1', madeira: '#b7753e', madeiraClara: '#e1ac70',
  ceu: '#8edaff', sol: '#ffd33d', fogao: '#344651', vidro: '#557c91', acento: '#e77d55',
};

const Azulejos: React.FC = () => (
  <group>
    {/* Grade única de 48 cm; a janela ocupa seis colunas e três linhas. */}
    {Array.from({ length: 12 }, (_, coluna) =>
      Array.from({ length: 4 }, (_, linha) => {
        if (coluna >= 5 && coluna <= 10 && linha >= 1) return null;
        return <Caixa key={`${coluna}-${linha}`} p={[-1.74 + coluna * 0.48, 1.16 + linha * 0.48, -3.65]}
          t={[0.4, 0.4, 0.08]} cor={C.azulejo} sombra={false} recebeSombra={false} />;
      }),
    )}
  </group>
);

const Janela: React.FC = () => (
  <group>
    {/* Uma janela inteira, sem vidro escuro nem sombra sobre o céu. */}
    <Caixa p={[1.86, 2.12, -3.95]} t={[2.88, 1.44, 0.08]} cor={C.ceu} sombra={false} recebeSombra={false} />
    <mesh position={[2.68, 2.48, -3.82]} rotation={[Math.PI / 2, 0, 0]} material={mat(C.sol)}>
      <cylinderGeometry args={[0.23, 0.23, 0.08, 32]} />
    </mesh>
    {[0.42, 3.3].map((x) => <Caixa key={x} p={[x, 2.12, -3.59]} t={[0.12, 1.56, 0.16]} cor={C.branco} sombra={false} recebeSombra={false} />)}
    {[1.4, 2.84].map((y) => <Caixa key={y} p={[1.86, y, -3.59]} t={[2.76, 0.12, 0.16]} cor={C.branco} sombra={false} recebeSombra={false} />)}
    <Caixa p={[1.86, 2.12, -3.59]} t={[0.12, 1.32, 0.16]} cor={C.branco} sombra={false} recebeSombra={false} />
    <Caixa p={[1.86, 2.15, -3.39]} t={[2.76, 0.12, 0.16]} cor={C.branco} sombra={false} recebeSombra={false} />
    <Caixa p={[1.86, 1.3, -3.44]} t={[3.12, 0.12, 0.4]} cor={C.branco} />
  </group>
);

const Armario: React.FC<{ x: number; alto?: boolean }> = ({ x, alto = false }) => {
  const y = alto ? 2.26 : 0.47;
  const altura = alto ? 1 : 0.7;
  const z = alto ? -3.28 : -3.17;
  return (
    <group>
      <Caixa p={[x, y, z]} t={[0.74, altura, alto ? 0.44 : 0.72]} cor={C.corpo} />
      <Caixa p={[x, y, alto ? -2.98 : -2.71]} t={[0.68, altura - 0.08, 0.08]} cor={C.branco} sombra={false} recebeSombra={false} />
      <Caixa p={[x + (alto ? 0.21 : 0), alto ? y - 0.28 : 0.66, alto ? -2.88 : -2.61]}
        t={alto ? [0.08, 0.22, 0.08] : [0.26, 0.08, 0.08]} cor={C.puxador} />
    </group>
  );
};

const Pia: React.FC = () => (
  <group position={[2.85, 0, -1.92]}>
    {/* Retorno em L, fora da silhueta da Bia. Tampo a 90 cm. */}
    <Caixa p={[0, 0.12, -0.25]} t={[1.08, 0.24, 2.5]} cor={C.puxador} />
    <Caixa p={[0, 0.45, -0.25]} t={[1.18, 0.62, 2.5]} cor={C.corpo} />
    <Caixa p={[0, 0.48, 1.06]} t={[1.1, 0.64, 0.08]} cor={C.branco} sombra={false} recebeSombra={false} />
    <Caixa p={[0, 0.67, 1.16]} t={[0.32, 0.08, 0.08]} cor={C.puxador} />
    {/* Quatro bordas deixam uma cuba retangular realmente rebaixada. */}
    {[-0.54, 0.54].map((x) => <Caixa key={x} p={[x, 0.84, 0]} t={[0.22, 0.12, 1.42]} cor={C.bancada} />)}
    {[-0.6, 0.6].map((z) => <Caixa key={z} p={[0, 0.84, z]} t={[0.86, 0.12, 0.22]} cor={C.inox} />)}
    {[-0.39, 0.39].map((x) => <Caixa key={x} p={[x, 0.82, 0]} t={[0.08, 0.16, 0.98]} cor={C.inox} />)}
    <Caixa p={[0, 0.76, 0]} t={[0.7, 0.08, 0.98]} cor={C.cuba} sombra={false} />
    <Caixa p={[0, 0.84, -1.21]} t={[1.3, 0.12, 1]} cor={C.bancada} />
    <Caixa p={[0, 0.84, 0.91]} t={[1.3, 0.12, 0.4]} cor={C.bancada} />
    {/* Base encostada no tampo; bica grossa apontada para a cuba. */}
    <Haste a={[0.2, 0.88, -0.6]} b={[0.2, 0.98, -0.6]} r={0.09} cor={C.inox} />
    <Haste a={[0.2, 0.96, -0.6]} b={[0.2, 1.27, -0.6]} r={0.05} cor={C.puxador} />
    <Haste a={[0.2, 1.27, -0.6]} b={[0.2, 1.27, -0.18]} r={0.05} cor={C.puxador} />
    <Haste a={[0.2, 1.27, -0.18]} b={[0.2, 1.16, -0.18]} r={0.05} cor={C.puxador} />
  </group>
);

const Eletrodomesticos: React.FC = () => (
  <group>
    {/* Geladeira compacta, com duas portas e puxadores contrastantes. */}
    <Caixa p={[-3.42, 1, -3.16]} t={[0.82, 2, 0.84]} cor={C.corpo} />
    {[[0.63, 1.1], [1.6, 0.68]].map(([y, altura]) => (
      <group key={y}>
        <Caixa p={[-3.42, y, -2.64]} t={[0.76, altura, 0.12]} cor={C.branco} sombra={false} recebeSombra={false} />
        <Caixa p={[-3.16, y + 0.08, -2.48]} t={[0.08, 0.3, 0.12]} cor={C.puxador} />
      </group>
    ))}
    {/* Fogão de quatro bocas e forno azul, ao lado dos armários. */}
    <Caixa p={[-2.5, 0.43, -3.17]} t={[0.76, 0.86, 0.8]} cor={C.branco} />
    <Caixa p={[-2.5, 0.86, -3.17]} t={[0.8, 0.08, 0.84]} cor={C.fogao} />
    {[-1, 1].map((x) => [-1, 1].map((z) => (
      <mesh key={`${x}-${z}`} position={[-2.5 + x * 0.21, 0.94, -3.17 + z * 0.22]} material={mat(C.inox)} castShadow receiveShadow>
        <cylinderGeometry args={[0.12, 0.12, 0.08, 16]} />
      </mesh>
    )))}
    <Caixa p={[-2.5, 0.4, -2.69]} t={[0.54, 0.38, 0.08]} cor={C.vidro} sombra={false} recebeSombra={false} />
    <Caixa p={[-2.5, 0.66, -2.59]} t={[0.5, 0.08, 0.08]} cor={C.puxador} />
  </group>
);

const Cadeira: React.FC<{ p: V3; giro: number }> = ({ p, giro }) => (
  <group position={p} rotation={[0, giro, 0]}>
    {/* Topo do assento a 45 cm. */}
    <Caixa p={[0, 0.4, 0]} t={[0.48, 0.1, 0.48]} cor={C.madeiraClara} />
    {[-1, 1].map((lado) => (
      <group key={lado}>
        <Caixa p={[lado * 0.18, 0.175, 0.18]} t={[0.08, 0.35, 0.08]} cor={C.madeira} />
        <Caixa p={[lado * 0.18, 0.47, -0.18]} t={[0.08, 0.94, 0.08]} cor={C.madeira} />
      </group>
    ))}
    <Caixa p={[0, 0.8, -0.23]} t={[0.5, 0.28, 0.1]} cor={C.madeiraClara} />
  </group>
);

const Mesa: React.FC = () => (
  <group position={[-2.55, 0, -0.7]}>
    {/* Cadeiras nos extremos em Z: ambas à esquerda dos personagens. */}
    <Caixa p={[0, 0.7, 0]} t={[1.05, 0.1, 0.92]} cor={C.madeiraClara} />
    {[-1, 1].map((x) => [-1, 1].map((z) => (
      <Caixa key={`${x}-${z}`} p={[x * 0.4, 0.325, z * 0.34]} t={[0.1, 0.65, 0.1]} cor={C.madeira} />
    )))}
    <Caixa p={[0, 0.59, 0]} t={[0.9, 0.12, 0.74]} cor={C.madeira} />
    <Cadeira p={[-0.1, 0, -0.86]} giro={0} />
    <Cadeira p={[0, 0, 0.86]} giro={Math.PI} />
    <mesh position={[0, 0.8, 0]} material={mat(C.acento)} castShadow receiveShadow>
      <cylinderGeometry args={[0.18, 0.12, 0.1, 24]} />
    </mesh>
  </group>
);

const alvoManha = new THREE.Object3D();
alvoManha.position.set(1.95, 0, -0.55);

export const Cozinha: React.FC = () => (
  <group>
    <Caixa p={[0, -0.08, 1]} t={[14, 0.16, 18]} cor={C.piso} sombra={false} />
    {/* Sem teto; laterais curtas deixam o sol do palco entrar. */}
    <Caixa p={[0, 0.7, -3.85]} t={[8.2, 1.4, 0.2]} cor={C.rejunte} sombra={false} />
    <Caixa p={[0, 3.08, -3.85]} t={[8.2, 0.48, 0.2]} cor={C.parede} sombra={false} />
    <Caixa p={[-1.84, 2.12, -3.85]} t={[4.52, 1.44, 0.2]} cor={C.rejunte} sombra={false} />
    <Caixa p={[3.7, 2.12, -3.85]} t={[0.8, 1.44, 0.2]} cor={C.rejunte} sombra={false} />
    {[-4.1, 4.1].map((x) => <Caixa key={x} p={[x, 1.66, -3.12]} t={[0.2, 3.32, 1.66]} cor={C.parede} sombra={false} />)}
    <Azulejos />
    <Janela />
    {[-1.66, -0.88, -0.1, 0.68, 1.46].map((x) => <Armario key={x} x={x} />)}
    {[-1.74, -0.96, -0.18].map((x) => <Armario key={x} x={x} alto />)}
    <Caixa p={[-0.1, 0.84, -3.17]} t={[3.86, 0.12, 0.92]} cor={C.bancada} />
    <Caixa p={[-0.1, 0.1, -3.17]} t={[3.86, 0.2, 0.7]} cor={C.puxador} />
    <Caixa p={[2.015, 0.84, -3.17]} t={[0.37, 0.12, 0.92]} cor={C.bancada} />
    <Caixa p={[2.015, 0.47, -3.17]} t={[0.37, 0.62, 0.72]} cor={C.corpo} />
    <Pia />
    <Eletrodomesticos />
    <Mesa />
    {/* Tapete só na área lateral, com topo separado do piso por 8 cm. */}
    <Caixa p={[2.9, 0.04, -0.25]} t={[1.22, 0.08, 0.66]} cor={C.acento} sombra={false} />
    <ambientLight color="#fff1d9" intensity={0.45} />
    {/* Luz quente no piso; mesma direção geral do sol do palco, sem outra sombra. */}
    <primitive object={alvoManha} />
    <spotLight position={[4.3, 4.7, 2.27]} target={alvoManha} color="#ffe3a2" intensity={36}
      angle={0.29} penumbra={0.85} distance={12} decay={2} />
  </group>
);
