import React from 'react';

export const HudContador: React.FC<{ quadro: number; rotulo: string; valor: string }> = ({ quadro, rotulo, valor }) => {
  const progresso = Math.min(1, Math.max(0, quadro / 10));
  const entrada = 1 - (1 - progresso) ** 3;
  return (
    <div style={{
      position: 'absolute', top: 48, left: 48, maxWidth: 1824,
      color: '#fff', fontFamily: "'Inter', 'Segoe UI', Arial, sans-serif",
      opacity: entrada, transform: `translateX(${(1 - entrada) * -28}px)`,
      textShadow: '0 2px 8px rgba(16, 30, 40, 0.45)', pointerEvents: 'none',
    }}>
      <div style={{ fontSize: 23, fontWeight: 650, letterSpacing: '0.19em', lineHeight: 1.3, textTransform: 'uppercase', marginBottom: 7 }}>{rotulo}</div>
      <div style={{ fontSize: 62, fontWeight: 750, lineHeight: 1.1, letterSpacing: '-0.035em', fontVariantNumeric: 'tabular-nums' }}>{valor}</div>
    </div>
  );
};
