// Cartão de 6 × 9 cm em um pequeno apoio, com estrela e reflexos luminosos.
import React from 'react';
import * as THREE from 'three';
import { Caixa, mat, type V2, type V3 } from './base';

const OURO = '#f2c230', BORDA = '#d99c16', CLARO = '#ffe99a', BRANCO = '#ffffff';
const D = 0.002, R = 0.003, MEIO = 0.027;
const INCLINACAO = -Math.PI / 7;
const ESTRELA: V2[] = Array.from({ length: 10 }, (_, i) => {
  const angulo = Math.PI / 2 + i * Math.PI / 5;
  const raio = i % 2 === 0 ? 0.03 : 0.013;
  return [Math.cos(angulo) * raio * 0.91, Math.sin(angulo) * raio];
});
const YMIN = Math.min(...ESTRELA.map((p) => p[1]));
const YMAX = Math.max(...ESTRELA.map((p) => p[1]));
const cache = new Map<string, THREE.MeshStandardMaterial>();
const metal = (cor: string) => {
  let material = cache.get(cor);
  if (!material) {
    // Exceção do metal polido: reflexo especular + cor viva sem luz adicional.
    const branco = cor === BRANCO;
    material = new THREE.MeshStandardMaterial({
      color: cor, metalness: branco ? 0 : 0.68, roughness: branco ? 0.85 : 0.27,
      emissive: cor, emissiveIntensity: branco ? 0.85 : 0.28,
    });
    cache.set(cor, material);
  }
  return material;
};

const Faixa: React.FC<{ p: V3; t: V3; cor: string }> = ({ p, t, cor }) => (
  <mesh position={p} material={metal(cor)} castShadow receiveShadow><boxGeometry args={t} /></mesh>
);

// Estrela com 60% da altura: branco e ouro ocupam a mesma lâmina, sem decal.
const Miolo: React.FC = () => {
  const faixa = (YMAX - YMIN) / 48;
  return (
    <group position={[0, 0.045, 0]}>
      <Faixa p={[0, (0.045 + YMAX) / 2, 0]} t={[2 * MEIO, 0.045 - YMAX, D]} cor={OURO} />
      <Faixa p={[0, (-0.045 + YMIN) / 2, 0]} t={[2 * MEIO, 0.045 + YMIN, D]} cor={OURO} />
      {Array.from({ length: 48 }, (_, i) => {
        const y = YMIN + (i + 0.5) * faixa;
        const cortes: number[] = [-MEIO, MEIO];
        ESTRELA.forEach((a, j) => {
          const b = ESTRELA[(j + 1) % ESTRELA.length];
          if ((a[1] <= y && b[1] > y) || (b[1] <= y && a[1] > y)) {
            cortes.push(a[0] + (y - a[1]) * (b[0] - a[0]) / (b[1] - a[1]));
          }
        });
        cortes.sort((a, b) => a - b);
        return cortes.slice(1).map((fim, j) => (
          <Faixa key={`${i}-${j}`} p={[(cortes[j] + fim) / 2, y, 0]}
            t={[fim - cortes[j], faixa, D]} cor={j % 2 === 0 ? OURO : BRANCO} />
        ));
      })}
    </group>
  );
};

const Reflexo: React.FC<{ p: V3; tamanho: number }> = ({ p, tamanho }) => (
  <group position={p}>
    <mesh scale={[tamanho, tamanho * 0.22, tamanho * 0.12]} material={mat('#fff8d5', { brilho: 1.3 })}>
      <icosahedronGeometry args={[1, 0]} />
    </mesh>
    <mesh scale={[tamanho * 0.22, tamanho, tamanho * 0.12]} material={mat('#fff8d5', { brilho: 1.3 })}>
      <icosahedronGeometry args={[1, 0]} />
    </mesh>
  </group>
);

export const FigurinhaDourada: React.FC = () => (
  <group position={[0, 0, 0.16]}>
    {/* Base, batente e encosto pertencem ao suporte do próprio cartão. */}
    <Caixa p={[0, 0.003, -0.012]} t={[0.054, 0.006, 0.048]} cor="#6c541e" />
    <Caixa p={[0, 0.008, 0.004]} t={[0.044, 0.004, 0.006]} cor={CLARO} />
    {([-1, 1] as const).map((lado) => (
      <mesh key={lado} position={[lado * 0.02, 0.026, -0.022]} rotation={[0.29, 0, 0]} material={mat('#6c541e')} castShadow receiveShadow>
        <boxGeometry args={[0.004, 0.043, 0.005]} />
      </mesh>
    ))}
    <group position={[0, 0.006 + D / 2 * Math.sin(-INCLINACAO), 0]} rotation={[INCLINACAO, 0, 0]}>
      <Miolo />
      <Faixa p={[-0.0285, 0.045, 0]} t={[R, 0.084, D]} cor={BORDA} />
      <Faixa p={[0.0285, 0.045, 0]} t={[R, 0.084, D]} cor={CLARO} />
      {([[1, 1], [1, -1], [-1, -1], [-1, 1]] as const).map(([x, y], i) => (
        <mesh key={i} position={[x * MEIO, 0.045 + y * 0.042, 0]}
          rotation={[-Math.PI / 2, 0, 0]} material={metal(x < 0 ? BORDA : CLARO)} castShadow receiveShadow>
          <cylinderGeometry args={[R, R, D, 10, 1, false, i * Math.PI / 2, Math.PI / 2]} />
        </mesh>
      ))}
      {/* Pontos de brilho separados da face por mais de 2 cm. */}
      <Reflexo p={[-0.028, 0.078, 0.025]} tamanho={0.009} />
      <Reflexo p={[0.027, 0.019, 0.025]} tamanho={0.006} />
    </group>
  </group>
);
