// Volante de loteria gigante: painel verde de 6 m (origem no centro da base, frente +Z), cabeçalho com trevo,
// grade 01–60 em círculos brancos (6 marcados de azul-caneta) e o prêmio 50.063.860 dourado flutuando acima.
// Os 120 dígitos da grade são 7 segmentos em InstancedMesh (2 draw calls); o resto são caixas e discos.
import * as THREE from 'three';
import React, { useLayoutEffect, useMemo, useRef } from 'react';
import { Caixa, Cil, mat, segmentos, type V3 } from './base';

const VERDE = '#2f9c58', VERDE_CLARO = '#46b56d', VERDE_ESC = '#1d6a3b', BRANCO = '#fbfbf5', CANETA = '#2b3f93', OURO = '#f7c63c', OURO_ESC = '#c98d1d';
export const VOLANTE = { larg: 3.6, alt: 6.0, esp: 0.2, premioY: 6.75 };
const MARCADOS = new Set([7, 18, 23, 36, 44, 59]);

// grade: 6 colunas x 10 linhas, passo 0,45 m, círculos de 38 cm, dígitos de 23 x 12,5 cm com traço de 4,5 cm
const COLS = 6, LINS = 10, PASSO = 0.45, R_CIRC = 0.19, GRADE_Y = 2.95; // centro da grade (0,7 a 5,2 m)
const DIG = { w: 0.125, h: 0.23, s: 0.045, vao: 0.03 };
const ZF = VOLANTE.esp / 2 + 0.03; // frente do painel claro

type Seg = [number, number, number, number]; // x, y, largura, altura
/** Segmentos (no mundo do painel) dos números da grade, separados em "tinta verde" e "tinta branca" (marcados). */
function segsGrade(): { verde: Seg[]; branco: Seg[]; centros: { x: number; y: number; marcado: boolean }[] } {
  const verde: Seg[] = [], branco: Seg[] = [], centros: { x: number; y: number; marcado: boolean }[] = [];
  for (let n = 1; n <= 60; n++) {
    const c = (n - 1) % COLS, l = Math.floor((n - 1) / COLS);
    const x = (c - (COLS - 1) / 2) * PASSO, y = GRADE_Y + ((LINS - 1) / 2 - l) * PASSO;
    const marcado = MARCADOS.has(n);
    centros.push({ x, y, marcado });
    const txt = String(n).padStart(2, '0');
    [...txt].forEach((d, i) => {
      const dx = (i - 0.5) * (DIG.w + DIG.vao);
      for (const [sx, sy, sw, sh] of segmentos(d, DIG.w, DIG.h, DIG.s)) (marcado ? branco : verde).push([x + dx + sx, y + sy, sw, sh]);
    });
  }
  return { verde, branco, centros };
}

const geoSeg = new THREE.BoxGeometry(1, 1, 1);
/** Todos os traços de uma cor num InstancedMesh (caixa de 1 m escalada por instância). */
const Tracos: React.FC<{ segs: Seg[]; z: number; prof: number; cor: string }> = ({ segs, z, prof, cor }) => {
  const ref = useRef<THREE.InstancedMesh>(null);
  useLayoutEffect(() => {
    const im = ref.current; if (!im) return;
    const m = new THREE.Matrix4();
    segs.forEach(([x, y, w, h], i) => { m.makeScale(w, h, prof).setPosition(x, y, z); im.setMatrixAt(i, m); });
    im.instanceMatrix.needsUpdate = true;
    im.computeBoundingSphere();
  }, [segs, z, prof]);
  return <instancedMesh ref={ref} args={[geoSeg, mat(cor, 0.8), segs.length]} receiveShadow frustumCulled={false} />;
};

/** Trevo de 4 folhas (discos) num disco branco. */
const Trevo: React.FC<{ p: V3 }> = ({ p }) => (
  <group position={p}>
    <Cil p={[0, 0, 0]} raio={0.3} h={0.04} cor={BRANCO} r={[Math.PI / 2, 0, 0]} sombra={false} />
    {[[0, 1], [1, 0], [0, -1], [-1, 0]].map(([a, b], i) => (
      <Cil key={i} p={[a * 0.095, b * 0.095 + 0.02, 0.03]} raio={0.1} h={0.03} cor={VERDE} r={[Math.PI / 2, 0, 0]} sombra={false} />
    ))}
    <Caixa p={[0.05, -0.15, 0.03]} t={[0.05, 0.16, 0.03]} r={[0, 0, 0.45]} cor={VERDE} sombra={false} />
  </group>
);

/** Prêmio "50.063.860": dígitos dourados com uma borda ouro-escuro 2 cm maior atrás (dá contorno sem linha preta). */
const Premio: React.FC = () => {
  const w = 0.34, h = 0.6, s = 0.1, vao = 0.1, ponto = 0.12;
  const itens: { t: string; larg: number }[] = [...'50.063.860'].map((t) => ({ t, larg: t === '.' ? ponto : w }));
  const total = itens.reduce((a, it) => a + it.larg, 0) + vao * (itens.length - 1);
  let x = -total / 2;
  const frente: Seg[] = [], borda: Seg[] = [];
  for (const it of itens) {
    const cx = x + it.larg / 2;
    const segs: Seg[] = it.t === '.' ? [[0, -h / 2 + ponto / 2, ponto, ponto]] : segmentos(it.t, w, h, s);
    for (const [sx, sy, sw, sh] of segs) { frente.push([cx + sx, sy, sw, sh]); borda.push([cx + sx, sy, sw + 0.05, sh + 0.05]); }
    x += it.larg + vao;
  }
  return (
    <group position={[0, VOLANTE.premioY, 0]}>
      {frente.map(([sx, sy, sw, sh], i) => <Caixa key={`f${i}`} p={[sx, sy, 0.03]} t={[sw, sh, 0.08]} cor={OURO} m={mat(OURO, 0.6, 0.35)} />)}
      {borda.map(([sx, sy, sw, sh], i) => <Caixa key={`b${i}`} p={[sx, sy, -0.03]} t={[sw, sh, 0.08]} cor={OURO_ESC} sombra={false} />)}
    </group>
  );
};

export const VolanteGigante: React.FC = () => {
  const { larg: L, alt: A, esp: E } = VOLANTE, rc = 0.2, base = 0.3;
  const grade = useMemo(segsGrade, []);
  const hp = A - base; // painel de 0,3 a 6,0 m
  const yp = base + hp / 2;
  return (
    <group>
      {/* base escura e dois escoras atrás */}
      <Caixa p={[0, base / 2, -0.05]} t={[L + 0.3, base, 0.8]} cor={VERDE_ESC} />
      {[-1, 1].map((l) => <Caixa key={l} p={[l * 1.2, 1.6, -0.75]} t={[0.18, 3.4, 0.18]} r={[-0.36, 0, 0]} cor={VERDE_ESC} />)}
      {/* painel com cantos arredondados (duas caixas em cruz + 4 cilindros) */}
      <Caixa p={[0, yp, 0]} t={[L - 2 * rc, hp, E]} cor={VERDE} />
      <Caixa p={[0, yp, 0]} t={[L, hp - 2 * rc, E]} cor={VERDE} />
      {[[-1, -1], [-1, 1], [1, -1], [1, 1]].map(([sx, sy], i) => (
        <Cil key={i} p={[sx * (L / 2 - rc), yp + sy * (hp / 2 - rc), 0]} raio={rc} h={E} cor={VERDE} r={[Math.PI / 2, 0, 0]} />
      ))}
      {/* área da grade, um verde mais claro (3 cm à frente) */}
      <Caixa p={[0, GRADE_Y, E / 2]} t={[COLS * PASSO + 0.14, LINS * PASSO + 0.14, 0.06]} cor={VERDE_CLARO} sombra={false} />
      {/* cabeçalho: faixa escura, trevo e título em traços brancos */}
      <Caixa p={[0, 5.6, E / 2]} t={[L - 0.3, 0.62, 0.06]} cor={VERDE_ESC} sombra={false} />
      <Trevo p={[-1.22, 5.6, ZF + 0.01]} />
      <Caixa p={[0.3, 5.7, ZF + 0.01]} t={[2.0, 0.16, 0.03]} cor={BRANCO} sombra={false} />
      <Caixa p={[-0.05, 5.48, ZF + 0.01]} t={[1.3, 0.1, 0.03]} cor={BRANCO} sombra={false} />
      <Caixa p={[1.05, 5.48, ZF + 0.01]} t={[0.5, 0.1, 0.03]} cor={OURO} sombra={false} />
      {/* círculos: brancos (livres) ou azul-caneta (marcados) */}
      {grade.centros.map(({ x, y, marcado }, i) => (
        <Cil key={i} p={[x, y, ZF + 0.015]} raio={R_CIRC} h={0.03} cor={marcado ? CANETA : BRANCO} lados={40} r={[Math.PI / 2, 0, 0]} sombra={false} />
      ))}
      <Tracos segs={grade.verde} z={ZF + 0.035} prof={0.02} cor={VERDE_ESC} />
      <Tracos segs={grade.branco} z={ZF + 0.035} prof={0.02} cor={BRANCO} />
      {/* rodapé: fileira de quadradinhos brancos (campo de "quantos números") */}
      {Array.from({ length: 7 }, (_, i) => (
        <Caixa key={i} p={[(i - 3) * 0.4, 0.42 + 0.05, E / 2 + 0.01]} t={[0.24, 0.16, 0.04]} cor={i === 0 ? CANETA : BRANCO} sombra={false} />
      ))}
      <Premio />
    </group>
  );
};
