// Balcão de 2,10 × 0,70 m, tampo a 1 m. Frente para +Z.
import React from 'react';
import { Caixa, Esfera, Tampo, mat, type V3 } from './base';

const C = {
  madeira: '#efc58d', borda: '#cb965d', rodape: '#94633d',
  vidro: '#c5edff', aro: '#e1f4f9', bandeja: '#f4dfb8', fundo: '#fff1d5',
  pao: '#efa52e',
};
const CORES_BALAS = ['#ff354f', '#ffd21e', '#13cf78', '#2878ff', '#c33dff'];

// Pão inteiro em uma elipsoide dourada, sem tampinhas ou peças soltas.
const Pao: React.FC<{ p: V3 }> = ({ p }) => (
  <Esfera p={[p[0], p[1] + 0.055, p[2]]} r={0.1} escala={[0.8, 0.55, 1.25]} cor={C.pao} brilho={0.18} />
);

const BandejaPaes: React.FC = () => (
  <group>
    <Tampo p={[0, 0.02, 0]} t={[0.94, 0.04, 0.4]} raio={0.04} cor={C.bandeja} />
    {[-1, 1].map((lado) => (
      <Caixa key={lado} p={[0, 0.06, lado * 0.18]} t={[0.86, 0.04, 0.04]} cor={C.bandeja} />
    ))}
    {[-1, 1].map((lado) => (
      <Caixa key={lado} p={[lado * 0.45, 0.06, 0]} t={[0.04, 0.04, 0.28]} cor={C.bandeja} />
    ))}
    {[-0.315, -0.105, 0.105, 0.315].map((x) => <Pao key={x} p={[x, 0.04, 0]} />)}
  </group>
);

const PoteBalas: React.FC = () => (
  <group>
    <mesh position={[0, 0.02, 0]} material={mat(C.aro)} castShadow receiveShadow>
      <cylinderGeometry args={[0.18, 0.17, 0.04, 24]} />
    </mesh>
    {/* Balas de 8 cm em quatro níveis fixos. */}
    {[0, 1, 2, 3].flatMap((nivel) => Array.from({ length: 7 }, (_, i) => {
      const angulo = (i / 6) * Math.PI * 2 + nivel * 0.45;
      const raio = i === 6 ? 0 : 0.10;
      return <Esfera key={`${nivel}:${i}`} p={[raio * Math.cos(angulo), 0.08 + nivel * 0.075, raio * Math.sin(angulo)]}
        r={0.04} cor={CORES_BALAS[(nivel * 2 + i) % CORES_BALAS.length]} brilho={0.18} />;
    }))}
    <mesh position={[0, 0.20, 0]} material={mat(C.vidro, 0.26)}>
      <cylinderGeometry args={[0.17, 0.17, 0.32, 24, 1, true]} />
    </mesh>
    <mesh position={[0, 0.36, 0]} rotation={[Math.PI / 2, 0, 0]} material={mat(C.aro)} castShadow receiveShadow>
      <torusGeometry args={[0.17, 0.016, 8, 24]} />
    </mesh>
    <mesh position={[0, 0.39, 0]} material={mat(C.aro)} castShadow receiveShadow>
      <cylinderGeometry args={[0.185, 0.185, 0.03, 24]} />
    </mesh>
    <Esfera p={[0, 0.43, 0]} r={0.035} escala={[1, 0.8, 1]} cor={C.borda} />
  </group>
);

export const BalcaoPadaria: React.FC = () => (
  <group>
    <Tampo p={[0, 0.04, 0]} t={[1.98, 0.08, 0.6]} raio={0.04} cor={C.rodape} />
    <Tampo p={[0, 0.35, 0]} t={[2.02, 0.54, 0.64]} raio={0.04} cor={C.madeira} />
    {/* Prateleira única clara, sem ripas frontais nem vão escuro entre bandejas. */}
    <Caixa p={[0, 0.66, 0]} t={[2.02, 0.08, 0.64]} cor={C.bandeja} />
    {/* Costas da própria vitrine impedem ver a quadra através do vidro. */}
    <Caixa p={[0, 0.83, -0.28]} t={[1.94, 0.26, 0.08]} cor={C.fundo} />
    {[-0.97, 0.97].flatMap((x) => [-0.28, 0.28].map((z) => (
      <Caixa key={`${x}:${z}`} p={[x, 0.83, z]} t={[0.08, 0.26, 0.08]} cor={C.borda} />
    )))}
    <Caixa p={[0, 0.83, 0.29]} t={[1.86, 0.26, 0.02]} cor={C.vidro} opacidade={0.32} />
    {[-0.97, 0.97].map((x) => (
      <Caixa key={x} p={[x, 0.83, 0]} t={[0.02, 0.26, 0.48]} cor={C.vidro} opacidade={0.32} />
    ))}
    {[-0.5, 0.5].map((x) => (
      <group key={x} position={[x, 0.70, 0.02]}><BandejaPaes /></group>
    ))}
    <Tampo p={[0, 0.96, 0]} t={[2.1, 0.08, 0.70]} raio={0.05} cor={C.madeira} />
    <group position={[-0.28, 1, 0.015]}><BandejaPaes /></group>
    <group position={[0.67, 1, 0.04]}><PoteBalas /></group>
  </group>
);
