// Checagem de enquadramento: todo personagem que é alvo da câmera tem de estar INTEIRO no quadro do começo ao fim.
import * as THREE from 'three';
import type { Ficha } from './schema';
import { caminho, cameraNoQuadro } from './montador';

export function foraDoQuadro(f: Ficha): string[] {
  const erros: string[] = [];
  if (f.camera.plano === 'detalhe') return erros; // detalhe é de propósito fechado nas mãos/objeto
  const cam = new THREE.PerspectiveCamera(40, 16 / 9, 0.1, 200);
  for (let q = 0; q < f.duracao; q += 5) {
    const c = cameraNoQuadro(f, q);
    cam.fov = c.fov; cam.position.set(...c.pos); cam.lookAt(...c.alvo); cam.updateProjectionMatrix(); cam.updateMatrixWorld();
    for (const id of [f.camera.alvo].flat()) {
      const { xz } = caminho(f.personagens.find((p) => p.id === id)!, q, f.duracao);
      // pontos da cabeça (topo e laterais) e dos pés; plano "close" só exige a cabeça
      const pts: [number, number, number][] = [[xz[0], 1.95, xz[1]], [xz[0] - 0.38, 1.5, xz[1]], [xz[0] + 0.38, 1.5, xz[1]]];
      if (f.camera.plano !== 'close' && f.camera.plano !== 'ombro') pts.push([xz[0], 0.4, xz[1]]);
      const fora = pts.some((p) => { const v = new THREE.Vector3(...p).project(cam); return Math.abs(v.x) > 0.97 || Math.abs(v.y) > 0.97 || v.z > 1; });
      if (fora) { erros.push(`"${id}" sai do quadro no quadro ${q}`); break; }
    }
    if (erros.length >= 3) break;
  }
  return erros;
}
