// Cenário reutilizável: quadra da escola (chão, quadra, linhas, prédio, alambrado, árvore). Medidas em metros, Y para cima.
import * as THREE from 'three';
import React from 'react';

const cache = new Map<string, THREE.MeshStandardMaterial>();
const mat = (cor: string, flat = false) => {
  const k = cor + flat;
  let m = cache.get(k);
  if (!m) { m = new THREE.MeshStandardMaterial({ color: cor, roughness: 0.85, flatShading: flat }); cache.set(k, m); }
  return m;
};
type V3 = [number, number, number];
const Caixa: React.FC<{ p: V3; t: V3; cor: string; sombra?: boolean }> = ({ p, t, cor, sombra = true }) => (
  <mesh position={p} material={mat(cor)} castShadow={sombra} receiveShadow><boxGeometry args={t} /></mesh>
);
const Haste: React.FC<{ a: V3; b: V3; r: number; cor: string }> = ({ a, b, r, cor }) => {
  const va = new THREE.Vector3(...a), vb = new THREE.Vector3(...b), d = vb.clone().sub(va);
  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), d.clone().normalize());
  return (
    <mesh position={va.add(vb).multiplyScalar(0.5)} quaternion={q} material={mat(cor)} castShadow receiveShadow>
      <cylinderGeometry args={[r, r, d.length(), 10]} />
    </mesh>
  );
};

export type CoresQuadra = { quadra: string; linha: string; linha2: string; predio: string; janela: string; faixa: string; chao: string };
export const CORES_QUADRA: CoresQuadra = { quadra: '#3d7fc4', linha: '#ffffff', linha2: '#f2c94c', predio: '#e8c27a', janela: '#1f3f75', faixa: '#c8323a', chao: '#cfc6b4' };

export const Quadra: React.FC<{ c?: CoresQuadra }> = ({ c = CORES_QUADRA }) => {
  const linhas: [number, number, number, number, keyof CoresQuadra][] = [
    [0, 0, 0.08, 11, 'linha2'], [0, -5.45, 18, 0.1, 'linha'], [0, 5.45, 18, 0.1, 'linha'],
    [-8.95, 0, 0.1, 11, 'linha'], [8.95, 0, 0.1, 11, 'linha'], [0, 2.6, 18, 0.08, 'linha2'],
  ];
  const janelas: V3[] = [];
  for (const y of [2.0, 4.6]) for (let i = -7; i <= 7; i++) janelas.push([i * 2.3, y, -8.47]);
  return (
    <group>
      <Caixa p={[0, -0.07, 0]} t={[60, 0.1, 60]} cor={c.chao} sombra={false} />
      {/* camadas do chão separadas por 2 cm: evita uma camada "vazar" pela outra num quadro (z-fighting) */}
      <Caixa p={[0, 0.0, 0]} t={[18, 0.02, 11]} cor={c.quadra} sombra={false} />
      {linhas.map(([x, z, w, h, k], i) => <Caixa key={i} p={[x, 0.016, z]} t={[w, 0.008, h]} cor={c[k]} sombra={false} />)}
      <mesh position={[0, 0.016, 0]} rotation={[Math.PI / 2, 0, 0]} scale={[1, 1, 0.1]} material={mat(c.linha)} receiveShadow>
        <torusGeometry args={[1.8, 0.045, 8, 128]} />
      </mesh>
      {/* prédio da escola */}
      <Caixa p={[0, 3.5, -9.5]} t={[34, 7, 2]} cor={c.predio} />
      <Caixa p={[0, 0.5, -8.48]} t={[34, 0.35, 0.04]} cor={c.faixa} />
      {janelas.map((p, i) => (
        <group key={i}>
          {/* janela: moldura branca larga + vidro; nada mais fino que 8 cm no fundo (linha fina cintila) */}
          <Caixa p={[p[0], p[1], -8.48]} t={[1.66, 1.46, 0.04]} cor="#f4efe6" sombra={false} />
          <Caixa p={p} t={[1.5, 1.3, 0.05]} cor={c.janela} sombra={false} />
          <Caixa p={[p[0], p[1] - 0.72, -8.42]} t={[1.8, 0.1, 0.14]} cor="#f4efe6" sombra={false} />
        </group>
      ))}
      {/* alambrado */}
      {/* mureta baixa com pilares grossos (no lugar do alambrado de arame, que cintilava) */}
      <Caixa p={[0, 0.45, -7.6]} t={[36, 0.9, 0.25]} cor="#d9d2c3" />
      <Caixa p={[0, 0.93, -7.6]} t={[36.2, 0.08, 0.34]} cor="#bfb6a4" />
      {Array.from({ length: 9 }, (_, i) => <Caixa key={i} p={[(i - 4) * 4.4, 0.6, -7.6]} t={[0.36, 1.2, 0.36]} cor="#bfb6a4" />)}
      {/* árvore */}
      <Haste a={[9.8, 0, -6.5]} b={[9.8, 2.2, -6.5]} r={0.14} cor="#6b4a2f" />
      <mesh position={[9.8, 3.0, -6.5]} material={mat('#3f8f4f', true)} castShadow receiveShadow><icosahedronGeometry args={[1.3, 0]} /></mesh>
    </group>
  );
};
