// Cenário: avenida de cidade grande de dia, em perspectiva. Os personagens ficam na calçada larga da frente;
// atrás deles a avenida (4 faixas, faixa de pedestres) some no horizonte entre duas fileiras de torres coloridas,
// com lojas no térreo, calçadas largas dos dois lados e muitos pedestres andando (Boneco do kit).
// Tudo é montado num referencial "da rua" girado 20°: o ponto de fuga cai no terço direito do quadro, longe dos personagens.
// Metros, Y para cima, chão em y = 0. Câmera olha de +Z para -Z.
import * as THREE from 'three';
import React from 'react';
import { useCurrentFrame, random } from 'remotion';
import { Boneco, type Visual } from '../../../kit/Boneco';
import { BASE, type Juntas } from '../../../kit/poses';
import type { LimitesCenario } from '../tipos';
import { Caixa, Caixas, Ceu, Haste, PlanoFoco, Sol, mat, type V3 } from './base';

export const LIMITES_CIDADE: LimitesCenario = { limiteX: 1.5, limiteZ: [-1, 3], ceu: '#a9d6f0' };

const GIRO = (-20 * Math.PI) / 180; // giro da rua: a avenida segue para trás e para a direita
const AV = 7; // meia largura do asfalto
const XF = 12; // fachadas das torres (|x|)
const Z_MF = -1.6; // borda da calçada da frente
const Y_RUA = -0.15; // asfalto 15 cm abaixo das calçadas
const FIM = -185; // fim da avenida (a câmera vê até 200 m)
const FAIXA: [number, number] = [-3.2, -6.4]; // faixa de pedestres (z)

const C = {
  calcada: '#e4d4b4', calcada2: '#dccaa8', meioFio: '#cfc8ba', asfalto: '#5d6470', faixa: '#f4f2ec', amarela: '#f2c531',
  servico: '#b8c2c9', terra: '#8a6a48', moldura: '#f6f1e6', vidro: '#3d6ea8', vitrine: '#a8d4ee', porta: '#2c3e50',
  tronco: '#6b4a2f', folha: '#4f9a52', folha2: '#63ad5a', poste: '#5b636e', pneu: '#22262c', calota: '#c9ccd1', ceu: '#dcecf6',
};
const PALETA = ['#ef7d5b', '#43aaa4', '#f2c94c', '#5b86d9', '#e98aa6', '#86cf9a', '#a98ad8', '#f0a050', '#4fb3d9', '#e8665f'];

// ---------- caixas agrupadas por cor (uma mesh por cor) ----------
type Item = { p: V3; t: V3 };
class Lotes {
  m = new Map<string, Item[]>();
  add(cor: string, p: V3, t: V3, sombra = true) {
    const k = `${cor}|${sombra ? 1 : 0}`;
    if (!this.m.has(k)) this.m.set(k, []);
    this.m.get(k)!.push({ p, t });
  }
  render() {
    return [...this.m.entries()].map(([k, itens]) => {
      const [cor, s] = k.split('|');
      return <Caixas key={k} itens={itens} cor={cor} sombra={s === '1'} />;
    });
  }
}

/** Cor clareada pela distância (ar entre a torre e a câmera), em 3 níveis para poucas cores. */
const longe = (cor: string, nivel: number) => new THREE.Color(cor).lerp(new THREE.Color(C.ceu), [0, 0.2, 0.4][nivel]).getHexString();
const escura = (cor: string) => '#' + new THREE.Color('#' + cor.replace('#', '')).multiplyScalar(0.78).getHexString();

// ---------- chão ----------
const Chao: React.FC = () => {
  const L = new Lotes();
  // bases: calçada da frente, calçadas da avenida e asfalto (mais baixo)
  L.add(C.calcada, [0, -0.06, (Z_MF + 14) / 2], [120, 0.1, 14 - Z_MF], false);
  for (const s of [-1, 1]) L.add(C.calcada, [s * (AV + 30), -0.06, (Z_MF + FIM) / 2], [60, 0.1, Z_MF - FIM], false);
  L.add(C.asfalto, [0, Y_RUA - 0.05, (Z_MF - 0.3 + FIM) / 2], [2 * AV, 0.1, Z_MF - 0.3 - FIM], false);
  // meios-fios (30 cm, mesmo tom da calçada um pouco mais cinza: sem "linha clara")
  L.add(C.meioFio, [0, Y_RUA / 2 - 0.01, Z_MF - 0.15], [2 * AV + 0.6, -Y_RUA + 0.02, 0.3], false);
  for (const s of [-1, 1]) L.add(C.meioFio, [s * (AV + 0.15), Y_RUA / 2 - 0.01, (Z_MF - 0.3 + FIM) / 2], [0.3, -Y_RUA + 0.02, Z_MF - 0.3 - FIM], false);
  // placas grandes em dois tons quase iguais, encostadas (sem junta): xadrez discreto só perto
  const placa = (x0: number, x1: number, z0: number, z1: number, passo: number) => {
    const nx = Math.round((x1 - x0) / passo), nz = Math.round((z0 - z1) / passo);
    const px = (x1 - x0) / nx, pz = (z0 - z1) / nz;
    for (let i = 0; i < nx; i++) for (let j = 0; j < nz; j++) if ((i + j) % 2) L.add(C.calcada2, [x0 + (i + 0.5) * px, -0.005, z0 - (j + 0.5) * pz], [px, 0.02, pz], false);
  };
  placa(-24, 24, 12, Z_MF, 2);
  for (const s of [-1, 1]) placa(s > 0 ? AV + 1.3 : -XF, s > 0 ? XF : -AV - 1.3, Z_MF, -60, 1.85);
  // faixa de serviço (canteiros e postes) junto ao meio-fio da avenida e piso tátil amarelo na frente
  for (const s of [-1, 1]) L.add(C.servico, [s * (AV + 0.8), -0.003, (Z_MF + FIM) / 2], [1.0, 0.02, Z_MF - FIM], false);
  L.add(C.amarela, [0, -0.003, Z_MF + 0.55], [2 * AV, 0.02, 0.4], false);
  // faixa central dupla amarela, tracejado branco das faixas, faixa de pedestres e linha de retenção
  for (const s of [-1, 1]) L.add(C.amarela, [s * 0.16, Y_RUA + 0.01, (-7.4 - 90) / 2], [0.16, 0.02, 90 - 7.4], false);
  for (let z = -9; z > -88; z -= 6) for (const s of [-1, 1]) L.add(C.faixa, [s * AV / 2, Y_RUA + 0.01, z], [0.16, 0.02, 3], false);
  for (let x = -AV + 0.6; x < AV - 0.3; x += 1.0) L.add(C.faixa, [x, Y_RUA + 0.01, (FAIXA[0] + FAIXA[1]) / 2], [0.5, 0.02, FAIXA[0] - FAIXA[1]], false);
  L.add(C.faixa, [-AV / 2, Y_RUA + 0.01, -7.1], [AV, 0.02, 0.4], false);
  return <group>{L.render()}</group>;
};

// ---------- torres ----------
type Loja = 'cafe' | 'farmacia' | 'livros' | 'padaria' | 'vitrine';
type Torre = { u0: number; u1: number; h: number; cor: string; jan: 'grade' | 'faixa' | 'vidro'; loja?: Loja; topo?: 'recuo' | 'antena'; recuo?: number };
type Lado = 'E' | 'D' | 'F';

// fileiras da avenida: u = distância ao longo da avenida (z = -u). As de perto são feitas à mão (lojas no térreo).
const ESQ: Torre[] = [
  { u0: 2, u1: 10, h: 16, cor: PALETA[0], jan: 'grade', loja: 'cafe' },
  { u0: 10, u1: 18, h: 44, cor: PALETA[1], jan: 'faixa', loja: 'vitrine', topo: 'recuo', recuo: 0.6 },
  { u0: 18, u1: 25, h: 12, cor: PALETA[2], jan: 'grade', loja: 'farmacia' },
  { u0: 25, u1: 35, h: 60, cor: PALETA[3], jan: 'vidro', loja: 'vitrine', recuo: 0.6 },
  { u0: 35, u1: 42, h: 20, cor: PALETA[4], jan: 'grade', loja: 'livros' },
  { u0: 42, u1: 52, h: 72, cor: PALETA[5], jan: 'faixa', topo: 'antena', recuo: 0.6 },
];
// do lado do sol: baixas e altas alternadas, com uma rua transversal (u 9 a 14), para a sombra cair em faixas na avenida
const DIR: Torre[] = [
  { u0: 2, u1: 9, h: 9, cor: PALETA[7], jan: 'grade', loja: 'padaria' },
  { u0: 14, u1: 22, h: 60, cor: PALETA[8], jan: 'vidro' },
  { u0: 22, u1: 28, h: 11, cor: PALETA[6], jan: 'grade', loja: 'vitrine', recuo: 0.6 },
  { u0: 28, u1: 38, h: 70, cor: PALETA[9], jan: 'faixa', topo: 'recuo' },
  { u0: 38, u1: 44, h: 14, cor: PALETA[2], jan: 'grade', loja: 'vitrine', recuo: 0.6 },
  { u0: 44, u1: 56, h: 80, cor: PALETA[0], jan: 'faixa', topo: 'antena' },
];
/** Continua a fileira até o fim da avenida, com larguras e alturas variadas (acaso fixo por semente). */
const continua = (lista: Torre[], semente: string) => {
  const out = [...lista];
  let u = lista[lista.length - 1].u1, i = 0;
  const jans = ['faixa', 'grade', 'vidro'] as const;
  while (u < -FIM - 30) {
    const w = 8 + Math.round(random(`${semente}-w${i}`) * 5), alta = i % 2 === 0;
    const h = alta ? 50 + Math.round(random(`${semente}-h${i}`) * 40) : 16 + Math.round(random(`${semente}-h${i}`) * 18);
    out.push({ u0: u, u1: u + w, h, cor: PALETA[(i * 3 + semente.length) % PALETA.length], jan: jans[i % 3], topo: alta ? (i % 4 === 0 ? 'antena' : 'recuo') : undefined, recuo: i % 2 ? 0.6 : 0 });
    u += w; i++;
  }
  return out;
};
const FILA_E = continua(ESQ, 'esq'), FILA_D = continua(DIR, 'dir');
// fundo da avenida: torres de frente para a câmera, mais baixas que o quadro (o topo aparece contra o céu)
const FUNDO: Torre[] = [
  { u0: -48, u1: -34, h: 30, cor: PALETA[3], jan: 'faixa' }, { u0: -34, u1: -22, h: 46, cor: PALETA[1], jan: 'vidro', topo: 'antena' },
  { u0: -22, u1: -10, h: 26, cor: PALETA[4], jan: 'grade' }, { u0: -10, u1: 4, h: 38, cor: PALETA[7], jan: 'faixa', topo: 'recuo' },
  { u0: 4, u1: 16, h: 52, cor: PALETA[8], jan: 'vidro', topo: 'antena' }, { u0: 16, u1: 28, h: 28, cor: PALETA[6], jan: 'grade' },
  { u0: 28, u1: 44, h: 42, cor: PALETA[5], jan: 'faixa' },
];

/** Monta uma torre nos lotes. Referencial da fachada: u ao longo, v para cima, w para fora (a fachada fica em w = 0). */
const torre = (L: Lotes, b: Torre, lado: Lado, nivel: number) => {
  const PROF = 14, rec = b.recuo ?? 0;
  const pos = (u: number, v: number, w: number): V3 =>
    lado === 'E' ? [-XF - rec + w, v, -u] : lado === 'D' ? [XF + rec - w, v, -u] : [u, v, FIM - 4 - rec + w];
  const tam = (tu: number, tv: number, tw: number): V3 => (lado === 'F' ? [tu, tv, tw] : [tw, tv, tu]);
  const add = (cor: string, u: number, v: number, w: number, tu: number, tv: number, tw: number, sombra = true) =>
    L.add(cor.startsWith('#') ? cor : '#' + cor, pos(u, v, w), tam(tu, tv, tw), sombra && nivel === 0);
  const W = b.u1 - b.u0, cu = (b.u0 + b.u1) / 2, h = b.h;
  const cor = '#' + longe(b.cor, nivel), esc = escura(cor);
  const vid = nivel === 0 ? C.vidro : '#' + longe('#6f97c4', nivel);
  add(cor, cu, h / 2, -PROF / 2, W, h, PROF);
  add(esc, cu, h + 0.3, -PROF / 2, W + 0.2, 0.6, PROF + 0.2);
  if (b.topo === 'recuo') { add(cor, cu, h + 3.6, -PROF / 2, W * 0.62, 6, PROF * 0.6); add(esc, cu, h + 6.8, -PROF / 2, W * 0.62 + 0.2, 0.5, PROF * 0.6 + 0.2); }
  if (b.topo === 'antena') { add(esc, cu, h + 1.2, -PROF / 2, 2.4, 1.8, 2.4); add('#8a929c', cu, h + 5, -PROF / 2, 0.3, 6, 0.3); }
  // térreo: loja (perto) ou faixa de base com porta (longe)
  const v0 = b.loja ? 4.9 : 4.2;
  if (b.loja) loja(add, b, esc);
  else { add(esc, cu, 1.6, 0.05, W, 3.2, 0.1); add(vid, cu, 1.3, 0.12, Math.min(3, W - 2), 2.4, 0.08, false); }
  // andares de cima
  if (b.jan === 'vidro') {
    add(vid, cu, (v0 - 0.3 + h - 0.8) / 2, 0.04, W - 0.8, h - 0.8 - (v0 - 0.3), 0.08, false);
    for (let v = v0 + 2.6; v < h - 1.5; v += 3) add(esc, cu, v, 0.1, W - 0.4, 0.4, 0.1, false);
  } else if (b.jan === 'faixa') {
    for (let v = v0 + 0.7; v < h - 1.2; v += 3) add(vid, cu, v, 0.05, W - 1.2, 1.4, 0.1, false);
  } else {
    const cols = Math.max(2, Math.floor((W - 1) / 2.1)), passo = (W - 1) / cols;
    for (let v = v0 + 0.8; v < h - 1.2; v += 3) for (let i = 0; i < cols; i++) {
      const u = b.u0 + 0.5 + (i + 0.5) * passo;
      if (nivel === 0) add(C.moldura, u, v, 0.03, passo - 0.5, 1.9, 0.06);
      add(vid, u, v, 0.08, passo - 0.8, 1.6, 0.06, false);
    }
  }
};

/** Térreo de loja: vitrine, porta, verga, toldo listrado e letreiro com ícone (tudo em caixas). */
const loja = (add: (cor: string, u: number, v: number, w: number, tu: number, tv: number, tw: number, sombra?: boolean) => void, b: Torre, esc: string) => {
  const W = b.u1 - b.u0, cu = (b.u0 + b.u1) / 2;
  const vi0 = b.u0 + 1.8, vi1 = b.u1 - 0.4;
  add(C.moldura, (vi0 + vi1) / 2, 1.5, 0.03, vi1 - vi0 + 0.3, 2.6, 0.06);
  add(C.vitrine, (vi0 + vi1) / 2, 1.5, 0.07, vi1 - vi0, 2.3, 0.06, false);
  add(C.porta, b.u0 + 0.95, 1.2, 0.06, 1.1, 2.4, 0.1);
  add(esc, cu, 3.2, 0.08, W, 0.5, 0.16);
  const acento = { cafe: '#7a4a2a', farmacia: '#2fa36b', livros: '#d64545', padaria: '#e0892e', vitrine: esc }[b.loja!];
  if (b.loja !== 'vitrine') {
    // toldo: listras ao longo da fachada, alternando a cor da loja e branco
    const n = Math.max(4, Math.round(W / 0.75)), lw = W / n;
    for (let i = 0; i < n; i++) add(i % 2 ? C.moldura : acento, b.u0 + (i + 0.5) * lw, 2.86, 0.75, lw, 0.14, 1.4);
    // letreiro branco com rabisco e ícone
    add(C.moldura, cu, 4.05, 0.12, W * 0.62, 1.0, 0.12);
    add(acento, cu + 0.55, 4.25, 0.2, W * 0.26, 0.16, 0.04, false);
    add(acento, cu + 0.4, 3.9, 0.2, W * 0.18, 0.16, 0.04, false);
    const ui = cu - W * 0.2;
    if (b.loja === 'cafe') { add(acento, ui, 4.12, 0.22, 0.42, 0.46, 0.06); add(acento, ui + 0.27, 4.16, 0.22, 0.12, 0.24, 0.06); add(acento, ui, 3.82, 0.22, 0.7, 0.1, 0.06); }
    if (b.loja === 'farmacia') { add(acento, ui, 4.05, 0.22, 0.24, 0.72, 0.06); add(acento, ui, 4.05, 0.22, 0.72, 0.24, 0.06); }
    if (b.loja === 'livros') ['#d64545', '#3a86c8', '#f2c531'].forEach((c, i) => add(c, ui - 0.24 + i * 0.24, 4.05, 0.22, 0.18, 0.62 - i * 0.08, 0.06));
    if (b.loja === 'padaria') { add(acento, ui, 4.05, 0.22, 0.8, 0.36, 0.06); add(C.moldura, ui, 4.12, 0.26, 0.5, 0.09, 0.04, false); }
  }
};

// ---------- veículos ----------
