/** Ciclo de caminhada: braços contrários às pernas, leve sobe e desce; `k` some com o passo ao parar. */
const andando = (d: number, passo: number, fase: number, k: number): Juntas => {
  const s = Math.sin((d / passo) * Math.PI * 2 + fase) * k;
  return {
    ...BASE,
    quadrilE: 24 * s, quadrilD: -24 * s, joelhoE: 6 + 22 * Math.max(0, -s), joelhoD: 6 + 22 * Math.max(0, s),
    ombroEX: -20 * s, ombroDX: 20 * s, ombroEZ: 8, ombroDZ: 8, cotoveloE: 18, cotoveloD: 18,
    troncoX: 3 * k, altura: -0.025 * Math.abs(s),
  };
};

const Pedestres: React.FC<{ q: number }> = ({ q }) => (
  <group>
    {PEDESTRES.map((p, i) => {
      const r = (p.giro * Math.PI) / 180, total = p.vel * (q / 30);
      const d = p.ate === undefined ? total : Math.min(total, p.ate);
      const k = p.ate === undefined ? 1 : Math.min(1, Math.max(0, (p.ate - total) / 0.4 + 1));
      const pos: V3 = [p.de[0] + Math.sin(r) * d, p.de[1], p.de[2] + Math.cos(r) * d];
      return <Boneco key={i} v={p.v} j={andando(d, Math.min(1.3, 0.6 + p.vel * 0.7), random(`ped-${i}`) * 6.28, k)} e={{ boca: p.boca ?? 'neutra' }} pos={pos} giro={p.giro} />;
    })}
  </group>
);

/** Todas as torres numa lista de lotes (uma mesh por cor). */
const Torres: React.FC = () => {
  const L = new Lotes();
  const nivel = (u: number) => (u < 45 ? 0 : u < 95 ? 1 : 2);
  FILA_E.forEach((b) => torre(L, b, 'E', nivel(b.u0)));
  FILA_D.forEach((b) => torre(L, b, 'D', nivel(b.u0)));
  FUNDO.forEach((b) => torre(L, b, 'F', 2));
  return <group>{L.render()}</group>;
};

