// Corredor de 25,6 m: câmera em +Z, ponto de fuga em -Z, piso em y = 0.
import React, { useMemo } from 'react';
import * as THREE from 'three';
import type { LimitesCenario } from '../tipos';
import { Caixa } from './base';

const C = {
  parede: '#f2ce65', barrado: '#dcb34d', rodape: '#bb9445',
  piso: '#f1ead8', piso2: '#d6cbb4', teto: '#fff3df',
  azul: '#387fbd', azul2: '#438ecb', metal: '#23527d',
  fenda: '#204d73', branco: '#faf4e7', porta: '#b67a4d',
  moldura: '#f6e8c5', vidro: '#9bc8d8', vidroEscuro: '#508297',
};

export const LIMITES_CORREDOR: LimitesCenario = {
  limiteX: 1.65, limiteZ: [-15, 3], ceu: '#f1dfad',
};

const COMPRIMENTO = 25.6;
const CENTRO_Z = -4.8;
const portas = [-1.3, -4.1, -6.9, -9.7, -12.5, -15.3];
const lampadas = [3.7, 0.5, -2.7, -5.9, -9.1, -12.3, -15.5];

// Ladrilhos contíguos: todas as faces superiores estão em y = 0.
const Piso: React.FC = () => (
  <group>
    {Array.from({ length: 16 }, (_, linha) => [-2, 0, 2].map((x, coluna) => (
      <Caixa key={`${linha}-${coluna}`} p={[x, -0.08, -16.8 + linha * 1.6]}
        t={[2, 0.16, 1.6]} cor={(linha + coluna) % 2 ? C.piso : C.piso2} sombra={false} />
    )))}
  </group>
);

// Frente local em +Z; o grupo gira a porta do armário para dentro do corredor.
const Armario: React.FC<{ z: number; indice: number }> = ({ z, indice }) => (
  <group position={[-2.99, 0, z]} rotation={[0, Math.PI / 2, 0]}>
    <Caixa p={[0, 0.94, 0.24]} t={[0.70, 1.56, 0.48]} cor={C.metal} />
    <Caixa p={[0, 0.94, 0.56]} t={[0.62, 1.48, 0.12]} cor={indice % 3 === 0 ? C.azul2 : C.azul} />
    {/* Recortes escuros grossos; 2 cm entre as superfícies paralelas. */}
    {[1.42, 1.25].map((y) => (
      <Caixa key={y} p={[0, y, 0.68]} t={[0.36, 0.08, 0.08]} cor={C.fenda} sombra={false} />
    ))}
    <Caixa p={[-0.18, 0.94, 0.68]} t={[0.10, 0.20, 0.08]} cor={C.branco} sombra={false} />
    <Caixa p={[0.12, 1.08, 0.68]} t={[0.18, 0.10, 0.08]} cor={C.branco} sombra={false} />
  </group>
);

const PortaSala: React.FC<{ z: number }> = ({ z }) => (
  <group position={[3, 0, z]} rotation={[0, -Math.PI / 2, 0]}>
    <Caixa p={[0, 1.21, 0.15]} t={[1.44, 2.42, 0.16]} cor={C.metal} />
    <Caixa p={[0, 1.16, 0.30]} t={[1.12, 2.32, 0.10]} cor={C.porta} />
    {[-0.66, 0.66].map((x) => (
      <Caixa key={x} p={[x, 1.21, 0.30]} t={[0.12, 2.42, 0.10]} cor={C.moldura} />
    ))}
    <Caixa p={[0, 2.43, 0.30]} t={[1.44, 0.12, 0.10]} cor={C.moldura} />
    <Caixa p={[0, 1.66, 0.42]} t={[0.62, 0.76, 0.10]} cor={C.moldura} />
    <Caixa p={[0, 1.66, 0.53]} t={[0.42, 0.56, 0.08]} cor={C.vidro} sombra={false} />
    <Caixa p={[-0.38, 1.02, 0.43]} t={[0.12, 0.22, 0.12]} cor={C.branco} />
    {/* Placa de sala com rabiscos, sem fonte. */}
    <Caixa p={[0, 2.78, 0.18]} t={[1.06, 0.32, 0.12]} cor={C.metal} />
    <Caixa p={[-0.20, 2.78, 0.30]} t={[0.30, 0.08, 0.08]} cor={C.branco} sombra={false} />
    <Caixa p={[0.22, 2.78, 0.30]} t={[0.22, 0.08, 0.08]} cor={C.branco} sombra={false} />
  </group>
);

// Difusor encostado à moldura; o foco aponta para o piso, afastado do teto.
const Luminaria: React.FC<{ z: number }> = ({ z }) => {
  const alvo = useMemo(() => {
    const objeto = new THREE.Object3D();
    objeto.position.set(0, 0, z);
    return objeto;
  }, [z]);
  return (
    <group>
      <Caixa p={[0, 3.34, z]} t={[1.20, 0.12, 0.50]} cor={C.metal} sombra={false} />
      <Caixa p={[0, 3.22, z]} t={[1.0, 0.08, 0.30]} cor={C.branco} brilho={0.4} sombra={false} />
      <primitive object={alvo} />
      <spotLight position={[0, 3.10, z]} target={alvo} color="#fff4df"
        intensity={18} distance={8} decay={2} angle={1.1} penumbra={0.85}
        castShadow={z === 0.5} shadow-mapSize={[1024, 1024]}
        shadow-camera-near={0.2} shadow-camera-far={8}
        shadow-bias={-0.0003} shadow-normalBias={0.02} shadow-radius={4} />
    </group>
  );
};

// Porta dupla ao fundo fecha a fuga com vidro opaco e travessas largas.
const Fundo: React.FC = () => (
  <group>
    <Caixa p={[0, 1.7, -17.72]} t={[6.48, 3.4, 0.24]} cor={C.parede} />
    <Caixa p={[0, 1.29, -17.48]} t={[2.66, 2.58, 0.20]} cor={C.metal} />
    {[-0.63, 0.63].map((x) => (
      <group key={x}>
        <Caixa p={[x, 1.26, -17.28]} t={[1.12, 2.40, 0.16]} cor={C.branco} />
        <Caixa p={[x, 1.67, -17.14]} t={[0.88, 1.28, 0.08]} cor={C.vidro} sombra={false} />
        <Caixa p={[x, 0.49, -17.14]} t={[0.88, 0.64, 0.08]} cor={C.vidroEscuro} sombra={false} />
        <Caixa p={[x, 0.94, -17.14]} t={[0.64, 0.10, 0.08]} cor={C.metal} />
      </group>
    ))}
    <Caixa p={[0, 2.99, -17.40]} t={[2.9, 0.26, 0.16]} cor={C.moldura} />
  </group>
);

export const CorredorEscola: React.FC = () => (
  <group>
    <Piso />
    {[-1, 1].map((lado) => (
      <group key={lado}>
        <Caixa p={[lado * 3.12, 1.7, CENTRO_Z]} t={[0.24, 3.4, COMPRIMENTO]} cor={C.parede} />
        <Caixa p={[lado * 2.92, 0.57, CENTRO_Z]} t={[0.12, 0.62, COMPRIMENTO]} cor={C.barrado} />
        <Caixa p={[lado * 2.92, 0.12, CENTRO_Z]} t={[0.12, 0.24, COMPRIMENTO]} cor={C.rodape} />
      </group>
    ))}
    {/* O teto bloqueia o sol do palco; a luz principal passa a vir de cima. */}
    <Caixa p={[0, 3.52, CENTRO_Z]} t={[6.48, 0.24, COMPRIMENTO]} cor={C.teto} />
    {lampadas.map((z) => <Luminaria key={z} z={z} />)}
    <Caixa p={[-2.75, 0.08, -7.98]} t={[0.48, 0.16, 17.86]} cor={C.metal} />
    <Caixa p={[-2.71, 1.76, -7.98]} t={[0.56, 0.08, 17.86]} cor={C.azul2} />
    {Array.from({ length: 23 }, (_, i) => <Armario key={i} z={0.6 - i * 0.78} indice={i} />)}
    {portas.map((z) => <PortaSala key={z} z={z} />)}
    <Fundo />
  </group>
);
