import React from 'react';
import { useCurrentFrame } from 'remotion';
import { Caixa, mat } from './base';

const PRATA = '#e7edf0';

// Diâmetro de 8 cm, deitada; base em y=0 e numeral voltado para +Z.
export const Moeda: React.FC = () => {
  const quadro = useCurrentFrame();
  const pulso = 0.85 + 0.15 * Math.sin(quadro * Math.PI / 45);
  return (
    <group>
      <mesh position={[0, 0.004, 0]} material={mat(PRATA)} castShadow receiveShadow>
        <cylinderGeometry args={[0.04, 0.04, 0.008, 48]} />
      </mesh>
      <mesh position={[0, 0.006, 0]} material={mat('#e9b630')} castShadow receiveShadow>
        <cylinderGeometry args={[0.033, 0.033, 0.008, 48]} />
      </mesh>
      <mesh position={[0, 0.006, 0]} rotation={[-Math.PI / 2, 0, 0]} material={mat(PRATA)} castShadow receiveShadow>
        <torusGeometry args={[0.0365, 0.0035, 8, 48]} />
      </mesh>
      {/* Um com haste, bandeira e base: não parece uma letra I. */}
      <group position={[0, 0.012, 0]} rotation={[-Math.PI / 2, 0, 0]}>
        <Caixa p={[0.002, 0, 0]} t={[0.007, 0.036, 0.004]} cor="#fff0ad" />
        <Caixa p={[-0.003, 0.014, 0]} t={[0.016, 0.007, 0.004]} r={[0, 0, 0.65]} cor="#fff0ad" />
        <Caixa p={[0.001, -0.018, 0]} t={[0.023, 0.007, 0.004]} cor="#fff0ad" />
      </group>
      {/* Reflexo toy sobre o aro, sem luz própria na cena. */}
      <group position={[-0.027, 0.014, -0.023]} rotation={[-Math.PI / 2, 0, 0]} scale={pulso}>
        <mesh material={mat('#fff7ce')} scale={[0.003, 0.011, 0.0018]}>
          <icosahedronGeometry args={[1, 0]} />
        </mesh>
        <mesh material={mat('#fff7ce')} scale={[0.008, 0.0025, 0.0018]}>
          <icosahedronGeometry args={[1, 0]} />
        </mesh>
      </group>
    </group>
  );
};
