import React from 'react';
import { useCurrentFrame } from 'remotion';
import { Haste, mat, suave, type V3 } from './base';

const C = { folha: '#35cc5c', caule: '#2cb24f' };

// Superfícies lisas, sem nervuras nem sombras entre os lobos da mesma folha.
const Lobo: React.FC<{ p: V3; t: V3 }> = ({ p, t }) => (
  <mesh position={p} scale={t} material={mat(C.folha)} castShadow>
    <sphereGeometry args={[1, 32, 24]} />
  </mesh>
);

const Folha: React.FC = () => (
  <group scale={1.08}>
    <Lobo p={[-0.029, 0.079, 0]} t={[0.032, 0.039, 0.012]} />
    <Lobo p={[0.029, 0.079, 0]} t={[0.032, 0.039, 0.012]} />
    <Lobo p={[0, 0.041, 0]} t={[0.029, 0.047, 0.011]} />
  </group>
);

// Coroa de 24 cm, quatro corações e caule curto; origem na base do caule.
export const TrevoUnico: React.FC = () => (
  <group>
    <Haste a={[-0.034, 0.01, -0.008]} b={[0, 0.15, -0.008]} raio={0.008} cor={C.caule} />
    <group position={[0, 0.15, 0]}>
      {[0, 1, 2, 3].map((i) => (
        <group key={i} rotation={[0, 0, Math.PI / 4 + i * Math.PI / 2]}><Folha /></group>
      ))}
      <Lobo p={[0, 0, 0]} t={[0.017, 0.017, 0.012]} />
    </group>
  </group>
);

// O quadro 90 ainda mostra o original. Depois: dois em q112, quatro em q140.
export const TrevosNoQuadro: React.FC<{ quadro: number }> = ({ quadro }) => {
  const primeira = suave(quadro, 96, 112), segunda = suave(quadro, 124, 140);
  const lados = primeira === 0 ? [0] : [-1, 1];
  const alturas = segunda === 0 ? [0] : [-1, 1];
  return (
    <group position={[0, 0.95 + 0.025 * Math.sin(quadro * Math.PI / 45), 0]}>
      {lados.flatMap((lado) => alturas.map((altura) => (
        <group key={`${lado}-${altura}`} position={[lado * 0.17 * primeira, altura * 0.17 * segunda, 0]}>
          {/* Oscila em Y e gira no plano: mantém os quatro corações legíveis. */}
          <group position={[0, 0.15, 0]} rotation={[0, 0.35 * Math.sin(quadro * Math.PI / 60), quadro * Math.PI / 180]}>
            <group position={[0, -0.15, 0]}><TrevoUnico /></group>
          </group>
        </group>
      )))}
    </group>
  );
};

export const Trevo: React.FC = () => <TrevosNoQuadro quadro={useCurrentFrame()} />;
