// Cenário: rua de bairro, de dia. Medidas em metros, Y para cima, chão (calçada) em y = 0.
// Os personagens ficam na calçada de cá (perto de z = 0); atrás deles o meio-fio, a rua (mais baixa) e,
// do outro lado, a calçada, os quintais e uma fileira de casas baixas com recuos e alturas diferentes.
import React from 'react';
import type { LimitesCenario } from '../tipos';
import { Caixa, Haste, Telhado, PlanoFoco, mat, type V3 } from './base';

const C = {
  grama: '#9cc078', quintal: '#aacd84', calcada: '#d3d5d1', calcada2: '#c4c7c3', meioFio: '#f3f1ea',
  asfalto: '#555b63', faixa: '#f2c94c', caminho: '#e6dccb', branco: '#f8f5ef', vidro: '#3f6f9e',
  porta: '#8c5a35', tronco: '#6b4a2f', folha: '#4f9a52', folha2: '#5fae5a', metal: '#5b6470', nuvem: '#ffffff',
};

// faixas do chão em Z (de trás para a frente)
const Z_CASAS = -9.8; // fim da calçada de lá / começo dos quintais
const Z_FIO_LA = -7.6, Z_FIO_CA = -1.85, Z_CALCADA = -1.6; // meios-fios e começo da calçada de cá
const Y_RUA = -0.15; // a rua fica 15 cm abaixo das calçadas

export const LIMITES_RUA: LimitesCenario = { limiteX: 1.5, limiteZ: [-1.0, 3.0], ceu: '#a9d8f0' };

/** Chão: grama de base, rua com faixa central tracejada, meios-fios claros e altos, calçadas cinza claras. */
const Chao: React.FC = () => {
  const ladrilhos: V3[] = [];
  // calçada de cá em placas de 1,5 m, dois tons (as escuras 2 cm acima da base)
  for (let i = 0; i < 20; i++) for (let j = 0; j < 8; j++) if ((i + j) % 2 === 0) ladrilhos.push([-15 + 0.75 + i * 1.5, -0.01, Z_CALCADA + 0.75 + j * 1.5]);
  const zFaixa = (Z_FIO_LA + Z_FIO_CA) / 2;
  return (
    <group>
      <Caixa p={[0, -0.3, -10]} t={[90, 0.2, 70]} cor={C.grama} sombra={false} />
      {/* rua */}
      <Caixa p={[0, Y_RUA - 0.06, (Z_FIO_LA + Z_FIO_CA) / 2]} t={[90, 0.12, Z_FIO_CA - Z_FIO_LA + 0.2]} cor={C.asfalto} sombra={false} />
      {/* faixa central: caixas chapadas de 30 cm, 3 cm acima do asfalto */}
      {Array.from({ length: 17 }, (_, i) => <Caixa key={i} p={[(i - 8) * 3.6, Y_RUA + 0.015, zFaixa]} t={[1.8, 0.03, 0.3]} cor={C.faixa} sombra={false} />)}
      {/* meios-fios: 25 cm de largura, 6 cm acima da calçada */}
      <Caixa p={[0, -0.07, Z_FIO_CA + 0.125]} t={[90, 0.26, 0.25]} cor={C.meioFio} />
      <Caixa p={[0, -0.07, Z_FIO_LA - 0.125]} t={[90, 0.26, 0.25]} cor={C.meioFio} />
      {/* calçadas */}
      <Caixa p={[0, -0.1, (Z_CALCADA + 12) / 2]} t={[90, 0.16, 12 - Z_CALCADA]} cor={C.calcada} sombra={false} />
      {ladrilhos.map((p, i) => <Caixa key={i} p={p} t={[1.5, 0.02, 1.5]} cor={C.calcada2} sombra={false} />)}
      <Caixa p={[0, -0.08, (Z_FIO_LA - 0.25 + Z_CASAS) / 2]} t={[90, 0.16, Z_FIO_LA - 0.25 - Z_CASAS]} cor={C.calcada} sombra={false} />
      {/* quintais (grama mais clara), 2 cm abaixo da calçada */}
      <Caixa p={[0, -0.1, Z_CASAS - 5]} t={[90, 0.16, 10]} cor={C.quintal} sombra={false} />
    </group>
  );
};

type Casa = { x: number; larg: number; alt: number; zf: number; cor: string; detalhe: string; tipo: 'duas' | 'plano'; porta: number };
const CASAS: Casa[] = [
  { x: -12.6, larg: 5.0, alt: 3.0, zf: -11.2, cor: '#f28c6b', detalhe: '#b5523b', tipo: 'duas', porta: 1.3 },
  { x: -7.4, larg: 4.6, alt: 3.4, zf: -10.5, cor: '#7cc5d9', detalhe: '#f8f5ef', tipo: 'plano', porta: -1.2 },
  { x: -2.4, larg: 4.4, alt: 2.9, zf: -11.7, cor: '#f5d06a', detalhe: '#c0603e', tipo: 'duas', porta: 1.1 },
  { x: 2.6, larg: 4.8, alt: 3.5, zf: -10.8, cor: '#a8d58a', detalhe: '#5f9e57', tipo: 'plano', porta: -1.3 },
  { x: 7.8, larg: 4.6, alt: 3.1, zf: -11.4, cor: '#e9a3c4', detalhe: '#8f4b3a', tipo: 'duas', porta: 1.2 },
  { x: 13.0, larg: 5.2, alt: 3.3, zf: -10.6, cor: '#c4b0e8', detalhe: '#7a5fb0', tipo: 'plano', porta: -1.4 },
];
const PROF = 6; // profundidade das casas

/** Janela na fachada (frente em z = zf): moldura branca, vidro 3 cm à frente, travessa grossa e peitoril. */
const Janela: React.FC<{ x: number; y: number; zf: number; w?: number; h?: number }> = ({ x, y, zf, w = 1.2, h = 1.0 }) => (
  <group>
    <Caixa p={[x, y, zf + 0.02]} t={[w + 0.2, h + 0.2, 0.04]} cor={C.branco} sombra={false} />
    <Caixa p={[x, y, zf + 0.05]} t={[w, h, 0.04]} cor={C.vidro} sombra={false} />
    <Caixa p={[x, y, zf + 0.08]} t={[0.1, h, 0.04]} cor={C.branco} sombra={false} />
    <Caixa p={[x, y - h / 2 - 0.1, zf + 0.09]} t={[w + 0.4, 0.1, 0.18]} cor={C.branco} />
  </group>
);

/** Mureta de 60 cm com capa branca, de x0 a x1, na frente do quintal. */
const Mureta: React.FC<{ x0: number; x1: number; cor: string }> = ({ x0, x1, cor }) => (
  <group>
    <Caixa p={[(x0 + x1) / 2, 0.3, Z_CASAS - 0.15]} t={[x1 - x0, 0.6, 0.2]} cor={cor} />
    <Caixa p={[(x0 + x1) / 2, 0.64, Z_CASAS - 0.15]} t={[x1 - x0 + 0.04, 0.08, 0.28]} cor={C.branco} />
  </group>
);

const CasaBaixa:React.FC<{ c: Casa }> = ({ c }) => {
  const { x, larg, alt, zf } = c;
  const xp = x + c.porta, xj = x - Math.sign(c.porta) * 1.0;
  return (
    <group>
      <Caixa p={[x, alt / 2, zf - PROF / 2]} t={[larg, alt, PROF]} cor={c.cor} />
      {c.tipo === 'duas'
        ? <Telhado p={[x, alt, zf - PROF / 2]} larg={larg + 0.5} prof={PROF + 0.7} alt={1.5} cor={c.detalhe} />
        : (<>
          {/* platibanda: fachada sobe 60 cm, com uma faixa de cor no alto */}
          <Caixa p={[x, alt + 0.3, zf - 0.1]} t={[larg, 0.6, 0.2]} cor={c.cor} />
          <Caixa p={[x, alt + 0.66, zf - 0.08]} t={[larg + 0.2, 0.14, 0.3]} cor={c.detalhe} />
          <Caixa p={[x, alt + 0.1, zf - PROF / 2]} t={[larg - 0.1, 0.2, PROF - 0.3]} cor="#b9b2a4" />
        </>)}
      {/* porta: batente branco, folha de madeira 3 cm à frente, maçaneta */}
      <Caixa p={[xp, 1.08, zf + 0.02]} t={[1.1, 2.16, 0.04]} cor={C.branco} sombra={false} />
      <Caixa p={[xp, 1.03, zf + 0.05]} t={[0.9, 2.06, 0.04]} cor={C.porta} sombra={false} />
      <mesh position={[xp + 0.3, 1.0, zf + 0.1]} material={mat('#e2c46a')}><sphereGeometry args={[0.06, 12, 8]} /></mesh>
      <Janela x={xj} y={1.55} zf={zf} />
      {/* caminho da calçada até a porta, 2 cm acima da grama */}
      <Caixa p={[xp, -0.01, (zf + Z_CASAS) / 2]} t={[1.1, 0.02, Z_CASAS - zf]} cor={C.caminho} sombra={false} />
      {/* mureta baixa na divisa, com vão no caminho */}
      <Mureta x0={x - larg / 2 - 0.25} x1={xp - 0.7} cor={c.cor} />
      <Mureta x0={xp + 0.7} x1={x + larg / 2 + 0.25} cor={c.cor} />
    </group>
  );
};

/** Árvore pequena (2,6 m): tronco curto e copa em duas bolas low poly. */
const Arvore: React.FC<{ p: V3; e?: number }> = ({ p, e = 1 }) => (
  <group position={p} scale={e}>
    <Haste a={[0, 0, 0]} b={[0, 1.4, 0]} r={0.11} cor={C.tronco} />
    <mesh position={[0, 1.85, 0]} material={mat(C.folha, { flat: true })} castShadow receiveShadow><icosahedronGeometry args={[0.72, 0]} /></mesh>
    <mesh position={[0.32, 1.6, 0.28]} material={mat(C.folha2, { flat: true })} castShadow receiveShadow><icosahedronGeometry args={[0.45, 0]} /></mesh>
  </group>
);

/** Poste na beira da calçada; o braço avança `lado` (±1 em Z) sobre a rua. */
const Poste: React.FC<{ x: number; z: number; lado: 1 | -1 }> = ({ x, z, lado }) => (
  <group>
    <Haste a={[x, 0, z]} b={[x, 5.2, z]} r={0.09} cor={C.metal} />
    <Caixa p={[x, 5.15, z + lado * 0.6]} t={[0.1, 0.1, 1.3]} cor={C.metal} />
    <Caixa p={[x, 5.08, z + lado * 1.2]} t={[0.32, 0.14, 0.5]} cor={C.metal} />
    <Caixa p={[x, 4.98, z + lado * 1.2]} t={[0.24, 0.08, 0.38]} cor="#fff3cf" sombra={false} />
    <Caixa p={[x, 0.15, z]} t={[0.3, 0.3, 0.3]} cor={C.metal} />
  </group>
);

/** Carro estacionado (de brinquedo), de lado para a câmera, virado para +X. */
const Carro: React.FC<{ p: V3; cor: string }> = ({ p, cor }) => (
  <group position={p}>
    <Caixa p={[0, 0.5, 0]} t={[3.6, 0.66, 1.6]} cor={cor} />
    <Caixa p={[-0.2, 1.13, 0]} t={[2.0, 0.6, 1.4]} cor={cor} />
    <Caixa p={[-0.68, 1.13, 0.71]} t={[0.82, 0.42, 0.04]} cor={C.vidro} sombra={false} />
    <Caixa p={[0.28, 1.13, 0.71]} t={[0.82, 0.42, 0.04]} cor={C.vidro} sombra={false} />
    <Caixa p={[1.81, 0.62, 0.5]} t={[0.04, 0.16, 0.3]} cor="#fff6d8" sombra={false} />
    <Caixa p={[1.81, 0.62, -0.5]} t={[0.04, 0.16, 0.3]} cor="#fff6d8" sombra={false} />
    <Caixa p={[-1.81, 0.62, 0.5]} t={[0.04, 0.16, 0.3]} cor="#d6453d" sombra={false} />
    {[[-1.15, 0.72], [1.15, 0.72], [-1.15, -0.72], [1.15, -0.72]].map(([x, z]) => (
      <mesh key={`${x}${z}`} position={[x, 0.32, z]} rotation={[Math.PI / 2, 0, 0]} material={mat('#2b2d33')} castShadow receiveShadow>
        <cylinderGeometry args={[0.32, 0.32, 0.26, 18]} />
      </mesh>
    ))}
  </group>
);

const Nuvem: React.FC<{ p: V3; e?: number }> = ({ p, e = 1 }) => (
  <group position={p} scale={e}>
    {([[0, 0, 0, 1.6], [1.6, -0.3, 0, 1.2], [-1.6, -0.4, 0, 1.1], [0.5, 0.6, -0.3, 1.1]] as const).map(([x, y, z, r], i) => (
      <mesh key={i} position={[x, y, z]} scale={[1, 0.7, 0.7]} material={mat(C.nuvem)}><sphereGeometry args={[r, 16, 10]} /></mesh>
    ))}
  </group>
);

export const Rua: React.FC = () => (
  <group>
    <PlanoFoco z={-1.0} />
    <Chao />
    {CASAS.map((c, i) => <CasaBaixa key={i} c={c} />)}
    {/* árvores pequenas: nos quintais e na calçada de lá, nos vãos entre as casas; uma na calçada de cá, longe dos bonecos */}
    <Arvore p={[-4.95, 0, -8.7]} />
    <Arvore p={[10.25, 0, -8.7]} e={0.95} />
    <Arvore p={[-9.9, 0, -10.4]} e={0.9} />
    <Arvore p={[5.25, 0, -10.2]} e={0.85} />
    <Arvore p={[3.8, 0, -0.95]} e={0.9} />
    <Caixa p={[3.8, 0.0, -0.95]} t={[0.9, 0.04, 0.9]} cor="#8a6a4a" sombra={false} />
    {/* postes na beira das calçadas, fora do eixo dos bonecos */}
    <Poste x={-3.6} z={-1.35} lado={-1} />
    <Poste x={6.4} z={-8.1} lado={1} />
    {/* lixeira baixa (55 cm), no chão ao lado do poste */}
    <mesh position={[-2.9, 0.275, -1.2]} material={mat('#3f9a5c')} castShadow receiveShadow><cylinderGeometry args={[0.2, 0.17, 0.55, 18]} /></mesh>
    <mesh position={[-2.9, 0.57, -1.2]} material={mat('#2f7a48')} castShadow receiveShadow><cylinderGeometry args={[0.22, 0.22, 0.06, 18]} /></mesh>
    <Carro p={[-8.6, Y_RUA, -6.5]} cor="#3a86c8" />
    {/* fundo: copas acima dos telhados, morros e nuvens */}
    {[-15.5, -5, 5.4, 10.6, 16].map((x, i) => (
      <mesh key={i} position={[x, 3.6 + (i % 2) * 0.5, -19]} material={mat(i % 2 ? C.folha : '#468a4a', { flat: true })} castShadow receiveShadow><icosahedronGeometry args={[1.8, 0]} /></mesh>
    ))}
    {[[-20, -40, 14], [6, -46, 18], [30, -42, 13]].map(([x, z, r], i) => (
      <mesh key={i} position={[x, -r * 0.55, z]} scale={[1.4, 1, 1]} material={mat('#86b86b', { flat: true })} receiveShadow><icosahedronGeometry args={[r, 1]} /></mesh>
    ))}
    <Nuvem p={[-14, 10.5, -40]} />
    <Nuvem p={[7, 12.5, -45]} e={1.2} />
    <Nuvem p={[22, 10, -38]} e={0.9} />
  </group>
);
