// Formas em metros; materiais chapados compartilhados por cor.
import React from 'react';
import * as THREE from 'three';

export type V3 = [number, number, number];
type Ponto = [number, number];
const cache = new Map<string, THREE.MeshStandardMaterial>();
export const mat = (cor: string) => {
  let material = cache.get(cor);
  if (!material) {
    material = new THREE.MeshStandardMaterial({ color: cor, roughness: 0.85 });
    cache.set(cor, material);
  }
  return material;
};

export const Caixa: React.FC<{ p: V3; t: V3; cor: string; r?: V3; sombra?: boolean }> = ({ p, t, cor, r, sombra = true }) => (
  <mesh position={p} rotation={r} material={mat(cor)} castShadow={sombra} receiveShadow>
    <boxGeometry args={t} />
  </mesh>
);

export const Haste: React.FC<{ a: V3; b: V3; raio: number; cor: string }> = ({ a, b, raio, cor }) => {
  const inicio = new THREE.Vector3(...a), fim = new THREE.Vector3(...b);
  const direcao = fim.clone().sub(inicio);
  const giro = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), direcao.clone().normalize());
  return (
    <mesh position={inicio.add(fim).multiplyScalar(0.5)} quaternion={giro} material={mat(cor)} castShadow receiveShadow>
      <cylinderGeometry args={[raio, raio, direcao.length(), 10]} />
    </mesh>
  );
};

// Traços de 8 cm no plano XY; frente para +Z.
export const Traco: React.FC<{ a: Ponto; b: Ponto; cor: string; z?: number }> = ({ a, b, cor, z = 0 }) => (
  <Caixa p={[(a[0] + b[0]) / 2, (a[1] + b[1]) / 2, z]}
    t={[Math.hypot(b[0] - a[0], b[1] - a[1]) + 0.08, 0.08, 0.04]}
    r={[0, 0, Math.atan2(b[1] - a[1], b[0] - a[0])]} cor={cor} sombra={false} />
);

const segmentos: [Ponto, Ponto][] = [
  [[-0.5, 0.5], [0.5, 0.5]], [[0.5, 0.5], [0.5, 0]],
  [[0.5, 0], [0.5, -0.5]], [[-0.5, -0.5], [0.5, -0.5]],
  [[-0.5, 0], [-0.5, -0.5]], [[-0.5, 0.5], [-0.5, 0]],
  [[-0.5, 0], [0.5, 0]],
];
const digitos: Record<string, number[]> = {
  '0': [0, 1, 2, 3, 4, 5], '1': [1, 2], '2': [0, 1, 6, 4, 3],
  '3': [0, 1, 6, 2, 3], '4': [5, 6, 1, 2], '5': [0, 5, 6, 2, 3],
  '6': [0, 5, 6, 4, 2, 3], '7': [0, 1, 2], '8': [0, 1, 2, 3, 4, 5, 6], '9': [0, 1, 2, 3, 5, 6],
};
const letras: Record<string, [Ponto, Ponto][]> = {
  L: [[[-0.5, 0.5], [-0.5, -0.5]], [[-0.5, -0.5], [0.5, -0.5]]],
  O: [segmentos[0], [segmentos[1][0], segmentos[2][1]], segmentos[3], [segmentos[5][0], segmentos[4][1]]],
  T: [segmentos[0], [[0, 0.5], [0, -0.5]]],
  É: [segmentos[0], segmentos[6], segmentos[3], [[-0.5, 0.5], [-0.5, -0.5]], [[0, 0.76], [0.35, 0.91]]],
  R: [[[-0.5, 0.5], [-0.5, -0.5]], segmentos[0], segmentos[1], segmentos[6], [[0, 0], [0.5, -0.5]]],
  I: [[[0, 0.5], [0, -0.5]]],
  C: [segmentos[0], segmentos[3], [[-0.5, 0.5], [-0.5, -0.5]]],
  A: [segmentos[0], segmentos[6], [[-0.5, 0.5], [-0.5, -0.5]], [[0.5, 0.5], [0.5, -0.5]]],
  '%': [[[0.42, 0.5], [-0.42, -0.5]], [[-0.45, 0.4], [-0.45, 0.4]], [[0.45, -0.4], [0.45, -0.4]]],
};

export const Escrita: React.FC<{ texto: string; p: V3; cor: string; largura?: number; altura?: number; passo?: number }> = ({ texto, p, cor, largura = 0.25, altura = 0.44, passo = 0.39 }) => (
  <group position={p}>
    {Array.from(texto).map((letra, i) => {
      const tracos = digitos[letra] ? digitos[letra].map((n) => segmentos[n]) : letras[letra] ?? [];
      const x = (i - (texto.length - 1) / 2) * passo;
      return <group key={i} position={[x, 0, 0]}>{tracos.map(([a, b], j) => (
        <Traco key={j} a={[a[0] * largura, a[1] * altura]} b={[b[0] * largura, b[1] * altura]} cor={cor} />
      ))}</group>;
    })}
  </group>
);
