// Folha única de 30 × 40 cm, base em y=0, impressão para +Z.
import React from 'react';
import { Caixa, mat } from './base';

const C = { papel: '#ffffff', texto: '#777777', azul: '#087dd5', nota: '#ef233c' };
// Face em z=0,003; detalhes separados por pelo menos 2 cm.
const Z = 0.025;

const TuboDesenhado: React.FC = () => (
  <group position={[-0.095, 0.33, Z]}>
    <Caixa p={[0, 0.009, 0]} t={[0.048, 0.072, 0.004]} cor={C.azul} sombra={false} brilho={0.15} />
    <mesh position={[0, -0.027, 0]} scale={[1, 1, 0.08]} material={mat(C.azul, 1, 0.15)}>
      <sphereGeometry args={[0.024, 20, 12]} />
    </mesh>
    <Caixa p={[0, 0.05, 0]} t={[0.069, 0.014, 0.004]} cor={C.azul} sombra={false} brilho={0.15} />
    <Caixa p={[-0.008, 0.015, 0.024]} t={[0.008, 0.041, 0.002]} cor={C.papel} sombra={false} brilho={0.45} />
  </group>
);

// Dois laços grossos e unidos formam o 8, com miolos pequenos.
const OitoCirculado: React.FC = () => (
  <group position={[0.075, 0.308, Z]}>
    <mesh position={[0, 0.028, 0]} scale={[1, 1.1, 0.16]} material={mat(C.nota, 1, 0.15)}>
      <torusGeometry args={[0.018, 0.010, 8, 28]} />
    </mesh>
    <mesh position={[0, -0.026, 0]} scale={[1, 1.1, 0.16]} material={mat(C.nota, 1, 0.15)}>
      <torusGeometry args={[0.022, 0.011, 8, 28]} />
    </mesh>
    <mesh scale={[0.049, 0.082, 0.018]} material={mat(C.nota, 1, 0.15)}>
      <torusGeometry args={[1, 0.075, 8, 48]} />
    </mesh>
  </group>
);

const Folha: React.FC<{ corrigida?: boolean }> = ({ corrigida = false }) => (
  <group>
    {/* Branco com reforço emissivo suave conserva a leitura sob a luz do palco. */}
    <Caixa p={[0, 0.2, 0]} t={[0.3, 0.4, 0.006]} cor={C.papel} brilho={0.45} />
    <TuboDesenhado />
    <Caixa p={[-0.018, 0.359, Z]} t={[0.039, 0.013, 0.004]} cor={C.texto} sombra={false} />
    <Caixa p={[-0.023, 0.329, Z]} t={[0.029, 0.012, 0.004]} cor={C.texto} sombra={false} />
    {/* Três questões em traços largos; cabeçalho e nota ficam isolados. */}
    {[0, 1, 2].map((i) => (
      <group key={i}>
        <Caixa p={[0, 0.193 - i * 0.074, Z]} t={[0.24, 0.013, 0.004]} cor={C.texto} sombra={false} />
        <Caixa p={[-0.026, 0.163 - i * 0.074, Z]} t={[0.188, 0.011, 0.004]} cor={C.texto} sombra={false} />
      </group>
    ))}
    {corrigida && <OitoCirculado />}
  </group>
);

export const ProvaQuimica: React.FC = () => <Folha />;
export const ProvaOito: React.FC = () => <Folha corrigida />;
