import React from 'react';
import { Caixa } from './base';
import { SilhuetaHumana } from './SilhuetaHumana';

const LARGURA = 0.19;
const COMPRIMENTO = 1.92 * Math.SQRT2 - LARGURA;

// Altura total de 2 m, incluindo o apoio de 8 cm.
export const XVermelho: React.FC = () => (
  <group>
    <Caixa p={[0, 0.04, 0.1]} t={[1.84, 0.08, 0.48]} cor="#9b2430" />
    <group position={[0, 0.08, 0]}><SilhuetaHumana /></group>
    {/* Barras iguais, ±45°, cruzamento no tronco; folga de 2 cm em Z. */}
    <Caixa p={[0, 1.04, 0.12]} t={[LARGURA, COMPRIMENTO, 0.04]} cor="#e52b38" giro={Math.PI / 4} chapado />
    <Caixa p={[0, 1.04, 0.18]} t={[LARGURA, COMPRIMENTO, 0.04]} cor="#e52b38" giro={-Math.PI / 4} chapado />
  </group>
);
