// Rodada 2 das ações do lote r05 (correção do revisor). Só juntas do boneco padrão, só em função do quadro.
// Reaproveita a IK do braço de acoes.ts: cada mão é escrita como "onde fica", em metros (espaço do tronco).
// As demos '+objetos' continuam com as poses de acoes.ts (não foram pedidas nesta rodada).
import type { Juntas } from '../../../kit/poses';
import { ikBraco, paraTronco, ciclo } from './acoes';

type V3 = [number, number, number];
const TAU = Math.PI * 2;
const suave = (t: number) => { const k = Math.min(1, Math.max(0, t)); return k * k * (3 - 2 * k); };
const bracoD = (alvo: V3) => { const b = ikBraco(1, alvo); return { ombroDX: b.x, ombroDZ: b.z, cotoveloD: b.cot }; };
const bracoE = (alvo: V3) => { const b = ikBraco(-1, alvo); return { ombroEX: b.x, ombroEZ: b.z, cotoveloE: b.cot }; };

// ── escrever ─────────────────────────────────────────────────────────────
// Mão E baixa e à frente da barriga (apoio do caderno, cotovelo a ~85°); mão D logo acima e à direita dela,
// em pinça, fazendo um zigue-zague curto (o lápis na página). Cotovelos dobrados e afastados do tronco.
// Cabeça 20° + tronco 6° = 26° para baixo: o rosto aparece e a aba do boné sai de lado, na nuca.
// Peso na perna D; a E fica solta (joelho um pouco dobrado).
const MAO_APOIO: V3 = [-0.12, 0.86, 0.25];
const MAO_LAPIS: V3 = [0.02, 0.92, 0.26];
const BASE_ESCREVER = {
  troncoX: 6, troncoY: -25, cabecaX: 20, cabecaY: -8, cabecaZ: 4,
  quadrilE: 5, joelhoE: 10, quadrilD: -2, joelhoD: 0, altura: -0.004,
};
export const ESCREVER2: Partial<Juntas> = { ...BASE_ESCREVER, ...bracoE(MAO_APOIO), ...bracoD(MAO_LAPIS) };
export function escrever2(q: number): Partial<Juntas> {
  const f = ciclo(q, 36) / 36; // uma "palavra" a cada 36 q: anda para a direita e volta
  const anda = f < 0.8 ? f / 0.8 : 1 - suave((f - 0.8) / 0.2);
  const risco = f < 0.8 ? Math.sin(TAU * q / 5) : 0; // letras: 6 por segundo
  const p: V3 = [MAO_LAPIS[0] - 0.025 + 0.06 * anda, MAO_LAPIS[1] + 0.012 * risco + (f >= 0.8 ? 0.02 : 0), MAO_LAPIS[2] + 0.006 * risco];
  return { ...bracoD(p), cabecaY: -8 + 40 * (p[0] - MAO_LAPIS[0]) }; // o rosto acompanha o lápis
}

// ── jogarMoeda ───────────────────────────────────────────────────────────
// Braço D estendido para cima e para a frente (cotovelo ~40°, quase alinhado), punho a ~1,4 m.
// Tronco girado 15° para o lado do braço e um pouco para trás; peso na perna D, perna E solta.
// Braço E dobrado, punho fechado perto da cintura. A cabeça sobe e acompanha a moeda.
// Ciclo de 60 q: prepara (10–16), peteleco (16–19), moeda no ar (18–42, topo no q 30 = quadro 90), pega (40–50).
const PUNHO: V3 = [0.36, 1.38, 0.28];
const VOO: [number, number] = [18, 42];
const alturaMoeda = (f: number) => (f < VOO[0] || f >= VOO[1] ? 0 : 4 * ((f - VOO[0]) / (VOO[1] - VOO[0])) * (1 - (f - VOO[0]) / (VOO[1] - VOO[0])));
function punho(q: number): V3 {
  const f = ciclo(q, 60);
  const prepara = f >= 10 && f < 16 ? suave((f - 10) / 6) : f >= 16 && f < 19 ? 1 - suave((f - 16) / 3) : 0;
  const tranco = f >= 16 && f < 26 ? Math.sin(Math.PI * (f - 16) / 10) : 0;
  const pega = f >= 40 && f < 50 ? Math.sin(Math.PI * (f - 40) / 10) : 0;
  return [PUNHO[0], PUNHO[1] - 0.08 * prepara + 0.04 * tranco - 0.05 * pega, PUNHO[2] - 0.03 * prepara];
}
const BASE_MOEDA = {
  troncoX: -4, troncoY: 22, cabecaZ: -5,
  quadrilE: 14, joelhoE: 26, quadrilD: -4, joelhoD: 0, altura: -0.01,
};
export const JOGAR_MOEDA2: Partial<Juntas> = {
  ...BASE_MOEDA, ...bracoD(PUNHO), ...bracoE([-0.3, 0.8, 0.12]),
  cabecaX: -20, cabecaY: 12,
};
export function jogarMoeda2(q: number): Partial<Juntas> {
  const h = alturaMoeda(ciclo(q, 60));
  return { ...bracoD(punho(q)), cabecaX: -6 - 22 * h, cabecaY: 11 + 6 * h, troncoX: -4 - 3 * h };
}

// ── virarCabeca ──────────────────────────────────────────────────────────
// Sentado no chão com os joelhos para cima: coxas subindo até os joelhos, canelas em pé, pés chatos no chão
// logo à frente (os tênis ficam deitados e pequenos, não mais em pé virados para a câmera).
// Tronco um pouco para trás, apoiado nas mãos no chão atrás do quadril. Corpo parado.
// Só a cabeça gira 80° para +X em 15 q (meio segundo), dos quadros 75 a 90, passa um pouco e assenta.
export const GIRO2 = 80;
const VIRA: [number, number] = [75, 15];
const SENTADO2 = { quadrilE: 138, joelhoE: 138, quadrilD: 135, joelhoD: 135, altura: -0.47, troncoX: -22, troncoY: 0 };
const APOIO = (lado: 1 | -1): V3 => [0.3 * lado, 0.075, -0.32]; // mão no chão, atrás do quadril (espaço do boneco)
export const VIRAR_CABECA2: Partial<Juntas> = {
  ...SENTADO2,
  ...bracoE(paraTronco(SENTADO2, APOIO(-1))), ...bracoD(paraTronco(SENTADO2, APOIO(1))),
  cabecaX: 6, cabecaY: GIRO2,
};
export function virarCabeca2(q: number): Partial<Juntas> {
  const t = (q - VIRA[0]) / VIRA[1];
  const g = suave(t);
  const assenta = t > 1 && t < 1.7 ? Math.sin(Math.PI * (t - 1) / 0.7) : 0;
  return { cabecaY: GIRO2 * g + 5 * assenta, cabecaX: 6 - 6 * Math.sin(Math.PI * g) };
}
