// Ajuste só da vitrine (composição VitrineLote): close-up do objeto sobre o pedestal, com a mão do Téo no quadro
// para dar escala. Os componentes exportados continuam em tamanho real, na origem e sem câmera.
// A câmera fica a ~2,1 m (o foco do DOF da vitrine) e fecha o quadro com fov estreito (teleobjetiva).
import React, { useLayoutEffect } from 'react';
import { useThree } from '@react-three/fiber';
import { useVideoConfig } from 'remotion';
import * as THREE from 'three';

type V3 = [number, number, number];
/** alvo: centro do quadro (mundo); altura: altura do quadro em metros no alvo; pe: [largura, fundo] da sombra de contato. */
type Plano = { desloc: V3; alvo: V3; altura: number; pe: [number, number] };

const DIST = 2.1, ELEV = 18; // distância (= foco da vitrine) e graus acima do alvo

export const PLANOS = {
  // a mão direita do Téo (parado) fica em x ≈ 0,25, y ≈ 0,59: o quadro vai dela até a borda direita do tampo
  celular: { desloc: [-0.12, 0, 0.1], alvo: [0.5, 0.75, 0.06], altura: 0.46, pe: [0.08, 0.05] },
  provaDez: { desloc: [-0.08, 0, 0.12], alvo: [0.5, 0.8, 0.08], altura: 0.6, pe: [0.22, 0.05] },
  cadernoBia: { desloc: [-0.07, 0, 0.1], alvo: [0.58, 0.79, 0.06], altura: 0.56, pe: [0.36, 0.06] },
} satisfies Record<string, Plano>;

const AjustarCamera: React.FC<{ p: Plano }> = ({ p }) => {
  const camera = useThree((s) => s.camera) as THREE.PerspectiveCamera;
  // roda depois da <Camera> do palco (vem antes na árvore), a cada quadro, sem loop próprio
  useLayoutEffect(() => {
    const e = (ELEV * Math.PI) / 180;
    camera.position.set(p.alvo[0], p.alvo[1] + DIST * Math.sin(e), p.alvo[2] + DIST * Math.cos(e));
    camera.lookAt(...p.alvo);
    camera.fov = (2 * Math.atan(p.altura / 2 / DIST) * 180) / Math.PI;
    camera.updateProjectionMatrix();
    camera.updateMatrixWorld();
  });
  return null;
};

// sombra de contato suave: retângulo escuro translúcido rente ao tampo, sob a base do objeto
const matSombra = new THREE.MeshStandardMaterial({ color: '#000000', transparent: true, opacity: 0.22, depthWrite: false, roughness: 0.9 });
const SombraContato: React.FC<{ pe: [number, number] }> = ({ pe }) => (
  <mesh position={[0, 0.0012, -pe[1] / 2 + 0.01]} material={matSombra}><boxGeometry args={[pe[0], 0.0004, pe[1]]} /></mesh>
);

export function apresentar(Componente: React.FC, nome: keyof typeof PLANOS): React.FC {
  return function PecaNaVitrine() {
    const { id } = useVideoConfig();
    if (id !== 'VitrineLote') return <Componente />;
    const p: Plano = PLANOS[nome];
    return (
      <>
        <AjustarCamera p={p} />
        <group position={p.desloc}><SombraContato pe={p.pe} /><Componente /></group>
      </>
    );
  };
}
