// Esfera de 3 m, frente para +Z; a ponta do raio inferior toca y = 0.
import React from 'react';
import { Capsula, mat } from './base';

const CENTRO_Y = 2.12;
const preto = '#111116';

export const SolToy: React.FC = () => (
  <group position={[0, CENTRO_Y, 0]}>
    {Array.from({ length: 12 }, (_, i) => {
      const angulo = i * Math.PI / 6;
      // Base em 1,40 m: cada raio entra 10 cm na esfera.
      return <Capsula key={i} p={[Math.sin(angulo) * 1.76, Math.cos(angulo) * 1.76, 0]}
        raio={0.12} comp={0.48} cor="#ffd527" brilho={0.65}
        giro={[0, 0, -angulo]} sombra={false} />;
    })}
    {/* O sol é luminoso: não recebe nem projeta sombra opaca. */}
    <mesh material={mat('#ff8c22', { brilho: 0.65 })}>
      <sphereGeometry args={[1.5, 48, 32]} />
    </mesh>
    <mesh material={mat(preto, { verso: true, brilho: 0.15 })}>
      <sphereGeometry args={[1.54, 48, 32]} />
    </mesh>
    {[-1, 1].map((lado) => (
      <group key={lado}>
        <mesh position={[lado * 0.43, 0.2, 1.46]} scale={[1, 1.1, 0.55]} material={mat(preto)}>
          <sphereGeometry args={[0.115, 20, 12]} />
        </mesh>
        <mesh position={[lado * 0.43 - 0.025, 0.24, 1.525]} scale={[1, 1, 0.45]} material={mat('#fff3d3', { brilho: 0.3 })}>
          <sphereGeometry args={[0.04, 12, 8]} />
        </mesh>
      </group>
    ))}
    <mesh position={[0, -0.24, 1.46]} rotation={[0, 0, Math.PI]} material={mat(preto)}>
      <torusGeometry args={[0.38, 0.06, 10, 36, Math.PI]} />
    </mesh>
  </group>
);
