import React from 'react';
import * as THREE from 'three';
import { useCurrentFrame } from 'remotion';
import { Caixa, mat } from './base';

const sombra = new THREE.MeshStandardMaterial({
  color: '#172c42', roughness: 0.85, transparent: true, opacity: 0.18, depthWrite: false,
});

// Diâmetro de 8 cm. O aro faz parte do corpo e o 1 encosta na face dourada.
export const Moeda: React.FC = () => {
  const quadro = useCurrentFrame();
  const pulso = 1 + 0.035 * Math.sin(quadro * Math.PI / 45);
  return (
    <group>
      {/* Volumes achatados suavizam a sombra de contato no close. */}
      {[0.045, 0.04].map((raio, i) => (
        <mesh key={raio} position={[0.002, 0.0003 + i * 0.0002, 0.002]}
          scale={[raio, 0.00025, raio]} material={sombra}>
          <sphereGeometry args={[1, 32, 12]} />
        </mesh>
      ))}
      <mesh position={[0, 0.0035, 0]} material={mat('#dce6f2', 0, 0.35)} castShadow receiveShadow>
        <cylinderGeometry args={[0.04, 0.04, 0.007, 48]} />
      </mesh>
      <mesh position={[0, 0.0045, 0]} material={mat('#eab22e', 0.1, 0.25)} castShadow receiveShadow>
        <cylinderGeometry args={[0.031, 0.031, 0.009, 48]} />
      </mesh>
      <group position={[0.003, 0.0105, 0]} rotation={[-Math.PI / 2, 0, 0]}>
        <Caixa p={[0, 0, 0]} t={[0.009, 0.038, 0.003]} cor="#70470c" />
        <Caixa p={[-0.004, 0.015, 0]} t={[0.017, 0.008, 0.003]} cor="#70470c" />
        <Caixa p={[0, -0.016, 0]} t={[0.025, 0.007, 0.003]} cor="#70470c" />
      </group>
      {/* Reflexo largo e claro na face, unido à moeda. */}
      <mesh position={[-0.016, 0.0091, -0.014]} scale={[0.013 * pulso, 0.0008, 0.006]}
        material={mat('#fff4be', 0.5)}>
        <sphereGeometry args={[1, 24, 12]} />
      </mesh>
    </group>
  );
};
