// Cenário: quarto pequeno da Bia, de dia. Medidas em metros, Y para cima, chão em y = 0.
// Parede do fundo (-Z), lilás: à esquerda a escrivaninha clara sob a janela, com luminária e três cadernos abertos
// com "98%" circulado em vermelho; no centro, acima das cabeças, o pôster de planetas; à direita a estante e a cama.
// Os bonecos da vitrine (x = ±0,7, z = 0,5) tapam o fundo até ~1,5 m entre |x| ≈ 0,4 e 1,9: nada importante fica ali.
import React from 'react';
import type { LimitesCenario } from '../tipos';
import { Caixa, Caixas, Cilindro, Haste, LuzInterior, Numero, PlanoFoco, mat, vidro, type V3 } from './base';

const C = {
  parede: '#cdb8ec', rodape: '#fbf8f4', teto: '#faf7fd',
  piso: '#d9b78c', piso2: '#cfab7e', tapete: '#f4a6c0',
  madeira: '#ead0a6', madeira2: '#d9b98a', batente: '#ffffff', vidro: '#d8f0fa', cortina: '#f6d36b',
  luminaria: '#3fa7a0', lampada: '#fff4c8',
  papel: '#fdfcf7', capa: ['#3a86c8', '#f08a24', '#5fae5a'], espiral: '#5b6470', nota: '#d6303a',
  poster: '#24315e', moldura: '#fbf8f4', sol: '#f6c33c', terra: '#3a9be0', saturno: '#e5b973', anel: '#f2dfb4', marte: '#e0583f',
  livros: ['#e0583f', '#3a86c8', '#f6c33c', '#5fae5a', '#8b5fc7', '#f08a24', '#2f4f7a'],
  colchao: '#fbf8f4', edredom: '#8b5fc7', edredom2: '#a882db', travesseiro: '#ffffff', banco: '#f4a6c0',
  folha: '#4f9a52', vaso: '#c8693f',
};

const X = 3.7; // meia largura (paredes em x = ±3,7)
const ZF = -2.4; // face da parede do fundo
const ZT = 7; // as paredes vão até atrás da câmera
const H = 2.9; // pé-direito
const L = ZT - ZF, ZC = (ZF + ZT) / 2;
const MESA = { x: -2.7, w: 1.4, d: 0.62, y: 0.75 };
const JAN = { x0: MESA.x - 0.5, x1: MESA.x + 0.5, y0: 1.1, y1: 2.1 }; // janela de 1 × 1 m centrada sobre a mesa

export const LIMITES_QUARTO_BIA: LimitesCenario = { limiteX: 1.5, limiteZ: [-1.0, 3.0], ceu: '#a9dcf2' };

/** Piso de tábuas de 30 cm em dois tons próximos, correndo para a câmera. */
const TABUAS: { p: V3; t: V3 }[] = [];
for (let i = 0; i < (2 * X) / 0.3; i += 2) TABUAS.push({ p: [-X + 0.15 + i * 0.3, -0.01, ZC], t: [0.3, 0.02, L] });

/** Paredes lilás (sem sombra própria: o sol do palco ilumina o quarto todo), com o vão da janela e rodapé branco. */
const Paredes: React.FC = () => {
  const e = 0.2, zc = ZF - e / 2;
  const blocos: [number, number, number, number][] = [
    [-X - e, JAN.x0, 0, H], [JAN.x1, X + e, 0, H], [JAN.x0, JAN.x1, 0, JAN.y0], [JAN.x0, JAN.x1, JAN.y1, H],
  ];
  return (
    <group>
      {blocos.map(([x0, x1, y0, y1], i) => <Caixa key={i} p={[(x0 + x1) / 2, (y0 + y1) / 2, zc]} t={[x1 - x0, y1 - y0, e]} cor={C.parede} sombra={false} />)}
      {[-1, 1].map((s) => (
        <group key={s}>
          <Caixa p={[s * (X + e / 2), H / 2, ZC]} t={[e, H, L]} cor={C.parede} sombra={false} />
          <Caixa p={[s * (X - 0.03), 0.06, ZC]} t={[0.06, 0.12, L]} cor={C.rodape} sombra={false} />
        </group>
      ))}
      <Caixa p={[0, 0.06, ZF + 0.03]} t={[2 * X, 0.12, 0.06]} cor={C.rodape} sombra={false} />
    </group>
  );
};

/** Janela: batente branco largo, cruzeta, vidro claro, peitoril e cortinas amarelas presas num varão. */
const Janela: React.FC = () => {
  const { x0, x1, y0, y1 } = JAN, xm = (x0 + x1) / 2, w = x1 - x0, h = y1 - y0, ym = (y0 + y1) / 2;
  return (
    <group>
      <Caixa p={[xm, y1 + 0.05, ZF + 0.02]} t={[w + 0.2, 0.1, 0.06]} cor={C.batente} sombra={false} />
      <Caixa p={[x0 - 0.05, ym, ZF + 0.02]} t={[0.1, h, 0.06]} cor={C.batente} sombra={false} />
      <Caixa p={[x1 + 0.05, ym, ZF + 0.02]} t={[0.1, h, 0.06]} cor={C.batente} sombra={false} />
      <Caixa p={[xm, ym, ZF - 0.1]} t={[0.08, h, 0.06]} cor={C.batente} sombra={false} />
      <Caixa p={[xm, ym, ZF - 0.1]} t={[w, 0.08, 0.06]} cor={C.batente} sombra={false} />
      <mesh position={[xm, ym, ZF - 0.15]} material={vidro(C.vidro, 0.12)}><boxGeometry args={[w, h, 0.01]} /></mesh>
      <Caixa p={[xm, y0 - 0.04, ZF + 0.04]} t={[w + 0.3, 0.08, 0.16]} cor={C.batente} />
      {/* varão e cortinas abertas, uma de cada lado */}
      <Haste a={[x0 - 0.45, y1 + 0.22, ZF + 0.14]} b={[x1 + 0.45, y1 + 0.22, ZF + 0.14]} r={0.03} cor={C.madeira2} />
      {[-1, 1].map((s) => (
        <group key={s}>
          <Caixa p={[xm + s * (w / 2 + 0.26), (y0 - 0.15 + y1 + 0.2) / 2, ZF + 0.16]} t={[0.3, y1 + 0.35 - y0, 0.1]} cor={C.cortina} />
          <Cilindro p={[x0 - 0.45 + (s > 0 ? w + 0.9 : 0), y1 + 0.17, ZF + 0.14]} r={0.05} h={0.1} cor={C.madeira2} />
        </group>
      ))}
    </group>
  );
};

/** Caderno aberto deitado (≈ 31 × 22 cm): capa colorida, duas folhas, espiral e "98%" circulado em vermelho. */
const Caderno: React.FC<{ p: V3; giro: number; capa: string }> = ({ p, giro, capa }) => (
  <group position={p} rotation={[0, giro, 0]}>
    <Caixa p={[0, 0.004, 0]} t={[0.32, 0.008, 0.23]} cor={capa} />
    {[-1, 1].map((s) => <Caixa key={s} p={[s * 0.079, 0.012, 0]} t={[0.148, 0.008, 0.21]} cor={C.papel} />)}
    <Caixa p={[0, 0.014, 0]} t={[0.012, 0.012, 0.2]} cor={C.espiral} sombra={false} />
    {/* nota da professora: número de traço grosso e círculo liso (torus), os dois em vermelho */}
    <Numero txt="98%" p={[0, 0.019, 0.04]} r={[-Math.PI / 2, 0, 0]} l={0.05} a={0.085} e={0.014} esp={0.018} prof={0.003} cor={C.nota} />
    <mesh position={[0, 0.019, 0]} rotation={[-Math.PI / 2, 0, 0]} scale={[1, 0.72, 1]} material={mat(C.nota)}><torusGeometry args={[0.125, 0.008, 8, 48]} /></mesh>
  </group>
);

/** Escrivaninha clara (tampo, 4 pernas, gaveta), luminária, cadernos e banqueta guardada embaixo. */
const Escrivaninha: React.FC = () => {
  const { x, w, d, y } = MESA, zc = ZF + 0.04 + d / 2;
  return (
    <group>
      <Caixa p={[x, y - 0.02, zc]} t={[w, 0.04, d]} cor={C.madeira} />
      <Caixa p={[x + 0.3, y - 0.1, zc + 0.02]} t={[0.5, 0.12, d - 0.1]} cor={C.madeira2} />
      <Caixa p={[x + 0.3, y - 0.1, zc + d / 2 - 0.02]} t={[0.14, 0.04, 0.04]} cor="#ffffff" />
      {([[-1, -1], [1, -1], [-1, 1], [1, 1]] as const).map(([sx, sz]) => (
        <Caixa key={`${sx}${sz}`} p={[x + sx * (w / 2 - 0.06), (y - 0.04) / 2, zc + sz * (d / 2 - 0.06)]} t={[0.08, y - 0.04, 0.08]} cor={C.madeira2} />
      ))}
      {/* luminária: base, haste em dois trechos e cúpula cônica com a lâmpada acesa */}
      <Cilindro p={[x - 0.56, y, ZF + 0.22]} r={0.09} h={0.03} cor={C.luminaria} />
      <Haste a={[x - 0.56, y + 0.03, ZF + 0.22]} b={[x - 0.52, y + 0.4, ZF + 0.22]} r={0.018} cor={C.luminaria} />
      <Haste a={[x - 0.52, y + 0.4, ZF + 0.22]} b={[x - 0.36, y + 0.48, ZF + 0.3]} r={0.018} cor={C.luminaria} />
      <mesh position={[x - 0.33, y + 0.43, ZF + 0.3]} rotation={[0, 0, 0.5]} material={mat(C.luminaria)} castShadow receiveShadow>
        <cylinderGeometry args={[0.04, 0.12, 0.15, 24]} />
      </mesh>
      <mesh position={[x - 0.29, y + 0.35, ZF + 0.3]} material={mat(C.lampada, { brilho: 1.2 })}><sphereGeometry args={[0.05, 16, 10]} /></mesh>
      {/* três cadernos abertos, cada um com 98% */}
      {[-0.22, 0.12, 0.47].map((dx, i) => (
        <Caderno key={dx} p={[x + dx, y, zc + 0.06 - (i % 2) * 0.05]} giro={[0.1, -0.05, -0.14][i]} capa={C.capa[i]} />
      ))}
      {/* lápis e banqueta */}
      <Haste a={[x + 0.62, y + 0.012, zc - 0.18]} b={[x + 0.62, y + 0.012, zc + 0.02]} r={0.012} cor={C.cortina} />
      <Cilindro p={[x - 0.15, 0, zc + 0.05]} r={0.12} r2={0.16} h={0.04} cor={C.banco} />
      <Cilindro p={[x - 0.15, 0.04, zc + 0.05]} r={0.04} h={0.36} cor={C.madeira2} />
      <Cilindro p={[x - 0.15, 0.4, zc + 0.05]} r={0.18} h={0.06} cor={C.banco} />
    </group>
  );
};

/** Pôster de planetas acima das cabeças (0,6 × 0,8 m): fundo azul-noite, Sol, Terra, Saturno com anel e Marte. */
const Poster: React.FC<{ p: V3 }> = ({ p }) => {
  const planeta = (x: number, y: number, r: number, cor: string) => (
    <mesh key={cor} position={[x, y, 0.04]} scale={[1, 1, 0.35]} material={mat(cor)}><sphereGeometry args={[r, 24, 14]} /></mesh>
  );
  return (
    <group position={p}>
      <Caixa p={[0, 0, 0.01]} t={[0.68, 0.88, 0.02]} cor={C.moldura} />
      <Caixa p={[0, 0, 0.03]} t={[0.6, 0.8, 0.02]} cor={C.poster} sombra={false} />
      {planeta(-0.16, 0.24, 0.12, C.sol)}
      {planeta(0.15, 0.17, 0.06, C.terra)}
      {planeta(-0.04, -0.08, 0.075, C.saturno)}
      <mesh position={[-0.04, -0.08, 0.06]} rotation={[0, 0, 0.35]} scale={[1, 0.38, 1]} material={mat(C.anel)}><torusGeometry args={[0.12, 0.016, 8, 32]} /></mesh>
      {planeta(0.17, -0.25, 0.05, C.marte)}
    </group>
  );
};

/** Estante clara de 4 prateleiras com livros coloridos, globo e plantinha em cima. */
const Estante: React.FC<{ x: number }> = ({ x }) => {
  const w = 0.92, d = 0.32, h = 1.85, zc = ZF + 0.04 + d / 2, e = 0.04;
  const prat = [0.1, 0.52, 0.94, 1.36];
  return (
    <group>
      {[-1, 1].map((s) => <Caixa key={s} p={[x + s * (w / 2 - e / 2), h / 2, zc]} t={[e, h, d]} cor={C.madeira} />)}
      <Caixa p={[x, h - e / 2, zc]} t={[w, e, d]} cor={C.madeira} />
      <Caixa p={[x, h / 2, ZF + 0.05]} t={[w, h, 0.02]} cor={C.madeira2} sombra={false} />
      {prat.map((y, j) => (
        <group key={y}>
          <Caixa p={[x, y - e / 2, zc]} t={[w - 2 * e, e, d]} cor={C.madeira} />
          {/* livros em pé, de larguras e alturas variadas */}
          {Array.from({ length: 6 - (j % 2) }, (_, i) => {
            const lb = 0.08 + ((i + j) % 3) * 0.015, hb = 0.24 + ((i * 7 + j * 3) % 4) * 0.03;
            const xb = x - w / 2 + e + 0.03 + i * 0.105 + lb / 2;
            return <Caixa key={i} p={[xb, y + hb / 2, zc + 0.02]} t={[lb, hb, 0.22]} cor={C.livros[(i + j * 2) % C.livros.length]} />;
          })}
        </group>
      ))}
      {/* em cima: globo e vasinho */}
      <Cilindro p={[x - 0.2, h, zc]} r={0.07} h={0.04} cor={C.madeira2} />
      <mesh position={[x - 0.2, h + 0.17, zc]} material={mat(C.terra)} castShadow><sphereGeometry args={[0.12, 20, 14]} /></mesh>
      <Cilindro p={[x + 0.22, h, zc]} r={0.08} r2={0.06} h={0.13} cor={C.vaso} />
      <mesh position={[x + 0.22, h + 0.24, zc]} material={mat(C.folha, { flat: true })} castShadow><icosahedronGeometry args={[0.14, 1]} /></mesh>
    </group>
  );
};

/** Cama de solteiro encostada no canto direito, cabeceira na parede do fundo. */
const Cama: React.FC<{ x: number }> = ({ x }) => {
  const w = 0.95, comp = 1.95, z0 = ZF + 0.04, zc = z0 + comp / 2;
  return (
    <group>
      <Caixa p={[x, 0.17, zc]} t={[w, 0.26, comp]} cor={C.madeira} />
      <Caixa p={[x, 0.36, zc]} t={[w - 0.06, 0.14, comp - 0.06]} cor={C.colchao} />
      <Caixa p={[x, 0.5, z0 + 0.04]} t={[w + 0.06, 1.0, 0.08]} cor={C.madeira2} />
      <Caixa p={[x, 0.5, z0 + 0.2]} t={[w - 0.25, 0.14, 0.32]} cor={C.travesseiro} />
      {/* edredom com dobra mais clara */}
      <Caixa p={[x, 0.46, zc + 0.3]} t={[w + 0.02, 0.08, comp - 0.66]} cor={C.edredom} />
      <Caixa p={[x, 0.5, zc - 0.3]} t={[w + 0.02, 0.08, 0.2]} cor={C.edredom2} />
      <Caixa p={[x - w / 2 - 0.01, 0.3, zc + 0.3]} t={[0.08, 0.38, comp - 0.66]} cor={C.edredom} />
    </group>
  );
};

export const QuartoBia: React.FC = () => (
  <>
    <LuzInterior hemi={{ ceu: '#fbf7ff', chao: '#e6dcef', forca: 2.1 }} sol={1.8} maciez={10} />
    <PlanoFoco z={-1.0} />
    {/* piso: base e tábuas 2 cm acima */}
    <Caixa p={[0, -0.045, ZC]} t={[2 * X + 0.4, 0.05, L]} cor={C.piso} sombra={false} />
    <Caixas itens={TABUAS} cor={C.piso2} />
    <Cilindro p={[0.1, 0.0, -0.4]} r={1.2} h={0.02} cor={C.tapete} s={[1.2, 1, 0.8]} sombra={false} seg={40} />
    <Paredes />
    <Janela />
    {/* teto claro, levemente aceso, sem sombra, com plafon */}
    <Caixa p={[0, H + 0.05, ZC]} t={[2 * X + 0.4, 0.1, L]} cor={C.teto} sombra={false} m={mat(C.teto, { brilho: 0.4 })} />
    <mesh position={[0, H - 0.04, -0.6]} material={mat('#fffdf4', { brilho: 0.9 })}><cylinderGeometry args={[0.3, 0.3, 0.08, 28]} /></mesh>
    <Escrivaninha />
    <Poster p={[0.1, 2.08, ZF]} />
    <Estante x={2.2} />
    <Cama x={3.2} />
  </>
);
