// Efeito `brilho`: estrelinhas brancas de quatro pontas piscando em anel em volta do objeto em destaque.
// Anel regular (mesmo espaço entre as estrelas) que gira devagar; cada estrela pisca e gira no seu tempo.
// Estrela branca chapada, sem halo e sem sombra. Tudo em função do quadro (ritmo sorteado com random do remotion).
import React from 'react';
import { random } from 'remotion';
import { mat, suave, TAU, type V3 } from './base';

const BRANCO = '#ffffff';
const C = { ouro: '#f2b632', ouroEsc: '#d18f1c', madeira: '#6e452c', podio: '#c8372f', faixa: '#f2b632' };

/** Estrela de 4 pontas: 4 pirâmides achatadas + miolo. Ponta a 1 m do centro (escala depois). */
const Estrela4: React.FC = () => {
  const m = mat(BRANCO, 1, 0.85);
  return (
    <group scale={[1, 1, 0.25]}>
      {[0, 1, 2, 3].map((k) => (
        <group key={k} rotation={[0, 0, (k * TAU) / 4]}>
          <mesh position={[0, 0.5, 0]} material={m}><cylinderGeometry args={[0, 0.24, 1, 4]} /></mesh>
        </group>
      ))}
      <mesh material={m}><sphereGeometry args={[0.22, 12, 8]} /></mesh>
    </group>
  );
};

export type PropsBrilho = {
  quadro: number;
  /** Centro do objeto em destaque. */
  centro?: V3;
  /** Semieixos do anel em volta do objeto (largura, altura), em metros. */
  raio?: [number, number];
  /** Tamanho da estrela (do centro até a ponta), em metros. */
  tamanho?: number;
  /** Quantas estrelas no anel. */
  n?: number;
  semente?: string;
};

/** Só o brilho: anel de estrelas em volta de `centro` (use nos planos, sobre qualquer objeto). */
export const Brilho: React.FC<PropsBrilho> = ({ quadro, centro = [0, 1, 0], raio = [0.5, 0.46], tamanho = 0.085, n = 8, semente = 'brilho' }) => {
  const entra = suave(quadro / 12);
  const giroAnel = (quadro / 240) * TAU; // uma volta a cada 8 s
  return (
    <group position={centro}>
      {Array.from({ length: n }, (_, i) => {
        // anel regular, começando meio passo fora do eixo (nenhuma estrela bem embaixo, no chão)
        const ang = ((i + 0.5) / n) * TAU + giroAnel;
        const x = raio[0] * Math.cos(ang), y = raio[1] * Math.sin(ang);
        // pisca: ciclo próprio de 1,0 a 1,5 s; nunca some de todo (mín. 55%), para não virar pontinho
        const periodo = 30 + Math.floor(random(`${semente}-p${i}`) * 15);
        const fase = random(`${semente}-f${i}`);
        const p = 0.5 + 0.5 * Math.sin((quadro / periodo + fase) * TAU);
        const esc = tamanho * (0.55 + 0.45 * p * p) * entra;
        const giro = (quadro / periodo) * 0.9 + i;
        return (
          <group key={i} position={[x, y, 0.3]} rotation={[0, 0, giro]} scale={Math.max(0.001, esc)}>
            <Estrela4 />
          </group>
        );
      })}
    </group>
  );
};

/** Troféu dourado de 0,5 m (taça com alças, haste e base de madeira). Origem no centro da base. */
const Trofeu: React.FC = () => (
  <group>
    <mesh position={[0, 0.05, 0]} material={mat(C.madeira)} castShadow receiveShadow><boxGeometry args={[0.24, 0.1, 0.24]} /></mesh>
    <mesh position={[0, 0.12, 0]} material={mat(C.ouroEsc)} castShadow><cylinderGeometry args={[0.07, 0.09, 0.04, 20]} /></mesh>
    <mesh position={[0, 0.2, 0]} material={mat(C.ouro)} castShadow><cylinderGeometry args={[0.025, 0.03, 0.12, 12]} /></mesh>
    <mesh position={[0, 0.27, 0]} material={mat(C.ouro)} castShadow><sphereGeometry args={[0.045, 14, 10]} /></mesh>
    {/* taça: tronco de cone + fundo arredondado */}
    <mesh position={[0, 0.39, 0]} material={mat(C.ouro)} castShadow receiveShadow><cylinderGeometry args={[0.15, 0.09, 0.2, 24]} /></mesh>
    <mesh position={[0, 0.3, 0]} material={mat(C.ouro)} castShadow><sphereGeometry args={[0.09, 20, 10, 0, TAU, Math.PI / 2, Math.PI / 2]} /></mesh>
    <mesh position={[0, 0.49, 0]} rotation={[Math.PI / 2, 0, 0]} material={mat(C.ouroEsc)}><torusGeometry args={[0.15, 0.015, 8, 28]} /></mesh>
    {/* alças */}
    {[-1, 1].map((l) => (
      <mesh key={l} position={[0.15 * l, 0.4, 0]} rotation={[0, 0, l > 0 ? -Math.PI / 2 : Math.PI / 2]} material={mat(C.ouro)} castShadow>
        <torusGeometry args={[0.065, 0.018, 8, 16, Math.PI]} />
      </mesh>
    ))}
  </group>
);

/** Pódio de 1º lugar (caixa com faixa e o "1" em caixas). Origem no chão. */
const Podio: React.FC = () => (
  <group>
    <mesh position={[0, 0.2, 0]} material={mat(C.podio)} castShadow receiveShadow><boxGeometry args={[0.5, 0.4, 0.45]} /></mesh>
    <mesh position={[0, 0.37, 0]} material={mat(C.faixa)} receiveShadow><boxGeometry args={[0.52, 0.06, 0.47]} /></mesh>
    {/* "1" na frente */}
    <mesh position={[0, 0.17, 0.235]} material={mat(C.faixa)}><boxGeometry args={[0.05, 0.2, 0.02]} /></mesh>
    <mesh position={[-0.035, 0.245, 0.235]} rotation={[0, 0, 0.7]} material={mat(C.faixa)}><boxGeometry args={[0.05, 0.08, 0.02]} /></mesh>
  </group>
);

const PODIO: V3 = [1.05, 0, 0.35];

/** Peça da vitrine: troféu num pódio ao lado do personagem, com o brilho em volta dele. */
export const BrilhoTrofeu: React.FC<{ quadro: number }> = ({ quadro }) => (
  <group>
    <group position={PODIO}>
      <Podio />
      <group position={[0, 0.4, 0]}><Trofeu /></group>
    </group>
    <Brilho quadro={quadro} centro={[PODIO[0], 0.7, PODIO[2]]} />
  </group>
);
