// Vitrine das peças em lote: o mesmo palco para qualquer peça (luz, câmera, Téo e acabamento iguais), por tipo.
// Render: npx remotion still src/index.ts VitrineLote saida/x.png --frame=90 --props=arquivo.json  ({"lote":"...","nome":"...","soCenario":false})
import React from 'react';
import { AbsoluteFill, useCurrentFrame, useVideoConfig } from 'remotion';
import { ThreeCanvas } from '@remotion/three';
import { Boneco } from '../kit/Boneco';
import { Quadra } from '../kit/Quadra';
import { Luz } from '../kit/Luz';
import { Camera, type ChaveCam } from '../kit/Camera';
import { Foco, Acabamento } from '../kit/Pos';
import { ELENCO } from '../kit/elenco';
import { misturar, pose } from '../kit/poses';
import { LOTES } from './lotes/registro';

const sorriso = { boca: 'sorriso' as const };

export const VitrineLote: React.FC<{ lote: string; nome: string; soCenario?: boolean }> = ({ lote, nome, soCenario = false }) => {
  const q = useCurrentFrame();
  const { width, height, durationInFrames } = useVideoConfig();
  const peca = (LOTES[lote] ?? []).find((p) => p.nome === nome);
  if (!peca) return <AbsoluteFill style={{ background: '#400', color: 'white', fontSize: 60, padding: 80 }}>peça {lote}/{nome} não encontrada</AbsoluteFill>;
  const ceu = peca.tipo === 'cenario' ? peca.limites.ceu : '#9fd3ee';
  const fim = durationInFrames - 1;

  let chaves: ChaveCam[]; let foco: number;
  if (peca.tipo === 'cenario') { chaves = [{ q: 0, pos: [0, 1.9, 6.2], alvo: [0, 1.1, 0], fov: 40 }, { q: fim, pos: [0.6, 1.8, 5.2], alvo: [0, 1.1, 0], fov: 40 }]; foco = 5.6; }
  else if (peca.tipo === 'objeto') { chaves = [{ q: 0, pos: [1.2, 1.3, 2.4], alvo: [0.75, 0.5, 0], fov: 36 }, { q: fim, pos: [1.0, 1.2, 2.0], alvo: [0.75, 0.5, 0], fov: 36 }]; foco = 2.1; }
  else if (peca.tipo === 'personagem') { chaves = [{ q: 0, pos: [0, 1.6, 4.4], alvo: [0, 1.0, 0], fov: 36 }, { q: fim, pos: [0.3, 1.6, 4.0], alvo: [0, 1.0, 0], fov: 36 }]; foco = 4.1; }
  else { chaves = [{ q: 0, pos: [0, 1.75, 4.2], alvo: [0, 1.0, 0], fov: 36 }, { q: fim, pos: [0, 1.7, 3.6], alvo: [0, 1.0, 0], fov: 36 }]; foco = 3.9; }

  const juntas = peca.tipo === 'acao'
    ? misturar(pose('parado'), { ...pose('parado'), ...peca.pose, ...(peca.animar ? peca.animar(q) : {}) }, (q - 20) / 25)
    : pose('parado');

  return (
    <AbsoluteFill style={{ backgroundColor: ceu }}>
      <ThreeCanvas width={width} height={height} shadows flat gl={{ antialias: true, preserveDrawingBuffer: true }} camera={{ fov: 40, position: chaves[0].pos }}>
        <color attach="background" args={[ceu]} />
        <Camera chaves={chaves} quadro={q} />
        <Luz ceu={ceu} />
        {peca.tipo === 'cenario' ? <peca.Componente /> : <Quadra />}
        {!soCenario && peca.tipo === 'cenario' && (<>
          <Boneco v={ELENCO.teo} e={sorriso} pos={[-0.7, 0, 0.5]} giro={10} />
          <Boneco v={ELENCO.bia} e={sorriso} pos={[0.7, 0, 0.5]} giro={-10} />
        </>)}
        {!soCenario && peca.tipo === 'personagem' && (<>
          <Boneco v={peca.visual} e={sorriso} pos={[-0.55, 0, 0]} giro={10} />
          <Boneco v={ELENCO.teo} e={sorriso} pos={[0.55, 0, 0]} giro={-10} />
        </>)}
        {!soCenario && (peca.tipo === 'acao' || peca.tipo === 'efeito') && <Boneco v={ELENCO.teo} j={juntas} e={sorriso} pos={[0, 0, 0]} />}
        {!soCenario && peca.tipo === 'objeto' && (<>
          <Boneco v={ELENCO.teo} e={sorriso} pos={[0, 0, 0]} />
          {peca.apoio === 'mesa' && (
            <mesh position={[0.75, 0.375, 0]} castShadow receiveShadow><boxGeometry args={[0.5, 0.75, 0.5]} /><meshStandardMaterial color="#d9d2c3" roughness={0.85} /></mesh>
          )}
          <group position={[0.75, peca.apoio === 'mesa' ? 0.75 : 0, 0]}><peca.Componente /></group>
        </>)}
        {!soCenario && peca.tipo === 'efeito' && <peca.Componente quadro={q} />}
        <Foco foco={foco} />
      </ThreeCanvas>
      <Acabamento quadro={q} />
    </AbsoluteFill>
  );
};
