import React from 'react';
import { Caixa, mat, numero } from './base';

const giz = '#ffffff';
const escrita = [
  ...numero('4', -0.43, 0.84, 0.13, 0.23, 0.024, giz),
  ...numero('10', -0.10, 0.84, 0.13, 0.23, 0.024, giz, 0.04),
  ...numero('=', 0.29, 0.84, 0.15, 0.23, 0.024, giz),
];
// Resultado alinhado numa segunda linha, com espaço ao redor dos pontos.
let cursor = -0.895;
for (const caractere of '1.048.576') {
  if (caractere === '.') {
    escrita.push({ x: cursor + 0.014, y: 0.325, largura: 0.028, altura: 0.028, cor: giz });
    cursor += 0.09;
  } else {
    escrita.push(...numero(caractere, cursor, 0.43, 0.16, 0.24, 0.026, giz));
    cursor += 0.22;
  }
}

// Quadro de 2 × 1,2 m, base em y=0 e frente para +Z.
export const Lousa: React.FC = () => (
  <group>
    <Caixa p={[0, 0.6, -0.04]} t={[1.84, 1.04, 0.08]} cor="#357e60" />
    {[-1, 1].map((lado) => (
      <group key={lado}>
        <Caixa p={[lado * 0.96, 0.6, 0]} t={[0.08, 1.04, 0.16]} cor="#875531" />
        <Caixa p={[0, 0.6 + lado * 0.56, 0]} t={[2, 0.08, 0.16]} cor="#a56e42" />
      </group>
    ))}
    {/* Giz chapado, com 2 cm de ar até o fundo verde. */}
    {escrita.map((m, i) => (
      <Caixa key={i} p={[m.x, m.y, 0.0215]} t={[m.largura, m.altura, 0.003]}
        cor={m.cor} brilho={0.15} sombra={false} />
    ))}
    {/* O sinal ^ é feito com duas caixas inclinadas. */}
    {[-1, 1].map((lado) => (
      <Caixa key={lado} p={[-0.2 + lado * 0.026, 0.88, 0.0215]}
        t={[0.024, 0.08, 0.003]} r={[0, 0, lado * Math.PI / 4]}
        cor={giz} brilho={0.15} sombra={false} />
    ))}
    {/* Calha de madeira integrada à moldura inferior. */}
    <Caixa p={[0, 0.04, 0.13]} t={[1.86, 0.08, 0.18]} cor="#875531" />
    <Caixa p={[0, 0.08, 0.215]} t={[1.86, 0.08, 0.03]} cor="#a56e42" />
    {[-0.48, 0, 0.48].map((x) => (
      <mesh key={x} position={[x, 0.094, 0.14]} rotation={[0, 0, Math.PI / 2]}
        material={mat(giz)} castShadow receiveShadow>
        <cylinderGeometry args={[0.014, 0.014, 0.13, 10]} />
      </mesh>
    ))}
  </group>
);
