import React from 'react';
import { Composition } from 'remotion';
import { TesteTeo } from './cenas/TesteTeo';
import { Cena } from './ficha/Cena';
import { validarFicha, type FichaEntrada } from './ficha/schema';
import fichaTeste from '../fichas/teo-teste.json';
import { Vitrine, DURACAO_VITRINE, type PecaVitrine } from './oficina/Vitrine';
import { VitrineLote } from './oficina/VitrineLote';

export const Root: React.FC = () => (
  <>
    <Composition id="TesteTeo" component={TesteTeo} durationInFrames={150} fps={30} width={1920} height={1080} defaultProps={{ soCenario: false }} />
    {/* Composição única de produção: toda micro-cena é esta, mudando só a ficha (--props) */}
    <Composition id="Ficha" component={Cena} fps={30} width={1920} height={1080} durationInFrames={150}
      defaultProps={{ ficha: fichaTeste as FichaEntrada, soCenario: false }}
      calculateMetadata={({ props }) => ({ durationInFrames: validarFicha(props.ficha).duracao })} />
    {/* Oficina: vitrine de uma peça de um autor (comparação Claude x GPT) */}
    <Composition id="Vitrine" component={Vitrine} fps={30} width={1920} height={1080} durationInFrames={DURACAO_VITRINE}
      defaultProps={{ autor: 'claude', peca: 'cenario' as PecaVitrine, soCenario: false }} />
    {/* Oficina automática (lotes da noite): qualquer peça de qualquer lote */}
    <Composition id="VitrineLote" component={VitrineLote} fps={30} width={1920} height={1080} durationInFrames={DURACAO_VITRINE}
      defaultProps={{ lote: '', nome: '', soCenario: false }} />
  </>
);
