// Objetos das demos do r07 (tamanho real, só primitivas, cores chapadas, cache de material por cor).
import * as THREE from 'three';
import React from 'react';

const cache = new Map<string, THREE.MeshStandardMaterial>();
export const mat = (cor: string) => {
  let m = cache.get(cor);
  if (!m) { m = new THREE.MeshStandardMaterial({ color: cor, roughness: 0.85 }); cache.set(cor, m); }
  return m;
};
type V3 = [number, number, number];
const Caixa: React.FC<{ p: V3; t: V3; cor: string; r?: V3 }> = ({ p, t, cor, r = [0, 0, 0] }) => (
  <mesh position={p} rotation={r} material={mat(cor)} castShadow receiveShadow><boxGeometry args={t} /></mesh>
);
const Bola: React.FC<{ p: V3; r: number; cor: string; esc?: V3 }> = ({ p, r, cor, esc = [1, 1, 1] }) => (
  <mesh position={p} scale={esc} material={mat(cor)} castShadow receiveShadow><sphereGeometry args={[r, 16, 10]} /></mesh>
);

// ── Escova de dentes (19 cm). Origem no meio das cerdas (a parte que entra na boca); cabo para +Y ──
// Cabo turquesa (contrasta com pele, camisa e quadra), pescoço fino, cerdas brancas com pasta azul.
const E = { cabo: '#13b5a8', pega: '#0d7f76', cerda: '#ffffff', pasta: '#5fc8f5' };
export const Escova: React.FC = () => (
  <group>
    {/* cabeça: base turquesa e cerdas para +Z (contra os dentes) */}
    <Caixa p={[0, 0, -0.006]} t={[0.018, 0.04, 0.01]} cor={E.cabo} />
    <Caixa p={[0, 0, 0.006]} t={[0.016, 0.034, 0.016]} cor={E.cerda} />
    <Caixa p={[0, 0, 0.016]} t={[0.01, 0.028, 0.006]} cor={E.pasta} />
    {/* pescoço e cabo (mais grosso na pega), com ponta arredondada */}
    <mesh position={[0, 0.045, -0.006]} material={mat(E.cabo)} castShadow><cylinderGeometry args={[0.006, 0.006, 0.05, 10]} /></mesh>
    <mesh position={[0, 0.13, -0.006]} material={mat(E.cabo)} castShadow><capsuleGeometry args={[0.011, 0.11, 4, 12]} /></mesh>
    <mesh position={[0, 0.125, -0.006]} material={mat(E.pega)} castShadow><cylinderGeometry args={[0.0125, 0.0125, 0.05, 12]} /></mesh>
  </group>
);

/** Espuma de pasta no canto da boca: bolinhas que pulsam com a fase. */
export const Espuma: React.FC<{ fase: number }> = ({ fase }) => (
  <group>
    {([[-0.035, 0.004, 0.016], [0, -0.012, 0.014], [0.03, 0.006, 0.013], [0.012, 0.016, 0.01], [-0.012, -0.022, 0.009]] as V3[]).map(([x, y, r], i) => (
      <Bola key={i} p={[x, y, 0]} r={r * (1 + 0.2 * Math.sin(fase + i * 1.7))} cor="#f6fbff" />
    ))}
  </group>
);

/** Marcas de vaivém: dois traços brancos curvos por fora da mão (origem no centro da mão; abrem para +X). */
export const MarcasVaivem: React.FC<{ abertura: number }> = ({ abertura }) => (
  <group>
    {[0, 1].map((k) => (
      <mesh key={k} position={[0.02 * abertura, 0, 0]} rotation={[0, 0, -Math.PI / 4]} material={mat('#ffffff')}>
        <torusGeometry args={[0.11 + 0.035 * k, 0.007, 6, 16, Math.PI / 2]} />
      </mesh>
    ))}
  </group>
);

// ── Copo de plástico (11 cm). Origem no centro do copo ──
export const Copo: React.FC = () => (
  <group>
    <mesh material={mat('#f27aa8')} castShadow receiveShadow><cylinderGeometry args={[0.042, 0.034, 0.11, 20]} /></mesh>
    <mesh position={[0, 0.056, 0]} rotation={[Math.PI / 2, 0, 0]} material={mat('#c9547f')} castShadow><torusGeometry args={[0.041, 0.005, 6, 20]} /></mesh>
    {/* água por dentro, logo abaixo da borda */}
    <mesh position={[0, 0.04, 0]} material={mat('#9fd8f5')}><cylinderGeometry args={[0.037, 0.037, 0.01, 20]} /></mesh>
  </group>
);
