// Poses do boneco: ângulos das juntas em graus. Toda pose é parcial: o que não está escrito fica no "base".
// Convenções (vista de frente do boneco, que olha para +Z):
//  ombroX/ombroZ: braço para a frente (+X) e para o lado/fora (+Z); cotovelo: dobra do antebraço para a frente.
//  quadril: perna para a frente; joelho: dobra para trás. tronco/cabeca: inclinação (X) e giro (Y).
export type Juntas = {
  troncoX: number; troncoY: number; cabecaX: number; cabecaY: number; cabecaZ: number;
  ombroEX: number; ombroEZ: number; cotoveloE: number;
  ombroDX: number; ombroDZ: number; cotoveloD: number;
  quadrilE: number; joelhoE: number; quadrilD: number; joelhoD: number;
  altura: number; // sobe/desce o corpo (pulo, agachar), em metros
};
export const BASE: Juntas = {
  troncoX: 0, troncoY: 0, cabecaX: 0, cabecaY: 0, cabecaZ: 0,
  ombroEX: 0, ombroEZ: 10, cotoveloE: 8, ombroDX: 0, ombroDZ: 10, cotoveloD: 8,
  quadrilE: 0, joelhoE: 0, quadrilD: 0, joelhoD: 0, altura: 0,
};
export const POSES: Record<string, Partial<Juntas>> = {
  parado: {},
  acenar: { ombroDZ: 150, cotoveloD: 25, cabecaZ: -6 },
  acenar2: { ombroDZ: 135, cotoveloD: 45, cabecaZ: -6 },
  surpreso: { ombroEX: 30, ombroEZ: 40, cotoveloE: 70, ombroDX: 30, ombroDZ: 40, cotoveloD: 70, troncoX: -6, cabecaX: -8 },
  pensar: { ombroDX: 60, ombroDZ: 15, cotoveloD: 130, cabecaZ: 10, cabecaX: 6 },
  bracosAbertos: { ombroEZ: 80, ombroDZ: 80, cotoveloE: 5, cotoveloD: 5 },
  comemorar: { ombroEZ: 160, ombroDZ: 160, cotoveloE: 10, cotoveloD: 10, cabecaX: -12, altura: 0.05 },
  triste: { troncoX: 12, cabecaX: 22, ombroEZ: 4, ombroDZ: 4 },
  andar1: { quadrilE: 25, joelhoE: 10, quadrilD: -20, joelhoD: 25, ombroEX: -20, ombroDX: 20 },
  andar2: { quadrilE: -20, joelhoE: 25, quadrilD: 25, joelhoD: 10, ombroEX: 20, ombroDX: -20 },
  sentar: { quadrilE: 90, joelhoE: 90, quadrilD: 90, joelhoD: 90, altura: -0.24, troncoX: -4 },
};
export const pose = (nome: string): Juntas => ({ ...BASE, ...(POSES[nome] ?? {}) });

const suave = (t: number) => t * t * (3 - 2 * t);
/** Mistura duas poses: t de 0 a 1, com entrada e saída suaves. */
export function misturar(a: Juntas, b: Juntas, t: number): Juntas {
  const k = suave(Math.min(1, Math.max(0, t))); const r = { ...a };
  for (const j of Object.keys(a) as (keyof Juntas)[]) r[j] = a[j] + (b[j] - a[j]) * k;
  return r;
}
/** Linha do tempo de poses: [[quadro, nome], ...]; devolve a pose naquele quadro (transição de `dur` quadros). */
export function poseNoQuadro(chaves: [number, string][], quadro: number, dur = 10): Juntas {
  let atual = pose(chaves[0][1]);
  for (let i = 1; i < chaves.length; i++) {
    const [q, nome] = chaves[i];
    if (quadro < q) break;
    atual = misturar(atual, pose(nome), (quadro - q) / dur);
  }
  return atual;
}
