// Efeito `estrelinhas`: estrelas amarelas de cinco pontas girando e piscando em órbita em volta do personagem.
// A órbita passa na altura do tronco, inclinada e com cada estrela numa altura própria; as de trás somem atrás do corpo.
// Pisca = escala e brilho pulsando com fases diferentes (em todo quadro há estrela acesa e estrela quase apagada).
import React from 'react';
import { mat, suave, TAU, type V3 } from './base';

const AMARELO = '#ffd23a';
const N = 7;

/** Estrela de 5 pontas com 0,1 m do centro à ponta (0,2 m de ponta a ponta): miolo pentagonal + 5 pirâmides achatadas. */
const Estrela5: React.FC<{ brilho: number }> = ({ brilho }) => {
  const m = mat(AMARELO, brilho, 0.85);
  return (
    <group>
      <mesh rotation={[Math.PI / 2, 0, 0]} material={m}><cylinderGeometry args={[0.044, 0.044, 0.04, 5]} /></mesh>
      {[0, 1, 2, 3, 4].map((k) => (
        <group key={k} rotation={[0, 0, (k * TAU) / 5]}>
          <mesh position={[0, 0.068, 0]} scale={[1, 1, 0.5]} material={m}>
            <cylinderGeometry args={[0, 0.04, 0.064, 4]} />
          </mesh>
        </group>
      ))}
    </group>
  );
};

export type PropsEstrelinhas = {
  quadro: number;
  /** Centro da órbita (padrão: meio do tronco do boneco). */
  centro?: V3;
  /** Raio da órbita, em metros. */
  raio?: number;
  /** Quadros por volta completa. */
  volta?: number;
};

export const Estrelinhas: React.FC<PropsEstrelinhas> = ({ quadro, centro = [0, 1.0, 0], raio = 0.62, volta = 90 }) => {
  const q = quadro;
  const entra = suave(q / 15);
  return (
    // órbita inclinada: a frente desce e o fundo sobe, e tomba um pouco de lado
    <group position={centro} rotation={[0.3, 0, 0.12]}>
      {Array.from({ length: N }, (_, i) => {
        const ang = (q / volta) * TAU + (i / N) * TAU;
        const x = raio * Math.sin(ang), z = raio * Math.cos(ang);
        // altura própria de cada estrela (ondula ao longo da volta)
        const y = 0.16 * Math.sin(ang * 2 + i * 1.7);
        // pisca: ciclo de 1 s com fases espalhadas; vai de 25% a 100% de brilho e de 55% a 100% de tamanho
        const p = 0.5 + 0.5 * Math.sin((q / 30) * TAU + (i / N) * TAU * 2);
        const brilho = 0.1 + 0.9 * p;
        const esc = (0.55 + 0.45 * p) * entra;
        // giro no próprio plano: uma volta a cada ~1,7 s, sentido alternado
        const giro = (q / 50) * TAU * (i % 2 ? 1 : -1) + i;
        return (
          <group key={i} position={[x, y, z]} rotation={[-0.3, 0, giro]} scale={Math.max(0.001, esc)}>
            <Estrela5 brilho={brilho} />
          </group>
        );
      })}
    </group>
  );
};
