// Interior para +Z. Corredor dos personagens livre, chão em y=0.
import React from 'react';
import { Caixa, Haste, mat, vidro, type V3 } from './base';

const C = {
  creme: '#f6e8cf', teto: '#fff0d8', pisoClaro: '#f1dfc4', pisoEscuro: '#d5b296',
  barrado: '#e1c6a0', madeira: '#98613e', madeiraClara: '#cc9c68',
  balcao: '#b47c57', tampo: '#f1d6af', metal: '#675b4d',
  pao: '#d99b48', paoClaro: '#edbd75', paoTostado: '#bd7c35', corte: '#f6d79e',
  lousa: '#36594f', giz: '#fff1d4', lampada: '#ffe5b1', telha: '#b96d47',
};

const Piso: React.FC = () => (
  <group>
    {/* Casas de 1,2 m, em dois tons quentes próximos. Topos em y=0. */}
    <Caixa p={[0, -0.16, 1.6]} t={[8.4, 0.12, 12]} cor={C.barrado} sombra={false} />
    {Array.from({ length: 7 }, (_, coluna) =>
      Array.from({ length: 10 }, (_, linha) => (
        <Caixa key={`${coluna}-${linha}`}
          p={[-3.6 + coluna * 1.2, -0.04, -3.8 + linha * 1.2]}
          t={[1.2, 0.08, 1.2]}
          cor={(coluna + linha) % 2 === 0 ? C.pisoClaro : C.pisoEscuro} sombra={false} />
      )),
    )}
  </group>
);

type FormatoPao = 'baguete' | 'redondo' | 'rosca';
const Pao: React.FC<{ p: V3; formato: FormatoPao; tostado?: boolean }> = ({ p, formato, tostado = false }) => (
  <group position={p}>
    {formato === 'baguete' ? (
      <mesh position={[0, 0.12, 0]} rotation={[0, 0, Math.PI / 2]} material={mat(tostado ? C.paoTostado : C.pao)} castShadow receiveShadow>
        <capsuleGeometry args={[0.12, 0.4, 4, 12]} />
      </mesh>
    ) : formato === 'redondo' ? (
      <mesh position={[0, 0.16, 0]} scale={[1.15, 0.8, 1]} material={mat(C.paoClaro)} castShadow receiveShadow>
        <sphereGeometry args={[0.22, 12, 8]} />
      </mesh>
    ) : (
      <mesh position={[0, 0.09, 0]} rotation={[-Math.PI / 2, 0, 0]} material={mat(C.paoTostado)} castShadow receiveShadow>
        <torusGeometry args={[0.2, 0.08, 8, 16]} />
      </mesh>
    )}
    {formato !== 'rosca' && (formato === 'baguete' ? [-0.18, 0, 0.18] : [0]).map((x) => (
      <Caixa key={x} p={[x, formato === 'baguete' ? 0.23 : 0.35, 0.04]}
        t={[0.08, 0.08, 0.18]} r={[0, -0.4, 0]} cor={C.corte} sombra={false} />
    ))}
  </group>
);

const Prateleiras: React.FC = () => (
  <group>
    {/* Sem chapa marrom no fundo: a parede creme continua visível. */}
    {[-3.32, -0.18].map((x) => (
      <Caixa key={x} p={[x, 2.17, -3.43]} t={[0.12, 1.62, 0.66]} cor={C.madeiraClara} />
    ))}
    {[1.66, 2.38].map((y, linha) => (
      <group key={y}>
        <Caixa p={[-1.75, y - 0.06, -3.43]} t={[3.26, 0.12, 0.7]} cor={C.madeiraClara} />
        {[-2.85, -2.1, -1.37, -0.65].map((x, coluna) => (
          <Pao key={x} p={[x, y, -3.3]}
            formato={(['baguete', 'redondo', 'rosca'] as const)[(coluna + linha * 2) % 3]}
            tostado={coluna % 2 === 1} />
        ))}
      </group>
    ))}
    <Caixa p={[-1.75, 2.97, -3.43]} t={[3.38, 0.14, 0.76]} cor={C.madeira} />
  </group>
);

// Traços contínuos de 8 cm. Sem fonte, pixels ou malha de texto.
type Traco = [number, number, number, number];
const LETRAS: Record<string, Traco[]> = {
  P: [[0, 0.14, 0, -0.14], [0, 0.14, 0.16, 0.14], [0.16, 0.14, 0.16, 0], [0, 0, 0.16, 0]],
  A: [[0, -0.14, 0.08, 0.14], [0.08, 0.14, 0.16, -0.14], [0.03, -0.02, 0.13, -0.02]],
  O: [[0, -0.14, 0, 0.14], [0.16, -0.14, 0.16, 0.14], [0, 0.14, 0.16, 0.14], [0, -0.14, 0.16, -0.14]],
  R: [[0, 0.14, 0, -0.14], [0, 0.14, 0.16, 0.14], [0.16, 0.14, 0.16, 0], [0, 0, 0.16, 0], [0.08, 0, 0.18, -0.14]],
  S: [[0.16, 0.14, 0, 0.14], [0, 0.14, 0, 0], [0, 0, 0.16, 0], [0.16, 0, 0.16, -0.14], [0.16, -0.14, 0, -0.14]],
  C: [[0.16, 0.14, 0, 0.14], [0, 0.14, 0, -0.14], [0, -0.14, 0.16, -0.14]],
};

const TracoDeGiz: React.FC<{ a: [number, number]; b: [number, number] }> = ({ a, b }) => (
  <Caixa p={[(a[0] + b[0]) / 2, (a[1] + b[1]) / 2, 0]}
    t={[Math.hypot(b[0] - a[0], b[1] - a[1]) + 0.08, 0.08, 0.08]}
    r={[0, 0, Math.atan2(b[1] - a[1], b[0] - a[0])]} cor={C.giz} sombra={false} />
);

// Dígitos menores, com segmentos unidos para ler como traços de giz.
const SEGMENTOS = { 0: [0, 1, 2, 3, 4, 5], 2: [0, 1, 6, 4, 3], 5: [0, 5, 6, 2, 3] } as const;
const TRACOS_DIGITO: Traco[] = [
  [0, 0.16, 0.18, 0.16], [0.18, 0.16, 0.18, 0], [0.18, 0, 0.18, -0.16],
  [0, -0.16, 0.18, -0.16], [0, -0.16, 0, 0], [0, 0, 0, 0.16], [0, 0, 0.18, 0],
];

const LinhaDePreco: React.FC<{ y: number; nome: string; unidade: 2 | 5; centavos: 0 | 5 }> = ({ y, nome, unidade, centavos }) => (
  <group position={[-1.19, y, 0]}>
    {nome.split('').map((letra, i) => (
      <group key={i} position={[i * 0.24, 0, 0]}>
        {LETRAS[letra].map(([x0, y0, x1, y1], j) => <TracoDeGiz key={j} a={[x0, y0]} b={[x1, y1]} />)}
      </group>
    ))}
    {([unidade, centavos, 0] as const).map((valor, i) => (
      <group key={i} position={[1.46 + i * 0.32 + (i > 0 ? 0.08 : 0), 0, 0]}>
        {SEGMENTOS[valor].map((indice) => {
          const [x0, y0, x1, y1] = TRACOS_DIGITO[indice];
          return <TracoDeGiz key={indice} a={[x0, y0]} b={[x1, y1]} />;
        })}
      </group>
    ))}
    <Caixa p={[1.73, -0.17, 0]} t={[0.08, 0.12, 0.08]} r={[0, 0, -0.2]} cor={C.giz} sombra={false} />
  </group>
);

const PlacaDePrecos: React.FC = () => (
  <group position={[1.46, 2.68, -3.7]}>
    <Caixa p={[0, 0, 0]} t={[2.84, 1.12, 0.12]} cor={C.madeira} />
    <Caixa p={[0, 0, 0.14]} t={[2.62, 0.9, 0.12]} cor={C.lousa} />
    <group position={[0, 0, 0.26]}>
      <LinhaDePreco y={0.23} nome="PAO" unidade={2} centavos={5} />
      <LinhaDePreco y={-0.23} nome="ROSCA" unidade={5} centavos={0} />
    </group>
  </group>
);

const Expositor: React.FC = () => (
  <group position={[-2.18, 1.1, -1.99]}>
    <Caixa p={[0, 0.05, 0]} t={[1.36, 0.1, 0.7]} cor={C.madeira} />
    <Caixa p={[0, 0.16, 0]} t={[1.16, 0.12, 0.5]} cor={C.tampo} />
    <Pao p={[-0.3, 0.22, 0]} formato="redondo" />
    <Pao p={[0.3, 0.22, 0]} formato="rosca" />
    {[-0.64, 0.64].map((x) => (
      <group key={x}>
        <Caixa p={[x, 0.3, 0.32]} t={[0.08, 0.6, 0.08]} cor={C.metal} />
        <mesh position={[x, 0.3, 0]} material={vidro('#d1ece7')} receiveShadow><boxGeometry args={[0.08, 0.52, 0.56]} /></mesh>
      </group>
    ))}
    <mesh position={[0, 0.34, 0.32]} material={vidro('#d1ece7')} receiveShadow><boxGeometry args={[1.2, 0.44, 0.08]} /></mesh>
    <Caixa p={[0, 0.63, 0]} t={[1.44, 0.1, 0.8]} cor={C.tampo} />
  </group>
);

const Balcao: React.FC = () => (
  <group>
    <Caixa p={[0, 0.49, -1.96]} t={[6.15, 0.98, 0.82]} cor={C.balcao} />
    <Caixa p={[0, 1.04, -1.96]} t={[6.4, 0.12, 1]} cor={C.tampo} />
    <Caixa p={[0, 0.12, -1.46]} t={[6.15, 0.16, 0.12]} cor={C.madeira} />
    {[-2, 0, 2].map((x) => (
      <Caixa key={x} p={[x, 0.55, -1.43]} t={[1.7, 0.52, 0.12]} cor={C.madeiraClara} />
    ))}
    <Expositor />
    {/* Caixa vermelha e creme, inteira na ponta direita do balcão. */}
    <Caixa p={[2.47, 1.2, -1.93]} t={[0.66, 0.2, 0.5]} cor="#b64d42" />
    <Caixa p={[2.47, 1.49, -2.04]} t={[0.56, 0.38, 0.2]} cor={C.teto} />
    <Caixa p={[2.47, 1.49, -1.86]} t={[0.36, 0.18, 0.12]} cor={C.lousa} sombra={false} />
    <Caixa p={[2.47, 1.34, -1.7]} t={[0.4, 0.08, 0.12]} cor={C.teto} />
  </group>
);

const Luminaria: React.FC<{ x: number; principal?: boolean }> = ({ x, principal = false }) => (
  <group position={[x, 0, -1.05]}>
    <Haste a={[0, 2.9, 0]} b={[0, 3.7, 0]} raio={0.05} cor={C.metal} />
    <mesh position={[0, 2.82, 0]} material={mat(C.telha)} castShadow receiveShadow>
      <cylinderGeometry args={[0.15, 0.29, 0.28, 12]} />
    </mesh>
    <mesh position={[0, 2.62, 0]} material={mat(C.lampada)} receiveShadow>
      <cylinderGeometry args={[0.23, 0.23, 0.08, 12]} />
    </mesh>
    <pointLight position={[0, 2.53, 0]} color="#ffdfb2" intensity={principal ? 5 : 2}
      distance={10} decay={2} castShadow={principal} shadow-mapSize={[1024, 1024]}
      shadow-radius={5} shadow-bias={-0.001} shadow-normalBias={0.03} />
  </group>
);

export const Padaria: React.FC = () => (
  <group>
    <Piso />
    <Caixa p={[0, 1.85, -4.1]} t={[8.4, 3.7, 0.2]} cor={C.creme} />
    <Caixa p={[0, 0.46, -3.86]} t={[8.4, 0.92, 0.16]} cor={C.barrado} />
    {[-1, 1].map((lado) => (
      <group key={lado}>
        <Caixa p={[lado * 4.1, 1.85, 1.6]} t={[0.2, 3.7, 11.2]} cor={C.creme} />
        <Caixa p={[lado * 3.86, 0.46, 1.6]} t={[0.16, 0.92, 11.2]} cor={C.barrado} />
      </group>
    ))}
    {/* Teto sem bloquear o sol suave do palco. */}
    <Caixa p={[0, 3.8, 1.6]} t={[8.4, 0.2, 11.6]} cor={C.teto} sombra={false} />
    <Prateleiras />
    <PlacaDePrecos />
    <Balcao />
    <Luminaria x={-2.95} />
    <Luminaria x={2.95} principal />
    {/* Preenchimento fraco preserva o xadrez nos cantos e as sombras principais. */}
    <pointLight position={[0, 2.8, 2.4]} color="#fff0d8" intensity={3} distance={12} decay={2} />
  </group>
);
