// Ônibus em corte, frente aberta para a câmera em +Z.
import React from 'react';
import { useCurrentFrame } from 'remotion';
import { Caixa, Haste, mat } from './base';

const C = {
  piso: '#536574', parede: '#e5e9e5', rodape: '#344856', teto: '#f3f1df',
  azul: '#367fcd', azulEscuro: '#24548b', azulClaro: '#609cde',
  amarelo: '#f6c745', metal: '#7a8e99', borracha: '#273e4a',
  ceu: '#b8e0ed', rua: '#7c8a92', calcada: '#c7c4af', grama: '#86af7d',
};
const FILEIRAS = [-4.1, -2.85, -1.6, -0.35, 0.9];
const MONTANTES = [-5.25, -3.75, -2.25, -0.75, 0.75, 2.25, 3.75];

const Banco: React.FC<{ x: number; z: number }> = ({ x, z }) => (
  <group position={[x, 0, z]}>
    <Caixa p={[0, 0.22, -0.08]} t={[0.16, 0.44, 0.3]} cor={C.metal} />
    <Caixa p={[0, 0.06, -0.08]} t={[0.44, 0.12, 0.42]} cor={C.borracha} />
    <Caixa p={[0, 0.46, -0.04]} t={[0.56, 0.16, 0.46]} cor={C.azul} />
    {/* Borda frontal arredondada, com o mesmo volume do assento. */}
    <mesh position={[0, 0.46, 0.19]} rotation={[0, 0, Math.PI / 2]} material={mat(C.azul)} castShadow receiveShadow>
      <capsuleGeometry args={[0.08, 0.4, 4, 12]} />
    </mesh>
    <Caixa p={[0, 0.77, -0.23]} t={[0.56, 0.5, 0.16]} cor={C.azulEscuro} />
    <mesh position={[0, 1.02, -0.23]} rotation={[0, 0, Math.PI / 2]} material={mat(C.azulEscuro)} castShadow receiveShadow>
      <capsuleGeometry args={[0.08, 0.4, 4, 12]} />
    </mesh>
    <Caixa p={[0, 0.81, -0.07]} t={[0.4, 0.32, 0.08]} cor={C.azulClaro} />
  </group>
);

// Prédios inteiros passam por trás de aberturas reais, sem vidro transparente.
const RuaPassando: React.FC<{ quadro: number }> = ({ quadro }) => {
  const cores = ['#d29a76', '#a6b9b2', '#e4c589', '#84a6bc'];
  const ciclo = (valor: number, periodo: number) => ((valor % periodo) + periodo) % periodo;
  return (
    <group>
      {[-1, 1].map((lado) => (
        <group key={lado}>
          <Caixa p={[lado * 4.2, 2.2, -0.8]} t={[0.16, 5.6, 23]} cor={C.ceu} sombra={false} />
          <Caixa p={[lado * 3.0, 0.15, -0.8]} t={[1.2, 0.3, 23]} cor={C.calcada} sombra={false} />
          <Caixa p={[lado * 3.1, 0.48, -0.8]} t={[0.8, 0.16, 23]} cor={C.grama} sombra={false} />
          {Array.from({ length: 7 }, (_, i) => {
            const z = ciclo(i * 3.2 + quadro * 0.045, 22.4) - 12;
            const altura = 2.5 + (i % 3) * 0.45;
            return (
              <group key={i} position={[lado * 3.65, 0, z]}>
                <Caixa p={[0, altura / 2, 0]} t={[0.64, altura, 2.4]} cor={cores[i % 4]} sombra={false} />
                {[1.25, 2.15].map((y) => [-0.65, 0.65].map((dz) => (
                  <Caixa key={`${y}-${dz}`} p={[-lado * 0.39, y, dz]} t={[0.1, 0.48, 0.48]} cor="#527f93" sombra={false} />
                )))}
              </group>
            );
          })}
        </group>
      ))}
      {/* A rua também atravessa a janela traseira. */}
      <Caixa p={[0, 2.1, -7.4]} t={[23, 5, 0.16]} cor={C.ceu} sombra={false} />
      <Caixa p={[0, 0.35, -6.75]} t={[23, 0.7, 0.8]} cor={C.rua} sombra={false} />
      {Array.from({ length: 8 }, (_, i) => {
        const x = ciclo(i * 2.8 - quadro * 0.045, 22.4) - 11.2;
        return (
          <group key={i} position={[x, 0, -6.9]}>
            <Caixa p={[0, 1.45, 0]} t={[2.1, 2.9, 0.5]} cor={cores[(i + 1) % 4]} sombra={false} />
            {[-0.55, 0.55].map((dx) => <Caixa key={dx} p={[dx, 1.85, 0.35]} t={[0.5, 0.6, 0.1]} cor="#527f93" sombra={false} />)}
          </group>
        );
      })}
    </group>
  );
};

const SaidaDeAr: React.FC<{ x: number; z: number }> = ({ x, z }) => (
  <group position={[x, 2.6, z]}>
    <Caixa p={[0, 0, 0]} t={[0.42, 0.12, 0.68]} cor={C.metal} />
    <Caixa p={[0, -0.12, 0]} t={[0.3, 0.08, 0.52]} cor={C.borracha} />
    {[-0.16, 0, 0.16].map((dz) => <Caixa key={dz} p={[0, -0.22, dz]} t={[0.3, 0.08, 0.08]} cor={C.parede} />)}
  </group>
);

export const InteriorOnibus: React.FC = () => {
  const quadro = useCurrentFrame();
  return (
    <group>
      <RuaPassando quadro={quadro} />
      <Caixa p={[0, -0.1, -0.75]} t={[4.48, 0.2, 9.3]} cor={C.piso} sombra={false} />
      {[-1, 1].map((lado) => (
        <group key={lado}>
          <Caixa p={[lado * 2.18, 0.54, -0.75]} t={[0.16, 1.08, 9.3]} cor={C.parede} />
          <Caixa p={[lado * 2.07, 0.2, -0.75]} t={[0.1, 0.32, 9.3]} cor={C.rodape} />
          <Caixa p={[lado * 2.18, 2.42, -0.75]} t={[0.16, 0.46, 9.3]} cor={C.parede} />
          {/* Janelas: vão de 1,08 a 2,19 m, com caixilhos de 12 cm. */}
          {MONTANTES.map((z) => <Caixa key={z} p={[lado * 2.18, 1.64, z]} t={[0.18, 1.12, 0.12]} cor={C.borracha} />)}
          {[1.12, 2.15].map((y) => <Caixa key={y} p={[lado * 2.15, y, -0.75]} t={[0.22, 0.08, 9.3]} cor={C.borracha} />)}
          {FILEIRAS.map((z) => <Banco key={z} x={lado * 1.8} z={z} />)}
          {/* Corredor livre de 3 m; barras com 9 cm de diâmetro. */}
          {[-3.6, -1.1, 1.4].map((z) => (
            <group key={z}>
              <Haste a={[lado * 1.58, 0.06, z]} b={[lado * 1.58, 2.32, z]} cor={C.amarelo} />
              <Caixa p={[lado * 1.58, 0.08, z]} t={[0.14, 0.16, 0.14]} cor={C.metal} />
              <Haste a={[lado * 1.58, 2.32, z]} b={[lado * 2.04, 2.32, z]} cor={C.amarelo} />
            </group>
          ))}
          <Haste a={[lado * 1.58, 2.32, -4.65]} b={[lado * 1.58, 2.32, 3.4]} cor={C.amarelo} />
          {[-3.8, -1.4, 1].map((z) => <SaidaDeAr key={z} x={lado * 0.85} z={z} />)}
        </group>
      ))}
      {/* Fundo recortado para uma janela larga; banco traseiro vazio. */}
      <Caixa p={[0, 0.54, -5.35]} t={[4.48, 1.08, 0.16]} cor={C.parede} />
      <Caixa p={[0, 2.42, -5.35]} t={[4.48, 0.46, 0.16]} cor={C.parede} />
      {[-1, 1].map((lado) => <Caixa key={lado} p={[lado * 1.96, 1.64, -5.35]} t={[0.56, 1.12, 0.16]} cor={C.parede} />)}
      {[1.12, 2.15].map((y) => <Caixa key={y} p={[0, y, -5.24]} t={[3.38, 0.08, 0.1]} cor={C.borracha} />)}
      {[-1.64, 0, 1.64].map((x) => <Caixa key={x} p={[x, 1.64, -5.24]} t={[0.08, 1.12, 0.1]} cor={C.borracha} />)}
      {[-1.2, -0.6, 0, 0.6, 1.2].map((x) => <Banco key={x} x={x} z={-4.9} />)}
      {/* Teto sem bloquear o sol do palco; luminárias só geométricas. */}
      <Caixa p={[0, 2.72, -0.75]} t={[4.48, 0.14, 9.3]} cor={C.teto} sombra={false} />
      {[-3.6, -1.1, 1.4].map((z) => (
        <group key={z}>
          <Caixa p={[0, 2.62, z]} t={[0.34, 0.08, 0.9]} cor={C.metal} sombra={false} />
          <Caixa p={[0, 2.51, z]} t={[0.22, 0.08, 0.76]} cor="#fff6cc" sombra={false} />
        </group>
      ))}
    </group>
  );
};
