// Objeto: trevo de quatro folhas do tamanho de uma bola de basquete (coroa ≈ 25 cm), flutuando e girando.
// Cada folha é UMA esfera achatada deformada em coração (ponta para o centro), verde chapado, sem nervura nem sulco.
// Origem no pé do caule, frente para +Z.
import * as THREE from 'three';
import React from 'react';
import { useCurrentFrame } from 'remotion';
import { mergeVertices } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import { mat, Esfera } from './base';

const C = { folha: '#22d34a', miolo: '#17a83b', caule: '#15a03a', sombra: '#1f2a1c' };
const ALT = 0.118;   // da ponta (centro do trevo) ao alto dos lobos
const LARG = 0.13;   // largura do coração
const ESP = 0.028;   // espessura no meio
export const CENTRO_COROA = 0.075; // altura do centro das folhas acima do pé do caule

// Contorno do coração "gordinho": curva clássica com o vinco entre os lobos raso (termo cos^12),
// para cada folha ler como UM coração e não duas pétalas. Ponta em y = -17, largura ±16.
const TABELA = (() => {
  const pts: [number, number][] = [];
  for (let i = 0; i < 1440; i++) {
    const t = (i / 1440) * Math.PI * 2, s = Math.sin(t), c = Math.cos(t);
    const x = 16 * s * s * s, y = 13 * c - 5 * Math.cos(2 * t) - 2 * Math.cos(3 * t) - Math.cos(4 * t) + 4.5 * Math.pow(c, 12);
    pts.push([Math.atan2(x, y), Math.hypot(x, y)]);
  }
  return pts.sort((a, b) => a[0] - b[0]);
})();
const raioCoracao = (ang: number) => {
  let i = TABELA.findIndex(([a]) => a >= ang);
  if (i <= 0) i = i === 0 ? 1 : TABELA.length - 1;
  const [a0, r0] = TABELA[i - 1], [a1, r1] = TABELA[i];
  return r0 + (r1 - r0) * ((ang - a0) / Math.max(a1 - a0, 1e-6));
};

/** Folha: esfera com os polos em ±Z, achatada e esticada no contorno do coração; ponta em (0,0), lobos em +Y. */
const geoFolha = (() => {
  const base = new THREE.SphereGeometry(1, 64, 32);
  base.rotateX(Math.PI / 2);
  base.deleteAttribute('normal'); base.deleteAttribute('uv');
  const g = mergeVertices(base); // solda a costura da esfera (sem linha na folha)
  const p = g.attributes.position;
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i), y = p.getY(i), z = p.getZ(i);
    const ro = Math.hypot(x, y), ang = Math.atan2(x, y), R = raioCoracao(ang) * ro;
    // perfil de lente cheia (almofada): borda fina, meio bojudo
    const zz = Math.sign(z) * Math.pow(Math.abs(z), 0.75) * (ESP / 2);
    p.setXYZ(i, Math.sin(ang) * R * (LARG / 32), (Math.cos(ang) * R + 17) * (ALT / 29), zz);
  }
  g.computeVertexNormals();
  return g;
})();

// cada folha levanta a borda para a frente (concha de ~17°): pega a luz num tom diferente da vizinha
const Folha: React.FC<{ ang: number }> = ({ ang }) => (
  <group rotation={[0, 0, ang]}>
    <group position={[0, 0.006, 0]} rotation={[0.3, 0, 0]}>
      <mesh geometry={geoFolha} material={mat(C.folha, { brilho: 0.12, rug: 0.7 })} castShadow receiveShadow />
    </group>
  </group>
);

/** Um trevo parado: quatro corações em X, miolo e caule curto, grosso e reto (uma peça só). */
export const TrevoUnico: React.FC = () => (
  <group position={[0, CENTRO_COROA, 0]}>
    {[45, 135, 225, 315].map((g) => <Folha key={g} ang={(g * Math.PI) / 180} />)}
    <Esfera p={[0, 0, 0.002]} r={0.02} esc={[1, 1, 0.8]} m={mat(C.miolo, { brilho: 0.08 })} />
    {/* caule: um cilindro reto de 1,5 cm de raio e 7,5 cm, com a ponta arredondada */}
    <mesh position={[0, -CENTRO_COROA / 2, -0.004]} material={mat(C.caule)} castShadow>
      <cylinderGeometry args={[0.014, 0.016, CENTRO_COROA, 16]} />
    </mesh>
    <Esfera p={[0, -CENTRO_COROA, -0.004]} r={0.016} m={mat(C.caule)} />
  </group>
);

const suave = (t: number) => { const u = Math.min(1, Math.max(0, t)); return u * u * (3 - 2 * u); };

/** Onde fica cada cópia: 1 trevo até q96, divide em 2 (q96–112) e em 4 (q124–140). Desloc. em metros no plano do trevo. */
export function copiasNoQuadro(q: number): { p: [number, number]; pulo: number }[] {
  const e1 = suave((q - 96) / 16), e2 = suave((q - 124) / 16);
  const pulo = (e: number) => 1 + 0.08 * Math.sin(Math.PI * e); // "estica" um pouco ao separar
  if (q < 96) return [{ p: [0, 0], pulo: 1 }];
  const dx = 0.17 * e1, dy = 0.16 * e2;
  if (q < 124) return [-1, 1].map((s) => ({ p: [s * dx, 0], pulo: pulo(e1) }));
  return [[-1, -1], [1, -1], [-1, 1], [1, 1]].map(([sx, sy]) => ({ p: [sx * dx, sy * dy], pulo: pulo(e2) }));
}

const matSombra = (o: number) => mat(C.sombra, { opac: o, rug: 0.9 });
/** Sombra suave no chão: 8 discos achatados translúcidos crescentes (borda esfumada), 3 mm um acima do outro. */
const SombraChao: React.FC<{ x: number; y: number; z: number; r: number }> = ({ x, y, z, r }) => (
  <group position={[x, y, z]}>
    {[1, 0.9, 0.8, 0.71, 0.62, 0.54, 0.46, 0.38].map((k, i) => (
      <mesh key={i} position={[0, 0.002 + i * 0.003, 0]} scale={[r * k, 1, r * k * 0.62]} material={matSombra(0.055)}>
        <cylinderGeometry args={[1, 1, 0.001, 32]} />
      </mesh>
    ))}
  </group>
);

/**
 * Trevo flutuando e girando (pelo quadro): balança ±2 cm, gira no próprio plano, tomba ~25° e o eixo bamboleia.
 * `dividir` liga as cópias; `alturaChao` (m, do pé do caule ao chão) liga a sombra suave no chão.
 */
export const Trevo: React.FC<{ quadro?: number; dividir?: boolean; alturaChao?: number }> = ({ quadro, dividir = true, alturaChao }) => {
  const qAtual = useCurrentFrame();
  const q = quadro ?? qAtual;
  const copias = dividir ? copiasNoQuadro(q) : [{ p: [0, 0] as [number, number], pulo: 1 }];
  const fase = (q / 60) * Math.PI * 2;
  const yBob = 0.02 * Math.sin(fase);
  return (
    <group>
      <group position={[0, yBob, 0]}>
        {copias.map(({ p, pulo }, i) => (
          <group key={i} position={[p[0], CENTRO_COROA + p[1], 0]}
            // eixo do giro desviado: tomba ~25° para trás e ~18° de lado, bamboleando devagar
            rotation={[-0.44 + 0.05 * Math.sin(fase + i), 0.32 + 0.06 * Math.cos(fase + i), 0.05]}>
            {/* gira 3°/quadro no próprio plano; no q90 o caule aponta para baixo-direita */}
            <group rotation={[0, 0, -((q - 90) * 3 * Math.PI) / 180 + 0.35 + i * 0.7]} scale={[pulo, 1 / pulo, 1]}>
              <group position={[0, -CENTRO_COROA, 0]}><TrevoUnico /></group>
            </group>
          </group>
        ))}
      </group>
      {/* sombra: fica mais forte e menor quando o trevo desce */}
      {alturaChao !== undefined && copias.map(({ p }, i) => (
        <SombraChao key={i} x={p[0]} y={-alturaChao} z={-0.03 - p[1] * 0.6} r={0.15 * (1 - yBob * 2)} />
      ))}
    </group>
  );
};
