// Balcão de padaria: 2,2 m de comprido, 1 m de altura. Gabinete de madeira clara com painéis, vitrine de vidro com doces
// e pães dentro; em cima, um pote de vidro cheio de balas e uma bandeja escura de pães. Origem no centro da base, frente +Z.
import React from 'react';
import { random } from 'remotion';
import { mat, Caixa, Placa, PaoFrances } from './base';

const COR = {
  madeira: '#eeb46a', clara: '#f8d9a6', painel: '#d9934a', rodape: '#8a5428', faixa: '#23988a',
  creme: '#fff3dc', fundo: '#f3dfbd', vidro: '#e3f7ff', reflexo: '#ffffff',
  bandejaV: '#c8372d', bandejaA: '#2f6fb5', prato: '#ffffff', bolo: '#f28bb0', cobertura: '#fff6f0', cereja: '#d0202a',
  sonho: '#e3a14c', acucar: '#fffaf0', chocolate: '#6b3a1e', bandejaTopo: '#34404c', tampa: '#d93a3a',
};
const BALAS = ['#e53935', '#fdd835', '#43a047', '#1e88e5', '#ec4fa0', '#fb8c00', '#8e44d6'];
const L = 2.2, D = 0.6, H = 1.0;
const XI = L - 0.12; // largura interna (entre as laterais)
const vidro = () => mat(COR.vidro, { brilho: 0.05, opac: 0.16 });

/** Gabinete de baixo: rodapé escuro recuado, frente clara com 4 painéis em relevo e a faixa colorida em cima. */
const Gabinete: React.FC = () => (
  <group>
    <Caixa p={[0, 0.04, -0.02]} t={[L - 0.08, 0.08, D - 0.08]} m={mat(COR.rodape)} />
    <Caixa p={[0, 0.245, 0]} t={[XI, 0.33, D - 0.04]} m={mat(COR.clara)} />
    {[-0.75, -0.25, 0.25, 0.75].map((x) => (
      <group key={x} position={[x, 0.245, 0.28]}>
        <Caixa p={[0, 0, 0.006]} t={[0.4, 0.22, 0.012]} m={mat(COR.painel)} />
        <Caixa p={[0, 0, 0.016]} t={[0.31, 0.14, 0.012]} m={mat(COR.clara)} />
      </group>
    ))}
    <Caixa p={[0, 0.43, 0.27]} t={[XI, 0.06, 0.04]} m={mat(COR.faixa)} />
  </group>
);

/** Doces dentro da vitrine (piso em y = 0,45). */
const Vitrine: React.FC = () => (
  <group position={[0, 0.45, 0.02]}>
    {/* bandeja vermelha com 4 pãezinhos */}
    <Placa w={0.5} d={0.3} h={0.02} r={0.03} p={[-0.65, 0.01, 0]} m={mat(COR.bandejaV)} />
    {[-0.09, 0.0, 0.09].map((z, i) => (
      <group key={z} position={[-0.65 + (i % 2) * 0.05, 0.02, z]}><PaoFrances escala={0.75} /></group>
    ))}
    {/* bolo rosa com cobertura e cereja, num prato branco */}
    <mesh position={[-0.12, 0.008, 0]} material={mat(COR.prato)} receiveShadow><cylinderGeometry args={[0.16, 0.16, 0.016, 32]} /></mesh>
    <mesh position={[-0.12, 0.07, 0]} material={mat(COR.bolo)} castShadow receiveShadow><cylinderGeometry args={[0.12, 0.12, 0.11, 32]} /></mesh>
    <mesh position={[-0.12, 0.13, 0]} material={mat(COR.cobertura)} castShadow receiveShadow><cylinderGeometry args={[0.123, 0.123, 0.02, 32]} /></mesh>
    <mesh position={[-0.12, 0.16, 0]} material={mat(COR.cereja)} castShadow><sphereGeometry args={[0.025, 16, 12]} /></mesh>
    {/* bandeja azul com sonhos (açúcar por cima) */}
    <Placa w={0.44} d={0.3} h={0.02} r={0.03} p={[0.36, 0.01, 0]} m={mat(COR.bandejaA)} />
    {[[-0.12, -0.07], [0, -0.07], [0.12, -0.07], [-0.06, 0.07], [0.06, 0.07]].map(([x, z], i) => (
      <group key={i} position={[0.36 + x, 0.05, z]}>
        <mesh scale={[1, 0.62, 1]} material={mat(COR.sonho)} castShadow receiveShadow><sphereGeometry args={[0.052, 20, 12]} /></mesh>
        <mesh position={[0, 0.02, 0]} scale={[1, 0.4, 1]} material={mat(COR.acucar)} receiveShadow><sphereGeometry args={[0.042, 20, 10]} /></mesh>
      </group>
    ))}
    {/* bolo de chocolate em barra com faixa branca */}
    <Caixa p={[0.82, 0.055, 0]} t={[0.24, 0.11, 0.16]} m={mat(COR.chocolate)} />
    <Caixa p={[0.82, 0.115, 0]} t={[0.245, 0.012, 0.05]} m={mat(COR.cobertura)} />
  </group>
);

/** Estrutura da vitrine: piso, fundo, laterais, montante do meio, tampo de madeira atrás e vidros. */
const Estrutura: React.FC = () => (
  <group>
    <Caixa p={[0, 0.43, -0.02]} t={[XI, 0.04, D - 0.08]} m={mat(COR.creme)} />
    <Caixa p={[0, 0.7, -0.275]} t={[XI, 0.52, 0.03]} m={mat(COR.fundo)} />
    {[-1, 1].map((s) => <Caixa key={s} p={[s * (L / 2 - 0.03), 0.535, 0]} t={[0.06, 0.93, D]} m={mat(COR.madeira)} />)}
    <Caixa p={[0, 0.7, 0.275]} t={[0.04, 0.5, 0.04]} m={mat(COR.madeira)} />
    {/* tampo: faixa de madeira atrás (onde ficam o pote e a bandeja) e régua na frente; vidro entre as duas */}
    <Caixa p={[0, 0.975, -0.18]} t={[L, 0.05, 0.24]} m={mat(COR.madeira)} />
    <Caixa p={[0, 0.975, 0.28]} t={[L, 0.05, 0.05]} m={mat(COR.madeira)} />
    <mesh position={[0, 0.97, 0.05]} material={vidro()} renderOrder={2}><boxGeometry args={[XI, 0.01, 0.42]} /></mesh>
    <mesh position={[0, 0.7, 0.28]} material={vidro()} renderOrder={2}><boxGeometry args={[XI, 0.5, 0.008]} /></mesh>
    {/* reflexos inclinados no vidro da frente (dois por metade) */}
    {[-0.96, -0.86, 0.62, 0.7].map((x, i) => (
      <mesh key={x} position={[x, 0.7, 0.287]} rotation={[0, 0, 0.6]} material={mat(COR.reflexo, { brilho: 0.4, opac: 0.4 })} renderOrder={3}>
        <boxGeometry args={[i % 2 ? 0.035 : 0.06, 0.42, 0.002]} />
      </mesh>
    ))}
  </group>
);

/** Pote de vidro (24 cm) com tampa vermelha, cheio de balas coloridas. Origem na base. */
const PoteBalas: React.FC = () => {
  const balas = Array.from({ length: 48 }, (_, i) => {
    const a = random(`bala-a-${i}`) * Math.PI * 2, rr = Math.sqrt(random(`bala-r-${i}`)) * 0.068;
    return { p: [Math.cos(a) * rr, 0.025 + (i / 48) * 0.16 + random(`bala-y-${i}`) * 0.02, Math.sin(a) * rr] as [number, number, number], cor: BALAS[i % BALAS.length] };
  });
  return (
    <group>
      {balas.map((b, i) => (
        <mesh key={i} position={b.p} material={mat(b.cor, { brilho: 0.12 })} castShadow receiveShadow><sphereGeometry args={[0.021, 14, 10]} /></mesh>
      ))}
      <mesh position={[0, 0.006, 0]} material={mat(COR.vidro, { opac: 0.5 })}><cylinderGeometry args={[0.1, 0.1, 0.012, 32]} /></mesh>
      <mesh position={[0, 0.12, 0]} material={vidro()} renderOrder={3}><cylinderGeometry args={[0.1, 0.1, 0.24, 32]} /></mesh>
      {/* reflexo vertical no vidro */}
      <mesh position={[-0.05, 0.13, 0.087]} rotation={[0, -0.5, 0]} material={mat(COR.reflexo, { brilho: 0.4, opac: 0.55 })} renderOrder={4}><boxGeometry args={[0.016, 0.17, 0.002]} /></mesh>
      {/* gargalo, tampa vermelha e pegador */}
      <mesh position={[0, 0.25, 0]} material={vidro()} renderOrder={2}><cylinderGeometry args={[0.078, 0.095, 0.02, 32]} /></mesh>
      <mesh position={[0, 0.278, 0]} material={mat(COR.tampa)} castShadow receiveShadow><cylinderGeometry args={[0.088, 0.088, 0.036, 32]} /></mesh>
      <mesh position={[0, 0.304, 0]} material={mat(COR.tampa)} castShadow receiveShadow><sphereGeometry args={[0.026, 16, 12]} /></mesh>
    </group>
  );
};

/** Bandeja escura de pães em cima do balcão: 4 pães francês no comprido, em 2 fileiras. */
const BandejaPaes: React.FC = () => (
  <group>
    <Placa w={0.46} d={0.22} h={0.016} r={0.025} p={[0, 0.008, 0]} m={mat(COR.bandejaTopo)} />
    {[[-0.11, -0.05, 0.06], [0.11, -0.05, -0.05], [-0.1, 0.05, -0.04], [0.12, 0.05, 0.07]].map(([x, z, g], i) => (
      <group key={i} position={[x, 0.016, z]} rotation={[0, g, 0]}><PaoFrances escala={0.95} /></group>
    ))}
  </group>
);

export const BalcaoPadaria: React.FC = () => (
  <group>
    <Gabinete />
    <Estrutura />
    <Vitrine />
    <group position={[0.62, H, -0.17]}><PoteBalas /></group>
    <group position={[-0.45, H, -0.17]}><BandejaPaes /></group>
  </group>
);
