// Objeto: gráfico flutuante (34 x 30 cm), placa branca de 1,4 cm, eixos pretos, barra laranja de 1% e o "fantasma" do
// mesmo laranja que cresce até 2%. Números em traços arredondados (cápsulas e arcos de toro, sem fonte).
// Origem no centro da borda de baixo, frente para +Z.
import React from 'react';
import { useCurrentFrame } from 'remotion';
import { mat, Caixa, Ret } from './base';

const C = { placa: '#fdfcf8', eixo: '#1d1f24', barra: '#ff8a1f', barraClara: '#ffb766', seta: '#d9541a', sombra: '#2a2620' };
const W = 0.34, H = 0.3, D = 0.014;
const ZF = D / 2;                  // face da frente da placa
const OX = -0.07, OY = -0.1;       // origem dos eixos (relativa ao centro da placa)
const UM = 0.085;                  // 1% = 8,5 cm
const EIXO = 0.0045;               // raio do traço dos eixos (9 mm)
const BX = OX + 0.075, BL = 0.07;  // centro e largura da barra
const SR = 0.0026;                 // raio do traço dos números (5 mm)
const GH = 0.03, GW = 0.019;       // altura e largura de um algarismo

const tinta = () => mat(C.eixo, { rug: 0.7 });

/** Traço arredondado de (x1,y1) a (x2,y2): cápsula achatada, meio enterrada na placa. */
const Linha: React.FC<{ a: [number, number]; b: [number, number]; r?: number; m?: ReturnType<typeof mat>; z?: number }> = ({ a, b, r = SR, m, z = ZF }) => {
  const dx = b[0] - a[0], dy = b[1] - a[1], c = Math.hypot(dx, dy);
  return (
    <mesh position={[(a[0] + b[0]) / 2, (a[1] + b[1]) / 2, z]} rotation={[0, 0, -Math.atan2(dx, dy)]} scale={[1, 1, 0.5]} material={m ?? tinta()}>
      <capsuleGeometry args={[r, Math.max(c, 0.0001), 4, 10]} />
    </mesh>
  );
};
/** Arco de traço (toro), centro (x,y), raio R, de `ini` a `ini + arco` (rad, anti-horário a partir de +X). */
const Arco: React.FC<{ x: number; y: number; R: number; ini: number; arco: number }> = ({ x, y, R, ini, arco }) => (
  <mesh position={[x, y, ZF]} rotation={[0, 0, ini]} scale={[1, 1, 0.5]} material={tinta()}>
    <torusGeometry args={[R, SR, 8, 24, arco]} />
  </mesh>
);

const LARG: Record<string, number> = { '0': GW, '1': 0.012, '2': GW, '%': 0.022 };

/** Um algarismo centrado em (x, y): letras limpas de traço redondo (o "2" tem barriga, não vira "Z"). */
const Glifo: React.FC<{ c: string; x: number; y: number }> = ({ c, x, y }) => {
  const t = y + GH / 2 - SR, b = y - GH / 2 + SR, e = x - GW / 2 + SR, d = x + GW / 2 - SR;
  if (c === '1') return (<>
    <Linha a={[x + 0.002, b]} b={[x + 0.002, t]} />
    <Linha a={[x + 0.002, t]} b={[x - 0.0045, t - 0.0065]} />
  </>);
  if (c === '2') {
    const R = GW / 2 - SR, yc = t - R, fim = -0.6; // barriga de cima: de 180° a -34°
    return (<>
      <Arco x={x} y={yc} R={R} ini={fim} arco={Math.PI - fim} />
      <Linha a={[x + R * Math.cos(fim), yc + R * Math.sin(fim)]} b={[e, b]} />
      <Linha a={[e, b]} b={[d, b]} />
    </>);
  }
  if (c === '0') {
    const R = GW / 2 - SR;
    return (<>
      <Arco x={x} y={t - R} R={R} ini={0} arco={Math.PI} />
      <Arco x={x} y={b + R} R={R} ini={Math.PI} arco={Math.PI} />
      <Linha a={[e, b + R]} b={[e, t - R]} />
      <Linha a={[d, b + R]} b={[d, t - R]} />
    </>);
  }
  if (c === '%') {
    const anel = (ax: number, ay: number) => (
      <mesh position={[ax, ay, ZF]} scale={[1, 1, 0.5]} material={tinta()}><torusGeometry args={[0.0042, 0.0019, 8, 20]} /></mesh>
    );
    return (<>{anel(x - 0.0058, y + 0.0085)}{anel(x + 0.0058, y - 0.0085)}<Linha a={[x - 0.0075, b - 0.001]} b={[x + 0.0075, t + 0.001]} r={0.0019} /></>);
  }
  return null;
};

/** Rótulo alinhado à direita em xDir, centrado na altura y. */
const Rotulo: React.FC<{ txt: string; xDir: number; y: number }> = ({ txt, xDir, y }) => {
  let x = xDir;
  return (<>{[...txt].reverse().map((c, i) => {
    const w = LARG[c] ?? GW, cx = x - w / 2; x -= w + 0.005;
    return <Glifo key={i} c={c} x={cx} y={y} />;
  })}</>);
};

const suave = (t: number) => { const u = Math.min(1, Math.max(0, t)); return u * u * (3 - 2 * u); };
/** Até onde vai o laranja, em %: 1 até q25, sobe até 2 em q70. */
export const valorNoQuadro = (q: number) => 1 + suave((q - 25) / 45);

const matSombra = mat(C.sombra, { opac: 0.05, rug: 0.9 });

/**
 * Gráfico flutuante. A barra sólida fica em 1%; a parte que cresce (1% → `valor`) é o fantasma translúcido do mesmo
 * laranja, com a seta. `cheia` pinta tudo sólido (a barra "já é" o valor). `alturaChao` (m, da borda de baixo ao chão)
 * liga a sombra suave no chão; `inclinar` dá a pose flutuante (tomba e vira um pouco, balança devagar).
 */
export const GraficoBarras: React.FC<{ quadro?: number; valor?: number; cheia?: boolean; flutuar?: boolean; inclinar?: boolean; alturaChao?: number }> = ({
  quadro, valor, cheia = false, flutuar = true, inclinar = true, alturaChao,
}) => {
  const qAtual = useCurrentFrame();
  const q = quadro ?? qAtual;
  const v = valor ?? valorNoQuadro(q);
  const fase = (q / 75) * Math.PI * 2;
  const yBob = flutuar ? 0.012 * Math.sin(fase) : 0;
  const base = OY + EIXO, topo1 = OY + UM, topoV = OY + v * UM;
  const cresce = Math.min(1, Math.max(0, (v - 1) / 0.25)); // a seta entra assim que o fantasma começa a subir
  const solidoAte = cheia ? topoV : topo1;
  return (
    <group>
      <group position={[0, H / 2 + yBob, 0]}
        rotation={inclinar ? [-0.14 + 0.03 * Math.sin(fase), 0.22 + 0.03 * Math.cos(fase), 0.035] : undefined}>
        {/* placa branca de 1,4 cm, levemente acesa para ficar branca na sombra */}
        <Ret w={W} h={H} d={D} r={0.026} p={[0, 0, 0]} m={mat(C.placa, { brilho: 0.35 })} sombra />
        {/* eixos com pontas de seta */}
        <Linha a={[OX, OY]} b={[OX, OY + 2.35 * UM]} r={EIXO} />
        <Linha a={[OX, OY]} b={[OX + 0.19, OY]} r={EIXO} />
        <mesh position={[OX, OY + 2.35 * UM + 0.01, ZF]} scale={[1, 1, 0.5]} material={tinta()}><cylinderGeometry args={[0, 0.011, 0.022, 3]} /></mesh>
        <mesh position={[OX + 0.2, OY, ZF]} rotation={[0, 0, -Math.PI / 2]} scale={[1, 1, 0.5]} material={tinta()}><cylinderGeometry args={[0, 0.011, 0.022, 3]} /></mesh>
        {/* tiques iguais (2 cm) e rótulo centrado na altura de cada um; o "0" na altura do eixo X */}
        {([[1, '1%'], [2, '2%']] as const).map(([n, txt]) => (
          <group key={txt}>
            <Linha a={[OX - 0.012, OY + n * UM]} b={[OX, OY + n * UM]} r={0.003} />
            <Rotulo txt={txt} xDir={OX - 0.022} y={OY + n * UM} />
          </group>
        ))}
        <Rotulo txt="0" xDir={OX - 0.022} y={OY} />
        {/* barra laranja chapada (1%), com filete claro à esquerda */}
        <Caixa p={[BX, (base + solidoAte) / 2, ZF + 0.004]} t={[BL, solidoAte - base, 0.012]} m={mat(C.barra, { brilho: 0.15 })} sombra={false} />
        <Caixa p={[BX - BL / 2 + 0.008, (base + solidoAte) / 2, ZF + 0.0055]} t={[0.008, solidoAte - base - 0.012, 0.012]} m={mat(C.barraClara, { brilho: 0.15 })} sombra={false} />
        {/* fantasma do mesmo laranja: a parte que cresceu, de 1% até o valor */}
        {!cheia && topoV > topo1 + 0.001 && (
          <Caixa p={[BX, (topo1 + topoV) / 2, ZF + 0.004]} t={[BL, topoV - topo1, 0.012]} m={mat(C.barra, { opac: 0.55, brilho: 0.25 })} sombra={false} />
        )}
        {/* seta grossa de 1% para 2%, ao lado da barra */}
        {cresce > 0 && (
          <group position={[BX + BL / 2 + 0.03, OY + 1.5 * UM, 0]} scale={[cresce, cresce, 1]}>
            <Linha a={[0, -0.034]} b={[0, 0.03]} r={0.0045} m={mat(C.seta)} />
            <Linha a={[0, 0.034]} b={[-0.014, 0.018]} r={0.0045} m={mat(C.seta)} />
            <Linha a={[0, 0.034]} b={[0.014, 0.018]} r={0.0045} m={mat(C.seta)} />
          </group>
        )}
      </group>
      {/* sombra suave no chão: elipses translúcidas crescentes */}
      {alturaChao !== undefined && [1, 0.9, 0.8, 0.71, 0.62, 0.54, 0.46, 0.38].map((k, i) => (
        <mesh key={i} position={[0, -alturaChao + 0.002 + i * 0.003, -0.02]} scale={[0.22 * k * (1 - yBob * 3), 1, 0.09 * k]} material={matSombra}>
          <cylinderGeometry args={[1, 1, 0.001, 32]} />
        </mesh>
      ))}
    </group>
  );
};
