// Painel de 6 m; frente limpa, discos inteiros e prêmio acima da borda.
import React from 'react';
import { mat, numero, RetanguloArredondado, Tracos } from './base';

const C = { verde: '#16804c', borda: '#10583c', branco: '#fffdf5', tinta: '#103e2c', ouro: '#f5bd35' };
const casas = Array.from({ length: 60 }, (_, i) => ({
  valor: i + 1, x: ((i % 10) - 4.5) * 0.90, y: 5.25 - Math.floor(i / 10) * 0.90,
}));
const digitos = casas.flatMap(({ valor, x, y }) => numero(String(valor), x, y, 0.50, 0.08, C.tinta));
const premio = numero('50.063.860', 0, 6.72, 0.82, 0.10, C.ouro);

export const VolanteGigante: React.FC = () => (
  <group>
    <RetanguloArredondado l={9.4} a={6} e={0.24} raio={0.20} p={[0, 3, 0]} cor={C.borda} />
    <RetanguloArredondado l={9.12} a={5.72} e={0.08} raio={0.16} p={[0, 3, 0.12]} cor={C.verde} />
    {/* Disco começa em Z=0,20, 4 cm à frente do verde. Sem sombras de impressão. */}
    {casas.map(({ valor, x, y }) => (
      <mesh key={valor} position={[x, y, 0.24]} rotation={[Math.PI / 2, 0, 0]}
        material={mat(C.branco)} castShadow={false} receiveShadow={false}>
        <cylinderGeometry args={[0.43, 0.43, 0.08, 48]} />
      </mesh>
    ))}
    {/* Disco termina em 0,28; traços começam em 0,30. */}
    <Tracos retangulos={digitos} z={0.34} espessura={0.08} />
    <Tracos retangulos={premio} z={0.10} espessura={0.12} />
  </group>
);
