// Base do lote r04: cache de material por cor, instâncias (muitas formas iguais = 1 mesh), céu em degradê
// e a lua (reaponta o sol com sombra do palco enquanto o cenário está montado). Padrão do Quadra.tsx.
import * as THREE from 'three';
import React, { useEffect, useLayoutEffect, useMemo, useRef } from 'react';
import { useThree } from '@react-three/fiber';

export type V3 = [number, number, number];

const cache = new Map<string, THREE.MeshStandardMaterial>();
/** Material chapado (roughness 0.85). `luz` clareia a sombra própria com um emissivo frio e fraco (neve). */
export const mat = (cor: string, o: { luz?: string; forca?: number; aspereza?: number } = {}) => {
  const { luz, forca = 0, aspereza = 0.85 } = o;
  const k = [cor, luz, forca, aspereza].join('|');
  let m = cache.get(k);
  if (!m) {
    m = new THREE.MeshStandardMaterial({ color: cor, roughness: aspereza });
    if (luz && forca > 0) { m.emissive = new THREE.Color(luz); m.emissiveIntensity = forca; }
    cache.set(k, m);
  }
  return m;
};

/** Muitas formas iguais (mesma geometria e material) numa mesh só. Cada item: centro, tamanho e giro em Y. */
export type Item = { p: V3; t: V3; giro?: number };
export const Instancias: React.FC<{ itens: Item[]; geo: THREE.BufferGeometry; m: THREE.Material; sombra?: boolean; recebe?: boolean }> = ({ itens, geo, m, sombra = false, recebe = true }) => {
  const ref = useRef<THREE.InstancedMesh>(null);
  useLayoutEffect(() => {
    const im = ref.current; if (!im) return;
    const mx = new THREE.Matrix4(), q = new THREE.Quaternion(), eixo = new THREE.Vector3(0, 1, 0);
    itens.forEach((it, i) => im.setMatrixAt(i, mx.compose(new THREE.Vector3(...it.p), q.setFromAxisAngle(eixo, it.giro ?? 0), new THREE.Vector3(...it.t))));
    im.instanceMatrix.needsUpdate = true;
    im.computeBoundingSphere();
  });
  return <instancedMesh ref={ref} args={[geo, m, itens.length]} castShadow={sombra} receiveShadow={recebe} frustumCulled={false} />;
};

/** Céu: esfera grande por dentro. Do horizonte (`baixo`) ao alto (`alto`) numa faixa curta de altura (`faixa`, em seno do ângulo). */
export const Ceu: React.FC<{ baixo: string; alto: string; faixa?: number; raio?: number }> = ({ baixo, alto, faixa = 0.16, raio = 120 }) => {
  const geo = useMemo(() => {
    const g = new THREE.SphereGeometry(raio, 48, 48);
    const pos = g.attributes.position, cor = new Float32Array(pos.count * 3);
    const a = new THREE.Color(baixo), b = new THREE.Color(alto), c = new THREE.Color();
    for (let i = 0; i < pos.count; i++) {
      const k = THREE.MathUtils.smoothstep(pos.getY(i) / raio, 0, faixa);
      c.copy(a).lerp(b, k);
      cor[i * 3] = c.r; cor[i * 3 + 1] = c.g; cor[i * 3 + 2] = c.b;
    }
    g.setAttribute('color', new THREE.BufferAttribute(cor, 3));
    return g;
  }, [baixo, alto, faixa, raio]);
  const m = useMemo(() => new THREE.MeshBasicMaterial({ vertexColors: true, side: THREE.BackSide, depthWrite: false, fog: false }), []);
  return <mesh geometry={geo} material={m} renderOrder={-1} frustumCulled={false} />;
};

/** Lua: reaponta o sol com sombra do palco (direção, cor, força, área, maciez) e esfria o hemisfério do kit,
 *  só enquanto o cenário está montado. Aplica no layout e no efeito; devolve os valores da <Luz> ao desmontar. */
type Hemi = { ceu: string; chao: string; forca: number };
export const Lua: React.FC<{ dir: V3; cor: string; forca: number; area: number; maciez?: number; hemi?: Hemi }> = ({ dir, cor, forca, area, maciez = 6, hemi }) => {
  const { scene } = useThree();
  const kit = useRef<{ s: THREE.DirectionalLight; p: THREE.Vector3; c: THREE.Color; f: number; r: number;
    h?: { l: THREE.HemisphereLight; c: THREE.Color; g: THREE.Color; f: number } } | null>(null);
  const dist = area + 20;
  const aplicar = () => {
    let s: THREE.DirectionalLight | undefined, h: THREE.HemisphereLight | undefined;
    scene.traverse((o) => {
      if (!s && (o as THREE.DirectionalLight).isDirectionalLight && o.castShadow) s = o as THREE.DirectionalLight;
      if (!h && (o as THREE.HemisphereLight).isHemisphereLight && !o.name) h = o as THREE.HemisphereLight; // o do kit não tem nome
    });
    if (!s) return;
    if (!kit.current) kit.current = { s, p: s.position.clone(), c: s.color.clone(), f: s.intensity, r: s.shadow.radius,
      h: h && { l: h, c: h.color.clone(), g: h.groundColor.clone(), f: h.intensity } };
    s.position.copy(new THREE.Vector3(...dir).normalize().multiplyScalar(-dist));
    s.color.set(cor); s.intensity = forca; s.shadow.radius = maciez;
    Object.assign(s.shadow.camera, { left: -area, right: area, top: area, bottom: -area, near: 1, far: dist + area * 1.5 });
    s.shadow.camera.updateProjectionMatrix();
    if (h && hemi) { h.color.set(hemi.ceu); h.groundColor.set(hemi.chao); h.intensity = hemi.forca; }
  };
  useLayoutEffect(aplicar);
  useEffect(aplicar);
  useEffect(() => () => {
    const k = kit.current; if (!k) return;
    k.s.position.copy(k.p); k.s.color.copy(k.c); k.s.intensity = k.f; k.s.shadow.radius = k.r;
    Object.assign(k.s.shadow.camera, { left: -20, right: 20, top: 20, bottom: -20, near: 1, far: 80 }); // os valores da <Luz>
    k.s.shadow.camera.updateProjectionMatrix();
    if (k.h) { k.h.l.color.copy(k.h.c); k.h.l.groundColor.copy(k.h.g); k.h.l.intensity = k.h.f; }
  }, []);
  return null;
};

/** Névoa em faixa: plano vertical largo, opaco embaixo (cor da névoa) e transparente em cima. Suaviza o horizonte. */
export const FaixaNevoa: React.FC<{ cor: string; z: number; altura: number; largura?: number; opaco?: number }> = ({ cor, z, altura, largura = 120, opaco = 1 }) => {
  const geo = useMemo(() => {
    const g = new THREE.PlaneGeometry(largura, altura, 1, 12);
    const pos = g.attributes.position, rgba = new Float32Array(pos.count * 4), c = new THREE.Color(cor);
    for (let i = 0; i < pos.count; i++) {
      const t = pos.getY(i) / altura + 0.5; // 0 embaixo, 1 em cima
      rgba.set([c.r, c.g, c.b, opaco * (1 - THREE.MathUtils.smoothstep(t, 0.05, 1))], i * 4);
    }
    g.setAttribute('color', new THREE.BufferAttribute(rgba, 4));
    return g;
  }, [cor, altura, largura, opaco]);
  const m = useMemo(() => new THREE.MeshBasicMaterial({ vertexColors: true, transparent: true, depthWrite: false, fog: false }), []);
  return <mesh geometry={geo} material={m} position={[0, altura / 2 - 0.3, z]} frustumCulled={false} />;
};
