// Base do lote r03: cache de material por cor e as formas do kit (Caixa, Haste), no padrão do Quadra.tsx,
// mais instâncias (muitas caixas iguais = 1 mesh), céu em degradê e o plano de foco.
import * as THREE from 'three';
import React, { useEffect, useLayoutEffect, useMemo, useRef } from 'react';
import { useThree } from '@react-three/fiber';

export type V3 = [number, number, number];

const cache = new Map<string, THREE.MeshStandardMaterial>();
/** Material chapado (roughness 0.85). `brilho` > 0 acende a cor (emissivo: lâmpada, semáforo). */
export const mat = (cor: string, o: { flat?: boolean; brilho?: number } = {}) => {
  const { flat = false, brilho = 0 } = o;
  const k = [cor, flat, brilho].join('|');
  let m = cache.get(k);
  if (!m) {
    m = new THREE.MeshStandardMaterial({ color: cor, roughness: 0.85, flatShading: flat });
    if (brilho > 0) { m.emissive = new THREE.Color(cor); m.emissiveIntensity = brilho; }
    cache.set(k, m);
  }
  return m;
};

export const Caixa: React.FC<{ p: V3; t: V3; cor: string; sombra?: boolean; r?: V3; m?: THREE.Material }> = ({ p, t, cor, sombra = true, r, m }) => (
  <mesh position={p} rotation={r} material={m ?? mat(cor)} castShadow={sombra} receiveShadow><boxGeometry args={t} /></mesh>
);

export const Haste: React.FC<{ a: V3; b: V3; r: number; cor: string; seg?: number; sombra?: boolean }> = ({ a, b, r, cor, seg = 10, sombra = true }) => {
  const va = new THREE.Vector3(...a), vb = new THREE.Vector3(...b), d = vb.clone().sub(va);
  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), d.clone().normalize());
  return (
    <mesh position={va.add(vb).multiplyScalar(0.5)} quaternion={q} material={mat(cor)} castShadow={sombra} receiveShadow>
      <cylinderGeometry args={[r, r, d.length(), seg]} />
    </mesh>
  );
};

/** Muitas caixas da mesma cor numa mesh só (janelas, placas do piso). Cada item: centro e tamanho. */
const caixaUnit = new THREE.BoxGeometry(1, 1, 1);
export const Caixas: React.FC<{ itens: { p: V3; t: V3 }[]; cor: string; sombra?: boolean }> = ({ itens, cor, sombra = true }) => {
  const ref = useRef<THREE.InstancedMesh>(null);
  useLayoutEffect(() => {
    const im = ref.current; if (!im) return;
    const m = new THREE.Matrix4(), q = new THREE.Quaternion();
    itens.forEach((it, i) => im.setMatrixAt(i, m.compose(new THREE.Vector3(...it.p), q, new THREE.Vector3(...it.t))));
    im.instanceMatrix.needsUpdate = true;
    im.computeBoundingSphere();
  });
  return <instancedMesh ref={ref} args={[caixaUnit, mat(cor), itens.length]} castShadow={sombra} receiveShadow frustumCulled={false} />;
};

/** Céu: esfera grande por dentro, degradê do horizonte (`baixo`) ao alto (`alto`). Sem luz, sem sombra. */
export const Ceu: React.FC<{ baixo: string; alto: string; raio?: number }> = ({ baixo, alto, raio = 120 }) => {
  const geo = useMemo(() => {
    const g = new THREE.SphereGeometry(raio, 32, 24);
    const pos = g.attributes.position, cor = new Float32Array(pos.count * 3);
    const a = new THREE.Color(baixo), b = new THREE.Color(alto), c = new THREE.Color();
    for (let i = 0; i < pos.count; i++) {
      const k = Math.min(1, Math.max(0, pos.getY(i) / raio / 0.45));
      c.copy(a).lerp(b, Math.sqrt(k));
      cor[i * 3] = c.r; cor[i * 3 + 1] = c.g; cor[i * 3 + 2] = c.b;
    }
    g.setAttribute('color', new THREE.BufferAttribute(cor, 3));
    return g;
  }, [baixo, alto, raio]);
  const m = useMemo(() => new THREE.MeshBasicMaterial({ vertexColors: true, side: THREE.BackSide, depthWrite: false, fog: false }), []);
  return <mesh geometry={geo} material={m} renderOrder={-1} frustumCulled={false} />;
};

/** Sol do cenário: reaponta o sol com sombra do palco (direção, cor, força) só enquanto o cenário está montado.
 *  `area` (opcional) é a meia largura do quadrado coberto pela sombra (padrão: os 20 m da <Luz>).
 *  Roda a cada commit (layout e efeito), depois das props da <Luz>, e devolve os valores do kit ao desmontar. */
export const Sol: React.FC<{ dir: V3; cor: string; forca: number; area?: number }> = ({ dir, cor, forca, area }) => {
  const { scene } = useThree();
  const acha = () => {
    let sol: THREE.DirectionalLight | undefined;
    scene.traverse((o) => { if (!sol && (o as THREE.DirectionalLight).isDirectionalLight && o.castShadow) sol = o as THREE.DirectionalLight; });
    return sol;
  };
  const dist = area ? area + 20 : 30;
  // valores da <Luz> do kit, guardados uma vez para devolver ao desmontar
  const kit = useRef<{ s: THREE.DirectionalLight; p: THREE.Vector3; c: THREE.Color; f: number } | null>(null);
  const aplicar = () => {
    const s = acha(); if (!s) return;
    const cs = s.shadow.camera;
    if (!kit.current) kit.current = { s, p: s.position.clone(), c: s.color.clone(), f: s.intensity };
    s.position.copy(new THREE.Vector3(...dir).normalize().multiplyScalar(-dist));
    s.color.set(cor); s.intensity = forca;
    // área: a do cenário, ou os ±20 m que a <Luz> fixa num useEffect (que pode rodar depois do quadro ser desenhado)
    const a = area ?? 20;
    Object.assign(cs, { left: -a, right: a, top: a, bottom: -a, near: 1, far: area ? dist + a * 1.5 : 80 });
    cs.updateProjectionMatrix();
  };
  useLayoutEffect(aplicar);
  useEffect(aplicar);
  useEffect(() => () => {
    const k = kit.current; if (!k) return;
    const cs = k.s.shadow.camera;
    k.s.position.copy(k.p); k.s.color.copy(k.c); k.s.intensity = k.f;
    Object.assign(cs, { left: -20, right: 20, top: 20, bottom: -20, near: 1, far: 80 }); cs.updateProjectionMatrix(); // os valores da <Luz>
  }, []);
  return null;
};

// Plano de foco: invisível na imagem (não escreve cor nem profundidade), mas entra no passe de profundidade
// do desfoque (o BokehPass troca todos os materiais por um de profundidade). Tudo o que fica atrás dele
// é desfocado como se estivesse no plano: o fundo fica legível, sem mexer no kit.
const geoFoco = new THREE.PlaneGeometry(600, 600);
const matFoco = new THREE.MeshBasicMaterial({ colorWrite: false, depthWrite: false });
export const PlanoFoco: React.FC<{ z: number }> = ({ z }) => (
  <mesh position={[0, 0, z]} geometry={geoFoco} material={matFoco} frustumCulled={false} />
);
