// Adereços das ações do lote r05: caderno aberto + lápis, moeda + polegar, linhas de giro da cabeça.
// <ObjetosDaAcao> vai DENTRO do mesmo grupo do <Boneco> (mesma posição e giro) e usa a cinemática do kit
// para pôr cada objeto na mão no quadro pedido. Tamanho real, cores chapadas, cache de material por cor.
import * as THREE from 'three';
import React from 'react';
import {
  CADERNO_CENTRO, CADERNO_INCLINA, maoEscrevendo, juntasNoQuadro, ciclo, MOEDA_VOO, alturaMoeda, punhoMoeda,
  VIRA, GIRO_CABECA,
} from './acoes';
import { matrizCabeca, posicao } from './cinematica';

const cache = new Map<string, THREE.MeshStandardMaterial>();
const mat = (cor: string) => {
  let m = cache.get(cor);
  if (!m) { m = new THREE.MeshStandardMaterial({ color: cor, roughness: 0.85 }); cache.set(cor, m); }
  return m;
};
type V3 = [number, number, number];
const R = THREE.MathUtils.degToRad;
const Caixa: React.FC<{ p: V3; t: V3; cor: string; r?: V3 }> = ({ p, t, cor, r = [0, 0, 0] }) => (
  <mesh position={p} rotation={r} material={mat(cor)} castShadow receiveShadow><boxGeometry args={t} /></mesh>
);

// ── peças soltas ─────────────────────────────────────────────────────────
/** Caderno universitário aberto, 40 × 27 cm, deitado (origem no centro, página para +Y). */
export const Caderno: React.FC = () => (
  <group>
    <Caixa p={[0, -0.007, 0]} t={[0.41, 0.01, 0.28]} cor="#2f6fb5" />
    {([-1, 1] as const).map((l) => <Caixa key={l} p={[0.1 * l, 0.001, 0]} t={[0.19, 0.008, 0.265]} cor="#f7f4ea" />)}
    {/* espiral: argolas no meio */}
    {[-5, -3, -1, 1, 3, 5].map((i) => (
      <mesh key={i} position={[0, 0.006, i * 0.022]} rotation={[0, Math.PI / 2, 0]} material={mat('#9aa3ad')}>
        <torusGeometry args={[0.009, 0.0025, 6, 12]} />
      </mesh>
    ))}
    {/* margem vermelha e linhas já escritas na página da esquerda; na da direita, as primeiras linhas */}
    <Caixa p={[-0.17, 0.0055, 0]} t={[0.003, 0.001, 0.26]} cor="#e07070" />
    {[0, 1, 2, 3, 4, 5].map((i) => (
      <Caixa key={i} p={[-0.09 - (i % 3) * 0.008, 0.0055, -0.1 + i * 0.034]} t={[0.13 - (i % 3) * 0.022, 0.0012, 0.009]} cor="#3d4a5c" />
    ))}
    {[0, 1, 2].map((i) => <Caixa key={i} p={[0.085 - i * 0.012, 0.0055, -0.1 + i * 0.034]} t={[0.12 - i * 0.024, 0.0012, 0.009]} cor="#3d4a5c" />)}
  </group>
);
/** Lápis "jumbo" de 19 cm (1,5 cm de grossura, o de criança) ao longo de +Y, ponta do grafite na origem. */
export const Lapis: React.FC = () => (
  <group>
    <mesh position={[0, 0.003, 0]} material={mat('#2a2a2a')}><coneGeometry args={[0.0028, 0.006, 6]} /></mesh>
    <mesh position={[0, 0.0125, 0]} material={mat('#e8c49a')} castShadow><coneGeometry args={[0.0075, 0.019, 6]} /></mesh>
    <mesh position={[0, 0.099, 0]} material={mat('#f2c230')} castShadow><cylinderGeometry args={[0.0075, 0.0075, 0.156, 6]} /></mesh>
    <mesh position={[0, 0.183, 0]} material={mat('#b8b8b8')} castShadow><cylinderGeometry args={[0.008, 0.008, 0.012, 8]} /></mesh>
    <mesh position={[0, 0.1945, 0]} material={mat('#e98aa0')} castShadow><cylinderGeometry args={[0.0075, 0.0075, 0.011, 8]} /></mesh>
  </group>
);
/** Moeda de 2,7 cm (face para +Z): borda dourada, face clara e um "1" em relevo. */
export const Moeda: React.FC = () => (
  <group rotation={[Math.PI / 2, 0, 0]}>
    <mesh material={mat('#d9a521')} castShadow><cylinderGeometry args={[0.0135, 0.0135, 0.0022, 24]} /></mesh>
    {([-1, 1] as const).map((l) => (
      <mesh key={l} position={[0, 0.0008 * l, 0]} material={mat('#f2c94c')}><cylinderGeometry args={[0.011, 0.011, 0.001, 24]} /></mesh>
    ))}
    <Caixa p={[0, 0.0014, 0]} t={[0.0028, 0.0008, 0.012]} cor="#b8860b" />
    <Caixa p={[-0.0018, 0.0014, -0.0045]} t={[0.003, 0.0008, 0.0022]} cor="#b8860b" r={[0, R(-35), 0]} />
  </group>
);

// ── montagem por ação ─────────────────────────────────────────────────────
/** Matriz do espaço do tronco (o da IK) para o espaço do boneco. */
const tronco = (j: { altura: number; troncoX: number; troncoY: number }) =>
  new THREE.Matrix4().makeTranslation(0, j.altura + 0.66, 0)
    .multiply(new THREE.Matrix4().makeRotationFromEuler(new THREE.Euler(R(j.troncoX), R(j.troncoY), 0)))
    .multiply(new THREE.Matrix4().makeTranslation(0, -0.66, 0));

/** Escala dos adereços pequenos na demo: o boneco é de brinquedo (mão de 14 cm), uma moeda real sumiria. */
export const ESCALA_MOEDA = 2.5;

/** Objetos da ação `nome` no quadro `quadro`, no espaço do boneco (ponha junto do <Boneco>).
 *  `pele` desenha o polegar erguido no `jogarMoeda`. */
export const ObjetosDaAcao: React.FC<{ nome: string; quadro: number; pele?: string }> = ({ nome, quadro, pele = '#e9b48a' }) => {
  const j = juntasNoQuadro(nome, quadro);

  if (nome === 'escrever') {
    // tudo no espaço do tronco (onde a IK pôs as mãos): caderno na mão E, lápis na mão D com a ponta na página
    const inc = R(CADERNO_INCLINA);
    const c = new THREE.Vector3(...CADERNO_CENTRO);
    const alturaPagina = (z: number) => c.y + 0.006 / Math.cos(inc) - (z - c.z) * Math.tan(inc);
    const { p, levantado } = maoEscrevendo(quadro);
    // a ponta fica na página, por dentro e à frente da mão; o lápis sobe dali e atravessa o punho
    const pz = p[2] + 0.05;
    const ponta: V3 = [p[0] - 0.085, alturaPagina(pz) + 0.05 * levantado, pz];
    const dir = new THREE.Vector3(p[0] - ponta[0], p[1] - ponta[1], p[2] - ponta[2]).normalize();
    const qLapis = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
    return (
      <group matrixAutoUpdate={false} matrix={tronco(j)}>
        <group position={CADERNO_CENTRO} rotation={[inc, 0, 0]}><Caderno /></group>
        <group position={ponta} quaternion={qLapis}><Lapis /></group>
      </group>
    );
  }
  if (nome === 'jogarMoeda') {
    // a moeda sai de cima do polegar, sobe 50 cm girando e volta ao punho; o polegar fica em pé
    const f = ciclo(quadro, 60);
    const [ini, fim, alto] = MOEDA_VOO;
    const noAr = f >= ini && f < fim;
    const sobePunho = (p: V3): V3 => {
      const v = new THREE.Vector3(...p).applyMatrix4(tronco(j));
      return [v.x, v.y, v.z];
    };
    const punho = sobePunho(punhoMoeda(quadro));
    const lancou = sobePunho(punhoMoeda(quadro - f + ini));
    const p: V3 = noAr ? [lancou[0], lancou[1] + 0.12 + alto * alturaMoeda(f), lancou[2]] : [punho[0] - 0.005, punho[1] + 0.12, punho[2] + 0.01];
    return (
      <group>
        <group position={p} rotation={[noAr ? (f - 30) * 0.55 : R(-70), 0, 0]} scale={ESCALA_MOEDA}><Moeda /></group>
        <mesh position={[punho[0] - 0.015, punho[1] + 0.07, punho[2] + 0.02]} rotation={[0, 0, R(8)]} material={mat(pele)} castShadow>
          <capsuleGeometry args={[0.022, 0.04, 4, 10]} />
        </mesh>
      </group>
    );
  }
  if (nome === 'virarCabeca') {
    // linhas de giro: três arcos atrás da cabeça, do lado de onde ela saiu; aparecem no giro e somem 8 q depois
    const t = (quadro - VIRA[0]) / VIRA[1];
    const vis = t < 0 ? 0 : t <= 1 ? Math.min(1, t * 3) : Math.max(0, 1 - (quadro - VIRA[0] - VIRA[1]) / 8);
    if (vis <= 0.01) return null;
    // arcos horizontais ao lado da cabeça, do lado oposto ao giro (de 130° a 200° no plano XZ, a partir de +X)
    const cab = posicao(matrizCabeca(j));
    const lado = Math.sign(GIRO_CABECA);
    return (
      <group position={[cab.x, cab.y, cab.z]} scale={[lado, 1, 1]}>
        {[0, 1, 2].map((i) => (
          <mesh key={i} position={[0, 0.14 - i * 0.13, 0]} rotation={[Math.PI / 2, 0, R(130 + i * 6)]} material={mat('#ffffff')}>
            <torusGeometry args={[0.47 + i * 0.04, 0.013, 6, 20, R(70 - i * 12) * vis]} />
          </mesh>
        ))}
      </group>
    );
  }
  return null;
};
