// Lote l17-acao: ações de corpo para "E se a sua sorte DOBRASSE todo dia?".
// A mão segue um caminho em metros (espaço do boneco, que olha +Z) e a cinemática inversa do kit acha os ângulos.
// Tudo em função do quadro (30 fps), sem acaso. Os objetos (marcador, caneta, quadro) estão em objetos.tsx.
import * as THREE from 'three';
import { BASE, type Juntas } from '../../../kit/poses';
import { alturaNoChao, bracoNo } from './cinematica';

const v3 = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);
const suave = (t: number) => { const k = Math.min(1, Math.max(0, t)); return k * k * (3 - 2 * k); };
/** Trecho [a, b) do tempo, em 0..1 suave. */
const trecho = (q: number, a: number, b: number) => suave((q - a) / (b - a));
const mix = (a: number, b: number, k: number) => a + (b - a) * k;
/** Completa a pose: junta com a BASE, calcula o braço D e apoia o pé mais baixo no chão. */
const fechar = (p: Partial<Juntas>, mao: THREE.Vector3): Partial<Juntas> => {
  const j: Juntas = { ...BASE, ...p };
  const comBraco = { ...j, ...bracoNo(j, 1, mao) };
  return { ...comBraco, altura: alturaNoChao(comBraco) };
};

// ── riscar ────────────────────────────────────────────────────────────────
// Alvo à frente e à direita (de quem olha), na altura do rosto: o corpo vira 3/4 para ele, o tronco inclina,
// a perna D vai à frente e o braço D sobe estendido. O marcador aponta para +Z: a ponta fica 13 cm à frente da mão.
// O X (9 cm) tem centro a 1,42 m do chão, 55 cm para o lado (braço quase reto, na diagonal), e o alvo tem a
// face em z = 0,25. Nos cantos de fora a mão passa ~1 cm do alcance e a IK encurta de leve o traço.
export const RISCO = {
  centro: v3(0.55, 1.42, 0), meio: 0.045, // centro e meia-diagonal do X
  ponta: 0.13, // da mão à ponta do marcador
  encosta: 0.12, // z da mão com a ponta no alvo
  afasta: 0.06, // z da mão com a ponta no ar
};
export const FACE_ALVO = RISCO.encosta + RISCO.ponta;
const canto = (sx: number, sy: number, z: number) => v3(RISCO.centro.x + sx * RISCO.meio, RISCO.centro.y + sy * RISCO.meio, z);
// Linha do tempo (quadros): sobe o braço até 30; encosta 40–48; 1º traço 48–62; troca de canto; 2º traço 80–96; recua.
export const TEMPOS_RISCO = { sobe: [8, 30], encosta1: 40, traco1: [48, 62], sobe1: 62, troca: [66, 76], encosta2: 76, traco2: [80, 96], recua: 96 } as const;
const MAO_REPOUSO = v3(0.3, 0.68, 0.08);

/** Mão no quadro + quanto de cada traço já foi riscado (0..1). */
export function caminhoRiscar(q: number): { mao: THREE.Vector3; traco1: number; traco2: number } {
  const T = TEMPOS_RISCO, { encosta: zE, afasta: zA } = RISCO;
  const t1 = trecho(q, T.traco1[0], T.traco1[1]);
  const t2 = trecho(q, T.traco2[0], T.traco2[1]);
  let mao: THREE.Vector3;
  if (q < T.traco1[0]) {
    // levanta o braço até o canto de cima, espera no ar e encosta
    const z = zA + (zE - zA) * trecho(q, T.encosta1, T.traco1[0]);
    mao = MAO_REPOUSO.clone().lerp(canto(-1, 1, z), trecho(q, T.sobe[0], T.sobe[1]));
  } else if (q < T.sobe1) {
    mao = canto(-1, 1, zE).lerp(canto(1, -1, zE), t1);
  } else if (q < T.encosta2) {
    // tira a ponta, vai em arco ao outro canto de cima, ainda no ar
    const z = zE + (zA - zE) * trecho(q, T.sobe1, T.troca[0]);
    const k = trecho(q, T.troca[0], T.troca[1]);
    mao = canto(1, -1 + 2 * k, z).add(v3(0, 0, -0.03 * Math.sin(Math.PI * k)));
  } else if (q < T.traco2[0]) {
    mao = canto(1, 1, zA + (zE - zA) * trecho(q, T.encosta2, T.traco2[0]));
  } else if (q < T.recua) {
    mao = canto(1, 1, zE).lerp(canto(-1, -1, zE), t2);
  } else {
    // recua um pouco: "pronto"
    const k = trecho(q, T.recua, T.recua + 12);
    mao = canto(-1, -1, zE).add(v3(-0.02 * k, -0.04 * k, -0.08 * k));
  }
  return { mao, traco1: t1, traco2: t2 };
}

export function riscar(q: number): Partial<Juntas> {
  const k = trecho(q, 6, 30); // entra na postura junto com a subida do braço
  const { mao, traco1, traco2 } = caminhoRiscar(q);
  // empurrão do tronco durante cada traço (sobe 1,5° no meio do traço)
  const forca = Math.sin(Math.PI * traco1) + Math.sin(Math.PI * traco2);
  return fechar({
    troncoX: 9 * k + 1.5 * forca, troncoY: 16 * k,
    quadrilD: 14 * k, joelhoD: 6 * k, quadrilE: -9 * k, joelhoE: 4 * k, // passada: perna D à frente
    ombroEX: 22 * k, ombroEZ: 4 + 14 * k, cotoveloE: 8 + 52 * k, // braço E dobrado, mão junto à barriga
    cabecaY: 8 * k, cabecaX: -9 * k, cabecaZ: 0, // olha o alvo, para cima; o giro total fica em 24°
  }, mao);
}
export const RISCAR: Partial<Juntas> = riscar(90);

// ── entregar ──────────────────────────────────────────────────────────────
// Quem recebe fica à frente e à direita (de quem olha), a ~1 m. O corpo vira 22° para ele, inclina e dá um passo;
// o braço D estende quase reto, com a mão a 1,0 m do chão e 40 cm à frente. A caneta sai da mão para +Z
// (a ponta oferecida fica 15 cm adiante). Antes do quadro 34 a mão segura a caneta junto ao peito; estende
// entre 34 e 52; depois dá um "toma!" (avança 3 cm) a cada 36 quadros.
export const MAO_ENTREGA = v3(0.42, 1.0, 0.4);
const MAO_PEITO = v3(0.2, 0.92, 0.2);
export function maoEntregar(q: number): THREE.Vector3 {
  const k = trecho(q, 34, 52);
  const f = ((((q - 52) % 36) + 36) % 36) / 36;
  const toma = q >= 52 ? Math.sin(Math.PI * Math.min(1, f / 0.4)) * (f < 0.4 ? 1 : 0) : 0;
  return MAO_PEITO.clone().lerp(MAO_ENTREGA, k).add(v3(0.01 * toma, 0, 0.03 * toma));
}
export function entregar(q: number): Partial<Juntas> {
  const k = trecho(q, 34, 52);
  const g = trecho(q, 10, 34); // primeiro vira para quem recebe, depois estende
  return fechar({
    troncoX: 3 + 9 * k, troncoY: 22 * g,
    quadrilD: 18 * k, joelhoD: 12 * k, quadrilE: -6 * k, joelhoE: 3, // passo à frente com a perna D
    ombroEX: 12 * k, ombroEZ: 6, cotoveloE: 10 + 22 * k, // braço E solto, mão à frente do quadril
    cabecaY: 3 * g, cabecaX: 2 * k, cabecaZ: 5 * k, // olha quem recebe; cabeça pende: gesto simpático
  }, maoEntregar(q));
}
export const ENTREGAR: Partial<Juntas> = entregar(90);

export const ACOES: Record<string, { pose: Partial<Juntas>; animar: (q: number) => Partial<Juntas> }> = {
  riscar: { pose: RISCAR, animar: riscar },
  entregar: { pose: ENTREGAR, animar: entregar },
};
export const juntasNoQuadro = (nome: string, q: number): Juntas => ({ ...BASE, ...ACOES[nome].pose, ...ACOES[nome].animar(q) });
