// Ajuste exclusivo da vitrine; modelos em metros e sem câmera própria.
import React, { useLayoutEffect } from 'react';
import { useThree } from '@react-three/fiber';
import { useVideoConfig } from 'remotion';
import type { PerspectiveCamera } from 'three';
import type { V3 } from './base';

type Enquadramento = { pos: V3; alvo: V3; deslocamento: V3 };

export const ENQUADRAMENTOS: Record<'moedas' | 'sol' | 'barreira', Enquadramento> = {
  moedas: { pos: [1.2, 3, 3.8], alvo: [0.65, 0.8, 0], deslocamento: [0.2, 0, -0.2] },
  sol: { pos: [1.8, 2.65, 8.6], alvo: [1.8, 2.05, 0], deslocamento: [2.25, 0, 0] },
  barreira: { pos: [1.4, 1.9, 6.4], alvo: [1.25, 1.45, 0], deslocamento: [1.1, 0, 0] },
};

const AjustarCameraExistente: React.FC<{ enquadramento: Enquadramento }> = ({ enquadramento }) => {
  const camera = useThree((estado) => estado.camera) as PerspectiveCamera;
  // Depois da câmera do palco, em cada quadro; sem loop próprio.
  useLayoutEffect(() => {
    camera.position.set(...enquadramento.pos);
    camera.fov = 36;
    camera.zoom = 1;
    camera.lookAt(...enquadramento.alvo);
    camera.updateProjectionMatrix();
    camera.updateMatrixWorld();
  });
  return null;
};

export const Apresentacao: React.FC<{
  peca: keyof typeof ENQUADRAMENTOS; children: React.ReactNode;
}> = ({ peca, children }) => {
  const { id } = useVideoConfig();
  if (id !== 'VitrineLote') return <>{children}</>;
  const enquadramento = ENQUADRAMENTOS[peca];
  return (
    <>
      <AjustarCameraExistente enquadramento={enquadramento} />
      <group position={enquadramento.deslocamento}>{children}</group>
    </>
  );
};
