// Guarda-chuva amarelo fechado, 80 cm de ponta a ponta: ponteira embaixo (origem), pano enrolado liso, cinta com botão,
// cabo reto marrom e gancho curvo (curva para -X). Tudo de revolução com 64 lados e ombro em esfera: sem gomos facetados.
import React from 'react';
import { Cil, mat } from './base';

export const GUARDA = {
  comp: 0.8,
  /** altura (no eixo do guarda-chuva) onde a mão segura o cabo reto */
  pega: 0.65,
};
const AMARELO = '#f6c531', AMARELO_ESC = '#dba21c', MARROM = '#7a4a26', MARROM_ESC = '#5c3519';
const R_CABO = 0.017, R_GANCHO = 0.045;

export const GuardaChuva: React.FC = () => {
  const topoCabo = GUARDA.comp - R_GANCHO - R_CABO; // 0,738: o gancho sobe até 0,80
  return (
    <group>
      {/* ponteira marrom grossa e arredondada (7,6 cm), um pouco mais larga que a ponta do pano */}
      <mesh position={[0, 0.038, 0]} material={mat(MARROM_ESC)} castShadow receiveShadow><capsuleGeometry args={[0.021, 0.034, 12, 40]} /></mesh>
      {/* pano enrolado: afina até a ponta; o ombro largo é uma esfera achatada (sem quina) e fecha num cone curto */}
      <Cil p={[0, 0.27, 0]} raio={0.04} raio2={0.017} h={0.42} cor={AMARELO} lados={64} />
      <mesh position={[0, 0.48, 0]} scale={[1, 0.9, 1]} material={mat(AMARELO)} castShadow receiveShadow><sphereGeometry args={[0.04, 48, 24]} /></mesh>
      <Cil p={[0, 0.515, 0]} raio={0.02} raio2={0.034} h={0.05} cor={AMARELO} lados={64} />
      {/* cinta (amarelo escuro, por cima do pano) com botão marrom */}
      <Cil p={[0, 0.33, 0]} raio={0.036} raio2={0.034} h={0.045} cor={AMARELO_ESC} lados={64} />
      <mesh position={[0, 0.33, 0.035]} scale={[1, 1, 0.5]} material={mat(MARROM)} castShadow><sphereGeometry args={[0.012, 16, 10]} /></mesh>
      {/* colar no topo do pano */}
      <Cil p={[0, 0.55, 0]} raio={0.022} h={0.03} cor={AMARELO_ESC} lados={64} />
      {/* cabo reto marrom + gancho em meia-rosca + ponta que desce um pouco */}
      <Cil p={[0, (0.565 + topoCabo) / 2, 0]} raio={R_CABO} h={topoCabo - 0.565} cor={MARROM} />
      <mesh position={[-R_GANCHO, topoCabo, 0]} material={mat(MARROM)} castShadow receiveShadow>
        <torusGeometry args={[R_GANCHO, R_CABO, 16, 40, Math.PI]} />
      </mesh>
      <mesh position={[-2 * R_GANCHO, topoCabo - 0.02, 0]} material={mat(MARROM)} castShadow receiveShadow>
        <capsuleGeometry args={[R_CABO, 0.04, 8, 16]} />
      </mesh>
    </group>
  );
};
