// Base do lote l20-efeito: cache de material por cor (padrão do Quadra.tsx) e formas comuns (retângulo arredondado, disco).
import * as THREE from 'three';
import React from 'react';

export type V3 = [number, number, number];

const cache = new Map<string, THREE.MeshStandardMaterial>();
/** Material chapado (roughness 0,85). `brilho` > 0 acende a cor (tela). Brilho arredondado: o cache não cresce. */
export const mat = (cor: string, brilho = 0, rug = 0.85) => {
  const b = Math.round(brilho * 20) / 20;
  const k = `${cor}|${b}|${rug}`;
  let m = cache.get(k);
  if (!m) {
    m = new THREE.MeshStandardMaterial({ color: cor, roughness: rug });
    if (b > 0) { m.emissive = new THREE.Color(cor); m.emissiveIntensity = b; }
    cache.set(k, m);
  }
  return m;
};

/** Suaviza 0..1 (smoothstep). */
export const suave = (t: number) => { const x = Math.min(1, Math.max(0, t)); return x * x * (3 - 2 * x); };

/** Retângulo de cantos arredondados (2 caixas em cruz + 4 cilindros), espessura d em Z. */
export const Ret: React.FC<{ w: number; h: number; d: number; r: number; x?: number; y?: number; z: number; m: THREE.Material; sombra?: boolean }> = ({ w, h, d, r, x = 0, y = 0, z, m, sombra = false }) => (
  <group position={[x, y, z]}>
    <mesh material={m} castShadow={sombra} receiveShadow><boxGeometry args={[w - 2 * r, h, d]} /></mesh>
    <mesh material={m} castShadow={sombra} receiveShadow><boxGeometry args={[w, h - 2 * r, d]} /></mesh>
    {([[-1, -1], [1, -1], [-1, 1], [1, 1]] as const).map(([sx, sy]) => (
      <mesh key={`${sx}${sy}`} position={[sx * (w / 2 - r), sy * (h / 2 - r), 0]} rotation={[Math.PI / 2, 0, 0]} material={m} castShadow={sombra} receiveShadow>
        <cylinderGeometry args={[r, r, d, 16]} />
      </mesh>
    ))}
  </group>
);

/** Disco virado para +Z. */
export const Disco: React.FC<{ r: number; d: number; x: number; y: number; z: number; m: THREE.Material }> = ({ r, d, x, y, z, m }) => (
  <mesh position={[x, y, z]} rotation={[Math.PI / 2, 0, 0]} material={m}><cylinderGeometry args={[r, r, d, 20]} /></mesh>
);

/** Traço reto de a até b (caixa de seção e x d), com as pontas cobertas. */
export const Traco: React.FC<{ a: [number, number]; b: [number, number]; e: number; d: number; z: number; m: THREE.Material }> = ({ a, b, e, d, z, m }) => {
  const dx = b[0] - a[0], dy = b[1] - a[1];
  return (
    <mesh position={[(a[0] + b[0]) / 2, (a[1] + b[1]) / 2, z]} rotation={[0, 0, Math.atan2(dy, dx)]} material={m}>
      <boxGeometry args={[Math.hypot(dx, dy) + e, e, d]} />
    </mesh>
  );
};
