// Base do lote r12-objeto: cache de material por cor, retângulo de cantos redondos e "traços" (texto feito de caixas).
import * as THREE from 'three';
import React from 'react';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';

const cache = new Map<string, THREE.MeshStandardMaterial>();
/** Material chapado (roughness 0.85). `brilho` > 0 acende a cor (tela acesa). */
export const mat = (cor: string, o: { brilho?: number; rug?: number } = {}) => {
  const { brilho = 0, rug = 0.85 } = o;
  const k = [cor, brilho, rug].join('|');
  let m = cache.get(k);
  if (!m) {
    m = new THREE.MeshStandardMaterial({ color: cor, roughness: rug });
    if (brilho > 0) { m.emissive = new THREE.Color(cor); m.emissiveIntensity = brilho; }
    cache.set(k, m);
  }
  return m;
};

/** Retângulo de cantos arredondados no plano XY, espessura d em Z: 2 caixas em cruz + 4 cilindros. */
export const Ret: React.FC<{ w: number; h: number; d: number; r: number; x?: number; y?: number; z: number; m: THREE.Material; sombra?: boolean }> = ({ w, h, d, r, x = 0, y = 0, z, m, sombra = false }) => (
  <group position={[x, y, z]}>
    <mesh material={m} castShadow={sombra} receiveShadow><boxGeometry args={[w - 2 * r, h, d]} /></mesh>
    <mesh material={m} castShadow={sombra} receiveShadow><boxGeometry args={[w, h - 2 * r, d]} /></mesh>
    {([[-1, -1], [1, -1], [-1, 1], [1, 1]] as const).map(([sx, sy]) => (
      <mesh key={`${sx}${sy}`} position={[sx * (w / 2 - r), sy * (h / 2 - r), 0]} rotation={[Math.PI / 2, 0, 0]} material={m} castShadow={sombra} receiveShadow>
        <cylinderGeometry args={[r, r, d, 16]} />
      </mesh>
    ))}
  </group>
);

/** Traço 2D: segmento (x1,y1)→(x2,y2) com largura `l`, no plano XY. */
export type Traco = [number, number, number, number];

/** Junta muitos traços (caixas) numa geometria só: 1 mesh por cor em vez de centenas. */
export const geoTracos = (tracos: Traco[], l: number, d: number) => {
  const partes = tracos.map(([x1, y1, x2, y2]) => {
    const dx = x2 - x1, dy = y2 - y1, comp = Math.hypot(dx, dy) + l; // + l: pontas se encontram nos cantos
    const g = new THREE.BoxGeometry(comp, l, d);
    g.rotateZ(Math.atan2(dy, dx));
    g.translate((x1 + x2) / 2, (y1 + y2) / 2, 0);
    return g;
  });
  return mergeGeometries(partes)!;
};

export const Tracos: React.FC<{ tracos: Traco[]; l: number; d?: number; z: number; m: THREE.Material }> = ({ tracos, l, d = 0.0006, z, m }) => {
  const geo = React.useMemo(() => geoTracos(tracos, l, d), [tracos, l, d]);
  return <mesh geometry={geo} position={[0, 0, z]} material={m} receiveShadow />;
};

// Display de 7 segmentos: a (cima), b (cima-dir), c (baixo-dir), d (baixo), e (baixo-esq), f (cima-esq), g (meio)
const SEG: Record<string, string> = {
  '0': 'abcdef', '1': 'bc', '2': 'abged', '3': 'abgcd', '4': 'fgbc', '5': 'afgcd', '6': 'afgedc', '7': 'abc', '8': 'abcdefg', '9': 'abcdfg',
};

/** Traços de um texto (dígitos, '+', 'x', '='), com a base em (x, y); `incl` inclina como letra de mão. */
export const textoTracos = (txt: string, x: number, y: number, w: number, h: number, passo: number, incl = 0): Traco[] => {
  const t: Traco[] = [];
  [...txt].forEach((ch, i) => {
    const x0 = x + i * passo;
    const P = (px: number, py: number): [number, number] => [x0 + px * w + incl * py * h, y + py * h];
    const S = (a: [number, number], b: [number, number]) => t.push([a[0], a[1], b[0], b[1]]);
    const seg: Record<string, () => void> = {
      a: () => S(P(0, 1), P(1, 1)), b: () => S(P(1, 1), P(1, 0.5)), c: () => S(P(1, 0.5), P(1, 0)), d: () => S(P(0, 0), P(1, 0)),
      e: () => S(P(0, 0), P(0, 0.5)), f: () => S(P(0, 0.5), P(0, 1)), g: () => S(P(0, 0.5), P(1, 0.5)),
    };
    // "1" no meio da casa e com bandeirinha (no canto direito ele se separa do vizinho e vira "I")
    if (ch === '1') { S(P(0.6, 1), P(0.6, 0)); S(P(0.6, 1), P(0.25, 0.75)); }
    else if (SEG[ch]) [...SEG[ch]].forEach((s) => seg[s]());
    else if (ch === '+') { S(P(0.5, 0.2), P(0.5, 0.8)); S(P(0.1, 0.5), P(0.9, 0.5)); }
    else if (ch === 'x') { S(P(0.15, 0.2), P(0.85, 0.75)); S(P(0.15, 0.75), P(0.85, 0.2)); }
    else if (ch === '=') { S(P(0.1, 0.35), P(0.9, 0.35)); S(P(0.1, 0.65), P(0.9, 0.65)); }
  });
  return t;
};

/** Gira o objeto para trás em volta da aresta de baixo de trás (z = 0): em pé (0°) até deitado (90°), sem entrar no apoio. */
export const Inclinado: React.FC<{ graus: number; children: React.ReactNode }> = ({ graus, children }) => (
  <group rotation={[-(graus * Math.PI) / 180, 0, 0]}>{children}</group>
);
