// Banheiro fechado; a câmera da vitrine fica dentro do cômodo.
import React from 'react';
import * as THREE from 'three';
import { Caixa, Disco, Haste, mat, type V3 } from './base';

const C = {
  branco: '#ffffff', rejunte: '#e6e2dc', teto: '#fff9ee',
  piso: '#f5e7cd', piso2: '#d5ae7d', louca: '#fffdf7', cuba: '#dcecf1',
  metal: '#7e929d', gabinete: '#29a99a', puxador: '#f2bd52',
  espelho: '#bee6f1', moldura: '#eeb854', ceu: '#aaddf8', sol: '#fff1b3',
};
const X = 2.08, H = 3.2, FUNDO = -2.08, FRENTE = 7.52;
const PASSO = 0.08;
const cacheGrade = new Map<string, THREE.MeshStandardMaterial>();
const cachePlano = new Map<string, THREE.BufferGeometry>();

const materialGrade = (cor: string) => {
  let material = cacheGrade.get(cor);
  if (!material) {
    material = new THREE.MeshStandardMaterial({ color: cor, roughness: 0.85, vertexColors: true });
    cacheGrade.set(cor, material);
  }
  return material;
};

// Uma primitiva plana: o rejunte é só cor nas faces, sem peças salientes.
const planoAzulejado = (largura: number, altura: number, u: number, v: number) => {
  const chave = [largura, altura, u, v].join('|');
  let plano = cachePlano.get(chave);
  if (!plano) {
    const colunas = Math.round(largura / PASSO), linhas = Math.round(altura / PASSO);
    const primitiva = new THREE.PlaneGeometry(largura, altura, colunas, linhas);
    plano = primitiva.toNonIndexed();
    primitiva.dispose();
    const cores = new Float32Array(plano.attributes.position.count * 3);
    const branco = new THREE.Color(C.branco), rejunte = new THREE.Color(C.rejunte);
    for (let linha = 0; linha < linhas; linha++) {
      for (let coluna = 0; coluna < colunas; coluna++) {
        const gx = Math.round((u - largura / 2) / PASSO) + coluna;
        const gy = Math.round((v + altura / 2) / PASSO) - linha - 1;
        const modulo = (n: number) => ((n % 8) + 8) % 8;
        const cor = modulo(gx) === 0 || modulo(gy) === 0 ? rejunte : branco;
        const inicio = (linha * colunas + coluna) * 18;
        for (let vertice = 0; vertice < 6; vertice++) cor.toArray(cores, inicio + vertice * 3);
      }
    }
    plano.setAttribute('color', new THREE.BufferAttribute(cores, 3));
    cachePlano.set(chave, plano);
  }
  return plano;
};

const Revestimento: React.FC<{ p: V3; largura: number; altura: number; giro?: number; u?: number }> =
  ({ p, largura, altura, giro = 0, u = p[0] }) => (
    <mesh position={p} rotation={[0, giro, 0]} geometry={planoAzulejado(largura, altura, u, p[1])}
      material={materialGrade(C.branco)} receiveShadow />
  );

const Paredes: React.FC = () => {
  // Abertura real de 1,28 m, no alto à direita da parede de trás.
  const trechos: [number, number, number, number][] = [
    [-0.72, H / 2, 2.72, H], [2, H / 2, 0.16, H],
    [1.28, 0.88, 1.28, 1.76], [1.28, 3.12, 1.28, 0.16],
  ];
  const comprimento = FRENTE - FUNDO, centro = (FRENTE + FUNDO) / 2;
  return (
    <group>
      {trechos.map(([x, y, largura, altura], i) => (
        <group key={i}>
          <Caixa p={[x, y, FUNDO - 0.12]} t={[largura, altura, 0.2]} cor={C.branco} sombra={false} />
          <Revestimento p={[x, y, FUNDO]} largura={largura} altura={altura} />
        </group>
      ))}
      {([-1, 1] as const).map((lado) => (
        <group key={lado}>
          <Caixa p={[lado * (X + 0.12), H / 2, centro]} t={[0.2, H, comprimento + 0.44]} cor={C.branco} sombra={false} />
          <Revestimento p={[lado * X, H / 2, centro]} largura={comprimento} altura={H}
            giro={-lado * Math.PI / 2} u={centro} />
        </group>
      ))}
      {/* Fechamento atrás da câmera; piso e teto terminam nas paredes. */}
      <Caixa p={[0, H / 2, FRENTE + 0.12]} t={[2 * X, H, 0.2]} cor={C.branco} sombra={false} />
      <Caixa p={[0, H + 0.04, centro]} t={[2 * X, 0.08, comprimento]} cor={C.teto} sombra={false} />
      {/* Casca sem projetar sombra: mantém a luz quente do palco dentro da sala. */}
    </group>
  );
};

const Pia: React.FC = () => (
  <group position={[0, 0, -1.7]}>
    {/* Gabinete de 1 m e bancada a 95 cm; a cuba fica realmente rebaixada. */}
    <Caixa p={[0, 0.42, 0]} t={[1, 0.64, 0.6]} cor={C.gabinete} />
    <Caixa p={[0, 0.06, 0]} t={[0.84, 0.12, 0.5]} cor={C.metal} />
    <Caixa p={[0, 0.78, 0]} t={[1.12, 0.08, 0.7]} cor={C.cuba} />
    {[-1, 1].map((lado) => (
      <group key={lado}>
        <Caixa p={[lado * 0.46, 0.885, 0]} t={[0.2, 0.13, 0.7]} cor={C.louca} />
        <Caixa p={[0, 0.885, lado * 0.28]} t={[0.72, 0.13, 0.14]} cor={C.louca} />
        <Caixa p={[lado * 0.24, 0.57, 0.34]} t={[0.16, 0.08, 0.08]} cor={C.puxador} />
      </group>
    ))}
    <mesh position={[0, 0.84, 0.04]} material={mat(C.metal)} castShadow receiveShadow>
      <cylinderGeometry args={[0.045, 0.045, 0.08, 16]} />
    </mesh>
    <Haste a={[0, 0.94, -0.28]} b={[0, 1.15, -0.28]} cor={C.metal} />
    <Haste a={[0, 1.15, -0.28]} b={[0, 1.15, -0.08]} cor={C.metal} />
    <Haste a={[0, 1.15, -0.08]} b={[0, 1.07, -0.08]} cor={C.metal} />
    <Caixa p={[0.14, 1.02, -0.28]} t={[0.16, 0.08, 0.1]} cor={C.metal} />
    <Caixa p={[-0.44, 0.99, 0.06]} t={[0.16, 0.08, 0.22]} cor="#f1a06b" />
  </group>
);

const Espelho: React.FC = () => (
  <group position={[-0.12, 1.86, FUNDO]}>
    <Disco p={[0, 0, 0.08]} raio={0.47} espessura={0.16} cor={C.moldura} />
    {/* Superfície lisa; sem rabiscos de reflexo sobre o rosto. */}
    <Disco p={[0, 0, 0.22]} raio={0.38} espessura={0.08} cor={C.espelho} />
  </group>
);

const Janela: React.FC = () => (
  <group position={[1.28, 2.4, FUNDO]}>
    <Caixa p={[0, 0, -0.4]} t={[1.44, 1.44, 0.08]} cor={C.ceu} sombra={false} />
    <Disco p={[0.33, 0.3, -0.28]} raio={0.15} espessura={0.08} cor={C.sol} />
    {[-1, 1].map((lado) => (
      <group key={lado}>
        <Caixa p={[lado * 0.6, 0, -0.04]} t={[0.08, 1.28, 0.32]} cor={C.louca} />
        <Caixa p={[0, lado * 0.6, -0.04]} t={[1.12, 0.08, 0.32]} cor={C.louca} />
      </group>
    ))}
    <Caixa p={[0, -0.7, 0.04]} t={[1.44, 0.12, 0.4]} cor={C.louca} />
  </group>
);

export const Banheiro: React.FC = () => (
  <group>
    {/* Ladrilhos contíguos: topo em y=0 e bordas nos limites internos da sala. */}
    {Array.from({ length: 8 }, (_, x) => Array.from({ length: 15 }, (_, z) => (
      <Caixa key={`${x}-${z}`} p={[-X + 0.26 + x * 0.52, -0.08, FUNDO + 0.32 + z * 0.64]}
        t={[0.52, 0.16, 0.64]} cor={(x + z) % 2 === 0 ? C.piso : C.piso2} sombra={false} />
    )))}
    <Paredes />
    <Pia />
    <Espelho />
    <Janela />
  </group>
);
