import React from 'react';
import { Lousa } from './Lousa';
import { Moeda } from './Moeda';
import { PaoQuente } from './PaoQuente';

// Ajustes só da exposição; os modelos originais continuam em metros reais.
// O piso da Quadra termina em y=0,01: 1,2 cm evita enterrar peças baixas.
export const MoedaNaVitrine: React.FC = () => (
  <group position={[0, 0.012, 0]} scale={3}><Moeda /></group>
);

export const PaoNaVitrine: React.FC = () => (
  <group position={[0, 0.012, 0]} scale={2}><PaoQuente /></group>
);

// Recua e desloca o objeto inteiro; pés e escrita mantêm o mesmo centro.
export const LousaNaVitrine: React.FC = () => (
  <group position={[0.45, 0.012, -1.6]}><Lousa /></group>
);
