// Base do lote r19-objeto: cache de material por cor, primitivas posicionadas, retângulo de cantos redondos
// e dígitos de 7 segmentos (todos os traços de uma cor num só InstancedMesh).
import * as THREE from 'three';
import React, { useLayoutEffect, useRef } from 'react';

const cache = new Map<string, THREE.MeshStandardMaterial>();
/** Material chapado (roughness 0.85 por padrão), um por cor + rugosidade + metal. */
export const mat = (cor: string, rug = 0.85, metal = 0) => {
  const k = `${cor}|${rug}|${metal}`;
  let m = cache.get(k);
  if (!m) { m = new THREE.MeshStandardMaterial({ color: cor, roughness: rug, metalness: metal }); cache.set(k, m); }
  return m;
};

export type V3 = [number, number, number];
type Sombra = { sombra?: boolean; recebe?: boolean };
export const R = THREE.MathUtils.degToRad;

export const Caixa: React.FC<{ p: V3; t: V3; cor: string; r?: V3; m?: THREE.Material } & Sombra> = ({ p, t, cor, r, m, sombra = true, recebe = true }) => (
  <mesh position={p} rotation={r} material={m ?? mat(cor)} castShadow={sombra} receiveShadow={recebe}><boxGeometry args={t} /></mesh>
);

/** Cilindro em pé (eixo Y); `r` gira (ex.: [PI/2,0,0] deita o disco de frente para +Z). */
export const Cil: React.FC<{ p: V3; raio: number; h: number; cor: string; raio2?: number; lados?: number; r?: V3; m?: THREE.Material } & Sombra> = (
  { p, raio, h, cor, raio2, lados = 32, r, m, sombra = true, recebe = true },
) => (
  <mesh position={p} rotation={r} material={m ?? mat(cor)} castShadow={sombra} receiveShadow={recebe}><cylinderGeometry args={[raio, raio2 ?? raio, h, lados]} /></mesh>
);

/** Retângulo de cantos arredondados no plano XY, espessura d em Z (2 caixas em cruz + 4 cilindros). */
export const Ret: React.FC<{ w: number; h: number; d: number; r: number; p: V3; cor: string; m?: THREE.Material } & Sombra> = (
  { w, h, d, r, p, cor, m, sombra = false, recebe = true },
) => {
  const mm = m ?? mat(cor);
  return (
    <group position={p}>
      <mesh material={mm} castShadow={sombra} receiveShadow={recebe}><boxGeometry args={[w - 2 * r, h, d]} /></mesh>
      <mesh material={mm} castShadow={sombra} receiveShadow={recebe}><boxGeometry args={[w, h - 2 * r, d]} /></mesh>
      {([[-1, -1], [1, -1], [-1, 1], [1, 1]] as const).map(([sx, sy]) => (
        <mesh key={`${sx}${sy}`} position={[sx * (w / 2 - r), sy * (h / 2 - r), 0]} rotation={[Math.PI / 2, 0, 0]} material={mm} castShadow={sombra} receiveShadow={recebe}>
          <cylinderGeometry args={[r, r, d, 12]} />
        </mesh>
      ))}
    </group>
  );
};

// ── dígitos de 7 segmentos ────────────────────────────────────────────────
//   a
//  f b
//   g
//  e c
//   d
const SEGS: Record<string, string> = {
  '0': 'abcdef', '1': 'bc', '2': 'abged', '3': 'abgcd', '4': 'fgbc',
  '5': 'afgcd', '6': 'afgedc', '7': 'abc', '8': 'abcdefg', '9': 'abcdfg',
};
export type Seg = [number, number, number, number]; // x, y, largura, altura
/** Retângulos de um dígito centrado em (cx, cy), w x h, traço s. Os traços se sobrepõem nos cantos (dígito inteiriço). */
export function segmentos(d: string, cx: number, cy: number, w: number, h: number, s: number): Seg[] {
  const out: Seg[] = [];
  const meio = (h - s) / 2 + s;
  for (const c of SEGS[d] ?? '') {
    if (c === 'a') out.push([0, h / 2 - s / 2, w, s]);
    if (c === 'g') out.push([0, 0, w, s]);
    if (c === 'd') out.push([0, -h / 2 + s / 2, w, s]);
    if (c === 'f') out.push([-w / 2 + s / 2, h / 4, s, meio]);
    if (c === 'b') out.push([w / 2 - s / 2, h / 4, s, meio]);
    if (c === 'e') out.push([-w / 2 + s / 2, -h / 4, s, meio]);
    if (c === 'c') out.push([w / 2 - s / 2, -h / 4, s, meio]);
  }
  // o "1" vai para o meio da casa (encostado à direita lê como "I" deslocado)
  const dx = d === '1' ? -(w / 2 - s / 2) * 0.5 : 0;
  return out.map(([x, y, a, b]) => [cx + x + dx, cy + y, a, b]);
}
/** Número com vários dígitos centrado em (cx, cy); `vao` entre dígitos. */
export function numero(n: string, cx: number, cy: number, w: number, h: number, s: number, vao: number): Seg[] {
  const larg = n.length * w + (n.length - 1) * vao;
  return [...n].flatMap((d, i) => segmentos(d, cx - larg / 2 + w / 2 + i * (w + vao), cy, w, h, s));
}

const geoSeg = new THREE.BoxGeometry(1, 1, 1);
/** Todos os traços de uma cor num InstancedMesh (caixa de 1 m escalada por instância), no plano z, relevo `prof`. */
export const Tracos: React.FC<{ segs: Seg[]; z: number; prof: number; cor: string }> = ({ segs, z, prof, cor }) => {
  const ref = useRef<THREE.InstancedMesh>(null);
  useLayoutEffect(() => {
    const im = ref.current; if (!im) return;
    const m = new THREE.Matrix4();
    segs.forEach(([x, y, w, h], i) => { m.makeScale(w, h, prof).setPosition(x, y, z); im.setMatrixAt(i, m); });
    im.instanceMatrix.needsUpdate = true;
    im.computeBoundingSphere();
  }, [segs, z, prof]);
  return <instancedMesh ref={ref} args={[geoSeg, mat(cor, 0.8), segs.length]} receiveShadow frustumCulled={false} />;
};
