// Rua transversal. Passeio em y=0; pista rebaixada e frente livre.
import React from 'react';
import { Caixa, Copa, Haste, mat, type V3 } from './base';

const C = {
  passeio: '#adb7bd', borda: '#738591', asfalto: '#536471',
  grama: '#7fa856', tronco: '#91613d', metal: '#46586b', branco: '#f6ebd4', vidro: '#2e688b',
};

const Chao: React.FC = () => (
  <group>
    <Caixa p={[0, -0.36, -2]} t={[44, 0.24, 40]} cor={C.grama} sombra={false} />
    <Caixa p={[0, -0.08, 3.3]} t={[36, 0.16, 9.4]} cor={C.passeio} sombra={false} />
    {/* Meio-fio com face de 24 cm sobre a pista. */}
    <Caixa p={[0, -0.1, -1.54]} t={[36, 0.28, 0.28]} cor={C.borda} />
    <Caixa p={[0, -0.26, -3.75]} t={[36, 0.12, 4.14]} cor={C.asfalto} sombra={false} />
    <Caixa p={[0, -0.1, -5.96]} t={[36, 0.28, 0.28]} cor={C.borda} />
    <Caixa p={[0, -0.08, -6.48]} t={[36, 0.16, 0.76]} cor={C.passeio} sombra={false} />
    <Caixa p={[0, -0.08, -10.86]} t={[36, 0.16, 8]} cor={C.grama} sombra={false} />
    {/* Faixas assentadas no asfalto, todas no mesmo eixo. */}
    {Array.from({ length: 13 }, (_, i) => (i - 6) * 2.5).map((x) => (
      <Caixa key={x} p={[x, -0.24, -3.75]} t={[1.25, 0.08, 0.16]} cor="#efc458" sombra={false} />
    ))}
  </group>
);

type DadosCasa = {
  x: number; cor: string; porta: string; altura: number;
  telhado: 'laje' | 'duasAguas'; espelhada?: boolean;
};

const Casa: React.FC<DadosCasa> = ({ x, cor, porta, altura, telhado, espelhada = false }) => {
  const lado = espelhada ? -1 : 1;
  const alturaJanela = telhado === 'laje' ? 0.8 : 1.1;
  return (
    <group position={[x, 0, -8.02]}>
      <Caixa p={[0, altura / 2, 0]} t={[2.7, altura, 2.3]} cor={cor} />
      <Caixa p={[0, 0.15, 1.22]} t={[2.7, 0.3, 0.1]} cor="#ccc5b3" />
      {telhado === 'duasAguas' ? (
        <group>
          <group position={[0, altura, 0]} scale={[1, 0.33, 1]}>
            <Caixa p={[0, 0, 0]} t={[1.91, 1.91, 2.3]} r={[0, 0, Math.PI / 4]} cor={cor} />
          </group>
          <Caixa p={[-0.72, altura + 0.25, 0]} t={[1.62, 0.16, 2.62]} r={[0, 0, 0.32]} cor="#ae5841" />
          <Caixa p={[0.72, altura + 0.25, 0]} t={[1.62, 0.16, 2.62]} r={[0, 0, -0.32]} cor="#ae5841" />
          <Haste a={[0, altura + 0.5, -1.32]} b={[0, altura + 0.5, 1.32]} r={0.09} cor="#c66c48" />
        </group>
      ) : (
        <group>
          <Caixa p={[0, altura + 0.09, 0]} t={[2.94, 0.18, 2.54]} cor={C.branco} />
          <Caixa p={[0, altura + 0.29, -0.06]} t={[2.7, 0.22, 2.3]} cor={cor} />
        </group>
      )}
      <Caixa p={[-0.78 * lado, 0.97, 1.27]} t={[0.86, 1.94, 0.16]} cor={C.branco} />
      <Caixa p={[-0.78 * lado, 0.91, 1.41]} t={[0.64, 1.82, 0.08]} cor={porta} />
      <Caixa p={[-0.58 * lado, 0.92, 1.51]} t={[0.08, 0.16, 0.08]} cor="#efd194" />
      <Caixa p={[0.57 * lado, 1.4, 1.27]} t={[1.18, alturaJanela, 0.16]} cor={C.branco} />
      <Caixa p={[0.57 * lado, 1.4, 1.41]} t={[0.94, alturaJanela - 0.24, 0.08]} cor={C.vidro} />
      <Caixa p={[0.57 * lado, 1.4, 1.51]} t={[0.1, alturaJanela - 0.24, 0.08]} cor={C.branco} />
      <Caixa p={[0.57 * lado, 1.34 - alturaJanela / 2, 1.41]} t={[1.32, 0.12, 0.32]} cor={C.branco} />
      <Caixa p={[-0.78 * lado, 0.06, 1.43]} t={[1.06, 0.12, 0.4]} cor="#b8b19e" />
    </group>
  );
};

const Quintal: React.FC = () => (
  <group position={[1.8, 0, -7.8]}>
    <Caixa p={[0, 0.02, 0]} t={[0.86, 0.08, 1.5]} cor="#72984c" sombra={false} />
    <Caixa p={[0, 0.34, 0.84]} t={[0.86, 0.68, 0.16]} cor="#e1c88d" />
    <Caixa p={[0, 0.72, 0.84]} t={[1, 0.08, 0.24]} cor={C.branco} />
    {[-0.45, 0.45].map((x) => <Caixa key={x} p={[x, 0.44, 0.84]} t={[0.16, 0.88, 0.24]} cor="#e1c88d" />)}
    <Haste a={[0, 0.06, -0.15]} b={[0, 0.7, -0.15]} r={0.06} cor={C.tronco} />
    <Copa p={[0, 0.88, -0.15]} r={0.3} cor="#509759" />
  </group>
);

const Arvore: React.FC<{ p: V3; verde?: string }> = ({ p, verde = '#55a168' }) => (
  <group position={p}>
    <Caixa p={[0, 0.08, 0]} t={[0.68, 0.16, 0.68]} cor="#8c9788" />
    <Caixa p={[0, 0.2, 0]} t={[0.52, 0.08, 0.52]} cor="#7eaa5c" />
    <Haste a={[0, 0.24, 0]} b={[0, 1.32, 0]} r={0.09} cor={C.tronco} />
    <Copa p={[0, 1.53, 0]} r={0.48} cor={verde} />
    <Copa p={[-0.24, 1.37, 0.06]} r={0.3} cor={verde} />
    <Copa p={[0.25, 1.4, -0.06]} r={0.3} cor={verde} />
  </group>
);

const Poste: React.FC<{ p: V3; lado: 1 | -1 }> = ({ p, lado }) => (
  <group position={p}>
    <mesh position={[0, 0.12, 0]} material={mat(C.metal)} castShadow receiveShadow>
      <cylinderGeometry args={[0.19, 0.23, 0.24, 16]} />
    </mesh>
    <Haste a={[0, 0.24, 0]} b={[0, 2.95, 0]} r={0.11} cor={C.metal} />
    <Haste a={[0, 2.89, 0]} b={[lado * 0.48, 3.03, 0]} r={0.08} cor={C.metal} />
    <Caixa p={[lado * 0.59, 3.02, 0]} t={[0.46, 0.18, 0.28]} cor={C.metal} />
    <Caixa p={[lado * 0.59, 2.87, 0]} t={[0.32, 0.08, 0.2]} cor={C.branco} />
  </group>
);

const Banco: React.FC = () => (
  <group position={[-2.18, 0, 0.9]}>
    <Caixa p={[0, 0.45, 0]} t={[1.14, 0.12, 0.44]} cor="#b68350" />
    <Caixa p={[0, 0.78, -0.22]} t={[1.14, 0.4, 0.12]} cor="#b68350" />
    {[-0.43, 0.43].map((x) => (
      <group key={x}>
        <Caixa p={[x, 0.2, 0]} t={[0.14, 0.4, 0.38]} cor={C.metal} />
        <Caixa p={[x, 0.65, -0.24]} t={[0.1, 0.58, 0.1]} cor={C.metal} />
      </group>
    ))}
  </group>
);

const Lixeira: React.FC = () => (
  <group position={[2.2, 0, 1.1]}>
    <mesh position={[0, 0.32, 0]} material={mat('#3c897f')} castShadow receiveShadow>
      <cylinderGeometry args={[0.23, 0.2, 0.64, 20]} />
    </mesh>
    <mesh position={[0, 0.68, 0]} material={mat(C.metal)} castShadow receiveShadow>
      <cylinderGeometry args={[0.26, 0.26, 0.08, 20]} />
    </mesh>
    <Caixa p={[0, 0.7, 0.17]} t={[0.26, 0.12, 0.08]} cor="#263f49" sombra={false} />
  </group>
);

export const Rua: React.FC = () => (
  <group>
    <Chao />
    {/* Fachadas na mesma profundidade, paleta viva e vãos entre lotes. */}
    <Casa x={-6.8} cor="#ab78bc" porta="#684481" altura={2.25} telhado="laje" espelhada />
    <Casa x={-3.4} cor="#e5a059" porta="#99492f" altura={2.45} telhado="duasAguas" />
    <Casa x={0} cor="#4ca5b3" porta="#285769" altura={2.15} telhado="laje" espelhada />
    <Casa x={3.6} cor="#df8578" porta="#854738" altura={2.4} telhado="duasAguas" />
    <Casa x={7} cor="#729ee0" porta="#3c568a" altura={2.2} telhado="laje" />
    <Quintal />
    <Arvore p={[-2.95, 0, -0.75]} />
    <Arvore p={[2.8, 0, -0.75]} verde="#47976b" />
    <Poste p={[-3.7, 0, -6.4]} lado={1} />
    <Poste p={[3.7, 0, -6.4]} lado={-1} />
    {/* Mobiliário fora do corredor dos personagens. */}
    <Banco />
    <Lixeira />
  </group>
);
