// Cenário: entrada da escola de manhã. Muro amarelo de ponta a ponta, portão de grade cinza aberto para dentro,
// placa "ESCOLA" no pórtico, guarita pequena e calçada na frente. Metros, Y para cima, chão em y = 0.
// Composição pelo palco fixo da vitrine: o pórtico fica à esquerda (x ≈ -4,3) e a guarita à direita (x ≈ 3,9),
// fora das faixas que os personagens tapam. Pelo vão do portão se vê o caminho até a porta do prédio.
import React from 'react';
import type { LimitesCenario } from '../tipos';
import { Caixa, Caixas, Ceu, Haste, PlanoFoco, Sol, mat, type V3 } from './base';
import { Palavra } from './letras';

const C = {
  base: '#b3aa9a', placa: '#ddd6c8', placa2: '#d2cab9', tapete: '#c9734f', tapete2: '#b8653f', meioFio: '#eeeae1', asfalto: '#555b63',
  muro: '#f2c531', barrado: '#d99a22', capa: '#f6f2e9', azul: '#2459a8', branco: '#f6f2e9', concreto: '#9c968c',
  grade: '#aeb8c6', grade2: '#8995a5', vidro: '#a9d3ec',
  grama: '#8cc063', caminho: '#d98b5f', soleira: '#a8a49b',
  predio: '#f3e5c8', platibanda: '#d2643c', janela: '#3d6ea8', porta: '#2f6e7a',
  folha: '#4f9a52', folha2: '#63ad5a', tronco: '#6b4a2f', arbusto: '#4e9447',
};

export const LIMITES_PORTAO: LimitesCenario = { limiteX: 1.5, limiteZ: [-4.2, 2.8], ceu: '#f2dcc0' };

const ZM = -5; // face da frente do muro
const EM = 0.25; // espessura do muro
const HM = 2.2; // altura do muro
const PX = -4.3; // centro do portão
const VAO = 1.4; // meio vão do portão (abertura de 2,8 m)
const PIL = 0.5; // lado do pilar
const XE = PX - VAO - PIL, XD = PX + VAO + PIL; // pontas de fora dos pilares
const GX = 3.9; // centro da guarita

/** Calçada: placas grandes em dois tons quase iguais (juntas de 8 cm), e um "tapete" de tijolinho terracota
 *  na frente do portão, que puxa o olho para a entrada. Meio-fio e rua lá na frente, fora do quadro da vitrine. */
const Calcada: React.FC = () => {
  const passo = 1.6, folga = 0.08, z0 = ZM, z1 = 3.0;
  const linhas = Math.round((z1 - z0) / passo), pz = (z1 - z0) / linhas;
  const a: { p: V3; t: V3 }[] = [], b: { p: V3; t: V3 }[] = [];
  for (let i = -12; i < 12; i++) for (let j = 0; j < linhas; j++) {
    const x = (i + 0.5) * passo, z = z0 + (j + 0.5) * pz;
    if (z < 1.6 && Math.abs(x - PX) < VAO + 0.9) continue; // lugar do tapete
    const it = { p: [x, -0.015, z] as V3, t: [passo - folga, 0.03, pz - folga] as V3 };
    ((i + j) % 2 === 0 ? a : b).push(it);
  }
  // tapete: faixas de tijolinho alternadas, do portão até a frente do quadro (puxa o olho para a entrada)
  const t1: { p: V3; t: V3 }[] = [], t2: { p: V3; t: V3 }[] = [];
  const tz0 = ZM, tz1 = 1.6, nt = 14, ptz = (tz1 - tz0) / nt;
  for (let j = 0; j < nt; j++) (j % 2 ? t1 : t2).push({ p: [PX, -0.01, tz0 + (j + 0.5) * ptz], t: [2 * VAO + 1.7, 0.04, ptz] });
  return (
    <group>
      <Caixa p={[0, -0.08, 0]} t={[90, 0.1, 90]} cor={C.base} sombra={false} />
      <Caixas itens={a} cor={C.placa} sombra={false} />
      <Caixas itens={b} cor={C.placa2} sombra={false} />
      <Caixas itens={t1} cor={C.tapete} sombra={false} />
      <Caixas itens={t2} cor={C.tapete2} sombra={false} />
      {/* meio-fio e rua (fora da vitrine, mas existem para outros planos) */}
      <Caixa p={[0, -0.01, 3.13]} t={[90, 0.05, 0.26]} cor={C.meioFio} sombra={false} />
      <Caixa p={[0, -0.17, 9]} t={[90, 0.1, 11.5]} cor={C.asfalto} sombra={false} />
    </group>
  );
};

/** Trecho de muro amarelo com barrado ocre e capa branca. */
const Muro: React.FC<{ x0: number; x1: number }> = ({ x0, x1 }) => {
  const w = x1 - x0, cx = (x0 + x1) / 2, zc = ZM - EM / 2;
  return (
    <group>
      <Caixa p={[cx, 0.2, zc]} t={[w, 0.4, EM]} cor={C.barrado} />
      <Caixa p={[cx, (0.4 + HM) / 2, zc]} t={[w, HM - 0.4, EM]} cor={C.muro} />
      <Caixa p={[cx, HM + 0.06, zc]} t={[w, 0.12, EM + 0.1]} cor={C.capa} />
    </group>
  );
};

/** Folha do portão: quadro + grade vertical. Origem na dobradiça, a folha corre para +x (lado = 1) ou -x (lado = -1)
 *  e gira `abre` radianos para dentro do pátio. */
const Folha: React.FC<{ lado: 1 | -1; abre: number }> = ({ lado, abre }) => {
  const w = VAO - 0.05, h = 1.95, y0 = 0.08, barra = 0.08;
  const n = 6, barras: { p: V3; t: V3 }[] = [];
  for (let i = 1; i <= n; i++) barras.push({ p: [lado * (i * w) / (n + 1), y0 + h / 2, 0], t: [barra, h - 0.1, barra] });
  return (
    <group position={[PX - lado * VAO, 0, ZM - 0.15]} rotation={[0, lado * abre, 0]}>
      <Caixa p={[lado * w / 2, y0 + h - 0.06, 0]} t={[w, 0.12, 0.1]} cor={C.grade2} />
      <Caixa p={[lado * w / 2, y0 + 0.06, 0]} t={[w, 0.12, 0.1]} cor={C.grade2} />
      <Caixa p={[lado * w / 2, y0 + h * 0.55, 0]} t={[w, 0.1, 0.1]} cor={C.grade2} />
      <Caixa p={[lado * 0.05, y0 + h / 2, 0]} t={[0.1, h, 0.1]} cor={C.grade2} />
      <Caixa p={[lado * (w - 0.05), y0 + h / 2, 0]} t={[0.1, h, 0.1]} cor={C.grade2} />
      <Caixas itens={barras} cor={C.grade} />
      {/* ponteiras no topo das barras */}
      <Caixas itens={barras.map((b) => ({ p: [b.p[0], y0 + h + 0.06, 0] as V3, t: [0.1, 0.12, 0.1] as V3 }))} cor={C.grade} />
      {/* dobradiças */}
      {[0.4, 1.6].map((y) => <Caixa key={y} p={[0, y, 0]} t={[0.1, 0.14, 0.14]} cor={C.grade2} />)}
    </group>
  );
};

/** Pórtico: dois pilares azuis, placa "ESCOLA" entre eles e o portão aberto. */
const Portico: React.FC = () => {
  const yP0 = 2.55, yP1 = 3.25, zP = ZM - 0.04; // placa
  return (
    <group>
      {[-1, 1].map((s) => (
        <group key={s}>
          <Caixa p={[PX + s * (VAO + PIL / 2), 1.7, ZM - 0.1]} t={[PIL, 3.4, PIL]} cor={C.azul} />
          <Caixa p={[PX + s * (VAO + PIL / 2), 3.46, ZM - 0.1]} t={[0.62, 0.12, 0.62]} cor={C.capa} />
        </group>
      ))}
      {/* placa da escola: fundo azul, moldura branca e letras brancas */}
      <Caixa p={[PX, (yP0 + yP1) / 2, zP - 0.06]} t={[2 * VAO, yP1 - yP0, 0.12]} cor={C.azul} />
      <Caixa p={[PX, yP1 - 0.07, zP + 0.02]} t={[2 * VAO - 0.2, 0.08, 0.04]} cor={C.branco} sombra={false} />
      <Caixa p={[PX, yP0 + 0.07, zP + 0.02]} t={[2 * VAO - 0.2, 0.08, 0.04]} cor={C.branco} sombra={false} />
      <Palavra txt="ESCOLA" p={[PX, yP0 + 0.17, zP + 0.04]} l={0.28} a={0.36} e={0.085} esp={0.14} cor={C.branco} />
      <Folha lado={1} abre={(70 * Math.PI) / 180} />
      <Folha lado={-1} abre={(32 * Math.PI) / 180} />
      {/* soleira do portão */}
      <Caixa p={[PX, -0.01, ZM - EM / 2]} t={[2 * VAO, 0.04, EM + 0.1]} cor={C.soleira} sombra={false} />
    </group>
  );
};

/** Guarita pequena, de pé na calçada, um passo à frente do muro: base de concreto, paredes brancas,
 *  janela com balcão azul, laje azul de beiral curto e plaquinha amarela. */
const Guarita: React.FC = () => {
  const w = 1.5, d = 1.3, h = 2.35, zf = ZM + 0.95, zc = zf - d / 2;
  return (
    <group position={[GX, 0, 0]}>
      <Caixa p={[0, 0.1, zc]} t={[w + 0.08, 0.2, d + 0.08]} cor={C.concreto} />
      <Caixa p={[0, (0.2 + h) / 2, zc]} t={[w, h - 0.2, d]} cor={C.branco} />
      <Caixa p={[0, 0.45, zc]} t={[w + 0.02, 0.18, d + 0.02]} cor={C.azul} />
      <Caixa p={[0, h + 0.07, zc]} t={[w + 0.16, 0.14, d + 0.16]} cor={C.azul} />
      {/* janela da frente: moldura, vidro e travessa */}
      <Caixa p={[0, 1.45, zf + 0.01]} t={[1.1, 0.8, 0.04]} cor={C.azul} />
      <Caixa p={[0, 1.45, zf + 0.04]} t={[0.94, 0.64, 0.04]} cor={C.vidro} sombra={false} />
      <Caixa p={[0, 1.45, zf + 0.07]} t={[0.08, 0.64, 0.03]} cor={C.branco} sombra={false} />
      {/* balcão: prateleira azul grossa com duas mãos-francesas */}
      <Caixa p={[0, 1.0, zf + 0.15]} t={[1.2, 0.1, 0.3]} cor={C.azul} />
      {[-0.45, 0.45].map((x) => <Caixa key={x} p={[x, 0.88, zf + 0.08]} t={[0.08, 0.16, 0.16]} cor={C.azul} />)}
      {/* plaquinha "portaria" (rabisco) sobre a janela */}
      <Caixa p={[0, 2.06, zf + 0.03]} t={[0.8, 0.22, 0.05]} cor="#f2c531" />
      <Caixa p={[0, 2.06, zf + 0.07]} t={[0.5, 0.08, 0.03]} cor={C.azul} sombra={false} />
      {/* janelinha do lado (aparece de lado na câmera) */}
      <Caixa p={[-w / 2 - 0.01, 1.5, zc + 0.1]} t={[0.04, 0.5, 0.6]} cor={C.vidro} sombra={false} />
    </group>
  );
};

/** Prédio da escola, lá dentro: dois andares, platibanda terracota, janelas azuis e porta dupla com marquise.
 *  A porta fica em x = -9, na linha de visão que passa pelo vão do portão. */
const XPORTA = -9;
const Predio: React.FC = () => {
  const zf = -16, w = 20, x0 = -14.5, h = 4.8, cx = x0 + w / 2, zc = zf - 1.5;
  const molduras: { p: V3; t: V3 }[] = [], vidros: { p: V3; t: V3 }[] = [];
  for (const y of [1.4, 3.5]) for (let x = x0 + 1.6; x < x0 + w - 1; x += 2.4) {
    if (y < 2 && Math.abs(x - XPORTA) < 1.6) continue; // lugar da porta
    molduras.push({ p: [x, y, zf + 0.03], t: [1.5, 1.2, 0.06] });
    vidros.push({ p: [x, y, zf + 0.07], t: [1.3, 1.0, 0.04] });
  }
  return (
    <group>
      <Caixa p={[cx, h / 2, zc]} t={[w, h, 3]} cor={C.predio} />
      <Caixa p={[cx, h + 0.25, zc]} t={[w + 0.3, 0.5, 3.3]} cor={C.platibanda} />
      <Caixa p={[cx, 2.45, zf + 0.05]} t={[w, 0.16, 0.1]} cor={C.platibanda} />
      <Caixas itens={molduras} cor={C.branco} />
      <Caixas itens={vidros} cor={C.janela} sombra={false} />
      {/* porta dupla, marquise e degraus */}
      <Caixa p={[XPORTA, 1.1, zf + 0.04]} t={[1.9, 2.2, 0.08]} cor={C.branco} />
      <Caixa p={[XPORTA - 0.42, 1.05, zf + 0.09]} t={[0.76, 2.0, 0.06]} cor={C.porta} />
      <Caixa p={[XPORTA + 0.42, 1.05, zf + 0.09]} t={[0.76, 2.0, 0.06]} cor={C.porta} />
      <Caixa p={[XPORTA, 2.3, zf + 0.6]} t={[2.6, 0.12, 1.2]} cor={C.platibanda} />
      <Caixa p={[XPORTA, 0.08, zf + 0.5]} t={[3.0, 0.16, 1.0]} cor={C.soleira} />
    </group>
  );
};

/** Pátio de dentro: grama e caminho terracota do portão até a porta (em diagonal). */
const Patio: React.FC = () => {
  const ax = PX, az = ZM - 0.3, bx = XPORTA, bz = -15.0;
  const comp = Math.hypot(bx - ax, bz - az), ang = Math.atan2(ax - bx, az - bz);
  return (
    <group>
      <Caixa p={[0, -0.03, -14]} t={[60, 0.06, 18]} cor={C.grama} sombra={false} />
      <group position={[(ax + bx) / 2, 0, (az + bz) / 2]} rotation={[0, ang, 0]}>
        <Caixa p={[0, 0.0, 0]} t={[2.4, 0.04, comp]} cor={C.caminho} sombra={false} />
        {[-1, 1].map((s) => <Caixa key={s} p={[s * 1.3, 0.02, 0]} t={[0.2, 0.08, comp]} cor={C.soleira} sombra={false} />)}
      </group>
    </group>
  );
};

const Arvore: React.FC<{ p: V3; e?: number }> = ({ p, e = 1 }) => (
  <group position={p} scale={e}>
    <Haste a={[0, 0, 0]} b={[0, 2.6, 0]} r={0.17} cor={C.tronco} />
    <mesh position={[0, 3.5, 0]} material={mat(C.folha, { flat: true })} castShadow receiveShadow><icosahedronGeometry args={[1.45, 0]} /></mesh>
    <mesh position={[0.75, 3.0, 0.45]} material={mat(C.folha2, { flat: true })} castShadow receiveShadow><icosahedronGeometry args={[0.85, 0]} /></mesh>
  </group>
);

/** Canteiro junto ao muro: borda de concreto, grama e arbustos low poly. */
const Canteiro: React.FC<{ x0: number; x1: number }> = ({ x0, x1 }) => {
  const cx = (x0 + x1) / 2, w = x1 - x0, z = ZM + 0.3, n = Math.max(1, Math.floor(w / 1.5));
  return (
    <group>
      <Caixa p={[cx, 0.09, z]} t={[w, 0.18, 0.56]} cor={C.soleira} />
      <Caixa p={[cx, 0.16, z]} t={[w - 0.16, 0.08, 0.4]} cor={C.grama} sombra={false} />
      {Array.from({ length: n }, (_, i) => (
        <mesh key={i} position={[x0 + (i + 0.5) * (w / n), 0.42, z - 0.02]} scale={[1.15, 0.85, 0.8]} material={mat(i % 2 ? C.arbusto : C.folha2, { flat: true })} castShadow receiveShadow>
          <icosahedronGeometry args={[0.36, 0]} />
        </mesh>
      ))}
    </group>
  );
};

export const PortaoEscola: React.FC = () => (
  <group>
    <Ceu baixo="#ffd2a1" alto="#86bfe8" />
    {/* sol da manhã: quente, vindo da frente e da direita; as sombras caem para trás dos pés */}
    <Sol dir={[-0.45, -0.8, -0.75]} cor="#ffd9a6" forca={2.5} area={24} />
    <PlanoFoco z={-1} />
    <Calcada />
    <Patio />
    <Muro x0={-30} x1={XE} />
    <Muro x0={XD} x1={30} />
    <Portico />
    <Guarita />
    <Canteiro x0={-12} x1={XE - 0.3} />
    <Canteiro x0={XD + 0.3} x1={GX - 1.0} />
    <Canteiro x0={GX + 1.0} x1={12} />
    <Predio />
    <Arvore p={[1.2, 0, -10]} e={0.9} />
    <Arvore p={[7.2, 0, -11]} e={0.95} />
  </group>
);
