// HUD: contador fixo no canto superior esquerdo (1920x1080, margem 48 px). Rótulo pequeno espaçado + valor grande.
// Entra deslizando nos 10 primeiros quadros; números com largura fixa (tabular) para não "dançar" quando mudam.
import React from 'react';
import { AbsoluteFill, Easing, interpolate } from 'remotion';

const FONTE = "'Inter', 'Segoe UI', Arial, sans-serif";
const SOMBRA = '0 2px 6px rgba(0,0,0,0.35), 0 1px 1px rgba(0,0,0,0.35)';
const ACENTO = '#ffd23f';

const entrada = (q: number, de: number, ate: number) =>
  interpolate(q, [de, ate], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.out(Easing.cubic) });

export const HudContador: React.FC<{ quadro: number; rotulo: string; valor: string }> = ({ quadro, rotulo, valor }) => {
  const a = entrada(quadro, 0, 8), b = entrada(quadro, 2, 10);
  // "SORTE 1.048.576x" → palavra pequena + número grande
  const i = valor.indexOf(' ');
  const [palavra, numero] = i > 0 ? [valor.slice(0, i), valor.slice(i + 1)] : ['', valor];
  return (
    <AbsoluteFill style={{ pointerEvents: 'none', fontFamily: FONTE, color: '#ffffff' }}>
      {/* sombra difusa atrás do texto: legível em fundo claro, sem caixa dura */}
      <div style={{ position: 'absolute', left: -120, top: -140, width: 900, height: 460, opacity: b,
        background: 'radial-gradient(ellipse at 30% 50%, rgba(10,14,24,0.38) 0%, rgba(10,14,24,0.16) 40%, rgba(10,14,24,0) 70%)' }} />
      <div style={{ position: 'absolute', left: 48, top: 48, textShadow: SOMBRA }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 14, opacity: a, transform: `translateX(${(1 - a) * -32}px)` }}>
          <div style={{ width: 6, height: 26, borderRadius: 3, background: ACENTO, boxShadow: '0 1px 4px rgba(0,0,0,0.3)', transform: `scaleY(${a})` }} />
          <span style={{ fontSize: 26, fontWeight: 700, letterSpacing: '0.34em', textTransform: 'uppercase', opacity: 0.92 }}>{rotulo}</span>
        </div>
        <div style={{ display: 'flex', alignItems: 'baseline', gap: 14, marginTop: 4, opacity: b, transform: `translateX(${(1 - b) * -40}px)` }}>
          {palavra && <span style={{ fontSize: 34, fontWeight: 600, letterSpacing: '0.12em', opacity: 0.85 }}>{palavra}</span>}
          <span style={{ fontSize: 84, fontWeight: 800, letterSpacing: '-0.015em', lineHeight: 1, fontVariantNumeric: 'tabular-nums' }}>{numero}</span>
        </div>
      </div>
    </AbsoluteFill>
  );
};
