// Só na VitrineLote (padrão r12/r17): câmera do plano, sem desfoque, e as montagens "na mão do Téo".
// A vitrine não deixa o objeto mudar a pose do Téo dela: para a nota e o guarda-chuva, desenhamos aqui um Téo
// com a pose de segurar, 5 m à esquerda (o Téo parado da vitrine fica fora do quadro). Fora da vitrine, o componente puro.
import React, { useLayoutEffect } from 'react';
import * as THREE from 'three';
import { useThree } from '@react-three/fiber';
import { useVideoConfig } from 'remotion';
import { Boneco } from '../../../kit/Boneco';
import { ELENCO } from '../../../kit/elenco';
import { BASE, type Juntas } from '../../../kit/poses';
import { ikBraco } from '../r05-acao/acoes';
import { mat, type V3 } from './base';
import { NOTA, NotaCem } from './NotaCem';
import { GUARDA, GuardaChuva } from './GuardaChuva';
import { VolanteGigante } from './VolanteGigante';

const R = THREE.MathUtils.degToRad;

// ── cinemática do braço do kit (mesma cadeia do Boneco.tsx) ───────────────
/** Cotovelo e mão (centro da esfera) no espaço do boneco, com giro 0. lado 1 = braço em +X. */
export function bracoNoMundo(j: Juntas, lado: 1 | -1): { cotovelo: THREE.Vector3; mao: THREE.Vector3 } {
  const x = lado === 1 ? j.ombroDX : j.ombroEX, z = lado === 1 ? j.ombroDZ : j.ombroEZ, cot = lado === 1 ? j.cotoveloD : j.cotoveloE;
  const ombro = new THREE.Quaternion().setFromEuler(new THREE.Euler(R(-x), 0, R(z) * lado));
  const ante = new THREE.Quaternion().setFromEuler(new THREE.Euler(R(-cot), 0, 0));
  const tronco = new THREE.Quaternion().setFromEuler(new THREE.Euler(R(j.troncoX), R(j.troncoY), 0));
  const noTronco = (v: THREE.Vector3) => v.applyQuaternion(ombro).add(new THREE.Vector3(0.25 * lado, 1.06 - 0.66, 0)).applyQuaternion(tronco).add(new THREE.Vector3(0, 0.66 + j.altura, 0));
  const cotovelo = noTronco(new THREE.Vector3(0, -0.22, 0));
  const mao = noTronco(new THREE.Vector3(0, -0.25, 0).applyQuaternion(ante).add(new THREE.Vector3(0, -0.22, 0)));
  return { cotovelo, mao };
}
const bracoD = (alvo: V3) => { const b = ikBraco(1, alvo); return { ombroDX: b.x, ombroDZ: b.z, cotoveloD: b.cot }; };

// ── nota: mão logo abaixo do queixo, nota em pé virada para a câmera, presa pela ponta entre os "dedos"
// (a esfera da mão, atrás) e o polegar (na frente) ──
export const POSE_NOTA: Juntas = { ...BASE, cabecaX: 4, ...bracoD([0.2, 1.06, 0.38]) };
export const NOTA_GIRO = 8; // graus: a nota sobe um pouco para dentro do corpo
/** Nota na mão do boneco (espaço do boneco): a ponta direita (de quem olha) fica sobre a mão, presa pelo polegar. */
export const NotaNaMao: React.FC<{ j?: Juntas; comPolegar?: boolean }> = ({ j = POSE_NOTA, comPolegar = true }) => {
  const { mao } = bracoNoMundo(j, 1);
  const pega = [NOTA.larg / 2 - 0.02, 0.022]; // ponto da nota que fica sobre o centro da mão (na faixa lateral)
  return (
    <group position={mao.toArray()} rotation={[0, 0, R(NOTA_GIRO)]}>
      {/* a folha encosta na frente da esfera da mão (raio 7,2 cm) */}
      <group position={[-pega[0], -pega[1], 0.07]}><NotaCem /></group>
      {/* polegar por cima da faixa lateral, de pé: prende a nota contra a mão */}
      {comPolegar && (
        <mesh position={[0.002, 0.004, 0.088]} rotation={[0, 0, R(-12)]} scale={[1, 1, 0.7]} material={mat(ELENCO.teo.pele, 0.82)} castShadow>
          <capsuleGeometry args={[0.019, 0.036, 8, 16]} />
        </mesh>
      )}
    </group>
  );
};

// ── guarda-chuva: cotovelo aberto ~30° e dobrado para a frente; o braço desce por fora da peça e a aperta contra a
// costela (o meio do pano encosta na lateral do tronco). A mão fecha no cabo reto à frente do peito, e o gancho fica
// na frente dela, virado para baixo. A ponta vai para trás e para baixo (~20°). ──
export const GUARDA_MAO: V3 = [0.32, 0.98, 0.22]; // centro da mão (espaço do tronco)
export const POSE_GUARDA: Juntas ={ ...BASE, ...bracoD(GUARDA_MAO), ombroEX: -12, ombroEZ: 8, cabecaY: 18, cabecaX: 6 }; // braço E para trás: some atrás do corpo
/** Eixo do guarda-chuva (espaço do boneco): passa pelo centro da mão e pelo vão entre o fim do braço e a costela. */
export function eixoGuarda(j: Juntas = POSE_GUARDA) {
  const { cotovelo, mao } = bracoNoMundo(j, 1);
  const ombro = new THREE.Vector3(0.25, 1.06 + j.altura, 0);
  // aperto: 80% do braço, por dentro dele (raio do braço 6,2 cm + pano 4 cm − 1 cm de pressão)
  const aperto = ombro.clone().lerp(cotovelo, 0.8).add(new THREE.Vector3(-0.092, -0.035, 0));
  const u = mao.clone().sub(aperto).normalize(); // ponta → gancho
  return { mao, cotovelo, aperto, u, ponta: mao.clone().sub(u.clone().multiplyScalar(GUARDA.pega)) };
}
export const GuardaSobBraco: React.FC<{ j?: Juntas }> = ({ j = POSE_GUARDA }) => {
  const { mao, u, ponta } = eixoGuarda(j);
  const cima = new THREE.Vector3(0, 1, 0);
  const x = cima.clone().sub(u.clone().multiplyScalar(cima.dot(u))).normalize(); // gancho (−X local) para baixo
  const zz = new THREE.Vector3().crossVectors(x, u);
  const q = new THREE.Quaternion().setFromRotationMatrix(new THREE.Matrix4().makeBasis(x, u, zz));
  return (
    <>
      <group position={ponta.toArray()} quaternion={q}><GuardaChuva /></group>
      {/* mão fechada: o cabo atravessa o punho (a esfera da mão); o polegar deita por cima, ao longo do cabo
          (local +X = para cima, +Y = para o gancho) */}
      <group position={mao.toArray()} quaternion={q}>
        <mesh position={[0.058, 0.03, 0]} rotation={[0, 0, R(-10)]} material={mat(ELENCO.teo.pele, 0.82)} castShadow>
          <capsuleGeometry args={[0.022, 0.05, 8, 16]} />
        </mesh>
      </group>
    </>
  );
};

// ── câmera ─────────────────────────────────────────────────────────────────
/** alvo: centro do quadro (mundo); altura: altura do quadro no alvo (m); dist; elev/azim em graus (+azim = câmera para +X). */
type Plano = { alvo: V3; altura: number; dist: number; elev: number; azim: number };

const AjustarCamera: React.FC<{ p: Plano }> = ({ p }) => {
  const camera = useThree((s) => s.camera) as THREE.PerspectiveCamera;
  // roda depois da <Camera> do palco (vem antes na árvore), a cada quadro, sem loop próprio
  useLayoutEffect(() => {
    const e = R(p.elev), a = R(p.azim), h = p.dist * Math.cos(e);
    camera.position.set(p.alvo[0] + h * Math.sin(a), p.alvo[1] + p.dist * Math.sin(e), p.alvo[2] + h * Math.cos(a));
    camera.lookAt(...p.alvo);
    camera.fov = 2 * THREE.MathUtils.radToDeg(Math.atan(p.altura / 2 / p.dist));
    camera.updateProjectionMatrix();
    camera.updateMatrixWorld();
  });
  return null;
};

// Sem desfoque (r17): plano invisível a 2,1 m da câmera (o foco da vitrine) entra só no passe de profundidade do bokeh.
const geoFoco = new THREE.PlaneGeometry(80, 80);
const matFoco = new THREE.MeshBasicMaterial({ colorWrite: false, depthWrite: false });
const SemDesfoque: React.FC = () => {
  const camera = useThree((s) => s.camera);
  const ref = React.useRef<THREE.Mesh>(null);
  useLayoutEffect(() => {
    const m = ref.current; if (!m) return;
    m.quaternion.copy(camera.quaternion);
    m.position.copy(camera.position).add(new THREE.Vector3(0, 0, -2.1).applyQuaternion(camera.quaternion));
    m.updateMatrixWorld();
  });
  return <mesh ref={ref} geometry={geoFoco} material={matFoco} frustumCulled={false} />;
};

// ── montagens da vitrine (coordenadas do mundo) ───────────────────────────
const TEO_X = -5; // Téo que segura: longe do Téo parado da vitrine (x = 0)
const MONTAGENS = {
  notaCem: {
    plano: { alvo: [TEO_X + 0.05, 1.27, 0.25], altura: 0.72, dist: 2.6, elev: 4, azim: 8 },
    Cena: () => (
      <group position={[TEO_X, 0, 0]}>
        <Boneco v={ELENCO.teo} j={POSE_NOTA} e={{ boca: 'sorriso', olharX: 0.1 }} />
        <NotaNaMao />
      </group>
    ),
  },
  guardaChuva: {
    // perto da cintura e do braço, de 3/4 pelo lado do braço: queixo e sorriso no alto, a ponta no canto
    plano: { alvo: [TEO_X + 0.2, 0.98, -0.06], altura: 1.05, dist: 2.8, elev: 18, azim: 80 },
    Cena: () => (
      <group position={[TEO_X, 0, 0]}>
        <Boneco v={ELENCO.teo} j={POSE_GUARDA} e={{ boca: 'sorriso' }} />
        <GuardaSobBraco />
      </group>
    ),
  },
  // painel atrás e à direita do Téo da vitrine (ele fica "ao pé", à esquerda); câmera baixa e longe
  volanteGigante: {
    plano: { alvo: [1.75, 3.55, -1.4], altura: 8.3, dist: 13, elev: -10, azim: 4 },
    Cena: () => <group position={[2.35, 0.01, -1.5]}><VolanteGigante /></group>,
  },
} satisfies Record<string, { plano: Plano; Cena: React.FC }>;

export function apresentar(Componente: React.FC, nome: keyof typeof MONTAGENS): React.FC {
  return function PecaNaVitrine() {
    const { id } = useVideoConfig();
    if (id !== 'VitrineLote') return <Componente />;
    const { plano, Cena } = MONTAGENS[nome];
    return (
      <>
        <AjustarCamera p={plano} />
        {/* a vitrine põe o objeto em x = 0,75: desfaz para montar no mundo */}
        <group position={[-0.75, 0, 0]}><Cena /></group>
        <SemDesfoque />
      </>
    );
  };
}
