// Luz padrão do canal: céu (hemisfério) + sol com sombra suave.
import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

export const Luz: React.FC<{ ceu?: string; dir?: [number, number, number]; forca?: number }> = ({ ceu = '#9fd3ee', dir = [-0.5, -1, -0.6], forca = 2.4 }) => {
  const sol = useRef<THREE.DirectionalLight>(null);
  const p = new THREE.Vector3(...dir).normalize().multiplyScalar(-30);
  useEffect(() => {
    const s = sol.current; if (!s) return;
    Object.assign(s.shadow.camera, { left: -20, right: 20, top: 20, bottom: -20, near: 1, far: 80 });
    s.shadow.camera.updateProjectionMatrix();
  }, []);
  return (
    <>
      <hemisphereLight args={[ceu, '#9a8f7a', 1.6]} />
      <directionalLight ref={sol} color="#fff6e8" intensity={forca} position={p} castShadow
        shadow-mapSize={[4096, 4096]} shadow-radius={6} shadow-bias={-0.0004} />
    </>
  );
};
