import React from 'react';
import { Caixa, mat, type V3 } from './base';

const C = {
  papelao: '#a65e31', lateral: '#894724', borda: '#d39a5c',
  interior: '#613a24', tampa: '#bf8147', etiqueta: '#eee1bf',
};
const PAPEIS = ['#ffffff', '#f5ecd9', '#e1d8c5'];

const PapelDobrado: React.FC<{ indice: number }> = ({ indice }) => (
  <group>
    {/* A crista sobe; as duas abas descem em direções opostas. */}
    {([-1, 1] as const).map((lado) => (
      <group key={lado} rotation={[lado * 0.62, 0, 0]}>
        <Caixa p={[0, 0, lado * 0.011]} t={[0.047, 0.0016, 0.022]}
          cor={PAPEIS[(indice + (lado === 1 ? 1 : 0)) % PAPEIS.length]} />
      </group>
    ))}
    <mesh rotation={[0, 0, Math.PI / 2]} material={mat(PAPEIS[indice % PAPEIS.length])} castShadow receiveShadow>
      <cylinderGeometry args={[0.0008, 0.0008, 0.047, 8]} />
    </mesh>
  </group>
);

// Posições e giros fixos: a camada visível não forma fileiras.
const TOPO: { p: V3; r: V3 }[] = [
  { p: [-0.111, 0.127, 0.058], r: [0.12, 0.25, -0.20] },
  { p: [-0.049, 0.133, 0.063], r: [-0.26, -0.48, 0.17] },
  { p: [0.017, 0.124, 0.065], r: [0.28, 0.10, -0.32] },
  { p: [0.092, 0.135, 0.057], r: [-0.10, 0.68, 0.24] },
  { p: [-0.102, 0.137, 0.007], r: [-0.25, -0.68, 0.31] },
  { p: [-0.030, 0.145, 0.008], r: [0.33, 0.42, -0.24] },
  { p: [0.043, 0.139, 0.013], r: [-0.18, -0.37, 0.18] },
  { p: [0.110, 0.125, -0.004], r: [0.24, 0.83, -0.27] },
  { p: [-0.112, 0.121, -0.059], r: [0.30, 0.15, -0.22] },
  { p: [-0.048, 0.135, -0.055], r: [-0.24, 0.82, 0.19] },
  { p: [0.025, 0.130, -0.052], r: [0.21, -0.52, -0.29] },
  { p: [0.101, 0.132, -0.059], r: [-0.27, 0.29, 0.28] },
  { p: [-0.065, 0.151, 0.034], r: [-0.22, 1.13, -0.34] },
  { p: [0.007, 0.159, -0.018], r: [0.35, -0.75, 0.26] },
  { p: [0.075, 0.151, 0.037], r: [-0.31, 0.39, -0.25] },
];

// Corpo de 30 × 20 × 11,8 cm, com tampa removível apoiada atrás.
export const CaixaDeSapato: React.FC = () => (
  <group>
    <Caixa p={[0, 0.003, 0]} t={[0.30, 0.006, 0.20]} cor={C.interior} />
    <Caixa p={[0, 0.062, 0.0975]} t={[0.30, 0.112, 0.005]} cor={C.papelao} />
    <Caixa p={[0, 0.062, -0.0975]} t={[0.30, 0.112, 0.005]} cor={C.interior} />
    {([-1, 1] as const).map((lado) => (
      <group key={lado}>
        <Caixa p={[lado * 0.1475, 0.062, 0]} t={[0.005, 0.112, 0.19]} cor={C.lateral} />
        <Caixa p={[lado * 0.1475, 0.119, 0]} t={[0.005, 0.002, 0.20]} cor={C.borda} />
        <Caixa p={[0, 0.119, lado * 0.0975]} t={[0.29, 0.002, 0.005]} cor={C.borda} />
      </group>
    ))}
    {/* Etiqueta simples de embalagem, sem letras adicionais. */}
    <Caixa p={[-0.085, 0.044, 0.1006]} t={[0.061, 0.027, 0.0012]} cor={C.etiqueta} />
    <Caixa p={[-0.090, 0.049, 0.1015]} t={[0.035, 0.004, 0.0006]} cor={C.lateral} />
    <Caixa p={[-0.098, 0.039, 0.1015]} t={[0.019, 0.004, 0.0006]} cor={C.lateral} />

    {/* Tampa sem dobradiça: bandeja rasa inclinada, com saia nos quatro lados. */}
    <group position={[0, 0.003 * Math.cos(0.65) + 0.107 * Math.sin(0.65), -0.198]} rotation={[0.65, 0, 0]}>
      <Caixa p={[0, 0, 0]} t={[0.312, 0.006, 0.214]} cor={C.tampa} />
      {([-1, 1] as const).map((lado) => (
        <group key={lado}>
          <Caixa p={[lado * 0.153, 0.012, 0]} t={[0.006, 0.018, 0.214]} cor={C.borda} />
          <Caixa p={[0, 0.012, lado * 0.104]} t={[0.30, 0.018, 0.006]} cor={C.borda} />
        </group>
      ))}
    </group>

    {/* Camadas internas sustentam os bilhetes que passam da borda. */}
    {[0, 1, 2].flatMap((camada) => Array.from({ length: 12 }, (_, i) => (
      <group key={camada + '-' + i}
        position={[(i % 4 - 1.5) * 0.064, 0.042 + camada * 0.027 + (i % 3) * 0.003, (Math.floor(i / 4) - 1) * 0.056]}
        rotation={[0.13 * (i % 3 - 1), 0.34 * ((i + camada) % 4 - 1.5), 0.16 * (i % 3 - 1)]}>
        <PapelDobrado indice={i + camada} />
      </group>
    )))}
    {TOPO.map(({ p, r }, i) => (
      <group key={i} position={p} rotation={r}><PapelDobrado indice={i} /></group>
    ))}
  </group>
);
