// Cenário: banheiro pequeno de azulejo branco, de dia. Medidas em metros, Y para cima, chão em y = 0.
// Parede do fundo (-Z): pia com gabinete e espelho redondo à esquerda, janela quadrada no alto do centro
// (acima das cabeças), vaso sanitário à direita e box de vidro no canto direito.
// Os bonecos da vitrine (x = ±0,7, z = 0,5) tapam o fundo até ~1,5 m entre |x| ≈ 0,4 e 1,9: nada importante fica ali.
import React from 'react';
import type { LimitesCenario } from '../tipos';
import { Caixa, Caixas, Cilindro, Haste, LuzInterior, PlanoFoco, mat, vidro, type V3 } from './base';

const C = {
  azulejo: '#f8fbfc', rejunte: '#cdd9de', pintura: '#e6f2f5', faixa: '#6fc3c4', teto: '#f7fafa',
  piso: '#d9dfe1', piso2: '#e6eaeb',
  louca: '#fbfdfd', loucaSombra: '#dfe7ea', metal: '#b7c3ca', metalEscuro: '#7f8d96',
  gabinete: '#e3b57e', gabinete2: '#cf9d63', tampo: '#f3f5f5',
  espelho: '#cfe7f0', moldura: '#6fc3c4', batente: '#ffffff', vidroJanela: '#d8f0fa',
  toalha: '#f07a63', tapete: '#6fc3c4', sabonete: '#f2a7c3', copo: '#f2c544', folha: '#4f9a52', vaso: '#c8693f',
};

const X = 3.4; // meia largura (paredes em x = ±3,4)
const ZF = -2.4; // face da parede do fundo
const ZT = 7; // as paredes vão até atrás da câmera
const H = 3.0; // pé-direito
const Y_AZ = 2.2; // altura do azulejo
const L = ZT - ZF, ZC = (ZF + ZT) / 2;
const JAN = { x0: -0.45, x1: 0.45, y0: 1.72, y1: 2.62 }; // vão da janela (0,9 × 0,9 m)

export const LIMITES_BANHEIRO: LimitesCenario = { limiteX: 1.5, limiteZ: [-1.0, 3.0], ceu: '#a9dcf2' };

/** Azulejos grandes (≈ 0,57 × 0,55 m) com rejunte de 8 cm: o rejunte é a parede, o azulejo fica 3 cm à frente. */
const azulejosFundo = (): { p: V3; t: V3 }[] => {
  const n = 12, w = (2 * X) / n, h = Y_AZ / 4, itens: { p: V3; t: V3 }[] = [];
  for (let i = 0; i < n; i++) for (let j = 0; j < 4; j++) {
    const x = -X + w * (i + 0.5), y = h * (j + 0.5);
    if (x + w / 2 > JAN.x0 - 0.1 && x - w / 2 < JAN.x1 + 0.1 && y + h / 2 > JAN.y0 - 0.1) continue; // vão da janela
    itens.push({ p: [x, y, ZF + 0.03], t: [w - 0.08, h - 0.08, 0.02] });
  }
  return itens;
};
const azulejosLado = (): { p: V3; t: V3 }[] => {
  const w = 0.6, h = Y_AZ / 4, itens: { p: V3; t: V3 }[] = [];
  for (const s of [-1, 1]) for (let i = 0; i * w < L; i++) for (let j = 0; j < 4; j++) {
    itens.push({ p: [s * (X - 0.03), h * (j + 0.5), ZF + w * (i + 0.5)], t: [0.02, h - 0.08, w - 0.08] });
  }
  return itens;
};
/** Piso claro em xadrez de baixo contraste (placas de 62 cm). */
const placasPiso = (): { p: V3; t: V3 }[] => {
  const n = 11, w = (2 * X) / n, itens: { p: V3; t: V3 }[] = [];
  for (let i = 0; i < n; i++) for (let k = 0; k * w < L; k++) {
    if ((i + k) % 2) continue;
    itens.push({ p: [-X + w * (i + 0.5), -0.01, ZF + w * (k + 0.5)], t: [w, 0.02, w] });
  }
  return itens;
};
const AZ_FUNDO = azulejosFundo(), AZ_LADO = azulejosLado(), PISO = placasPiso();

/** Paredes: a do fundo com o vão da janela; nenhuma projeta sombra (o sol do palco entra pelo "teto" e ilumina tudo). */
const Paredes: React.FC = () => {
  const e = 0.2, zc = ZF - e / 2, xm = (JAN.x0 + JAN.x1) / 2, wj = JAN.x1 - JAN.x0;
  const blocos: [number, number, number, number][] = [ // x0, x1, y0, y1 dos pedaços da parede do fundo
    [-X - e, JAN.x0, 0, H], [JAN.x1, X + e, 0, H], [JAN.x0, JAN.x1, 0, JAN.y0], [JAN.x0, JAN.x1, JAN.y1, H],
  ];
  return (
    <group>
      {blocos.map(([x0, x1, y0, y1], i) => {
        // rejunte até a altura do azulejo, pintura acima dela
        const yA = Math.min(y1, Y_AZ), yB = Math.max(y0, Y_AZ);
        return (
          <group key={i}>
            {yA > y0 && <Caixa p={[(x0 + x1) / 2, (y0 + yA) / 2, zc]} t={[x1 - x0, yA - y0, e]} cor={C.rejunte} sombra={false} />}
            {y1 > yB && <Caixa p={[(x0 + x1) / 2, (yB + y1) / 2, zc]} t={[x1 - x0, y1 - yB, e]} cor={C.pintura} sombra={false} />}
          </group>
        );
      })}
      {[-1, 1].map((s) => (
        <group key={s}>
          <Caixa p={[s * (X + e / 2), Y_AZ / 2, ZC]} t={[e, Y_AZ, L]} cor={C.rejunte} sombra={false} />
          <Caixa p={[s * (X + e / 2), (Y_AZ + H) / 2, ZC]} t={[e, H - Y_AZ, L]} cor={C.pintura} sombra={false} />
          {/* faixa verde-água no alto do azulejo */}
          <Caixa p={[s * (X - 0.04), Y_AZ + 0.05, ZC]} t={[0.08, 0.1, L]} cor={C.faixa} sombra={false} />
        </group>
      ))}
      <Caixas itens={AZ_FUNDO} cor={C.azulejo} />
      <Caixas itens={AZ_LADO} cor={C.azulejo} />
      {/* faixa do fundo, interrompida pela janela */}
      <Caixa p={[(-X + JAN.x0 - 0.1) / 2, Y_AZ + 0.05, ZF + 0.04]} t={[X + JAN.x0 - 0.1, 0.1, 0.08]} cor={C.faixa} sombra={false} />
      <Caixa p={[(X + JAN.x1 + 0.1) / 2, Y_AZ + 0.05, ZF + 0.04]} t={[X - JAN.x1 - 0.1, 0.1, 0.08]} cor={C.faixa} sombra={false} />
      {/* janela: batente branco largo, cruzeta, vidro claro e peitoril com um vasinho; lá fora, só o céu chapado */}
      <Caixa p={[xm, JAN.y1 + 0.05, ZF + 0.02]} t={[wj + 0.2, 0.1, 0.06]} cor={C.batente} sombra={false} />
      <Caixa p={[JAN.x0 - 0.05, (JAN.y0 + JAN.y1) / 2, ZF + 0.02]} t={[0.1, JAN.y1 - JAN.y0, 0.06]} cor={C.batente} sombra={false} />
      <Caixa p={[JAN.x1 + 0.05, (JAN.y0 + JAN.y1) / 2, ZF + 0.02]} t={[0.1, JAN.y1 - JAN.y0, 0.06]} cor={C.batente} sombra={false} />
      <Caixa p={[xm, (JAN.y0 + JAN.y1) / 2, ZF - 0.1]} t={[0.08, JAN.y1 - JAN.y0, 0.06]} cor={C.batente} sombra={false} />
      <Caixa p={[xm, (JAN.y0 + JAN.y1) / 2, ZF - 0.1]} t={[wj, 0.08, 0.06]} cor={C.batente} sombra={false} />
      <mesh position={[xm, (JAN.y0 + JAN.y1) / 2, ZF - 0.15]} material={vidro(C.vidroJanela, 0.12)}><boxGeometry args={[wj, JAN.y1 - JAN.y0, 0.01]} /></mesh>
      <Caixa p={[xm, JAN.y0 - 0.04, ZF + 0.02]} t={[wj + 0.3, 0.08, 0.24]} cor={C.batente} />
      <Cilindro p={[xm + 0.22, JAN.y0, ZF + 0.07]} r={0.07} r2={0.055} h={0.12} cor={C.vaso} />
      <mesh position={[xm + 0.22, JAN.y0 + 0.2, ZF + 0.07]} material={mat(C.folha, { flat: true })} castShadow><icosahedronGeometry args={[0.1, 1]} /></mesh>
    </group>
  );
};

/** Pia: gabinete de madeira clara de 0,85 m, cuba branca de apoio, torneira e espelho redondo acima. */
const Pia: React.FC<{ x: number }> = ({ x }) => {
  const w = 0.9, d = 0.5, zc = ZF + d / 2, zf = ZF + d, yt = 0.85;
  return (
    <group>
      <Caixa p={[x, 0.08, zc - 0.04]} t={[w - 0.08, 0.16, d - 0.08]} cor={C.gabinete2} />
      <Caixa p={[x, (0.16 + yt - 0.04) / 2, zc]} t={[w, yt - 0.04 - 0.16, d]} cor={C.gabinete2} />
      {[-1, 1].map((s) => (
        <group key={s}>
          <Caixa p={[x + s * w / 4, (0.16 + yt - 0.04) / 2, zf + 0.01]} t={[w / 2 - 0.08, yt - 0.04 - 0.16 - 0.08, 0.02]} cor={C.gabinete} />
          <Caixa p={[x + s * 0.09, yt - 0.18, zf + 0.04]} t={[0.04, 0.14, 0.04]} cor={C.metalEscuro} />
        </group>
      ))}
      <Caixa p={[x, yt - 0.02, zc + 0.02]} t={[w + 0.06, 0.04, d + 0.06]} cor={C.tampo} />
      {/* cuba de apoio: corpo, borda em anel e fundo cinza */}
      <Cilindro p={[x, yt, zc + 0.04]} r={0.2} r2={0.15} h={0.09} cor={C.louca} s={[1, 1, 0.8]} />
      <mesh position={[x, yt + 0.115, zc + 0.04]} rotation={[Math.PI / 2, 0, 0]} scale={[1, 0.8, 1]} material={mat(C.louca)} castShadow receiveShadow>
        <torusGeometry args={[0.18, 0.025, 8, 28]} />
      </mesh>
      <Cilindro p={[x, yt + 0.11, zc + 0.04]} r={0.16} h={0.001} cor={C.loucaSombra} s={[1, 1, 0.8]} sombra={false} />
      {/* torneira */}
      <Haste a={[x, yt, ZF + 0.07]} b={[x, yt + 0.3, ZF + 0.07]} r={0.025} cor={C.metal} />
      <Haste a={[x, yt + 0.3, ZF + 0.05]} b={[x, yt + 0.3, ZF + 0.2]} r={0.025} cor={C.metal} />
      <Cilindro p={[x + 0.1, yt, ZF + 0.07]} r={0.03} h={0.08} cor={C.metal} />
      {/* sabonete líquido e copo com escovas */}
      <Cilindro p={[x - 0.33, yt, zc]} r={0.045} h={0.15} cor={C.sabonete} />
      <Haste a={[x - 0.33, yt + 0.15, zc]} b={[x - 0.33, yt + 0.21, zc]} r={0.012} cor={C.louca} />
      <Cilindro p={[x + 0.33, yt, zc]} r={0.045} h={0.1} cor={C.copo} />
      <Haste a={[x + 0.32, yt + 0.06, zc]} b={[x + 0.29, yt + 0.24, zc]} r={0.012} cor="#3a86c8" />
      <Haste a={[x + 0.34, yt + 0.06, zc]} b={[x + 0.37, yt + 0.24, zc]} r={0.012} cor={C.toalha} />
      {/* espelho redondo: placa, moldura em anel e um reflexo diagonal claro */}
      <group position={[x, 1.58, ZF + 0.07]}>
        <mesh position={[0, 0, -0.02]} rotation={[Math.PI / 2, 0, 0]} material={mat(C.espelho, { brilho: 0.15 })} castShadow receiveShadow><cylinderGeometry args={[0.36, 0.36, 0.03, 40]} /></mesh>
        <mesh position={[0, 0, 0.02]} material={mat(C.moldura)} castShadow><torusGeometry args={[0.36, 0.045, 10, 40]} /></mesh>
        {([[-0.1, 0.08, 0.36], [0.04, -0.04, 0.2]] as const).map(([dx, dy, comp]) => (
          <Caixa key={dx} p={[dx, dy, 0.02]} t={[0.08, comp, 0.004]} r={[0, 0, -0.75]} cor="#ffffff" m={mat('#ffffff', { brilho: 0.3 })} sombra={false} />
        ))}
      </group>
    </group>
  );
};

/** Vaso sanitário branco com caixa acoplada, virado para +Z. */
const Vaso: React.FC<{ x: number }> = ({ x }) => {
  const zc = ZF + 0.45;
  return (
    <group>
      <Cilindro p={[x, 0, zc]} r={0.13} r2={0.16} h={0.3} cor={C.louca} s={[1, 1, 1.25]} />
      <Cilindro p={[x, 0.3, zc]} r={0.21} r2={0.17} h={0.1} cor={C.louca} s={[1, 1, 1.25]} />
      {/* assento e tampa fechada */}
      <Cilindro p={[x, 0.4, zc]} r={0.21} h={0.03} cor={C.loucaSombra} s={[1, 1, 1.25]} />
      <Cilindro p={[x, 0.43, zc]} r={0.2} h={0.03} cor={C.louca} s={[1, 1, 1.25]} />
      {/* caixa acoplada e botão de descarga */}
      <Caixa p={[x, 0.62, ZF + 0.12]} t={[0.44, 0.42, 0.2]} cor={C.louca} />
      <Caixa p={[x, 0.85, ZF + 0.12]} t={[0.48, 0.04, 0.24]} cor={C.louca} />
      <Cilindro p={[x, 0.87, ZF + 0.12]} r={0.04} h={0.02} cor={C.metal} />
      {/* papel higiênico ao lado */}
      <Haste a={[x + 0.4, 0.7, ZF + 0.03]} b={[x + 0.4, 0.7, ZF + 0.09]} r={0.02} cor={C.metal} />
      <mesh position={[x + 0.4, 0.66, ZF + 0.1]} rotation={[0, 0, Math.PI / 2]} material={mat('#ffffff')} castShadow><cylinderGeometry args={[0.06, 0.06, 0.11, 20]} /></mesh>
    </group>
  );
};

/** Box de vidro no canto direito: piso elevado, dois vidros com perfil grosso e chuveiro. */
const Box: React.FC = () => {
  const x0 = 2.6, z1 = ZF + 1.1, hv = 2.0, xc = (x0 + X) / 2, zc = (ZF + z1) / 2;
  return (
    <group>
      <Caixa p={[xc, 0.04, zc]} t={[X - x0, 0.08, z1 - ZF]} cor={C.louca} />
      <Caixa p={[xc, 0.1, zc]} t={[0.14, 0.01, 0.14]} cor={C.metalEscuro} sombra={false} />
      {/* vidros */}
      <mesh position={[xc, 0.08 + hv / 2, z1]} material={vidro('#cfeef6', 0.22)}><boxGeometry args={[X - x0, hv, 0.02]} /></mesh>
      <mesh position={[x0, 0.08 + hv / 2, zc]} material={vidro('#cfeef6', 0.22)}><boxGeometry args={[0.02, hv, z1 - ZF]} /></mesh>
      {/* perfis de 8 cm */}
      <Caixa p={[x0, 0.08 + hv / 2, z1]} t={[0.08, hv, 0.08]} cor={C.metal} />
      <Caixa p={[xc, 0.08 + hv, z1]} t={[X - x0, 0.08, 0.08]} cor={C.metal} />
      <Caixa p={[x0, 0.08 + hv, zc]} t={[0.08, 0.08, z1 - ZF]} cor={C.metal} />
      <Caixa p={[x0 + 0.12, 1.05, z1 + 0.05]} t={[0.04, 0.3, 0.04]} cor={C.metalEscuro} />
      {/* chuveiro: cano na parede, braço e ducha redonda */}
      <Haste a={[xc, 1.0, ZF + 0.04]} b={[xc, 2.15, ZF + 0.04]} r={0.025} cor={C.metal} />
      <Haste a={[xc, 2.15, ZF + 0.02]} b={[xc, 2.15, ZF + 0.32]} r={0.025} cor={C.metal} />
      <Cilindro p={[xc, 2.06, ZF + 0.34]} r={0.12} r2={0.09} h={0.07} cor={C.metal} />
      <mesh position={[xc, 1.15, ZF + 0.04]} rotation={[Math.PI / 2, 0, 0]} material={mat(C.metal)} castShadow><cylinderGeometry args={[0.07, 0.07, 0.05, 20]} /></mesh>
      {/* tapete na saída do box */}
      <Caixa p={[xc, 0.01, z1 + 0.42]} t={[0.7, 0.02, 0.48]} cor={C.tapete} sombra={false} />
    </group>
  );
};

/** Toalha dobrada no toalheiro da parede esquerda. */
const Toalha: React.FC = () => (
  <group>
    <Haste a={[-X + 0.02, 1.4, -1.0]} b={[-X + 0.1, 1.4, -1.0]} r={0.02} cor={C.metal} />
    <Haste a={[-X + 0.02, 1.4, -0.2]} b={[-X + 0.1, 1.4, -0.2]} r={0.02} cor={C.metal} />
    <Haste a={[-X + 0.1, 1.4, -1.05]} b={[-X + 0.1, 1.4, -0.15]} r={0.03} cor={C.metal} />
    <Caixa p={[-X + 0.1, 1.12, -0.6]} t={[0.1, 0.6, 0.62]} cor={C.toalha} />
    <Caixa p={[-X + 0.1, 0.88, -0.6]} t={[0.12, 0.08, 0.62]} cor="#ffffff" />
  </group>
);

export const Banheiro: React.FC = () => (
  <>
    <LuzInterior hemi={{ ceu: '#f4fbff', chao: '#e3edf0', forca: 2.0 }} sol={1.7} maciez={10} />
    <PlanoFoco z={-1.0} />
    {/* piso: base clara e xadrez claro 2 cm acima */}
    <Caixa p={[0, -0.045, ZC]} t={[2 * X + 0.4, 0.05, L]} cor={C.piso} sombra={false} />
    <Caixas itens={PISO} cor={C.piso2} />
    <Paredes />
    {/* teto claro, levemente aceso, sem sombra, com plafon */}
    <Caixa p={[0, H + 0.05, ZC]} t={[2 * X + 0.4, 0.1, L]} cor={C.teto} sombra={false} m={mat(C.teto, { brilho: 0.45 })} />
    <mesh position={[0, H - 0.04, -0.8]} material={mat('#fffdf4', { brilho: 0.9 })}><cylinderGeometry args={[0.28, 0.28, 0.08, 28]} /></mesh>
    <Pia x={-2.4} />
    <Vaso x={1.95} />
    <Box />
    <Toalha />
  </>
);
