// Efeito `brilho`: estrelinhas brancas de quatro pontas piscando em volta do objeto em destaque.
// Cada estrela tem lugar FIXO (sem órbita, sem giro): o pisca é só escala + opacidade + halo, com ritmo e fase
// determinísticos por estrela. Tamanho de ponta a ponta entre 0,06 e 0,12 m; todas a ≥ 0,1 m de qualquer superfície.
import * as THREE from 'three';
import React from 'react';
import { random } from 'remotion';
import { Halo, mat, suave, TAU, type V3 } from './base';

const BRANCO = '#ffffff';
const C = { ouro: '#f2b632', ouroEsc: '#d18f1c', madeira: '#6e452c', podio: '#c8372f', faixa: '#f2b632' };

/** Branco emissivo com opacidade (arredondada em 0,02 para o cache). */
const cacheEstrela = new Map<number, THREE.MeshStandardMaterial>();
const matEstrela = (opac: number) => {
  const o = Math.round(Math.min(1, Math.max(0, opac)) * 50) / 50;
  let m = cacheEstrela.get(o);
  if (!m) {
    m = new THREE.MeshStandardMaterial({ color: BRANCO, emissive: new THREE.Color(BRANCO), emissiveIntensity: 1, roughness: 0.85, transparent: true, opacity: o, depthWrite: false });
    cacheEstrela.set(o, m);
  }
  return m;
};

/** Estrela de 4 pontas com 1 m de ponta a ponta (escala depois): pontas finas, a vertical um pouco mais longa. */
const Estrela4: React.FC<{ m: THREE.Material }> = ({ m }) => (
  <group scale={[1, 1, 0.2]}>
    {[0, 1, 2, 3].map((k) => {
      const comp = k % 2 === 0 ? 0.5 : 0.4; // vertical 0,5 / horizontal 0,4 (do centro à ponta)
      return (
        <group key={k} rotation={[0, 0, (k * TAU) / 4]}>
          <mesh position={[0, comp / 2, 0]} material={m}><cylinderGeometry args={[0, 0.12, comp, 4]} /></mesh>
        </group>
      );
    })}
    <mesh material={m}><sphereGeometry args={[0.08, 12, 8]} /></mesh>
  </group>
);

/** Uma estrela do brilho: posição, tamanho (ponta a ponta, m) e quanto já acendeu. */
export type EstrelaBrilho = { p: V3; t: number };

export type PropsBrilho = {
  quadro: number;
  /** Estrelas em coordenadas do objeto (fixas). */
  estrelas: EstrelaBrilho[];
  /** Origem do objeto na cena. */
  centro?: V3;
  /** Giro (Y) para as estrelas ficarem de frente para a câmera. */
  giroY?: number;
  /** Quadro em que a 1ª estrela está no pico (capa). */
  pico?: number;
  semente?: string;
};

/** Só o brilho: use nos planos passando as estrelas em volta das partes de metal do objeto. */
export const Brilho: React.FC<PropsBrilho> = ({ quadro, estrelas, centro = [0, 0, 0], giroY = 0, pico = 90, semente = 'brilho' }) => {
  const entra = suave(quadro / 20);
  return (
    <group position={centro}>
      {estrelas.map((e, i) => {
        // ritmo próprio de 1,5 a 2,2 s; fases espalhadas pela razão áurea (+ um acaso fixo pequeno), para que no quadro
        // `pico` a estrela 0 esteja cheia e as outras em intensidades bem diferentes
        const periodo = 46 + Math.floor(random(`${semente}-p${i}`) * 20);
        const fase = i === 0 ? 0 : (((i * 0.618034) % 1) + 0.08 * random(`${semente}-f${i}`)) * TAU;
        const c = 0.5 + 0.5 * Math.cos(((quadro - pico) / periodo) * TAU + fase);
        const p = c * c; // pico curto, vale longo: lê como "piscar", não como respirar
        const esc = e.t * (0.55 + 0.45 * p) * entra;
        // lugar e giro fixos: só a escala, a opacidade e o halo mudam
        return (
          <group key={i} position={e.p} rotation={[0, giroY, 0]}>
            <Halo cor="#fff6d8" raio={Math.max(0.001, esc * 0.4)} forca={0.25 + 0.6 * p} z={-0.01} />
            <group scale={Math.max(0.001, esc)}><Estrela4 m={matEstrela((0.35 + 0.65 * p) * entra)} /></group>
          </group>
        );
      })}
    </group>
  );
};

/** Troféu dourado de 0,5 m (taça com alças, haste e base de madeira). Origem no centro da base. */
const Trofeu: React.FC = () => (
  <group>
    <mesh position={[0, 0.05, 0]} material={mat(C.madeira)} castShadow receiveShadow><boxGeometry args={[0.24, 0.1, 0.24]} /></mesh>
    <mesh position={[0, 0.12, 0]} material={mat(C.ouroEsc)} castShadow><cylinderGeometry args={[0.07, 0.09, 0.04, 20]} /></mesh>
    <mesh position={[0, 0.2, 0]} material={mat(C.ouro)} castShadow><cylinderGeometry args={[0.025, 0.03, 0.12, 12]} /></mesh>
    <mesh position={[0, 0.27, 0]} material={mat(C.ouro)} castShadow><sphereGeometry args={[0.045, 14, 10]} /></mesh>
    {/* taça: tronco de cone + fundo arredondado + borda */}
    <mesh position={[0, 0.39, 0]} material={mat(C.ouro)} castShadow receiveShadow><cylinderGeometry args={[0.15, 0.09, 0.2, 24]} /></mesh>
    <mesh position={[0, 0.3, 0]} material={mat(C.ouro)} castShadow><sphereGeometry args={[0.09, 20, 10, 0, TAU, Math.PI / 2, Math.PI / 2]} /></mesh>
    <mesh position={[0, 0.49, 0]} rotation={[Math.PI / 2, 0, 0]} material={mat(C.ouroEsc)}><torusGeometry args={[0.15, 0.015, 8, 28]} /></mesh>
    {/* alças */}
    {[-1, 1].map((l) => (
      <mesh key={l} position={[0.15 * l, 0.4, 0]} rotation={[0, 0, l > 0 ? -Math.PI / 2 : Math.PI / 2]} material={mat(C.ouro)} castShadow>
        <torusGeometry args={[0.065, 0.018, 8, 16, Math.PI]} />
      </mesh>
    ))}
  </group>
);

/** Pódio de 1º lugar, 0,3 m (caixa com faixa e o "1" em caixas). Origem no chão.
 *  A faixa fica 6 cm abaixo do topo e 2 cm para fora: nenhuma face coincide com a da caixa (sem tremido). */
const ALTURA_PODIO = 0.3;
const Podio: React.FC = () => (
  <group>
    <mesh position={[0, ALTURA_PODIO / 2, 0]} material={mat(C.podio)} castShadow receiveShadow><boxGeometry args={[0.5, ALTURA_PODIO, 0.45]} /></mesh>
    <mesh position={[0, 0.21, 0]} material={mat(C.faixa)} receiveShadow><boxGeometry args={[0.54, 0.06, 0.49]} /></mesh>
    {/* "1" na frente: haste, bandeirinha e pé */}
    <mesh position={[0, 0.105, 0.24]} material={mat(C.faixa)}><boxGeometry args={[0.045, 0.13, 0.03]} /></mesh>
    <mesh position={[-0.03, 0.155, 0.24]} rotation={[0, 0, 0.8]} material={mat(C.faixa)}><boxGeometry args={[0.04, 0.06, 0.03]} /></mesh>
    <mesh position={[0, 0.04, 0.24]} material={mat(C.faixa)}><boxGeometry args={[0.1, 0.03, 0.03]} /></mesh>
  </group>
);

/** Estrelas do troféu (coordenadas do troféu na escala 1, base em y=0): todas com 0,11 m, perto dos metais mas a ≥ 0,1 m deles.
 *  Borda da taça: raio 0,15 a y=0,49. Alças: ponta de fora em x=±0,23, y=0,34–0,47. */
export const ESTRELAS_TROFEU: EstrelaBrilho[] = [
  { p: [0.1, 0.567, 0.183], t: 0.11 }, // borda, frente-direita (pico na capa)
  { p: [0.333, 0.458, 0.042], t: 0.11 }, // fora da alça direita
  { p: [-0.142, 0.55, 0.183], t: 0.11 }, // borda, frente-esquerda
  { p: [0.025, 0.392, 0.225], t: 0.11 }, // na frente da taça
  { p: [-0.333, 0.367, 0.05], t: 0.11 }, // fora da alça esquerda
  { p: [0.0, 0.6, 0.12], t: 0.11 }, // na frente da borda, no meio
  { p: [0.225, 0.267, 0.108], t: 0.11 }, // embaixo da alça direita
];

/** Escala do troféu na vitrine (0,57 m de altura). */
const ESC_TROFEU = 1.15;
/** Pódio baixo, à frente e perto do centro: o troféu é o destaque e as estrelas ficam sobre a quadra, abaixo da linha da mureta. */
const PODIO: V3 = [0.82, 0, 0.3];
const ESTRELAS_VITRINE: EstrelaBrilho[] = ESTRELAS_TROFEU.map((e) => ({ ...e, p: e.p.map((v) => v * ESC_TROFEU) as V3 }));

/** Peça da vitrine: troféu num pódio ao lado do personagem, com o brilho nos metais dourados. */
export const BrilhoTrofeu: React.FC<{ quadro: number }> = ({ quadro }) => (
  <group>
    <group position={PODIO}>
      <Podio />
      <group position={[0, ALTURA_PODIO, 0]} scale={ESC_TROFEU}><Trofeu /></group>
    </group>
    {/* giroY: estrelas de frente para a câmera da vitrine (em x=0, z≈4) */}
    <Brilho quadro={quadro} estrelas={ESTRELAS_VITRINE} centro={[PODIO[0], ALTURA_PODIO, PODIO[2]]} giroY={-0.23} />
  </group>
);

/** Para a cena (14/11): só as estrelas, sem troféu, em volta da MÃO do personagem (onde fica o objeto em destaque).
 *  A cena coloca o efeito na posição do personagem; a mão com o objeto fica ~0,3 m à direita, 0,85–1,0 m de altura, à frente. */
const ESTRELAS_MAO: EstrelaBrilho[] = [
  { p: [0.12, 0.28, 0.06], t: 0.11 }, { p: [-0.14, 0.12, 0.08], t: 0.09 }, { p: [0.16, -0.08, 0.1], t: 0.08 },
  { p: [-0.06, 0.34, -0.04], t: 0.07 }, { p: [0.02, -0.16, 0.12], t: 0.06 },
];
export const BrilhoNaMao: React.FC<{ quadro: number }> = ({ quadro }) => (
  <Brilho quadro={quadro} estrelas={ESTRELAS_MAO} centro={[-0.32, 0.95, 0.28]} />
);
