// Efeito `estrelinhas`: estrelas amarelas de cinco pontas (0,1 m de altura) girando e piscando em órbita em volta do personagem.
// Órbita = anel inclinado de raio único (0,6 m) entre o peito e a cabeça, com um rastro fino e claro que mostra o plano.
// Todas do mesmo tamanho; o pisca é emissivo + halo (a escala varia pouco). Tudo em função do quadro.
import * as THREE from 'three';
import React, { useMemo } from 'react';
import { Halo, mat, suave, TAU, type V3 } from './base';

const AMARELO = '#ffd23a';
const AMARELO_ESC = '#f0a818';
const N = 5;
/** Raio externo da estrela: 5 pontas com 0,1 m de altura → R·(1 + cos 36°) = 0,1. */
const R_ESTRELA = 0.1 / (1 + Math.cos(Math.PI / 5));

/** Estrela de 5 pontas com raio externo 1 (escala depois): miolo pentagonal + 5 pirâmides, facetada. */
const Estrela5: React.FC<{ brilho: number }> = ({ brilho }) => {
  const m = mat(AMARELO, brilho, 0.8);
  const mb = mat(AMARELO_ESC, brilho * 0.8, 0.8);
  return (
    <group scale={[1, 1, 0.45]}>
      <mesh rotation={[Math.PI / 2, Math.PI / 10, 0]} material={m}><cylinderGeometry args={[0.42, 0.42, 0.42, 5]} /></mesh>
      {[0, 1, 2, 3, 4].map((k) => (
        <group key={k} rotation={[0, 0, (k * TAU) / 5]}>
          <mesh position={[0, 0.66, 0]} rotation={[0, Math.PI / 4, 0]} material={k % 2 ? mb : m}>
            <cylinderGeometry args={[0, 0.3, 0.68, 4]} />
          </mesh>
        </group>
      ))}
    </group>
  );
};

export type PropsEstrelinhas = {
  quadro: number;
  /** Centro da órbita (padrão: entre o peito e a cabeça do boneco parado na origem). */
  centro?: V3;
  /** Raio da órbita, em metros. */
  raio?: number;
  /** Quadros por volta completa. */
  volta?: number;
  /** Inclinação do anel: [frente para baixo, tombo de lado], em radianos. */
  inclinacao?: [number, number];
  /** Mostra o rastro do anel. */
  rastro?: boolean;
};

export const Estrelinhas: React.FC<PropsEstrelinhas> = ({
  quadro, centro = [0, 1.35, 0], raio = 0.6, volta = 120, inclinacao = [0.3, -0.14], rastro = true,
}) => {
  const q = quadro;
  const entra = suave(q / 15);
  const giroAnel = useMemo(() => new THREE.Euler(inclinacao[0], 0, inclinacao[1]), [inclinacao]);

  // rastro: toro fino aditivo no plano da órbita
  const mRastro = useMemo(() => new THREE.MeshBasicMaterial({
    color: '#ffe38a', transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
  }), []);
  mRastro.opacity = 0.32 * entra;

  const v = new THREE.Vector3();
  return (
    <group position={centro}>
      {rastro && (
        <group rotation={giroAnel}>
          <mesh rotation={[Math.PI / 2, 0, 0]} material={mRastro}><torusGeometry args={[raio, 0.012, 6, 96]} /></mesh>
        </group>
      )}
      {Array.from({ length: N }, (_, i) => {
        // ângulo a partir de +Z; no quadro 90 a estrela 0 está bem atrás da cabeça (oculta inteira, sem "corte")
        const ang = ((q - 90) / volta) * TAU + Math.PI + (i / N) * TAU;
        v.set(raio * Math.sin(ang), 0, raio * Math.cos(ang)).applyEuler(giroAnel);
        // pisca: ciclo de 1 s, fases espalhadas; emissivo de 0,3 a 1,2 e escala de 88% a 100%
        const c = 0.5 + 0.5 * Math.sin((q / 30) * TAU + (i / N) * TAU * 2);
        const p = c * c;
        const brilho = 0.3 + 0.9 * p;
        const esc = R_ESTRELA * (0.88 + 0.12 * p) * entra;
        // giro no próprio plano (sempre de frente para a câmera): uma volta a cada 2 s, sentido alternado
        const giro = (q / 60) * TAU * (i % 2 ? 1 : -1) + i;
        return (
          <group key={i} position={[v.x, v.y, v.z]}>
            <Halo cor="#ffd84a" raio={0.11 * entra} forca={0.2 + 0.55 * p} z={-0.03} />
            <group rotation={[0, 0, giro]} scale={Math.max(0.001, esc)}><Estrela5 brilho={brilho} /></group>
          </group>
        );
      })}
    </group>
  );
};
