// Ajuste só da vitrine (composição VitrineLote), no padrão do r12/r16: reposiciona a câmera do palco e o objeto.
// Fora da vitrine, os componentes continuam em tamanho real, na origem e sem câmera nem fundo.
import React, { useLayoutEffect } from 'react';
import { useThree } from '@react-three/fiber';
import { useVideoConfig } from 'remotion';
import * as THREE from 'three';
import { Caixa, mat } from './base';

type V3 = [number, number, number];
/** desloc: soma à posição que a vitrine dá ao objeto (0,75; 0 ou 0,75; 0); alvo: centro do quadro (mundo); altura: altura do quadro no alvo (m);
 *  dist: distância da câmera (2,1 = foco do DOF da vitrine); elev/azim: graus acima do alvo e giro (+ = câmera para a direita). */
type Plano = { desloc: V3; alvo: V3; altura: number; dist: number; elev: number; azim: number; janela?: boolean; pe?: V3 };

// sombra de contato suave (pe: [largura, fundo, recuo para trás-esquerda]): 4 manchas translúcidas, cada uma um
// pouco maior e mais fraca, que somadas escurecem rente ao objeto e somem em poucos milímetros
const sombraPe = new THREE.MeshBasicMaterial({ color: '#000000', transparent: true, opacity: 0.07, depthWrite: false });
const SombraContato: React.FC<{ pe: V3 }> = ({ pe: [w, d, r] }) => (
  <group position={[-r, 0.0002, -r]} rotation={[-Math.PI / 2, 0, 0]}>
    {[0, 1, 2, 3].map((i) => (
      <mesh key={i} position={[0, 0, i * 0.00003]} scale={[w + i * 0.0012, d + i * 0.0012, 1]} material={sombraPe}><planeGeometry args={[1, 1]} /></mesh>
    ))}
  </group>
);

export const PLANOS = {
  // papel no meio do tampo do pedestal (fundo neutro, sombra de contato), câmera de frente e um pouco de cima
  papelRifa: { desloc: [0, 0, 0], alvo: [0.75, 0.758, 0.0], altura: 0.085, dist: 2.1, elev: 34, azim: 24, pe: [0.05, 0.055, 0.0006] },
  // pacote deitado no meio do tampo bege do pedestal (fundo limpo, contraste com o azul); câmera alta para ver estampa e espessura
  pacoteFigurinhas: { desloc: [0, 0, 0], alvo: [0.75, 0.753, 0.0], altura: 0.165, dist: 2.1, elev: 48, azim: 10 },
  // arco-íris lá fora, visto pela janela de uma parede atrás e à direita do Téo (a parede só existe na vitrine)
  // (pés do arco no gramado, y = 0,3; o quadro abre até os pés do Téo; sem desfoque, ver `SemDesfoque`)
  arcoIrisDuplo: { desloc: [1.25, 0.3, -5.0], alvo: [1.15, 1.3, -1.2], altura: 3.9, dist: 5.8, elev: 1, azim: -3, janela: true },
} satisfies Record<string, Plano>;

const AjustarCamera: React.FC<{ p: Plano }> = ({ p }) => {
  const camera = useThree((s) => s.camera) as THREE.PerspectiveCamera;
  // roda depois da <Camera> do palco (vem antes na árvore), a cada quadro, sem loop próprio
  useLayoutEffect(() => {
    const e = (p.elev * Math.PI) / 180, a = (p.azim * Math.PI) / 180, h = p.dist * Math.cos(e);
    camera.position.set(p.alvo[0] + h * Math.sin(a), p.alvo[1] + p.dist * Math.sin(e), p.alvo[2] + h * Math.cos(a));
    camera.lookAt(...p.alvo);
    camera.fov = (2 * Math.atan(p.altura / 2 / p.dist) * 180) / Math.PI;
    camera.updateProjectionMatrix();
    camera.updateMatrixWorld();
  });
  return null;
};

// Sem desfoque: plano invisível (não escreve cor nem profundidade) a 2,1 m da câmera, o foco da vitrine.
// O BokehPass troca todos os materiais pelo de profundidade, e nesse passe o plano entra: tudo atrás dele fica "no foco".
const geoFoco = new THREE.PlaneGeometry(50, 50);
const matFoco = new THREE.MeshBasicMaterial({ colorWrite: false, depthWrite: false });
const SemDesfoque: React.FC = () => {
  const camera = useThree((s) => s.camera);
  const ref = React.useRef<THREE.Mesh>(null);
  useLayoutEffect(() => {
    const m = ref.current; if (!m) return;
    m.quaternion.copy(camera.quaternion);
    m.position.copy(camera.position).add(new THREE.Vector3(0, 0, -2.1).applyQuaternion(camera.quaternion));
    m.updateMatrixWorld();
  });
  return <mesh ref={ref} geometry={geoFoco} material={matFoco} frustumCulled={false} />;
};

// céu de fora: emissivo puro na cor do fundo da vitrine, para não ganhar sombra nem tom da luz
const ceuFora = new THREE.MeshStandardMaterial({ color: '#000000', emissive: '#9fd3ee', roughness: 1 });

/** Parede com janela larga (em coordenadas do mundo), céu e morrinhos lá fora. Só para mostrar o arco na vitrine. */
const ParedeComJanela: React.FC = () => {
  const z = -1.2, x0 = 0.45, x1 = 2.65, y0 = 0.62, y1 = 2.25; // vão da janela
  const xe = -2.2, xd = 6.5, topo = 4.2, esp = 0.16, parede = '#efe2c4', moldura = '#fbfbf7';
  return (
    <group>
      {/* parede em 4 pedaços em volta do vão; em cima e embaixo eles entram 5 cm nos lados e saltam 2 mm (encostar deixava um risco na emenda) */}
      {/* (sem sombra projetada: um pedaço sombreava o vizinho rente à emenda e deixava um risco) */}
      <Caixa p={[(xe + x0) / 2, topo / 2, z]} t={[x0 - xe, topo, esp]} cor={parede} sombra={false} />
      <Caixa p={[(x1 + xd) / 2, topo / 2, z]} t={[xd - x1, topo, esp]} cor={parede} sombra={false} />
      <Caixa p={[(x0 + x1) / 2, y0 / 2, z]} t={[x1 - x0 + 0.1, y0, esp + 0.004]} cor={parede} sombra={false} />
      <Caixa p={[(x0 + x1) / 2, (y1 + topo) / 2, z]} t={[x1 - x0 + 0.1, topo - y1, esp + 0.004]} cor={parede} sombra={false} />
      {/* rodapé */}
      <Caixa p={[(xe + xd) / 2, 0.06, z + 0.1]} t={[xd - xe, 0.12, 0.04]} cor="#c9b48c" />
      {/* moldura branca grossa e peitoril */}
      {/* (sem sombra projetada: a do peitoril virava uma faixa dura na parede) */}
      <Caixa p={[x0 - 0.05, (y0 + y1) / 2, z + 0.03]} t={[0.1, y1 - y0 + 0.2, esp + 0.06]} cor={moldura} sombra={false} />
      <Caixa p={[x1 + 0.05, (y0 + y1) / 2, z + 0.03]} t={[0.1, y1 - y0 + 0.2, esp + 0.06]} cor={moldura} sombra={false} />
      <Caixa p={[(x0 + x1) / 2, y1 + 0.05, z + 0.03]} t={[x1 - x0 + 0.2, 0.1, esp + 0.06]} cor={moldura} sombra={false} />
      <Caixa p={[(x0 + x1) / 2, y0 - 0.04, z + 0.09]} t={[x1 - x0 + 0.34, 0.08, esp + 0.2]} cor={moldura} sombra={false} />
      {/* lá fora: céu, gramado e dois morrinhos (sem sombra: a parede taparia o sol) */}
      {/* (o céu fica na frente da mureta da quadra, em z = -7,6, para ela não aparecer pela janela) */}
      <mesh position={[1.5, 3, -7.25]} material={ceuFora}><boxGeometry args={[24, 8, 0.1]} /></mesh>
      <mesh position={[1.5, 0.15, -5.0]} material={mat('#7cc46a')}><boxGeometry args={[24, 0.3, 4.4]} /></mesh>
      <mesh position={[-0.4, 0.3, -6.7]} scale={[2.4, 0.75, 0.4]} material={mat('#69b35a')}><sphereGeometry args={[1, 24, 12]} /></mesh>
      <mesh position={[4.0, 0.3, -6.8]} scale={[2.8, 0.95, 0.35]} material={mat('#5fa651')}><sphereGeometry args={[1, 24, 12]} /></mesh>
    </group>
  );
};

export function apresentar(Componente: React.FC, nome: keyof typeof PLANOS): React.FC {
  return function PecaNaVitrine() {
    const { id } = useVideoConfig();
    if (id !== 'VitrineLote') return <Componente />;
    const p: Plano = PLANOS[nome];
    return (
      <>
        <AjustarCamera p={p} />
        <group position={p.desloc}>
          <Componente />
          {p.pe && <SombraContato pe={p.pe} />}
        </group>
        {/* a vitrine põe o objeto em x = 0,75: desfaz para desenhar a parede no mundo */}
        {p.janela && <group position={[-0.75, 0, 0]}><ParedeComJanela /></group>}
        {p.janela && <SemDesfoque />}
      </>
    );
  };
}
