// Efeito: neve caindo devagar e em diagonal por toda a tela, em duas camadas bem distintas:
// perto da câmera (flocos de 2 cm, passam na frente do personagem) e em volta/atrás dele (flocos de 1 cm, mais densos).
// Cada floco desce num loop em função de `quadro`; o recomeço acontece fora do quadro (acima da tela e abaixo do chão).
// Flocos que passariam na frente do rosto encolhem até sumir e voltam depois (sem "pulo").
import * as THREE from 'three';
import React, { useMemo } from 'react';
import { random } from 'remotion';
import { mat, modulo, suave, TAU } from './base';

type Camada = { n: number; raio: number; z: [number, number]; queda: number; vento: number };
const CAMADAS: Camada[] = [
  // perto: Ø 2 cm, entre o personagem e a câmera
  { n: 210, raio: 0.01, z: [0.9, 2.6], queda: 0.012, vento: 0.0065 },
  // longe: Ø 1 cm, do personagem até 1,8 m atrás dele
  { n: 380, raio: 0.005, z: [-1.8, 0.5], queda: 0.009, vento: 0.005 },
];
const Y_BAIXO = -0.15, Y_ALTO = 3.0; // faixa de queda: nasce acima do quadro e some abaixo do chão
const ALTURA = Y_ALTO - Y_BAIXO;
// câmera típica do canal (de +Z, na altura dos olhos), usada só para saber o que fica na frente do rosto
const CAM = { y: 1.7, z: 3.9 };
const ROSTO = { x: 0, y: 1.55, rx: 0.5, ry: 0.5 }; // elipse da cabeça (com folga) no plano z = 0

/** Largura da faixa de flocos numa profundidade z: um pouco mais que o quadro visto da câmera. */
const largura = (z: number) => 2 * (0.62 * (CAM.z - z) + 0.4);

/** 0 dentro da área do rosto (projetada no plano do personagem), 1 longe dela, com transição suave. */
const foraDoRosto = (x: number, y: number, z: number) => {
  if (z <= 0) return 1; // atrás do personagem: a própria cabeça já esconde
  const s = CAM.z / (CAM.z - z);
  const px = x * s, py = CAM.y + (y - CAM.y) * s;
  const d = Math.hypot((px - ROSTO.x) / ROSTO.rx, (py - ROSTO.y) / ROSTO.ry);
  return suave((d - 1) / 0.35);
};

export const Neve: React.FC<{ quadro: number; intensidade?: number }> = ({ quadro, intensidade = 1 }) => {
  const geo = useMemo(() => CAMADAS.map((c) => new THREE.SphereGeometry(c.raio, 10, 8)), []);
  // branco com brilho, para destacar no fundo bege e no azul da quadra
  const m = mat('#ffffff', 0.6, 0.9);
  // entrada suave (1 s) para o efeito não aparecer de estalo
  const ent = suave(quadro / 30);
  return (
    <group>
      {CAMADAS.map((c, ci) => Array.from({ length: Math.round(c.n * intensidade) }, (_, i) => {
        const s = `neve-${ci}-${i}`;
        const vel = 0.8 + 0.4 * random(s + 'v');
        const z = c.z[0] + random(s + 'z') * (c.z[1] - c.z[0]);
        const L = largura(z);
        const y = Y_ALTO - modulo(random(s + 'y') * ALTURA + quadro * c.queda * vel, ALTURA);
        // diagonal: o vento leva o floco para +X; ao sair por um lado, volta pelo outro (fora do quadro)
        const x = modulo(random(s + 'x') * L + quadro * c.vento * vel + L / 2, L) - L / 2;
        // leve balanço lateral, como floco de verdade
        const bx = 0.04 * Math.sin(quadro * 0.06 + random(s + 'f') * TAU);
        const tam = (0.85 + 0.3 * random(s + 't')) * ent * foraDoRosto(x + bx, y, z);
        if (tam < 0.02) return null;
        return <mesh key={s} geometry={geo[ci]} material={m} position={[x + bx, y, z]} scale={tam} />;
      }))}
    </group>
  );
};
