// Fechado: 80 cm da base do gancho até a ponteira, antes da inclinação.
import React from 'react';
import { Caixa, mat } from './base';

const C = { amarelo: '#ffd238', claro: '#ffdc52', cinta: '#d6a021', cabo: '#75452d' };

const Cilindro: React.FC<{ y: number; altura: number; topo: number; base?: number; cor: string }> = ({ y, altura, topo, base = topo, cor }) => (
  <mesh position={[0, y, 0]} material={mat(cor)} castShadow receiveShadow>
    <cylinderGeometry args={[topo, base, altura, 48]} />
  </mesh>
);

// Oito gomos suaves, com seis segmentos por gomo (48 em volta).
const Tecido: React.FC<{ baixo: number; alto: number; base: number; topo: number }> = ({ baixo, alto, base, topo }) => (
  <group position={[0, (baixo + alto) / 2, 0]}>
    {Array.from({ length: 8 }, (_, i) => (
      <mesh key={i} material={mat(i % 2 === 0 ? C.amarelo : C.claro)} castShadow receiveShadow>
        <cylinderGeometry args={[topo, base, alto - baixo, 6, 1, false, i * Math.PI / 4, Math.PI / 4]} />
      </mesh>
    ))}
  </group>
);

export const GuardaChuva: React.FC = () => (
  <group position={[-0.037, 0, 0]}>
    {/* Gancho largo em J, com tubo de 4,4 cm e pontas arredondadas. */}
    <mesh position={[0.058, 0.080, 0]} rotation={[0, 0, Math.PI]} material={mat(C.cabo)} castShadow receiveShadow>
      <torusGeometry args={[0.058, 0.022, 16, 48, Math.PI]} />
    </mesh>
    <Cilindro y={0.1675} altura={0.175} topo={0.022} cor={C.cabo} />
    <mesh position={[0.116, 0.101, 0]} material={mat(C.cabo)} castShadow receiveShadow>
      <capsuleGeometry args={[0.022, 0.042, 8, 24]} />
    </mesh>

    {/* Silhueta afunilada sem nervuras finas ou faces planas largas. */}
    <Tecido baixo={0.235} alto={0.30} base={0.035} topo={0.064} />
    <Tecido baixo={0.30} alto={0.67} base={0.064} topo={0.035} />
    <Tecido baixo={0.67} alto={0.76} base={0.035} topo={0.014} />
    <Cilindro y={0.773} altura={0.026} topo={0.014} cor={C.cabo} />
    <mesh position={[0, 0.786, 0]} material={mat(C.cabo)} castShadow receiveShadow>
      <sphereGeometry args={[0.014, 24, 16]} />
    </mesh>

    {/* Cinta larga e fecho legível, em dois tons de marrom. */}
    <Cilindro y={0.46} altura={0.038} topo={0.055} base={0.058} cor={C.cinta} />
    <Caixa p={[0, 0.46, 0.057]} t={[0.034, 0.030, 0.012]} cor={C.cinta} />
    <mesh position={[0, 0.46, 0.066]} scale={[1, 1, 0.5]} material={mat(C.cabo)} castShadow receiveShadow>
      <sphereGeometry args={[0.009, 16, 12]} />
    </mesh>
  </group>
);
