// Plano de teste (5 s): Téo acena para a câmera, Bia chega andando, Téo fica surpreso e comemora. Câmera faz um dolly lento.
import React from 'react';
import { AbsoluteFill, useCurrentFrame, useVideoConfig } from 'remotion';
import { ThreeCanvas } from '@remotion/three';
import * as THREE from 'three';
import { Boneco } from '../kit/Boneco';
import { poseNoQuadro, misturar, pose } from '../kit/poses';
import { Quadra } from '../kit/Quadra';
import { Luz } from '../kit/Luz';
import { Camera, camNoQuadro, type ChaveCam } from '../kit/Camera';
import { Foco, Acabamento } from '../kit/Pos';
import { ELENCO } from '../kit/elenco';

const CAM: ChaveCam[] = [
  { q: 0, pos: [0.2, 1.9, 5.6], alvo: [-0.4, 1.3, 0.8], fov: 38 },
  { q: 150, pos: [-0.3, 1.7, 4.4], alvo: [-0.4, 1.35, 0.8], fov: 36 },
];
const piscar = (q: number, inicio: number) => { const d = q - inicio; return d >= 0 && d < 6 ? Math.sin((d / 6) * Math.PI) : 0; };

/** soCenario: esconde personagens e bola; usado pelo QA de cintilação para testar só o fundo e a câmera. */
export const TesteTeo: React.FC<{ soCenario?: boolean }> = ({ soCenario = false }) => {
  const q = useCurrentFrame();
  const { width, height } = useVideoConfig();

  // Téo: acena (balança entre acenar e acenar2), depois surpreso, depois comemora
  let jt = poseNoQuadro([[0, 'parado'], [8, 'acenar'], [62, 'surpreso'], [100, 'comemorar']], q, 8);
  if (q >= 16 && q < 62) jt = misturar(pose('acenar'), pose('acenar2'), 0.5 + 0.5 * Math.sin((q - 16) / 4));
  if (q >= 100) jt = { ...jt, altura: Math.abs(Math.sin((q - 100) / 5)) * 0.12 };
  const bocaT = q < 62 ? 'sorriso' : q < 100 ? 'o' : 'aberta';
  const olharT = q >= 50 && q < 100 ? 1 : 0;
  const sobT = q >= 62 ? 1 : 0;

  // Bia: entra andando da direita até parar perto do Téo
  const t = Math.min(1, q / 70);
  const biaX = 3.4 - 2.1 * (1 - (1 - t) * (1 - t));
  const andando = q < 70;
  const jb = andando ? misturar(pose('andar1'), pose('andar2'), 0.5 + 0.5 * Math.sin(q / 3.2)) : poseNoQuadro([[70, 'andar1'], [70, 'parado'], [100, 'bracosAbertos']], q, 10);

  const c = camNoQuadro(CAM, q);
  const foco = new THREE.Vector3(...c.pos).distanceTo(new THREE.Vector3(-1.0, 1.5, 0.9));

  return (
    <AbsoluteFill style={{ backgroundColor: '#9fd3ee' }}>
      <ThreeCanvas width={width} height={height} shadows flat gl={{ antialias: true, preserveDrawingBuffer: true }}
        camera={{ fov: 38, position: [0.2, 1.9, 5.6] }}>
        <color attach="background" args={['#9fd3ee']} />
        <Camera chaves={CAM} quadro={q} />
        <Luz />
        <Quadra />
        {!soCenario && (<>
        <Boneco v={ELENCO.teo} j={jt} pos={[-1.0, 0, 0.9]} giro={12}
          e={{ piscar: piscar(q, 30) + piscar(q, 118), boca: bocaT, olharX: olharT, sobrancelha: sobT }} />
        <Boneco v={ELENCO.bia} j={jb} pos={[biaX, 0, 0.5]} giro={andando ? -90 : -35}
          e={{ piscar: piscar(q, 84), boca: q < 100 ? 'neutra' : 'sorriso', olharX: -1 }} />
        <Boneco v={ELENCO.c1} pos={[-3.6, 0, -2.2]} giro={30} e={{ piscar: piscar(q, 40) }} />
        <Boneco v={ELENCO.c2} j={pose('pensar')} pos={[2.8, 0, -2.8]} giro={-30} e={{ boca: 'neutra' }} />
        <mesh position={[-0.2, 0.13, 1.9]} castShadow receiveShadow>
          <sphereGeometry args={[0.13, 32, 16]} /><meshStandardMaterial color="#e8582c" roughness={0.7} />
        </mesh>
        </>)}
        <Foco foco={foco} />
      </ThreeCanvas>
      <Acabamento quadro={q} />
    </AbsoluteFill>
  );
};
