// Cinemática do boneco padrão (mesmas medidas e ordem de giros do kit/Boneco.tsx). Base: l17-acao.
// Direta: onde estão o ombro e a mão. Inversa (analítica): que ângulos do braço levam a mão a um ponto.
import * as THREE from 'three';
import type { Juntas } from '../../../kit/poses';

const R = THREE.MathUtils.degToRad;
const G = THREE.MathUtils.radToDeg;
const m4 = (x: number, y: number, z: number, rx = 0, ry = 0, rz = 0) =>
  new THREE.Matrix4().compose(new THREE.Vector3(x, y, z), new THREE.Quaternion().setFromEuler(new THREE.Euler(rx, ry, rz)), new THREE.Vector3(1, 1, 1));

const BRACO = 0.22; // ombro → cotovelo
const ANTEBRACO = 0.25; // cotovelo → centro da mão
export const ALCANCE = BRACO + ANTEBRACO;

/** Matriz do tronco (espaço do boneco, já com a `altura`). */
export const matrizTronco = (j: Juntas) => m4(0, j.altura, 0).multiply(m4(0, 0.66, 0, R(j.troncoX), R(j.troncoY), 0)).multiply(m4(0, -0.66, 0));

/** Centro do ombro no espaço do boneco. lado 1 = braço D (+X), -1 = braço E. */
export const posOmbro = (j: Juntas, lado: 1 | -1) => new THREE.Vector3(0.25 * lado, 1.06, 0).applyMatrix4(matrizTronco(j));

/** Matriz da mão (centro da esfera); o eixo -Y dela é a direção do antebraço. */
export function matrizMao(j: Juntas, lado: 1 | -1): THREE.Matrix4 {
  const [x, z, cot] = lado === 1 ? [j.ombroDX, j.ombroDZ, j.cotoveloD] : [j.ombroEX, j.ombroEZ, j.cotoveloE];
  return matrizTronco(j)
    .multiply(m4(0.25 * lado, 1.06, 0, R(-x), 0, R(z) * lado))
    .multiply(m4(0, -BRACO, 0, R(-cot), 0, 0))
    .multiply(m4(0, -ANTEBRACO, 0));
}
export const posMao = (j: Juntas, lado: 1 | -1) => new THREE.Vector3().setFromMatrixPosition(matrizMao(j, lado));

/** Ângulos (graus) do braço para o centro da mão chegar em `alvo`; fora do alcance, o braço fica reto apontando para ele. */
function alcancar(j: Juntas, lado: 1 | -1, alvo: THREE.Vector3): { x: number; z: number; cot: number } {
  const t = alvo.clone().applyMatrix4(matrizTronco(j).invert()).sub(new THREE.Vector3(0.25 * lado, 1.06, 0));
  const d = Math.min(ALCANCE - 0.002, Math.max(0.12, t.length()));
  t.setLength(d);
  const cc = (d * d - BRACO * BRACO - ANTEBRACO * ANTEBRACO) / (2 * BRACO * ANTEBRACO);
  const cot = Math.acos(Math.min(1, Math.max(-1, cc)));
  const L = BRACO + ANTEBRACO * Math.cos(cot);
  const pz = ANTEBRACO * Math.sin(cot);
  const z = Math.asin(Math.min(1, Math.max(-1, (lado * t.x) / L)));
  const x = Math.atan2(pz, -L * Math.cos(z)) - Math.atan2(t.z, t.y);
  return { x: ((G(x) + 540) % 360) - 180, z: G(z), cot: G(cot) };
}

/** Escreve os ângulos do braço que alcança `alvo` nas juntas do lado certo. */
export function bracoNo(j: Juntas, lado: 1 | -1, alvo: THREE.Vector3): Partial<Juntas> {
  const a = alcancar(j, lado, alvo);
  return lado === 1 ? { ombroDX: a.x, ombroDZ: a.z, cotoveloD: a.cot } : { ombroEX: a.x, ombroEZ: a.z, cotoveloE: a.cot };
}

/** `altura` que apoia o pé mais baixo no chão (cantos de baixo do tênis do kit). */
export function alturaNoChao(j: Juntas): number {
  let min = Infinity;
  for (const [lado, q, jo] of [[-1, j.quadrilE, j.joelhoE], [1, j.quadrilD, j.joelhoD]] as const) {
    const pe = m4(0.1 * lado, 0.64, 0, R(-q)).multiply(m4(0, -0.25, 0, R(jo))).multiply(m4(0, -0.3, 0.05));
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
      min = Math.min(min, new THREE.Vector3(0.075 * sx, -0.055, 0.135 * sz).applyMatrix4(pe).y);
    }
  }
  return -min;
}
