// Telas em 2D (HTML do Remotion), por cima do 3D, no plano de detalhe: texto NÍTIDO e legível, como na referência.
// Peça 3D de celular/papel nunca carrega texto; o texto vem daqui.
import React from 'react';
import { AbsoluteFill, interpolate, spring, useVideoConfig } from 'remotion';

type Linha = { de: 'eu' | 'outro' | 'sistema'; texto: string };
const fonte = "'Inter', 'Segoe UI', Arial, sans-serif";

/** Celular em pé no centro, com a conversa aparecendo balão por balão. */
const Celular: React.FC<{ quadro: number; titulo?: string; linhas: Linha[] }> = ({ quadro, titulo, linhas }) => {
  const { fps } = useVideoConfig();
  const entra = spring({ frame: quadro, fps, config: { damping: 18 } });
  return (
    <AbsoluteFill style={{ alignItems: 'center', justifyContent: 'center' }}>
      <div style={{ width: 470, height: 900, borderRadius: 64, background: '#15171c', padding: 18, boxShadow: '0 30px 80px rgba(0,0,0,0.45)',
        transform: `translateY(${interpolate(entra, [0, 1], [500, 0])}px) rotate(${interpolate(entra, [0, 1], [8, -2])}deg)` }}>
        <div style={{ width: '100%', height: '100%', borderRadius: 48, background: '#eef2f5', overflow: 'hidden', fontFamily: fonte, display: 'flex', flexDirection: 'column' }}>
          <div style={{ background: '#1f8a5b', color: 'white', padding: '54px 28px 22px', fontSize: 30, fontWeight: 700 }}>{titulo ?? 'Mensagens'}</div>
          <div style={{ flex: 1, padding: 22, display: 'flex', flexDirection: 'column', gap: 16, justifyContent: 'flex-end' }}>
            {linhas.map((l, i) => {
              const a = spring({ frame: quadro - 12 - i * 16, fps, config: { damping: 14 } });
              if (l.de === 'sistema') return <div key={i} style={{ alignSelf: 'center', fontSize: 22, color: '#6b7680', opacity: a }}>{l.texto}</div>;
              return (
                <div key={i} style={{ alignSelf: l.de === 'eu' ? 'flex-end' : 'flex-start', maxWidth: '80%', background: l.de === 'eu' ? '#d7f8c6' : 'white',
                  borderRadius: 22, padding: '16px 20px', fontSize: 28, lineHeight: 1.25, color: '#1b1f23', boxShadow: '0 2px 6px rgba(0,0,0,0.12)',
                  opacity: a, transform: `scale(${interpolate(a, [0, 1], [0.6, 1])})`, transformOrigin: l.de === 'eu' ? 'right bottom' : 'left bottom' }}>{l.texto}</div>
              );
            })}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

/** Papel (prova, bilhete, volante): folha clara inclinada com linhas e um destaque grande. */
const Papel: React.FC<{ quadro: number; titulo?: string; linhas: Linha[] }> = ({ quadro, titulo, linhas }) => {
  const { fps } = useVideoConfig();
  const entra = spring({ frame: quadro, fps, config: { damping: 16 } });
  return (
    <AbsoluteFill style={{ alignItems: 'center', justifyContent: 'center' }}>
      <div style={{ width: 760, minHeight: 860, background: '#fbfaf5', borderRadius: 10, padding: '60px 70px', fontFamily: fonte, color: '#2b2f36',
        boxShadow: '0 30px 80px rgba(0,0,0,0.4)', transform: `translateY(${interpolate(entra, [0, 1], [600, 0])}px) rotate(-3deg)`,
        backgroundImage: 'repeating-linear-gradient(#fbfaf5 0 52px, #cfd8e3 52px 54px)' }}>
        {titulo && <div style={{ fontSize: 40, fontWeight: 800, marginBottom: 30 }}>{titulo}</div>}
        {linhas.map((l, i) => (
          <div key={i} style={{ fontSize: l.de === 'sistema' ? 150 : 38, fontWeight: l.de === 'sistema' ? 900 : 500, color: l.de === 'sistema' ? '#d3202f' : '#2b2f36',
            lineHeight: 1.35, opacity: spring({ frame: quadro - 10 - i * 10, fps }) }}>{l.texto}</div>
        ))}
      </div>
    </AbsoluteFill>
  );
};

export const Tela2D: React.FC<{ quadro: number; tipo: 'celular' | 'papel'; titulo?: string; linhas: Linha[] }> = (p) =>
  p.tipo === 'celular' ? <Celular {...p} /> : <Papel {...p} />;

/** Contador grande na virada do dia: aparece grande embaixo à esquerda e encolhe para o canto (como na referência). */
export const HudGrande: React.FC<{ quadro: number; rotulo: string; valor: string }> = ({ quadro, rotulo, valor }) => {
  const { fps } = useVideoConfig();
  const entra = spring({ frame: quadro, fps, config: { damping: 20 } });
  const sai = interpolate(quadro, [50, 70], [1, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  if (sai <= 0) return null;
  return (
    <AbsoluteFill style={{ justifyContent: 'flex-end', padding: '0 0 120px 110px', fontFamily: fonte, color: 'white', opacity: sai, textShadow: '0 4px 20px rgba(0,0,0,0.5)' }}>
      <div style={{ transform: `translateY(${interpolate(entra, [0, 1], [60, 0])}px)`, opacity: entra }}>
        <div style={{ fontSize: 46, letterSpacing: 10, fontWeight: 600 }}>{rotulo}</div>
        <div style={{ fontSize: 170, fontWeight: 300, lineHeight: 1 }}>{valor}</div>
      </div>
    </AbsoluteFill>
  );
};
