import React from 'react';
import * as THREE from 'three';

export type V3 = [number, number, number];
const cache = new Map<string, THREE.MeshStandardMaterial>();
export const mat = (cor: string, rugosidade = 0.85) => {
  const chave = `${cor}-${rugosidade}`;
  let material = cache.get(chave);
  if (!material) {
    material = new THREE.MeshStandardMaterial({ color: cor, roughness: rugosidade });
    cache.set(chave, material);
  }
  return material;
};
export const Caixa: React.FC<{ p: V3; t: V3; cor: string; giro?: V3; sombra?: boolean; receberSombra?: boolean }> = ({ p, t, cor, giro, sombra = true, receberSombra = true }) => (
  <mesh position={p} rotation={giro} material={mat(cor)} castShadow={sombra} receiveShadow={receberSombra}>
    <boxGeometry args={t} />
  </mesh>
);
export const Haste: React.FC<{ a: V3; b: V3; r: number; cor: string }> = ({ a, b, r, cor }) => {
  const inicio = new THREE.Vector3(...a);
  const fim = new THREE.Vector3(...b);
  const direcao = fim.clone().sub(inicio);
  const giro = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), direcao.clone().normalize());
  return (
    <mesh position={inicio.add(fim).multiplyScalar(0.5)} quaternion={giro} material={mat(cor)} castShadow receiveShadow>
      <cylinderGeometry args={[r, r, direcao.length(), 10]} />
    </mesh>
  );
};
// Caixas e quartos de cilindro encostados, sem faces sobrepostas.
export const Arredondado: React.FC<{ largura: number; altura: number; fundo: number; raio: number; material: THREE.Material; sombra?: boolean; receberSombra?: boolean }> = ({ largura, altura, fundo, raio, material, sombra = true, receberSombra = true }) => (
  <group>
    <mesh material={material} castShadow={sombra} receiveShadow={receberSombra}><boxGeometry args={[largura - 2 * raio, altura, fundo]} /></mesh>
    {([-1, 1] as const).map((lado) => (
      <mesh key={lado} position={[lado * (largura - raio) / 2, 0, 0]} material={material} castShadow={sombra} receiveShadow={receberSombra}>
        <boxGeometry args={[raio, altura - 2 * raio, fundo]} />
      </mesh>
    ))}
    {([[-1, -1, Math.PI * 1.5], [1, -1, 0], [1, 1, Math.PI / 2], [-1, 1, Math.PI]] as const).map(([x, y, angulo]) => (
      <mesh key={`${x}-${y}`} position={[x * (largura / 2 - raio), y * (altura / 2 - raio), 0]} rotation={[Math.PI / 2, 0, 0]} material={material} castShadow={sombra} receiveShadow={receberSombra}>
        <cylinderGeometry args={[raio, raio, fundo, 8, 1, false, angulo, Math.PI / 2]} />
      </mesh>
    ))}
  </group>
);
