// Efeito: tela holográfica do grupo "Família 💛" ao lado do personagem, projetada por um disco no chão.
// Balões verdes chegam em rajada e a conversa sobe; balões escapam pelo topo deixando rastro; avatares grandes + "+40".
// Medidas em metros (painel de 0,95 m de altura; o prop `altura` escala tudo).
// Anti-tremido (qa/cintilacao.py reprova pixel que vai e volta em 1 quadro):
//  - a conversa sobe AOS SALTOS: muda num quadro e fica parada nos outros 3 (nada vai e volta);
//  - o que se move sem parar (balões voando) é lento (~2 cm/quadro) e só tem peças com mais de 5 cm na direção do movimento;
//  - sem flutuação lenta e sem detalhe fino que se mexa.
import React from 'react';
import * as THREE from 'three';
import { random } from 'remotion';
import { mat, suave, Ret, Disco, Traco, type V3 } from './base';

const C = {
  moldura: '#1d2a35', aura: '#5fe39a', tela: '#f5f1e6', barra: '#e6dfcf', topo: '#148a46',
  entra: '#2fcf6a', sai: '#14a957', branco: '#ffffff', amarelo: '#ffc61a', ouro: '#f4b928', ouroBorda: '#c98a12', olho: '#3b2a12',
  rastro: '#9ef0bd',
};
const FUNDOS = ['#ff8a3d', '#3d8bff', '#a45cff', '#ff4f8b', '#00b8a9', '#ffb703', '#e63946'];
const PELES = ['#f6d2b8', '#e3ab84', '#c98d63', '#8d5a3a', '#6a4128'];
const CABELOS = ['#2b1d14', '#5a3a22', '#a0522d', '#e2b65a', '#8f8f8f', '#141414'];

// tela (coordenadas do painel, centro em 0): conversa entre Y_INF e Y_SUP, atrás das tampas
const W = 0.52;
const Y_INF = -0.35; // topo da barra de digitação
const Y_SUP = 0.25; // base do cabeçalho
const VAO = 0.03; // espaço entre balões
const T = 4; // quadros entre duas mensagens (7,5 por segundo)
const Z = { tela: 0.032, balao: 0.042, conteudo: 0.048, tampa: 0.058, sobre: 0.066 };

type Avatar = { fundo: string; pele: string; cabelo: string };
type Emoji = 'coracao' | 'sorriso' | 'moeda';
type Msg = { esq: boolean; w: number; h: number; linhas: number[]; emojis: Emoji[] | null; av: Avatar };

const escolher = <X,>(lista: X[], r: number) => lista[Math.floor(r * lista.length) % lista.length];
const avatar = (s: string): Avatar => ({ fundo: escolher(FUNDOS, random(s + 'f')), pele: escolher(PELES, random(s + 'p')), cabelo: escolher(CABELOS, random(s + 'c')) });

// conversa fixa (determinística) e a altura acumulada
const N = 400;
const MSGS: Msg[] = [];
const ACUM: number[] = [0];
for (let i = 0; i < N; i++) {
  const r = (k: string) => random(`familia2-${i}-${k}`);
  const esq = r('lado') < 0.7; // a maioria vem dos parentes
  let w: number, h: number, linhas: number[] = [], emojis: Emoji[] | null = null;
  if (r('tipo') < 0.35) {
    const n = 1 + Math.floor(r('n') * 3);
    const tipo = escolher<Emoji>(['coracao', 'coracao', 'sorriso', 'moeda'], r('e'));
    emojis = Array.from({ length: n }, (_, k) => (k > 0 && r('mix' + k) < 0.4 ? 'coracao' : tipo));
    w = 0.04 + n * 0.07; h = 0.1;
  } else {
    const n = r('n') < 0.55 ? 1 : 2;
    w = 0.22 + r('w') * 0.1;
    linhas = Array.from({ length: n }, (_, k) => (k === n - 1 && n > 1 ? 0.45 + r('l') * 0.35 : 1));
    h = 0.05 + n * 0.035;
  }
  MSGS.push({ esq, w, h, linhas, emojis, av: avatar(`familia2-av-${i}`) });
  ACUM.push(ACUM[i] + h + VAO);
}

/** Avatar redondo: fundo saturado, cabelo e rosto. */
const Rosto: React.FC<{ x: number; y: number; z: number; r: number; a: Avatar; b: number }> = ({ x, y, z, r, a, b }) => (
  <group position={[x, y, z]}>
    <Disco r={r} d={0.003} x={0} y={0} z={0} m={mat(a.fundo, b)} />
    <Disco r={r * 0.6} d={0.003} x={0} y={r * 0.14} z={0.003} m={mat(a.cabelo, b * 0.5)} />
    <Disco r={r * 0.47} d={0.003} x={0} y={-r * 0.08} z={0.006} m={mat(a.pele, b)} />
  </group>
);

/** Coração: quadrado a 45° + dois discos nas arestas de cima. `s` = largura total. */
const Coracao: React.FC<{ x: number; y: number; z: number; s: number; cor: string; b: number }> = ({ x, y, z, s, cor, b }) => {
  const m = mat(cor, b), l = s / 1.53, o = l / (2 * Math.SQRT2);
  return (
    <group position={[x, y - 0.12 * l, z]}>
      <mesh rotation={[0, 0, Math.PI / 4]} material={m}><boxGeometry args={[l, l, 0.004]} /></mesh>
      <Disco r={l / 2} d={0.004} x={-o} y={o} z={0} m={m} />
      <Disco r={l / 2} d={0.004} x={o} y={o} z={0} m={m} />
    </group>
  );
};

const EmojiPeca: React.FC<{ tipo: Emoji; x: number; y: number; z: number; b: number }> = ({ tipo, x, y, z, b }) => {
  const r = 0.027;
  if (tipo === 'coracao') return <Coracao x={x} y={y} z={z} s={0.058} cor={C.amarelo} b={b} />;
  if (tipo === 'sorriso') return (
    <group position={[x, y, z]}>
      <Disco r={r} d={0.004} x={0} y={0} z={0} m={mat(C.amarelo, b)} />
      <Disco r={r * 0.17} d={0.003} x={-r * 0.36} y={r * 0.25} z={0.003} m={mat(C.olho)} />
      <Disco r={r * 0.17} d={0.003} x={r * 0.36} y={r * 0.25} z={0.003} m={mat(C.olho)} />
      <mesh position={[0, -r * 0.05, 0.003]} rotation={[0, 0, Math.PI]} material={mat(C.olho)}><torusGeometry args={[r * 0.5, r * 0.13, 6, 16, Math.PI]} /></mesh>
    </group>
  );
  return (
    <group position={[x, y, z]}>
      <Disco r={r} d={0.004} x={0} y={0} z={0} m={mat(C.ouro, b)} />
      <mesh position={[0, 0, 0.003]} material={mat(C.ouroBorda)}><torusGeometry args={[r * 0.66, r * 0.12, 6, 20]} /></mesh>
    </group>
  );
};

/** Balão da conversa com a base em `y`. */
const Balao: React.FC<{ m: Msg; y: number; b: number }> = ({ m, y, b }) => {
  const cx = m.esq ? -0.17 + m.w / 2 : 0.235 - m.w / 2;
  const cor = mat(m.esq ? C.entra : C.sai, b);
  const zc = Z.conteudo - Z.balao;
  const x0 = -m.w / 2 + 0.03;
  return (
    <group>
      {m.esq && <Rosto x={-0.215} y={y + 0.035} z={Z.balao} r={0.035} a={m.av} b={b} />}
      <group position={[cx, y + m.h / 2, Z.balao]}>
        <Ret w={m.w} h={m.h} d={0.006} r={0.03} z={0} m={cor} />
        {/* biquinho embaixo, do lado de quem mandou */}
        <mesh position={[(m.esq ? -1 : 1) * (m.w / 2 - 0.012), -m.h / 2 + 0.012, -0.0005]} rotation={[0, 0, Math.PI / 4]} material={cor}>
          <boxGeometry args={[0.034, 0.034, 0.005]} />
        </mesh>
        {m.emojis
          ? m.emojis.map((e, k) => <EmojiPeca key={k} tipo={e} x={-m.w / 2 + 0.055 + k * 0.07} y={0} z={zc} b={b + 0.1} />)
          : m.linhas.map((f, k) => {
            const lw = f * (m.w - 0.06);
            const ly = (m.linhas.length - 1) * 0.0175 - k * 0.035;
            return <mesh key={k} position={[x0 + lw / 2, ly, zc]} material={mat(C.branco, b)}><boxGeometry args={[lw, 0.02, 0.004]} /></mesh>;
          })}
      </group>
    </group>
  );
};

// título "Família" em traços (grade: maiúscula = 1, minúscula = 0,66)
type Peca = { t: 'traco'; s: [number, number, number, number] } | { t: 'anel'; x: number; y: number; r: number; arco?: boolean } | { t: 'ponto'; x: number; y: number };
type Glifo = { w: number; p: Peca[] };
const tr = (ax: number, ay: number, bx: number, by: number): Peca => ({ t: 'traco', s: [ax, ay, bx, by] });
const F: Glifo = { w: 0.5, p: [tr(0, 0, 0, 1), tr(0, 1, 0.52, 1), tr(0, 0.55, 0.42, 0.55)] };
const A: Glifo = { w: 0.58, p: [{ t: 'anel', x: 0.27, y: 0.3, r: 0.24 }, tr(0.58, 0, 0.58, 0.64)] };
const M: Glifo = { w: 0.76, p: [tr(0, 0, 0, 0.64), tr(0.38, 0, 0.38, 0.48), tr(0.76, 0, 0.76, 0.48), { t: 'anel', x: 0.19, y: 0.46, r: 0.19, arco: true }, { t: 'anel', x: 0.57, y: 0.46, r: 0.19, arco: true }] };
const I_AGUDO: Glifo = { w: 0, p: [tr(0, 0, 0, 0.64), tr(0.02, 0.82, 0.16, 1.0)] };
const L: Glifo = { w: 0, p: [tr(0, 0, 0, 1.04)] };
const I: Glifo = { w: 0, p: [tr(0, 0, 0, 0.64), { t: 'ponto', x: 0, y: 0.88 }] };
const TITULO = [F, A, M, I_AGUDO, L, I, A];
const ESP = 0.36; // espaço entre letras
const E = 0.2; // espessura do traço
const LARG_TITULO = TITULO.reduce((s, g) => s + g.w + ESP, -ESP);

const Titulo: React.FC<{ x: number; y: number; z: number; alt: number; b: number }> = ({ x, y, z, alt, b }) => {
  const m = mat(C.branco, b);
  let cursor = 0;
  return (
    <group position={[x, y, z]} scale={[alt, alt, 1]}>
      {TITULO.map((g, i) => {
        const x0 = cursor; cursor += g.w + ESP;
        return g.p.map((p, k) => {
          const key = `${i}-${k}`;
          if (p.t === 'traco') return <Traco key={key} a={[x0 + p.s[0], p.s[1]]} b={[x0 + p.s[2], p.s[3]]} e={E} d={0.004} z={0} m={m} />;
          if (p.t === 'ponto') return <mesh key={key} position={[x0 + p.x, p.y, 0]} material={m}><boxGeometry args={[E * 1.1, E * 1.1, 0.004]} /></mesh>;
          return <mesh key={key} position={[x0 + p.x, p.y, 0]} material={m}><torusGeometry args={[p.r, E / 2, 8, 24, p.arco ? Math.PI : Math.PI * 2]} /></mesh>;
        });
      })}
    </group>
  );
};

// "+40" em 7 segmentos (grade: largura 0,55, altura 1)
const SEG: Record<string, [number, number, number, number]> = {
  a: [0, 1, 0.55, 1], b: [0.55, 1, 0.55, 0.5], c: [0.55, 0.5, 0.55, 0], d: [0, 0, 0.55, 0], e: [0, 0, 0, 0.5], f: [0, 0.5, 0, 1], g: [0, 0.5, 0.55, 0.5],
};
const DIG: Record<string, string> = { '4': 'bcfg', '0': 'abcdef' };
const Contagem: React.FC<{ x: number; y: number; z: number; alt: number; b: number }> = ({ x, y, z, alt, b }) => {
  const m = mat(C.branco, b);
  return (
    <group position={[x, y, z]} scale={[alt, alt, 1]}>
      <Traco a={[0, 0.5]} b={[0.5, 0.5]} e={0.2} d={0.004} z={0} m={m} />
      <Traco a={[0.25, 0.25]} b={[0.25, 0.75]} e={0.2} d={0.004} z={0} m={m} />
      {['4', '0'].map((d, i) => DIG[d].split('').map((s) => {
        const [ax, ay, bx, by] = SEG[s];
        return <Traco key={`${i}${s}`} a={[0.85 + i * 0.85 + ax, ay]} b={[0.85 + i * 0.85 + bx, by]} e={0.2} d={0.004} z={0} m={m} />;
      }))}
    </group>
  );
};

// luz do projetor: cone translúcido (não escreve profundidade, não faz sombra)
const mFeixe = new THREE.MeshBasicMaterial({ color: C.aura, transparent: true, opacity: 0.16, depthWrite: false, toneMapped: false });

const VOO_DUR = 36; // quadros de voo
const VOO_CAD = 6; // um balão novo a cada 6 quadros

/** Balão que escapa pelo topo e sobe com rastro. Movimento lento e reto; nada fino no sentido do movimento. */
const BalaoVoando: React.FC<{ i: number; q: number }> = ({ i, q }) => {
  const t = (q - i * VOO_CAD) / VOO_DUR;
  if (t <= 0 || t >= 1) return null;
  const r = (k: string) => random(`familia2-voa-${i}-${k}`);
  const x0 = -0.16 + r('x') * 0.32, y0 = 0.56;
  const dx = -0.55 + r('dx') * 0.7, dy = 0.4 + r('dy') * 0.1;
  const x = x0 + dx * t, y = y0 + dy * t;
  const esc = suave(t / 0.15) * (1 - suave((t - 0.8) / 0.2));
  const esq = r('lado') < 0.6, cor = mat(esq ? C.entra : C.sai, 0.35);
  const ang = Math.atan2(dy, dx); // direção do voo
  const rastro = Math.min(0.24, Math.hypot(dx, dy) * t) * esc; // nunca passa do ponto de saída
  return (
    <group position={[x, y, 0.09 + (i & 3) * 0.02]}>
      {/* rastro: faixa chapada para trás, de ponta arredondada */}
      <group rotation={[0, 0, ang]} position={[0, 0, -0.012]}>
        <mesh position={[-rastro / 2, 0, 0]} material={mat(C.rastro, 0.5)}><boxGeometry args={[rastro, 0.05 * esc, 0.004]} /></mesh>
        <Disco r={0.025 * esc} d={0.004} x={-rastro} y={0} z={0} m={mat(C.rastro, 0.5)} />
      </group>
      <group scale={esc} rotation={[0, 0, (esq ? 1 : -1) * 0.12]}>
        <Ret w={0.17} h={0.1} d={0.012} r={0.035} z={0} m={cor} />
        {r('tipo') < 0.5
          ? <Coracao x={0} y={0} z={0.008} s={0.062} cor={C.amarelo} b={0.4} />
          : <mesh position={[0, 0, 0.008]} material={mat(C.branco, 0.4)}><boxGeometry args={[0.11, 0.024, 0.004]} /></mesh>}
      </group>
    </group>
  );
};

export const GrupoFamilia: React.FC<{
  quadro: number;
  /** ponto do chão sob a tela (o projetor fica aqui), em metros */ pos?: V3;
  /** altura da tela em metros (0,95 por padrão) */ altura?: number;
  /** altura do centro da tela em metros */ centroY?: number;
  /** giro em Y (rad); o padrão vira a tela um pouco para a câmera */ giro?: number;
  /** balões escapando pelo topo */ voando?: boolean;
  /** disco projetor no chão + feixe */ projetor?: boolean;
}> = ({ quadro, pos = [1.0, 0, 0.35], altura = 0.95, centroY = 1.08, giro = -0.18, voando = true, projetor = true }) => {
  const q = Math.max(0, quadro);
  const e = suave(q / 12);
  const ent = e + 0.08 * Math.sin(Math.PI * e); // entrada com pulinho
  const esc = (altura / 0.95) * ent;
  const b = 0.32; // brilho da tela
  const base = centroY - altura / 2; // pé da tela

  // conversa aos saltos: a mensagem k chega no quadro k*T e a pilha sobe de uma vez
  const K0 = 6;
  const k = K0 + (Math.floor(q / T) % (N - K0 - 10));
  const visiveis: { i: number; y: number }[] = [];
  for (let i = k; i >= 0; i--) {
    const y = Y_INF + VAO + (ACUM[k + 1] - ACUM[i + 1]);
    if (y > Y_SUP) break;
    visiveis.push({ i, y });
  }

  // membros no cabeçalho
  const membros = Array.from({ length: 6 }, (_, n) => avatar(`familia2-cab-${n}`));

  return (
    <group position={[pos[0], pos[1], pos[2]]} rotation={[0, giro, 0]}>
      {projetor && (<>
        {/* disco projetor no chão (dá o apoio e a escala) */}
        <mesh position={[0, 0.03, 0]} material={mat(C.moldura)} castShadow receiveShadow><cylinderGeometry args={[0.17, 0.19, 0.06, 32]} /></mesh>
        <mesh position={[0, 0.062, 0]} material={mat(C.aura, 0.9)}><cylinderGeometry args={[0.12, 0.12, 0.008, 32]} /></mesh>
        {ent > 0.02 && (
          <mesh position={[0, 0.066 + (base - 0.066) * ent / 2, 0]} scale={[ent, ent, ent]} material={mFeixe}>
            <cylinderGeometry args={[0.24, 0.12, Math.max(0.01, base - 0.066), 32, 1, true]} />
          </mesh>
        )}
      </>)}

      <group position={[0, centroY, 0]} scale={esc}>
        {/* aura verde + moldura escura + fundo da conversa */}
        <Ret w={0.6} h={1.03} d={0.016} r={0.07} z={0} m={mat(C.aura, 0.7)} />
        <Ret w={0.56} h={0.99} d={0.02} r={0.055} z={0.016} m={mat(C.moldura)} sombra />
        <Ret w={W} h={0.95} d={0.004} r={0.04} z={Z.tela} m={mat(C.tela, b)} />
        {visiveis.map(({ i, y }) => <Balao key={i} m={MSGS[i]} y={y} b={b} />)}

        {/* cabeçalho verde: título, coração e membros */}
        <Ret w={W} h={0.23} d={0.008} r={0.04} y={0.36} z={Z.tampa} m={mat(C.topo, b)} />
        <mesh position={[0, 0.275, Z.tampa]} material={mat(C.topo, b)}><boxGeometry args={[W, 0.05, 0.008]} /></mesh>
        <Titulo x={-0.205} y={0.375} z={Z.sobre} alt={0.07} b={0.7} />
        <Coracao x={-0.205 + LARG_TITULO * 0.07 + 0.06} y={0.405} z={Z.sobre} s={0.07} cor={C.amarelo} b={0.55} />
        {membros.map((a, n) => <Rosto key={n} x={-0.21 + n * 0.046} y={0.305} z={Z.sobre + n * 0.0015} r={0.03} a={a} b={b + 0.1} />)}
        <Contagem x={0.075} y={0.284} z={Z.sobre} alt={0.044} b={0.7} />

        {/* barra de digitação e botão de enviar */}
        <Ret w={W} h={0.13} d={0.008} r={0.04} y={-0.41} z={Z.tampa} m={mat(C.barra, b)} />
        <mesh position={[0, -0.37, Z.tampa]} material={mat(C.barra, b)}><boxGeometry args={[W, 0.05, 0.008]} /></mesh>
        <Ret w={0.36} h={0.07} d={0.004} r={0.035} x={-0.06} y={-0.41} z={Z.sobre} m={mat(C.branco, b)} />
        <Disco r={0.04} d={0.004} x={0.19} y={-0.41} z={Z.sobre} m={mat(C.topo, b)} />
        <group position={[0.195, -0.41, Z.sobre + 0.004]} rotation={[0, 0, Math.PI / 2]}>
          <mesh rotation={[Math.PI / 2, 0, 0]} material={mat(C.branco, b)}><cylinderGeometry args={[0.022, 0.022, 0.004, 3]} /></mesh>
        </group>

        {voando && Array.from({ length: Math.ceil(VOO_DUR / VOO_CAD) + 1 }, (_, j) => {
          const i = Math.floor(q / VOO_CAD) - j; // negativos: já estão no ar no quadro 0
          return <BalaoVoando key={i} i={i} q={q} />;
        })}
      </group>
    </group>
  );
};
