// Objeto: xícara de café (8 cm de boca) sobre pires (14 cm), cheia de café frio (sem fumaça). Origem no centro da base.
import React from 'react';
import { Cil, mat } from './base';

const C = { louca: '#f7f4ee', sombraLouca: '#dcd6cb', cafe: '#8a5530', borda: '#6e4224', colher: '#b6bcc4' };

// medidas (m): pires até y = 0,016; xícara de 0,016 a 0,074
const Y_PIRES = 0.016, H_XIC = 0.058, R_BOCA = 0.04, R_FUNDO = 0.028;

export const XicaraCafe: React.FC = () => {
  const topo = Y_PIRES + H_XIC;
  return (
    <group>
      {/* pires: pé, prato inclinado e aro grosso; anel cinza-claro marca o encaixe da xícara */}
      <Cil p={[0, 0.003, 0]} topo={0.046} base={0.044} h={0.006} cor={C.sombraLouca} />
      <Cil p={[0, 0.0105, 0]} topo={0.068} base={0.05} h={0.009} cor={C.louca} lados={48} />
      <mesh position={[0, 0.0148, 0]} rotation={[Math.PI / 2, 0, 0]} material={mat(C.louca)} castShadow receiveShadow>
        <torusGeometry args={[0.067, 0.0045, 10, 48]} />
      </mesh>
      <Cil p={[0, 0.0153, 0]} topo={0.036} h={0.0016} cor={C.sombraLouca} lados={40} />

      {/* xícara virada com a alça para a frente-direita (3/4) */}
      <group rotation={[0, -0.55, 0]}>
        <Cil p={[0, Y_PIRES + 0.0035, 0]} topo={0.027} base={0.025} h={0.007} cor={C.sombraLouca} />
        <Cil p={[0, Y_PIRES + 0.004 + (H_XIC - 0.004) / 2, 0]} topo={R_BOCA} base={R_FUNDO} h={H_XIC - 0.004} cor={C.louca} lados={48} />
        {/* café cheio até perto da borda: disco marrom médio com um anel mais escuro encostado no aro */}
        <Cil p={[0, topo + 0.0008, 0]} topo={R_BOCA - 0.0015} h={0.0016} cor={C.cafe} lados={48} />
        <mesh position={[0, topo + 0.0016, 0]} rotation={[Math.PI / 2, 0, 0]} scale={[1, 1, 0.3]} material={mat(C.borda)} receiveShadow>
          <torusGeometry args={[R_BOCA - 0.004, 0.002, 6, 48]} />
        </mesh>
        {/* aro da boca (lábio arredondado) */}
        <mesh position={[0, topo + 0.001, 0]} rotation={[Math.PI / 2, 0, 0]} material={mat(C.louca)} castShadow receiveShadow>
          <torusGeometry args={[R_BOCA - 0.0005, 0.0035, 10, 48]} />
        </mesh>
        {/* alça: meio toro grosso no lado +X */}
        <mesh position={[0.035, Y_PIRES + 0.032, 0]} rotation={[0, 0, -Math.PI / 2]} material={mat(C.louca)} castShadow receiveShadow>
          <torusGeometry args={[0.016, 0.0058, 12, 24, Math.PI]} />
        </mesh>
      </group>

      {/* colherinha no pires, à esquerda da xícara */}
      <group position={[-0.047, Y_PIRES + 0.003, 0.03]} rotation={[0, 0.9, 0]}>
        <mesh position={[0, 0, 0.012]} scale={[0.009, 0.003, 0.014]} material={mat(C.colher, 0.45)} castShadow receiveShadow>
          <sphereGeometry args={[1, 20, 10]} />
        </mesh>
        <mesh position={[0, 0.001, -0.02]} rotation={[Math.PI / 2, 0, 0]} material={mat(C.colher, 0.45)} castShadow receiveShadow>
          <capsuleGeometry args={[0.0028, 0.04, 4, 10]} />
        </mesh>
      </group>
    </group>
  );
};
