// Efeito: celular gigante "de brinquedo" (1 m) de pé num suporte no chão, ao lado do personagem, com o grupo "FAMÍLIA 💛":
// faixa de ~30 avatares no topo, balões verdes chegando em rajada (a conversa sobe rápido) e balões escapando pelo topo.
// Atrás, um palco liso (parede + piso) esconde a parede e as linhas da quadra (prop `palco`).
// Anti-tremido (qa/cintilacao.py reprova pixel que vai e volta em 1 quadro):
//  - a conversa sobe AOS SALTOS: muda num quadro e fica parada nos 3 seguintes;
//  - os balões que escapam sobem retos, a 1,4 cm/quadro, e tudo neles mede ≥ 4,5 cm na direção do movimento;
//  - sem entrada com "pulinho", sem flutuação, sem transparência.
import React from 'react';
import { random } from 'remotion';
import { Caixa, Disco, mat, Ret, suave, Traco, type V3 } from './base';

const C = {
  corpo: '#1f2b38', borda: '#2f3e4f', lente: '#0b0f14', suporte: '#f2b630', suporteEsc: '#d49a1c',
  tela: '#f6f2e8', topo: '#138a45', faixa: '#d4efdd', barra: '#e7e1d4', branco: '#ffffff',
  parente: '#2fcf6a', voce: '#169e52', rastro: '#9fe7b9', amarelo: '#ffc61a', ouro: '#f4b928', ouroBorda: '#c98a12', olho: '#3b2a12',
  parede: '#c9dbe6', rodape: '#a9bfcd', piso: '#ddd2c0',
};
const FUNDOS = ['#ff8a3d', '#3d8bff', '#a45cff', '#ff4f8b', '#00b8a9', '#ffb703', '#e63946', '#6a994e'];
const PELES = ['#f6d2b8', '#e3ab84', '#c98d63', '#8d5a3a', '#6a4128'];
const CABELOS = ['#2b1d14', '#5a3a22', '#a0522d', '#e2b65a', '#9a9a9a', '#141414'];
const B = 0.2; // brilho leve da tela (acesa, mas cor chapada)

// celular: 0,5 x 1,0 m; tela 0,44 x 0,9. Camadas em Z (frente da tela em +Z), 4 mm entre elas
const W = 0.44;
const Z = { tela: 0.027, balao: 0.032, conteudo: 0.036, tampa: 0.04, sobre: 0.044, sobre2: 0.047 };
const Y_SUP = 0.15; // base da faixa de avatares
const Y_INF = -0.33; // topo da barra de digitação
const VAO = 0.025;
const T = 4; // quadros entre duas mensagens (7,5 por segundo)

type Avatar = { fundo: string; pele: string; cabelo: string };
type Emoji = 'coracao' | 'moeda' | 'sorriso';
type Msg = { esq: boolean; w: number; h: number; linhas: number[]; emojis: Emoji[] | null; av: Avatar };

const escolher = <X,>(lista: X[], r: number) => lista[Math.floor(r * lista.length) % lista.length];
const avatar = (s: string): Avatar => ({ fundo: escolher(FUNDOS, random(s + 'f')), pele: escolher(PELES, random(s + 'p')), cabelo: escolher(CABELOS, random(s + 'c')) });

// conversa fixa (determinística) e a altura acumulada
const N = 400;
const MSGS: Msg[] = [];
const ACUM: number[] = [0];
for (let i = 0; i < N; i++) {
  const r = (k: string) => random(`familia-r10-${i}-${k}`);
  const esq = r('lado') < 0.72; // a maioria vem dos parentes
  let w: number, h: number, linhas: number[] = [], emojis: Emoji[] | null = null;
  if (r('tipo') < 0.3) {
    const n = 1 + Math.floor(r('n') * 3);
    emojis = Array.from({ length: n }, (_, k) => escolher<Emoji>(['coracao', 'coracao', 'moeda', 'sorriso'], r('e' + k)));
    w = 0.05 + n * 0.065; h = 0.085;
  } else {
    const n = r('n') < 0.6 ? 1 : 2;
    w = 0.2 + r('w') * 0.1;
    linhas = Array.from({ length: n }, (_, k) => (k === n - 1 && n > 1 ? 0.45 + r('l') * 0.35 : 1));
    h = 0.035 + n * 0.035;
  }
  MSGS.push({ esq, w, h, linhas, emojis, av: avatar(`familia-r10-av-${i}`) });
  ACUM.push(ACUM[i] + h + VAO);
}

/** Avatar redondo: fundo colorido, cabelo e rosto. */
const Rosto: React.FC<{ x: number; y: number; z: number; r: number; a: Avatar }> = ({ x, y, z, r, a }) => (
  <group position={[x, y, z]}>
    <Disco r={r} d={0.003} m={mat(a.fundo, B)} />
    <Disco r={r * 0.62} d={0.003} y={r * 0.12} z={0.0015} m={mat(a.cabelo, B)} />
    <Disco r={r * 0.46} d={0.003} y={-r * 0.1} z={0.003} m={mat(a.pele, B)} />
  </group>
);

/** Coração: quadrado a 45° + dois discos nas arestas de cima. `s` = largura total. */
const Coracao: React.FC<{ x: number; y: number; z: number; s: number }> = ({ x, y, z, s }) => {
  const m = mat(C.amarelo, 0.35), l = s / 1.53, o = l / (2 * Math.SQRT2);
  return (
    <group position={[x, y - 0.12 * l, z]}>
      <mesh rotation={[0, 0, Math.PI / 4]} material={m}><boxGeometry args={[l, l, 0.003]} /></mesh>
      <Disco r={l / 2} d={0.003} x={-o} y={o} m={m} />
      <Disco r={l / 2} d={0.003} x={o} y={o} m={m} />
    </group>
  );
};

const EmojiPeca: React.FC<{ tipo: Emoji; x: number; y: number; z: number }> = ({ tipo, x, y, z }) => {
  const r = 0.024;
  if (tipo === 'coracao') return <Coracao x={x} y={y} z={z} s={0.052} />;
  if (tipo === 'moeda') return (
    <group position={[x, y, z]}>
      <Disco r={r} d={0.003} m={mat(C.ouro, 0.3)} />
      <Disco r={r * 0.6} d={0.003} z={0.002} m={mat(C.ouroBorda, 0.2)} />
      <Disco r={r * 0.4} d={0.003} z={0.004} m={mat(C.ouro, 0.3)} />
    </group>
  );
  return (
    <group position={[x, y, z]}>
      <Disco r={r} d={0.003} m={mat(C.amarelo, 0.3)} />
      <Disco r={r * 0.2} d={0.003} x={-r * 0.38} y={r * 0.25} z={0.002} m={mat(C.olho)} />
      <Disco r={r * 0.2} d={0.003} x={r * 0.38} y={r * 0.25} z={0.002} m={mat(C.olho)} />
      <mesh position={[0, -r * 0.08, 0.002]} rotation={[0, 0, Math.PI]} material={mat(C.olho)}><torusGeometry args={[r * 0.5, r * 0.14, 6, 16, Math.PI]} /></mesh>
    </group>
  );
};

/** Balão da conversa com a base em `y`. */
const Balao: React.FC<{ m: Msg; y: number }> = ({ m, y }) => {
  const cx = m.esq ? -0.158 + m.w / 2 : 0.205 - m.w / 2;
  const cor = mat(m.esq ? C.parente : C.voce, B);
  const zc = Z.conteudo - Z.balao;
  const x0 = -m.w / 2 + 0.028;
  return (
    <group>
      {m.esq && <Rosto x={-0.192} y={y + 0.026} z={Z.balao} r={0.024} a={m.av} />}
      <group position={[cx, y + m.h / 2, Z.balao]}>
        <Ret w={m.w} h={m.h} d={0.004} r={0.028} m={cor} />
        {m.emojis
          ? m.emojis.map((e, k) => <EmojiPeca key={k} tipo={e} x={-m.w / 2 + 0.057 + k * 0.065} y={0} z={zc} />)
          : m.linhas.map((f, k) => {
            const lw = f * (m.w - 0.056);
            const ly = (m.linhas.length - 1) * 0.0175 - k * 0.035;
            return <mesh key={k} position={[x0 + lw / 2, ly, zc]} material={mat(C.branco, B)}><boxGeometry args={[lw, 0.02, 0.003]} /></mesh>;
          })}
      </group>
    </group>
  );
};

// título "FAMÍLIA" em maiúsculas de traço redondo (grade: altura da letra = 1)
type Seg = [number, number, number, number];
const LETRAS: { w: number; s: Seg[] }[] = [
  { w: 0.5, s: [[0, 0, 0, 1], [0, 1, 0.5, 1], [0, 0.52, 0.4, 0.52]] }, // F
  { w: 0.6, s: [[0, 0, 0.3, 1], [0.3, 1, 0.6, 0], [0.13, 0.38, 0.47, 0.38]] }, // A
  { w: 0.7, s: [[0, 0, 0, 1], [0, 1, 0.35, 0.38], [0.35, 0.38, 0.7, 1], [0.7, 1, 0.7, 0]] }, // M
  { w: 0.2, s: [[0, 0, 0, 1], [0.04, 1.35, 0.2, 1.62]] }, // Í (acento bem separado da haste)
  { w: 0.45, s: [[0, 0, 0, 1], [0, 0, 0.45, 0]] }, // L
  { w: 0, s: [[0, 0, 0, 1]] }, // I
  { w: 0.6, s: [[0, 0, 0.3, 1], [0.3, 1, 0.6, 0], [0.13, 0.38, 0.47, 0.38]] }, // A
];
const ESP = 0.34; // espaço entre letras
const LARG = LETRAS.reduce((s, l) => s + l.w + ESP, -ESP);

const Titulo: React.FC<{ x: number; y: number; z: number; alt: number }> = ({ x, y, z, alt }) => {
  const m = mat(C.branco, 0.4);
  let cursor = 0;
  return (
    <group position={[x, y, z]}>
      {LETRAS.flatMap((l, i) => {
        const x0 = cursor; cursor += l.w + ESP;
        return l.s.map(([ax, ay, bx, by], k) => (
          <Traco key={`${i}-${k}`} a={[(x0 + ax) * alt, ay * alt]} b={[(x0 + bx) * alt, by * alt]} e={0.013} m={m} />
        ));
      })}
    </group>
  );
};

const VOO_DUR = 36; // quadros de voo
const VOO_CAD = 18; // cada faixa solta um balão a cada 18 quadros
const VOO_VEL = 0.014; // m por quadro, reto para cima
const FAIXAS = [-0.16, 0, 0.16];

/** Balão que escapa pelo topo do celular: sobe reto, com rastro curto e chapado embaixo. */
const BalaoVoando: React.FC<{ faixa: number; n: number; q: number }> = ({ faixa, n, q }) => {
  const q0 = n * VOO_CAD + faixa * 6; // as faixas se alternam (nunca dois lado a lado na mesma altura)
  const t = q - q0;
  if (t <= 0 || t >= VOO_DUR) return null;
  const r = (k: string) => random(`familia-r10-voa-${faixa}-${n}-${k}`);
  const esc = suave(t / 5) * (1 - suave((t - VOO_DUR + 6) / 6));
  const y = 0.56 + t * VOO_VEL;
  const esq = r('lado') < 0.6;
  return (
    <group position={[FAIXAS[faixa], y, 0.02]} scale={esc}>
      {/* rastro: dois blocos chapados, mais claros, colados embaixo */}
      <Ret w={0.06} h={0.05} d={0.004} r={0.02} y={-0.055} z={-0.004} m={mat(C.rastro, B)} />
      <Ret w={0.036} h={0.045} d={0.004} r={0.014} y={-0.09} z={-0.004} m={mat(C.rastro, B)} />
      <Ret w={0.13} h={0.075} d={0.01} r={0.03} m={mat(esq ? C.parente : C.voce, B)} sombra />
      <Rosto x={-0.032} y={0} z={0.007} r={0.024} a={avatar(`familia-r10-voa-av-${faixa}-${n}`)} />
      {r('tipo') < 0.5
        ? <Coracao x={0.032} y={0} z={0.007} s={0.048} />
        : <EmojiPeca tipo="moeda" x={0.032} y={0} z={0.007} />}
    </group>
  );
};

/** Suporte de mesa ampliado: base no chão, lábio na frente e encosto inclinado atrás. */
const Suporte: React.FC = () => (
  <group>
    <Caixa p={[0, 0.02, -0.08]} t={[0.48, 0.04, 0.36]} m={mat(C.suporte)} />
    <Caixa p={[0, 0.06, 0.07]} t={[0.48, 0.08, 0.05]} m={mat(C.suporteEsc)} />
    <mesh position={[0, 0.27, -0.2]} rotation={[0.335, 0, 0]} material={mat(C.suporte)} castShadow receiveShadow><boxGeometry args={[0.3, 0.5, 0.035]} /></mesh>
  </group>
);

export const GrupoFamilia: React.FC<{
  quadro: number;
  /** ponto do chão sob o celular */ pos?: V3;
  /** giro em Y (rad); o padrão vira a tela um pouco para a câmera */ giro?: number;
  /** escala do conjunto (1 = celular de 1 m) */ escala?: number;
  /** balões escapando pelo topo */ voando?: boolean;
  /** parede + piso lisos atrás (esconde o fundo do palco) */ palco?: boolean;
}> = ({ quadro, pos = [0.68, 0, 0.5], giro = -0.22, escala = 1, voando = true, palco = true }) => {
  const q = Math.max(0, quadro);

  // conversa aos saltos: a mensagem k chega no quadro k*T e a pilha sobe de uma vez
  const K0 = 6;
  const k = K0 + (Math.floor(q / T) % (N - K0 - 10));
  const visiveis: { i: number; y: number }[] = [];
  for (let i = k; i >= 0; i--) {
    const y = Y_INF + VAO + (ACUM[k + 1] - ACUM[i + 1]);
    if (y > Y_SUP) break;
    visiveis.push({ i, y });
  }

  // faixa de membros: 3 fileiras desencontradas (10 + 9 + 10 = 29 avatares)
  const membros: { x: number; y: number; a: Avatar }[] = [];
  [0.258, 0.22, 0.182].forEach((y, f) => {
    const n = f === 1 ? 9 : 10;
    for (let c = 0; c < n; c++) membros.push({ x: (c - (n - 1) / 2) * 0.042, y, a: avatar(`familia-r10-membro-${f}-${c}`) });
  });

  const xTit = -(LARG * 0.062 + 0.03 + 0.055) / 2;

  return (
    <>
      {palco && (
        <group>
          {/* palco liso: parede, rodapé e piso (2,2 cm acima das linhas da quadra) */}
          <Caixa p={[0, 2.5, -3.3]} t={[16, 5, 0.2]} m={mat(C.parede)} sombra={false} />
          <Caixa p={[0, 0.07, -3.17]} t={[16, 0.14, 0.08]} m={mat(C.rodape)} sombra={false} />
          <Caixa p={[0, 0.011, 0.5]} t={[16, 0.022, 7.8]} m={mat(C.piso)} sombra={false} />
        </group>
      )}
      <group position={[pos[0], pos[1] + (palco ? 0.022 : 0), pos[2]]} rotation={[0, giro, 0]} scale={escala}>
        <Suporte />
        {/* celular: inclinado 10° para trás, apoiado na base atrás do lábio */}
        <group position={[0, 0.04, 0.02]} rotation={[-0.175, 0, 0]}>
          <group position={[0, 0.5, 0]}>
            {/* corpo, borda clara e botões */}
            <Ret w={0.5} h={1.0} d={0.05} r={0.06} m={mat(C.corpo)} sombra />
            <Ret w={0.508} h={1.008} d={0.03} r={0.064} z={-0.005} m={mat(C.borda)} />
            <Caixa p={[0.256, 0.25, 0]} t={[0.016, 0.12, 0.03]} m={mat(C.borda)} />
            <Caixa p={[0.256, 0.1, 0]} t={[0.016, 0.08, 0.03]} m={mat(C.borda)} />
            {/* câmera frontal na borda de cima */}
            <Disco r={0.011} d={0.004} y={0.474} z={0.026} m={mat(C.lente)} />
            <Ret w={W} h={0.9} d={0.004} r={0.035} z={Z.tela} m={mat(C.tela, B)} />

            {visiveis.map(({ i, y }) => <Balao key={i} m={MSGS[i]} y={y} />)}

            {/* cabeçalho verde com o título e o coração */}
            <Ret w={W} h={0.16} d={0.004} r={0.035} y={0.37} z={Z.tampa} m={mat(C.topo, B)} />
            <Caixa p={[0, 0.31, Z.tampa]} t={[W, 0.04, 0.004]} m={mat(C.topo, B)} sombra={false} />
            <Titulo x={xTit} y={0.317} z={Z.sobre} alt={0.062} />
            <Coracao x={xTit + LARG * 0.062 + 0.03 + 0.0275} y={0.35} z={Z.sobre} s={0.055} />

            {/* faixa de membros (dezenas de avatares) */}
            <Caixa p={[0, 0.22, Z.tampa]} t={[W, 0.14, 0.004]} m={mat(C.faixa, B)} sombra={false} />
            {membros.map((m, n) => <Rosto key={n} x={m.x} y={m.y} z={Z.sobre + (n % 2) * 0.0015} r={0.018} a={m.a} />)}

            {/* barra de digitação e botão de enviar */}
            <Ret w={W} h={0.12} d={0.004} r={0.035} y={-0.39} z={Z.tampa} m={mat(C.barra, B)} />
            <Caixa p={[0, -0.35, Z.tampa]} t={[W, 0.04, 0.004]} m={mat(C.barra, B)} sombra={false} />
            <Ret w={0.3} h={0.064} d={0.003} r={0.032} x={-0.055} y={-0.39} z={Z.sobre} m={mat(C.branco, B)} />
            <Disco r={0.036} d={0.003} x={0.165} y={-0.39} z={Z.sobre} m={mat(C.topo, B)} />
            <mesh position={[0.168, -0.39, Z.sobre2]} rotation={[Math.PI / 2, 0, -Math.PI / 2]} material={mat(C.branco, B)}><cylinderGeometry args={[0.02, 0.02, 0.003, 3]} /></mesh>

            {voando && FAIXAS.flatMap((_, f) => {
              const n0 = Math.floor((q - f * 6) / VOO_CAD);
              return [n0, n0 - 1, n0 - 2].map((n) => <BalaoVoando key={`${f}-${n}`} faixa={f} n={n} q={q} />);
            })}
          </group>
        </group>
      </group>
    </>
  );
};
