// Primitivas em metros; materiais compartilhados por cor e acabamento.
import React from 'react';
import * as THREE from 'three';

export type V3 = [number, number, number];
type Acabamento = { brilho?: number; opacidade?: number; verso?: boolean; duplo?: boolean };

const cache = new Map<string, THREE.MeshStandardMaterial>();
export const mat = (cor: string, { brilho = 0, opacidade = 1, verso = false, duplo = false }: Acabamento = {}) => {
  const chave = [cor, brilho, opacidade, verso, duplo].join('|');
  let material = cache.get(chave);
  if (!material) {
    material = new THREE.MeshStandardMaterial({
      color: cor, roughness: 0.85,
      emissive: cor, emissiveIntensity: brilho,
      transparent: opacidade < 1, opacity: opacidade, depthWrite: opacidade === 1,
      side: verso ? THREE.BackSide : duplo ? THREE.DoubleSide : THREE.FrontSide,
    });
    cache.set(chave, material);
  }
  return material;
};

export const Caixa: React.FC<{ p: V3; t: V3; cor: string; giro?: V3; brilho?: number }> = ({ p, t, cor, giro, brilho = 0 }) => (
  <mesh position={p} rotation={giro} material={mat(cor, { brilho })}>
    <boxGeometry args={t} />
  </mesh>
);

export const Capsula: React.FC<{
  p: V3; raio: number; comp: number; cor: string; giro?: V3;
  brilho?: number; opacidade?: number; sombra?: boolean; ordem?: number;
}> = ({ p, raio, comp, cor, giro, brilho = 0, opacidade = 1, sombra = true, ordem = 0 }) => (
  <mesh position={p} rotation={giro} material={mat(cor, { brilho, opacidade })}
    castShadow={sombra} receiveShadow={sombra} renderOrder={ordem}>
    <capsuleGeometry args={[raio, comp, 6, 16]} />
  </mesh>
);
