// Base do lote r14-objeto: cache de material por cor, retângulo de cantos redondos, disco, traços (caixas juntadas) e o giro "deitado".
import * as THREE from 'three';
import React from 'react';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';

const cache = new Map<string, THREE.MeshStandardMaterial>();
/** Material chapado (roughness 0.85). `brilho` > 0 acende a cor; `metal` dá um toque metálico. */
export const mat = (cor: string, o: { brilho?: number; rug?: number; metal?: number } = {}) => {
  const { brilho = 0, rug = 0.85, metal = 0 } = o;
  const k = [cor, brilho, rug, metal].join('|');
  let m = cache.get(k);
  if (!m) {
    m = new THREE.MeshStandardMaterial({ color: cor, roughness: rug, metalness: metal });
    if (brilho > 0) { m.emissive = new THREE.Color(cor); m.emissiveIntensity = brilho; }
    cache.set(k, m);
  }
  return m;
};

/** Retângulo de cantos arredondados no plano XY, espessura d em Z: 2 caixas em cruz + 4 cilindros. */
/** `recebe` = false: não recebe sombra (evita a "acne" da sombra do sol nas bordas finas). */
export const Ret: React.FC<{ w: number; h: number; d: number; r: number; x?: number; y?: number; z: number; m: THREE.Material; sombra?: boolean; recebe?: boolean }> = ({ w, h, d, r, x = 0, y = 0, z, m, sombra = false, recebe = true }) => (
  <group position={[x, y, z]}>
    <mesh material={m} castShadow={sombra} receiveShadow={recebe}><boxGeometry args={[w - 2 * r, h, d]} /></mesh>
    <mesh material={m} castShadow={sombra} receiveShadow={recebe}><boxGeometry args={[w, h - 2 * r, d]} /></mesh>
    {([[-1, -1], [1, -1], [-1, 1], [1, 1]] as const).map(([sx, sy]) => (
      <mesh key={`${sx}${sy}`} position={[sx * (w / 2 - r), sy * (h / 2 - r), 0]} rotation={[Math.PI / 2, 0, 0]} material={m} castShadow={sombra} receiveShadow={recebe}>
        <cylinderGeometry args={[r, r, d, 16]} />
      </mesh>
    ))}
  </group>
);

/** Disco de frente para +Z (cilindro deitado), raio r e espessura d. */
export const Disco: React.FC<{ r: number; d: number; x: number; y: number; z: number; m: THREE.Material }> = ({ r, d, x, y, z, m }) => (
  <mesh position={[x, y, z]} rotation={[Math.PI / 2, 0, 0]} material={m} receiveShadow><cylinderGeometry args={[r, r, d, 40]} /></mesh>
);

/** Traço 2D: segmento (x1,y1)→(x2,y2) no plano XY. */
export type Traco = [number, number, number, number];

/** Junta muitos traços (caixas) numa geometria só: 1 mesh por cor. */
const geoTracos = (tracos: Traco[], l: number, d: number) => {
  const partes = tracos.map(([x1, y1, x2, y2]) => {
    const dx = x2 - x1, dy = y2 - y1;
    const g = new THREE.BoxGeometry(Math.hypot(dx, dy), l, d);
    g.rotateZ(Math.atan2(dy, dx));
    g.translate((x1 + x2) / 2, (y1 + y2) / 2, 0);
    return g;
  });
  return mergeGeometries(partes)!;
};

export const Tracos: React.FC<{ tracos: Traco[]; l: number; d?: number; z: number; m: THREE.Material }> = ({ tracos, l, d = 0.0004, z, m }) => {
  const geo = React.useMemo(() => geoTracos(tracos, l, d), [tracos, l, d]);
  return <mesh geometry={geo} position={[0, 0, z]} material={m} receiveShadow />;
};

/** Em pé (frente +Z, base em y = 0) ou deitado com a frente para cima, centrado na origem. `alto` = altura da peça em pé. */
export const Deitavel: React.FC<{ deitada: boolean; alto: number; children: React.ReactNode }> = ({ deitada, alto, children }) =>
  deitada
    ? <group position={[0, 0, alto / 2]} rotation={[-Math.PI / 2, 0, 0]}>{children}</group>
    : <group>{children}</group>;
