import React from 'react';
import { Caixa, mat, Triangulo } from './base';

const AZUL = '#193dc4';
const ESCURO = '#10245f';
const INTERIOR = '#0a1639';
const AMARELO = '#ffdb35';

const Estrela: React.FC<{ x: number; y: number; raio: number; giro?: number }> = ({ x, y, raio, giro = 0 }) => {
  const miolo = raio * 0.46;
  const base = miolo * Math.cos(Math.PI / 5);
  const altura = raio - base;
  const largura = 2 * miolo * Math.sin(Math.PI / 5);
  return (
    <group position={[x, y, 0.0082]} rotation={[0, 0, giro]}>
      <mesh rotation={[Math.PI / 2, 0, 0]} material={mat(AMARELO)} castShadow receiveShadow>
        <cylinderGeometry args={[miolo, miolo, 0.0014, 5]} />
      </mesh>
      {Array.from({ length: 5 }, (_, i) => (
        <group key={i} rotation={[0, 0, i * Math.PI * 2 / 5]}>
          <group position={[0, base + altura / 3, 0]}>
            <Triangulo largura={largura} altura={altura} espessura={0.0014} cor={AMARELO} />
          </group>
        </group>
      ))}
    </group>
  );
};

// Envelope de 8 × 12 cm; laterais fechadas, centro estufado e boca vazada.
export const PacoteFigurinhas: React.FC = () => (
  <group>
    <Caixa p={[0, 0.051, 0.006]} t={[0.08, 0.074, 0.002]} cor={AZUL} />
    <Caixa p={[0, 0.054, -0.008]} t={[0.08, 0.08, 0.002]} cor={INTERIOR} />
    <Caixa p={[0, 0.003, 0]} t={[0.08, 0.006, 0.012]} cor={ESCURO} />
    {/* A faixa frontal vira para dentro no fundo, em vez de acabar reta. */}
    <Caixa p={[0, 0.0098, 0.0048]} t={[0.08, 0.009, 0.002]} r={[0.28, 0, 0]} cor={AZUL} />
    <Caixa p={[0, 0.010, -0.0048]} t={[0.08, 0.01, 0.002]} r={[-0.30, 0, 0]} cor={ESCURO} />
    {([-1, 1] as const).map((lado) => (
      <Caixa key={lado} p={[lado * 0.0385, 0.049, -0.001]} t={[0.003, 0.086, 0.014]} cor={ESCURO} />
    ))}

    {/* Três recortes grandes na frente; alturas desiguais expõem a abertura. */}
    {[
      { x: -0.024, largura: 0.032, altura: 0.023, dobra: 0.32 },
      { x: 0.006, largura: 0.028, altura: 0.008, dobra: -0.15 },
      { x: 0.030, largura: 0.020, altura: 0.015, dobra: 0.12 },
    ].map(({ x, largura, altura, dobra }) => (
      <group key={x} position={[x, 0.088, 0.006]} rotation={[dobra, 0, 0]}>
        <group position={[0, altura / 3, 0]}>
          <Triangulo largura={largura} altura={altura} espessura={0.002} cor={AZUL} />
        </group>
      </group>
    ))}
    {/* O verso termina mais alto: o vão escuro fica visível pela frente e por cima. */}
    {[
      { x: -0.022, largura: 0.036, altura: 0.012 },
      { x: 0.018, largura: 0.044, altura: 0.026 },
    ].map(({ x, largura, altura }) => (
      <group key={x} position={[x, 0.094 + altura / 3, -0.008]}>
        <Triangulo largura={largura} altura={altura} espessura={0.002} cor={INTERIOR} />
      </group>
    ))}

    <Estrela x={0} y={0.053} raio={0.025} />
    <Estrela x={-0.026} y={0.077} raio={0.009} giro={0.15} />
    <Estrela x={0.026} y={0.079} raio={0.009} giro={-0.20} />
    <Estrela x={-0.026} y={0.023} raio={0.009} giro={0.25} />
    <Estrela x={0.026} y={0.023} raio={0.009} giro={-0.10} />
  </group>
);
