import React from 'react';
import { Caixa, Cilindro } from './base';

const CINZA = '#888888';
const PRETO = '#000000';

/** Poste de 3 m, uma base e mostrador voltado para +Z às 7h00. */
export const RelogioDeRua: React.FC = () => (
  <group>
    <Cilindro p={[0, 0.06, 0]} raio={0.17} altura={0.12} cor={CINZA} />
    <Cilindro p={[0, 1.55, 0]} raio={0.065} altura={2.90} cor={CINZA} />
    <group position={[0, 3, 0]}>
      <Cilindro p={[0, 0, 0]} raio={0.48} altura={0.18} cor={CINZA} frente />
      {/* A própria carcaça forma um aro contínuo, sem toros sobrepostos. */}
      <Cilindro p={[0, 0, 0.11]} raio={0.42} altura={0.08} cor="#ffffff" frente />
      {Array.from({ length: 12 }, (_, i) => {
        const angulo = i * Math.PI / 6;
        return (
          <Caixa key={i} p={[0.32 * Math.sin(angulo), 0.32 * Math.cos(angulo), 0.19]}
            t={[0.08, i % 3 === 0 ? 0.12 : 0.08, 0.04]} giro={-angulo} cor={PRETO} sombra={false} />
        );
      })}
      {/* Cada camada tem 2 cm livres até a próxima. */}
      <Caixa p={[0, 0.135, 0.25]} t={[0.08, 0.27, 0.04]} cor={PRETO} sombra={false} />
      <group rotation={[0, 0, -7 * Math.PI / 6]}>
        <Caixa p={[0, 0.10, 0.31]} t={[0.08, 0.20, 0.04]} cor={PRETO} sombra={false} />
      </group>
      <Cilindro p={[0, 0, 0.37]} raio={0.055} altura={0.04} cor={PRETO} frente sombra={false} />
    </group>
  </group>
);
