// Só na VitrineLote (padrão r12/r17/r18): câmera própria, sem desfoque, e a montagem de cada plano.
// calendario: numa parede de verdade, na altura do olho, com prego. volanteLoteria: deitado numa mesa, visto do
// ponto de vista do Téo (uma mão prende o cartão pela faixa do trevo, a outra marca com a caneta).
// pilhaMoedas: num tampo azul-ardósia, close baixo. Fora da vitrine, o componente puro.
// As montagens ficam a 3 m da origem (dentro da área de sombra do sol do palco).
import React, { useLayoutEffect } from 'react';
import * as THREE from 'three';
import { useThree } from '@react-three/fiber';
import { useVideoConfig } from 'remotion';
import { Boneco } from '../../../kit/Boneco';
import { ELENCO } from '../../../kit/elenco';
import { BASE, type Juntas } from '../../../kit/poses';
import { ikBraco } from '../r05-acao/acoes';
import { Caixa, Cil, R, mat, type V3 } from './base';
import { CAL, Calendario } from './Calendario';
import { CASA, Caneta, NA_CANETA, VOL, VolanteLoteria, casaDe } from './VolanteLoteria';
import { PilhaMoedas } from './PilhaMoedas';

// ── volante na mesa (espaço do boneco, giro 0: o Téo olha para +Z, mesa à frente com tampo a 75 cm) ──
const MAO_R = 0.072; // raio da mão-esfera do kit
const DEDO_R = 0.012;
export const MESA_Y = 0.75;
/** Base (meio da borda de baixo) do cartão deitado na mesa: o topo aponta para longe do Téo, a face para cima. */
export const CARTAO_BASE: V3 = [0, MESA_Y + 0.001, 0.31];
const qCartao = new THREE.Quaternion().setFromEuler(new THREE.Euler(-Math.PI / 2, Math.PI, 0, 'YXZ'));
/** Ponto no espaço do cartão → espaço do boneco: (x, y, z) vira (−x, z, y) a partir da base. */
const doCartao = (x: number, y: number, z: number) => new THREE.Vector3(CARTAO_BASE[0] - x, CARTAO_BASE[1] + z, CARTAO_BASE[2] + y);

// mão que prende (lado +1, à esquerda da tela): apoiada na mesa ao lado da faixa do trevo, polegar por cima da faixa
const MAO_PRENDE = doCartao(-VOL.larg / 2 - 0.06, 0.045, MAO_R - 0.001);
const POLEGAR_PRENDE = doCartao(-0.088, 0.03, 0.0016 + DEDO_R + 0.0004);

// caneta: ponta no canto de baixo à direita da casa NA_CANETA (fora dos dígitos)
const [cx, cy] = casaDe(NA_CANETA);
const PONTA = doCartao(cx + CASA.larg / 2 - 0.0035, cy - CASA.alt / 2 + 0.005, 0.0022);
// mão da caneta (lado −1, à direita da tela): apoiada na mesa, abaixo e à direita da ponta, fora do cartão
const MAO_CANETA = new THREE.Vector3(-0.175, MESA_Y + MAO_R, 0.235);
/** Eixo da caneta: da ponta para um ponto acima da mão, subindo até a caneta passar por cima da esfera (sem entrar nela). */
const EIXO = (() => {
  const folga = MAO_R + 0.0066 + 0.002;
  const dist = (k: number) => {
    const u = MAO_CANETA.clone().add(new THREE.Vector3(0, k, 0)).sub(PONTA).normalize();
    return new THREE.Vector3().crossVectors(MAO_CANETA.clone().sub(PONTA), u).length();
  };
  let a = 0, b = 0.3; // bissecção: a distância cresce com k
  for (let i = 0; i < 40; i++) { const m = (a + b) / 2; if (dist(m) < folga) a = m; else b = m; }
  return MAO_CANETA.clone().add(new THREE.Vector3(0, b, 0)).sub(PONTA).normalize();
})();
// dedos em pinça no fim da empunhadura (4,8 cm da ponta), um de cada lado da caneta: vista de cima, a caneta
// aparece entre eles, e a ponta e os números ficam livres
const PEGA = PONTA.clone().addScaledVector(EIXO, 0.048);
const CIMA = new THREE.Vector3(0, 1, 0).addScaledVector(EIXO, -EIXO.y).normalize();
const LADO = new THREE.Vector3().crossVectors(EIXO, CIMA).normalize();
const encosta = 0.0066 + DEDO_R + 0.0003;
const INDICADOR = PEGA.clone().addScaledVector(LADO, encosta).addScaledVector(CIMA, 0.004);
const POLEGAR_CANETA = PEGA.clone().addScaledVector(LADO, -encosta).addScaledVector(CIMA, 0.004).addScaledVector(EIXO, 0.01);

const bP = ikBraco(1, MAO_PRENDE.toArray() as V3), bC = ikBraco(-1, MAO_CANETA.toArray() as V3);
export const POSE_VOLANTE: Juntas = {
  // cabeça um pouco para trás: abre espaço para a câmera entre o queixo e a mesa
  ...BASE, cabecaX: -15,
  ombroDX: bP.x, ombroDZ: bP.z, cotoveloD: bP.cot,
  ombroEX: bC.x, ombroEZ: bC.z, cotoveloE: bC.cot,
};

const pele = () => mat(ELENCO.teo.pele, 0.82);
/** Dedo: cápsula cor de pele que sai de dentro da mão (a 2/3 do raio) e termina com a ponta em `ponta`. */
const Dedo: React.FC<{ mao: THREE.Vector3; ponta: THREE.Vector3 }> = ({ mao, ponta }) => {
  const dir = ponta.clone().sub(mao).normalize();
  const ini = mao.clone().addScaledVector(dir, MAO_R * 0.66);
  const comp = Math.max(0.001, ini.distanceTo(ponta));
  const meio = ini.clone().add(ponta).multiplyScalar(0.5);
  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  return (
    <mesh position={meio.toArray()} quaternion={q} material={pele()} castShadow receiveShadow>
      <capsuleGeometry args={[DEDO_R, comp, 8, 16]} />
    </mesh>
  );
};

/** Cartão deitado + caneta + dedos, para o boneco em POSE_VOLANTE atrás de uma mesa de 75 cm (espaço do boneco). */
export const VolanteNaMesa: React.FC = () => {
  const qCaneta = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), EIXO);
  return (
    <>
      <group position={CARTAO_BASE} quaternion={qCartao}><VolanteLoteria /></group>
      <group position={PONTA.toArray()} quaternion={qCaneta}><Caneta /></group>
      <Dedo mao={MAO_PRENDE} ponta={POLEGAR_PRENDE} />
      <Dedo mao={MAO_CANETA} ponta={INDICADOR} />
      <Dedo mao={MAO_CANETA} ponta={POLEGAR_CANETA} />
    </>
  );
};

// ── câmera ─────────────────────────────────────────────────────────────────
/** alvo: centro do quadro (mundo); altura: altura do quadro no alvo (m); elev/azim em graus (+azim = câmera para +X). */
type Plano = { alvo: V3; altura: number; dist: number; elev: number; azim: number };

const AjustarCamera: React.FC<{ p: Plano }> = ({ p }) => {
  const camera = useThree((s) => s.camera) as THREE.PerspectiveCamera;
  // roda depois da <Camera> do palco (que vem antes na árvore), a cada quadro
  useLayoutEffect(() => {
    const e = R(p.elev), a = R(p.azim), h = p.dist * Math.cos(e);
    camera.position.set(p.alvo[0] + h * Math.sin(a), p.alvo[1] + p.dist * Math.sin(e), p.alvo[2] + h * Math.cos(a));
    camera.lookAt(...p.alvo);
    camera.fov = 2 * THREE.MathUtils.radToDeg(Math.atan(p.altura / 2 / p.dist));
    camera.near = Math.min(0.3, p.dist * 0.4);
    camera.updateProjectionMatrix();
    camera.updateMatrixWorld();
  });
  return null;
};

// Sem desfoque: plano invisível a 2,1 m da câmera (o foco da vitrine) entra só no passe de profundidade do bokeh.
const geoFoco = new THREE.PlaneGeometry(80, 80);
const matFoco = new THREE.MeshBasicMaterial({ colorWrite: false, depthWrite: false });
const SemDesfoque: React.FC = () => {
  const camera = useThree((s) => s.camera);
  const ref = React.useRef<THREE.Mesh>(null);
  useLayoutEffect(() => {
    const m = ref.current; if (!m) return;
    m.quaternion.copy(camera.quaternion);
    m.position.copy(camera.position).add(new THREE.Vector3(0, 0, -2.1).applyQuaternion(camera.quaternion));
    m.updateMatrixWorld();
  });
  return <mesh ref={ref} geometry={geoFoco} material={matFoco} frustumCulled={false} />;
};

// ── montagens da vitrine (coordenadas do mundo) ───────────────────────────
const PAREDE: V3 = [3, 0, -1.5]; // face da parede em z = -1,5
const CAL_Y = 1.3; // base do calendário: o centro fica a 1,55 m (altura do olho)
const MESA: V3 = [3, 0, 3]; // tampo a 75 cm
const TEO: V3 = [-3, 0, 0];

/** Mesa simples: tampo de 4 cm com a face de cima em MESA_Y e 4 pés. */
const Mesa: React.FC<{ p: V3; larg: number; prof: number; cor: string; pe: string }> = ({ p, larg, prof, cor, pe }) => (
  <group position={p}>
    <Caixa p={[0, MESA_Y - 0.02, 0]} t={[larg, 0.04, prof]} cor={cor} />
    {([[-1, -1], [1, -1], [-1, 1], [1, 1]] as const).map(([a, b]) => (
      <Caixa key={`${a}${b}`} p={[a * (larg / 2 - 0.08), (MESA_Y - 0.04) / 2, b * (prof / 2 - 0.08)]} t={[0.08, MESA_Y - 0.04, 0.08]} cor={pe} />
    ))}
  </group>
);

const MONTAGENS = {
  calendario: {
    plano: { alvo: [PAREDE[0] + 0.02, CAL_Y + 0.26, PAREDE[2]], altura: 0.66, dist: 1.9, elev: 2, azim: 10 },
    Cena: () => (
      <group position={PAREDE}>
        {/* parede verde-água clara com rodapé, e o prego */}
        <Caixa p={[0, 1.4, -0.06]} t={[4, 2.8, 0.12]} cor="#b7ddd5" />
        <Caixa p={[0, 0.06, 0.02]} t={[4, 0.12, 0.04]} cor="#e9e4d8" />
        <Cil p={[0, CAL_Y + CAL.alt + 0.026, 0.02]} raio={0.0025} h={0.04} r={[Math.PI / 2, 0, 0]} cor="#6b6f76" />
        <Cil p={[0, CAL_Y + CAL.alt + 0.026, 0.04]} raio={0.0055} h={0.003} r={[Math.PI / 2, 0, 0]} cor="#6b6f76" />
        {/* o calendário fica 2 cm à frente da parede (apoiado no prego): a sombra aparece na parede */}
        <group position={[0, CAL_Y, 0.02]}><Calendario /></group>
      </group>
    ),
  },
  volanteLoteria: {
    // ponto de vista do Téo: câmera entre o queixo e a mesa, 78° de cima, olhando o cartão (que fica de pé para ela).
    // A 0,5 m, as mãos (mais perto da lente) não crescem demais; a borda de baixo do quadro cai na beira da mesa.
    plano: { alvo: [TEO[0], MESA_Y + 0.01, 0.37], altura: 0.3, dist: 0.5, elev: 78, azim: 180 },
    Cena: () => (
      <group position={TEO}>
        <Boneco v={ELENCO.teo} j={POSE_VOLANTE} e={{ boca: 'sorriso', olharY: -1 }} />
        <Mesa p={[0, 0, 0.71]} larg={1.4} prof={1.0} cor="#d6a36a" pe="#a8703f" />
        <VolanteNaMesa />
      </group>
    ),
  },
  pilhaMoedas: {
    plano: { alvo: [MESA[0], MESA_Y + 0.017, MESA[2]], altura: 0.085, dist: 0.55, elev: 14, azim: 10 },
    Cena: () => (
      <group position={MESA}>
        {/* tampo azul-ardósia: frio, para o dourado saltar */}
        <Mesa p={[0, 0, -0.2]} larg={1.6} prof={1.2} cor="#4f7286" pe="#3a5464" />
        <group position={[0, MESA_Y, 0]}><PilhaMoedas /></group>
      </group>
    ),
  },
} satisfies Record<string, { plano: Plano; Cena: React.FC }>;

export function apresentar(Componente: React.FC, nome: keyof typeof MONTAGENS, apoio: 'chao' | 'mesa'): React.FC {
  return function PecaNaVitrine() {
    const { id } = useVideoConfig();
    if (id !== 'VitrineLote') return <Componente />;
    const { plano, Cena } = MONTAGENS[nome];
    return (
      <>
        <AjustarCamera p={plano} />
        {/* a vitrine põe o objeto em x = 0,75 (e no pedestal de 75 cm se 'mesa'): desfaz para montar no mundo */}
        <group position={[-0.75, apoio === 'mesa' ? -0.75 : 0, 0]}><Cena /></group>
        <SemDesfoque />
      </>
    );
  };
}
