// Planície de gelo à noite: chão em grade regular de blocos de 1 m (branco e azul-claro), montinhos de neve em bolas,
// céu azul-marinho com estrelas amarelas e névoa azul-violeta no horizonte. Sem construções. Metros, Y para cima.
import * as THREE from 'three';
import React from 'react';
import { random } from 'remotion';
import { Ceu, FaixaNevoa, Instancias, Lua, mat, type Item, type V3 } from './base';
import type { LimitesCenario } from '../tipos';

const MARINHO = '#0f1a46';
const NEVOA = '#6672c0'; // azul-violeta do horizonte: névoa, faixas de névoa e pé do céu têm a mesma cor
export const LIMITES_GELO: LimitesCenario = { limiteX: 18, limiteZ: [-28, 5], ceu: MARINHO };

const caixa = new THREE.BoxGeometry(1, 1, 1);
const bola = new THREE.SphereGeometry(1, 32, 16);
const bolinha = new THREE.SphereGeometry(1, 12, 8);

// ---------- chão: grade alinhada de blocos de 1 m, junta uniforme de 8 cm, sem sobreposição ----------
// Centros em meios metros (±0,5; ±1,5...): os pés dos personagens perto da origem caem no meio de um bloco.
const TONS = [
  { cor: '#ffffff', peso: 0.5 }, // branco-gelo
  { cor: '#ebf3fd', peso: 0.3 }, // gelo claro
  { cor: '#d3e5f8', peso: 0.2 }, // azul-claro
];
const LADO = 1, JUNTA = 0.08;
const blocos = TONS.map(() => [] as Item[]);
for (let i = 0; i < 34; i++) {
  const z = 5.5 - i * LADO;
  for (let j = 0; j < 38; j++) {
    const x = -18.5 + j * LADO;
    const s = `r04b-bloco-${i}-${j}`;
    // topo em 0, 1 ou 2 cm (a diferença some na junta); onde ficam os personagens, tudo em y = 0
    const livre = Math.abs(x) < 2.5 && z > -2 && z < 4;
    const h = livre ? 0 : Math.floor(random(`${s}-h`) * 3) * 0.01;
    let r = random(`${s}-cor`), k = 0;
    while (k < TONS.length - 1 && r > TONS[k].peso) { r -= TONS[k].peso; k++; }
    blocos[k].push({ p: [x, (h - 0.04) / 2, z], t: [LADO - JUNTA, h + 0.04, LADO - JUNTA] });
  }
}

// ---------- montinhos de neve: 1 a 4 bolas achatadas, com a base afundada no gelo ----------
// [x, z, raio da bola principal]. Bola principal com no máximo ~1,5 m de diâmetro; fora da frente livre e longe das bordas.
const MONTES: [number, number, number][] = [
  [-2.3, -1.7, 0.36], [2.5, -2.6, 0.48],
  [-4.2, -5.0, 0.6], [4.6, -5.6, 0.42], [0.6, -7.2, 0.34], [-1.6, -6.4, 0.22],
  [-6.9, -8.4, 0.72], [6.8, -9.6, 0.66], [-3.4, -11.0, 0.5], [2.6, -12.4, 0.75],
  [-9.0, -14.0, 0.7], [9.4, -15.0, 0.75], [-0.8, -16.5, 0.6], [-5.6, -19.0, 0.75], [5.4, -20.5, 0.7],
];
const NEVE = mat('#f7faff', { luz: '#c6d6ff', forca: 0.3, aspereza: 0.9 }); // emissivo frio: sombra própria suave, sem "sujar"
type Bola = { p: V3; e: V3 };
const MONTE_BOLAS: Bola[][] = MONTES.map(([, , r], i) => {
  const s = `r04b-monte-${i}`;
  const achata = 0.72 + random(`${s}-a`) * 0.16;
  const lista: Bola[] = [{ p: [0, 0.2 * r, 0], e: [r, r * achata, r] }]; // centro baixo: ~20% da bola fica sob o gelo
  const n = Math.floor(random(`${s}-n`) * 4); // 0 a 3 bolas extras
  let ang = random(`${s}-ang`) * Math.PI * 2;
  for (let k = 0; k < n; k++) {
    ang += 1.3 + random(`${s}-d${k}`) * 1.9;
    const rr = r * (0.3 + random(`${s}-r${k}`) * 0.32);
    const dist = r * (0.72 + random(`${s}-x${k}`) * 0.3);
    lista.push({ p: [Math.cos(ang) * dist, 0.1 * rr, Math.sin(ang) * dist], e: [rr, rr * 0.82, rr] });
  }
  return lista;
});
const Monte: React.FC<{ x: number; z: number; bolas: Bola[] }> = ({ x, z, bolas }) => (
  <group position={[x, 0, z]}>
    {bolas.map(({ p, e }, k) => (
      <mesh key={k} position={p} scale={e} geometry={bola} material={NEVE} castShadow receiveShadow />
    ))}
  </group>
);

// ---------- estrelas: no céu a 90 m, sorteio livre (sem grade), muitas miúdas e poucas grandes ----------
const ESTRELAS: Item[] = [];
{
  const dirs: THREE.Vector3[] = [];
  const grau = Math.PI / 180;
  for (let n = 0; n < 600 && ESTRELAS.length < 74; n++) {
    // a lateral do quadro fica a ~33° e o topo a ~12°: margem para nenhuma ser cortada
    const az = (random(`r04b-estrela-az-${n}`) - 0.5) * 58 * grau;
    const el = (2.4 + random(`r04b-estrela-el-${n}`) * 7.8) * grau;
    const d = new THREE.Vector3(Math.sin(az) * Math.cos(el), Math.sin(el), -Math.cos(az) * Math.cos(el));
    if (dirs.some((o) => o.angleTo(d) < 1.7 * grau)) continue;
    dirs.push(d);
    const t = random(`r04b-estrela-t-${n}`);
    const raio = 0.06 + t * t * t * 0.46; // de ~2 px a ~15 px no quadro
    ESTRELAS.push({ p: d.multiplyScalar(90).add(new THREE.Vector3(0, 1.8, 5.5)).toArray() as V3, t: [raio, raio, raio] });
  }
}
const matEstrela = new THREE.MeshBasicMaterial({ color: '#ffd84a', fog: false });

export const PaisagemGelada: React.FC = () => (
  <>
    {/* névoa azul-violeta (fora de grupo: vai para a cena) + duas faixas de névoa que apagam o horizonte e os montes distantes */}
    <fog attach="fog" args={[NEVOA, 11, 36]} />
    <Ceu baixo={NEVOA} alto={MARINHO} faixa={0.2} />
    <Instancias itens={ESTRELAS} geo={bolinha} m={matEstrela} recebe={false} />
    <FaixaNevoa cor={NEVOA} z={-13} altura={3.2} opaco={0.55} />
    <FaixaNevoa cor={NEVOA} z={-23} altura={6} opaco={1} />

    {/* luz fria: lua quase a pino (sombra colada aos pés), hemisfério do kit esfriado e preenchimento azul de frente */}
    <Lua dir={[-0.15, -1, -0.2]} cor="#dbe5ff" forca={2.2} area={14} maciez={3}
      hemi={{ ceu: '#8ca0e4', chao: '#dde8f7', forca: 1.2 }} />
    <directionalLight name="preenchimento-frio" position={[1, 3, 8]} color="#7f9cff" intensity={0.9} />
    <directionalLight name="contraluz" position={[4, 5, -8]} color="#94a0ff" intensity={0.4} />

    {/* fundo das juntas: um azul-claro mais fundo, 6 cm abaixo do gelo */}
    <mesh position={[0, -0.08, -12]} geometry={caixa} scale={[300, 0.04, 300]} material={mat('#c2d6ef')} receiveShadow />
    {blocos.map((itens, k) => <Instancias key={k} itens={itens} geo={caixa} m={mat(TONS[k].cor)} />)}
    {MONTES.map(([x, z], i) => <Monte key={i} x={x} z={z} bolas={MONTE_BOLAS[i]} />)}
  </>
);
