// Base do lote r16-objeto: cache de material por cor e primitivas posicionadas (caixa, cilindro, haste).
import * as THREE from 'three';
import React from 'react';

const cache = new Map<string, THREE.MeshStandardMaterial>();
/** Material chapado (roughness 0.85 por padrão), um por cor+rugosidade. */
export const mat = (cor: string, rug = 0.85) => {
  const k = `${cor}|${rug}`;
  let m = cache.get(k);
  if (!m) { m = new THREE.MeshStandardMaterial({ color: cor, roughness: rug }); cache.set(k, m); }
  return m;
};

export type V3 = [number, number, number];
type Sombra = { sombra?: boolean; recebe?: boolean };

export const Caixa: React.FC<{ p: V3; t: V3; cor: string; r?: V3 } & Sombra> = ({ p, t, cor, r, sombra = true, recebe = true }) => (
  <mesh position={p} rotation={r} material={mat(cor)} castShadow={sombra} receiveShadow={recebe}><boxGeometry args={t} /></mesh>
);

/** Cilindro em pé (eixo Y); `topo`/`base` = raios; `lados` baixo dá o visual low poly. */
export const Cil: React.FC<{ p: V3; topo: number; base?: number; h: number; cor: string; lados?: number; r?: V3 } & Sombra> = ({ p, topo, base = topo, h, cor, lados = 32, r, sombra = true, recebe = true }) => (
  <mesh position={p} rotation={r} material={mat(cor)} castShadow={sombra} receiveShadow={recebe}><cylinderGeometry args={[topo, base, h, lados]} /></mesh>
);

/** Cilindro de a até b (raio r). */
export const Haste: React.FC<{ a: V3; b: V3; r: number; cor: string }> = ({ a, b, r, cor }) => {
  const va = new THREE.Vector3(...a), vb = new THREE.Vector3(...b), d = vb.clone().sub(va);
  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), d.clone().normalize());
  return (
    <mesh position={va.add(vb).multiplyScalar(0.5)} quaternion={q} material={mat(cor)} castShadow receiveShadow>
      <cylinderGeometry args={[r, r, d.length(), 12]} />
    </mesh>
  );
};
