// Ajuste só da vitrine (composição VitrineLote), no padrão do r12: reposiciona a câmera do palco e o objeto.
// Fora da vitrine, os componentes continuam em tamanho real, na origem e sem câmera.
import React, { useLayoutEffect } from 'react';
import { useThree } from '@react-three/fiber';
import { useVideoConfig } from 'remotion';
import * as THREE from 'three';

type V3 = [number, number, number];
/** desloc: soma à posição que a vitrine dá ao objeto; alvo: centro do quadro (mundo); altura: altura do quadro no alvo (m);
 *  dist: distância da câmera (2,1 = foco do DOF da vitrine); elev/azim: graus acima do alvo e giro (+ = câmera para a direita). */
type Plano = { desloc: V3; alvo: V3; altura: number; dist: number; elev: number; azim: number };

export const PLANOS = {
  // moeda no chão (a quadra tem 1 cm de espessura), ao lado do tênis direito do Téo, que serve de régua (15 cm)
  moeda: { desloc: [-0.3, 0.01, 0.15], alvo: [0.45, 0.02, 0.15], altura: 0.26, dist: 2.1, elev: 48, azim: 8 },
  // bandeja no chão, longe do Téo e das linhas (o círculo vai até x = 1,8); a câmera fechada só vê o piso azul
  paoQuente: { desloc: [3.75, 0.01, -1.0], alvo: [4.5, 0.04, -1.0], altura: 0.3, dist: 2.1, elev: 42, azim: 0 },
  // balcão longe do Téo e das linhas da quadra; câmera em 3/4 pela esquerda (o Téo fica atrás dela)
  balcaoPadaria: { desloc: [3.75, 0.01, -2.4], alvo: [4.5, 0.66, -2.4], altura: 1.7, dist: 2.8, elev: 24, azim: -35 },
} satisfies Record<string, Plano>;

const AjustarCamera: React.FC<{ p: Plano }> = ({ p }) => {
  const camera = useThree((s) => s.camera) as THREE.PerspectiveCamera;
  // roda depois da <Camera> do palco (vem antes na árvore), a cada quadro, sem loop próprio
  useLayoutEffect(() => {
    const e = (p.elev * Math.PI) / 180, a = (p.azim * Math.PI) / 180, h = p.dist * Math.cos(e);
    camera.position.set(p.alvo[0] + h * Math.sin(a), p.alvo[1] + p.dist * Math.sin(e), p.alvo[2] + h * Math.cos(a));
    camera.lookAt(...p.alvo);
    camera.fov = (2 * Math.atan(p.altura / 2 / p.dist) * 180) / Math.PI;
    camera.updateProjectionMatrix();
    camera.updateMatrixWorld();
  });
  return null;
};

export function apresentar(Componente: React.FC, nome: keyof typeof PLANOS): React.FC {
  return function PecaNaVitrine() {
    const { id } = useVideoConfig();
    if (id !== 'VitrineLote') return <Componente />;
    const p: Plano = PLANOS[nome];
    return (
      <>
        <AjustarCamera p={p} />
        <group position={p.desloc}><Componente /></group>
      </>
    );
  };
}
