// Vitrine da oficina: mostra UMA peça de UM autor sempre no mesmo palco (mesma luz, câmera, boneco e acabamento).
// Assim a comparação Claude x GPT é justa: só a peça muda.
// Render: npx remotion still src/index.ts Vitrine saida/oficina/<autor>-<peca>.png --frame=90 --props='{"autor":"claude","peca":"cenario"}'
import React from 'react';
import { AbsoluteFill, useCurrentFrame, useVideoConfig } from 'remotion';
import { ThreeCanvas } from '@remotion/three';
import { Boneco } from '../kit/Boneco';
import { Quadra } from '../kit/Quadra';
import { Luz } from '../kit/Luz';
import { Camera, type ChaveCam } from '../kit/Camera';
import { Foco, Acabamento } from '../kit/Pos';
import { ELENCO } from '../kit/elenco';
import { misturar, pose } from '../kit/poses';
import type { PecasOficina } from './contrato';
import { PECAS as CLAUDE } from './claude';
import { PECAS as GPT } from './gpt';

export const AUTORES: Record<string, PecasOficina> = { claude: CLAUDE, gpt: GPT };
export type PecaVitrine = 'cenario' | 'objeto' | 'pose' | 'efeito' | 'hud';
export const DURACAO_VITRINE = 150; // 5 s

const sorriso = { boca: 'sorriso' as const };

export const Vitrine: React.FC<{ autor: string; peca: PecaVitrine; soCenario?: boolean }> = ({ autor, peca, soCenario = false }) => {
  const P = AUTORES[autor] ?? CLAUDE;
  const q = useCurrentFrame();
  const { width, height, durationInFrames } = useVideoConfig();
  const ceu = peca === 'cenario' ? P.LIMITES_SALA.ceu : '#9fd3ee';
  const t = q / (durationInFrames - 1);

  let chaves: ChaveCam[]; let foco: number;
  if (peca === 'cenario') { chaves = [{ q: 0, pos: [0, 1.9, 6.2], alvo: [0, 1.1, 0], fov: 40 }, { q: durationInFrames - 1, pos: [0.6, 1.8, 5.2], alvo: [0, 1.1, 0], fov: 40 }]; foco = 5.6; }
  else if (peca === 'objeto') { chaves = [{ q: 0, pos: [0, 1.25, 0.95], alvo: [0, 1.15, 0.3], fov: 32 }, { q: durationInFrames - 1, pos: [0.1, 1.22, 0.8], alvo: [0, 1.15, 0.3], fov: 32 }]; foco = 0.6; }
  else { chaves = [{ q: 0, pos: [0, 1.75, 4.2], alvo: [0, 1.0, 0], fov: 36 }, { q: durationInFrames - 1, pos: [0, 1.7, 3.6], alvo: [0, 1.0, 0], fov: 36 }]; foco = 3.9; }

  const juntas = peca === 'pose' ? misturar(pose('parado'), { ...pose('parado'), ...P.POSE_APONTAR }, (q - 20) / 25) : pose('parado');

  return (
    <AbsoluteFill style={{ backgroundColor: ceu }}>
      <ThreeCanvas width={width} height={height} shadows flat gl={{ antialias: true, preserveDrawingBuffer: true }} camera={{ fov: 40, position: chaves[0].pos }}>
        <color attach="background" args={[ceu]} />
        <Camera chaves={chaves} quadro={q} />
        <Luz ceu={ceu} />
        {peca === 'cenario' ? <P.SalaDeAula /> : <Quadra />}
        {!soCenario && peca === 'cenario' && (<>
          <Boneco v={ELENCO.teo} e={sorriso} pos={[-0.7, 0, 0.5]} giro={10} />
          <Boneco v={ELENCO.bia} e={sorriso} pos={[0.7, 0, 0.5]} giro={-10} />
        </>)}
        {!soCenario && peca !== 'cenario' && <Boneco v={ELENCO.teo} j={juntas} e={sorriso} pos={[0, 0, 0]} />}
        {!soCenario && peca === 'objeto' && (
          <group position={[0, 1.15, 0.3]} rotation={[-0.25, -0.35 + 0.3 * t, 0]}><P.Celular telaAcesa /></group>
        )}
        {!soCenario && peca === 'efeito' && <P.BrilhoSorte quadro={q} intensidade={1} />}
        <Foco foco={foco} />
      </ThreeCanvas>
      <Acabamento quadro={q} />
      {peca === 'hud' && <P.HudContador quadro={q} rotulo="DIA 20" valor={`SORTE ${Math.round(2 ** Math.min(20, 1 + t * 20)).toLocaleString('pt-BR')}x`} />}
    </AbsoluteFill>
  );
};
