// Objeto de fundo: arco-íris duplo, para pôr do lado de fora de uma janela (atrás do personagem).
// Dois semicírculos de pé no plano XY, com o MESMO centro na linha do chão: o de dentro encosta por dentro do de fora,
// com uma faixa estreita de céu entre eles. Mesma saturação; o de fora só um pouco mais claro (o 2º arco é mais fraco).
// Faixas planas (toro achatado em Z), 9 cm cada (nada mais fino que 8 cm no fundo). Os pés apoiam no chão (y = 0).
// Sem sombra projetada nem recebida (é luz, não coisa). Origem no centro da base, frente para +Z. ~3,2 m x 1,6 m.
import React from 'react';
import { mat, misturarCor } from './base';

// de fora para dentro: vermelho → violeta, nos dois arcos
const CORES = ['#e8413c', '#f58a2e', '#f7d038', '#4cb85c', '#3b8fe0', '#8a5cc9'];
const FAIXA = 0.09;
const RAIO_FORA = 1.6;
const VAO = 0.1; // céu entre os dois arcos

const Arco: React.FC<{ raioFora: number; clarear: number }> = ({ raioFora, clarear }) => (
  <>
    {CORES.map((cor, i) => (
      // toro em meia-volta (arco = PI) achatado em Z: vira uma faixa plana; as faixas encostam sem sobrepor
      <mesh key={cor} scale={[1, 1, 0.08]} material={mat(misturarCor(cor, '#ffffff', clarear), 0.85, 0.45)}>
        <torusGeometry args={[raioFora - FAIXA * (i + 0.5), FAIXA / 2, 8, 72, Math.PI]} />
      </mesh>
    ))}
  </>
);

export const ArcoIrisDuplo: React.FC = () => (
  <group>
    <Arco raioFora={RAIO_FORA} clarear={0.12} />
    <Arco raioFora={RAIO_FORA - CORES.length * FAIXA - VAO} clarear={0} />
  </group>
);
