// Cenário: cozinha doméstica de manhã. Medidas em metros, Y para cima, chão em y = 0.
// Bancada com pia e fogão na parede do fundo (-Z), toda azulejada de amarelo; geladeira no canto esquerdo.
// A janela fica na parede +X, do lado de onde vem o sol da Luz padrão: a luz entra por ela, desenha a janela
// no chão e as sombras dos bonecos caem para trás e para a esquerda, coerentes com a janela.
// A mesa com duas cadeiras (uma de cada lado) fica embaixo da janela, à direita, fora da frente dos personagens.
import React from 'react';
import type { LimitesCenario } from '../tipos';
import { Caixa, Cilindro, Copa, Feixe, Haste, PlanoFoco, mat, vidro, type V3 } from './base';

const C = {
  piso: '#b8794a', piso2: '#a5683d', rodape: '#6e4327',
  parede: '#a5d6c4', azulejo: '#f2c544', azulejo2: '#f8dc7c', teto: '#f7f3ec',
  armario: '#fbfaf6', carcaca: '#d5d9dc', tampo: '#4b5059', rodapeArm: '#3d4249', puxador: '#3d4249',
  inox: '#c7ccd2', inoxEscuro: '#8e959d', fogao: '#f1efea', fogaoTopo: '#2f3338', vidroForno: '#3a4048',
  geladeira: '#e0675a', geladeira2: '#c9564a',
  madeira: '#d9a066', madeiraEscura: '#8a5530', almofada: '#d6453d', branco: '#f8f5ef', vidro: '#d8eef9',
  folha: '#4f9a52', folha2: '#5fae5a', vaso: '#c8693f', tronco: '#6b4a2f',
};

// medidas da cozinha
const X = 4.4; // meia largura (paredes em x = ±4,4)
const ZF = -2.6; // face da parede do fundo
const ZT = 7; // as paredes vão até atrás da câmera
const H = 2.9; // pé-direito
const Y_BANCADA = 0.92; // topo do tampo
const Y_AZULEJO = 2.2; // altura da faixa de azulejo
const L = ZT - ZF + 0.2, ZC = (ZF - 0.2 + ZT) / 2; // comprimento e centro das paredes laterais

// janela na parede +X
const JAN = { z0: -2.3, z1: -0.7, y0: 0.95, y1: 2.3 };

export const LIMITES_COZINHA: LimitesCenario = { limiteX: 1.5, limiteZ: [-1.0, 3.0], ceu: '#cfe9f5' };

/** Piso de tábuas largas (30 cm) correndo para a câmera, em dois tons de madeira. */
const Piso: React.FC = () => {
  const tabuas: number[] = [];
  for (let i = 0; i < (2 * X) / 0.3; i += 2) tabuas.push(-X + 0.15 + i * 0.3);
  return (
    <group>
      <Caixa p={[0, -0.12, 0]} t={[60, 0.1, 60]} cor="#9cc078" sombra={false} />
      <Caixa p={[0, -0.045, ZC]} t={[2 * X + 0.4, 0.05, L]} cor={C.piso} sombra={false} />
      {/* tábuas escuras 2 cm acima da base */}
      {tabuas.map((x) => <Caixa key={x} p={[x, -0.01, ZC]} t={[0.3, 0.02, L]} cor={C.piso2} sombra={false} />)}
    </group>
  );
};

/** Parede do fundo: verde-água em cima e azulejo amarelo do chão até 2,2 m, em xadrez de dois tons (32 cm). */
const ParedeFundo: React.FC = () => {
  const lad: V3[] = [];
  const t = 0.32;
  for (let i = 0; i * t < 2 * X - 0.1; i++) {
    for (let j = -2; j < 4; j++) {
      if ((i + j + 10) % 2) continue;
      const x = -X + t / 2 + i * t, y = Y_BANCADA + t / 2 + j * t;
      if (x < -3.45) continue; // atrás da geladeira
      if (j < 0 && x < 2.1) continue; // atrás da bancada e do fogão
      if (j >= 2 && ((x > -3.6 && x < -0.9) || (x > 0.5 && x < 2.1))) continue; // atrás dos armários de cima
      lad.push([x, y, ZF + 0.03]);
    }
  }
  return (
    <group>
      <Caixa p={[0, H / 2, ZF - 0.1]} t={[2 * X + 0.4, H + 0.1, 0.2]} cor={C.parede} />
      {/* base do azulejo (2 cm) e xadrez claro (mais 2 cm à frente) */}
      <Caixa p={[0, Y_AZULEJO / 2, ZF + 0.01]} t={[2 * X, Y_AZULEJO, 0.02]} cor={C.azulejo} sombra={false} />
      {lad.map((p, i) => <Caixa key={i} p={p} t={[t, t, 0.02]} cor={C.azulejo2} sombra={false} />)}
      {/* acabamento do azulejo: frisa branca grossa no alto */}
      <Caixa p={[0, Y_AZULEJO + 0.04, ZF + 0.03]} t={[2 * X, 0.08, 0.06]} cor={C.branco} />
      {/* rodapé atrás da mesa */}
      <Caixa p={[3.25, 0.06, ZF + 0.06]} t={[2.3, 0.12, 0.12]} cor={C.rodape} />
    </group>
  );
};

/** Parede lateral (eixo Z), com rodapé de madeira na face de dentro. */
const ParedeLado: React.FC<{ x: number; z0: number; z1: number; y0?: number; y1?: number; dentro: 1 | -1; rodape?: boolean }> = ({ x, z0, z1, y0 = 0, y1 = H + 0.1, dentro, rodape = true }) => (
  <group>
    <Caixa p={[x, (y0 + y1) / 2, (z0 + z1) / 2]} t={[0.2, y1 - y0, z1 - z0]} cor={C.parede} />
    {rodape && y0 === 0 && <Caixa p={[x + dentro * 0.14, 0.06, (z0 + z1) / 2]} t={[0.08, 0.12, z1 - z0]} cor={C.rodape} />}
  </group>
);

/** Fileira de armários (de baixo ou de cima): carcaça cinza-clara, portas brancas 2 cm à frente, frestas de 8 cm, puxador escuro. */
const Armarios: React.FC<{ x0: number; x1: number; y0: number; y1: number; prof: number; n: number; puxadorEmCima?: boolean }> = ({ x0, x1, y0, y1, prof, n, puxadorEmCima = true }) => {
  const w = (x1 - x0) / n, zf = ZF + prof;
  return (
    <group>
      <Caixa p={[(x0 + x1) / 2, (y0 + y1) / 2, ZF + prof / 2]} t={[x1 - x0, y1 - y0, prof]} cor={C.carcaca} />
      {Array.from({ length: n }, (_, i) => {
        const xc = x0 + w * (i + 0.5);
        const yp = puxadorEmCima ? y1 - 0.14 : y0 + 0.14;
        return (
          <group key={i}>
            <Caixa p={[xc, (y0 + y1) / 2, zf + 0.01]} t={[w - 0.08, y1 - y0 - 0.08, 0.02]} cor={C.armario} />
            <Caixa p={[xc + (i % 2 ? -1 : 1) * (w / 2 - 0.16), yp, zf + 0.035]} t={[0.08, 0.2, 0.03]} cor={C.puxador} />
          </group>
        );
      })}
    </group>
  );
};

/** Bancada de baixo: armários, rodapé escuro recuado e tampo escuro com beirada saliente. */
const Bancada: React.FC<{ x0: number; x1: number; n: number }> = ({ x0, x1, n }) => (
  <group>
    <Caixa p={[(x0 + x1) / 2, 0.05, ZF + 0.26]} t={[x1 - x0, 0.1, 0.52]} cor={C.rodapeArm} />
    <Armarios x0={x0} x1={x1} y0={0.1} y1={Y_BANCADA - 0.04} prof={0.58} n={n} />
    <Caixa p={[(x0 + x1) / 2, Y_BANCADA - 0.02, ZF + 0.32]} t={[x1 - x0 + 0.04, 0.04, 0.64]} cor={C.tampo} />
  </group>
);

/** Pia: cuba de inox embutida no tampo e torneira em arco. */
const Pia: React.FC<{ x: number }> = ({ x }) => (
  <group>
    <Caixa p={[x, Y_BANCADA + 0.01, ZF + 0.34]} t={[0.7, 0.02, 0.46]} cor={C.inox} sombra={false} />
    <Caixa p={[x, Y_BANCADA + 0.03, ZF + 0.36]} t={[0.56, 0.02, 0.34]} cor={C.inoxEscuro} sombra={false} />
    <Haste a={[x, Y_BANCADA, ZF + 0.08]} b={[x, Y_BANCADA + 0.36, ZF + 0.08]} r={0.04} cor={C.inox} />
    <Haste a={[x, Y_BANCADA + 0.36, ZF + 0.05]} b={[x, Y_BANCADA + 0.36, ZF + 0.3]} r={0.04} cor={C.inox} />
    <Haste a={[x, Y_BANCADA + 0.38, ZF + 0.3]} b={[x, Y_BANCADA + 0.26, ZF + 0.3]} r={0.04} cor={C.inox} />
    {/* escorredor com dois pratos ao lado */}
    <Caixa p={[x + 0.62, Y_BANCADA + 0.03, ZF + 0.3]} t={[0.42, 0.06, 0.32]} cor={C.inox} />
    {[-0.08, 0.06].map((dx) => (
      <mesh key={dx} position={[x + 0.62 + dx, Y_BANCADA + 0.17, ZF + 0.3]} rotation={[0, 0, 0.15]} material={mat(dx < 0 ? '#8fc6f0' : C.branco)} castShadow>
        <cylinderGeometry args={[0.13, 0.13, 0.03, 20]} />
      </mesh>
    ))}
  </group>
);

/** Fogão de 4 bocas com forno, chaleira vermelha e coifa de inox até o teto. */
const Fogao: React.FC<{ x: number }> = ({ x }) => {
  const w = 0.7, d = 0.62, zc = ZF + 0.02 + d / 2;
  return (
    <group>
      <Caixa p={[x, 0.45, zc]} t={[w, 0.9, d]} cor={C.fogao} />
      <Caixa p={[x, 0.915, zc]} t={[w, 0.03, d]} cor={C.fogaoTopo} />
      <Caixa p={[x, 1.0, ZF + 0.06]} t={[w, 0.16, 0.08]} cor={C.fogao} />
      {([[-0.17, -0.13], [0.17, -0.13], [-0.17, 0.15], [0.17, 0.15]] as const).map(([dx, dz]) => (
        <Cilindro key={`${dx}${dz}`} p={[x + dx, 0.93, zc + dz]} r={0.085} h={0.03} cor="#5a6068" />
      ))}
      {/* forno: vidro escuro, puxador e botões */}
      <Caixa p={[x, 0.44, zc + d / 2 + 0.01]} t={[0.54, 0.4, 0.02]} cor={C.vidroForno} sombra={false} />
      <Caixa p={[x, 0.71, zc + d / 2 + 0.04]} t={[0.52, 0.06, 0.04]} cor={C.inox} />
      {[-0.24, -0.08, 0.08, 0.24].map((dx) => (
        <mesh key={dx} position={[x + dx, 0.83, zc + d / 2 + 0.025]} rotation={[Math.PI / 2, 0, 0]} material={mat(C.fogaoTopo)} castShadow><cylinderGeometry args={[0.04, 0.04, 0.05, 14]} /></mesh>
      ))}
      {/* chaleira */}
      <Cilindro p={[x - 0.17, 0.96, zc + 0.15]} r={0.11} r2={0.13} h={0.16} cor="#d6453d" />
      <mesh position={[x - 0.17, 1.13, zc + 0.15]} scale={[1, 0.45, 1]} material={mat('#d6453d')} castShadow><sphereGeometry args={[0.11, 18, 10]} /></mesh>
      <Haste a={[x - 0.06, 1.0, zc + 0.15]} b={[x + 0.05, 1.1, zc + 0.15]} r={0.03} cor="#d6453d" />
      <Cilindro p={[x - 0.17, 1.17, zc + 0.15]} r={0.03} h={0.04} cor="#2f3338" />
      {/* coifa */}
      <Caixa p={[x, 1.88, ZF + 0.27]} t={[0.82, 0.16, 0.52]} cor={C.inox} />
      <Caixa p={[x, 1.79, ZF + 0.27]} t={[0.78, 0.04, 0.48]} cor={C.inoxEscuro} sombra={false} />
      <Caixa p={[x, (1.96 + H) / 2, ZF + 0.16]} t={[0.34, H - 1.96, 0.3]} cor={C.inox} />
    </group>
  );
};

/** Geladeira vermelha de duas portas, no canto esquerdo. */
const Geladeira: React.FC<{ x: number }> = ({ x }) => {
  const d = 0.7, zc = ZF + 0.02 + d / 2, zf = ZF + 0.02 + d;
  return (
    <group>
      <Caixa p={[x, 0.97, zc]} t={[0.8, 1.94, d]} cor={C.geladeira2} />
      <Caixa p={[x, 0.68, zf + 0.01]} t={[0.76, 1.24, 0.02]} cor={C.geladeira} />
      <Caixa p={[x, 1.63, zf + 0.01]} t={[0.76, 0.54, 0.02]} cor={C.geladeira} />
      <Caixa p={[x + 0.28, 1.05, zf + 0.05]} t={[0.08, 0.42, 0.05]} cor={C.branco} />
      <Caixa p={[x + 0.28, 1.5, zf + 0.05]} t={[0.08, 0.24, 0.05]} cor={C.branco} />
      {/* ímãs e um bilhete */}
      <Caixa p={[x - 0.12, 0.98, zf + 0.025]} t={[0.2, 0.24, 0.01]} cor={C.branco} r={[0, 0, 0.08]} sombra={false} />
      <Cilindro p={[x - 0.12, 1.08, zf + 0.02]} r={0.035} h={0.02} cor="#f2c544" sombra={false} />
    </group>
  );
};

/** Janela da parede +X: caixilho branco em cruz, vidro claro e peitoril com um vaso. */
const Janela: React.FC = () => {
  const { z0, z1, y0, y1 } = JAN, zc = (z0 + z1) / 2, w = z1 - z0, h = y1 - y0, yc = (y0 + y1) / 2, xm = X + 0.1;
  return (
    <group>
      <Caixa p={[xm, y0 + 0.05, zc]} t={[0.24, 0.1, w]} cor={C.branco} />
      <Caixa p={[xm, y1 - 0.05, zc]} t={[0.24, 0.1, w]} cor={C.branco} />
      <Caixa p={[xm, yc, z0 + 0.05]} t={[0.24, h, 0.1]} cor={C.branco} />
      <Caixa p={[xm, yc, z1 - 0.05]} t={[0.24, h, 0.1]} cor={C.branco} />
      <Caixa p={[xm, yc, zc]} t={[0.1, h - 0.1, 0.1]} cor={C.branco} />
      <Caixa p={[xm, y0 + h * 0.6, zc]} t={[0.1, 0.1, w - 0.1]} cor={C.branco} />
      <Caixa p={[X - 0.08, y0 - 0.03, zc]} t={[0.24, 0.06, w + 0.2]} cor={C.branco} />
      <mesh position={[X + 0.17, yc, zc]} material={vidro(C.vidro, 0.15)}><boxGeometry args={[0.02, h - 0.1, w - 0.1]} /></mesh>
      {/* vaso de planta no peitoril */}
      <Cilindro p={[X - 0.1, y0, z1 - 0.3]} r={0.08} r2={0.06} h={0.14} cor={C.vaso} />
      <Copa p={[X - 0.1, y0 + 0.22, z1 - 0.3]} r={0.11} cor={C.folha2} />
    </group>
  );
};

/** Cadeira de madeira com almofada; o encosto fica do lado -X local (a pessoa olha para +X local). */
const Cadeira: React.FC<{ p: V3; giro: number }> = ({ p, giro }) => (
  <group position={p} rotation={[0, giro, 0]}>
    <Caixa p={[0, 0.45, 0]} t={[0.44, 0.05, 0.44]} cor={C.madeiraEscura} />
    <Caixa p={[0.02, 0.49, 0]} t={[0.38, 0.04, 0.38]} cor={C.almofada} />
    {([[-1, -1], [1, -1], [-1, 1], [1, 1]] as const).map(([sx, sz]) => (
      <Caixa key={`${sx}${sz}`} p={[sx * 0.18, 0.215, sz * 0.18]} t={[0.05, 0.43, 0.05]} cor={C.madeiraEscura} />
    ))}
    {/* encosto: dois montantes e duas travessas largas */}
    {[-1, 1].map((sz) => <Caixa key={sz} p={[-0.195, 0.7, sz * 0.18]} t={[0.05, 0.46, 0.05]} cor={C.madeiraEscura} />)}
    <Caixa p={[-0.195, 0.86, 0]} t={[0.05, 0.12, 0.42]} cor={C.madeiraEscura} />
    <Caixa p={[-0.195, 0.64, 0]} t={[0.05, 0.1, 0.42]} cor={C.madeiraEscura} />
  </group>
);

/** Mesa pequena de madeira (0,8 × 1,0 m) com fruteira, canecas e pratos. */
const Mesa: React.FC<{ p: V3 }> = ({ p }) => (
  <group position={p}>
    <Caixa p={[0, 0.735, 0]} t={[0.84, 0.05, 1.04]} cor={C.madeira} />
    <Caixa p={[0, 0.66, 0]} t={[0.7, 0.1, 0.9]} cor={C.madeiraEscura} />
    {([[-1, -1], [1, -1], [-1, 1], [1, 1]] as const).map(([sx, sz]) => (
      <Caixa key={`${sx}${sz}`} p={[sx * 0.34, 0.355, sz * 0.44]} t={[0.06, 0.71, 0.06]} cor={C.madeiraEscura} />
    ))}
    {/* fruteira */}
    <Cilindro p={[0, 0.76, 0.05]} r={0.15} r2={0.09} h={0.07} cor="#f1ece4" />
    {([[-0.06, 0.02, '#f08a24'], [0.06, 0.08, '#d93a3a'], [0.0, -0.06, '#f2c544']] as const).map(([dx, dz, cor]) => (
      <mesh key={cor} position={[dx, 0.86, 0.05 + dz]} material={mat(cor)} castShadow><sphereGeometry args={[0.06, 14, 10]} /></mesh>
    ))}
    {/* pratos e canecas, um de cada lado */}
    {[-1, 1].map((s) => (
      <group key={s}>
        <Cilindro p={[s * 0.22, 0.76, -0.25]} r={0.12} h={0.02} cor={C.branco} sombra={false} />
        <Cilindro p={[s * 0.24, 0.76, 0.32]} r={0.045} h={0.1} cor={s < 0 ? '#3a86c8' : '#f2c544'} />
      </group>
    ))}
  </group>
);

/** Relógio redondo de parede. */
const Relogio: React.FC<{ p: V3 }> = ({ p }) => (
  <group position={p}>
    <mesh position={[0, 0, 0.04]} rotation={[Math.PI / 2, 0, 0]} material={mat(C.branco)} castShadow receiveShadow><cylinderGeometry args={[0.2, 0.2, 0.06, 32]} /></mesh>
    <mesh position={[0, 0, 0.06]} material={mat(C.geladeira)} castShadow><torusGeometry args={[0.2, 0.04, 10, 32]} /></mesh>
    <group position={[0, 0, 0.09]} rotation={[0, 0, -Math.PI / 3]}><Caixa p={[0, 0.05, 0]} t={[0.06, 0.12, 0.02]} cor="#2f3338" sombra={false} /></group>
    <group position={[0, 0, 0.11]} rotation={[0, 0, Math.PI]}><Caixa p={[0, 0.07, 0]} t={[0.05, 0.16, 0.02]} cor="#2f3338" sombra={false} /></group>
  </group>
);

export const Cozinha: React.FC = () => {
  const { z0, z1, y0, y1 } = JAN;
  return (
    <group>
      <PlanoFoco z={-1.0} />
      <Piso />
      <ParedeFundo />
      {/* paredes laterais: a da direita com o vão da janela */}
      <ParedeLado x={-X - 0.1} z0={ZF - 0.2} z1={ZT} dentro={1} />
      <ParedeLado x={X + 0.1} z0={ZF - 0.2} z1={z0} dentro={-1} />
      <ParedeLado x={X + 0.1} z0={z1} z1={ZT} dentro={-1} />
      <ParedeLado x={X + 0.1} z0={z0} z1={z1} y1={y0} dentro={-1} />
      <ParedeLado x={X + 0.1} z0={z0} z1={z1} y0={y1} dentro={-1} />
      <Janela />
      {/* luz da manhã entrando pela janela */}
      <Feixe de={[X + 0.15, (y0 + y1) / 2, (z0 + z1) / 2]} larg={1.0} alt={1.4} comp={2.6} />
      {/* teto sem sombra (o sol continua entrando), levemente aceso, com plafon */}
      <Caixa p={[0, H + 0.05, ZC]} t={[2 * X + 0.4, 0.1, L]} cor={C.teto} sombra={false} m={mat(C.teto, { brilho: 0.4 })} />
      <mesh position={[0, H - 0.04, -0.6]} material={mat('#fffdf4', { brilho: 0.9 })}><cylinderGeometry args={[0.3, 0.3, 0.08, 28]} /></mesh>
      {/* bancada com pia (esquerda) e fogão (no vão entre os personagens) */}
      <Geladeira x={-3.95} />
      <Bancada x0={-3.5} x1={-0.55} n={5} />
      <Bancada x0={0.15} x1={2.1} n={3} />
      <Pia x={-2.65} />
      <Fogao x={-0.2} />
      <Armarios x0={-3.5} x1={-1.0} y0={1.5} y1={2.26} prof={0.36} n={4} puxadorEmCima={false} />
      <Armarios x0={0.5} x1={2.1} y0={1.5} y1={2.26} prof={0.36} n={2} puxadorEmCima={false} />
      {/* coisas na bancada: potes, tábua de corte, torradeira, planta */}
      {([[-1.55, 0.2, '#e9e1cc'], [-1.35, 0.16, '#3a86c8'], [-1.17, 0.12, '#e9e1cc']] as const).map(([x, h, cor]) => (
        <group key={x}>
          <Cilindro p={[x, Y_BANCADA, ZF + 0.18]} r={0.08} h={h} cor={cor} />
          <Cilindro p={[x, Y_BANCADA + h, ZF + 0.18]} r={0.085} h={0.03} cor={C.madeiraEscura} />
        </group>
      ))}
      <Caixa p={[-0.95, Y_BANCADA + 0.02, ZF + 0.36]} t={[0.36, 0.03, 0.26]} cor={C.madeira} r={[0, 0.2, 0]} />
      <Caixa p={[0.75, Y_BANCADA + 0.11, ZF + 0.3]} t={[0.3, 0.22, 0.18]} cor="#e9e1cc" />
      <Caixa p={[0.75, Y_BANCADA + 0.235, ZF + 0.3]} t={[0.2, 0.03, 0.1]} cor="#2f3338" sombra={false} />
      <Cilindro p={[1.8, Y_BANCADA, ZF + 0.3]} r={0.1} r2={0.08} h={0.16} cor={C.vaso} />
      <Copa p={[1.8, Y_BANCADA + 0.3, ZF + 0.3]} r={0.16} cor={C.folha} />
      <Relogio p={[1.3, 2.6, ZF]} />
      {/* mesa embaixo da janela, uma cadeira de cada lado */}
      <Mesa p={[3.15, 0, -1.35]} />
      <Cadeira p={[2.3, 0, -1.35]} giro={0} />
      <Cadeira p={[4.0, 0, -1.35]} giro={Math.PI} />
      {/* lá fora: árvore vista pela janela */}
      <Haste a={[7, -0.1, -1.4]} b={[7, 2.2, -1.4]} r={0.16} cor={C.tronco} />
      <Copa p={[7, 2.8, -1.4]} r={1.2} cor={C.folha} />
      <Copa p={[6.6, 2.0, -0.5]} r={0.8} cor={C.folha2} />
    </group>
  );
};
