// Planície noturna sem construções. Piso em y=0 e frente livre para o elenco.
import React from 'react';
import { random } from 'remotion';
import { Caixa, Esfera, mat, type V3 } from './base';

export const CEU_GELO = '#192e67';
const C = {
  base: '#72a3d5', neve: '#edf5ff', gelo: '#80afe2', claro: '#aacbec', branco: '#c9dcf0',
  azul: '#6599d4', longe: '#5363bd', horizonte: '#6b7bd0', estrela: '#ffd52b',
};

// Larguras e comprimentos variados; as peças se tocam, sem riscos entre elas.
const BLOCOS: { p: V3; t: V3; cor: string }[] = [];
const FAIXAS = [-12, -10.2, -8.8, -7.7, -6.1, -4.9, -3.5, -2, -1, 0.2, 1.7, 2.6, 4.1, 5.5, 7.2];
for (let linha = 0; linha < FAIXAS.length - 1; linha++) {
  const frente = FAIXAS[linha + 1];
  const fundo = FAIXAS[linha];
  let x = -14;
  for (let coluna = 0; x < 14; coluna++) {
    const semente = `l06-placa-${linha}-${coluna}`;
    const largura = Math.min(14 - x, 0.95 + random(`${semente}-largura`) * 1.4);
    const centro = x + largura / 2;
    const elevado = frente < -1.2 && Math.abs(centro) > 1.9;
    const topo = elevado ? Math.floor(random(`${semente}-altura`) * 3) * 0.08 : 0;
    const cores = [C.gelo, C.claro, C.branco, C.azul];
    BLOCOS.push({
      p: [centro, (topo - 0.32) / 2, (fundo + frente) / 2],
      t: [largura, topo + 0.32, frente - fundo],
      cor: cores[Math.floor(random(`${semente}-cor`) * cores.length)],
    });
    x += largura;
  }
}

const MONTES: { p: V3; r: number }[] = [
  { p: [-3.3, 0, -0.5], r: 0.63 },
  { p: [3.8, 0, -1.4], r: 0.74 },
  { p: [-2.9, 0, -4.1], r: 0.78 },
  { p: [2.9, 0, -4.9], r: 0.86 },
  { p: [-5.3, 0, -6.5], r: 0.94 },
  { p: [5.6, 0, -7.3], r: 1.02 },
  { p: [-0.3, 0, -8.6], r: 0.92 },
];

// Distribuição por faixas com variação pequena, sem aglomerados aleatórios.
const ESTRELAS = Array.from({ length: 32 }, (_, i) => ({
  p: [
    -17.5 + (i % 8) * 5 + (random(`l06-estrela-x-${i}`) - 0.5) * 2,
    3.9 + Math.floor(i / 8) * 2.15 + (random(`l06-estrela-y-${i}`) - 0.5) * 0.8,
    -23 - random(`l06-estrela-z-${i}`) * 2,
  ] as V3,
  raio: 0.085 + random(`l06-estrela-raio-${i}`) * 0.035,
}));

const Monte: React.FC<{ p: V3; r: number }> = ({ p, r }) => (
  <group position={p}>
    {/* Esferas quase inteiras, com apenas a base enterrada; alturas diferentes. */}
    <Esfera p={[0, r * 0.51, 0]} t={[r, r * 0.94, r * 0.96]} cor={C.neve} />
    <Esfera p={[-r * 0.83, r * 0.29, r * 0.2]} t={[r * 0.64, r * 0.61, r * 0.65]} cor={C.neve} />
    <Esfera p={[r * 0.78, r * 0.2, r * 0.35]} t={[r * 0.47, r * 0.45, r * 0.5]} cor={C.neve} />
  </group>
);

export const PaisagemGelada: React.FC = () => (
  <>
    {/* A névoa chega à cor do céu; o chão distante não corta o horizonte. */}
    <fog attach="fog" args={[CEU_GELO, 14, 42]} />
    <hemisphereLight args={['#87baff', '#294c8c', 0.55]} />
    <directionalLight position={[-7, 8, -6]} color="#80aaff" intensity={0.85} />
    <Caixa p={[0, -0.5, 0]} t={[100, 0.4, 100]} cor={C.base} sombra={false} />
    {BLOCOS.map((bloco, i) => <Caixa key={i} {...bloco} sombra={false} />)}
    {MONTES.map((monte, i) => <Monte key={i} {...monte} />)}
    {/* Relevos azul-violeta suaves; o Foco da vitrine fornece o desfoque. */}
    {Array.from({ length: 11 }, (_, i) => (
      <Esfera key={`fundo-${i}`} p={[(i - 5) * 4.4, 0, -16 - (i % 3) * 2]}
        t={[3.5, 1.1 + random(`l06-horizonte-${i}`) * 0.8, 2.6]}
        cor={i % 2 === 0 ? C.longe : C.horizonte} sombra={false} />
    ))}
    {ESTRELAS.map(({ p, raio }, i) => (
      <mesh key={`estrela-${i}`} position={p} material={mat(C.estrela, 0.85, false)}>
        <sphereGeometry args={[raio, 16, 12]} />
      </mesh>
    ))}
  </>
);
