// Efeito: neve caindo devagar e em diagonal por toda a tela, em duas camadas bem separadas.
//  - fundo: flocos de raio ~1 cm, densos, de 0,4 a 3,5 m ATRÁS do personagem (o próprio boneco os esconde: teste de profundidade);
//  - frente: flocos de raio ~2 cm, poucos, entre o personagem e a câmera, desviando da silhueta dele.
// Anti-tremido (qa/cintilacao.py reprova pixel que vai e volta em 1 quadro): posição = fase fixa + velocidade constante · quadro,
// com módulo para o loop (o recomeço é fora do quadro), e cada floco anda por quadro só ~1/3 do próprio diâmetro.
import * as THREE from 'three';
import React, { useMemo } from 'react';
import { random } from 'remotion';
import { LuzFria, mat, modulo, suave, TAU } from './base';

type Camada = {
  n: number; raio: [number, number]; z: [number, number];
  queda: number; vento: number; // metros por quadro (constantes)
  estica: number; // alongamento na direção do movimento (lê a diagonal na foto parada)
  desvia: boolean; // some suavemente diante da silhueta do personagem
};
const CAMADAS: Camada[] = [
  { n: 430, raio: [0.009, 0.012], z: [-3.5, -0.4], queda: 0.005, vento: 0.0028, estica: 1.15, desvia: false },
  { n: 120, raio: [0.017, 0.021], z: [1.0, 2.6], queda: 0.0095, vento: 0.0052, estica: 1.35, desvia: true },
];
// câmera típica do efeito (de +Z, na altura dos olhos): só para dimensionar a faixa de flocos e o desvio
const CAM = { y: 1.72, z: 3.9 };
const Y_BAIXO = -0.08; // recomeça abaixo do chão (escondido)
/** Topo da faixa numa profundidade z: acima do que a câmera vê. */
const topo = (z: number) => 2.2 + 0.16 * (CAM.z + 0.3 - z);
/** Largura da faixa numa profundidade z: um pouco mais que o quadro. */
const largura = (z: number) => 2 * (0.6 * (CAM.z + 0.3 - z) + 0.35);

/** 0 dentro da silhueta do personagem (projetada no plano z = 0), 1 fora, com transição suave de 25 cm. */
const foraDoBoneco = (x: number, y: number, z: number) => {
  const s = CAM.z / (CAM.z - z);
  const px = x * s, py = CAM.y + (y - CAM.y) * s;
  // distância a uma caixa |x| < 0,42, 0 < y < 1,8 (corpo + cabeça + boné)
  const dx = Math.max(0, Math.abs(px) - 0.42), dy = Math.max(0, py - 1.8);
  return suave(Math.hypot(dx, dy) / 0.25);
};

type Floco = { ci: number; r: number; z: number; x0: number; y0: number; L: number; H: number; vel: number; fase: number };

/** Flocos fixos (gerados uma vez): metade em "nuvens" agrupadas, metade espalhada. */
const gerar = (): Floco[] => {
  const lista: Floco[] = [];
  CAMADAS.forEach((c, ci) => {
    const nuvens = Math.round(c.n / 30);
    for (let i = 0; i < c.n; i++) {
      const r = (k: string) => random(`neve-r10-${ci}-${i}-${k}`);
      let z = c.z[0] + r('z') * (c.z[1] - c.z[0]);
      const L = largura(z), H = topo(z) - Y_BAIXO;
      let x0 = r('x') * L, y0 = r('y') * H;
      if (r('agrupa') < 0.5) {
        // agrupado: em volta do centro de uma nuvem (soma de 2 sorteios = mais denso no meio)
        const k = Math.floor(r('nuvem') * nuvens);
        const rn = (s: string) => random(`neve-r10-nuvem-${ci}-${k}-${s}`);
        const esp = ci === 0 ? 0.55 : 0.35;
        z = Math.min(c.z[1], Math.max(c.z[0], c.z[0] + rn('z') * (c.z[1] - c.z[0]) + (r('dz') + r('dz2') - 1) * 0.4));
        x0 = rn('x') * L + (r('dx') + r('dx2') - 1) * esp;
        y0 = rn('y') * H + (r('dy') + r('dy2') - 1) * esp;
      }
      lista.push({ ci, r: c.raio[0] + r('raio') * (c.raio[1] - c.raio[0]), z, x0, y0, L: largura(z), H: topo(z) - Y_BAIXO, vel: 0.85 + 0.3 * r('v'), fase: r('f') * TAU });
    }
  });
  return lista;
};
const FLOCOS = gerar();

export const Neve: React.FC<{ quadro: number; /** fração dos flocos (0 a 1) */ intensidade?: number; /** esfria a luz da cena */ frio?: boolean }> = ({ quadro, intensidade = 1, frio = true }) => {
  const geo = useMemo(() => new THREE.SphereGeometry(1, 12, 10), []);
  // branco levemente azulado e com emissivo frio: tem sombreado (não é recorte chapado), mas não fica cinza na sombra
  const m = mat('#ffffff', 0.3, '#cfdcf5');
  const giroDiagonal = CAMADAS.map((c) => Math.atan2(c.vento, c.queda)); // inclinação do movimento (em torno de Z)
  return (
    <>
      {frio && <LuzFria />}
      {FLOCOS.map((f, i) => {
        const c = CAMADAS[f.ci];
        if (intensidade < 1 && random(`neve-r10-fica-${i}`) >= intensidade) return null;
        // posição: fase fixa + velocidade constante · quadro, com loop por módulo (o recomeço é fora do quadro)
        const y = topo(f.z) - modulo(f.y0 + quadro * c.queda * f.vel, f.H);
        const x = modulo(f.x0 + quadro * c.vento * f.vel, f.L) - f.L / 2 + 0.025 * Math.sin(quadro * 0.04 + f.fase);
        const k = c.desvia ? foraDoBoneco(x, y, f.z) : 1;
        if (k < 0.03) return null;
        const r = f.r * k;
        return (
          <mesh key={i} geometry={geo} material={m} position={[x, y, f.z]} rotation={[0, 0, giroDiagonal[f.ci]]} scale={[r, r * c.estica, r]} />
        );
      })}
    </>
  );
};
