// Demos das ações COM os objetos e o outro personagem (tipo 'efeito'). O contrato `acao` só leva juntas, então
// a vitrine da ação mostra o Téo sozinho e de mãos vazias; aqui a mesma pose aparece com a cena inteira, ao lado dele.
// Cada demo monta a cena no espaço de quem faz a ação (olha +Z) e gira o grupo para a câmera da vitrine.
import * as THREE from 'three';
import React from 'react';
import { Boneco } from '../../../kit/Boneco';
import { ELENCO } from '../../../kit/elenco';
import { BASE, type Juntas } from '../../../kit/poses';
import type { PecaOficina } from '../tipos';
import { caminhoRiscar, juntasNoQuadro, RISCO, TEMPOS_RISCO, tranco } from './acoes';
import { alturaNoChao, bracoNo, matrizMao, matrizTronco, posMao, posOmbro } from './cinematica';
import { Apontado, Caneta, centroCelula, Marcador, Mochila, NaMatriz, Placa, PONTA_CANETA, Traco } from './objetos';

const v3 = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);
const suave = (t: number) => { const k = Math.min(1, Math.max(0, t)); return k * k * (3 - 2 * k); };
const R = THREE.MathUtils.degToRad;
/** Direção do antebraço (do cotovelo para a mão). */
const dirAntebraco = (j: Juntas, lado: 1 | -1) =>
  v3(0, -1, 0).applyQuaternion(new THREE.Quaternion().setFromRotationMatrix(matrizMao(j, lado))).normalize();

// ── puxar: c2 agarra a mochila do c1 pelos lados; o c1 tenta ir embora ──
// O c1 anda inclinado para a frente e olha para trás, assustado. A mochila fica onde os braços retos alcançam.
const FUGINDO: Juntas = {
  ...BASE, troncoX: 16, cabecaY: -55, cabecaX: -6,
  ombroEX: 45, ombroEZ: 18, cotoveloE: 40, ombroDX: -30, ombroDZ: 18, cotoveloD: 30,
  quadrilE: 30, joelhoE: 14, quadrilD: -20, joelhoD: 28,
};
const MOCHILA_NAS_COSTAS = new THREE.Matrix4().makeTranslation(0, 0.95, -0.2);
const PEGA_MOCHILA = v3(0.19, -0.04, -0.1); // mão D no lado da mochila (a E é o espelho em X)
const DemoPuxar: React.FC<{ quadro: number }> = ({ quadro }) => {
  // cena de perfil: a puxada vai reto para a frente (sem o giro do tronco feito para a câmera de frente),
  // assim a inclinação para trás aparece inteira; o rosto vira para a câmera
  const j0: Juntas = { ...juntasNoQuadro('puxar', quadro), troncoY: 0, cabecaY: -30 };
  const fugindo: Juntas = { ...FUGINDO, altura: alturaNoChao(FUGINDO) };
  const mMochila = matrizTronco(fugindo).multiply(MOCHILA_NAS_COSTAS);
  // as mãos pegam os dois lados da mochila (no espaço de quem foge)
  const pegaD = PEGA_MOCHILA.clone().applyMatrix4(mMochila), pegaE = PEGA_MOCHILA.clone().setX(-PEGA_MOCHILA.x).applyMatrix4(mMochila);
  const meio = pegaD.clone().add(pegaE).multiplyScalar(0.5);
  // quem foge fica onde o meio das mãos cai a 46 cm do meio dos ombros de quem puxa (braços retos)
  const ombros = posOmbro(j0, 1).add(posOmbro(j0, -1)).multiplyScalar(0.5);
  const dy = meio.y - ombros.y;
  const posF = v3(0, 0, ombros.z + Math.sqrt(Math.max(0, 0.46 * 0.46 - dy * dy)) - meio.z);
  const j1 = { ...j0, ...bracoNo(j0, 1, pegaD.clone().add(posF)) };
  const j: Juntas = { ...j1, ...bracoNo(j1, -1, pegaE.clone().add(posF)) };
  const f = tranco(quadro);
  return (
    <group position={[0.75, 0, -0.5]} rotation={[0, R(71), 0]}>
      <Boneco v={ELENCO.c2} j={j} e={{ boca: 'neutra', sobrancelha: -1, piscar: 0.3 + 0.15 * f, olharX: 0.6 }} />
      <group position={posF}>
        <Boneco v={ELENCO.c1} j={fugindo} e={{ boca: 'o', sobrancelha: 1, olharX: -0.7 }} />
        <NaMatriz m={mMochila}><Mochila /></NaMatriz>
      </group>
    </group>
  );
};

// ── riscar: Bia marca o X vermelho no 3º dia da placa de metas (os dois primeiros já estão riscados) ──
const DemoRiscar: React.FC<{ quadro: number }> = ({ quadro }) => {
  const j = juntasNoQuadro('riscar', quadro);
  const { traco1, traco2 } = caminhoRiscar(quadro);
  const [cx, cy] = centroCelula(2, 0);
  const base = RISCO.centro.clone().addScaledVector(RISCO.lado, -cx).setY(0);
  const giroPlaca = Math.atan2(RISCO.normal.x, RISCO.normal.z);
  const m = RISCO.meio;
  const c = (sx: number, sy: number) => v3(cx + sx * m, RISCO.centro.y + sy * m, 0.008);
  const feito = quadro >= TEMPOS_RISCO.recua[0];
  return (
    <group position={[0.8, 0, -0.1]} rotation={[0, R(14), 0]}>
      <Boneco v={ELENCO.bia} j={j} e={{ boca: feito ? 'sorriso' : 'neutra', sobrancelha: feito ? 0.3 : -0.5, olharX: 0.5, olharY: 0.6 }} />
      <Apontado p={posMao(j, 1)} dir={RISCO.dir}><Marcador /></Apontado>
      <group position={base} rotation={[0, giroPlaca, 0]}>
        <Placa alturaCentro={RISCO.centro.y - cy} />
        {/* o X novo: as pontas seguem a ponta do marcador */}
        {traco1 > 0 && <Traco a={c(-1, 1)} b={c(-1, 1).lerp(c(1, -1), traco1)} />}
        {traco2 > 0 && <Traco a={c(1, 1)} b={c(1, 1).lerp(c(-1, -1), traco2)} />}
      </group>
    </group>
  );
};

// ── entregar: c1 oferece a caneta; c2, de frente para ele, abre a mão por baixo da ponta ──
const LINHA = R(38); // direção de quem recebe, no espaço de quem entrega (a mesma do braço)
const DemoEntregar: React.FC<{ quadro: number }> = ({ quadro }) => {
  // a cabeça vira um pouco para a câmera (a vista aqui é de lado)
  const j = { ...juntasNoQuadro('entregar', quadro), cabecaY: -8 };
  const dir = dirAntebraco(j, 1).setY(0).normalize(); // caneta deitada na palma, na direção do braço
  const caneta = posMao(j, 1).add(v3(0, 0.08, 0)).addScaledVector(dir, 0.03);
  const pontaCaneta = caneta.clone().addScaledVector(dir, PONTA_CANETA);
  const posR = v3(Math.sin(LINHA), 0, Math.cos(LINHA)).multiplyScalar(0.98);
  const giroR = LINHA + Math.PI;
  // quem recebe: a mão E (do lado da câmera) sobe entre 40 e 60 até logo abaixo e além da ponta
  const k = suave((quadro - 40) / 20);
  const alvo = pontaCaneta.clone().addScaledVector(dir, 0.02).add(v3(0, -0.1, 0)).sub(posR).applyAxisAngle(v3(0, 1, 0), -giroR);
  const jr0: Juntas = { ...BASE, troncoX: 5 * k, quadrilE: 10, joelhoE: 4, quadrilD: -4, cabecaX: 8, cabecaY: 34 }; // a cabeça vira para a câmera
  const repouso = v3(-0.3, 0.64, 0.1);
  const jr1: Juntas = { ...jr0, ombroDX: 4, ombroDZ: 6, cotoveloD: 14 };
  const jr: Juntas = { ...jr1, ...bracoNo(jr1, -1, repouso.lerp(alvo, k)) };
  return (
    <group position={[0.65, 0, -0.35]} rotation={[0, R(28), 0]}>
      <Boneco v={ELENCO.c1} j={j} e={{ boca: 'sorriso', sobrancelha: 0.3, olharX: 0.6, olharY: -0.3 }} />
      <Apontado p={caneta} dir={dir}><Caneta /></Apontado>
      <group position={posR} rotation={[0, giroR, 0]}>
        <Boneco v={ELENCO.c2} j={{ ...jr, altura: alturaNoChao(jr) }} e={{ boca: k > 0.9 ? 'sorriso' : 'o', sobrancelha: 0.7, olharY: -0.4 }} />
      </group>
    </group>
  );
};

export const DEMOS: PecaOficina[] = [
  { tipo: 'efeito', nome: 'puxar+outro', Componente: DemoPuxar },
  { tipo: 'efeito', nome: 'riscar+alvo', Componente: DemoRiscar },
  { tipo: 'efeito', nome: 'entregar+outro', Componente: DemoEntregar },
];
