import React from 'react';
import { useCurrentFrame } from 'remotion';
import { Caixa, Cilindro } from './base';

const PRETO = '#000000';
const LARANJA = '#ff8000';
const BASE_BARRA = 0.34;
const UNIDADE = 0.20;
const X_BARRA = -0.075;
const LARGURA_BARRA = 0.12;

// Topo, direita alta/baixa, base, esquerda baixa/alta, meio.
const SEGMENTOS: [number, number, number, number][] = [
  [0, 0.035, 0.042, 0.012], [0.021, 0.0175, 0.012, 0.035],
  [0.021, -0.0175, 0.012, 0.035], [0, -0.035, 0.042, 0.012],
  [-0.021, -0.0175, 0.012, 0.035], [-0.021, 0.0175, 0.012, 0.035],
  [0, 0, 0.042, 0.012],
];
const DIGITOS = { 1: [1, 2], 2: [0, 1, 6, 4, 3] };

const Porcentagem: React.FC<{ valor: 1 | 2; y: number }> = ({ valor, y }) => (
  <group position={[0.16, y, 0.08]}>
    {DIGITOS[valor].map((i) => {
      const [x, py, largura, altura] = SEGMENTOS[i];
      return <Caixa key={i} p={[x, py, 0]} t={[largura, altura, 0.02]} cor={PRETO} sombra={false} />;
    })}
    <Caixa p={[0.073, 0, 0]} t={[0.012, 0.082, 0.02]} giro={-0.55} cor={PRETO} sombra={false} />
    <Cilindro p={[0.051, 0.025, 0]} raio={0.009} altura={0.02} cor={PRETO} frente sombra={false} />
    <Cilindro p={[0.095, -0.025, 0]} raio={0.009} altura={0.02} cor={PRETO} frente sombra={false} />
  </group>
);

/** Em 90: 1% e meta em 2%. Depois, a barra chega exatamente à meta. */
export const GraficoBarrasNoQuadro: React.FC<{ quadro: number }> = ({ quadro }) => {
  const t = Math.max(0, Math.min(1, (quadro - 100) / 50));
  const altura = UNIDADE * (1 + t * t * (3 - 2 * t));
  return (
    <group>
      {/* Uma caixa: sem faces coplanares ou costuras nos cantos. Vão de 20 cm. */}
      <Caixa p={[0, 0.55, 0]} t={[0.66, 0.70, 0.08]} cor="#ffffff" />
      {/* Face até Z=0,04; inscrições começam em Z=0,07. */}
      <Caixa p={[-0.25, 0.56, 0.09]} t={[0.03, 0.50, 0.04]} cor={PRETO} sombra={false} />
      <Caixa p={[-0.095, 0.325, 0.09]} t={[0.34, 0.03, 0.04]} cor={PRETO} sombra={false} />
      {/* Meta: o topo coincide com 2%, na mesma profundidade da barra. */}
      {t === 0 && <group>
        <Caixa p={[X_BARRA, BASE_BARRA + 2 * UNIDADE - 0.009, 0.09]}
          t={[LARGURA_BARRA, 0.018, 0.04]} cor="#ffd6ad" sombra={false} />
        {[-1, 1].map((lado) => (
          <Caixa key={lado} p={[X_BARRA + lado * (LARGURA_BARRA / 2 - 0.009), BASE_BARRA + 1.5 * UNIDADE, 0.09]}
            t={[0.018, UNIDADE - 0.036, 0.04]} cor="#ffd6ad" sombra={false} />
        ))}
      </group>}
      <Caixa p={[X_BARRA, BASE_BARRA + altura / 2, 0.09]}
        t={[LARGURA_BARRA, altura, 0.04]} cor={LARANJA} sombra={false} />
      {([1, 2] as const).map((valor) => {
        const y = BASE_BARRA + valor * UNIDADE;
        return (
          <group key={valor}>
            <Caixa p={[-0.22, y, 0.09]} t={[0.08, 0.02, 0.04]} cor={PRETO} sombra={false} />
            <Porcentagem valor={valor} y={y} />
          </group>
        );
      })}
    </group>
  );
};

export const GraficoBarras: React.FC = () => {
  const quadro = useCurrentFrame();
  return <GraficoBarrasNoQuadro quadro={quadro} />;
};
