import React from 'react';
import { useCurrentFrame } from 'remotion';
import { Caixa, Elipsoide, mat } from './base';

// Bandeja de 28 × 16 cm, fundo escuro e borda prateada arredondada.
const Bandeja: React.FC = () => (
  <group>
    <Caixa p={[0, 0.006, 0]} t={[0.264, 0.012, 0.144]} cor="#9aa9b3" />
    {[-1, 1].map((lado) => (
      <React.Fragment key={lado}>
        <mesh position={[0, 0.013, lado * 0.072]} rotation={[0, 0, Math.PI / 2]} material={mat('#e7edf0')} castShadow receiveShadow>
          <capsuleGeometry args={[0.008, 0.264, 4, 12]} />
        </mesh>
        <mesh position={[lado * 0.132, 0.013, 0]} rotation={[Math.PI / 2, 0, 0]} material={mat('#e7edf0')} castShadow receiveShadow>
          <capsuleGeometry args={[0.008, 0.144, 4, 12]} />
        </mesh>
      </React.Fragment>
    ))}
  </group>
);

// Três baforadas macias; subida e ondulação dependem só do quadro.
const Fumaca: React.FC<{ quadro: number }> = ({ quadro }) => (
  <group>
    {[0, 1, 2].map((i) => {
      const fase = (quadro / 96 + i / 3) % 1;
      const volume = Math.sin(Math.PI * fase) ** 0.5;
      return (
        <mesh key={i}
          position={[Math.sin(quadro / 35 + i * 1.7) * 0.013 + (i - 1) * 0.018, 0.108 + fase * 0.17, -0.004]}
          scale={[(0.018 + fase * 0.012) * volume, (0.024 + fase * 0.014) * volume, (0.018 + fase * 0.01) * volume]}
          material={mat('#f7fafb')}>
          <sphereGeometry args={[1, 16, 12]} />
        </mesh>
      );
    })}
  </group>
);

// Pão de 20 cm: duas abas altas de casca e corte longitudinal claro.
export const PaoQuente: React.FC = () => {
  const quadro = useCurrentFrame();
  return (
    <group>
      <Bandeja />
      <Elipsoide p={[0, 0.047, 0]} t={[0.10, 0.035, 0.037]} cor="#bd762b" />
      <Elipsoide p={[0, 0.054, -0.017]} t={[0.098, 0.041, 0.021]} cor="#eab454" />
      <Elipsoide p={[0, 0.054, 0.017]} t={[0.098, 0.041, 0.021]} cor="#d99839" />
      <Elipsoide p={[0, 0.089, 0]} t={[0.080, 0.009, 0.013]} cor="#fff0bd" />
      <Elipsoide p={[0, 0.096, -0.001]} t={[0.071, 0.003, 0.004]} cor="#bc792b" />
      <Fumaca quadro={quadro} />
    </group>
  );
};
