// Moeda da sorte: 8 cm, deitada no chão, face dourada com um "1" em relevo, aro prateado e brilho (halo + estrelinhas).
// Origem no centro da base; o "1" se lê de quem olha de +Z (o topo do número aponta para -Z).
import React from 'react';
import { useCurrentFrame } from 'remotion';
import { mat } from './base';

const COR = { ouro: '#ffc21f', ouroEscuro: '#d48d0c', relevo: '#a8560a', prata: '#f1f5fa', contorno: '#46505e', reflexo: '#fff7cf', estrela: '#fffbe6', halo: '#ffe05a' };
const R = 0.04; // raio da moeda (8 cm)

/** Traço do "1" no plano da face (XZ), de (x1,z1) a (x2,z2), com largura l e altura h. */
const Traco: React.FC<{ a: [number, number]; b: [number, number]; l: number; h: number; y: number }> = ({ a, b, l, h, y }) => {
  const dx = b[0] - a[0], dz = b[1] - a[1];
  return (
    <mesh position={[(a[0] + b[0]) / 2, y + h / 2, (a[1] + b[1]) / 2]} rotation={[0, -Math.atan2(dz, dx), 0]} material={mat(COR.relevo)} castShadow receiveShadow>
      <boxGeometry args={[Math.hypot(dx, dz) + l, h, l]} />
    </mesh>
  );
};

/** Estrelinha de 4 pontas: dois elipsoides finos em cruz, acesos. */
const Estrela: React.FC<{ p: [number, number, number]; t: number }> = ({ p, t }) => (
  <group position={p} rotation={[-0.75, 0, 0]} scale={t}>
    <mesh scale={[1, 0.13, 0.13]} material={mat(COR.estrela, { brilho: 1.4 })}><sphereGeometry args={[1, 16, 8]} /></mesh>
    <mesh scale={[0.13, 1, 0.13]} material={mat(COR.estrela, { brilho: 1.4 })}><sphereGeometry args={[1, 16, 8]} /></mesh>
    <mesh scale={0.22} material={mat(COR.estrela, { brilho: 1.4 })}><sphereGeometry args={[1, 12, 8]} /></mesh>
  </group>
);

export const Moeda: React.FC = () => {
  const q = useCurrentFrame();
  // pulso lento das estrelinhas (período de 2 s, variação de ±15%: anda bem menos que 1/3 do tamanho por quadro)
  const pulso = (fase: number) => 1 + 0.15 * Math.sin(((q + fase) / 60) * Math.PI * 2);
  const yFace = 0.0075;
  return (
    <group>
      {/* halo dourado no chão (quase opaco: translúcido sobre o azul vira cinza) e sombra de contato escura logo embaixo */}
      <mesh position={[0, 0.0009, 0]} material={mat(COR.halo, { brilho: 0.7, opac: 0.85 })} renderOrder={2}><cylinderGeometry args={[R * 1.6, R * 1.6, 0.0004, 48]} /></mesh>
      <mesh position={[0.004, 0.0012, 0.003]} material={mat('#2a1a00', { opac: 0.55 })} renderOrder={3}><cylinderGeometry args={[R * 1.12, R * 1.12, 0.0004, 48]} /></mesh>

      {/* contorno escuro rente ao chão: separa a moeda do piso */}
      <mesh position={[0, 0.0016, 0]} material={mat(COR.contorno)} castShadow receiveShadow><cylinderGeometry args={[R + 0.0012, R + 0.0012, 0.003, 48]} /></mesh>
      {/* corpo dourado e aro prateado fino e redondo (toro), mais alto que a face, como numa moeda de verdade */}
      <mesh position={[0, 0.004, 0]} material={mat(COR.ouro, { brilho: 0.18 })} castShadow receiveShadow><cylinderGeometry args={[R - 0.0015, R - 0.0015, 0.007, 48]} /></mesh>
      <mesh position={[0, 0.0058, 0]} rotation={[Math.PI / 2, 0, 0]} material={mat(COR.prata, { brilho: 0.25 })} castShadow receiveShadow><torusGeometry args={[R - 0.0025, 0.0028, 12, 48]} /></mesh>
      {/* friso gravado em volta da face */}
      <mesh position={[0, yFace, 0]} rotation={[Math.PI / 2, 0, 0]} material={mat(COR.ouroEscuro)} receiveShadow><torusGeometry args={[0.03, 0.0011, 8, 48]} /></mesh>

      {/* "1" em relevo, âmbar escuro sobre o ouro: haste, bandeirinha e pé */}
      <Traco a={[0.003, 0.017]} b={[0.003, -0.018]} l={0.0075} h={0.003} y={yFace} />
      <Traco a={[0.002, -0.0165]} b={[-0.0095, -0.0085]} l={0.0065} h={0.003} y={yFace} />
      <Traco a={[-0.008, 0.0175]} b={[0.014, 0.0175]} l={0.006} h={0.003} y={yFace} />

      {/* reflexo: arco claro no canto de cima à esquerda da face + pontinho */}
      <group position={[0, yFace + 0.0004, 0]} rotation={[-Math.PI / 2, 0, 0]}>
        <mesh rotation={[0, 0, 1.75]} material={mat(COR.reflexo, { brilho: 0.7 })}><torusGeometry args={[0.0245, 0.0017, 8, 24, 1.2]} /></mesh>
      </group>
      <mesh position={[-0.0215, yFace + 0.0004, 0.0035]} scale={[1, 0.4, 1]} material={mat(COR.reflexo, { brilho: 0.7 })}><sphereGeometry args={[0.0022, 12, 8]} /></mesh>

      {/* estrelinhas de brilho em volta */}
      <Estrela p={[0.036, 0.05, -0.025]} t={0.022 * pulso(0)} />
      <Estrela p={[-0.05, 0.026, -0.006]} t={0.014 * pulso(25)} />
      <Estrela p={[0.05, 0.016, 0.03]} t={0.01 * pulso(45)} />
    </group>
  );
};
