// Rodada 2 das ações do r06 (quicarBola, sortear, abrirPacote): poses refeitas para a câmera de frente da vitrine.
// As demos '+objetos' seguem com `acoes.ts` (não foram pedidas). Mesma ideia: a mão é escrita como "onde fica"
// (metros, espaço do boneco, chão em y = 0, olhando +Z) e a IK do r05 vira juntas. +X = braço D (direita de quem olha).
// Truque comum: girar o tronco (troncoY) para o braço da ação ficar de 3/4, e não apontado para a lente.
import type { Juntas } from '../../../kit/poses';
import { ikBraco, paraTronco, ciclo } from '../r05-acao/acoes';

type V3 = [number, number, number];
type Corpo = Pick<Juntas, 'altura' | 'troncoX' | 'troncoY'>;
const GRAU = Math.PI / 180;
const suave = (t: number) => { const k = Math.min(1, Math.max(0, t)); return k * k * (3 - 2 * k); };
const braco = (lado: 1 | -1, c: Corpo, p: V3): Partial<Juntas> => {
  const b = ikBraco(lado, paraTronco(c, p));
  return lado === 1 ? { ombroDX: b.x, ombroDZ: b.z, cotoveloD: b.cot } : { ombroEX: b.x, ombroEZ: b.z, cotoveloE: b.cot };
};
/** Quanto o corpo desce com a perna dobrada (quadril q, joelho j), para o pé ficar no chão. */
const descida = (q: number, j: number) => -(0.55 - 0.25 * Math.cos(q * GRAU) - 0.3 * Math.cos((q - j) * GRAU));

// ── quicarBola ───────────────────────────────────────────────────────────
// Agachado de verdade (quadril 40°, joelho 70°), tronco 22° à frente e girado para trazer o ombro D adiante.
// Braço D quase reto para baixo, à frente e para fora da perna, mão a ~0,5 m do chão no fundo do empurrão.
// Braço E solto para trás e para fora (equilíbrio, sem subir). Cabeça virada e baixa, olhando o ponto da mão.
// Ciclo de 20 q; no quadro 90 a mão está no fundo (braço todo estendido).
const QUIQUE = 20;
const MAO_ALTA = 0.7, MAO_BAIXA = 0.44; // no fundo o braço fica quase reto (0,46 de 0,47 m)
const CORPO_QUICAR: Corpo = { altura: descida(40, 70), troncoX: 22, troncoY: -18 };
const PERNAS_QUICAR = { quadrilE: 40, joelhoE: 70, quadrilD: 40, joelhoD: 70 };
const MAO_BOLA: [number, number] = [0.36, 0.36]; // x, z da bola: fora da perna D, à frente
const MAO_SOLTA: V3 = [-0.39, 0.54, -0.04]; // pendurada, um pouco para fora e para trás
/** 0 = mão no alto (pega a bola), 0,5 = mão no fundo (empurrou). */
const tempo = (q: number) => ciclo(q, QUIQUE) / QUIQUE;
const maoQuique = (q: number): V3 => [MAO_BOLA[0], MAO_BAIXA + (MAO_ALTA - MAO_BAIXA) * Math.cos(Math.PI * tempo(q)) ** 2, MAO_BOLA[1]];
export const QUICAR: Partial<Juntas> = {
  ...PERNAS_QUICAR, ...CORPO_QUICAR, cabecaX: 10, cabecaY: 28, cabecaZ: -10,
  ...braco(1, CORPO_QUICAR, maoQuique(10)), ...braco(-1, CORPO_QUICAR, MAO_SOLTA),
};
export function quicarBola(q: number): Partial<Juntas> {
  const empurra = Math.sin(Math.PI * tempo(q)); // 1 no fundo do empurrão
  const c: Corpo = { ...CORPO_QUICAR, altura: CORPO_QUICAR.altura - 0.02 * empurra, troncoX: CORPO_QUICAR.troncoX + 3 * empurra };
  return { ...c, ...braco(1, c, maoQuique(q)), ...braco(-1, c, MAO_SOLTA), cabecaX: 7 + 4 * empurra };
}

// ── sortear ──────────────────────────────────────────────────────────────
// Tronco inclinado à frente e girado para a caixa (à esquerda de quem olha, na altura da cintura).
// Braço E estendido para a frente e para baixo, mão dentro da caixa, remexendo em círculos curtos.
// Braço D dobrado com a mão no alto, ao lado da cabeça (o que o revisor aprovou), mostrando o papel.
// Cabeça inclinada e virada para o papel.
const CORPO_SORTEAR: Corpo = { altura: descida(10, 18), troncoX: 12, troncoY: 14 };
const NA_CAIXA: V3 = [-0.34, 0.69, 0.4]; // braço quase reto, à frente e para baixo
const PAPEL_MAO: V3 = [0.42, 1.4, 0.24];
const maoNaCaixa = (q: number): V3 => {
  const a = (2 * Math.PI * q) / 24;
  return [NA_CAIXA[0] + 0.035 * Math.sin(a), NA_CAIXA[1] + 0.02 * Math.sin(2 * a), NA_CAIXA[2] + 0.03 * Math.cos(a)];
};
const maoPapel = (q: number): V3 => {
  const a = (2 * Math.PI * q) / 16;
  return [PAPEL_MAO[0] + 0.012 * Math.sin(a), PAPEL_MAO[1] + 0.025 * Math.sin(a + 0.6), PAPEL_MAO[2]];
};
export const SORTEAR: Partial<Juntas> = {
  ...CORPO_SORTEAR, quadrilE: 10, joelhoE: 18, quadrilD: 10, joelhoD: 18,
  cabecaX: -4, cabecaY: 16, cabecaZ: -12,
  ...braco(-1, CORPO_SORTEAR, NA_CAIXA), ...braco(1, CORPO_SORTEAR, PAPEL_MAO),
};
export function sortear(q: number): Partial<Juntas> {
  const p = maoPapel(q);
  return { ...braco(-1, CORPO_SORTEAR, maoNaCaixa(q)), ...braco(1, CORPO_SORTEAR, p), cabecaY: 16 + 30 * (p[0] - PAPEL_MAO[0]) };
}

// ── abrirPacote ──────────────────────────────────────────────────────────
// Mãos à frente da barriga/peito (~25 cm do peito), separadas na horizontal, puxando uma para cada lado:
// de 22 cm para 32 cm de distância durante o rasgo, a D subindo e indo à frente, a E descendo e recuando.
// Ombros girados (troncoY) para os dois antebraços aparecerem; pé D um passo à frente; cabeça baixa nas mãos.
// Ciclo de 48 q: segura (0–6), puxa (6–36), segura aberto (36–48). No quadro 90 o puxão está no meio.
const PUXA = 48;
const rasgo = (q: number) => suave((ciclo(q - 66, PUXA) - 6) / 30);
const forcaPuxao = (q: number) => Math.sin(Math.PI * Math.min(1, Math.max(0, (ciclo(q - 66, PUXA) - 6) / 30)));
const CORPO_PACOTE: Corpo = { altura: -0.006, troncoX: 6, troncoY: -10 };
// mãos na altura da barriga, braços quase retos e descendo: o antebraço aparece inteiro na câmera alta
const maoPacote = (lado: 1 | -1, r: number): V3 => [
  lado * (0.11 + 0.05 * r), 0.88 + lado * 0.02 * r, 0.39 + lado * 0.03 * r,
];
export const ABRIR_PACOTE: Partial<Juntas> = {
  ...CORPO_PACOTE, quadrilD: 18, joelhoD: 22, quadrilE: -8, joelhoE: 4,
  cabecaX: 14, cabecaY: -6, cabecaZ: 0,
  ...braco(-1, CORPO_PACOTE, maoPacote(-1, 0.5)), ...braco(1, CORPO_PACOTE, maoPacote(1, 0.5)),
};
export function abrirPacote(q: number): Partial<Juntas> {
  const r = rasgo(q), f = forcaPuxao(q);
  const c: Corpo = { ...CORPO_PACOTE, troncoY: CORPO_PACOTE.troncoY - 4 * f, troncoX: CORPO_PACOTE.troncoX - 3 * f };
  return { ...c, ...braco(-1, c, maoPacote(-1, r)), ...braco(1, c, maoPacote(1, r)), cabecaZ: -4 * f };
}
