import React from 'react';
import { Caixa, mat } from './base';

const BRANCO = '#fffef8';
const PRETO = '#101116';
const LARGURA_CELULA = 0.0038;
const ALTURA_CELULA = 0.0048;
const DIGITOS: Record<string, string[]> = {
  '4': ['101', '101', '111', '001', '001'],
  '3': ['111', '001', '111', '001', '111'],
  '7': ['111', '001', '001', '001', '001'],
};

// Traços de 3,8 mm. Papel e tinta ocupam a mesma superfície, sem sobreposição.
const Digito: React.FC<{ valor: string }> = ({ valor }) => (
  <group>
    {DIGITOS[valor].flatMap((linha, y) => Array.from(linha, (celula, x) => (
      <Caixa key={y + '-' + x}
        p={[(x - 1) * LARGURA_CELULA, (2 - y) * ALTURA_CELULA, 0]}
        t={[LARGURA_CELULA, ALTURA_CELULA, 0.0016]} cor={celula === '1' ? PRETO : BRANCO} />
    )))}
  </group>
);

// Bilhete de 5 cm. A dobra aberta forma um apoio triangular de verdade.
export const PapelRifa: React.FC = () => {
  const altura = 0.038;
  const inclinacao = 0.45;
  const inclinacaoAba = 0.65;
  const espessura = 0.0016;
  const yPe = espessura / 2 * Math.sin(inclinacao);
  const yDobra = yPe + altura * Math.cos(inclinacao);
  const zPe = 0.014;
  const zDobra = zPe - altura * Math.sin(inclinacao);
  const aba = (yDobra - espessura / 2 * Math.sin(inclinacaoAba)) / Math.cos(inclinacaoAba);
  return (
    <group rotation={[0, -0.18, 0]}>
      <group position={[0, yPe, zPe]} rotation={[-inclinacao, 0, 0]}>
        {/* Número ocupa quase toda a largura útil da face. */}
        <Caixa p={[0, 0.0035, 0]} t={[0.05, 0.007, espessura]} cor={BRANCO} />
        <Caixa p={[0, 0.0345, 0]} t={[0.05, 0.007, espessura]} cor={BRANCO} />
        {([-1, 1] as const).map((lado) => (
          <group key={lado}>
            <Caixa p={[lado * 0.02235, 0.019, 0]} t={[0.0053, 0.024, espessura]} cor={BRANCO} />
            <Caixa p={[lado * 0.007, 0.019, 0]} t={[0.0026, 0.024, espessura]} cor={BRANCO} />
          </group>
        ))}
        {['4', '3', '7'].map((valor, i) => (
          <group key={valor} position={[(i - 1) * 0.014, 0.019, 0]}><Digito valor={valor} /></group>
        ))}
      </group>
      <group position={[0, yDobra, zDobra]} rotation={[inclinacaoAba, 0, 0]}>
        <Caixa p={[0, -aba / 2, 0]} t={[0.05, aba, espessura]} cor="#c6bfad" />
      </group>
      <mesh position={[0, yDobra, zDobra]} rotation={[0, 0, Math.PI / 2]} material={mat(BRANCO)} castShadow receiveShadow>
        <cylinderGeometry args={[espessura / 2, espessura / 2, 0.05, 10]} />
      </mesh>
    </group>
  );
};
