// Demos das 3 ações (tipo 'efeito'): o contrato `acao` só leva juntas, então a vitrine mostra o Téo
// sozinho e de mãos vazias. Aqui um coadjuvante faz a mesma ação (mesmas juntas) com o que falta:
// o "outro" sob o ombro, a escova e o copo, e a vista de lado do deitado.
import * as THREE from 'three';
import React from 'react';
import { Boneco } from '../../../kit/Boneco';
import { ELENCO } from '../../../kit/elenco';
import { BASE, type Juntas } from '../../../kit/poses';
import type { PecaOficina } from '../tipos';
import { ikBraco, paraTronco } from '../r05-acao/acoes';
import { matrizCabeca, matrizMao, posicao } from '../r05-acao/cinematica';
import { Raspadinha } from '../l16-acao/objetos';
import { juntasNoQuadro, OUTRO_INCLINAR, PERIODO_ESCOVA, vaivem } from './acoes';
import { Escova, Espuma, MarcasVaivem } from './objetos';

const v3 = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);
const R = THREE.MathUtils.degToRad;

// ── inclinar+outro: Bia sentada no chão com a raspadinha; c1 se debruça por cima do ombro dela ──
// Montado como na pose (os dois olhando +Z, Bia em OUTRO_INCLINAR), espelhado em X para a dupla ficar à
// esquerda do Téo, e girado 50° para a direita: a dobra do quadril aparece de 3/4 e a Bia fica na frente.
// No chão a cabeça dela fica a 1,03 m; a de c1, ~0,3 m mais alta, por cima do ombro dela.
const ALT_CHAO = -0.47;
const maoCarta = (lado: 1 | -1) => ikBraco(lado, paraTronco({ altura: ALT_CHAO, troncoX: 0, troncoY: 0 }, [0.08 * lado, 0.6, 0.34]));
const [cD, cE] = [maoCarta(1), maoCarta(-1)];
const SENTADA_CHAO: Juntas = {
  ...BASE, quadrilE: 135, joelhoE: 135, quadrilD: 135, joelhoD: 135, altura: ALT_CHAO, cabecaX: 20, cabecaY: 6,
  ombroDX: cD.x, ombroDZ: cD.z, cotoveloD: cD.cot, ombroEX: cE.x, ombroEZ: cE.z, cotoveloE: cE.cot,
};
const DemoInclinar: React.FC<{ quadro: number }> = ({ quadro }) => {
  const j = juntasNoQuadro('inclinar', quadro);
  const meio = new THREE.Vector3().addVectors(posicao(matrizMao(SENTADA_CHAO, 1)), posicao(matrizMao(SENTADA_CHAO, -1))).multiplyScalar(0.5);
  return (
    <group position={[-1.15, 0, -0.45]} rotation={[0, R(50), 0]} scale={[-1, 1, 1]}>
      <group position={OUTRO_INCLINAR}>
        <Boneco v={ELENCO.bia} j={SENTADA_CHAO} e={{ boca: 'aberta', olharY: -1 }} />
        {/* espelhada de volta para o "x2" ler certo */}
        <group position={[meio.x, meio.y + 0.03, meio.z + 0.02]} rotation={[-0.5, 0, 0]} scale={[-1, 1, 1]}><Raspadinha /></group>
      </group>
      <Boneco v={ELENCO.c1} j={j} e={{ boca: 'o', olharY: -1, olharX: 0.6, sobrancelha: 1 }} />
    </group>
  );
};

// ── deitar+lado: c2 deitado atravessado (giro −90°: cabeça para +X), atrás e à direita do Téo ──
// A câmera da vitrine só vê o chão até z ≈ 0,5; atrás do Téo (z −1,3) o corpo cabe inteiro.
const DemoDeitar: React.FC<{ quadro: number }> = ({ quadro }) => (
  <Boneco v={ELENCO.c2} j={juntasNoQuadro('deitar', quadro)} e={{ boca: 'sorriso', piscar: 0.55 }} pos={[1.1, 0, -1.3]} giro={-90} />
);

// ── escovarDentes+objetos: c2 com a escova da mão ao canto da boca, espuma e marcas de vaivém ──
const DemoEscovar: React.FC<{ quadro: number }> = ({ quadro }) => {
  const j = juntasNoQuadro('escovarDentes', quadro);
  const mCab = matrizCabeca(j);
  const boca = v3(0.035, -0.13, 0.3).applyMatrix4(mCab);
  const mao = posicao(matrizMao(j, 1));
  const giro = new THREE.Quaternion().setFromUnitVectors(v3(0, 1, 0), new THREE.Vector3().subVectors(mao, boca).normalize());
  const p = vaivem(quadro);
  return (
    <group position={[1.05, 0, 0.15]} rotation={[0, R(-18), 0]}>
      <Boneco v={ELENCO.c2} j={j} e={{ boca: 'aberta', olharX: 0.35, olharY: 0.2, piscar: 0.3 }} />
      <group position={boca} quaternion={giro}><Escova /></group>
      <group position={v3(0.05, -0.15, 0.31).applyMatrix4(mCab)}><Espuma fase={(quadro * Math.PI * 2) / PERIODO_ESCOVA} /></group>
      <group position={[mao.x + 0.02, mao.y + 0.02, mao.z + 0.03]}><MarcasVaivem abertura={p} /></group>
    </group>
  );
};

export const DEMOS: PecaOficina[] = [
  { tipo: 'efeito', nome: 'inclinar+outro', Componente: DemoInclinar },
  { tipo: 'efeito', nome: 'deitar+lado', Componente: DemoDeitar },
  { tipo: 'efeito', nome: 'escovarDentes+objetos', Componente: DemoEscovar },
];
