// Primitivas do lote. Medidas em metros, Y para cima.
import React from 'react';
import * as THREE from 'three';

export type V3 = [number, number, number];

const cache = new Map<string, THREE.MeshStandardMaterial>();
export const mat = (cor: string) => {
  let material = cache.get(cor);
  if (!material) {
    material = new THREE.MeshStandardMaterial({ color: cor, roughness: 0.86 });
    cache.set(cor, material);
  }
  return material;
};

const cacheVidro = new Map<string, THREE.MeshStandardMaterial>();
export const vidro = (cor: string) => {
  let material = cacheVidro.get(cor);
  if (!material) {
    material = new THREE.MeshStandardMaterial({
      color: cor, roughness: 0.86, transparent: true, opacity: 0.24, depthWrite: false,
    });
    cacheVidro.set(cor, material);
  }
  return material;
};

export const Caixa: React.FC<{
  p: V3;
  t: V3;
  cor: string;
  r?: V3;
  sombra?: boolean;
}> = ({ p, t, cor, r, sombra = true }) => (
  <mesh position={p} rotation={r} material={mat(cor)} castShadow={sombra} receiveShadow>
    <boxGeometry args={t} />
  </mesh>
);

export const Haste: React.FC<{ a: V3; b: V3; raio: number; cor: string }> = ({ a, b, raio, cor }) => {
  const inicio = new THREE.Vector3(...a);
  const fim = new THREE.Vector3(...b);
  const direcao = fim.clone().sub(inicio);
  const giro = new THREE.Quaternion().setFromUnitVectors(
    new THREE.Vector3(0, 1, 0),
    direcao.clone().normalize(),
  );
  return (
    <mesh position={inicio.add(fim).multiplyScalar(0.5)} quaternion={giro}
      material={mat(cor)} castShadow receiveShadow>
      <cylinderGeometry args={[raio, raio, direcao.length(), 10]} />
    </mesh>
  );
};
