// Base do lote l19-efeito: cache de material por cor (padrão do Quadra.tsx) e utilitários comuns.
import * as THREE from 'three';
import React from 'react';

export type V3 = [number, number, number];
export const TAU = Math.PI * 2;

const cache = new Map<string, THREE.MeshStandardMaterial>();
/** Material chapado (roughness 0,85). `brilho` > 0 acende a cor (emissivo: janela acesa, floco). */
export const mat = (cor: string, brilho = 0, rug = 0.85) => {
  const b = Math.round(brilho * 20) / 20;
  const k = `${cor}|${b}|${rug}`;
  let m = cache.get(k);
  if (!m) {
    m = new THREE.MeshStandardMaterial({ color: cor, roughness: rug });
    if (b > 0) { m.emissive = new THREE.Color(cor); m.emissiveIntensity = b; }
    cache.set(k, m);
  }
  return m;
};

/** Suaviza 0..1 (smoothstep). */
export const suave = (t: number) => { const x = Math.min(1, Math.max(0, t)); return x * x * (3 - 2 * x); };

/** Resto sempre positivo (para o loop dar a volta sem número negativo). */
export const modulo = (a: number, n: number) => ((a % n) + n) % n;

export const Caixa: React.FC<{ p: V3; t: V3; cor: string; brilho?: number; sombra?: boolean }> = ({ p, t, cor, brilho = 0, sombra = true }) => (
  <mesh position={p} material={mat(cor, brilho)} castShadow={sombra} receiveShadow><boxGeometry args={t} /></mesh>
);
