// Calendário de parede: 40 x 50 cm (origem no centro da base, frente para +Z), pendurado por uma alça de arame.
// Espiral no topo, cabeçalho vermelho com "07" e "2026", linha dos dias da semana e grade 7 x 5 (julho/2026,
// começa na quarta). O dia 25 tem uma casa amarela e um círculo vermelho grosso de caneta.
// Sem linhas finas: a grade são casas cinza-claras separadas por vãos brancos de 6 mm.
import React, { useMemo } from 'react';
import { Cil, Ret, Tracos, mat, numero, type Seg } from './base';

export const CAL = { larg: 0.4, alt: 0.5, esp: 0.006 };
const C = {
  costas: '#d6d2c8', folha: '#ffffff', casa: '#e9ebef', vermelho: '#d8343a', branco: '#ffffff',
  tinta: '#33363d', semana: '#8a8f99', metal: '#7d838c', destaque: '#ffe27a',
};
const INICIO = 3, DIAS = 31, DIA = 25; // julho/2026: dia 1 numa quarta (coluna 3, domingo = 0)

// camadas em Z (frente): costas 0–6 mm, folha até 9 mm, casas até 10 mm, dígitos até 11 mm, círculo ~12 mm
const ZF = 0.0075, ZC = 0.0095, ZD = 0.0105;
// grade: 7 colunas x 5 linhas entre x ±0,18 e y 0,02–0,31
const COL = 0.36 / 7, LIN = 0.058, Y0 = 0.02 + LIN / 2;
const xCol = (c: number) => -0.18 + COL * (c + 0.5);
const yLin = (l: number) => Y0 + LIN * (4 - l);
// dígito da grade: 1,3 x 2,6 cm, traço de 4,2 mm
const DG = { w: 0.013, h: 0.026, s: 0.0042, vao: 0.0035 };

export const Calendario: React.FC = () => {
  const { tinta, domingo, cabecalho } = useMemo(() => {
    const tinta: Seg[] = [], domingo: Seg[] = [];
    for (let d = 1; d <= DIAS; d++) {
      const i = INICIO + d - 1, c = i % 7, l = Math.floor(i / 7);
      (c === 0 ? domingo : tinta).push(...numero(String(d), xCol(c), yLin(l), DG.w, DG.h, DG.s, DG.vao));
    }
    // cabeçalho: mês grande à esquerda, ano à direita (brancos sobre o vermelho)
    const cabecalho = [...numero('07', -0.115, 0.405, 0.032, 0.058, 0.011, 0.009), ...numero('2026', 0.085, 0.398, 0.022, 0.04, 0.0078, 0.007)];
    return { tinta, domingo, cabecalho };
  }, []);
  const i25 = INICIO + DIA - 1, x25 = xCol(i25 % 7), y25 = yLin(Math.floor(i25 / 7));

  return (
    <group>
      {/* costas de papelão e folha */}
      <Ret w={CAL.larg} h={CAL.alt} d={CAL.esp} r={0.012} p={[0, CAL.alt / 2, CAL.esp / 2]} cor={C.costas} sombra />
      <Ret w={0.388} h={0.448} d={0.003} r={0.008} p={[0, 0.234, ZF]} cor={C.folha} />
      {/* cabeçalho vermelho */}
      <Ret w={0.37} h={0.096} d={0.002} r={0.008} p={[0, 0.4, ZC]} cor={C.vermelho} />
      <Tracos segs={cabecalho} z={ZD + 0.001} prof={0.001} cor={C.branco} />
      {/* dias da semana: traços curtos (domingo em vermelho) */}
      {Array.from({ length: 7 }, (_, c) => (
        <Ret key={c} w={0.026} h={0.009} d={0.001} r={0.004} p={[xCol(c), 0.333, ZC]} cor={c === 0 ? C.vermelho : C.semana} />
      ))}
      {/* casas da grade (a do dia 25 em amarelo) */}
      {Array.from({ length: 35 }, (_, i) => (
        <Ret key={i} w={COL - 0.006} h={LIN - 0.006} d={0.001} r={0.004} p={[xCol(i % 7), yLin(Math.floor(i / 7)), ZC]}
          cor={i === i25 ? C.destaque : C.casa} />
      ))}
      <Tracos segs={tinta} z={ZD} prof={0.001} cor={C.tinta} />
      <Tracos segs={domingo} z={ZD} prof={0.001} cor={C.vermelho} />
      {/* círculo de caneta no 25: grosso (1 cm), um pouco oval e torto, por cima de tudo */}
      <mesh position={[x25, y25, 0.0125]} rotation={[0, 0, 0.35]} scale={[1, 1.14, 0.35]} material={mat(C.vermelho, 0.7)} castShadow>
        <torusGeometry args={[0.0285, 0.005, 10, 40]} />
      </mesh>
      {/* espiral de arame no topo e alça de pendurar */}
      {Array.from({ length: 15 }, (_, k) => (
        <mesh key={k} position={[-0.168 + k * 0.024, CAL.alt - 0.006, 0.004]} rotation={[0, Math.PI / 2, 0]} material={mat(C.metal, 0.45, 0.6)} castShadow>
          <torusGeometry args={[0.0085, 0.0017, 6, 16]} />
        </mesh>
      ))}
      {([-1, 1] as const).map((l) => (
        <Cil key={l} p={[l * 0.022, CAL.alt + 0.016, 0.004]} raio={0.0016} h={0.05} r={[0, 0, l * 1.0]} cor={C.metal} m={mat(C.metal, 0.45, 0.6)} />
      ))}
    </group>
  );
};
