// Primitivas em metros; frente para +Z.
import React from 'react';
import * as THREE from 'three';

export type V3 = [number, number, number];
const cache = new Map<string, THREE.MeshStandardMaterial>();
export const mat = (cor: string) => {
  let material = cache.get(cor);
  if (!material) {
    material = new THREE.MeshStandardMaterial({
      color: cor, roughness: 0.85, metalness: 0, side: THREE.DoubleSide,
      emissive: cor, emissiveIntensity: 0.18,
    });
    cache.set(cor, material);
  }
  return material;
};

export const Caixa: React.FC<{ p: V3; t: V3; cor: string; giro?: number; sombra?: boolean }> = ({ p, t, cor, giro = 0, sombra = true }) => (
  <mesh position={p} rotation={[0, 0, giro]} material={mat(cor)} castShadow={sombra} receiveShadow>
    <boxGeometry args={t} />
  </mesh>
);

export const Cilindro: React.FC<{
  p: V3; raio: number; altura: number; cor: string;
  raioBase?: number; frente?: boolean; aberto?: boolean; sombra?: boolean;
}> = ({ p, raio, altura, cor, raioBase = raio, frente = false, aberto = false, sombra = true }) => (
  <mesh position={p} rotation={frente ? [Math.PI / 2, 0, 0] : [0, 0, 0]} material={mat(cor)} castShadow={sombra} receiveShadow>
    <cylinderGeometry args={[raio, raioBase, altura, 40, 1, aberto]} />
  </mesh>
);
