// Base do lote r17-objeto: cache de material por cor e primitivas posicionadas (caixa, cilindro).
import * as THREE from 'three';
import React from 'react';

const cache = new Map<string, THREE.MeshStandardMaterial>();
/** Material chapado (roughness 0.85 por padrão), um por cor+rugosidade+brilho próprio (emissivo, 0 a 1). */
export const mat = (cor: string, rug = 0.85, brilho = 0) => {
  const k = `${cor}|${rug}|${brilho}`;
  let m = cache.get(k);
  if (!m) {
    m = new THREE.MeshStandardMaterial({ color: cor, roughness: rug });
    if (brilho > 0) { m.emissive = new THREE.Color(cor); m.emissiveIntensity = brilho; }
    cache.set(k, m);
  }
  return m;
};

export type V3 = [number, number, number];
type Sombra = { sombra?: boolean; recebe?: boolean };

export const Caixa: React.FC<{ p: V3; t: V3; cor: string; r?: V3; m?: THREE.Material } & Sombra> = ({ p, t, cor, r, m, sombra = true, recebe = true }) => (
  <mesh position={p} rotation={r} material={m ?? mat(cor)} castShadow={sombra} receiveShadow={recebe}><boxGeometry args={t} /></mesh>
);

/** Cilindro em pé (eixo Y); `r` gira (ex.: [PI/2,0,0] deita o disco de frente para +Z). */
export const Cil: React.FC<{ p: V3; raio: number; h: number; cor: string; lados?: number; r?: V3 } & Sombra> = ({ p, raio, h, cor, lados = 24, r, sombra = true, recebe = true }) => (
  <mesh position={p} rotation={r} material={mat(cor)} castShadow={sombra} receiveShadow={recebe}><cylinderGeometry args={[raio, raio, h, lados]} /></mesh>
);

/** Mistura duas cores hex (t = 0 → a, 1 → b). */
export const misturarCor = (a: string, b: string, t: number) => `#${new THREE.Color(a).lerp(new THREE.Color(b), t).getHexString()}`;
