import React from 'react';
import { useCurrentFrame } from 'remotion';
import { Caixa, mat } from './base';

export const PaoQuente: React.FC = () => {
  const quadro = useCurrentFrame();
  return (
    <group>
      {/* Bandeja de 27 × 18 cm com bordas altas e claras. */}
      <Caixa p={[0, 0.005, 0]} t={[0.27, 0.01, 0.18]} cor="#a1b1c0" metal={0.3} />
      {[-1, 1].map((lado) => (
        <group key={lado}>
          <Caixa p={[0, 0.023, lado * 0.085]} t={[0.27, 0.036, 0.01]} cor="#e4edf5" metal={0.3} />
          <Caixa p={[lado * 0.13, 0.023, 0]} t={[0.01, 0.036, 0.16]} cor="#e4edf5" metal={0.3} />
        </group>
      ))}
      <mesh position={[0, 0.039, 0]} scale={[0.1, 0.029, 0.045]} material={mat('#bd7c29')} castShadow receiveShadow>
        <sphereGeometry args={[1, 24, 14]} />
      </mesh>
      {/* Sulco escuro contínuo entre as duas metades douradas. */}
      <mesh position={[0, 0.062, 0]} scale={[0.086, 0.011, 0.017]} material={mat('#8c4e1d')} castShadow receiveShadow>
        <sphereGeometry args={[1, 24, 12]} />
      </mesh>
      {[-1, 1].map((lado) => (
        <mesh key={lado} position={[0, 0.049, lado * 0.027]} scale={[0.098, 0.033, 0.022]}
          material={mat('#efb548')} castShadow receiveShadow>
          <sphereGeometry args={[1, 24, 14]} />
        </mesh>
      ))}
      {/* Três fios contínuos de vapor. As esferas sempre se sobrepõem. */}
      {[-1, 0, 1].map((coluna) => (
        <group key={coluna}>
          {Array.from({ length: 10 }, (_, i) => {
            const raio = 0.012 - i * 0.00075;
            const curva = Math.sin(i * 0.47 - quadro * 0.025 + coluna) * (0.003 + i * 0.0008);
            return (
              <mesh key={i} position={[coluna * 0.052 + curva, 0.089 + i * 0.014, 0]}
                scale={[raio, raio * 1.8, raio * 0.75]} material={mat('#ffffff', 0.15)}>
                <sphereGeometry args={[1, 12, 8]} />
              </mesh>
            );
          })}
        </group>
      ))}
    </group>
  );
};
