// Entrada voltada para +Z. Portão e construções ficam atrás da área de atuação.
import React from 'react';
import type { LimitesCenario } from '../tipos';
import { Ambiente, Arvore, Caixa, Haste, type V3 } from './base';

const C = {
  muro: '#f2bd35', topo: '#ffe5ac', pilar: '#f9edcd', metal: '#a4adb1', metalEscuro: '#7b898e',
  placa: '#285a79', branco: '#fff4da', janela: '#77b6cb', escola: '#f4dfab',
  calcada: '#e4d8c0', piso: '#c5b695', rua: '#90999d', grama: '#9bc77d', telhado: '#cc7755', guarita: '#69a99d',
};

export const LIMITES_PORTAO: LimitesCenario = { limiteX: 1.4, limiteZ: [-1, 3], ceu: '#d4edfa' };

// Letras de traços grossos, lidas de frente (+Z), sem fonte.
const SEGMENTOS: Record<string, string> = { E: 'afged', S: 'afgcd', C: 'afed', O: 'abcdef', L: 'fed', A: 'abcefg' };
const TRACOS: Record<string, { p: V3; t: V3 }> = {
  a: { p: [0, 0.25, 0], t: [0.42, 0.1, 0.1] },
  g: { p: [0, 0, 0], t: [0.42, 0.1, 0.1] },
  d: { p: [0, -0.25, 0], t: [0.42, 0.1, 0.1] },
  f: { p: [-0.2, 0.125, 0], t: [0.1, 0.25, 0.1] },
  b: { p: [0.2, 0.125, 0], t: [0.1, 0.25, 0.1] },
  e: { p: [-0.2, -0.125, 0], t: [0.1, 0.25, 0.1] },
  c: { p: [0.2, -0.125, 0], t: [0.1, 0.25, 0.1] },
};

const Placa: React.FC = () => (
  <group position={[0, 3.05, -3.6]}>
    <Caixa p={[0, 0, 0]} t={[5.9, 0.94, 0.24]} cor={C.placa} />
    <Caixa p={[0, 0.52, 0]} t={[6.12, 0.1, 0.4]} cor={C.topo} />
    {'ESCOLA'.split('').map((letra, i) => (
      <group key={i} position={[-1.625 + i * 0.65, 0, 0.2]}>
        {SEGMENTOS[letra].split('').map((segmento) => <Caixa key={segmento} {...TRACOS[segmento]} cor={C.branco} sombra={false} />)}
      </group>
    ))}
    {/* Livro aberto, em relevo, nas duas pontas da placa. */}
    {[-2.5, 2.5].map((x) => (
      <group key={x} position={[x, 0, 0.2]}>
        <Caixa p={[-0.12, 0, 0]} t={[0.2, 0.35, 0.1]} r={[0, 0, 0.14]} cor={C.branco} sombra={false} />
        <Caixa p={[0.12, 0, 0]} t={[0.2, 0.35, 0.1]} r={[0, 0, -0.14]} cor={C.branco} sombra={false} />
      </group>
    ))}
  </group>
);

const FolhaPortao: React.FC<{ lado: -1 | 1 }> = ({ lado }) => (
  // Abertura de 130° para fora, inteiramente nas laterais da área de atuação.
  <group position={[lado * 2.4, 0, -3.27]}>
    {[0.4, 1.95].map((y) => <Haste key={y} a={[0, y - 0.15, 0]} b={[0, y + 0.15, 0]} r={0.11} cor={C.metalEscuro} />)}
    <group rotation={[0, lado * 130 * Math.PI / 180, 0]}>
      <group position={[-lado * 1.16, 0, 0]}>
        {[0.2, 1.15, 2.2].map((y) => <Caixa key={y} p={[0, y, 0]} t={[2.32, 0.16, 0.18]} cor={C.metalEscuro} />)}
        {[-1.08, 1.08].map((x) => <Caixa key={x} p={[x, 1.2, 0]} t={[0.16, 2.16, 0.18]} cor={C.metalEscuro} />)}
        {[-0.72, -0.36, 0, 0.36, 0.72].map((x) => <Caixa key={x} p={[x, 1.2, 0]} t={[0.16, 1.94, 0.16]} cor={C.metal} sombra={false} />)}
        <Caixa p={[-lado * 0.89, 1.04, 0.17]} t={[0.12, 0.3, 0.12]} cor={C.branco} />
      </group>
    </group>
  </group>
);

const Guarita: React.FC = () => (
  <group position={[5.65, 0, -4.05]}>
    <Caixa p={[0, 1.2, 0]} t={[1.8, 2.4, 1.8]} cor={C.guarita} />
    <Caixa p={[0, 0.3, 0]} t={[1.84, 0.6, 1.84]} cor="#427b73" />
    <Caixa p={[0, 2.5, 0]} t={[2.22, 0.2, 2.22]} cor="#a64e3a" />
    <Caixa p={[0, 2.66, 0]} t={[1.92, 0.12, 1.92]} cor={C.telhado} />
    {/* Vidro opaco e caixilho: superfícies avançam pelo menos 2 cm. */}
    <Caixa p={[0, 1.56, 1]} t={[1.35, 0.86, 0.12]} cor={C.janela} sombra={false} />
    {[-0.72, 0.72].map((x) => <Caixa key={x} p={[x, 1.56, 1.15]} t={[0.12, 1.1, 0.12]} cor={C.branco} />)}
    {[1.06, 2.06].map((y) => <Caixa key={y} p={[0, y, 1.15]} t={[1.56, 0.12, 0.12]} cor={C.branco} />)}
    <Caixa p={[0, 1.56, 1.15]} t={[0.1, 0.9, 0.12]} cor={C.branco} />
    <Caixa p={[0, 1, 1.18]} t={[1.66, 0.12, 0.4]} cor={C.metalEscuro} />
    <Caixa p={[-1, 1.03, 0]} t={[0.12, 2.06, 0.8]} cor={C.placa} />
    <Caixa p={[-1.15, 1.05, 0.22]} t={[0.12, 0.12, 0.12]} cor={C.branco} />
  </group>
);

export const PortaoEscola: React.FC = () => (
  <group>
    <Ambiente manha />
    {/* Gramado e passeio em y=0, separados pelas bordas; rua rebaixada. */}
    {[-1, 1].map((lado) => <Caixa key={lado} p={[lado * 16.175, -0.1, -20]}
      t={[27.65, 0.2, 33.2]} cor={C.grama} sombra={false} />)}
    <Caixa p={[0, -0.1, -24.9]} t={[4.7, 0.2, 28.6]} cor={C.grama} sombra={false} />
    <Caixa p={[0, -0.1, -2.25]} t={[32, 0.2, 2.3]} cor={C.calcada} sombra={false} />
    <Caixa p={[0, -0.1, -0.95]} t={[32, 0.2, 0.3]} cor={C.piso} sombra={false} />
    <Caixa p={[0, -0.1, -0.02]} t={[32, 0.2, 1.56]} cor={C.calcada} sombra={false} />
    <Caixa p={[0, -0.24, 8]} t={[60, 0.2, 13.4]} cor={C.rua} sombra={false} />
    <Caixa p={[0, -0.1, 1.4]} t={[32, 0.2, 0.2]} cor={C.branco} sombra={false} />
    {/* Faixas adjacentes, sem faces sobrepostas no piso. */}
    <Caixa p={[0, -0.1, 1.03]} t={[32, 0.2, 0.54]} cor={C.piso} sombra={false} />
    <Caixa p={[0, -0.1, -7]} t={[4.7, 0.2, 7.2]} cor={C.calcada} sombra={false} />
    {[-1, 1].map((lado) => (
      <group key={lado}>
        {/* O trecho direito recua para expor a guarita inteira. */}
        <Caixa p={[lado * 8, 0.95, lado === 1 ? -7 : -3.6]} t={[10.7, 1.9, 0.36]} cor={C.muro} />
        <Caixa p={[lado * 8, 1.98, lado === 1 ? -7 : -3.6]} t={[10.7, 0.16, 0.44]} cor={C.topo} />
        <Caixa p={[lado * 2.65, 1.35, -3.6]} t={[0.5, 2.7, 0.58]} cor={C.pilar} />
        <Caixa p={[lado * 2.65, 2.72, -3.6]} t={[0.68, 0.16, 0.74]} cor={C.topo} />
      </group>
    ))}
    <FolhaPortao lado={-1} />
    <FolhaPortao lado={1} />
    <Placa />
    <Guarita />
    {/* Bloco escolar simples, visto através do portão. */}
    <Caixa p={[0, 1.8, -11.2]} t={[13, 3.6, 2.8]} cor={C.escola} />
    <Caixa p={[0, 3.7, -11.2]} t={[13.4, 0.2, 3.2]} cor={C.telhado} />
    {[-5, -2.5, 0, 2.5, 5].map((x) => [1.2, 2.65].map((y) => (
      <group key={`${x}-${y}`}>
        <Caixa p={[x, y, -9.68]} t={[1.65, 0.9, 0.12]} cor={C.placa} sombra={false} />
        <Caixa p={[x, y, -9.54]} t={[0.12, 0.9, 0.12]} cor={C.branco} sombra={false} />
      </group>
    )))}
    <Arvore p={[-5.5, 0, -8.3]} />
    {/* Banco lateral, fora da frente livre. */}
    <Caixa p={[-5.25, 0.48, -2.7]} t={[1.6, 0.16, 0.54]} cor={C.telhado} />
    <Caixa p={[-5.25, 0.88, -2.92]} t={[1.6, 0.44, 0.12]} cor={C.telhado} />
    {[-5.8, -4.7].map((x) => <Caixa key={x} p={[x, 0.2, -2.7]} t={[0.18, 0.4, 0.44]} cor={C.metalEscuro} />)}
  </group>
);
