// Ajuste só da vitrine. Os modelos exportados continuam na origem, sem câmera.
import React, { useLayoutEffect } from 'react';
import { useThree } from '@react-three/fiber';
import { useVideoConfig } from 'remotion';
import type { PerspectiveCamera } from 'three';
import type { V3 } from './base';

type Plano = { centroX: number; centroY: number; fov: number; deslocamento: V3 };

const PLANOS = {
  silhueta: { centroX: 0.55, centroY: 0.95, fov: 58, deslocamento: [0.3, 0, 0] },
  x: { centroX: 1.15, centroY: 1.03, fov: 58, deslocamento: [0.85, 0, 0] },
  contador: { centroX: 1.55, centroY: 0.94, fov: 64, deslocamento: [1.4, 0, 0] },
} satisfies Record<string, Plano>;

const AjustarCameraExistente: React.FC<{ plano: Plano }> = ({ plano }) => {
  const camera = useThree((estado) => estado.camera) as PerspectiveCamera;
  // Depois da câmera do palco, em cada atualização React, sem loop próprio.
  useLayoutEffect(() => {
    camera.position.set(plano.centroX, plano.centroY, 2.4);
    camera.lookAt(plano.centroX, plano.centroY, 0);
    camera.fov = plano.fov;
    camera.zoom = 1;
    camera.updateProjectionMatrix();
    camera.updateMatrixWorld();
  });
  return null;
};

export function apresentar(Componente: React.FC, nome: keyof typeof PLANOS): React.FC {
  return function PecaNaVitrine() {
    const { id } = useVideoConfig();
    if (id !== 'VitrineLote') return <Componente />;
    const plano = PLANOS[nome];
    return (
      <>
        <AjustarCameraExistente plano={plano} />
        <group position={plano.deslocamento}><Componente /></group>
      </>
    );
  };
}
