// Papel de 20 x 10 cm. A mão é opcional para encaixe na mão do elenco.
import React from 'react';
import { Caixa, mat, numero, Papel, type Retangulo } from './base';

const C = { papel: '#daf0bc', borda: '#92b577', tinta: '#102d24', azul: '#1963ed', tampa: '#173c88', pele: '#f3c9a0' };
const tintas: Retangulo[] = [
  { x: 0, y: 0.090, l: 0.184, a: 0.010, cor: C.tinta },
  // A grade é o alinhamento das casas: sem reticulado minúsculo.
  ...Array.from({ length: 60 }, (_, i) => numero(String(i + 1), -0.081 + (i % 10) * 0.018,
    0.074 - Math.floor(i / 10) * 0.012, 0.009, 0.00105, C.tinta)).flat(),
  { x: -0.039, y: 0.005, l: 0.102, a: 0.003, cor: C.tinta },
];

const Caneta: React.FC = () => (
  <group position={[0.020, 0.116, 0.030]} rotation={[0, 0, -1.35]}>
    <mesh material={mat(C.azul)} castShadow><cylinderGeometry args={[0.005, 0.005, 0.092, 16]} /></mesh>
    <mesh position={[0, 0.057, 0]} material={mat(C.tampa)} castShadow><capsuleGeometry args={[0.006, 0.020, 4, 16]} /></mesh>
    <Caixa p={[0, 0.056, 0.006]} t={[0.003, 0.022, 0.003]} cor={C.azul} sombra={false} />
    <mesh position={[0, -0.052, 0]} material={mat('#eee0ba')} castShadow><cylinderGeometry args={[0.005, 0.0015, 0.012, 12]} /></mesh>
    <mesh position={[0, -0.059, 0]} material={mat(C.tampa)}><cylinderGeometry args={[0.0015, 0.0006, 0.002, 8]} /></mesh>
  </group>
);

const Mao: React.FC = () => (
  <group>
    {/* Palma atrás do papel e polegar sobre a margem, sem cobrir os números. */}
    <mesh position={[-0.107, -0.016, -0.035]} scale={[0.8, 0.85, 0.55]} material={mat(C.pele)} castShadow>
      <sphereGeometry args={[0.040, 20, 12]} />
    </mesh>
    {[0, 1, 2].map((i) => (
      <mesh key={i} position={[-0.125 + i * 0.014, -0.009, -0.013]} material={mat(C.pele)} castShadow>
        <capsuleGeometry args={[0.008, 0.023, 4, 12]} />
      </mesh>
    ))}
    <mesh position={[-0.106, 0.021, 0.008]} rotation={[0, 0, -0.2]} material={mat(C.pele)} castShadow>
      <capsuleGeometry args={[0.009, 0.021, 4, 12]} />
    </mesh>
  </group>
);

export const VolanteLoteria: React.FC<{ comMao?: boolean }> = ({ comMao = true }) => (
  <group position={[0, comMao ? 0.05 : 0, 0]}>
    <Papel l={0.20} a={0.10} e={0.0012} cor={C.papel} borda={C.borda} tintas={tintas} />
    <Caneta />
    {comMao && <Mao />}
  </group>
);
