// Pós-processamento do visual do canal: profundidade de campo (DOF) na cena 3D; vinheta e grão em CSS por cima.
import React, { useEffect, useMemo } from 'react';
import * as THREE from 'three';
import { useFrame, useThree } from '@react-three/fiber';
import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass.js';
import { BokehPass } from 'three/examples/jsm/postprocessing/BokehPass.js';
import { OutputPass } from 'three/examples/jsm/postprocessing/OutputPass.js';
import { AbsoluteFill, random } from 'remotion';

/** DOF: foco em metros a partir da câmera. Assume o desenho do quadro (prioridade 1). */
export const Foco: React.FC<{ foco: number; abertura?: number; max?: number }> = ({ foco, abertura = 0.0009, max = 0.004 }) => {
  const { gl, scene, camera, size } = useThree();
  const [comp, bokeh] = useMemo(() => {
    // alvo com MSAA: sem isso o compositor perde o antialias e as linhas finas "tremem" de um quadro para o outro
    const alvo = new THREE.WebGLRenderTarget(size.width, size.height, { samples: 8, type: THREE.HalfFloatType });
    const c = new EffectComposer(gl, alvo); c.addPass(new RenderPass(scene, camera));
    const b = new BokehPass(scene, camera, { focus: foco, aperture: abertura, maxblur: max });
    c.addPass(b); c.addPass(new OutputPass()); return [c, b];
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [gl, scene, camera]);
  useEffect(() => { comp.setSize(size.width, size.height); }, [comp, size]);
  (bokeh.uniforms as any).focus.value = foco;
  useFrame(() => { comp.render(); }, 1);
  return null;
};

/** Vinheta + grão (o grão muda a cada quadro, de forma determinística). */
export const Acabamento: React.FC<{ quadro: number }> = ({ quadro }) => {
  const sem = Math.floor(random(`grao-${quadro}`) * 1000);
  return (
    <AbsoluteFill style={{ pointerEvents: 'none' }}>
      <AbsoluteFill style={{ background: 'radial-gradient(ellipse at center, rgba(0,0,0,0) 55%, rgba(0,0,0,0.38) 100%)' }} />
      <svg width="100%" height="100%" style={{ position: 'absolute', opacity: 0.07, mixBlendMode: 'overlay' }}>
        <filter id={`g${sem}`}><feTurbulence type="fractalNoise" baseFrequency="0.9" numOctaves={2} seed={sem} /></filter>
        <rect width="100%" height="100%" filter={`url(#g${sem})`} />
      </svg>
    </AbsoluteFill>
  );
};
