// Nota de 100: folha verde-clara em pé (origem no meio da borda de baixo, frente para +Z), "100" verde-escuro
// grosso e arredondado nas duas faces. Sem moldura preta: só duas faixas laterais num verde do meio.
// Medida: 16 x 8 cm (na proporção da mão de 14 cm do boneco, os 12 x 6 cm viravam um selo; a razão 2:1 ficou).
import React from 'react';
import { Caixa, Cil, mat, type V3 } from './base';

export const NOTA = { larg: 0.16, alt: 0.08, esp: 0.002 };
const CLARO = '#bfe8a6', MEIO = '#93d17d', TINTA = '#2d6a35';
const tinta = mat(TINTA, 0.8);

// "100": altura 4,2 cm, traço de 8,4 mm; o relevo é achatado (sobe ~1,3 mm da face)
const H = 0.042, TR = 0.0042, RZ = 0.0105; // altura, raio do traço, raio da curva do zero
const ACHATA: V3 = [1, 1, 0.3];

/** Traço reto arredondado (cápsula) de comprimento `c` entre as pontas das curvas, girado `ang` graus. */
const Traco: React.FC<{ p: V3; c: number; ang?: number }> = ({ p, c, ang = 0 }) => (
  <mesh position={p} rotation={[0, 0, (ang * Math.PI) / 180]} scale={ACHATA} material={tinta}>
    <capsuleGeometry args={[TR, c, 6, 16]} />
  </mesh>
);
/** Zero "estádio": meia-rosca em cima e embaixo + dois traços retos (traço com a mesma grossura em volta). */
const Zero: React.FC<{ x: number }> = ({ x }) => {
  const reto = H - 2 * (RZ + TR);
  return (
    <group position={[x, 0, 0]}>
      {[1, -1].map((l) => (
        <mesh key={l} position={[0, (l * reto) / 2, 0]} rotation={[0, 0, l > 0 ? 0 : Math.PI]} scale={ACHATA} material={tinta}>
          <torusGeometry args={[RZ, TR, 10, 24, Math.PI]} />
        </mesh>
      ))}
      {[1, -1].map((l) => (
        <mesh key={l} position={[l * RZ, 0, 0]} scale={ACHATA} material={tinta}>
          <cylinderGeometry args={[TR, TR, reto + 0.0004, 12]} />
        </mesh>
      ))}
    </group>
  );
};
/** "1": haste em pé + bandeirinha (sem pé, para não virar "I"). */
const Um: React.FC<{ x: number }> = ({ x }) => (
  <group position={[x, 0, 0]}>
    <Traco p={[0, 0, 0]} c={H - 2 * TR} />
    {/* bandeira: desce do topo da haste para a esquerda */}
    <Traco p={[-0.0035, H / 2 - TR - 0.0024, 0]} c={0.0085} ang={-55} />
  </group>
);
/** "100" centrado na origem, no plano XY. */
const Cem: React.FC = () => {
  // largura: bandeira+haste 1,35 cm, zeros 2,94 cm, vãos 4–7 mm; total ~8,4 cm entre as faixas (10,8 cm livres)
  const xZ1 = -0.0076, xZ2 = 0.026;
  return (
    <group position={[0.0014, 0, 0]}>
      <Um x={-0.030} />
      <Zero x={xZ1} />
      <Zero x={xZ2} />
    </group>
  );
};

export const NotaCem: React.FC = () => {
  const { larg: L, alt: A, esp: E } = NOTA, r = 0.007, y = A / 2;
  const faixa = 0.02, recuo = 0.006, xf = L / 2 - recuo - faixa / 2;
  return (
    <group>
      {/* folha com cantos arredondados: duas caixas em cruz + 4 discos nos cantos */}
      <Caixa p={[0, y, 0]} t={[L - 2 * r, A, E]} cor={CLARO} />
      <Caixa p={[0, y, 0]} t={[L, A - 2 * r, E]} cor={CLARO} />
      {[[-1, -1], [-1, 1], [1, -1], [1, 1]].map(([sx, sy], i) => (
        <Cil key={i} p={[sx * (L / 2 - r), y + sy * (A / 2 - r), 0]} raio={r} h={E} cor={CLARO} lados={16} r={[Math.PI / 2, 0, 0]} />
      ))}
      {/* faixas laterais (0,8 mm mais grossas que a folha: aparecem nas duas faces) com um selo redondo */}
      {[-1, 1].map((l) => (
        <group key={l}>
          <Caixa p={[l * xf, y, 0]} t={[faixa, A - 2 * recuo, E + 0.0008]} cor={MEIO} sombra={false} />
          <Cil p={[l * xf, y, 0]} raio={0.0062} h={E + 0.0016} cor={TINTA} lados={20} r={[Math.PI / 2, 0, 0]} sombra={false} />
        </group>
      ))}
      {/* "100" na frente e atrás (atrás, girado 180°: lê certo de costas) */}
      <group position={[0, y, E / 2 + 0.0002]}><Cem /></group>
      <group position={[0, y, -E / 2 - 0.0002]} rotation={[0, Math.PI, 0]}><Cem /></group>
    </group>
  );
};
