// Formas em metros e materiais compartilhados por cor.
import React from 'react';
import * as THREE from 'three';

export type V3 = [number, number, number];

const cache = new Map<string, THREE.MeshStandardMaterial>();
export const mat = (cor: string, brilho = 0, vertices = false) => {
  const chave = `${cor}|${brilho}|${vertices}`;
  let material = cache.get(chave);
  if (!material) {
    material = new THREE.MeshStandardMaterial({
      color: cor, roughness: 0.85, metalness: 0, vertexColors: vertices,
      emissive: cor, emissiveIntensity: brilho,
      toneMapped: brilho === 0,
    });
    cache.set(chave, material);
  }
  return material;
};

export const Caixa: React.FC<{
  p: V3; t: V3; cor: string; sombra?: boolean; brilho?: number;
}> = ({ p, t, cor, sombra = true, brilho = 0 }) => (
  <mesh position={p} material={mat(cor, brilho)} castShadow={sombra} receiveShadow>
    <boxGeometry args={t} />
  </mesh>
);
