import React from 'react';
import { Arredondado as FormaArredondada, Caixa as FormaCaixa, mat } from './formas';

// Relevos milimétricos não recebem sombras: evita costuras no vidro.
const Arredondado: React.FC<React.ComponentProps<typeof FormaArredondada>> = (props) => (
  <FormaArredondada {...props} sombra={false} receberSombra={false} />
);
const Caixa: React.FC<React.ComponentProps<typeof FormaCaixa>> = (props) => (
  <FormaCaixa {...props} sombra={false} receberSombra={false} />
);

export const Celular: React.FC<{ telaAcesa?: boolean }> = ({ telaAcesa = true }) => (
  <group>
    <FormaArredondada largura={0.075} altura={0.155} fundo={0.007} raio={0.011} material={mat('#738dcd')} receberSombra={false} />
    <group position={[0, 0, 0.0038]}>
      <Arredondado largura={0.069} altura={0.149} fundo={0.0004} raio={0.009} material={mat('#172335', 0.25)} />
    </group>
    <group position={[0, 0, 0.0043]}>
      <Arredondado largura={0.062} altura={0.138} fundo={0.0002} raio={0.006} material={mat(telaAcesa ? '#e8f3f0' : '#080e18', telaAcesa ? 0.85 : 0.16)} />
    </group>
    {telaAcesa && (
      <group position={[0, 0, 0.0047]}>
        <Caixa p={[-0.006, 0.052, 0]} t={[0.032, 0.006, 0.0005]} cor="#9bb5c9" />
        <Caixa p={[0.021, 0.052, 0]} t={[0.006, 0.006, 0.0005]} cor="#61a586" />
        {['#eab754', '#689cd5', '#d67e87', '#71b49e'].map((cor, i) => (
          <group key={cor} position={[(i % 2 - 0.5) * 0.027, 0.021 - Math.floor(i / 2) * 0.03, 0]}>
            <Arredondado largura={0.019} altura={0.019} fundo={0.0005} raio={0.004} material={mat(cor)} />
          </group>
        ))}
        <Caixa p={[0, -0.049, 0]} t={[0.038, 0.009, 0.0005]} cor="#cadbdc" />
      </group>
    )}
    <Caixa p={[0, 0.064, 0.0051]} t={[0.018, 0.003, 0.0002]} cor="#172335" />
    <Caixa p={[0, -0.063, 0.0051]} t={[0.018, 0.002, 0.0002]} cor={telaAcesa ? '#536479' : '#313d4e'} />
    {/* Ilha traseira com duas lentes salientes. */}
    <group position={[-0.018, 0.049, -0.0042]}>
      <Arredondado largura={0.029} altura={0.045} fundo={0.001} raio={0.007} material={mat('#506aa7')} />
      {[-0.01, 0.01].map((y) => (
        <group key={y} position={[-0.003, y, -0.0012]} rotation={[Math.PI / 2, 0, 0]}>
          <mesh material={mat('#1c293c', 0.22)} castShadow><cylinderGeometry args={[0.008, 0.008, 0.001, 16]} /></mesh>
          <mesh position={[0, -0.0008, 0]} material={mat('#477b9b', 0.18)}><cylinderGeometry args={[0.0045, 0.0045, 0.0004, 16]} /></mesh>
        </group>
      ))}
      <Caixa p={[0.008, 0, -0.001]} t={[0.004, 0.005, 0.0004]} cor="#f4e7bd" />
    </group>
    <Caixa p={[0.0378, 0.018, 0]} t={[0.0016, 0.019, 0.003]} cor="#4d64a0" />
    <Caixa p={[-0.0378, 0.027, 0]} t={[0.0016, 0.027, 0.003]} cor="#4d64a0" />
  </group>
);
