// Primitivas do lote. Medidas em metros, materiais compartilhados por cor.
import React, { useLayoutEffect } from 'react';
import * as THREE from 'three';
import { useThree } from '@react-three/fiber';
import { useCurrentFrame, useVideoConfig } from 'remotion';
import { Camera } from '../../../kit/Camera';

export type V3 = [number, number, number];

const cache = new Map<string, THREE.MeshStandardMaterial>();
export const mat = (cor: string) => {
  let material = cache.get(cor);
  if (!material) {
    material = new THREE.MeshStandardMaterial({ color: cor, roughness: 0.85 });
    cache.set(cor, material);
  }
  return material;
};

export const Caixa: React.FC<{ p: V3; t: V3; cor: string; r?: V3; sombra?: boolean }> = ({ p, t, cor, r, sombra = true }) => (
  <mesh position={p} rotation={r} material={mat(cor)} castShadow={sombra} receiveShadow>
    <boxGeometry args={t} />
  </mesh>
);

// Reenquadra a câmera existente e ajusta o único sol fornecido pelo palco.
export const Ambiente: React.FC<{ manha?: boolean }> = ({ manha = false }) => {
  const quadro = useCurrentFrame();
  const { durationInFrames } = useVideoConfig();
  const cena = useThree((s) => s.scene);
  useLayoutEffect(() => {
    const sol = cena.children.find((objeto): objeto is THREE.DirectionalLight => objeto instanceof THREE.DirectionalLight);
    const ceu = cena.children.find((objeto): objeto is THREE.HemisphereLight => objeto instanceof THREE.HemisphereLight);
    if (!sol || !ceu) return;
    const posicao = sol.position.clone();
    const cor = sol.color.clone();
    const forca = sol.intensity;
    const forcaCeu = ceu.intensity;
    const corCeu = ceu.color.clone();
    const corChao = ceu.groundColor.clone();
    sol.position.set(...(manha ? [18, 9, 12] : [12, 24, 16]) as V3);
    sol.color.set(manha ? '#ffd3a0' : '#fff3de');
    sol.intensity = manha ? 2.8 : 2.6;
    ceu.intensity = manha ? 1.15 : 1.4;
    ceu.color.set(manha ? '#ffe3be' : '#d3ebff');
    ceu.groundColor.set(manha ? '#c78d65' : '#a6977c');
    return () => {
      sol.position.copy(posicao);
      sol.color.copy(cor);
      sol.intensity = forca;
      ceu.intensity = forcaCeu;
      ceu.color.copy(corCeu);
      ceu.groundColor.copy(corChao);
    };
  }, [cena, manha]);
  const alvo: V3 = manha ? [0, 1.5, -3.6] : [0, 2.5, -10];
  const altura = manha ? 1.9 : 3;
  const fov = manha ? 50 : 64;
  return <Camera quadro={quadro} chaves={[
    { q: 0, pos: [0, altura, 6.2], alvo, fov },
    { q: durationInFrames - 1, pos: [0.12, altura, 6.1], alvo, fov },
  ]} />;
};

export const Haste: React.FC<{ a: V3; b: V3; r: number; cor: string }> = ({ a, b, r, cor }) => {
  const inicio = new THREE.Vector3(...a), fim = new THREE.Vector3(...b);
  const direcao = fim.clone().sub(inicio);
  const giro = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), direcao.clone().normalize());
  return (
    <mesh position={inicio.add(fim).multiplyScalar(0.5)} quaternion={giro} material={mat(cor)} castShadow receiveShadow>
      <cylinderGeometry args={[r, r, direcao.length(), 8]} />
    </mesh>
  );
};

export const Arvore: React.FC<{ p: V3; copa?: string }> = ({ p, copa = '#65a86b' }) => (
  <group position={p}>
    <Haste a={[0, 0, 0]} b={[0, 2.3, 0]} r={0.18} cor="#886044" />
    <mesh position={[0, 2.9, 0]} material={mat(copa)} castShadow receiveShadow>
      <icosahedronGeometry args={[1.1, 0]} />
    </mesh>
    <mesh position={[0.65, 2.65, 0.05]} material={mat('#83b96d')} castShadow receiveShadow>
      <icosahedronGeometry args={[0.75, 0]} />
    </mesh>
  </group>
);
