// Pilha de moedas: 30 moedas douradas num monte de colunas lado a lado, em 2 fileiras (origem no centro da base,
// frente +Z). Atrás, 3 colunas altas (8, 10 e 7); na frente, 2 baixas (3 e 2), encaixadas entre as de trás.
// Moeda de 3,2 cm x 3,2 mm, colunas alinhadas no eixo. Cada coluna tem um miolo dourado-escuro que aparece nos vãos
// de 0,6 mm entre as moedas: lê como "moedas empilhadas", não como cilindro liso.
// Moeda de cima com a cara para cima: borda grossa em relevo e disco liso mais claro no meio.
// Cada coluna leva a própria sombra de contato (discos translúcidos): a do sol, nessa escala, vira uma mancha só.
import React from 'react';
import * as THREE from 'three';
import { mat } from './base';

export const MOEDA = { raio: 0.016, esp: 0.0032, vao: 0.0006 };
const PASSO = 0.034; // 2 mm entre moedas vizinhas
/** Colunas: x, z e quantas moedas. Total 30. */
export const COLUNAS: [number, number, number][] = [
  [-PASSO, -0.016, 8], [0, -0.016, 10], [PASSO, -0.016, 7],
  [-PASSO / 2, 0.018, 3], [PASSO / 2, 0.018, 2],
];
const OURO = mat('#ffb000', 0.55), OURO_ESC = mat('#a86400', 0.65), OURO_CLARO = mat('#ffd23a', 0.5);

// sombra de contato: 3 discos de raio decrescente, um pouco deslocados para longe do sol (−X, −Z)
const geoSombra = new THREE.CircleGeometry(1, 40);
const matSombra = new THREE.MeshBasicMaterial({ color: '#10141c', transparent: true, opacity: 0.16, depthWrite: false });
const SOMBRA: [number, number][] = [[1.35, 0.0002], [1.15, 0.0004], [1.0, 0.0006]];

export const PilhaMoedas: React.FC = () => {
  const { raio, esp, vao } = MOEDA;
  const passoY = esp + vao;
  return (
    <group>
      {COLUNAS.map(([cx, cz, n], c) => {
        const alt = n * passoY;
        return (
          <group key={c} position={[cx, 0, cz]}>
            {SOMBRA.map(([k, y], i) => (
              <mesh key={i} position={[-0.002, y, -0.002]} rotation={[-Math.PI / 2, 0, 0]} scale={raio * k} geometry={geoSombra} material={matSombra} />
            ))}
            <mesh position={[0, alt / 2, 0]} material={OURO_ESC}>
              <cylinderGeometry args={[raio - 0.0009, raio - 0.0009, alt - 0.0004, 48, 1, true]} />
            </mesh>
            {Array.from({ length: n }, (_, k) => (
              // a lateral não recebe sombra (riscos de "acne" do mapa de sombra em peças milimétricas)
              <mesh key={k} position={[0, vao / 2 + esp / 2 + k * passoY, 0]} material={OURO}>
                <cylinderGeometry args={[raio, raio, esp, 40]} />
              </mesh>
            ))}
            {/* cara da moeda de cima: borda grossa + disco liso claro */}
            <group position={[0, alt, 0]}>
              <mesh position={[0, 0.0003, 0]} rotation={[Math.PI / 2, 0, 0]} scale={[1, 1, 0.55]} material={OURO}>
                <torusGeometry args={[raio - 0.0019, 0.0019, 8, 40]} />
              </mesh>
              <mesh position={[0, 0.0001, 0]} material={OURO_CLARO}>
                <cylinderGeometry args={[raio - 0.0037, raio - 0.0037, 0.0006, 36]} />
              </mesh>
            </group>
          </group>
        );
      })}
    </group>
  );
};
