import React from 'react';
import * as THREE from 'three';

export type V3 = [number, number, number];
const cache = new Map<string, THREE.MeshStandardMaterial>();
export const mat = (cor: string) => {
  let material = cache.get(cor);
  if (!material) {
    material = new THREE.MeshStandardMaterial({ color: cor, roughness: 0.87 });
    cache.set(cor, material);
  }
  return material;
};

export const Caixa: React.FC<{ p: V3; t: V3; cor: string; r?: V3 }> = ({ p, t, cor, r }) => (
  <mesh position={p} rotation={r} material={mat(cor)} castShadow receiveShadow>
    <boxGeometry args={t} />
  </mesh>
);

// Prisma triangular obtido de um cilindro de três lados; ponta para +Y.
export const Triangulo: React.FC<{ largura: number; altura: number; espessura: number; cor: string }> = ({ largura, altura, espessura, cor }) => (
  <group scale={[largura / Math.sqrt(3), altura / 1.5, 1]} rotation={[0, 0, Math.PI]}>
    <mesh rotation={[Math.PI / 2, 0, 0]} material={mat(cor)} castShadow receiveShadow>
      <cylinderGeometry args={[1, 1, espessura, 3]} />
    </mesh>
  </group>
);
