// Lote r07-acao: inclinar, deitar e escovarDentes (3ª versão; a 1ª foi o l16).
// Só juntas do boneco padrão (graus; altura em metros). Animação só em função do quadro (30 fps).
// As mãos são escritas como "onde ficam", em metros no espaço do boneco, e viram juntas pela IK do r05.
import { BASE, type Juntas } from '../../../kit/poses';
import { ikBraco, paraTronco } from '../r05-acao/acoes';

type V3 = [number, number, number];
const TAU = Math.PI * 2;
const onda = (q: number, periodo: number, fase = 0) => Math.sin((TAU * q) / periodo + fase);

/** Braço D/E com a mão no ponto `p` (espaço do boneco, chão em y = 0), já descontando o tronco. */
function bracos(j: Pick<Juntas, 'altura' | 'troncoX' | 'troncoY'>, maoD?: V3, maoE?: V3): Partial<Juntas> {
  const r: Partial<Juntas> = {};
  if (maoD) { const b = ikBraco(1, paraTronco(j, maoD)); r.ombroDX = b.x; r.ombroDZ = b.z; r.cotoveloD = b.cot; }
  if (maoE) { const b = ikBraco(-1, paraTronco(j, maoE)); r.ombroEX = b.x; r.ombroEZ = b.z; r.cotoveloE = b.cot; }
  return r;
}

// ── inclinar ─────────────────────────────────────────────────────────────
// Debruçado por cima do ombro de quem está sentado no chão à frente e à direita (o "outro" da demo:
// centro em x 0,66 / z 0,45, ombro dele em ~(0,40; 0,70; 0,45)). Quadril dobrado 48°; a cabeça fica
// bem acima desse ombro, vira para ele e aponta para baixo, com o rosto ainda para a câmera.
// Mão D pousada no ombro do outro; mão E para trás, nas costas (contrapeso).
// Pé E à frente com o joelho dobrado, pé D bem atrás sustentando a inclinação.
export const OUTRO_INCLINAR: V3 = [0.66, 0, 0.45];
export const OMBRO_OUTRO: V3 = [0.4, 0.7, 0.45]; // onde a mão D pousa
const PERNAS_INCLINAR = { quadrilE: 24, joelhoE: 26, quadrilD: -22, joelhoD: 6, altura: -0.06 };
const troncoInclinar = (q: number) => ({ troncoX: 48 + 1.5 * onda(q, 75), troncoY: 0, altura: PERNAS_INCLINAR.altura });
const maoCostas = (q: number): V3 => [-0.2, 0.8 + 0.01 * onda(q, 75), -0.1];
export const INCLINAR: Partial<Juntas> = {
  ...PERNAS_INCLINAR, ...troncoInclinar(0), cabecaX: -36, cabecaY: 10, cabecaZ: -6,
  ...bracos(troncoInclinar(0), OMBRO_OUTRO, maoCostas(0)),
};
export const inclinar = (q: number): Partial<Juntas> => {
  const t = troncoInclinar(q);
  // respira por cima do ombro: o tronco desce e sobe 1,5°, a mão D fica pousada e a cabeça "espia" de leve
  return { ...t, ...bracos(t, OMBRO_OUTRO, maoCostas(q)), cabecaY: 10 + 4 * onda(q, 90), cabecaZ: -6 + 3 * onda(q, 90, 1) };
};

// ── deitar ───────────────────────────────────────────────────────────────
// De costas no chão: tronco a −90° (cabeça em −Z), costas em y = 0 (eixo do tronco a 0,19 m).
// Joelhos para cima e pés no chão: as pernas não avançam para a câmera.
// A cabeça descansa sobre as mãos: queixo 28° para dentro, o que a ergue e mostra o rosto e o boné.
// Braços em "asa": cotovelos abertos rentes ao chão, antebraços voltando até as mãos sob a nuca.
// Feito à mão: o ombro do kit tem só 2 eixos, então o plano do antebraço vem junto com o do braço.
// Com ombroZ 78 / ombroX 105 o cotovelo vai para o lado e um pouco para cima (y ≈ 0,23) e o antebraço
// dobra rente ao chão até a mão, em (±0,32; 0,15; −0,6), encostada atrás do queixo/orelha.
const ASA = { ombroEX: 105, ombroEZ: 78, cotoveloE: 125, ombroDX: 105, ombroDZ: 78, cotoveloD: 125 };
// Perna D com o joelho alto (fêmur sobe 50°, canela a prumo, pé no chão em z ≈ 0,3); perna E baixa e
// quase esticada (joelho a 23 cm do chão, pé em z ≈ 0,5). Assimétrico: lê "deitado à toa", não "sentado".
export const DEITAR: Partial<Juntas> = {
  troncoX: -90, troncoY: 0, altura: -0.47, cabecaX: 36, cabecaY: 0, cabecaZ: 0,
  ...ASA, quadrilE: 105, joelhoE: 60, quadrilD: 140, joelhoD: 145,
};
export const deitar = (q: number): Partial<Juntas> => {
  const balanco = 4 * onda(q, 60); // o joelho D balança devagar (a canela mantém o ângulo, o pé fica no chão)
  return { quadrilD: 140 + balanco, joelhoD: 145 + balanco, cabecaZ: 4 * onda(q, 120), cabecaY: 5 * onda(q, 120, 0.8) };
};

// ── escovarDentes ────────────────────────────────────────────────────────
// Em pé, de frente, cabeça quase de frente. Mão D diante do queixo, um pouco à direita da boca, com o
// antebraço deitado na horizontal: a escova (na demo) sai do punho até a boca. O vaivém é lateral,
// 3 por segundo (a mão vai de x 0,08 a 0,16), e a cabeça gira e pende ao contrário.
// Mão E pousada na barriga. Pé E um pouco à frente.
const PES_ESCOVAR = { quadrilE: 12, joelhoE: 6, quadrilD: -6, joelhoD: 0, altura: -0.03 };
const TRONCO_ESCOVAR = { troncoX: 3, troncoY: -6, altura: PES_ESCOVAR.altura };
export const PERIODO_ESCOVA = 10;
/** 0..1: posição do vaivém (0 = mão perto da boca, 1 = mão para fora). */
export const vaivem = (q: number) => 0.5 + 0.5 * onda(q, PERIODO_ESCOVA);
export const maoEscova = (q: number): V3 => { const p = vaivem(q); return [0.08 + 0.08 * p, 1.29, 0.4 - 0.02 * p]; };
export const MAO_BARRIGA: V3 = [-0.1, 0.88, 0.25];
export const ESCOVAR_DENTES: Partial<Juntas> = {
  ...PES_ESCOVAR, ...TRONCO_ESCOVAR, cabecaX: 4, cabecaY: 4, cabecaZ: 0,
  ...bracos(TRONCO_ESCOVAR, maoEscova(0), MAO_BARRIGA),
};
export const escovarDentes = (q: number): Partial<Juntas> => {
  const p = vaivem(q);
  return { ...bracos(TRONCO_ESCOVAR, maoEscova(q)), cabecaZ: 3 - 6 * p, cabecaY: 7 - 8 * p };
};

/** Juntas completas da ação no quadro (para as demos com objetos). */
const ACOES = {
  inclinar: { pose: INCLINAR, animar: inclinar },
  deitar: { pose: DEITAR, animar: deitar },
  escovarDentes: { pose: ESCOVAR_DENTES, animar: escovarDentes },
};
export const juntasNoQuadro = (nome: keyof typeof ACOES, q: number): Juntas => ({ ...BASE, ...ACOES[nome].pose, ...ACOES[nome].animar(q) });
