// Demonstrações das ações COM os objetos. O contrato `acao` só leva juntas, então a vitrine mostra o boneco
// de mãos vazias; estas peças (tipo 'efeito') põem ao lado do Téo um coadjuvante fazendo a mesma ação,
// com caderno, moeda, bola, caixa ou banco na mão, e com o olhar e a boca certos para a ação.
import React from 'react';
import { Boneco, type Expressao } from '../../../kit/Boneco';
import { ELENCO } from '../../../kit/elenco';
import { juntasNoQuadro } from './acoes';
import { ObjetosDaAcao } from './objetos';
import type { PecaOficina } from '../tipos';

const V = ELENCO.c1;
const ROSTO: Record<string, Expressao> = {
  escrever: { boca: 'neutra', olharY: -1, sobrancelha: -0.3 },
  jogarMoeda: { boca: 'o', olharY: 1, olharX: 0.4 },
  virarCabeca: { boca: 'neutra', olharX: 0.6 },
  quicarBola: { boca: 'neutra', olharY: -1, olharX: 0.4 },
  sortear: { boca: 'sorriso', olharX: 0.8, olharY: -0.2 },
};

const Demo = (nome: string): React.FC<{ quadro: number }> => ({ quadro }) => (
  <group position={[1.05, 0, 0.1]} rotation={[0, -0.2, 0]}>
    <Boneco v={V} j={juntasNoQuadro(nome, quadro)} e={ROSTO[nome]} />
    <ObjetosDaAcao nome={nome} quadro={quadro} pele={V.pele} />
  </group>
);

export const DEMOS: PecaOficina[] = Object.keys(ROSTO).map((nome) => ({
  tipo: 'efeito' as const, nome: `${nome}+objetos`, Componente: Demo(nome),
}));
