import React from 'react';
import * as THREE from 'three';

export type V3 = [number, number, number];

const cache = new Map<string, THREE.MeshStandardMaterial>();
export const mat = (cor: string) => {
  let material = cache.get(cor);
  if (!material) {
    material = new THREE.MeshStandardMaterial({ color: cor, roughness: 0.85 });
    if (['#b9c4ca', '#9aa9b3', '#d4dde1', '#e7edf0'].includes(cor)) material.metalness = 0.25;
    if (cor === '#e9b630') {
      material.metalness = 0.12;
      material.emissive.set('#ba790c');
      material.emissiveIntensity = 0.18;
    }
    if (cor === '#fff7ce') {
      material.emissive.set(cor);
      material.emissiveIntensity = 0.65;
    }
    if (cor === '#f7fafb') {
      material.transparent = true;
      material.opacity = 0.65;
      material.depthWrite = false;
      material.emissive.set('#ffffff');
      material.emissiveIntensity = 0.35;
    }
    cache.set(cor, material);
  }
  return material;
};

export const Caixa: React.FC<{
  p: V3; t: V3; cor: string; r?: V3; sombra?: boolean;
}> = ({ p, t, cor, r, sombra = true }) => (
  <mesh position={p} rotation={r} material={mat(cor)} castShadow={sombra} receiveShadow>
    <boxGeometry args={t} />
  </mesh>
);

export const Elipsoide: React.FC<{ p: V3; t: V3; cor: string }> = ({ p, t, cor }) => (
  <mesh position={p} scale={t} material={mat(cor)} castShadow receiveShadow>
    <sphereGeometry args={[1, 24, 16]} />
  </mesh>
);

export const Haste: React.FC<{ a: V3; b: V3; raio: number; cor: string }> = ({ a, b, raio, cor }) => {
  const inicio = new THREE.Vector3(...a), fim = new THREE.Vector3(...b);
  const direcao = fim.clone().sub(inicio);
  const giro = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), direcao.clone().normalize());
  return (
    <mesh position={inicio.add(fim).multiplyScalar(0.5)} quaternion={giro} material={mat(cor)} castShadow receiveShadow>
      <cylinderGeometry args={[raio, raio, direcao.length(), 12]} />
    </mesh>
  );
};
