// Primitivas do lote, em metros. Materiais compartilhados por cor.
import React from 'react';
import * as THREE from 'three';

export type V3 = [number, number, number];

const cache = new Map<string, THREE.MeshStandardMaterial>();
export const mat = (cor: string, brilho = 0, nevoa = true, facetado = false) => {
  const chave = `${cor}|${brilho}|${nevoa}|${facetado}`;
  let material = cache.get(chave);
  if (!material) {
    material = new THREE.MeshStandardMaterial({
      color: cor, roughness: 0.87, metalness: 0,
      emissive: cor, emissiveIntensity: brilho, fog: nevoa, flatShading: facetado,
    });
    cache.set(chave, material);
  }
  return material;
};

export const Caixa: React.FC<{ p: V3; t: V3; cor: string; r?: V3; sombra?: boolean; brilho?: number }> = ({ p, t, cor, r, sombra = true, brilho = 0 }) => (
  <mesh position={p} rotation={r} material={mat(cor, brilho)} castShadow={sombra} receiveShadow>
    <boxGeometry args={t} />
  </mesh>
);

export const Esfera: React.FC<{ p: V3; t: V3; cor: string; sombra?: boolean }> = ({ p, t, cor, sombra = true }) => (
  <mesh position={p} scale={t} material={mat(cor)} castShadow={sombra} receiveShadow>
    <sphereGeometry args={[1, 48, 32]} />
  </mesh>
);
