// Volante de loteria: cartão de papel verde de 20 x 10 cm (origem no centro da base, frente para +Z) e a caneta azul.
// Faixa esquerda verde-escura com trevo (é por ali que a mão prende o cartão) e grade 3 x 6 (01–18) ocupando o resto,
// com dígitos grossos verde-escuros. Três números já marcados de caneta (casa azul, dígito branco).
import React, { useMemo } from 'react';
import { Caixa, Cil, Ret, Tracos, mat, numero, type Seg, type V3 } from './base';

export const VOL = { larg: 0.2, alt: 0.1 };
const C = {
  papel: '#a8dc92', escuro: '#25784a', casa: '#effae8', tinta: '#1c5534', branco: '#ffffff', caneta: '#2448c8',
};
export const MARCADOS = new Set([4, 9, 14]);
/** Número que a caneta está marcando agora (a ponta toca o canto de baixo à direita da casa, fora dos dígitos). */
export const NA_CANETA = 18;

// grade: 6 colunas x 3 linhas entre x −0,072 e 0,096 e y 0,005–0,095 (sem faixa de título: números maiores)
const COLS = 6, PX = 0.168 / COLS, PY = 0.03, X0 = -0.072 + PX / 2, Y0 = 0.005 + PY / 2;
export const CASA = { larg: PX, alt: PY };
export const casaDe = (n: number): [number, number] => {
  const i = n - 1, c = i % COLS, l = Math.floor(i / COLS);
  return [X0 + c * PX, Y0 + (2 - l) * PY];
};
const DG = { w: 0.0095, h: 0.019, s: 0.0034, vao: 0.0026 };
// camadas: papel 0–0,8 mm; faixa e casas até 1,6 mm; dígitos até 2,2 mm (frente)
const ZP = 0.0004, ZC = 0.0012, ZD = 0.0019;

export const VolanteLoteria: React.FC = () => {
  const { escuros, brancos } = useMemo(() => {
    const escuros: Seg[] = [], brancos: Seg[] = [];
    for (let n = 1; n <= 18; n++) {
      const [x, y] = casaDe(n);
      (MARCADOS.has(n) ? brancos : escuros).push(...numero(String(n).padStart(2, '0'), x, y, DG.w, DG.h, DG.s, DG.vao));
    }
    return { escuros, brancos };
  }, []);
  return (
    <group>
      <Ret w={VOL.larg} h={VOL.alt} d={0.0008} r={0.006} p={[0, VOL.alt / 2, ZP]} cor={C.papel} sombra />
      {/* faixa esquerda com trevo de 4 folhas */}
      <Ret w={0.022} h={0.09} d={0.0008} r={0.004} p={[-0.0855, 0.05, ZC]} cor={C.escuro} />
      <group position={[-0.0855, 0.074, ZD]}>
        {[[0, 1], [1, 0], [0, -1], [-1, 0]].map(([a, b], i) => (
          <Cil key={i} p={[a * 0.0042, b * 0.0042, 0]} raio={0.0045} h={0.0006} r={[Math.PI / 2, 0, 0]} cor={C.branco} sombra={false} />
        ))}
        <Caixa p={[0.002, -0.0105, 0]} t={[0.0024, 0.009, 0.0006]} r={[0, 0, 0.4]} cor={C.branco} sombra={false} />
      </group>
      {/* casas: claras ou marcadas de azul */}
      {Array.from({ length: 18 }, (_, i) => {
        const [x, y] = casaDe(i + 1);
        return <Ret key={i} w={PX - 0.004} h={PY - 0.004} d={0.0008} r={0.0028} p={[x, y, ZC]} cor={MARCADOS.has(i + 1) ? C.caneta : C.casa} />;
      })}
      <Tracos segs={escuros} z={ZD} prof={0.0006} cor={C.tinta} />
      <Tracos segs={brancos} z={ZD} prof={0.0006} cor={C.branco} />
    </group>
  );
};

// ── caneta azul: 16 cm (na escala da mão de 14 cm do boneco), origem na ponta, corpo ao longo de +Y ──
export const CANETA = { comp: 0.16 };
const AZUL = '#2f62e0', AZUL_ESC = '#1c3a9a';
export const Caneta: React.FC = () => {
  const p = (y: number): V3 => [0, y, 0];
  return (
    <group>
      {/* ponta: bolinha de metal + cone */}
      <mesh position={p(0.0012)} material={mat('#c9ced6', 0.4, 0.6)}><sphereGeometry args={[0.0012, 10, 8]} /></mesh>
      <Cil p={p(0.009)} raio={0.0012} raio2={0.0052} h={0.016} cor="#c9ced6" m={mat('#c9ced6', 0.4, 0.6)} lados={16} />
      {/* empunhadura emborrachada, corpo e tampa de trás com clipe */}
      <Cil p={p(0.035)} raio={0.0066} h={0.036} cor={AZUL_ESC} lados={20} />
      <Cil p={p(0.0975)} raio={0.0058} h={0.089} cor={AZUL} m={mat(AZUL, 0.55)} lados={20} />
      <Cil p={p(0.151)} raio={0.0062} h={0.018} cor={AZUL_ESC} lados={20} />
      <mesh position={p(0.16)} material={mat(AZUL_ESC)}><sphereGeometry args={[0.0062, 16, 8, 0, Math.PI * 2, 0, Math.PI / 2]} /></mesh>
      <Caixa p={[0, 0.132, 0.0075]} t={[0.0032, 0.042, 0.0024]} cor={AZUL_ESC} />
    </group>
  );
};
