// Efeito: aura dourada de "sorte" em volta de um personagem de ~1,6 m em pé na origem.
// Camadas: brilho no chão + coluna de luz (degradê por cor de vértice, aditivo), halo atrás do corpo,
// anel que se espalha no chão, 16 moedas/estrelas subindo em espiral e um "×2" pulsando acima da cabeça.
// Tudo é função de `quadro` (30 fps): nada de acaso, nada de useFrame; mudanças suaves, sem piscar.
import * as THREE from 'three';
import React, { useMemo } from 'react';
import { mat } from './base';

const OURO = new THREE.Color('#ffc93a');
const C = { moeda: '#f4b928', moedaBorda: '#c98a12', estrela: '#ffe27a', glifo: '#ffd23f', glifoSombra: '#b8760e' };
const TAU = Math.PI * 2;
const N = 16;

/** Material aditivo com degradê por cor de vértice (preto = invisível). */
const useAditivo = () => useMemo(() => new THREE.MeshBasicMaterial({
  vertexColors: true, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide, toneMapped: false,
}), []);

/** Potência segura: base negativa (arredondamento na borda) daria NaN e pintaria o vértice de preto. */
const pw = (b: number, e: number) => Math.pow(Math.max(0, b), e);

/** Pinta cada vértice com OURO * f(vértice). */
const pintar = (g: THREE.BufferGeometry, f: (v: THREE.Vector3) => number) => {
  const pos = g.attributes.position, cor = new Float32Array(pos.count * 3), v = new THREE.Vector3();
  for (let i = 0; i < pos.count; i++) {
    v.fromBufferAttribute(pos, i); const k = Math.max(0, f(v));
    cor[i * 3] = OURO.r * k; cor[i * 3 + 1] = OURO.g * k; cor[i * 3 + 2] = OURO.b * k;
  }
  g.setAttribute('color', new THREE.BufferAttribute(cor, 3));
  return g;
};

const Moeda: React.FC = () => (
  <group>
    <mesh rotation={[Math.PI / 2, 0, 0]} material={mat(C.moeda, { brilho: 0.35, rug: 0.35, metal: 0.4 })} castShadow><cylinderGeometry args={[0.042, 0.042, 0.012, 20]} /></mesh>
    <mesh position={[0, 0, 0.007]} material={mat(C.moedaBorda, { brilho: 0.3, rug: 0.4, metal: 0.4 })}><torusGeometry args={[0.03, 0.005, 6, 20]} /></mesh>
    <mesh position={[0, 0, -0.007]} material={mat(C.moedaBorda, { brilho: 0.3, rug: 0.4, metal: 0.4 })}><torusGeometry args={[0.03, 0.005, 6, 20]} /></mesh>
  </group>
);

/** Estrelinha de 4 pontas: dois losangos cruzados + miolo. */
const Estrela: React.FC = () => {
  const m = mat(C.estrela, { brilho: 1.1, rug: 0.5 });
  return (
    <group>
      <mesh scale={[0.075, 0.02, 0.02]} material={m}><icosahedronGeometry args={[1, 0]} /></mesh>
      <mesh scale={[0.02, 0.075, 0.02]} material={m}><icosahedronGeometry args={[1, 0]} /></mesh>
      <mesh material={m}><sphereGeometry args={[0.022, 12, 8]} /></mesh>
    </group>
  );
};

/** "×2" feito de cápsulas (traço arredondado de 3,2 cm). */
const Traco: React.FC<{ a: [number, number]; b: [number, number]; m: THREE.Material }> = ({ a, b, m }) => {
  const dx = b[0] - a[0], dy = b[1] - a[1];
  return (
    <mesh position={[(a[0] + b[0]) / 2, (a[1] + b[1]) / 2, 0]} rotation={[0, 0, Math.atan2(dy, dx) - Math.PI / 2]} material={m}>
      <capsuleGeometry args={[0.016, Math.hypot(dx, dy), 6, 12]} />
    </mesh>
  );
};
const VezesDois: React.FC<{ m: THREE.Material }> = ({ m }) => (
  <group>
    <Traco a={[-0.125, -0.04]} b={[-0.045, 0.04]} m={m} />
    <Traco a={[-0.125, 0.04]} b={[-0.045, -0.04]} m={m} />
    {/* "2": topo, descida da direita, diagonal, base */}
    <Traco a={[0.03, 0.065]} b={[0.09, 0.065]} m={m} />
    <Traco a={[0.105, 0.05]} b={[0.105, 0.015]} m={m} />
    <Traco a={[0.095, 0.0]} b={[0.025, -0.06]} m={m} />
    <Traco a={[0.025, -0.07]} b={[0.11, -0.07]} m={m} />
    <Traco a={[0.015, 0.05]} b={[0.03, 0.065]} m={m} />
  </group>
);

export const BrilhoSorte: React.FC<{ quadro: number; intensidade?: number }> = ({ quadro, intensidade = 1 }) => {
  const q = quadro, k = Math.max(0, intensidade);
  // entrada suave no primeiro segundo
  const entra = Math.min(1, q / 20);
  const ent = entra * entra * (3 - 2 * entra) * k;
  const resp = 0.5 + 0.5 * Math.sin((TAU * q) / 60); // "respiração" de 2 s

  const geo = useMemo(() => ({
    chao: pintar(new THREE.CircleGeometry(1.05, 48), (v) => pw(1 - v.length() / 1.05, 1.6)),
    coluna: pintar(new THREE.CylinderGeometry(0.62, 0.52, 2.3, 40, 12, true), (v) => pw(1 - (v.y + 1.15) / 2.3, 2.2)),
    halo: pintar(new THREE.PlaneGeometry(2.4, 3.0, 24, 30), (v) => 1 - Math.hypot(v.x / 1.05, (v.y - 0.1) / 1.45)),
  }), []);
  const mChao = useAditivo(), mColuna = useAditivo(), mHalo = useAditivo();
  mChao.opacity = (0.7 + 0.15 * resp) * ent;
  mColuna.opacity = (0.16 + 0.05 * resp) * ent;
  mHalo.opacity = (0.4 + 0.1 * resp) * ent;

  // anel que nasce no pé e se espalha (ciclo de 50 quadros; some com opacidade 0 antes de reiniciar)
  const mAnel = useMemo(() => new THREE.MeshBasicMaterial({ color: '#ffd45a', transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, toneMapped: false }), []);
  const ciclo = (q % 50) / 50;
  mAnel.opacity = Math.sin(Math.PI * ciclo) * 0.8 * ent;

  const mGlifo = mat(C.glifo, { brilho: 0.8, rug: 0.45 });
  const mSombra = mat(C.glifoSombra, { rug: 0.6 });
  // ×2 entre o topo do boné (~1,93 m) e a borda de cima do quadro na vitrine
  const pulso = 0.9 * (1 + 0.05 * Math.sin((TAU * q) / 36));
  const yGlifo = 2.02 + 0.01 * Math.sin((TAU * q) / 72);

  return (
    <group>
      <pointLight position={[0, 1.1, 0.9]} color="#ffcf5a" intensity={1.6 * ent} distance={3.5} decay={2} />
      <mesh position={[0, 0.045, 0]} rotation={[-Math.PI / 2, 0, 0]} geometry={geo.chao} material={mChao} />
      <mesh position={[0, 1.2, 0]} geometry={geo.coluna} material={mColuna} />
      <mesh position={[0, 1.0, -0.55]} geometry={geo.halo} material={mHalo} />
      <mesh position={[0, 0.05, 0]} rotation={[-Math.PI / 2, 0, 0]} scale={0.45 + 0.75 * ciclo} material={mAnel}>
        <torusGeometry args={[1, 0.035 / (0.45 + 0.75 * ciclo), 6, 64]} />
      </mesh>
      {/* partículas: sobem em 4 s numa espiral; crescem ao nascer e encolhem ao chegar no alto (sem estalo) */}
      {Array.from({ length: N }, (_, i) => {
        const s = (q / 120 + i / N) % 1;
        const ang = i * 2.39996 + q * 0.03 + s * 2.2;
        const r = 0.5 + 0.08 * Math.sin(i * 1.7) + 0.12 * s;
        const e = Math.sin(Math.PI * s) ** 0.8 * ent;
        const moeda = i % 2 === 0;
        const brilho = moeda ? 1 : 1 + 0.2 * Math.sin(q * 0.25 + i * 2.1);
        return (
          <group key={i} position={[r * Math.cos(ang), 0.15 + s * 2.05, r * Math.sin(ang)]} scale={e * brilho}
            rotation={moeda ? [0.3 * Math.sin(i), q * 0.09 + i, 0] : [0, 0, q * 0.04 + i]}>
            {moeda ? <Moeda /> : <Estrela />}
          </group>
        );
      })}
      {/* ×2 acima da cabeça, com "sombra" deslocada 2 cm para trás */}
      <group position={[0, yGlifo, 0.08]} scale={pulso * ent}>
        <VezesDois m={mGlifo} />
        <group position={[0.008, -0.01, -0.02]}><VezesDois m={mSombra} /></group>
      </group>
    </group>
  );
};
