// Quarto aberto para +Z. Notas em suportes, livres dos bonecos da vitrine.
import React from 'react';
import { Caixa, Escrita, Haste, mat, Traco } from './base';

const C = {
  parede: '#d9c8eb', lateral: '#e1d3ed', rodape: '#b69acb', piso: '#e4cfb3',
  madeira: '#dcb986', borda: '#ba9364', branco: '#fff7e8', metal: '#556176',
  vermelho: '#d33243', papel: '#fff9e9', noite: '#283b60', tinta: '#243b58',
};

const Janela: React.FC = () => (
  <group position={[-0.2, 2.31, -2.12]}>
    <Caixa p={[0, 0, 0]} t={[4.9, 1.58, 0.12]} cor={C.branco} />
    <Caixa p={[0, 0, 0.12]} t={[4.66, 1.34, 0.08]} cor="#9dd3e8" sombra={false} />
    <Caixa p={[0, -0.45, 0.22]} t={[4.66, 0.3, 0.08]} cor="#b1cfad" sombra={false} />
    <Caixa p={[0, 0, 0.32]} t={[0.12, 1.34, 0.08]} cor={C.branco} />
    <Caixa p={[0, 0, 0.32]} t={[4.66, 0.12, 0.08]} cor={C.branco} />
    <Caixa p={[0, -0.87, 0.18]} t={[5.1, 0.12, 0.4]} cor={C.branco} />
    <Haste a={[-2.65, 0.92, 0.22]} b={[2.65, 0.92, 0.22]} raio={0.06} cor={C.metal} />
    {[-1, 1].map((lado) => (
      <group key={lado} position={[lado * 2.46, 0.06, 0.15]}>
        <Caixa p={[0, 0, 0]} t={[0.34, 1.6, 0.16]} cor="#e1b752" />
        <Caixa p={[lado * 0.08, 0, 0.14]} t={[0.1, 1.6, 0.08]} cor="#f4d47d" />
        <Caixa p={[0, -0.26, 0.24]} t={[0.38, 0.12, 0.08]} cor="#447c83" />
      </group>
    ))}
  </group>
);

const Caderno: React.FC<{ x: number; y?: number; cor: string }> = ({ x, y = 1.43, cor }) => (
  <group position={[x, y, -1.62]} rotation={[-0.42, 0, 0]}>
    {/* Frente local +Z, topo +Y: a nota não vira nem espelha. */}
    <Caixa p={[0, 0, 0]} t={[1.5, 1.24, 0.08]} cor={cor} />
    {[-1, 1].map((lado) => <Caixa key={lado} p={[lado * 0.355, 0, 0.1]} t={[0.63, 1.12, 0.08]} cor={C.papel} />)}
    <Caixa p={[0, 0, 0.1]} t={[0.08, 1.12, 0.08]} cor="#e3d0a8" />
    <Escrita texto="98%" p={[0, 0, 0.18]} cor={C.tinta} largura={0.2} altura={0.42} passo={0.34} />
    {/* Tinta escura separada do círculo vermelho; traços de 8 cm. */}
    {Array.from({ length: 20 }, (_, i) => {
      const a = i * Math.PI / 10, b = (i + 1) * Math.PI / 10;
      return <Traco key={i} a={[0.64 * Math.cos(a), 0.49 * Math.sin(a)]}
        b={[0.64 * Math.cos(b), 0.49 * Math.sin(b)]} z={0.18} cor={C.vermelho} />;
    })}
  </group>
);

const Luminaria: React.FC = () => (
  <group position={[-2.88, 0.84, -1.92]}>
    <mesh position={[0, 0.05, 0]} material={mat(C.metal)} castShadow receiveShadow><cylinderGeometry args={[0.2, 0.23, 0.1, 12]} /></mesh>
    <Haste a={[0, 0.1, 0]} b={[-0.12, 0.94, 0]} raio={0.05} cor={C.metal} />
    <Haste a={[-0.12, 0.94, 0]} b={[0.18, 1.23, 0]} raio={0.05} cor={C.metal} />
    <mesh position={[0.22, 1.16, 0]} rotation={[0, 0, 0.25]} material={mat('#efbd51')} castShadow receiveShadow>
      <cylinderGeometry args={[0.12, 0.24, 0.24, 12]} />
    </mesh>
    <mesh position={[0.25, 1.02, 0]} material={mat(C.branco)} castShadow receiveShadow><sphereGeometry args={[0.1, 12, 8]} /></mesh>
  </group>
);

const Mesa: React.FC = () => (
  <group>
    {/* Borda traseira em z=-2,20, encostada na parede e sob o vidro. */}
    <Caixa p={[-0.2, 0.78, -1.675]} t={[5.9, 0.12, 1.05]} cor={C.madeira} />
    <Caixa p={[-0.2, 0.65, -2.06]} t={[5.66, 0.18, 0.12]} cor={C.borda} />
    {[-2.94, 2.54].map((x) => [-2.02, -1.3].map((z) => <Caixa key={`${x}-${z}`} p={[x, 0.36, z]} t={[0.14, 0.72, 0.14]} cor={C.borda} />))}
    {/* Apoios de leitura; o central fica acima das cabeças da vitrine. */}
    {[-2.52, 2.15].map((x) => <Haste key={x} a={[x, 0.88, -1.28]} b={[x, 1.82, -1.89]} raio={0.06} cor={C.borda} />)}
    <Caixa p={[0, 1.36, -1.98]} t={[0.2, 1.04, 0.16]} cor={C.borda} />
    <Caixa p={[0, 1.9, -1.62]} t={[1.36, 0.12, 0.54]} cor={C.madeira} />
    <Haste a={[0, 1.96, -1.36]} b={[0, 2.82, -1.88]} raio={0.06} cor={C.borda} />
    <Caderno x={-2.52} cor="#59a3c6" />
    <Caderno x={0} y={2.54} cor="#9c7ac1" />
    <Caderno x={2.15} cor="#e2ae50" />
    <Luminaria />
    {/* Cadeira girada e recolhida: assento espesso, sem tapar as notas. */}
    <group position={[-1.42, 0, -1.48]} rotation={[0, 0.65, 0]}>
      <Caixa p={[0, 0.47, 0]} t={[0.56, 0.16, 0.52]} cor="#318b90" />
      <Caixa p={[0, 0.76, 0.2]} t={[0.56, 0.42, 0.14]} cor="#24666f" />
      {[-0.21, 0.21].map((x) => [-0.19, 0.19].map((z) => <Caixa key={`${x}-${z}`} p={[x, 0.2, z]} t={[0.1, 0.4, 0.1]} cor={C.metal} />))}
    </group>
  </group>
);

const coresLivros = ['#568fb9', '#dc7969', '#e5b958', '#7f9f7b', '#9172b2'];
const Estante: React.FC = () => (
  <group position={[-3.02, 0, 0.1]}>
    <Caixa p={[0, 0.88, -0.19]} t={[0.56, 1.76, 0.08]} cor={C.borda} />
    {[-0.28, 0.28].map((x) => <Caixa key={x} p={[x, 0.88, 0]} t={[0.1, 1.76, 0.46]} cor={C.madeira} />)}
    {[0.08, 0.62, 1.16, 1.7].map((y) => <Caixa key={y} p={[0, y, 0]} t={[0.66, 0.1, 0.46]} cor={C.madeira} />)}
    {[0.13, 0.67, 1.21].map((base, prateleira) => coresLivros.map((cor, i) => {
      const h = 0.27 + ((i + prateleira) % 3) * 0.06;
      return <group key={`${base}-${i}`}>
        <Caixa p={[-0.19 + i * 0.095, base + h / 2, 0.02]} t={[0.08, h, 0.3]} cor={cor} />
      </group>;
    }))}
    <Caixa p={[0, 1.85, 0]} t={[0.54, 0.2, 0.36]} cor="#cf8eab" />
  </group>
);

const Poster: React.FC = () => (
  <group position={[2.97, 2.64, -2.12]}>
    <Caixa p={[0, 0, 0]} t={[1.14, 1.64, 0.12]} cor={C.branco} />
    <Caixa p={[0, 0, 0.12]} t={[0.94, 1.44, 0.08]} cor={C.noite} />
    {/* Planetas em relevo: esfera, planeta anelado e lua. */}
    <mesh position={[-0.2, 0.43, 0.25]} material={mat('#f2c35c')} receiveShadow><sphereGeometry args={[0.16, 12, 8]} /></mesh>
    <mesh position={[0.1, -0.05, 0.3]} material={mat('#d38b81')} receiveShadow><sphereGeometry args={[0.18, 12, 8]} /></mesh>
    <mesh position={[0.1, -0.05, 0.32]} rotation={[0.35, 0.2, -0.3]} material={mat('#e5c9aa')} receiveShadow><torusGeometry args={[0.26, 0.04, 6, 20]} /></mesh>
    <mesh position={[-0.23, -0.48, 0.24]} material={mat('#8fbee1')} receiveShadow><sphereGeometry args={[0.11, 12, 8]} /></mesh>
    {[[0.28, 0.55], [-0.29, 0.02], [0.29, -0.49]].map(([x, y], i) => <Caixa key={i} p={[x, y, 0.23]} t={[0.08, 0.08, 0.08]} cor={C.branco} sombra={false} />)}
  </group>
);

export const QuartoBia: React.FC = () => (
  <group>
    <Caixa p={[0, -0.1, 1.05]} t={[7.4, 0.2, 6.7]} cor={C.piso} sombra={false} />
    <Caixa p={[0, 1.75, -2.3]} t={[7.4, 3.5, 0.2]} cor={C.parede} sombra={false} />
    {[-3.7, 3.7].map((x) => <group key={x}>
      <Caixa p={[x, 1.75, 1.05]} t={[0.2, 3.5, 6.7]} cor={C.lateral} sombra={false} />
      <Caixa p={[x + (x < 0 ? 0.17 : -0.17), 0.15, 1.05]} t={[0.16, 0.3, 6.7]} cor={C.rodape} />
    </group>)}
    <Caixa p={[0, 0.15, -2.1]} t={[7.2, 0.3, 0.16]} cor={C.rodape} />
    {/* Tapete baixo ocupa o primeiro plano sem bloquear a atuação. */}
    <Caixa p={[0, 0, 0.9]} t={[3.7, 0.08, 2.7]} cor="#83b8ba" sombra={false} />
    {[-0.22, 2.02].map((z) => <Caixa key={z} p={[0, 0.08, z]} t={[3.3, 0.04, 0.16]} cor="#c3dfd9" sombra={false} />)}
    <Janela />
    <Mesa />
    <Estante />
    <Poster />
    {/* Cama lateral, fora da faixa dos personagens. */}
    <Caixa p={[2.25, 0.18, -0.1]} t={[0.96, 0.36, 1.82]} cor={C.borda} />
    <Caixa p={[2.25, 0.45, -0.1]} t={[0.94, 0.18, 1.78]} cor={C.branco} />
    <Caixa p={[2.25, 0.6, 0.13]} t={[0.96, 0.12, 1.24]} cor="#9873b6" />
    <Caixa p={[2.25, 0.63, -0.7]} t={[0.7, 0.18, 0.34]} cor="#efdbc7" />
    <Caixa p={[2.25, 0.49, -1.06]} t={[1.04, 0.98, 0.12]} cor={C.madeira} />
  </group>
);
