// Peças disponíveis para a ficha: as do kit + as da oficina escolhidas (melhor versão de cada nome).
// `escolhidas.json` é GERADO por código (automacao/catalogo.ts) a partir das notas da oficina; nunca à mão.
import type React from 'react';
import type { Juntas } from '../kit/poses';
import { Quadra } from '../kit/Quadra';
import { LOTES } from '../oficina/lotes/registro';
import type { LimitesCenario, PecaOficina } from '../oficina/lotes/tipos';
import { PECAS as CMP } from '../oficina/claude';
import escolhidasJson from './escolhidas.json';

type Escolha = { lote: string; nota: number; aprovada: boolean };
const ESCOLHIDAS = escolhidasJson as Record<string, Escolha>;

const daOficina = (tipo: PecaOficina['tipo']) => Object.entries(ESCOLHIDAS)
  .filter(([k]) => k.startsWith(tipo + ':'))
  .map(([k, e]) => (LOTES[e.lote] ?? []).find((p) => p.tipo === tipo && p.nome === k.slice(tipo.length + 1)))
  .filter((p): p is PecaOficina => !!p);

type Cen = { Componente: React.FC; limites: LimitesCenario };
export const CENARIOS_3D: Record<string, Cen> = {
  quadra: { Componente: Quadra, limites: { limiteX: 8.5, limiteZ: [-7.0, 5.0], ceu: '#9fd3ee' } },
  salaDeAula: { Componente: CMP.SalaDeAula, limites: CMP.LIMITES_SALA }, // comparação 01 (Claude, nota 9)
};
for (const p of daOficina('cenario')) if (p.tipo === 'cenario' && !CENARIOS_3D[p.nome]) CENARIOS_3D[p.nome] = { Componente: p.Componente, limites: p.limites };

export const ACOES_OFICINA: Record<string, { pose: Partial<Juntas>; animar?: (q: number) => Partial<Juntas> }> = {
  apontar: { pose: CMP.POSE_APONTAR }, // comparação 01
};
for (const p of daOficina('acao')) if (p.tipo === 'acao') ACOES_OFICINA[p.nome] = { pose: p.pose, animar: p.animar };

export const OBJETOS_3D: Record<string, { Componente: React.FC; apoio: 'chao' | 'mesa' }> = {};
for (const p of daOficina('objeto')) if (p.tipo === 'objeto') OBJETOS_3D[p.nome] = { Componente: p.Componente, apoio: p.apoio };

export const EFEITOS_3D: Record<string, React.FC<{ quadro: number }>> = {};
for (const p of daOficina('efeito')) if (p.tipo === 'efeito') EFEITOS_3D[p.nome] = p.Componente;

export const HudContador = CMP.HudContador; // comparação 01 (Claude, nota 9)

/** Peças usadas que ainda NÃO estão aprovadas (nota < 8): o render de prévia sai com elas, o final não. */
export const NAO_APROVADAS = Object.entries(ESCOLHIDAS).filter(([, e]) => !e.aprovada).map(([k, e]) => `${k} (nota ${e.nota})`);
