// Montagens da vitrine; os modelos separados mantêm origem na base.
import React from 'react';
import * as THREE from 'three';
import { BASE } from '../../../kit/poses';
import { ArcoIrisDuplo } from './ArcoIrisDuplo';
import { NotaCem } from './NotaCem';
import { GuardaChuva } from './GuardaChuva';

// A vitrine insere objetos em x=0,75 e o Téo na origem.
const X_VITRINE = 0.75;
const rad = THREE.MathUtils.degToRad;
const ombro = new THREE.Euler(-rad(BASE.ombroDX), 0, rad(BASE.ombroDZ));
const cotovelo = new THREE.Euler(-rad(BASE.cotoveloD), 0, 0);
const mao = new THREE.Vector3(0, -0.25, 0)
  .applyEuler(cotovelo).add(new THREE.Vector3(0, -0.22, 0))
  .applyEuler(ombro).add(new THREE.Vector3(0.25, 1.06, 0));

export const ArcoAoFundo: React.FC = () => (
  // Recuo real: nenhum tubo atravessa o corpo ou os braços.
  <group position={[-0.25, 0.10, -2.5]} rotation={[-1, 0, 0]}><ArcoIrisDuplo /></group>
);

export const NotaNaMao: React.FC = () => (
  // A borda esquerda toca a mão; o número fica livre na frente dos dedos.
  <group position={[mao.x + 0.045 - X_VITRINE, mao.y - 0.015, mao.z + 0.071]}>
    <NotaCem />
  </group>
);

export const GuardaChuvaSobBraco: React.FC = () => (
  // Eixo quase horizontal, debaixo do braço, com ponta para fora do corpo.
  <group position={[0.04 - X_VITRINE, 0.90, 0.20]} rotation={[0, 0.53, -Math.PI / 2 + 0.20]}>
    <GuardaChuva />
  </group>
);
