// Demonstrações das ações COM os adereços. O contrato `acao` só leva juntas, então a vitrine mostra o Téo
// de mãos vazias e sorrindo; estas peças (tipo 'efeito') põem ao lado dele um coadjuvante fazendo a mesma
// ação (mesmas juntas), com caderno e lápis, moeda e polegar ou as linhas do giro, e com o olhar certo.
import React from 'react';
import { Boneco, type Expressao } from '../../../kit/Boneco';
import { ELENCO } from '../../../kit/elenco';
import { juntasNoQuadro } from './acoes';
import { ObjetosDaAcao } from './objetos';
import type { PecaOficina } from '../tipos';

const V = ELENCO.c2;
const ROSTO: Record<string, Expressao> = {
  escrever: { boca: 'neutra', olharY: -1, sobrancelha: -0.3 },
  jogarMoeda: { boca: 'o', olharY: 1, olharX: 0.5, sobrancelha: 0.6 },
  virarCabeca: { boca: 'o', sobrancelha: 0.8 },
};

const Demo = (nome: string): React.FC<{ quadro: number }> => ({ quadro }) => (
  <group position={[1.05, 0, 0.15]} rotation={[0, -0.15, 0]}>
    <Boneco v={V} j={juntasNoQuadro(nome, quadro)} e={ROSTO[nome]} />
    <ObjetosDaAcao nome={nome} quadro={quadro} pele={V.pele} />
  </group>
);

export const DEMOS: PecaOficina[] = Object.keys(ROSTO).map((nome) => ({
  tipo: 'efeito' as const, nome: `${nome}+objetos`, Componente: Demo(nome),
}));
